import{n as e}from"./rolldown-runtime-hePW80VL.js";var t=e({diyaloglar:()=>r,dosyalar:()=>n}),n=JSON.parse(`[{"ders":"otelcilik-seyahat","sinif":9,"unite":1,"baslik":"Kişisel Hijyen Kuralları","onay":true,"kazanimlar":["Kişisel bakım yapar.","İşe uygun iş kıyafetlerini giyer.","Vücut mekaniklerine göre hareket eder."],"soz":"Konuk oteli gezmeden önce seni görür: otelin ilk temiz yüzeyi sensin.","dersler":[{"baslik":"Temiz Görünmek Yeter mi?","ilk":"os-1-001"},{"baslik":"Gözle Görülmeyen Canlılar","ilk":"os-1-006"},{"baslik":"Konuk Önce Seni Görür","ilk":"os-1-013"},{"baslik":"Sen Otelin Yüzüsün","ilk":"os-1-016"},{"baslik":"Duşta Ne, Neden Kullanılır?","ilk":"os-1-019"},{"baslik":"Deodorant Duşun Yerini Tutar mı?","ilk":"os-1-031"},{"baslik":"Doğaya da Temiz Davran","ilk":"os-1-021"},{"baslik":"Yirmi Saniyelik Standart","ilk":"os-1-034"},{"baslik":"Tırnağın Altında Ne Var?","ilk":"os-1-038"},{"baslik":"Bütün Gün Ayakta","ilk":"os-1-042"},{"baslik":"Konuşarak Yapılan Meslek","ilk":"os-1-044"},{"baslik":"Fırça, Macun, İp","ilk":"os-1-049"},{"baslik":"Sert Fırça Daha mı İyi Temizler?","ilk":"os-1-046"},{"baslik":"Gargara Fırçanın Yerini Tutar mı?","ilk":"os-1-057"},{"baslik":"Saçın Derdi Ne?","ilk":"os-1-059"},{"baslik":"Krem, Makine, Tarak","ilk":"os-1-065"},{"baslik":"Etiketi Oku, Suyu Koru","ilk":"os-1-068"},{"baslik":"Cildin Bir Kalkan mı?","ilk":"os-1-070"},{"baslik":"Beş Cilt, Beş Karakter","ilk":"os-1-072"},{"baslik":"Cilt Ne Zaman Alarm Verir?","ilk":"os-1-078"},{"baslik":"Beş Adımda Cilt Bakımı","ilk":"os-1-083"},{"baslik":"Jilet Kimseyle Paylaşılmaz","ilk":"os-1-088"},{"baslik":"Vardiyanın Yakıtı","ilk":"os-1-094"},{"baslik":"Kötü Beslenmenin Faturası","ilk":"os-1-100"},{"baslik":"Sağlıklı Yaşamın Beş Ögesi","ilk":"os-1-104"},{"baslik":"Yastık, Bardak, Tabak","ilk":"os-1-107"},{"baslik":"Sektörün Dili: Mutfaktan Gelen Kelimeler","ilk":"os-1-137"},{"baslik":"Sektörün Dili: Kurallar ve Belgeler","ilk":"os-1-140"},{"baslik":"Konuşmadan Önce Ne Söylersin?","ilk":"os-1-113"},{"baslik":"İş Kıyafetinin Dört Standardı","ilk":"os-1-116"},{"baslik":"Aynadaki Son Bakış","ilk":"os-1-120"},{"baslik":"Kirli Sepetinden Askıya","ilk":"os-1-124"},{"baslik":"Sektörün Dili: Dress Code ve Yaka Kartı","ilk":"os-1-130"},{"baslik":"Sektörün Dili: Koruyan Kıyafet","ilk":"os-1-136"},{"baslik":"Bedenin de Bir İş Aracıdır","ilk":"os-1-145"},{"baslik":"Yanlış Hareket Bedene Ne Yapar?","ilk":"os-1-149"},{"baslik":"Önce Denge, Sonra Hareket","ilk":"os-1-153"},{"baslik":"Bankoda Dik Durmak","ilk":"os-1-155"},{"baslik":"Valizi Belinle Değil Bacağınla Kaldır","ilk":"os-1-160"},{"baslik":"Vardiya Bitti, Sırtını Unutma","ilk":"os-1-166"}],"kavramlar":[{"id":"os-1-001","konu":"1.1","terim":"Hijyen","ingilizce":"Hygiene","tanim":"Sağlığa zarar verecek ortamlardan korunmak için yapılan uygulamalar ve alınan temizlik önlemlerinin tümü.","ornek":"Sabah 06.30, kahvaltı salonu açılmadan önce: masalar silinmiş, büfe örtülü, servis ekibinin elleri yıkanmış. Konuk bunların hiçbirini görmez, yalnızca güvenle oturur.","sektor":"Konuk temizliği fark etmez, eksikliğini fark eder. Otelde hijyen bir ek hizmet değil, hizmet kalitesinin kendisidir; hijyen standartlarına uyan çalışan işletmenin güvenilirliğini artırır.","iliskili":["os-1-003","os-1-002","os-1-006"],"kontrol":null},{"id":"os-1-003","konu":"1.1","terim":"Temizlik","ingilizce":"Cleanliness","tanim":"Kirin, tozun ve lekenin uzaklaştırılması; hijyenin bir parçasıdır. Hijyen ise yalnızca dış görünüşle ilgili değildir, sağlığı korumayı da kapsar.","ornek":"Saat 11.00, kat koridoru: oda görevlisi aynadaki parmak izini siler, halıdaki tozu süpürgeyle alır. Görünen kir gider; bu temizliktir.","sektor":"Temiz görünen her şey hijyenik değildir: pırıl pırıl görünen bir bardağa yıkanmamış elle dokunulmuş olabilir. Otelde hedef yalnız parlak görünmek değil, konuğun sağlığını korumaktır.","iliskili":["os-1-001","os-1-019"],"kontrol":null,"cizim":"hijyen-damla"},{"id":"os-1-002","konu":"1.1","terim":"Kişisel hijyen","ingilizce":"Personal hygiene","tanim":"Vücudu temiz tutmak, sağlığı korumak ve hastalıklara karşı önlem almak için düzenli yapılan bakım ve temizlik uygulamaları.","ornek":"Vardiyadan önce duş almak, tuvaletten sonra elleri su ve sabunla yıkamak, sabah ve gece dişleri fırçalamak.","sektor":"Otel çalışanı yalnız kendi sağlığını değil, hizmet ettiği konuğun ve yanında çalıştığı arkadaşının sağlığını da korur. Bu yüzden kişisel hijyen sektörde özel bir tercih değil, mesleki bir standarttır.","iliskili":["os-1-001","os-1-005","os-1-019","os-1-034","os-1-044"],"kontrol":null,"gorsel":"h1a-sabunla-el-yikama"},{"id":"os-1-005","konu":"1.1","terim":"Kişisel bakım","ingilizce":"Personal grooming","tanim":"Kişinin vücut, saç, cilt, ağız ve diş, el ve ayak bakımına ve dış görünüşüne düzenli özen göstermesi.","ornek":"Saat 07.40, personel soyunma odası: duşunu almış, saçını toplamış, tırnakları kısa bir resepsiyon görevlisi vardiyaya hazır.","sektor":"Birçok otelde bu standartların yazılı hâline “grooming standartları” denir ve işe yeni başlayanlara anlatılır; çünkü bakımlı personel, bakımlı otel demektir.","iliskili":["os-1-002","os-1-014","os-1-011","os-1-131"],"kontrol":null},{"id":"os-1-018","konu":"1.1.1","terim":"Yaşam kalitesi","ingilizce":"Quality of life","tanim":"Kişinin sağlıklı, rahat ve mutlu yaşama düzeyi; hijyen ve sağlıklı yaşam onu artırır.","ornek":"Temizliğine, uykusuna ve beslenmesine özen gösteren bir stajyer, sabah 07.00 vardiyasına dinç ve keyifli başlar.","sektor":"Kendini iyi hisseden çalışan konuğa daha sabırlı ve daha güler yüzlü davranır. Hijyen bu yüzden yalnız “hasta olmamak” değil, işini severek yapabilmektir.","iliskili":["os-1-002","os-1-104"],"kontrol":null},{"id":"os-1-006","konu":"1.1.1","terim":"Mikroorganizma","ingilizce":"Microorganism","tanim":"Gözle görülemeyecek kadar küçük canlılar (bakteri, virüs, mantar); hijyene uyulmazsa vücutta birikip hastalık yapabilir.","ornek":"Lobideki asansör düğmesi tertemiz görünür; oysa gün boyu ona dokunan ellerden gözle görülmeyen canlılar birikmiştir.","sektor":"Otel kalabalık bir yerdir: aynı kapı koluna, aynı masaya, aynı düğmeye çok sayıda insan dokunur. Göremediğin şeye karşı korunmanın yolu düzenli temizlik ve el yıkama alışkanlığıdır.","iliskili":["os-1-007","os-1-008","os-1-004","os-1-034"],"kontrol":null,"gorsel":"h1a-mikrop-kolonisi"},{"id":"os-1-007","konu":"1.1.1","terim":"Bakteri","ingilizce":"Bacterium (pl. bacteria)","tanim":"Tek hücreli mikroorganizma; ağızda, ciltte ve yüzeylerde çoğalarak koku ve hastalığa yol açabilir.","ornek":"Yaz günü vardiya boyunca terleyen bir çalışanın koltuk altında bakteriler çoğalır; kötü kokuyu onlar oluşturur.","sektor":"Bakteriler sıcak ve nemli yerlerde kolay çoğalır. Islak bırakılan havlu, kapalı kutuda nemli kalan diş fırçası ve kurulanmayan ayak onlar için uygun ortamdır.","iliskili":["os-1-006","os-1-045","os-1-051","os-1-031"],"kontrol":null,"gorsel":"h1a-ecoli-bakteri"},{"id":"os-1-008","konu":"1.1.1","terim":"Enfeksiyon hastalığı","ingilizce":"Infectious disease","tanim":"Mikroorganizmaların vücuda girip çoğalmasıyla oluşan, başkalarına bulaşabilen hastalık.","ornek":"Tuvaletten sonra ellerini yıkamadan servise çıkan bir çalışan, elindeki mikroorganizmaları ekmek sepetiyle konuğun masasına taşıyabilir.","sektor":"Her enfeksiyon kişiden kişiye geçmez; geçenlere bulaşıcı hastalık denir. Bulaşıcı olanı otelde ekip arkadaşlarına ve konuklara yayılabilir; bu yüzden el hijyeni, sektörde ilk öğrenilen standartlardandır.","iliskili":["os-1-006","os-1-009","os-1-034","os-1-139"],"kontrol":null,"gorsel":"h1a-ates-olcer"},{"id":"os-1-009","konu":"1.1","terim":"Bulaşıcı hastalık","ingilizce":"Contagious disease","tanim":"Kişiden kişiye geçebilen hastalık; tırnak makası, tarak, havlu gibi eşyaların ortak kullanımı bulaşmaya yol açar.","ornek":"Personel lojmanında aynı odayı paylaşan iki stajyerin her birinin kendi havlusu, kendi tarağı ve kendi tırnak makası vardır.","sektor":"Kişisel eşya ödünç verilmez, ödünç alınmaz; bu kabalık değil, sağlık standardıdır. Kalabalık bir ekipte tek bir ortak eşya, hastalığı birçok kişiye taşıyabilir.","iliskili":["os-1-008","os-1-020","os-1-032","os-1-039"],"kontrol":null},{"id":"os-1-004","konu":"1.1.4","terim":"Ortak kullanılan yüzey","ingilizce":"Shared surface","tanim":"Kapı kolu, tırabzan, para gibi pek çok kişinin dokunduğu yüzey; eller bunlara dokunduktan sonra yıkanır.","ornek":"Resepsiyondaki kalem, asansör düğmesi, merdiven tırabzanı, konuğun uzattığı banknot: hepsine gün boyu çok sayıda el değer.","sektor":"Otelde ortak yüzeyler evdekinden çok daha fazladır; hepsine konuk da personel de dokunur. Bu yüzeylerden sonra el yıkamak, mikroorganizmanın bir konuktan ötekine taşınmasını önler.","iliskili":["os-1-006","os-1-034","os-1-035"],"kontrol":null,"gorsel":"h1a-kapi-kollari"},{"id":"os-1-013","konu":"1.1.2","terim":"Konuk","ingilizce":"Guest","tanim":"Konaklama işletmesinden hizmet alan kişi; misafir.","ornek":"Otelde bir hafta kalan aile de, yalnız akşam yemeği için otelin restoranına gelen çift de konuktur.","sektor":"Otelcilikte “müşteri” yerine “konuk” denir: kişi, evimize gelmiş bir misafir gibi ağırlanır. İngilizcesi olan “guest” sözünü stajda her gün duyarsın.","iliskili":["os-1-011","os-1-012"],"kontrol":null,"cizim":"zil-hizmet"},{"id":"os-1-011","konu":"1.1.2","terim":"İlk izlenim","ingilizce":"First impression","tanim":"Konuğun bir çalışanı ilk gördüğü anda oluşan düşünce; temiz ve bakımlı çalışan güven verir.","ornek":"Saat 14.00, konuk döner kapıdan giriyor. Daha tek kelime konuşulmadan resepsiyondaki görevlinin saçına, yakasına ve ellerine bakmış, otel hakkında ilk kararını vermiştir.","sektor":"Personel konukla yüz yüzedir. Konuk mutfağı ya da çamaşırhaneyi göremez; oranın temizliğini karşısındaki çalışanın görünüşünden tahmin eder.","iliskili":["os-1-013","os-1-014","os-1-012","os-1-005"],"kontrol":null,"cizim":"uniforma"},{"id":"os-1-012","konu":"1.1.2","terim":"Konuk memnuniyeti","ingilizce":"Guest satisfaction","tanim":"Konuğun aldığı hizmetten hoşnut kalması; çalışanın temizliği ve görünümü bunu doğrudan etkiler.","ornek":"Kahvaltıda çayını temiz üniformalı, güler yüzlü bir garsondan alan konuk, masadan memnun kalkar ve ertesi sabah aynı salona güvenle gelir.","sektor":"Memnun konuk yeniden gelir ve oteli çevresine önerir. Bakımsız tek bir çalışan ise iyi hazırlanmış bir hizmeti gölgeleyebilir ve işletmenin tercih edilmesini azaltabilir.","iliskili":["os-1-013","os-1-011","os-1-015"],"kontrol":null,"cizim":"zil-hizmet"},{"id":"os-1-014","konu":"1.1.2","terim":"Profesyonel imaj","ingilizce":"Professional image","tanim":"Çalışanın görünüşü ve davranışıyla yansıttığı, güven veren ve mesleğe yakışan izlenim.","ornek":"Saat 09.00, resepsiyon: ütülü üniforması, toplanmış saçı ve temiz elleriyle konuğu ayakta, gülümseyerek karşılayan görevli.","sektor":"Konuk, işini bilen biriyle karşı karşıya olduğunu önce gözüyle anlar. Bakımlı çalışana daha kolay güvenir ve sorusunu ona sorar.","iliskili":["os-1-011","os-1-005","os-1-016","os-1-017"],"kontrol":null,"cizim":"uniforma"},{"id":"os-1-016","konu":"1.1.2","terim":"Kurumsal imaj","ingilizce":"Corporate image","tanim":"İşletmenin dışarıya yansıyan görüntüsü; çalışanların kıyafeti ve görünümü bu imajı oluşturur.","ornek":"Kapıdaki görevliden kahvaltıdaki garsona kadar herkesin üniforması temiz ve ütülüdür; konuk otelin her köşesinde aynı özeni görür.","sektor":"Konuk için otel, karşısına çıkan çalışandır. Kirli bir üniforma, konukta mutfağın ve odaların temizliği konusunda da şüphe uyandırır.","iliskili":["os-1-015","os-1-014","os-1-113","os-1-115"],"kontrol":null},{"id":"os-1-015","konu":"1.1.2","terim":"Kurumsal itibar","ingilizce":"Corporate reputation","tanim":"İşletmenin konuklar ve toplum gözündeki saygınlığı; bakımlı çalışanlar onu güçlendirir.","ornek":"Tatilden dönen bir aile komşularına “Çalışanlar çok bakımlı ve özenliydi, gönül rahatlığıyla kaldık” der; otelin adı böyle yayılır.","sektor":"İtibar, her çalışanın her günkü özeniyle zamanla kazanılır; tek bir kötü deneyimle zarar görebilir. Çalışanın hijyeni bu yüzden yalnız kendisini değil, bütün işletmeyi ilgilendirir.","iliskili":["os-1-016","os-1-012","os-1-014"],"kontrol":null},{"id":"os-1-017","konu":"1.1","terim":"Mesleki yeterlilik","ingilizce":"Professional competence","tanim":"Bir mesleğin gerektirdiği bilgi, beceri ve tutumlara sahip olma; hijyen de bunun bir parçasıdır.","ornek":"Rezervasyon programını çok iyi kullanan ama bankoya kirli tırnaklarla çıkan bir stajyerin mesleki yeterliliği eksik kalır.","sektor":"Otelcilikte bilgi ve beceri kadar tutum da değerlendirilir. Hizmeti konuğun bir adım yanında sunduğun için kişisel hijyen bu mesleğin eki değil, kendisidir.","iliskili":["os-1-014","os-1-002","os-1-005"],"kontrol":null},{"id":"os-1-019","konu":"1.1.3","terim":"Vücut temizliği","ingilizce":"Body cleansing","tanim":"Cildin kir, ter, yağ ve mikroorganizmalardan arındırılması; ürünler cilt tipine uygun seçilir.","ornek":"Oda görevlisi sabah 08.00 vardiyasına duş almış, temiz çamaşır ve temiz üniformayla başlar.","sektor":"Otelde iş bedenle yapılır ve terletir; üstelik konukla çoğu zaman bir adım mesafede çalışılır. Bu yüzden vücut temizliği bizim mesleğimizde günlük bir iş standardıdır.","iliskili":["os-1-025","os-1-031","os-1-030","os-1-002","os-1-071"],"kontrol":null},{"id":"os-1-025","konu":"1.1.3","terim":"Sabun / duş jeli","ingilizce":"Soap / shower gel","tanim":"Cilt yüzeyinde biriken kir, yağ ve mikroorganizmaları temizler.","ornek":"Sabah 07.00, vardiya öncesi duş: sabun ya da duş jeli köpürtülür; ter ve kir suyla birlikte akıp gider.","sektor":"Otel odasının banyosunda konuğa da sabun ve duş jeli bırakılır; eksileni oda görevlisi tamamlar. Cildi kuru olan kişi nemlendirici özellikli ürün seçerse cildini korur.","iliskili":["os-1-019","os-1-026","os-1-027","os-1-034"],"kontrol":null,"gorsel":"os-sabun"},{"id":"os-1-026","konu":"1.1.3","terim":"Şampuan","ingilizce":"Shampoo","tanim":"Saçı ve saç derisini temizler; saç tipine uygun seçilir.","ornek":"Saçı çabuk yağlanan bir stajyer, market rafından rastgele bir şişe almak yerine etiketi okuyup yağlı saçlara uygun olanı seçer.","sektor":"Temiz ve bakımlı saç, profesyonel görünümün parçasıdır. Şampuan, otel banyosunda konuk için bırakılan ürünlerden de biridir.","iliskili":["os-1-025","os-1-059","os-1-060","os-1-064"],"kontrol":null,"cizim":"hijyen-damla"},{"id":"os-1-027","konu":"1.1.3","terim":"Lif, sünger, kese","ingilizce":"Loofah, sponge, exfoliating mitt","tanim":"Ölü derinin uzaklaştırılmasına yardımcı olur; doğru ve ölçülü kullanılmalıdır.","ornek":"Banyoda kese cilde bastırmadan, yumuşak hareketlerle kullanılır; iş bitince lif yıkanır ve kuruması için asılır.","sektor":"Lif ve kese kişiseldir; ortak kullanılırsa mikroorganizmayı bir kişiden ötekine taşır. Çok sık ve sert kullanılırsa cildi tahriş eder.","iliskili":["os-1-028","os-1-029","os-1-025"],"kontrol":null,"gorsel":"os-lif-sunger"},{"id":"os-1-028","konu":"1.1.3","terim":"Ölü deri","ingilizce":"Dead skin","tanim":"Cildin en üst katmanında biriken ölü hücreler; lif, kese ve peelingle uzaklaştırılır.","ornek":"Banyoda kese yapıldığında ciltten dökülen ince, gri parçacıklar ölü deridir.","sektor":"Ölü deri birikince cilt donuk ve pürüzlü görünür; düzenli banyo ve kese ya da peeling bunu önler. Konukla yüz yüze çalışan personel için bakımlı cilt, kişisel hijyen standardının görünen parçasıdır.","iliskili":["os-1-027","os-1-084","os-1-070"],"kontrol":null},{"id":"os-1-029","konu":"1.1.3","terim":"Tahriş","ingilizce":"Irritation","tanim":"Ciltte kızarıklık, kaşıntı ya da yanma; sert ya da uygun olmayan ürün kullanımıyla oluşur.","ornek":"Sert bir süngerle kolunu bastırarak ovan stajyerin cildi kızarır ve yanmaya başlar.","sektor":"Cildi tahriş olan çalışan gün boyu rahatsız olur ve bu yüzüne yansır. Tahrişe yol açan ürün bırakılır; şikâyet geçmiyorsa hekime başvurulur.","iliskili":["os-1-027","os-1-024","os-1-076"],"kontrol":null,"gorsel":"h1a-temas-dermatiti"},{"id":"os-1-031","konu":"1.1.3","terim":"Terleme","ingilizce":"Sweating","tanim":"Vücudun ter salgılaması; temizlik yapılmazsa kötü koku oluşur.","ornek":"Ağustos öğleni, havuz başındaki restoran: tepsi taşıyan garsonun gömleği kısa sürede terden ıslanır.","sektor":"Terlemek doğaldır; sorun terin kendisi değil, temizlenmeyen ter ve değiştirilmeyen giysidir. İnsan kendi kokusuna alışır ve onu fark etmez; konuk ise ilk saniyede fark eder.","iliskili":["os-1-030","os-1-019","os-1-007"],"kontrol":null,"cizim":"hijyen-damla"},{"id":"os-1-030","konu":"1.1.3","terim":"Deodorant","ingilizce":"Deodorant","tanim":"Terleme sonucu oluşan kötü kokuyu önlemeye yardımcı olur; temiz cilde uygulanır.","ornek":"Sabah duşundan sonra kurulanmış koltuk altına sürülen deodorant gün boyu iş görür; yıkanmamış cilde sıkılan deodorant ise ter kokusuyla karışır.","sektor":"Koku temizliğin yerini tutmaz, yalnız onu tamamlar. Konuğa yakın çalışan personel ağır koku kullanmaz: konuk seni kokundan değil, hizmetinden hatırlamalıdır.","iliskili":["os-1-031","os-1-019","os-1-020"],"kontrol":null,"cizim":"hijyen-damla"},{"id":"os-1-032","konu":"1.1.3","terim":"Havlu","ingilizce":"Towel","tanim":"Vücudu kurulamak için kullanılan bez; temiz olmalı ve yalnızca kişiye özel kullanılmalıdır.","ornek":"Duştan sonra kendi havlunla kurulanır, havluyu nemli hâlde bırakmayıp kuruması için asarsın.","sektor":"Ortak kullanılan havlu mikroorganizmaları bir kişiden ötekine taşır. Otelde de aynı standart geçerlidir: her konuğa temiz havlu verilir.","iliskili":["os-1-009","os-1-036","os-1-020"],"kontrol":null,"gorsel":"t12s-rulo-havlu-raf"},{"id":"os-1-020","konu":"1.1.3","terim":"Kişisel bakım ürünü","ingilizce":"Personal care product","tanim":"Sabun, şampuan, deodorant, diş fırçası gibi bakım için kullanılan ürünler; başkalarıyla paylaşılmaz.","ornek":"Staj çantasındaki küçük bakım seti: diş fırçası, diş macunu, tarak, deodorant. Hepsi yalnız sana aittir.","sektor":"Otel de konuğuna aynı özeni gösterir: odaya konan bakım ürünleri her konuk için yenilenir, başkasının kullandığı ürün bırakılmaz.","iliskili":["os-1-009","os-1-033","os-1-024","os-1-021"],"kontrol":null,"cizim":"hijyen-damla"},{"id":"os-1-033","konu":"1.1.3","terim":"Son kullanma tarihi","ingilizce":"Expiry date","tanim":"Ürünün güvenle kullanılabileceği son gün; kişisel bakım ürünlerinde kontrol edilmelidir.","ornek":"Dolabın arkasında unutulmuş bir krem: sürmeden önce ambalajdaki tarihe bakılır; geçmişse kullanılmaz.","sektor":"Tarihe bakmak bir meslek alışkanlığıdır: otelde konuğa sunulan ürünlerde de aynı kontrol yapılır. Tarihi geçmiş ürün etkisini yitirebilir, cilde zarar verebilir.","iliskili":["os-1-020","os-1-024"],"kontrol":null,"cizim":"takvim"},{"id":"os-1-024","konu":"1.1.3","terim":"Zararlı kimyasal","ingilizce":"Harmful chemical","tanim":"Sağlığa ve cilde zarar verebilen madde; bakım ürünlerinde bulunmamasına dikkat edilir.","ornek":"Yeni aldığı ürünü sürdükten sonra cildi kızaran bir çalışan ürünü kullanmayı bırakır ve bundan sonra etiketteki “içindekiler” bölümünü okur.","sektor":"Oteller de konuğa sunacakları bakım ürünlerini seçerken sağlığa ve çevreye etkisine bakar. Etiket okumak, hem kendin hem konuğun için edineceğin iyi bir alışkanlıktır.","iliskili":["os-1-029","os-1-020","os-1-021","os-1-033"],"kontrol":null,"gorsel":"h1a-cevre-tehlike-isareti"},{"id":"os-1-021","konu":"1.1.3","terim":"Çevre dostu ürün","ingilizce":"Eco-friendly product","tanim":"Doğaya daha az zarar veren, sürdürülebilir ürün. Örnek: bambu diş fırçası, sülfatsız şampuan.","ornek":"Banyo rafında plastik şişedeki sıvı sabun yerine kâğıda sarılı kalıp sabun, plastik saplı fırça yerine bambu saplı fırça durur.","sektor":"Doğa dostu ürünler kullanan bir işletme, çevre bilinci yüksek konuklar tarafından daha çok tercih edilebilir. Çevreye duyarlı davranmak, turizm çalışanından beklenen bir tutumdur.","iliskili":["os-1-022","os-1-023","os-1-050","os-1-068"],"kontrol":null,"gorsel":"h1a-tekrar-kullanilir-sise"},{"id":"os-1-022","konu":"1.1.3","terim":"Geri dönüştürülebilir ambalaj","ingilizce":"Recyclable packaging","tanim":"Kullanıldıktan sonra yeniden işlenip değerlendirilebilen ambalaj.","ornek":"Biten şampuanın şişesi ve sabunun karton kutusu çöpe değil, geri dönüşüm kutusuna atılır.","sektor":"Otelde her gün çok sayıda ambalaj atığı çıkar. Ambalajı doğru kutuya atmak küçük bir harekettir ama her çalışan yaptığında büyük fark yaratır.","iliskili":["os-1-021","os-1-023"],"kontrol":null,"gorsel":"h1a-geri-donusum-ambalaj"},{"id":"os-1-023","konu":"1.1.3","terim":"Tek kullanımlık ürün","ingilizce":"Single-use product","tanim":"Bir kez kullanılıp atılan ürün; plastik atık ve çevre kirliliği yaratır.","ornek":"Bir kez kullanılıp çöpe giden plastik bardak, plastik çatal ve ıslak mendil.","sektor":"Tek kullanımlık ürün yerinde kullanıldığında hijyen sağlar; gereksiz kullanıldığında yalnızca çöp üretir. Ölçü: gerektiği yerde, gerektiği kadar.","iliskili":["os-1-021","os-1-022","os-1-036"],"kontrol":null,"gorsel":"h1a-otel-terligi"},{"id":"os-1-180","konu":"1.1.3","terim":"Biyolojik olarak parçalanabilir ürün","ingilizce":"Biodegradable product","tanim":"Kullanıldıktan sonra doğada kendiliğinden ayrışıp çözünen, bu yüzden çevreyi az kirleten üründür.","ornek":"Banyo rafında “biyolojik olarak parçalanabilir” yazan bir şampuan şişesi; suyla giderken su kirliliğini azaltır.","sektor":"Ders kitabı doğada çözünebilen şampuanların su kirliliğini azaltmaya yardımcı olduğunu söyler. Çevre bilinci yüksek konuklar bu etiketi arayabilir.","iliskili":["os-1-021","os-1-026","os-1-068"],"kontrol":null,"cizim":"geri-donusum"},{"id":"os-1-050","konu":"1.1.5","terim":"Bambu diş fırçası","ingilizce":"Bamboo toothbrush","tanim":"Sapı bambudan yapılan, plastik atığı azaltan çevre dostu diş fırçası.","ornek":"Marketin kişisel bakım rafında plastik saplı fırçaların yanında duran, ahşap görünümlü saplı fırça.","sektor":"Bambu saplı fırça da öteki fırçalar gibi kullanılır, saklanır ve değiştirilir; farkı, atıldığında doğada daha az plastik bırakmasıdır.","iliskili":["os-1-049","os-1-021","os-1-023"],"kontrol":null,"gorsel":"t14a-bambu-disfircasi"},{"id":"os-1-034","konu":"1.1.4","terim":"El hijyeni","ingilizce":"Hand hygiene","tanim":"Ellerin su ve sabunla, parmak araları ve tırnaklarla birlikte en az 20 saniye yıkanıp durulanması ve kurulanması.","ornek":"Bir garson aynı elle önce parayı, sonra kapı kolunu, sonra konuğun ekmek sepetini tutar. Arada el yıkanmazsa mikroorganizma da aynı yolu izler.","sektor":"El yıkamak, hastalıkların yayılmasını önlemenin en basit yollarından biridir. Otel gibi kalabalık yerlerde tek bir kişinin eli pek çok konuğa ulaşır; yemek servisinden önce, tuvaletten sonra ve paraya dokunduktan sonra eller mutlaka yıkanır. Ders kitabına göre eller şu durumlarda mutlaka yıkanır: yemekten önce ve sonra, yemek hazırlamadan önce ve çiğ gıdaya dokunduktan sonra, tuvaleti kullanmadan önce ve sonra, öksürük ya da hapşırık sonrası mendil kullandıktan sonra, ağız, burun, yüz ve göz temizliğinden önce ve sonra, deriyi kaşıdıktan sonra, gözle görülür kirlilikte, paraya, ortak kullanılan ve kirli yüzeylere dokunduktan sonra, eldiven giymeden önce ve çıkardıktan sonra, dışarıdan işe geldikten sonra, hasta ziyaretinden ve hayvanlarla temastan sonra. Bunların hiçbiri olmasa bile gün içinde temizliğin sürmesi için eller sık sık yıkanır.","iliskili":["os-1-004","os-1-006","os-1-035","os-1-036","os-1-037","os-1-140"],"kontrol":null,"gorsel":"t14a-el-yikama"},{"id":"os-1-036","konu":"1.1.4","terim":"Kâğıt havlu","ingilizce":"Paper towel","tanim":"Elleri kurulamak için kullanılan tek kullanımlık havlu.","ornek":"Personel lavabosu: eller yıkanır, kutudan bir kâğıt havlu çekilir, eller kurulanır ve havlu çöp kutusuna atılır.","sektor":"Herkesin kullandığı nemli bir bez havlu, yıkanmış eli yeniden kirletebilir; bu yüzden ortak lavabolarda kâğıt havlu kullanılır. Gereğinden fazlasını çekmemek de çevre bilincidir.","iliskili":["os-1-034","os-1-032","os-1-023"],"kontrol":null,"gorsel":"os-kagit-havlu"},{"id":"os-1-035","konu":"1.1.4","terim":"El dezenfektanı","ingilizce":"Hand sanitiser","tanim":"Su ve sabun olmadığında ellerdeki mikroorganizmaları azaltmak için kullanılan ürün.","ornek":"Resepsiyon bankosunda duran el dezenfektanı: görevli, bankodan ayrılamadığı yoğun bir anda avucuna sıkar ve elleri kuruyana kadar ovar.","sektor":"Su ve sabunun yerini tutmaz; lavaboya gidilemeyen anda ara çözümdür. Gözle görülür biçimde kirlenmiş el dezenfektanla değil, su ve sabunla yıkanarak temizlenir.","iliskili":["os-1-034","os-1-004","os-1-137"],"kontrol":null,"gorsel":"os-el-dezenfektani"},{"id":"os-1-037","konu":"1.1.4","terim":"Eldiven","ingilizce":"Gloves","tanim":"Elleri koruyan giysi; giymeden önce ve çıkardıktan sonra eller yıkanmalıdır.","ornek":"Oda görevlisi banyoyu temizlerken eldivenini takar; iş bitince eldiveni çıkarır ve ellerini yıkar.","sektor":"Eldiven el yıkamanın yerini tutmaz. Kirli işte kullanılan eldivenle temiz havluya, bardağa ya da kapı koluna dokunulmaz; yoksa kir eldivenle birlikte taşınır.","iliskili":["os-1-034","os-1-139","os-1-136"],"kontrol":null,"gorsel":"lastik-eldiven"},{"id":"os-1-038","konu":"1.1.4","terim":"Tırnak bakımı","ingilizce":"Nail care","tanim":"Tırnakların banyodan sonra haftada bir kesilmesi: el tırnakları yarım ay, ayak tırnakları düz biçimde.","ornek":"Garson tabağı masaya bırakırken konuğun gözü tam o anda ellerine gider: tırnaklar kısa ve temizse kimse bir şey düşünmez.","sektor":"Uzun tırnağın altında kir, yağ ve mikroorganizma birikir. Tırnak banyodan sonra, yumuşamışken daha kolay kesilir. Konuğa tabak, anahtar ya da kalem uzatan el her zaman göz önündedir.","iliskili":["os-1-039","os-1-040","os-1-041","os-1-034"],"kontrol":null},{"id":"os-1-039","konu":"1.1.4","terim":"Tırnak makası","ingilizce":"Nail clippers","tanim":"Uzayan tırnakları kesmeye yarayan alet; başkalarıyla ortak kullanılmaz.","ornek":"Lojmanda oda arkadaşı tırnak makasını istediğinde “Kusura bakma, bu kişisel” demek ayıp değil, doğru davranıştır.","sektor":"Tırnak kesiminde kullanılan araçları kimseyle paylaşmamak, bulaşıcı hastalıkların yayılmasını önlemenin etkili yollarındandır.","iliskili":["os-1-038","os-1-009","os-1-020"],"kontrol":null,"gorsel":"os-tirnak-makasi"},{"id":"os-1-040","konu":"1.1.4","terim":"Tırnak fırçası","ingilizce":"Nail brush","tanim":"Tırnakların altındaki kiri temizlemeye yarayan küçük fırça.","ornek":"Vardiya öncesi lavabo başında: sabunlu tırnak fırçası tırnak uçlarına ve altlarına sürülür, sonra eller durulanır.","sektor":"El yıkarken en zor temizlenen yer tırnak altıdır. Konuğa tabak uzatan ya da yiyecekle çalışan personel için temiz tırnak, işin vazgeçilmez standardıdır.","iliskili":["os-1-038","os-1-034"],"kontrol":null,"gorsel":"os-tirnak-fircasi"},{"id":"os-1-041","konu":"1.1.4","terim":"Tırnak batması","ingilizce":"Ingrown nail","tanim":"Tırnağın çok derin kesilmesiyle kenarının ete batması.","ornek":"Ayak tırnağını köşelerinden derin ve yuvarlak kesen bir komi, bir süre sonra ayakkabısını giyerken ağrı duymaya başlar.","sektor":"Bu yüzden ayak tırnakları düz kesilir, fazla dipten alınmaz. Bütün gün ayakta çalışan biri için tırnak batması her adımda ağrı demektir.","iliskili":["os-1-038","os-1-042"],"kontrol":null},{"id":"os-1-042","konu":"1.1.4","terim":"Ayak bakımı","ingilizce":"Foot care","tanim":"Ayakların her gün yıkanıp parmak aralarıyla iyi kurulanması; pamuklu ya da yünlü çorap her gün değiştirilir.","ornek":"Akşam eve dönünce ayaklar yıkanır, parmak araları tek tek kurulanır; ertesi gün için temiz bir çorap hazırlanır.","sektor":"Resepsiyonda, serviste, katta iş ayakta yapılır: ayağın sağlam değilse vardiyan da sağlam geçmez. Nemli kalan parmak arası mantar ve kötü koku demektir; bu yüzden en önemli adım kurulamaktır.","iliskili":["os-1-010","os-1-043","os-1-041"],"kontrol":null},{"id":"os-1-010","konu":"1.1.4","terim":"Mantar enfeksiyonu","ingilizce":"Fungal infection","tanim":"Mantarların yol açtığı hastalık; iyi kurulanmayan ayakların parmak aralarında sık görülür.","ornek":"Duştan sonra ayağını kurulamadan çorabını giyen bir komi, bir süre sonra parmak aralarında kaşıntı ve kızarıklıkla uğraşır.","sektor":"Bütün gün kapalı ayakkabıyla çalışan otel personelinin ayağı terler ve nemli kalır. Korunmanın yolu kurulamak, çorabı her gün değiştirmek ve çorabı kimseyle paylaşmamaktır; şikâyet geçmiyorsa hekime gidilir.","iliskili":["os-1-042","os-1-006","os-1-008"],"kontrol":null},{"id":"os-1-043","konu":"1.1.4","terim":"Ortopedik ayakkabı","ingilizce":"Orthopaedic shoe","tanim":"Ayak yapısına uygun, ayağı destekleyen yumuşak ayakkabı; çok yüksek topuk tercih edilmez.","ornek":"Açılış gününde yeni ve dar ayakkabıyla servise çıkan stajyer, öğleden sonra ayağı vurduğu için topallayarak yürür.","sektor":"Otelde vardiyanın büyük bölümü ayakta geçer. Ayağa uygun ayakkabı gün sonunda daha az yorgunluk demektir; çok yüksek topuk uzun vardiyada ayağı yorar.","iliskili":["os-1-042","os-1-135"],"kontrol":null,"gorsel":"h1a-diyabetik-ayakkabi"},{"id":"os-1-044","konu":"1.1.5","terim":"Ağız ve diş bakımı","ingilizce":"Oral care","tanim":"Dişlerin günde en az iki kez fırçalanması, diş ipi ve dil temizliğiyle ağız sağlığının korunması.","ornek":"Sabah vardiyadan önce ve gece yatmadan önce: dişler fırçalanır, diş ipi kullanılır, dil temizlenir.","sektor":"Turizmde ağız ve diş sağlığı kişisel bir konu olmaktan çıkar, mesleki bir gereklilik olur: işimiz konukla yakın mesafede, konuşarak yapılır.","iliskili":["os-1-049","os-1-056","os-1-045","os-1-058","os-1-002"],"kontrol":null,"gorsel":"h1a-dis-fircasi-macun"},{"id":"os-1-045","konu":"1.1.5","terim":"Ağız kokusu","ingilizce":"Bad breath","tanim":"Ağızda biriken bakterilerin yol açtığı kötü koku; konukla iletişimi olumsuz etkiler.","ornek":"Sabah 09.00, resepsiyonda giriş işlemi: görevli ile konuk arasında yalnız bir banko vardır ve konuşma yüz yüze geçer.","sektor":"Mesleğimiz konuşarak yapılır: karşılama, bilgi verme, sipariş alma. Sakız kokuyu yalnızca örter; çözüm düzenli ağız bakımıdır. Bakıma rağmen koku geçmiyorsa diş hekimine gidilir.","iliskili":["os-1-044","os-1-007","os-1-057","os-1-058"],"kontrol":null,"cizim":"dis-bakimi"},{"id":"os-1-051","konu":"1.1.5","terim":"Plak","ingilizce":"Dental plaque","tanim":"Diş yüzeyinde biriken, bakteri içeren yapışkan tabaka; fırça ve diş ipiyle temizlenir.","ornek":"Akşam dişini fırçalamadan uyuyan biri, sabah dilini dişlerinde gezdirdiğinde kaygan bir tabaka hisseder.","sektor":"Plak temizlenmezse çürüğe ve diş eti hastalığına zemin hazırlar. Fırça diş yüzeyindeki plağı, diş ipi diş aralarındaki plağı alır; ikisi birbirini tamamlar.","iliskili":["os-1-049","os-1-056","os-1-047","os-1-055"],"kontrol":null,"gorsel":"h1a-plak-tableti"},{"id":"os-1-055","konu":"1.1.5","terim":"Diş çürüğü","ingilizce":"Tooth decay","tanim":"Dişin bakteriler nedeniyle bozulması; günde en az iki kez fırçalama büyük ölçüde engeller.","ornek":"Çürük dişini “nasılsa ağrımıyor” diye erteleyen bir çalışan, sonunda hem ağrıyla hem ağız kokusuyla uğraşır.","sektor":"Diş ağrısıyla gülümsemek zordur; oysa gülümseme bu mesleğin en çok kullanılan aracıdır. Çürükten şüphelenince beklemeden diş hekimine gidilir.","iliskili":["os-1-051","os-1-053","os-1-054","os-1-044"],"kontrol":null},{"id":"os-1-049","konu":"1.1.5","terim":"Diş fırçası","ingilizce":"Toothbrush","tanim":"Diş yüzeyindeki plakları uzaklaştırır; yumuşak ya da orta sert olmalı, 2–3 ayda bir değiştirilmelidir.","ornek":"Kılları iki yana açılmış, yıpranmış bir fırça artık iyi temizlemez; yenisiyle değiştirilir.","sektor":"Diş fırçası kimseyle paylaşılmaz. Temiz ve kuru bir yerde saklanır; ıslak hâlde kapalı bir kutuda bırakılırsa üzerinde bakteri çoğalır.","iliskili":["os-1-051","os-1-052","os-1-048","os-1-050","os-1-044"],"kontrol":null,"gorsel":"dis-fircalari"},{"id":"os-1-052","konu":"1.1.5","terim":"Diş macunu","ingilizce":"Toothpaste","tanim":"Dişleri fırçalarken kullanılan temizleyici; florürlü olanlar çürüğe karşı korur.","ornek":"Market rafında macun seçerken kutunun üzerinde “florürlü” yazıp yazmadığına bakılır.","sektor":"Temizliği macun tek başına yapmaz; fırçanın hareketi yapar, macun ona yardım eder. Fırçaya çok macun sıkmak dişi daha temiz yapmaz.","iliskili":["os-1-049","os-1-053","os-1-055"],"kontrol":null,"gorsel":"os-dis-macunu"},{"id":"os-1-053","konu":"1.1.5","terim":"Florür","ingilizce":"Fluoride","tanim":"Diş minesini güçlendirerek çürük oluşumunu önlemeye yardımcı olan madde.","ornek":"Diş macunu kutusunun “içindekiler” bölümünde “florür” ya da İngilizcesiyle “fluoride” yazar.","sektor":"Florürlü diş macunuyla düzenli fırçalama çürüğü önlemeye yardımcı olur. Konukla yakından konuşan personel için ağız sağlığı da hizmetin parçasıdır; temiz ve bakımlı bir ağız, güven veren bir ilk izlenimdir.","iliskili":["os-1-052","os-1-054","os-1-055"],"kontrol":null,"gorsel":"h1a-florurlu-macun"},{"id":"os-1-054","konu":"1.1.5","terim":"Diş minesi","ingilizce":"Tooth enamel","tanim":"Dişin en dıştaki sert, koruyucu tabakası.","ornek":"Gülümsediğinde görünen, dişin parlak dış yüzeyi minedir.","sektor":"Mine zarar görürse kendini yenileyemez. Bu yüzden şişe kapağını dişle açmak, sert kabukları dişle kırmak gibi alışkanlıklardan uzak durulur.","iliskili":["os-1-053","os-1-055"],"kontrol":null},{"id":"os-1-056","konu":"1.1.5","terim":"Diş ipi","ingilizce":"Dental floss","tanim":"Diş aralarına sıkışan yiyecek artıklarını temizler; kullanılmazsa plak artar.","ornek":"Gece yatmadan önce, fırçalamayla birlikte diş araları diş ipiyle tek tek temizlenir.","sektor":"Fırça diş aralarına ulaşamaz; orada kalan artık hem plak hem ağız kokusu demektir. Diş ipi diş etine bastırmadan, nazikçe kullanılır.","iliskili":["os-1-051","os-1-049","os-1-047","os-1-044"],"kontrol":null,"gorsel":"os-dis-ipi"},{"id":"os-1-046","konu":"1.1.5","terim":"Diş eti","ingilizce":"Gums","tanim":"Dişleri çevreleyen pembe doku; yumuşak fırçayla korunur.","ornek":"Aynada gülümsediğinde dişlerinin dibinde gördüğün pembe bölüm diş etidir; fırça oraya da yumuşak hareketlerle değdirilir.","sektor":"Bastırarak ve sert fırçalamak dişi daha temiz yapmaz; diş etini zedeler. Sağlıklı bir gülümseme yalnız dişle değil, diş etiyle birlikte korunur.","iliskili":["os-1-047","os-1-048","os-1-049"],"kontrol":null,"gorsel":"h1a-dis-eti"},{"id":"os-1-047","konu":"1.1.5","terim":"Diş eti hastalığı","ingilizce":"Gum disease","tanim":"Plak birikmesi sonucu diş etinde iltihap, kanama ve çekilme.","ornek":"Dişini fırçalarken lavaboda sık sık kan gören biri bunu geçiştirmez; diş hekimine görünür.","sektor":"Diş eti hastalığı ağız kokusuna da yol açabilir. Düzenli fırçalama ve diş ipi, plağı azaltarak diş etini korur.","iliskili":["os-1-046","os-1-051","os-1-048","os-1-056"],"kontrol":null,"gorsel":"h1a-dis-eti-iltihabi"},{"id":"os-1-048","konu":"1.1.5","terim":"Diş eti çekilmesi","ingilizce":"Gum recession","tanim":"Diş etinin geriye çekilip diş kökünün açığa çıkması; sert fırça buna yol açabilir.","ornek":"Uzun süre sert kıllı fırçayla bastırarak fırçalayan birinin dişleri aynada eskisinden daha uzun görünmeye başlar.","sektor":"Çekilen diş eti kendiliğinden eski yerine dönmez. Bu yüzden baştan yumuşak ya da orta sert fırça seçilir ve dişler bastırmadan fırçalanır.","iliskili":["os-1-046","os-1-047","os-1-049"],"kontrol":null,"gorsel":"h1a-dis-eti-cekilmesi"},{"id":"os-1-057","konu":"1.1.5","terim":"Ağız gargarası","ingilizce":"Mouthwash","tanim":"Ağızdaki bakterileri azaltır, ağız kokusunu önler; tek başına yeterli değildir.","ornek":"Öğle yemeğinden sonra, personel lavabosunda: dişlerini fırçalayan görevli en son gargarayla ağzını çalkalar. Gargara fırçanın yerine geçmez, onu tamamlar.","sektor":"Resepsiyonda, serviste, turda iş konuşarak yapılır ve konukla aran çoğu zaman bir adımdır. Yalnız gargara kullanıp dişini fırçalamayan kişi ağız bakımını yapmış sayılmaz.","iliskili":["os-1-044","os-1-045","os-1-049","os-1-058"],"kontrol":null,"gorsel":"h1a-gargara-dagitici"},{"id":"os-1-058","konu":"1.1.5","terim":"Dil temizleyici","ingilizce":"Tongue cleaner","tanim":"Dil yüzeyinde biriken bakterileri temizler; ağız kokusunu önlemede önemlidir.","ornek":"Sabah 07.00, evde: dişlerini fırçalayan stajyer son olarak dilini de temizler, sonra işe çıkar.","sektor":"Dişler fırçalansa bile dil temizlenmezse ağız kokusu sürebilir. Konuğa yakın mesafede konuşan personel için bu küçük adım büyük fark yaratır.","iliskili":["os-1-045","os-1-007","os-1-057"],"kontrol":null,"gorsel":"h1a-dil-kazima"},{"id":"os-1-173","konu":"1.1.5","terim":"Diş fırçasının saklanması","ingilizce":"Toothbrush storage","tanim":"Kullanılmış fırçanın üzerinde bakteri üremesin diye nemden uzak, temiz ve kuru bir ortamda, kendi kabında bekletilmesidir.","ornek":"Sabah 06.30’da personel yurdunda hazırlanan stajyer, fırçasını yıkayıp sallar ve ayrı fırça kabına koyar; kapaklı, ıslak bir kutuya atmaz.","sektor":"Islak ve kapalı bir kutu bakteri için hazır bir ortamdır; kitaba göre aynı fırçayı uzun süre kullanmak da hem temizliği azaltır hem bakteri birikimini artırır. Vardiyalı çalışanın çantasında taşıdığı fırça bu yüzden havalanabilen bir kılıfta ya da kabında durmalıdır.","iliskili":["os-1-049","os-1-044","os-1-006"],"kontrol":null,"gorsel":"h1a-dis-fircasi-rafi"},{"id":"os-1-059","konu":"1.1.6","terim":"Saç bakımı","ingilizce":"Hair care","tanim":"Islatma, şampuan, durulama, saç kremi, kurulama ve tarama aşamalarıyla saçın temiz ve düzenli tutulması.","ornek":"Saat 07.40, personel soyunma odası: saç yıkanmış, taranmış, toplanmış; omuzda tek bir saç teli ya da kepek yok.","sektor":"Bakımlı saç profesyonel görünümün parçasıdır; dağınık ve bakımsız saç konukta “burası özensiz” duygusu bırakır. Altı aşamanın hiçbiri pahalı ürün istemez, yalnızca düzen ister.","iliskili":["os-1-026","os-1-060","os-1-065","os-1-122","os-1-011"],"kontrol":null,"gorsel":"h1a-sac-fircasi"},{"id":"os-1-060","konu":"1.1.6","terim":"Saç tipi","ingilizce":"Hair type","tanim":"Saçın yağlı, kuru, normal gibi yapısı; şampuan ve bakım ürünleri saç tipine göre seçilir.","ornek":"Market rafının önünde: saçı çabuk yağlanan Elif yağ dengeleyici, saçı kuru olan arkadaşı nemlendirici şampuan alır.","sektor":"Arkadaşına iyi gelen ürün sana iyi gelmeyebilir. Saçına uyan ürünü bulan çalışan vardiyaya düzgün bir görünümle, aynanın önünde daha az uğraşarak başlar.","iliskili":["os-1-026","os-1-059","os-1-061"],"kontrol":null,"gorsel":"h1a-duz-sac"},{"id":"os-1-064","konu":"1.1.6","terim":"Saç derisi","ingilizce":"Scalp","tanim":"Başın saçla kaplı derisi; şampuan buraya nazikçe uygulanır, çok sıcak su ona zarar verir.","ornek":"Duşta: saç önce ılık suyla ıslatılır, şampuan avuçta köpürtülüp parmak uçlarıyla saç derisine yedirilir; tırnakla kazınmaz.","sektor":"Sağlıklı saçın başladığı yer saç derisidir. Kaşıntı ya da pullanma geçmiyorsa ürün değiştirip durmak yerine bir uzmana danışılır.","iliskili":["os-1-026","os-1-061","os-1-067"],"kontrol":null,"cizim":"sac-bakimi"},{"id":"os-1-061","konu":"1.1.6","terim":"Kepek","ingilizce":"Dandruff","tanim":"Saç derisinden dökülen beyaz pulcuklar; uygun olmayan ürün kullanımıyla artabilir.","ornek":"Koyu lacivert üniforma ceketinin omzundaki beyaz pullar, konuğun gözüne ilk çarpan şey olur.","sektor":"Koyu renkli üniformada kepek hemen görünür ve bakımsızlık izlenimi verir. İlk adım saça uygun ürün ve iyi durulamadır; buna rağmen geçmiyorsa bir uzmana başvurulur.","iliskili":["os-1-064","os-1-060","os-1-115","os-1-014"],"kontrol":null},{"id":"os-1-062","konu":"1.1.6","terim":"Saç dökülmesi","ingilizce":"Hair loss","tanim":"Saç tellerinin normalden fazla dökülmesi; özensiz bakım nedenlerinden biridir.","ornek":"Akşam saçını tararken tarakta her zamankinden çok tel kalması; ceketin omzunda dökülmüş saç telleri.","sektor":"Yiyecek ve içecek servisinde dökülen tek bir saç teli tabağa düşebilir; bu yüzden saç toplanır, mutfakta bone takılır. Dökülme uzun sürerse nedeni için hekime danışılır.","iliskili":["os-1-063","os-1-122","os-1-133"],"kontrol":null,"cizim":"sac-bakimi"},{"id":"os-1-063","konu":"1.1.6","terim":"Saç kırılması","ingilizce":"Hair breakage","tanim":"Saç tellerinin kopması; sert kurulama ve yüksek ısı yol açar.","ornek":"Islak saçını havluyla sertçe ovalayıp en yüksek ısıda kurutan birinin saç uçları zamanla kuru ve kırık görünür.","sektor":"Kırık ve yıpranmış uçlar, saç toplanmış olsa bile dağınık görünür. Çözüm pahalı değildir: havluyla nazikçe kurulamak ve ısıyı düşük tutmak.","iliskili":["os-1-066","os-1-032","os-1-065"],"kontrol":null,"gorsel":"h1a-sac-ucu-catallanma"},{"id":"os-1-065","konu":"1.1.6","terim":"Saç kremi","ingilizce":"Conditioner","tanim":"Saçı yumuşatır, kolay taranmasını sağlar; saç uçlarına uygulanıp bekletilir ve durulanır.","ornek":"Şampuan durulandıktan sonra krem yalnız saç uçlarına sürülür, kısa bir süre beklenir ve iyice durulanır.","sektor":"Kremle yumuşayan saç kolay taranır ve kolay toplanır; sabah vardiyasına hazırlanırken zaman kazandırır. Krem kullanılmayan uzun saç karışır, taranırken kopabilir.","iliskili":["os-1-059","os-1-063","os-1-067"],"kontrol":null,"gorsel":"h1a-sac-kremi"},{"id":"os-1-066","konu":"1.1.6","terim":"Saç kurutma makinesi","ingilizce":"Hair dryer","tanim":"Saçı kurutan elektrikli alet; yüksek ısıdan kaçınılmalıdır.","ornek":"Otel odasının banyosunda, duvardaki askıda duran saç kurutma makinesi.","sektor":"Birçok otelde odada konuğa sunulan donanımlardandır; kat görevlisi odayı hazırlarken yerinde ve çalışır durumda olduğuna bakar. Elektrikli bir alet olduğu için kullanırken eller ve ortam kuru olmalıdır.","iliskili":["os-1-063","os-1-059"],"kontrol":null,"gorsel":"t14a-sac-kurutma"},{"id":"os-1-067","konu":"1.1.6","terim":"Tarak","ingilizce":"Comb","tanim":"Saçı düzeltmeye yarayan araç; temiz tutulur ve başkasıyla paylaşılmaz.","ornek":"Personel lojmanında aynı odada kalan iki stajyer: her birinin tarağı kendi dolabında durur, “bir dakikalığına” bile ödünç verilmez.","sektor":"Başkasının tarağı saç derisi hastalıklarını bulaştırabilir; kirli tarak da mikroorganizmaları saç derisine taşır. Saç konuğun gördüğü yerde değil, soyunma odasında taranır.","iliskili":["os-1-064","os-1-006","os-1-009","os-1-090"],"kontrol":null,"gorsel":"h1a-tarak"},{"id":"os-1-068","konu":"1.1.6","terim":"Sülfat","ingilizce":"Sulphate","tanim":"Şampuanlarda köpürtücü olarak kullanılan madde; sülfatsız şampuan çevre dostu seçenektir.","ornek":"Şampuan şişesinin arkasındaki içindekiler listesi; bazı şişelerin ön yüzünde “sülfatsız” yazar.","sektor":"Ders kitabı sülfatsız şampuanı doğa dostu ürün örneği olarak verir. Sülfat yasak bir madde değildir; hassas saç derisinde tahriş yapabildiği için bazı kişiler sülfatsız olanı seçer. Çevreye duyarlı oteller banyoya koydukları şampuanı seçerken içeriğe de bakar.","iliskili":["os-1-026","os-1-021","os-1-087"],"kontrol":null,"cizim":"hijyen-damla"},{"id":"os-1-178","konu":"1.1.6","terim":"Saç havlusu","ingilizce":"Hair towel","tanim":"Yıkanan saçın nazikçe kurulanması için kullanılan, temiz ve kişiye özel havludur.","ornek":"Duştan çıkan stajyer, saçını yumuşak havluyla sıkıştırarak kurular; sert ovalamaz.","sektor":"Saçlar havluyla sert ovalanırsa saç telleri yıpranır ve kırılır; yumuşak ve emici havlu seçilir, başkasıyla paylaşılmaz.","iliskili":["os-1-032","os-1-059","os-1-063"],"kontrol":null,"cizim":"sac-bakimi"},{"id":"os-1-087","konu":"1.1.7","terim":"Paraben","ingilizce":"Paraben","tanim":"Kozmetik ve bakım ürünlerinde bozulmayı geciktirmek ve mikroorganizma çoğalmasını önlemek için kullanılan koruyucu madde.","ornek":"Krem kutusunun üzerindeki “paraben içermez” yazısı; içindekiler listesinde sonu “-paraben” ile biten adlar.","sektor":"Ders kitabı paraben içermeyen ürünleri doğa dostu ürün örneği olarak verir. Koruyucu madde, açılan ürünün bozulmasını geciktirir; hangi ürünü seçersen seç, etiketi okumak ve son kullanma tarihine bakmak bilinçli seçimin ilk adımıdır.","iliskili":["os-1-020","os-1-033","os-1-068","os-1-006"],"kontrol":null,"cizim":"hijyen-damla"},{"id":"os-1-179","konu":"1.1.7","terim":"Pamuk ve uygulama araçları","ingilizce":"Cotton pads and applicators","tanim":"Cilt bakım ürünlerinin temiz ve hijyenik biçimde cilde uygulanmasını sağlayan pamuk gibi yardımcı araçlardır.","ornek":"Yüzünü yıkayıp kurulayan stajyer, toniği temiz bir pamuğa döker ve yüzüne nazikçe sürer.","sektor":"Kitaptaki cilt bakımı basamaklarında tonik temiz bir pamuk yardımıyla uygulanır. Kirli pamuk ya da el, temizlenen cilde yeniden kir taşıyabilir.","iliskili":["os-1-082","os-1-069","os-1-083"],"kontrol":null,"cizim":"hijyen-damla"},{"id":"os-1-111","konu":"1.1","terim":"Su verimliliği","ingilizce":"Water efficiency","tanim":"Suyu ihtiyaç kadar, israf etmeden kullanmak; çevreye ve gelecek nesillere karşı bir sorumluluktur.","ornek":"Dişlerini fırçalarken musluğu kapatan, ellerini sabunlarken suyu boşa akıtmayan bir öğrenci.","sektor":"Otelde su her yerde kullanılır: odalar, mutfak, çamaşırhane, havuz, bahçe. Suyu ihtiyaç kadar kullanmak hem doğal kaynağı korur hem işletmenin giderini azaltır.","iliskili":["os-1-112","os-1-021","os-1-034"],"kontrol":null,"gorsel":"h1a-su-tasarruflu-klozet"},{"id":"os-1-112","konu":"1.1","terim":"Su tasarrufu","ingilizce":"Water saving","tanim":"Evde ve işletmede suyu gereksiz harcamamak için alınan önlemler.","ornek":"Damlatan musluğu fark eden kat görevlisi bunu teknik servise bildirir; banyodaki kart konuğa, askıya astığı havlunun yeniden kullanılacağını hatırlatır.","sektor":"Birçok otel konuğa havlusunu her gün değiştirmeme seçeneği sunar: daha az yıkama, daha az su demektir. Konuk havlusunu askıya astıysa bu tercihine uyulur. Arızayı bildirmek ve musluğu açık bırakmamak her çalışanın katkısıdır.","iliskili":["os-1-111","os-1-032","os-1-128"],"kontrol":null,"gorsel":"t13e-muslugu-kapatan-el"},{"id":"os-1-070","konu":"1.1.7","terim":"Cilt","ingilizce":"Skin","tanim":"Vücudu dış etkilerden koruyan, vücudun en dıştaki organı.","ornek":"Yaz günü havuz başında çalışan görevlinin cildi gün boyu güneşe, rüzgâra, toza ve tere karşı vücudunu korur.","sektor":"Konuk önce yüzüne ve ellerine bakar; bakımlı cilt temiz ve sağlıklı görünümün parçasıdır. Cilt aynı zamanda bir kalkandır: çatlamış, tahriş olmuş cilt bu görevini iyi yapamaz.","iliskili":["os-1-069","os-1-071","os-1-081","os-1-029"],"kontrol":null,"gorsel":"h1a-cilt-dokusu"},{"id":"os-1-069","konu":"1.1.7","terim":"Cilt bakımı","ingilizce":"Skin care","tanim":"Temizleme, tonik, peeling, maske ve nemlendirme adımlarıyla cildin sağlıklı tutulması.","ornek":"Akşam vardiyasından dönünce: yüz temizlenir, tonik sürülür, en son nemlendirici uygulanır. Peeling haftanın bir gününe bırakılır; maske cildin ihtiyacına göre yapılır.","sektor":"Cilt bakımı süs değil, sağlıklı ve profesyonel görünümün parçasıdır. Ürünler cilt tipine göre seçilir ve kimseyle paylaşılmaz.","iliskili":["os-1-083","os-1-082","os-1-084","os-1-085","os-1-086"],"kontrol":null,"cizim":"hijyen-damla"},{"id":"os-1-071","konu":"1.1.7","terim":"Cilt tipi","ingilizce":"Skin type","tanim":"Cildin yapısına göre beş tip: yağlı, kuru, karma, normal ve hassas.","ornek":"Aynı sabunu kullanan iki kardeşten birinin yüzü gün ortasında parlar, ötekininki gerilir ve kurur: cilt tipleri farklıdır.","sektor":"Bakım ürünü arkadaşının tavsiyesine göre değil, kendi cilt tipine göre seçilir. Cilde uymayan ürün tahriş, kuruluk ya da sivilceye yol açabilir.","iliskili":["os-1-072","os-1-073","os-1-074","os-1-075","os-1-076"],"kontrol":null},{"id":"os-1-081","konu":"1.1.7","terim":"Gözenek","ingilizce":"Pore","tanim":"Ciltteki çok küçük açıklıklar; yağlı ciltte geniştir.","ornek":"Aynaya yakından bakınca burnun üstünde ve çevresinde görülen küçük noktacıklar.","sektor":"Ter ve cildin doğal yağı gözeneklerden dışarı çıkar. Gözenek kir ve yağla tıkanırsa sivilce oluşabilir; cilt bakımı bu yüzden temizlemeyle başlar.","iliskili":["os-1-072","os-1-078","os-1-082","os-1-031"],"kontrol":null,"gorsel":"h1a-gozenek"},{"id":"os-1-072","konu":"1.1.7","terim":"Yağlı cilt","ingilizce":"Oily skin","tanim":"Gözenekleri geniş; parlama ve sivilce sık görülür.","ornek":"Öğle servisinin ortasında alnı ve burnu parlayan garson: sabah yüzünü yıkamış olsa da parlama öğleye doğru geri gelir.","sektor":"Ağır ve yağlı ürünler sivilceyi artırabilir; yağlı cilde jel temizleyici gibi hafif ürünler daha uygundur. Utanılacak bir şey değil, doğru bakımla yönetilecek bir cilt tipidir.","iliskili":["os-1-071","os-1-081","os-1-078","os-1-083"],"kontrol":null},{"id":"os-1-073","konu":"1.1.7","terim":"Kuru cilt","ingilizce":"Dry skin","tanim":"Ciltte kuruluk, pullanma ve hassasiyet görülür.","ornek":"Kış sabahı kapıda konuk karşılayan görevlinin yanakları gerilir, ellerinin üstü pul pul olur.","sektor":"Nemlendirilmeyen kuru cilt çatlayabilir ve tahriş olabilir. Sık el yıkayan ve temizlik ürünleriyle çalışan personelin elleri kolay kurur; nemlendirici bu yüzden iş çantasının parçasıdır.","iliskili":["os-1-071","os-1-079","os-1-086","os-1-029"],"kontrol":null,"gorsel":"h1a-kuru-cilt"},{"id":"os-1-074","konu":"1.1.7","terim":"Karma cilt","ingilizce":"Combination skin","tanim":"Yüzün bazı bölgeleri yağlı (T bölgesi), bazı bölgeleri kurudur.","ornek":"Alnı, burnu ve çenesi parlayan ama yanakları kuru olan birinin cildi karmadır.","sektor":"Yüzün her bölgesine aynı bakım uymayabilir: yağlı bölgeye hafif, kuru bölgeye daha yoğun nemlendirici kullanılır.","iliskili":["os-1-071","os-1-077","os-1-072","os-1-073"],"kontrol":null},{"id":"os-1-077","konu":"1.1.7","terim":"T bölgesi","ingilizce":"T-zone","tanim":"Alın, burun ve çeneden oluşan, yağlanmanın en çok görüldüğü yüz bölgesi.","ornek":"Alnın boyunca yatay, burnundan çenene doğru dikey bir çizgi çek: ortaya çıkan şekil T harfidir.","sektor":"Uzun bir vardiyada yüzün ilk parlayan yeri burasıdır. Karma ciltte bakım buna göre ayarlanır: T bölgesine hafif, yanaklara daha yoğun ürün seçilir.","iliskili":["os-1-074","os-1-072","os-1-081"],"kontrol":null,"gorsel":"h1a-t-bolgesi-cizimi"},{"id":"os-1-075","konu":"1.1.7","terim":"Normal cilt","ingilizce":"Normal skin","tanim":"Dengeli, sağlıklı ve sorunsuz cilt tipi.","ornek":"Ne gün ortasında parlayan ne de yıkayınca gerilen, canlı görünen bir yüz.","sektor":"Normal cilt de bakım ister: temizleme ve nemlendirme ihmal edilirse denge bozulabilir. Dengeli beslenme, yeterli su ve düzenli uyku cilde de yansır.","iliskili":["os-1-071","os-1-069","os-1-104"],"kontrol":null},{"id":"os-1-076","konu":"1.1.7","terim":"Hassas cilt","ingilizce":"Sensitive skin","tanim":"Kolay tahriş olan, kızarıklık ve reaksiyon gösteren cilt tipi.","ornek":"Yeni aldığı parfümlü kremi süren birinin yüzü birkaç dakika içinde kızarır ve yanmaya başlar.","sektor":"Kimyasal içeriği yoğun ürünler hassas ciltte alerjik reaksiyona yol açabilir. Temizlik ürünleriyle çalışan personel eldiven takar; ciltteki kızarıklık geçmiyorsa amirine haber verir ve hekime gider.","iliskili":["os-1-071","os-1-080","os-1-029","os-1-024","os-1-037"],"kontrol":null},{"id":"os-1-078","konu":"1.1.7","terim":"Sivilce","ingilizce":"Pimple","tanim":"Gözeneklerin tıkanmasıyla ciltte oluşan iltihaplı kabarcık; yağlı ciltte sık görülür.","ornek":"Sınav haftasında alnında sivilce çıkan stajyer onu sıkmaz; yüzünü temiz tutar ve elini yüzüne götürmemeye çalışır.","sektor":"Sivilceyle oynamak hem cilde zarar verir hem eli kirletir. Hizmet sırasında yüze dokunulmaz; dokunulduysa işe dönmeden önce eller yıkanır. Yaygın ve geçmeyen sivilcede hekime danışılır.","iliskili":["os-1-081","os-1-072","os-1-034"],"kontrol":null},{"id":"os-1-079","konu":"1.1.7","terim":"Pullanma","ingilizce":"Flaking","tanim":"Ciltten ince kepek gibi parçaların dökülmesi; kuru ciltte görülür.","ornek":"Kış ayında nemlendirici sürmeyi bırakan birinin burun kenarlarında ve ellerinin üstünde ince, beyaz pullar belirir.","sektor":"Tabağı uzatan, anahtarı veren el konuğun gözünün önündedir; pul pul olmuş eller bakımsız görünür. Kuru cildi düzenli nemlendirmek pullanmayı azaltır.","iliskili":["os-1-073","os-1-086","os-1-061"],"kontrol":null,"gorsel":"h1a-pullanan-cilt"},{"id":"os-1-080","konu":"1.1.7","terim":"Alerjik reaksiyon","ingilizce":"Allergic reaction","tanim":"Vücudun bir maddeye kızarıklık, kaşıntı, şişlik gibi aşırı tepki vermesi.","ornek":"Yeni bir deodorant deneyen stajyerin koltuk altı kısa süre sonra kızarır ve kaşınır: ürünü kullanmayı bırakır.","sektor":"Konuklarda da görülür: bir yiyecek, sabun ya da deterjan alerjiye yol açabilir. Konuk alerjisini söylediğinde bu bilgi ciddiye alınır ve ilgili bölüme eksiksiz iletilir. Nefes darlığı ya da yüzde şişme gibi ağır bir tepkide hemen 112 aranır ve amire haber verilir.","iliskili":["os-1-076","os-1-024","os-1-029"],"kontrol":null,"gorsel":"h1a-kurdesen"},{"id":"os-1-083","konu":"1.1.7","terim":"Yüz temizleme ürünü","ingilizce":"Facial cleanser","tanim":"Yüzdeki yağ ve kiri temizleyen ürün; örneğin yağlı cilt için jel temizleyici.","ornek":"Akşam eve dönünce: yüz suyla ıslatılır, temizleyici nazikçe köpürtülür ve bol suyla durulanır.","sektor":"Bütün gün toz, ter ve kirle karşılaşan cilt için bakımın ilk adımıdır; öteki ürünler temizlenmiş cilde uygulanır.","iliskili":["os-1-069","os-1-082","os-1-072"],"kontrol":null,"gorsel":"h1a-yuz-temizleme-pedleri"},{"id":"os-1-082","konu":"1.1.7","terim":"Tonik","ingilizce":"Toner","tanim":"Temizlikten sonra gözenekleri sıkılaştırır ve cildi dengeler.","ornek":"Yüzünü yıkayıp kurulayan Zeynep, temiz bir pamuğa döktüğü toniği yüzüne nazikçe sürer.","sektor":"Bakım sırasında ikinci adımdır: temizlemeden sonra, nemlendiriciden önce gelir. Ürün temiz bir pamukla uygulanır; kullanılan pamuk yeniden kullanılmaz.","iliskili":["os-1-069","os-1-083","os-1-081","os-1-086"],"kontrol":null,"gorsel":"h1a-tonik-sisesi"},{"id":"os-1-084","konu":"1.1.7","terim":"Peeling","ingilizce":"Exfoliation (peeling)","tanim":"Haftalık uygulanır; ölü deriyi temizler, cildin yenilenmesini sağlar.","ornek":"Pazar akşamı, haftanın bakım günü: yüz temizlendikten sonra peeling nazikçe uygulanır ve durulanır.","sektor":"“Ne kadar sık, o kadar temiz” düşüncesi yanlıştır: sık ya da sert uygulama cildi tahriş eder. Vücut temizliğindeki karşılığı kesedir; o da ölçülü kullanılır.","iliskili":["os-1-069","os-1-028","os-1-027","os-1-029"],"kontrol":null,"gorsel":"h1a-peeling-kremi"},{"id":"os-1-085","konu":"1.1.7","terim":"Maske","ingilizce":"Face mask","tanim":"Cildin ihtiyacına göre uygulanan bakım ürünü.","ornek":"Cildi kuru olan biri nemlendirici bir maske, cildi yağlı olan biri yağı dengeleyen bir maske seçer.","sektor":"Seçim yine cilt tipine göredir. İlk kez denenen bir üründe ciltte kızarıklık ya da yanma olursa ürün bırakılır.","iliskili":["os-1-069","os-1-071","os-1-080"],"kontrol":null,"cizim":"hijyen-damla"},{"id":"os-1-086","konu":"1.1.7","terim":"Nemlendirici","ingilizce":"Moisturiser","tanim":"Cildin nem dengesini korur, kuruluğu önler; bakımın son adımıdır.","ornek":"Kış sabahı işe çıkmadan önce yüzüne ve ellerine nemlendirici süren kat görevlisi.","sektor":"Gün boyu el yıkayan ve temizlik ürünleriyle çalışan personelin elleri kurur, çatlar; nemlendirici cildi korur. Kuru cilde yoğun, yağlı cilde hafif olanı seçilir.","iliskili":["os-1-069","os-1-073","os-1-079","os-1-093"],"kontrol":null,"cizim":"hijyen-damla"},{"id":"os-1-088","konu":"1.1.7","terim":"Tıraş","ingilizce":"Shaving","tanim":"Cilt ılık suyla yumuşatılır, köpük sürülür, temiz ve keskin jiletle kıl çıkış yönünde tıraş olunur.","ornek":"Sabah 06.30, vardiyadan önce: yüz ılık suyla yıkanır, köpük sürülür, sakal çıkış yönünde tıraş edilir, sonunda yatıştırıcı losyon sürülür.","sektor":"Birçok işletme sakalsız ya da bakımlı, şekilli sakalla çalışmayı ister. Kuru ciltte ya da kör jiletle, aceleyle yapılan tıraş kesik ve kızarıklık bırakır; konuk bunu ilk bakışta görür.","iliskili":["os-1-089","os-1-090","os-1-092","os-1-093","os-1-014"],"kontrol":null,"cizim":"sac-bakimi"},{"id":"os-1-089","konu":"1.1.7","terim":"Tıraş köpüğü / jeli","ingilizce":"Shaving foam / gel","tanim":"Tıraştan önce cilde sürülen, jiletin kaymasını kolaylaştıran ürün.","ornek":"Yüzünü ılık suyla ıslatan stajyer avucuna aldığı köpüğü sakalına yayar, sonra jileti eline alır.","sektor":"Köpüksüz, kuru ciltte yapılan tıraş kızarıklık ve yanma hissine neden olabilir. İşe yetişme telaşı bu adımı atlamanın bahanesi değildir.","iliskili":["os-1-088","os-1-091","os-1-029"],"kontrol":null,"gorsel":"t14a-tras-kopugu"},{"id":"os-1-091","konu":"1.1.7","terim":"Tıraş fırçası","ingilizce":"Shaving brush","tanim":"Köpüğü cilde eşit dağıtmaya yarayan fırça.","ornek":"Berber koltuğunda: usta, kâsede köpürttüğü sabunu fırçayla müşterinin yüzüne dairesel hareketlerle yayar.","sektor":"Geleneksel tıraşta kullanılır. Kişisel bir araçtır: kullanıldıktan sonra yıkanır, kurumaya bırakılır ve paylaşılmaz.","iliskili":["os-1-089","os-1-088","os-1-090"],"kontrol":null,"gorsel":"h1a-tiras-fircasi"},{"id":"os-1-090","konu":"1.1.7","terim":"Jilet / tıraş makinesi","ingilizce":"Razor / shaver","tanim":"Tıraş aracı; temiz ve keskin olmalı, paylaşılmamalıdır.","ornek":"Lojmanda oda arkadaşı “Jiletim bitmiş, seninkini alayım” dediğinde verilmez; yenisi alınır.","sektor":"Jilet cildi çizebilir ve kanla temas edebilir; bu yüzden ortak kullanılması bulaşıcı hastalık riski taşır. Körelmiş jilet tahriş ve kesiğe yol açar, zamanında yenilenir.","iliskili":["os-1-088","os-1-009","os-1-067","os-1-092"],"kontrol":null,"gorsel":"os-jilet"},{"id":"os-1-092","konu":"1.1.7","terim":"Batık","ingilizce":"Ingrown hair","tanim":"Kılın deri altına doğru uzaması; yanlış tıraş yöntemiyle oluşur.","ornek":"Tıraştan birkaç gün sonra boyunda beliren kırmızı, ağrılı küçük kabarcıklar.","sektor":"Gömlek yakasının sürtündüğü boyun bölgesinde çıkarsa hem rahatsız eder hem görünür. Temiz, keskin jiletle ve kıl çıkış yönünde tıraş olmak riski azaltır; batık iğneyle ya da tırnakla kurcalanmaz.","iliskili":["os-1-088","os-1-090","os-1-029"],"kontrol":null,"cizim":"sac-bakimi"},{"id":"os-1-093","konu":"1.1.7","terim":"Tıraş sonrası losyon","ingilizce":"Aftershave","tanim":"Tıraştan sonra cildi yatıştırmak için uygulanan ürün.","ornek":"Tıraş bitince yüz durulanır, kurulanır ve avuca alınan losyon yüze hafifçe bastırılarak sürülür.","sektor":"Kokulu olanı hafif seçilir: konuk seni kokundan değil, hizmetinden hatırlamalıdır. Ardından sürülen nemlendirici tahrişi azaltır.","iliskili":["os-1-088","os-1-086","os-1-029"],"kontrol":null,"cizim":"hijyen-damla"},{"id":"os-1-094","konu":"1.1.8","terim":"Beslenme","ingilizce":"Nutrition","tanim":"Vücudun ihtiyaç duyduğu besin ögelerini yeterli ve düzenli almak.","ornek":"Sabah 06.00 vardiyasına kahvaltı etmeden gelen garson, saat 10.00’a doğru yorulur ve siparişleri karıştırmaya başlar.","sektor":"Otelcilik ayakta ve tempolu yapılan bir iştir. Enerjik ve dikkatli çalışan hizmet kalitesini yükseltir; aç ve yorgun çalışan hata yapar.","iliskili":["os-1-095","os-1-096","os-1-104"],"kontrol":null,"gorsel":"t13b-dengeli-kahvalti"},{"id":"os-1-095","konu":"1.1.8","terim":"Dengeli beslenme","ingilizce":"Balanced diet","tanim":"Her besin grubundan yeterli miktarda tüketmek; fiziksel, zihinsel ve sosyal sağlığı etkiler.","ornek":"Personel yemekhanesinde öğle tabağı: kuru fasulye, bulgur pilavı, salata ve yoğurt.","sektor":"Yalnız bedeni değil, dikkati ve ruh hâlini de etkiler; güler yüzlü hizmet iyi beslenmiş bir çalışanla başlar. Tek tür yiyecekle karın doyurmak dengeli beslenmek değildir.","iliskili":["os-1-094","os-1-096","os-1-104","os-1-108"],"kontrol":null,"gorsel":"t14a-dengeli-tabak"},{"id":"os-1-096","konu":"1.1.8","terim":"Besin ögeleri","ingilizce":"Nutrients","tanim":"Vücudun ihtiyaç duyduğu protein, karbonhidrat, yağ, vitamin ve mineraller.","ornek":"Kahvaltı tabağında yumurta ve peynir protein, ekmek karbonhidrat, zeytin yağ, domates ve biber vitamin ile mineral kaynağıdır.","sektor":"Mutfakta ve serviste çalışan biri için besin ögelerini bilmek, konuğun yemekle ilgili sorusunu doğru cevaplamanın da temelidir.","iliskili":["os-1-097","os-1-098","os-1-099","os-1-095"],"kontrol":null,"gorsel":"f3f-sogus-tabagi-bufe"},{"id":"os-1-097","konu":"1.1.8","terim":"Protein","ingilizce":"Protein","tanim":"Vücudun büyümesi ve onarımı için gerekli besin ögesi: et, süt, yumurta, baklagiller.","ornek":"Kahvaltıda haşlanmış yumurta, öğle yemeğinde mercimek çorbası ya da ızgara tavuk.","sektor":"Gün boyu ayakta çalışan, yük taşıyan bedenin kendini onarması için gereklidir. Et yemeyen konuk için baklagiller, süt ürünleri ve yumurta da protein kaynağıdır.","iliskili":["os-1-096","os-1-098","os-1-095"],"kontrol":null,"gorsel":"h1a-protein-kaynaklari"},{"id":"os-1-098","konu":"1.1.8","terim":"Karbonhidrat","ingilizce":"Carbohydrate","tanim":"Vücudun temel enerji kaynağı: ekmek, pirinç, makarna, patates.","ornek":"Uzun bir vardiyadan önce yenen bir tabak pilav ya da bir dilim ekmek, saatler süren işin enerjisini verir.","sektor":"Ayakta geçen uzun vardiyanın yakıtıdır. Öğün atlamak enerjiyi düşürür; yorgunluk ve dikkatsizlik hizmete yansır.","iliskili":["os-1-096","os-1-097","os-1-094"],"kontrol":null,"gorsel":"h1a-somun-ekmek"},{"id":"os-1-099","konu":"1.1.8","terim":"Vitamin ve mineral","ingilizce":"Vitamins and minerals","tanim":"Vücut işlevleri için az miktarda gereken besin ögeleri (C vitamini, kalsiyum, demir vb.).","ornek":"Portakalda C vitamini, sütte ve yoğurtta kalsiyum, ette ve kuru baklagillerde demir bulunur.","sektor":"Az miktarda gerekir ama eksikliği insanı hâlsiz bırakabilir. En güvenli kaynak çeşitli beslenmedir; vitamin ya da mineral takviyesi ancak hekim önerirse kullanılır.","iliskili":["os-1-096","os-1-095","os-1-100"],"kontrol":null},{"id":"os-1-100","konu":"1.1.8","terim":"Bağışıklık sistemi","ingilizce":"Immune system","tanim":"Vücudu hastalıklara karşı koruyan savunma sistemi; sağlıksız beslenmeyle zayıflar.","ornek":"Sezonun en yoğun haftasında öğün atlayan ve az uyuyan bir çalışan, ekipte dolaşan soğuk algınlığına daha kolay yakalanır.","sektor":"Otel çalışanı gün içinde çok sayıda insanla karşılaşır. Hasta çalışan hem işe gelemez hem de hastalığı konuğa ve ekip arkadaşına taşıyabilir.","iliskili":["os-1-101","os-1-095","os-1-008","os-1-009"],"kontrol":null},{"id":"os-1-101","konu":"1.1.8","terim":"Vücut direnci","ingilizce":"Body resistance","tanim":"Vücudun hastalıklara karşı dayanma gücü; sağlıklı beslenmeyle artar.","ornek":"Kış boyunca düzenli beslenen ve yeterince uyuyan bir resepsiyon görevlisi sezonu daha az hastalanarak geçirebilir.","sektor":"Yoğun sezonda ekip için en değerli şey işe sağlıklı gelen çalışandır. Direnç bir günde kazanılmaz; düzenli alışkanlıkların sonucudur.","iliskili":["os-1-100","os-1-095","os-1-104"],"kontrol":null},{"id":"os-1-102","konu":"1.1.8","terim":"Obezite","ingilizce":"Obesity","tanim":"Vücutta aşırı yağ birikmesi; sağlıksız beslenmenin sonuçlarından biri.","ornek":"Yıllarca her gün kızartma ve şekerli içecekle beslenen, hiç hareket etmeyen birinde aşırı kilo sorunu gelişebilir.","sektor":"Bir sağlık sorunudur; alay konusu ya da insanı yargılama nedeni değildir. Korunmanın yolu dengeli beslenme ve düzenli fiziksel aktivitedir; tedavisi hekimin işidir.","iliskili":["os-1-095","os-1-108","os-1-106","os-1-103"],"kontrol":null},{"id":"os-1-103","konu":"1.1.8","terim":"Kronik hastalık","ingilizce":"Chronic disease","tanim":"Uzun süre devam eden hastalık; sağlıksız beslenme bu hastalıkların riskini artırır.","ornek":"Şeker hastalığı (diyabet) ve yüksek tansiyon, yıllarca süren ve düzenli takip isteyen kronik hastalıklardandır.","sektor":"Konuklar arasında da kronik hastalığı olanlar vardır: diyabetli konuk şekersiz, tansiyon hastası konuk tuzsuz yemek isteyebilir. Bu istek kapris değil, sağlık gereğidir; mutfağa eksiksiz iletilir.","iliskili":["os-1-102","os-1-095","os-1-100"],"kontrol":null,"gorsel":"h1a-tansiyon-olcumu"},{"id":"os-1-108","konu":"1.1.8","terim":"Fast food","ingilizce":"Fast food","tanim":"Hızlı hazırlanan, genellikle yağlı ve tuzlu yiyecekler; sağlıklı yaşam için sınırlanmalıdır.","ornek":"Vardiya arasında her gün hamburger, patates kızartması ve gazlı içecekle karın doyurmak.","sektor":"Yoğun günde en kolay seçenektir; alışkanlığa dönüşürse dengeli beslenmenin yerini alır. Arada bir yemek ile her gün yemek aynı şey değildir.","iliskili":["os-1-095","os-1-102","os-1-104"],"kontrol":null,"gorsel":"t14a-fast-food"},{"id":"os-1-104","konu":"1.1.8","terim":"Sağlıklı yaşam","ingilizce":"Healthy lifestyle","tanim":"Beş öge: dengeli beslenme, yeterli su, düzenli fiziksel aktivite, düzenli uyku, zararlı alışkanlıklardan kaçınma.","ornek":"Kahvaltısını eden, yanında su şişesi taşıyan, işe yürüyerek gelen, gece zamanında uyuyan ve sigara içmeyen bir stajyer beş ögeyi de yerine getirir.","sektor":"Turizmde iş performansı ve hizmet kalitesi çalışanın sağlığına bağlıdır. Enerjik, dikkatli ve sağlıklı çalışan konuk memnuniyetini artırır. Ders kitabına göre yeterli su tüketimi, vücudun sağlıklı çalışması için gün boyunca yeterli miktarda su içmektir; vardiyada su şişesini yanında taşımak bunu kolaylaştırır.","iliskili":["os-1-095","os-1-106","os-1-107","os-1-110","os-1-012"],"kontrol":null},{"id":"os-1-105","konu":"1.1.8","terim":"Yaşam tarzı","ingilizce":"Lifestyle","tanim":"Kişinin beslenme, uyku, hareket gibi günlük alışkanlıklarının bütünü.","ornek":"Biri sabah erken kalkar, kahvaltı eder ve işe yürür; öteki gece geç yatar, öğün atlar ve hep asansörü seçer: ikisinin yaşam tarzı farklıdır.","sektor":"Otelde vardiyalar değişir: sabah, akşam, gece. Alışkanlıklarını vardiyasına göre düzenleyebilen çalışan, yoğun sezonu sağlığını bozmadan çıkarır.","iliskili":["os-1-104","os-1-107","os-1-018"],"kontrol":null},{"id":"os-1-106","konu":"1.1.8","terim":"Fiziksel aktivite","ingilizce":"Physical activity","tanim":"Yürüme, koşma, spor gibi vücudu hareket ettiren her etkinlik.","ornek":"İşe yürüyerek gitmek, asansör yerine merdiveni kullanmak, izin gününde arkadaşlarla top oynamak.","sektor":"Kat görevlisi ve garson gün boyu hareket eder; rezervasyon görevlisi ise uzun süre masa başında kalır. İşi hareketsiz olan, hareketi günün başka bir saatine yerleştirir.","iliskili":["os-1-109","os-1-104","os-1-102"],"kontrol":null,"gorsel":"h1a-parkta-kosu"},{"id":"os-1-109","konu":"1.1.8","terim":"Egzersiz","ingilizce":"Exercise","tanim":"Vücudu güçlendirmek için yapılan düzenli fiziksel aktivite.","ornek":"Haftanın belli günleri yüzmeye gitmek; her sabah evde kısa bir esneme hareketi yapmak.","sektor":"Düzenli egzersiz vücudu güçlü ve esnek tutar, stresle baş etmeyi kolaylaştırır. Uzun vardiyayı kaldıran beden, çalıştırılan bedendir.","iliskili":["os-1-106","os-1-104","os-1-101"],"kontrol":null,"gorsel":"h1a-kosu-bantlari"},{"id":"os-1-107","konu":"1.1.8","terim":"Düzenli uyku","ingilizce":"Regular sleep","tanim":"Her gün yeterli sürede ve benzer saatlerde uyumak; dinlenme ve yenilenme sağlar.","ornek":"Sabah 07.00 vardiyası olan resepsiyon görevlisi gece erken yatar; uykusuz geldiği gün isimleri ve oda numaralarını karıştırır.","sektor":"Uykusuz çalışan dikkatsiz ve sabırsız olur, gülümsemesi zorlaşır; konuk bunu hemen fark eder. Vardiyalı işte uyku düzenini korumak ayrıca özen ister.","iliskili":["os-1-104","os-1-105","os-1-012"],"kontrol":null},{"id":"os-1-110","konu":"1.1.8","terim":"Zararlı alışkanlık","ingilizce":"Harmful habit","tanim":"Sağlığa zarar veren davranış: sigara ve alkol kullanımı gibi.","ornek":"Molada sigara içip doğrudan servise dönen bir garson: koku üniformasına, ellerine ve nefesine siner.","sektor":"Sigara ve alkol hem sağlığa hem mesleğe zarar verir: koku konuğu rahatsız eder, dikkat ve dayanıklılık düşer. Alkollü işe gelmek hiçbir işletmede kabul edilmez.","iliskili":["os-1-104","os-1-045","os-1-014"],"kontrol":null,"gorsel":"h1a-kul-tablasi"},{"id":"os-1-176","konu":"1.1.8","terim":"Yağ","ingilizce":"Fat","tanim":"Vücuda enerji veren besin ögelerinden biridir.","ornek":"Sabah 07.30, personel yemekhanesi: stajyer kahvaltıda zeytin ve ceviz alır, öğle yemeğinde de her gün kızartma yerine ızgara seçer; yağı ölçülü tüketir.","sektor":"Ders kitabı besin ögelerini protein, karbonhidrat, yağ, vitamin ve mineraller olarak sayar. Yağ ölçülü tüketilirse dengeli beslenmenin parçasıdır; kitaba göre sağlıksız beslenme obezite ve kronik hastalık gibi sorunlara yol açabilir.","iliskili":["os-1-096","os-1-097","os-1-098"],"kontrol":null,"cizim":"saglik-kalp"},{"id":"os-1-177","konu":"1.1.8","terim":"Yeterli su tüketimi","ingilizce":"Adequate water intake","tanim":"Vücudun işleyişini sürdürebilmesi için gün içine yayarak yeterince su içme alışkanlığıdır.","ornek":"Öğle servisinde terleyen garson, vardiya arasında yanındaki su şişesinden birkaç yudum alır.","sektor":"Ayakta ve tempolu çalışılan otel işinde su şişesini yanında taşımak alışkanlığı kolaylaştırır. Kitaba göre sağlıklı yaşamın beş ögesinden biridir.","iliskili":["os-1-104","os-1-095","os-1-106"],"kontrol":null,"cizim":"su-tasarrufu"},{"id":"os-1-137","konu":"1.1","terim":"Dezenfeksiyon","ingilizce":"Disinfection","tanim":"Yüzey ve araçlardaki mikroorganizmaların kimyasal madde ya da ısıyla büyük ölçüde yok edilmesi.","ornek":"Kahvaltı büfesi kapanınca tezgâh önce deterjanlı suyla silinir, sonra dezenfektan uygulanır.","sektor":"Sıra önemlidir: önce temizlik, sonra dezenfeksiyon. Kir, dezenfektanın yüzeye ulaşmasını engeller; kirli yüzeye sıkılan dezenfektan işini yapamaz.","iliskili":["os-1-003","os-1-006","os-1-035","os-1-138"],"kontrol":null,"kitapDisi":true,"gorsel":"t14a-dezenfeksiyon"},{"id":"os-1-138","konu":"1.1","terim":"Sanitasyon","ingilizce":"Sanitation","tanim":"Ortamın temizlik ve dezenfeksiyonla sağlık açısından güvenli hâle getirilmesi.","ornek":"Akşam servisi biter: mutfakta zemin yıkanır, tezgâhlar temizlenip dezenfekte edilir, çöpler çıkarılır. Sabah ekibi güvenli bir mutfağa girer.","sektor":"Sektörde temizlik, dezenfeksiyon ve sanitasyon sık sık birlikte anılır. Temizlik görünen kiri alır, dezenfeksiyon mikroorganizmaları azaltır; sanitasyon ikisinin düzenli ve sürekli uygulanmasıyla ulaşılan sonuçtur.","iliskili":["os-1-137","os-1-003","os-1-001","os-1-143"],"kontrol":null,"kitapDisi":true,"cizim":"hijyen-damla"},{"id":"os-1-139","konu":"1.1","terim":"Çapraz bulaşma","ingilizce":"Cross-contamination","tanim":"Mikroorganizmaların el, araç ya da yüzey yoluyla bir yerden başka bir yere, örneğin çiğ etten salataya geçmesi.","ornek":"Çiğ tavuğun doğrandığı tahta yıkanmadan üstünde salata doğranırsa tavuktaki mikroorganizma pişmeyecek olan salataya geçer.","sektor":"Otel mutfaklarında bunu önlemek için çiğ ve pişmiş yiyeceğe ayrı tahta ve bıçak kullanılır; iş değiştirirken eller yıkanır. Gıda zehirlenmelerinin en bilinen nedenlerindendir.","iliskili":["os-1-006","os-1-034","os-1-137","os-1-143"],"kontrol":null,"kitapDisi":true},{"id":"os-1-143","konu":"1.1","terim":"HACCP","ingilizce":"Hazard Analysis and Critical Control Points","tanim":"Gıda güvenliği sistemi: üretimde tehlikeleri belirleyip kritik noktaları kontrol altında tutma.","ornek":"Otel mutfağında soğuk hava deposunun kapısında asılı çizelge: sıcaklık gün içinde düzenli olarak ölçülür ve yazılır.","sektor":"Kısaltma İngilizce adının baş harflerinden oluşur. Mantığı sorun çıktıktan sonra çözmek değil, çıkabileceği noktayı önceden belirleyip orada sürekli kontrol yapmaktır; bu yüzden mutfakta ölçüm ve kayıt bu kadar önemlidir.","iliskili":["os-1-139","os-1-138","os-1-141"],"kontrol":null,"kitapDisi":true},{"id":"os-1-140","konu":"1.1.4","terim":"El hijyeninin 5 anı (DSÖ)","ingilizce":"WHO 5 Moments for Hand Hygiene","tanim":"Dünya Sağlık Örgütünün sağlık hizmetinde ellerin temizlenmesi gereken beş anı belirleyen kuralı.","ornek":"Hastanede hemşire hastaya dokunmadan önce ve dokunduktan sonra ellerini temizler; bu anlar bir kuralla belirlenmiştir.","sektor":"Kural sağlık çalışanları için yazılmıştır ama düşüncesi otelciliğe de yol gösterir: el hijyeninde “nasıl” kadar “ne zaman” da önemlidir. Otelde de ellerin yıkanacağı anlar bellidir.","iliskili":["os-1-034","os-1-035","os-1-008"],"kontrol":null,"kitapDisi":true,"gorsel":"sektor-el-yikama"},{"id":"os-1-175","konu":"1.1.4","terim":"Doğru el yıkama basamakları","ingilizce":"Handwashing steps","tanim":"Ellerin ıslatılması, sabunlanması, parmak aralarının ve tırnakların temizlenmesi, en az 20 saniye yıkanması, durulanması ve kurulanması olmak üzere sırayla izlenen yedi işlem basamağıdır.","ornek":"Sabah 06.45, personel lavabosu: stajyer elini ıslatır, sabunlar, parmak aralarını ve tırnaklarını ovar, en az yirmi saniye yıkar, durular ve kâğıt havluyla kurular.","sektor":"Ders kitabındaki Uygulama 1.1’de öğrenci bu yedi basamağı sırayla uygular ve çalışması kontrol listesiyle değerlendirilir. Sıra ve süre bilindiğinde konukla temas eden her el aynı standartla temizlenir.","iliskili":["os-1-034","os-1-036","os-1-040"],"kontrol":null,"cizim":"el-yikama"},{"id":"os-1-181","konu":"1.1.4","terim":"Çorap","ingilizce":"Socks","tanim":"Ayağı örten giyim parçası; teri emen, kolay kuruyan pamuklu ya da yünlü malzemeden seçilmeli, her gün değiştirilmeli ve kimseyle ortak kullanılmamalıdır.","ornek":"Bütün gün ayakta çalışan servis görevlisi her sabah temiz pamuklu çorap giyer; dünkü çorabı tekrar kullanmaz.","sektor":"Ayaklar nemli ve bakımsız kalırsa mantar enfeksiyonu ve kötü koku ortaya çıkabilir. Kitaba göre ayak bakımında sabun, temiz havlu, pamuklu çorap, uygun ayakkabı ve kişisel tırnak araçları kullanılır.","iliskili":["os-1-042","os-1-010","os-1-043"],"kontrol":null,"cizim":"uniforma"},{"id":"os-1-141","konu":"1.1","terim":"Hijyen eğitimi belgesi","ingilizce":"Hygiene training certificate","tanim":"Gıda ve konaklama gibi sektörlerde çalışanların aldığı, hijyen eğitimini gösteren belge.","ornek":"Yaz sezonu için bir otelin mutfağına başvuran aday, başvuru dosyasına hijyen eğitimi belgesini de koyar.","sektor":"Belge, hijyenin kişisel bir alışkanlık olmanın ötesinde mesleğin bir şartı olduğunu gösterir. Belgeyi almak yetmez; öğrenilenler her vardiyada uygulanır.","iliskili":["os-1-001","os-1-002","os-1-017","os-1-142"],"kontrol":null,"kitapDisi":true,"cizim":"hijyen-damla"},{"id":"os-1-142","konu":"1.1","terim":"Portör muayenesi","ingilizce":"Carrier screening","tanim":"Gıda ile çalışanların hastalık taşıyıcısı olup olmadığını anlamak için yapılan sağlık kontrolü.","ornek":"Eski uygulamada mutfakta çalışan kişi belirli aralıklarla sağlık kuruluşuna giderdi, verdiği örneklerle hastalık taşıyıcısı olmadığını belgelerdi.","sektor":"Hastalık belirtisi göstermediği hâlde mikrop taşıyan kişiye “portör” (taşıyıcı) denir; böyle biri kendini sağlıklı hissederken yiyeceğe mikrop bulaştırabilir. Türkiye’de bu muayene eskiden belirli aralıklarla zorunluydu; 2013’te çıkan Hijyen Eğitimi Yönetmeliği ile yerini hijyen eğitimi aldı. Hekim gerekli görürse yine istenebilir.","iliskili":["os-1-141","os-1-006","os-1-009","os-1-034"],"kontrol":null,"kitapDisi":true,"gorsel":"h1a-tahlil-tupleri"},{"id":"os-1-174","konu":"1.1","terim":"Toplum sağlığı","ingilizce":"Public health","tanim":"Bir toplumda yaşayan insanların bütününün sağlık durumudur.","ornek":"Sabah 07.00, otelin personel girişi: nezle olan bir komi ellerini yıkamadan kapı kollarına ve servis arabasına dokunur; birkaç gün içinde ekipteki birkaç kişi daha hastalanır.","sektor":"Otel kalabalık bir yerdir; bir çalışanın eli konuklara, ekip arkadaşlarına ve ortak yüzeylere ulaşır. Ders kitabına göre bireyin hijyen düzeyi çevresindeki insanların sağlığını doğrudan etkiler ve bu etki ortak kullanım alanlarında ve hizmet sektöründe daha belirgindir.","iliskili":["os-1-002","os-1-009","os-1-139"],"kontrol":null,"cizim":"hijyen-damla"},{"id":"os-1-113","konu":"1.2","terim":"İş kıyafeti","ingilizce":"Work clothing (workwear)","tanim":"Çalışanın mesleki kimliğini ve temsil ettiği kurumu yansıtan en önemli unsurlardan biri.","ornek":"Saat 14.00, otel girişi: konuk daha tek kelime duymadan resepsiyondaki görevlinin ütülü ceketine ve temiz yakasına bakar; “burası işini ciddiye alıyor” diye düşünür.","sektor":"Görünüşün senden önce konuşur. Temiz, düzenli ve mesleğe uygun kıyafet güven verir, profesyonel bir izlenim bırakır ve kuruma duyulan saygıyı gösterir; bu yüzden iş kıyafeti kişisel bir tercih değil, mesleki bir sorumluluktur.","iliskili":["os-1-114","os-1-115","os-1-116","os-1-011","os-1-016"],"kontrol":null,"cizim":"uniforma"},{"id":"os-1-114","konu":"1.2","terim":"Mesleki kimlik","ingilizce":"Professional identity","tanim":"Kişinin mesleğini ve o mesleğin değerlerini görünüşü ve davranışıyla yansıtması.","ornek":"Okulun uygulama otelinde üniformasını giyen öğrenci aynaya bakar: omuzları dikleşir, sesi değişir. Artık yalnız 9. sınıf öğrencisi değil, bir otelcidir.","sektor":"Konuk seni adınla değil mesleğinle tanır: “resepsiyondaki görevli”, “kattaki görevli”. Kıyafetin, duruşun ve konuşman o mesleği nasıl taşıdığını gösterir.","iliskili":["os-1-113","os-1-123","os-1-014","os-1-155"],"kontrol":null,"cizim":"egitim-kariyer"},{"id":"os-1-115","konu":"1.2.1","terim":"Üniforma","ingilizce":"Uniform","tanim":"İşletmenin çalışanları için belirlediği tip, düzenli iş kıyafeti.","ornek":"Sabah 08.00: ön büro ekibi takım elbiseyle, kat görevlileri kendi iş kıyafetleriyle, aşçılar beyaz ceketleriyle iş başındadır. Herkesin bölümü kıyafetinden anlaşılır.","sektor":"Üniformayı giydiğin anda kendi adına değil, otelin adına konuşursun. Konuk kime yaklaşacağını üniformadan anlar; bu yüzden üniforma otelin vitrinidir. Ders kitabında “otel çalışanları için üniforma standart ve düzenli olmalıdır” diye geçer: aynı bölümde çalışan herkes aynı tip kıyafeti giyer.","iliskili":["os-1-113","os-1-118","os-1-130","os-1-132"],"kontrol":null,"cizim":"uniforma"},{"id":"os-1-123","konu":"1.2","terim":"Meslek ahlakı","ingilizce":"Professional ethics","tanim":"Bir mesleğin dürüstlük, temizlik ve düzen gibi ahlaki ilkeleri; Ahilik geleneğinde de önemlidir.","ornek":"Akşam 18.00, kapanış: kimse görmese de tezgâhını silen, önlüğünü yıkanmaya ayıran ve kasayı kuruşu kuruşuna sayan çırak, ustasından gördüğünü yapmaktadır.","sektor":"Ahilik, Anadolu’da esnaf ve zanaatkârların yüzyıllar önce kurduğu meslek dayanışmasıdır; temiz olmayı, düzenli çalışmayı ve doğru sözlü olmayı işin parçası sayar. Otelcilikte de konuğun güveni bu üç şeyle kazanılır.","iliskili":["os-1-114","os-1-113","os-1-003"],"kontrol":null,"cizim":"etik-terazi"},{"id":"os-1-116","konu":"1.2.1","terim":"Temiz kıyafet","ingilizce":"Clean uniform","tanim":"Kir, leke ve kötü koku bulunmayan, günlük temizlenen kıyafet.","ornek":"Saat 07.45, soyunma odası: gömleği askıdan alırsın, yakasına ve koltuk altına bakarsın. Dünden kalma bir iz ya da koku varsa o gömlek bugün giyilmez.","sektor":"Her gün temiz kıyafet giyilir; konuk kıyafetteki kiri ve kokuyu odanın, mutfağın temizliğine yorar. Bu yüzden dolapta yedek bir takım bulundurmak iyi bir alışkanlıktır.","iliskili":["os-1-125","os-1-124","os-1-117","os-1-003"],"kontrol":null,"gorsel":"h1a-katli-gomlekler"},{"id":"os-1-117","konu":"1.2.1","terim":"Düzenli ve ütülü","ingilizce":"Neat and pressed","tanim":"Ütülü kıyafet düzenli ve profesyonel bir görünüm sağlar.","ornek":"Aynı lacivert ceket, iki görevli: birininki askıdan yeni inmiş gibi düzgün, ötekininki çantadan çıkmış gibi buruşuk. Konuk sorusunu ilkine sorar.","sektor":"Ütü, “işimi özenle yaparım” demenin sessiz yoludur. Ütüsüz ya da dağınık kıyafet olumsuz bir ilk izlenim bırakır ve işletmenin itibarına zarar verebilir.","iliskili":["os-1-127","os-1-129","os-1-116","os-1-011"],"kontrol":null},{"id":"os-1-118","konu":"1.2.1","terim":"İşe uygun kıyafet","ingilizce":"Appropriate work clothing","tanim":"Çalışanın görev yaptığı alana ve meslek kurallarına uygun kıyafet.","ornek":"Havuz başındaki görevlinin kısa kollu tişörtü ile resepsiyondaki görevlinin ceketi farklıdır; ikisi de kendi görev yerine uygundur.","sektor":"Kıyafet işe göre seçilir: mutfakta, katta, bankoda ve bahçede yapılan iş aynı değildir. Görev yerine uygun kıyafet hem rahat çalışmanı sağlar hem konuğa doğru kişiye geldiğini gösterir.","iliskili":["os-1-115","os-1-120","os-1-144","os-1-136"],"kontrol":null,"gorsel":"h1a-garson-yelegi"},{"id":"os-1-119","konu":"1.2.1","terim":"Kişisel bakımla uyum","ingilizce":"Well-groomed appearance","tanim":"Saç düzeni, tırnak temizliği ve genel görünümün kıyafetle uyumlu olması.","ornek":"Üniforması kusursuz ama saçı dağınık, tırnakları bakımsız bir garson tabağı masaya bırakır; konuğun gözü tabağa değil ellere gider.","sektor":"Kıyafet tek başına yetmez; saç, tırnak ve genel bakım onu tamamlar. Konuk görünüşe bir bütün olarak bakar: bir eksik, bütün özeni gölgeler.","iliskili":["os-1-122","os-1-005","os-1-038","os-1-131"],"kontrol":null},{"id":"os-1-120","konu":"1.2.1","terim":"Bedene uygun kıyafet","ingilizce":"Well-fitting uniform","tanim":"Çalışanın bedenine uygun, ne dar ne bol kıyafet.","ornek":"Staj öncesi prova: paçası yere sürünen pantolon ile kolu bileği örten ceket terziye gider. Öğrenci ertesi gün kendi bedenine oturan takımla aynaya bakar.","sektor":"Dar kıyafet eğilirken, uzanırken, taşırken hareketi kısıtlar; bol kıyafet özensiz görünür ve bir yere takılabilir. Bedene uygun kıyafet hem daha güvenli hem daha profesyoneldir.","iliskili":["os-1-118","os-1-115","os-1-127"],"kontrol":null,"gorsel":"h1a-terzi-manken"},{"id":"os-1-121","konu":"1.2.1","terim":"Aksesuar","ingilizce":"Accessory","tanim":"Takı, saat gibi tamamlayıcı eşyalar; iş kıyafetiyle aşırı aksesuar kullanılmaz.","ornek":"Servisten önce soyunma odasında: şıngırdayan bilezikler ve uzun kolye çıkarılıp dolaba konur; sade bir saatle salona çıkılır.","sektor":"Aşırı aksesuar dikkati hizmetten uzaklaştırır, bir yere takılabilir ve temizliği zorlaştırır. Neye izin verildiğini işletmenin görünüm standartları belirler.","iliskili":["os-1-119","os-1-131","os-1-130"],"kontrol":null,"gorsel":"h1a-kol-dugmesi"},{"id":"os-1-122","konu":"1.2.1","terim":"Saç düzeni","ingilizce":"Hairstyle","tanim":"Saçın temiz, toplu ve iş kıyafetiyle uyumlu biçimde düzenlenmesi.","ornek":"Kahvaltı servisine çıkan garsonun uzun saçı ensede toplanmıştır; tabağa eğildiğinde yüzüne ya da tabağa düşmez.","sektor":"Dağınık saç bütün görünümü bozar; yiyecek servisinde ise bir hijyen sorunudur. Saçın temiz ve toplu olması kıyafetin tamamlayıcısıdır.","iliskili":["os-1-119","os-1-059","os-1-133"],"kontrol":null,"cizim":"sac-bakimi"},{"id":"os-1-125","konu":"1.2.1","terim":"Leke","ingilizce":"Stain","tanim":"Kıyafette kalan kir izi; iş kıyafetinde leke bulunmamalıdır.","ornek":"Öğle servisinde gömleğin manşetine domates sosu sıçrar. Görevli servisi arkadaşına devredip arka alanda temiz gömleğini giyer ve salona öyle döner.","sektor":"Küçük bir leke bile konuğun gözünde temizlik hakkındaki güveni sarsar. Lekeli kıyafetle konuğun karşısına çıkılmaz; kıyafet değiştirilir.","iliskili":["os-1-116","os-1-124","os-1-134"],"kontrol":null},{"id":"os-1-127","konu":"1.2.2","terim":"Kırışıklık","ingilizce":"Crease","tanim":"Kıyafette oluşan buruşukluk; giymeden önce kontrol edilip ütülenir.","ornek":"Çantaya katlanıp tıkıştırılmış gömlek sabah buruş buruş çıkar. Askıda taşınan gömlek ise ütüden çıktığı gibi kalır.","sektor":"Kırışıklık çoğu zaman yanlış saklamanın sonucudur. Kıyafeti askıda ya da düzgün katlayarak saklamak, sabahki ütü telaşını önler.","iliskili":["os-1-117","os-1-129","os-1-124"],"kontrol":null,"gorsel":"t14zb-kirisik-gomlek"},{"id":"os-1-126","konu":"1.2.2","terim":"Yıpranmış kıyafet","ingilizce":"Worn-out clothing","tanim":"Eskiyip yırtılan ya da rengi solan kıyafet; işte kullanılmamalıdır.","ornek":"Yakası havlanmış, dirseği incelmiş, rengi solmuş bir ceket: sahibi alıştığı için fark etmez, konuk ise ilk bakışta görür.","sektor":"Bakımı yapılmamış, yıpranmış kıyafet işletme hakkında “buraya özen gösterilmiyor” izlenimi uyandırır. Yıprandığını gördüğünde amirine haber verip yenisini istemek senin sorumluluğundur.","iliskili":["os-1-116","os-1-124","os-1-016"],"kontrol":null,"gorsel":"h2-yipranmis-kiyafet"},{"id":"os-1-170","konu":"1.2.1","terim":"Görünüm kontrolü","ingilizce":"Appearance check","tanim":"İşe çıkmadan hemen önce kıyafetin, saçın ve genel görünümün aynada baştan aşağı gözden geçirilip eksiklerin düzeltilmesidir.","ornek":"Saat 07.55, soyunma odasının aynası: yaka düz mü, düğmeler ilikli mi, yaka kartı yerinde mi, saç toplu mu, ayakkabı temiz mi? Yarım dakikalık bir bakıştan sonra görevli lobiye çıkar.","sektor":"Ders kitabındaki iş kıyafeti giyme uygulamasının son adımlarından biridir. Konuğun göreceği şeyi önce sen görürsün; eksik, konuk fark etmeden düzeltilir.","iliskili":["os-1-119","os-1-120","os-1-122","os-1-132"],"kontrol":null,"cizim":"uniforma"},{"id":"os-1-124","konu":"1.2.2","terim":"Kıyafet bakımı","ingilizce":"Uniform care","tanim":"Kirli kıyafetleri ayırma, uygun programda yıkama, kurutma, ütüleme ve temiz saklama.","ornek":"Cuma akşamı evde: haftanın gömlekleri kirli sepetine ayrılır, etiketteki programa göre yıkanır, kurutulur, ütülenir ve pazartesi için askıya asılır.","sektor":"Beş basamak hep aynı sırayla ilerler: ayır, yıka, kurut, ütüle, sakla. Büyük otellerde bu işi çamaşırhane yapar; küçük işletmede ve stajda çoğu zaman sen yaparsın.","iliskili":["os-1-128","os-1-129","os-1-116","os-1-127"],"kontrol":null,"gorsel":"h2-camasir-balkon"},{"id":"os-1-128","konu":"1.2.2","terim":"Çamaşır yıkama","ingilizce":"Laundry","tanim":"Kıyafetlerin uygun programda yıkanıp kurutulması.","ornek":"Vardiya sonunda kirli üniforma çamaşırhaneye bırakılır; ertesi gün yıkanmış ve ütülenmiş olarak teslim alınır.","sektor":"Otellerde “laundry” denen çamaşırhane genellikle kat hizmetlerine (housekeeping) bağlıdır ve konuk çamaşırlarıyla birlikte personel üniformalarını da yıkar. Uygun program kumaşa göre seçilir; yanlış program kıyafeti çektirebilir ya da soldurabilir.","iliskili":["os-1-124","os-1-129","os-1-126"],"kontrol":null,"cizim":"kat-hizmeti"},{"id":"os-1-129","konu":"1.2.2","terim":"Ütüleme","ingilizce":"Ironing","tanim":"Kıyafetteki kırışıklıkların ütüyle giderilmesi.","ornek":"Akşam 21.00, evde: yarın giyilecek gömlek ütülenir, önce yakası ve manşetleri, sonra gövdesi. Askıya asılır, sabaha hazırdır.","sektor":"Ütü bakım basamaklarının dördüncüsüdür: kurutmadan sonra, saklamadan önce yapılır. Ütüyü akşamdan yapmak, sabah aceleyle kırışık kıyafet giymeyi önler.","iliskili":["os-1-127","os-1-117","os-1-124"],"kontrol":null,"cizim":"kat-hizmeti"},{"id":"os-1-130","konu":"1.2","terim":"Kıyafet kuralları","ingilizce":"Dress code","tanim":"İşletmenin çalışanlardan beklediği giyim ve görünüm standartları.","ornek":"İşe başladığın gün insan kaynakları sana bir sayfa verir: hangi bölüm ne giyer, ayakkabı ne renk olur, saç nasıl toplanır. Hepsi orada yazılıdır.","sektor":"Sektörde İngilizcesiyle “dress code” diye geçer. Bu standart sayesinde vardiya ve kişi değişse de konuk hep aynı düzenli görüntüyle karşılaşır.","iliskili":["os-1-115","os-1-131","os-1-118"],"kontrol":null,"kitapDisi":true,"cizim":"uniforma"},{"id":"os-1-131","konu":"1.2","terim":"Kişisel görünüm standartları","ingilizce":"Grooming standards","tanim":"Otellerin saç, sakal, tırnak, takı ve makyaj için belirlediği kurallar.","ornek":"Vardiya başında şef ekibi kısa bir bakışla dolaşır: saçlar toplu mu, tırnaklar kısa ve temiz mi, takılar sade mi?","sektor":"“Grooming” kıyafetin dışında kalan her şeydir: saç, sakal, tırnak, takı, makyaj. Kurallar otelden otele değişir; ortak ilke temiz, sade ve bakımlı görünmektir.","iliskili":["os-1-119","os-1-121","os-1-122","os-1-130"],"kontrol":null,"kitapDisi":true},{"id":"os-1-132","konu":"1.2","terim":"Yaka kartı","ingilizce":"Name badge","tanim":"Çalışanın adını ve görevini gösteren kart; konuğun çalışanı tanımasını sağlar.","ornek":"Kahvaltı salonunda konuk çayını getiren görevlinin yakasındaki ada bakar ve “Teşekkür ederim, Elif Hanım” der.","sektor":"Yaka kartı konuğa kiminle konuştuğunu söyler ve hizmeti kişisel kılar. Üniformanın parçasıdır: düz takılır, okunaklı olur, vardiya boyunca yakada durur.","iliskili":["os-1-115","os-1-130","os-1-113"],"kontrol":null,"kitapDisi":true,"cizim":"uniforma"},{"id":"os-1-144","konu":"1.2","terim":"Ön alan / arka alan","ingilizce":"Front of house / back of house","tanim":"Otelde konuğun gördüğü alanlar (lobi, restoran) ve görmediği alanlar (mutfak, çamaşırhane).","ornek":"Lobide konuğun önünden geçen görevli servis kapısından içeri girer: bir adım sonra mutfak koridorundadır. Kapının iki yanı aynı otelin iki ayrı dünyasıdır.","sektor":"Sektörde “front of house” ve “back of house” diye anılır. Kıyafet de buna göre değişir: ön alanda temsil öne çıkar, arka alanda koruma ve hijyen. Ama özen ikisinde de aynıdır; konuk görmese de sonucunu fark eder.","iliskili":["os-1-118","os-1-136","os-1-133"],"kontrol":null,"kitapDisi":true},{"id":"os-1-136","konu":"1.2","terim":"Kişisel koruyucu donanım (KKD)","ingilizce":"Personal protective equipment (PPE)","tanim":"Çalışanı iş kazası ve hastalıktan koruyan eldiven, maske, gözlük, bone gibi donanımlar.","ornek":"Kat görevlisi banyo temizliğine başlamadan önce eldivenini takar; toz kaldıran bir işte maskesini de kullanır.","sektor":"Kısaltması KKD’dir, İngilizcesi PPE. İşletme verir, çalışan kullanır: “bir kereden bir şey olmaz” diyerek takmamak, iş kazalarının bilinen başlangıçlarından biridir.","iliskili":["os-1-037","os-1-133","os-1-135","os-1-134"],"kontrol":null,"kitapDisi":true,"gorsel":"toz-maskesi"},{"id":"os-1-133","konu":"1.2","terim":"Bone","ingilizce":"Hairnet / hair cap","tanim":"Mutfakta ve yiyecek hizmetinde saçların yiyeceğe düşmesini önleyen başlık.","ornek":"Saat 06.30, otel mutfağı: kahvaltı hazırlığına giren herkes, daha tezgâha yaklaşmadan saçını bonenin içine toplar.","sektor":"Tabakta çıkan tek bir saç teli, bütün mutfağın emeğini bir anda değersizleştirir. Bone bu yüzden mutfak kıyafetinin vazgeçilmez parçasıdır.","iliskili":["os-1-122","os-1-134","os-1-136"],"kontrol":null,"kitapDisi":true,"gorsel":"h2-bone"},{"id":"os-1-134","konu":"1.2","terim":"Önlük","ingilizce":"Apron","tanim":"Kıyafeti kir ve lekeden koruyan, üste giyilen parça.","ornek":"Barista kahve hazırlarken üzerine sıçrayan damlalar önlüğünde kalır; gömleği gün boyu temiz görünür.","sektor":"Önlük kirlenmek için vardır, bu yüzden kirlenince değiştirilir. Elleri önlüğe silmek doğru değildir: eller yıkanır ve kâğıt havluyla kurulanır.","iliskili":["os-1-125","os-1-133","os-1-116"],"kontrol":null,"kitapDisi":true,"cizim":"uniforma"},{"id":"os-1-135","konu":"1.2","terim":"Kaymaz iş ayakkabısı","ingilizce":"Non-slip work shoes","tanim":"Mutfak, kat ve servis alanlarında kaymayı önleyen tabanlı iş ayakkabısı.","ornek":"Bulaşıkhanede zemin ıslaktır; elinde tabak yığınıyla yürüyen görevliyi ayakta tutan şey ayakkabısının tabanıdır.","sektor":"Otelde zemin sık sık ıslanır: mutfakta, bulaşıkhanede, yeni silinmiş koridorda. Kayıp düşme bu işte sık görülen kazalardandır; doğru ayakkabı ucuz ve etkili bir önlemdir.","iliskili":["os-1-136","os-1-043","os-1-118"],"kontrol":null,"kitapDisi":true,"gorsel":"os-kaymaz-is-ayakkabisi"},{"id":"os-1-145","konu":"1.3","terim":"Vücut mekanikleri","ingilizce":"Body mechanics","tanim":"Dururken, otururken, eğilirken ve yük kaldırırken kasları ve eklemleri en az zorlayacak, doğru biçimde kullanmaktır.","ornek":"Yatağı yaparken belden bükülmek yerine dizlerini büken kat görevlisi, günün son odasında da ilk odadaki rahatlıkla çalışır.","sektor":"Otelcilik bedenle yapılan bir iştir: ayakta durulur, eğilinir, taşınır. Bedenini doğru kullanan çalışan kendini korur, sakatlanma riskini azaltır, daha az yorulur ve işini daha verimli yapar. Bunun dört ayağı vardır: kasları ve eklemleri doğru kullanmak, doğru durup oturmak, yükü doğru kaldırmak ve uygun egzersizleri yapmak.","iliskili":["os-1-146","os-1-148","os-1-149","os-1-155","os-1-160","os-1-166"],"kontrol":null,"cizim":"beden-dili"},{"id":"os-1-146","konu":"1.3.1","terim":"Kas ve eklemler","ingilizce":"Muscles and joints","tanim":"Bedenin hareket sistemini oluşturan iki temel yapıdır: kaslar kasılıp gevşeyerek güç üretir, eklemler kemiklerin birleştiği oynak yerlerdir.","ornek":"Yerdeki valize uzanırken dizin bükülür: bükülen yer eklem, seni yeniden ayağa kaldıran güç bacak kaslarındır.","sektor":"Doğru teknikle yapılan hareket kaslara ve eklemlere binen gereksiz yükü azaltır. Bacaklar güçlü kaslara sahiptir; yük kaldırırken işi bele değil onlara yaptırmak bu yüzden önemlidir.","iliskili":["os-1-145","os-1-147","os-1-149","os-1-160"],"kontrol":null,"cizim":"beden-dili"},{"id":"os-1-147","konu":"1.3.2","terim":"Omurga","ingilizce":"Spine","tanim":"Başı ve gövdeyi dik tutan, boyundan kalçaya kadar sırtın ortasından inen kemik dizisidir.","ornek":"Sırtını bir duvara yasla: başın, sırtın ve kalçan aynı çizgiye geldiğinde omurgan doğal dik hâlindedir.","sektor":"Sırt ve bel kasları omurgayı destekler. Doğru duruşta baş ile omurga aynı hizada kalır; yük kaldırırken belin dik tutulması da omurgayı korumak içindir.","iliskili":["os-1-146","os-1-155","os-1-150","os-1-166"],"kontrol":null,"gorsel":"os-omurga"},{"id":"os-1-148","konu":"1.3","terim":"Ergonomi","ingilizce":"Ergonomics","tanim":"Çalışma ortamının, araçların ve eşyaların insan bedenine uygun biçimde düzenlenmesidir.","ornek":"Rezervasyon ofisinde yüksekliği ayarlanan sandalye; resepsiyonda eğilmeden yazılabilen banko; kat görevlisinin uzanmadan ulaştığı kat arabası.","sektor":"İlke şudur: insan işe değil, iş insana uydurulur. Ergonomik bir düzen kas ve eklem sağlığını korur; ağrımayan çalışan daha dikkatli ve daha güler yüzlü çalışır. Ders kitabının birim sonu ölçme bölümünde “ergonomi” ile “kas ve eklem sağlığı”, vücut mekaniklerinin amaçlarıyla ilişkili kavramlar arasında geçer.","iliskili":["os-1-145","os-1-157","os-1-158","os-1-149"],"kontrol":null,"cizim":"beden-dili"},{"id":"os-1-149","konu":"1.3","terim":"Kas ve eklem zorlanması","ingilizce":"Muscle and joint strain","tanim":"Yanlış ya da ani bir hareket yüzünden kasa ve ekleme taşıyabileceğinden fazla yük binmesidir.","ornek":"Acele eden görevli, servis arabasından düşmek üzere olan koliyi yakalamak için gövdesini birden çevirir; belinde bir sızı hisseder.","sektor":"Zorlanmaların çoğu büyük bir kazadan değil, gün içinde defalarca tekrarlanan küçük yanlış hareketlerden doğar. Zamanla ağrıya, eklem hasarına ve hareketin kısıtlanmasına yol açabilir.","iliskili":["os-1-146","os-1-150","os-1-154","os-1-161","os-1-171"],"kontrol":null,"gorsel":"h2-burkulan-bilek"},{"id":"os-1-150","konu":"1.3","terim":"Bel ve sırt ağrısı","ingilizce":"Lower back and back pain","tanim":"Yanlış duruş, yanlış oturuş ve yanlış yük kaldırma alışkanlıklarının bel ve sırt bölgesinde yol açabildiği ağrıdır.","ornek":"Sezonun ortasında bel ağrısı yüzünden işe gelemeyen bir bellboy: hem kendisi çalışamaz hem ekibi eksik kalır.","sektor":"Bedenle yapılan işlerde sık duyulan şikâyetlerdendir. Korunmanın yolu bellidir: doğru durmak, doğru oturmak, yükü doğru kaldırmak ve sırt ile bel kaslarını güçlü tutmak. Geçmeyen ya da şiddetli ağrıda hekime başvurulur.","iliskili":["os-1-149","os-1-151","os-1-161","os-1-166"],"kontrol":null},{"id":"os-1-151","konu":"1.3.2","terim":"Duruş bozukluğu","ingilizce":"Postural disorder","tanim":"Yanlış durma ve oturma alışkanlıkları yüzünden bedenin zamanla doğal dik biçimini kaybetmesidir.","ornek":"Telefona hep başını öne eğerek bakan, sırada hep kambur oturan öğrencinin omuzları yıllar içinde öne doğru yuvarlanır.","sektor":"Bir günde oluşmaz; her gün tekrarlanan yanlış alışkanlığın birikimidir. Sırt ve bel kasları zayıf kaldığında daha kolay ortaya çıkar; düzenli egzersiz duruşun düzelmesine yardım eder.","iliskili":["os-1-155","os-1-150","os-1-152","os-1-166"],"kontrol":null,"cizim":"beden-dili"},{"id":"os-1-152","konu":"1.3.2","terim":"Kas yorgunluğu","ingilizce":"Muscle fatigue","tanim":"Uzun süre aynı konumda kalan ya da fazla zorlanan kasın gücünün azalması ve gerginleşmesidir.","ornek":"Kalabalık bir giriş gününde saatlerce bankoda kıpırdamadan duran görevlinin akşama doğru bacakları ağırlaşır, omuzları gerilir.","sektor":"Yorulan kas bedeni dik tutamaz; duruş bozulur, dikkat dağılır. Ara verip hareket etmek ve düzenli egzersiz kas yorgunluğunu azaltır.","iliskili":["os-1-159","os-1-151","os-1-168","os-1-153"],"kontrol":null},{"id":"os-1-171","konu":"1.3","terim":"Hareket kısıtlılığı","ingilizce":"Restricted movement","tanim":"Ağrı ya da hasar yüzünden bir eklemin ya da bedenin bir bölümünün eskisi kadar rahat hareket edememesidir.","ornek":"Belini inciten kat görevlisi yatağın köşesine eğilemez, rafın üstüne uzanamaz; her gün rahatça yaptığı iş bir anda zorlaşır.","sektor":"Ders kitabı, kasları ve eklemleri yanlış kullanmanın, yanlış duruşun ve yanlış yük kaldırmanın sonuçları arasında hareket kısıtlılığını sayar. Bedenle yapılan bir meslekte rahat hareket edememek, işini yapamamak demektir.","iliskili":["os-1-149","os-1-150","os-1-161","os-1-145"],"kontrol":null},{"id":"os-1-153","konu":"1.3","terim":"Enerjiyi verimli kullanma","ingilizce":"Efficient use of energy","tanim":"Doğru teknikle hareket ederek aynı işi daha az güç harcayıp daha az yorularak yapmaktır.","ornek":"İki kat görevlisi aynı sayıda oda hazırlar: dizlerini kullanıp dengeli çalışan gün sonunda hâlâ dinçtir, her işte belinden eğilen ise tükenmiştir.","sektor":"Vücut mekaniklerine uygun hareket eden kişi gücünü boşa harcamaz, bu yüzden daha geç yorulur. Vardiyanın son saatinde de konuğa aynı güler yüzle hizmet edebilmenin yolu budur. Ders kitabı bunu “enerji tasarrufu” diye anar.","iliskili":["os-1-145","os-1-152","os-1-154"],"kontrol":null,"cizim":"enerji"},{"id":"os-1-154","konu":"1.3.1","terim":"Kontrollü hareket","ingilizce":"Controlled movement","tanim":"Bir hareketi dengeyi koruyarak, acele etmeden, ani ve sert çıkışlar yapmadan gerçekleştirmektir.","ornek":"Bellboy valizi bagaj arabasına fırlatmaz; kavrar, kaldırır, yerine yavaşça yerleştirir.","sektor":"Ani ve sert hareket kası hazırlıksız yakalar. Eğilirken, uzanırken, kaldırırken ve dönerken ilke aynıdır: önce denge, sonra hareket.","iliskili":["os-1-149","os-1-160","os-1-164","os-1-165","os-1-172"],"kontrol":null,"gorsel":"h2-tai-chi-park"},{"id":"os-1-172","konu":"1.3","terim":"Eğilme ve uzanma","ingilizce":"Bending and reaching","tanim":"Yerdeki ya da uzaktaki bir şeye ulaşmak için bedenin dengeyi koruyarak, ani hareket yapmadan ve zorlanmadan öne, aşağı ya da yana yönelmesidir.","ornek":"Kat görevlisi yere düşen yastık kılıfını almak için dizlerini büker; rafın ucundaki havluya ise kolunu zorlayarak uzanmaz, bir adım yaklaşır.","sektor":"Ders kitabındaki uygulamada üç hareket çalışılır: öne eğilme, yerden hafif bir nesne alma ve yana uzanma. Üçünde de ölçüt aynıdır: dengeni koru, ani hareket yapma, bedenini zorlama.","iliskili":["os-1-154","os-1-160","os-1-149","os-1-145"],"kontrol":null,"cizim":"beden-dili"},{"id":"os-1-155","konu":"1.3.2","terim":"Doğru duruş","ingilizce":"Correct posture","tanim":"Ayaktayken ya da otururken başın, omuzların ve omurganın aynı hizada, dik ve rahat tutulmasıdır.","ornek":"Lobide konuk bekleyen iki görevli: birinin başı dik, omuzları geride; öteki omuzları düşük, sütuna yaslanmış. Konuk hangisine yaklaşır?","sektor":"Doğru duruş kasların ve eklemlerin dengeli çalışmasını sağlar, ileride oluşabilecek sağlık sorunlarını önler. Konuğa verdiği mesaj da açıktır: dik duruş “hazırım” der.","iliskili":["os-1-156","os-1-157","os-1-147","os-1-151","os-1-114"],"kontrol":null,"gorsel":"h2-dik-duran-siluet"},{"id":"os-1-156","konu":"1.3.2","terim":"Doğru ayakta durma","ingilizce":"Correct standing posture","tanim":"Gövde dik, omuzlar geride ve rahat, ağırlık iki ayağa dengeli verilmiş olarak ayakta durmaktır.","ornek":"Akşam 20.00, resepsiyon bankosu: görevli iki ayağının üstünde dengeli durur; konuk yokken banko arkasında birkaç adım atar.","sektor":"Resepsiyonda, kapıda ve serviste işin büyük bölümü ayakta geçer. Hep tek ayağa yüklenmek ya da bankoya yaslanmak hem bedeni yorar hem konuğa özensiz görünür.","iliskili":["os-1-155","os-1-159","os-1-152","os-1-157"],"kontrol":null,"cizim":"beden-dili"},{"id":"os-1-157","konu":"1.3.2","terim":"Doğru oturma","ingilizce":"Correct sitting posture","tanim":"Sırt dik, bel destekli, ayaklar yere tam basmış, dizler ve kalça dengeli bir hizada olacak biçimde oturmaktır.","ornek":"Rezervasyon ofisinde ekran başındaki görevli: sırtı arkalığa dayalı, iki ayağı yerde. Yanındaki arkadaşı ise sandalyenin ucunda, ekrana doğru kamburlaşmış.","sektor":"Rezervasyon, santral ve muhasebe gibi görevlerde saatlerce oturulur. Yanlış oturma alışkanlığı zamanla bel ve sırt ağrısına yol açabilir; doğru oturuş hem sağlığı korur hem iş verimini artırır.","iliskili":["os-1-155","os-1-158","os-1-159","os-1-148"],"kontrol":null,"cizim":"beden-dili"},{"id":"os-1-158","konu":"1.3.2","terim":"Bel desteği","ingilizce":"Lumbar support","tanim":"Otururken belin boşta kalmaması için sandalyenin arkalığına ya da bir desteğe dayanmasıdır.","ornek":"Görevli sandalyenin ucuna ilişmek yerine geriye doğru yerleşir; beli arkalığa değdiğinde sırtı kendiliğinden dikleşir.","sektor":"Bel boşta kaldığında bütün yükü kaslar taşır ve çabuk yorulur. Sandalyeyi kendine göre ayarlamak, oturarak yapılan işte ilk yapılacak şeydir.","iliskili":["os-1-157","os-1-148","os-1-150"],"kontrol":null,"gorsel":"h2-bel-destekli-koltuk"},{"id":"os-1-159","konu":"1.3.2","terim":"Ara verip hareket etme","ingilizce":"Movement break","tanim":"Uzun süre ayakta ya da oturarak aynı konumda kalmak yerine belirli aralıklarla konum değiştirip birkaç adım atmaktır.","ornek":"Uzun bir rezervasyon listesini giren görevli ara sıra kalkar, yazıcıya kadar yürür, omuzlarını gevşetir ve işine döner.","sektor":"Hareketsiz kalan kas yorulur ve gerilir; kısa bir hareket onu dinlendirir. Bu bir kaytarma değil, vardiyanın sonuna kadar dinç kalmanın yoludur.","iliskili":["os-1-152","os-1-156","os-1-157","os-1-168"],"kontrol":null,"cizim":"saat-zaman"},{"id":"os-1-160","konu":"1.3.3","terim":"Doğru ağırlık kaldırma","ingilizce":"Safe lifting technique","tanim":"Yükü, dizleri bükerek çömelip beli dik tutarak ve bedene yakın tutarak kontrollü biçimde kaldırmaktır.","ornek":"Çamaşırhanede yerdeki çarşaf torbası: görevli torbanın karşısına geçer, çömelir, torbayı gövdesine yakın kavrar ve bacaklarıyla doğrulur.","sektor":"Bu teknikte yük yalnız bele değil bütün bedene dengeli dağılır. Bellboy, kat görevlisi ve depo görevlisi için bu, mesleği yıllarca sağlıkla sürdürebilmenin temel kuralıdır. Rahatça kaldıramayacağın yük için bagaj arabası kullanılır ya da yardım istenir. Ders kitabının beş kuralı: dizlerini kullan, belini dik tut, yükü vücuduna yakın taşı, ani ve sert hareketten kaçın, belinden değil bütün vücudunla dön.","iliskili":["os-1-161","os-1-162","os-1-163","os-1-146","os-1-154"],"kontrol":null,"gorsel":"h2-yerden-agirlik"},{"id":"os-1-161","konu":"1.3.3","terim":"Belden eğilerek kaldırma","ingilizce":"Lifting by bending at the waist","tanim":"Dizleri bükmeden yalnız beli öne eğerek yük almaktır; en yaygın ve en tehlikeli kaldırma hatalarından biridir.","ornek":"Acelesi olan görevli bagajdaki ağır valize dizlerini kırmadan uzanır ve tek hamlede çeker; bütün yük beline biner.","sektor":"Bu hareket bel ve sırt bölgesine aşırı yük bindirir; tekrarlandıkça kalıcı rahatsızlıklara yol açabilir. Yanlış kaldırmanın bilinen sonuçları bel ve sırt ağrısı, kas zorlanması, eklem hasarı ve hareket kısıtlılığıdır. Hızlı göründüğü için yapılır, oysa kazandırdığı birkaç saniyenin bedeli çok ağır olabilir.","iliskili":["os-1-160","os-1-150","os-1-149","os-1-171"],"kontrol":null},{"id":"os-1-162","konu":"1.3.3","terim":"Yükü vücuda yakın tutma","ingilizce":"Keeping the load close to the body","tanim":"Kaldırılan ya da taşınan eşyanın kolları öne uzatmadan gövdenin hemen önünde tutulmasıdır.","ornek":"Depodan gelen su kolisini görevli kollarını uzatarak değil, karnına yakın tutarak taşır.","sektor":"Yük gövdeden uzaklaştıkça bele ve kollara binen zorlanma artar; yakın tutulan yük daha hafif hissedilir ve daha kolay dengelenir.","iliskili":["os-1-160","os-1-163","os-1-153"],"kontrol":null,"gorsel":"h2-kolileri-gogse-yakin"},{"id":"os-1-163","konu":"1.3.3","terim":"Doğru yük taşıma","ingilizce":"Safe carrying technique","tanim":"Kaldırılan yükün bedene yakın tutularak, dengeyi koruyarak ve acele etmeden bir yerden başka bir yere götürülmesidir.","ornek":"Bellboy valizi kaldırdıktan sonra koşmaz; önündeki yolu görerek, dengeli adımlarla asansöre yürür.","sektor":"Taşırken denge bozulursa hem çalışan hem konuğun eşyası zarar görür. Önünü kapatacak kadar çok şeyi bir seferde taşımak yerine iki sefer yapmak ya da araba kullanmak daha güvenlidir.","iliskili":["os-1-160","os-1-162","os-1-164","os-1-165"],"kontrol":null},{"id":"os-1-164","konu":"1.3.3","terim":"Tüm vücutla dönme","ingilizce":"Turning with the whole body","tanim":"Elde yük varken yön değiştirmek için beli burmak yerine ayaklarla adım atarak gövdenin bütünüyle dönmektir.","ornek":"Kat arabasından aldığı çarşaf destesini yatağa koyacak olan görevli belinden kıvrılmaz; küçük adımlarla yatağa doğru döner.","sektor":"Yük taşırken belden dönmek, omurgayı hem yüklenmiş hem burulmuş durumda bırakır. Küçük bir adım atmak bu zorlanmayı ortadan kaldırır.","iliskili":["os-1-163","os-1-154","os-1-149","os-1-147"],"kontrol":null},{"id":"os-1-165","konu":"1.3.3","terim":"Yükü kontrollü bırakma","ingilizce":"Setting the load down safely","tanim":"Taşınan eşyanın yere atılmadan, kaldırırken olduğu gibi dizler bükülerek ve yavaşça yerine konmasıdır.","ornek":"Odaya gelen bellboy valizi yere bırakırken dizlerini büker ve yavaşça yerleştirir; ne valiz ses çıkarır ne beli zorlanır.","sektor":"Kaldırma işi yük yerine konunca biter. Bırakırken yapılan ani hareket de kaldırırken yapılan kadar zarar verebilir; ayrıca konuğun eşyasını atmak saygısızlıktır.","iliskili":["os-1-160","os-1-163","os-1-154"],"kontrol":null,"cizim":"bavul"},{"id":"os-1-166","konu":"1.3.4","terim":"Sırt ve bel egzersizleri","ingilizce":"Back and lower back exercises","tanim":"Omurgayı destekleyen sırt ve bel kaslarını güçlendirmek ve esnetmek için düzenli yapılan hareketlerdir.","ornek":"Uzun bir vardiyadan çıkan görevli evde, öğretmeninden öğrendiği birkaç basit hareketi yapar; ertesi sabah işe daha rahat başlar.","sektor":"Uzun süre ayakta duran, oturan ya da yük taşıyanlar için önerilir: kasları güçlendirir, esnekliği artırır, duruşu düzeltir, sakatlanma riskini ve kas yorgunluğunu azaltır. Hareketler bilen birinden öğrenilir; bel ya da sırt ağrısı olan kişi önce hekime danışır.","iliskili":["os-1-167","os-1-168","os-1-169","os-1-150","os-1-109"],"kontrol":null,"gorsel":"h2-bel-egzersizi"},{"id":"os-1-167","konu":"1.3.4","terim":"Isınma","ingilizce":"Warm-up","tanim":"Egzersize başlamadan önce bedeni harekete hazırlamak için yapılan kısa ve hafif hareketlerdir.","ornek":"Beden eğitimi dersinde maçtan önce yapılan hafif tempolu yürüyüş ve kol çevirme hareketleri.","sektor":"Hazırlanmamış kas ani zorlanmaya açıktır. Egzersizde de sıra bellidir: önce ısınma, sonra esneme ve güçlendirme hareketleri.","iliskili":["os-1-166","os-1-168","os-1-169"],"kontrol":null,"gorsel":"t14a-isinma-esneme"},{"id":"os-1-168","konu":"1.3.4","terim":"Esneme hareketi","ingilizce":"Stretching exercise","tanim":"Kası yavaşça uzatarak gerginliğini azaltan ve esnekliğini artıran harekettir.","ornek":"Saatlerdir ekran başında oturan görevli ayağa kalkar, kollarını yavaşça yukarı uzatır ve omuzlarını gevşetir.","sektor":"Basit bir esneme bile kası rahatlatır ve kan dolaşımını artırır. Yavaş ve kontrollü yapılır; kas zorlanmaz, acı hissedilen noktada durulur.","iliskili":["os-1-166","os-1-167","os-1-152","os-1-159"],"kontrol":null,"gorsel":"h2-esneme"},{"id":"os-1-169","konu":"1.3.4","terim":"Güçlendirme hareketi","ingilizce":"Strengthening exercise","tanim":"Kası çalıştırarak daha dayanıklı hâle getiren ve omurgaya verdiği desteği artıran harekettir.","ornek":"Öğretmeninin atölyede gösterdiği hareketi haftalarca düzenli yapan öğrenci, sırada eskisi kadar çabuk yorulmadan dik oturabildiğini fark eder.","sektor":"Güçlü sırt ve bel kasları doğru duruşu korumayı kolaylaştırır. Hareket dengeyi ve kontrolü koruyarak, ani ve zorlayıcı olmadan yapılır; doğru biçimi öğretmenden ya da bir uzmandan öğrenilir.","iliskili":["os-1-166","os-1-167","os-1-151","os-1-147"],"kontrol":null,"gorsel":"h2-plank"}],"acikSorular":[{"id":"os-1-y01","konu":"1.1","soru":"Yeni işe başlayan bir otel personeli, konuklarla temas ederken el hijyeninin neden önemli olduğunu soruyor. Bu konuda yapması gereken iki uygulamayı yazınız ve bu uygulamaların bulaşıcı hastalıkların yayılmasını nasıl önlediğini açıklayınız.","olcut":[{"metin":"Mikroorganizmaların eller yoluyla yayılabileceğini ve hastalık yapabileceğini belirtir.","puan":25},{"metin":"Birinci uygulamayı yazar ve açıklar.","puan":20},{"metin":"İkinci uygulamayı yazar ve açıklar.","puan":20},{"metin":"Uygulamaların bulaşıcı hastalıkların yayılmasını nasıl önlediğini açıklar.","puan":35}],"ornek":"El hijyeni: mikroorganizmalar eller aracılığıyla kapı kolu, para ve ortak yüzeylerden konuğa geçebilir. Uygulama 1: işe başlamadan ve konukla temas etmeden önce ellerin sabunla yıkanması. Uygulama 2: öksürdükten ya da burnunu sildikten sonra ellerin yıkanması. Bu uygulamalar mikroorganizmaların vücuda ve başka kişilere geçişini azaltır.","ipucu":"Mikroorganizmaların hangi yolla (el, yüzey, eşya) yayıldığını bağlayın; “temiz olmalı” demek yetmez."},{"id":"os-1-y02","konu":"1.2","soru":"Bir otelin kat hizmetleri ekibinden bir personel, kendisine verilen üniformayı giymeden işe gelmektedir. Bu davranışın işletmenin kurumsal imajı üzerindeki etkisini açıklayınız. Üniforma kuralının gerekçesini belirtiniz ve bu kuralı uygulamanın bir yolunu öneriniz.","olcut":[{"metin":"Kurumsal imaj kavramını doğru tanımlar.","puan":25},{"metin":"Üniformasız çalışmanın konuk algısına etkisini açıklar.","puan":25},{"metin":"Üniforma kuralının gerekçesini (güven, hijyen, tanınma) belirtir.","puan":25},{"metin":"Kuralı uygulamaya yönelik somut bir öneri yapar.","puan":25}],"ornek":"Kurumsal imaj: işletmenin dışarıya yansıyan görüntüsüdür; çalışanların kıyafeti bu görüntünün parçasıdır. Üniformasız çalışan, konukta düzensiz bir izlenim bırakır. Üniforma; hijyen, güven ve personelin tanınması için verilir. Öneri: vardiya başında kıyafet kontrolü yapılması ve eksik üniformanın yönetime bildirilmesi.","ipucu":"Kurallar yalnızca “uyulmalı” diye değil, neden konduğu ile birlikte yazılmalı."}],"sorular":[{"id":"os-1-s01","tur":"coktan-secmeli","soru":"Hangisi temizlik ile hijyen arasındaki farkı doğru anlatır?","secenekler":["Temizlik görünen kiri giderir; hijyen sağlığı koruyan tüm önlemleri kapsar.","Hijyen görünen kiri giderir; temizlik sağlığı koruyan tüm önlemleri kapsar.","İkisi de yalnız dış görünüşle ilgilidir; fark, uygulayan kişidedir.","Temizlik hijyenden daha geniştir; hijyen temizliğin küçük bir bölümüdür."],"dogru":0,"aciklama":"Temizlik hijyenin bir parçasıdır: kiri, tozu, lekeyi gidermek hijyenin yalnız bir yanıdır. Hijyen sağlığı koruyan tüm önlemleri kapsadığı için daha geniştir."},{"id":"os-1-s02","tur":"coktan-secmeli","soru":"Doğru el yıkamada eller neden en az 20 saniye yıkanır?","secenekler":["Sabun ve su, parmak aralarındaki ve tırnak altındaki mikroorganizmalara etki etsin diye.","Sabunun kokusu ellere iyice yerleşsin ve eller uzun süre temiz kokulu kalsın diye.","Su iyice ısınıp mikroorganizmaları öldürsün, böylece kurulama süresi de kısalsın diye.","Eldeki ölü deri tamamen uzaklaşsın ve cilt sonraki yıkamaya kadar nemli kalsın diye."],"dogru":0,"aciklama":"Mikroorganizmalar parmak aralarında ve tırnak altında kalır; sabunun ve suyun onlara etki etmesi için en az 20 saniye gerekir. Kısa yıkama görünen kiri alır ama hijyeni sağlamaz."},{"id":"os-1-s03","tur":"coktan-secmeli","soru":"Tırnak bakımıyla ilgili hangisi yanlıştır?","secenekler":["Tırnaklar banyodan sonra, yumuşamışken kesilir.","Tırnaklar haftada bir kez düzenli olarak kısaltılır.","Ayak tırnakları da yarım ay biçiminde kesilir.","El tırnakları, yarım ay biçimi verilerek kesilir."],"dogru":2,"aciklama":"Ayak tırnakları düz kesilir; yarım ay biçimi yalnız el tırnakları içindir."},{"id":"os-1-s04","tur":"coktan-secmeli","soru":"Duştan sonra ayak parmak araları kurulanmadan çorap giyen birinde birkaç gün sonra kaşıntı ve kızarıklık başlıyor. En olası sonuç ve nedeni hangisidir?","secenekler":["Tırnak batması; ıslak kalan tırnak yumuşar ve kenarı ete saplanır.","Tahriş; çorabın lifleri nemli cildi ovalayarak yakar.","Mantar enfeksiyonu; nemli ve kapalı ortam mantarların çoğalmasına elverişlidir.","Pullanma; nem, ciltteki ölü hücrelerin dökülmesini hızlandırır."],"dogru":2,"aciklama":"Parmak araları iyi kurulanmazsa nem kalır ve mantar bu ortamda çoğalır; kaşıntı ve kızarıklık bunun belirtisidir. Tırnak batması tırnak kenarında olur, parmak arasında değil."},{"id":"os-1-s05","tur":"coktan-secmeli","soru":"Terli bir çalışan duş almadan koltuk altına deodorant sıkarsa ne olur?","secenekler":["Deodorant duşun yerini tutar; ter kokusu hiç oluşmaz.","Ter ve kir cildin üzerinde kaldığı için kötü koku tam olarak giderilmez.","Bakteriler deodorantla yok olur; hijyen tam olarak sağlanır.","Deodorant cildi temizler; ter kokusu kendiliğinden geçer."],"dogru":1,"aciklama":"Deodorant kötü kokuyu önlemeye yardım eder ama temizlik yapmaz; temiz ve kuru cilde uygulanır. Kirli cilde sıkılırsa koku deodorantla karışır."},{"id":"os-1-s06","tur":"coktan-secmeli","soru":"Çürüğe karşı korunmak için diş macunu seçerken kutuda hangi maddenin yazmasına bakılır?","secenekler":["Sülfat","Paraben","Florür","Gargara"],"dogru":2,"aciklama":"Florür diş minesini güçlendirerek çürük oluşumunu önlemeye yardım eder. Sülfat köpürtücü, paraben koruyucu maddedir; ikisi de çürükle ilgili değildir."},{"id":"os-1-s07","tur":"coktan-secmeli","soru":"Uzun süre sert kıllı fırçayla bastırarak dişlerini fırçalayan birinde en olası sonuç hangisidir?","secenekler":["Dil yüzeyinde bakteri birikmesi","Diş etinin çekilip diş kökünün açığa çıkması","Diş aralarında yiyecek artığı sıkışması","Dişlerin florürü kaybetmesi"],"dogru":1,"aciklama":"Sert fırça ve sert bastırma diş etinin geriye çekilmesine yol açar. Dil bakterisi dil temizleyiciyle, sıkışan artık diş ipiyle ilgilidir; fırçanın sertliğiyle ilgili değildir."},{"id":"os-1-s08","tur":"coktan-secmeli","soru":"Üç aydır kullandığı fırçanın kıllarının iki yana açıldığını gören biri ne yapmalıdır?","secenekler":["Sıcak suyla yıkayıp kullanmalı; kıllar böylece düzelir.","Altı ay dolmasını beklemeli; fırça ancak o zaman değişir.","Bir yıl beklemeli; fırça en az yılda bir yenilenir.","Yenisini almalı; diş fırçası 2–3 ayda bir değişir."],"dogru":3,"aciklama":"Yıpranmış fırça plağı iyi temizlemez; bu yüzden 2–3 ayda bir değiştirilir. Sıcak su kılları düzeltmez, yıpranmayı gidermez."},{"id":"os-1-s09","tur":"coktan-secmeli","soru":"Dişlerin arasına sıkışan yiyecek artıklarını temizlemek için hangi araç kullanılır?","secenekler":["Dil temizleyici","Diş ipi","Ağız gargarası","Diş macunu"],"dogru":1,"aciklama":"Fırça diş aralarına giremez; sıkışan artıklar diş ipiyle çıkarılır. Dil temizleyici dile, gargara ağız içine yönelir; ikisi de diş aralarındaki artığı almaz."},{"id":"os-1-s10","tur":"coktan-secmeli","soru":"Bakımlı çalışanlar sayesinde otelin toplum gözündeki saygınlığı artıyor. Hangi kavram güçlenmiştir?","secenekler":["Kurumsal itibar","Kurumsal imaj","Profesyonel imaj","Mesleki yeterlilik"],"dogru":0,"aciklama":"İşletmenin konuklar ve toplum gözündeki saygınlığına kurumsal itibar denir. Kurumsal imaj işletmenin dışarıya yansıyan görüntüsüdür; saygınlık değil, görünümdür."},{"id":"os-1-s11","tur":"dogru-yanlis","soru":"Eldiven giymek el yıkama gereğini ortadan kaldırmaz; eller eldiven giymeden önce de çıkardıktan sonra da yıkanır.","secenekler":["Doğru","Yanlış"],"dogru":0,"aciklama":"Eldiven eli korur ama içine mikroorganizma girebilir ve çıkarırken ele bulaşabilir; bu yüzden iki durumda da eller yıkanır."},{"id":"os-1-s12","tur":"dogru-yanlis","soru":"Havlu yıkandığı sürece temiz sayılır; bu yüzden ekip arkadaşlarıyla ortak kullanılabilir.","secenekler":["Doğru","Yanlış"],"dogru":1,"aciklama":"Havlu kişiye özeldir; nemli havlu mikroorganizmaları taşır ve ortak kullanım bulaşıcı hastalığa yol açar. Temiz görünmesi güvenli olduğu anlamına gelmez."},{"id":"os-1-s13","tur":"senaryo","durum":"Stajının ilk haftası, saat 12.20, otelin restoranı. Kasada bir konuğun hesabını aldın, para üstünü verdin. Mutfak girişindeki lavabo hemen yanında. Tam o sırada şef, ekmek sepetlerini masalara dağıtmanı istiyor.","soru":"Ne yaparsın?","secenekler":["Elime el dezenfektanı sıkar, kurumasını bekleyip sepetleri dağıtırım.","Ellerimi önlüğüme siler, sepetleri hemen dağıtırım.","Sepetleri yalnız kenarından tutar, hemen dağıtırım.","Lavaboya gider, ellerimi su ve sabunla yıkar, sonra sepetleri dağıtırım."],"dogru":3,"aciklama":"Para pek çok elin dokunduğu ortak kullanılan bir yüzeydir; ekmeğe geçmeden eller yıkanır. Lavabo yakındayken dezenfektan yeterli sayılmaz: o, su ve sabun olmadığında kullanılır."},{"id":"os-1-s14","tur":"senaryo","durum":"Saat 10.30, üçüncü kat. Oda görevlisi olarak banyoyu eldivenle temizledin. Sırada, servis arabasındaki temiz havluları banyoya yerleştirmek var. Koridorda seni bekleyen dört oda daha var.","soru":"İlk adımın ne olur?","secenekler":["Eldiveni çıkarır, havluları hemen yerleştiririm.","Aynı eldivenle havluları yerleştirir, odayı sonra toparlarım.","Eldivenin üstüne ikinci bir çift giyip havluları öyle yerleştiririm.","Eldiveni çıkarır, ellerimi yıkar, sonra havluları koyarım."],"dogru":3,"aciklama":"Banyoda kirlenen eldivenle temiz havluya dokunmak mikroorganizmaları taşır. Eldiven çıkarıldıktan sonra eller de yıkanır; yalnız eldiven çıkarmak yetmez."},{"id":"os-1-s15","tur":"senaryo","durum":"Ağustos, saat 15.00. Havuz başındaki restoranda öğle servisini bitirdin; gömleğin terden ıslandı. Yarım saat sonra yeniden konukların arasında olacaksın. Dolabında yedek gömleğin ve deodorantın var; personel duşu açık.","soru":"Ne yaparsın?","secenekler":["Duş alır, deodorant sürer, yedek gömleğimi giyerim.","Duş alır, deodorant sürer, terli gömleğimi giymeye devam ederim.","Yüzümü yıkar, terli gömleğimin üstüne deodorant sıkarım.","Gömleğimi güneşte kurutur, aynı gömlekle salona dönerim."],"dogru":0,"aciklama":"Ter kokusu ancak temiz cilt ve temiz kıyafetle giderilir; deodorant temiz cilde uygulanır. Terli gömleği yeniden giymek duşun etkisini boşa çıkarır."},{"id":"os-1-s16","tur":"senaryo","durum":"Sezonun en yoğun haftası. Akşam servisinden sonra saat 23.30’da lojmana döndün; ayakların yorgun ve terli. Yarın sabah 07.00’de kahvaltı servisindesin.","soru":"Hangisi doğru davranıştır?","secenekler":["Ayaklarımı yıkar, parmak aralarını da iyice kurularım.","Ayaklarımı yıkar, yalnız üstlerini kurulayıp yatarım.","Çoraplarımı çıkarıp yatar, ayaklarımı sabah yıkarım.","Ayaklarımı yıkar, kurulamadan çorabımı giyip yatarım."],"dogru":0,"aciklama":"Terli ve yorgun ayakta ilk iş yıkamak, ikincisi parmak aralarını kurulamaktır; nem kalırsa mantar çoğalır. Yıkamayı sabaha bırakmak ya da yarım kurulamak sorunu çözmez."},{"id":"os-1-s21","tur":"coktan-secmeli","soru":"Ağız gargarasıyla ilgili hangisi yanlıştır?","secenekler":["Ağızdaki bakterileri azaltır.","Ağız kokusunu önlemeye yardım eder.","Fırçalamadan sonra, en son kullanılır.","Diş fırçalamanın yerini tutar."],"dogru":3,"aciklama":"Gargara fırçalamanın ve dil temizliğinin yerine geçmez, onları tamamlar; tek başına yeterli değildir. Bu yüzden uygulamada en son yapılır."},{"id":"os-1-s22","tur":"coktan-secmeli","soru":"Hangisi saç bakımı aşamalarının doğru sırasıdır?","secenekler":["Islatma, şampuan, durulama, saç kremi, kurulama, tarama","Islatma, saç kremi, şampuan, durulama, tarama, kurulama","Islatma, şampuan, saç kremi, durulama, tarama, kurulama","Şampuan, ıslatma, durulama, saç kremi, kurulama, tarama"],"dogru":0,"aciklama":"Şampuan ıslak saça uygulanıp durulanır, krem ondan sonra gelir; saç kurulandıktan sonra taranır. Islak ve kırılgan saçı taramak telleri koparabilir."},{"id":"os-1-s23","tur":"coktan-secmeli","soru":"Şampuanla yıkanıp durulanan saçında saç kremini doğru kullanan kişi ne yapar?","secenekler":["Saç derisine bolca sürer, durulamadan bırakır.","Saç derisine sürüp uzun süre masaj yaparak bekletir.","Saç uçlarına sürer, kısa süre bekletir ve durular.","Kuru saça sürer, sonra şampuanla yıkar."],"dogru":2,"aciklama":"Krem saç uçlarını yumuşatır ve taramayı kolaylaştırır; uçlara sürülür, kısa süre beklenir ve durulanır. Şampuandan önce sürülürse yıkamada gider."},{"id":"os-1-s24","tur":"coktan-secmeli","soru":"Hangi alışkanlığın saç tellerinin kırılmasına yol açması beklenir?","secenekler":["Saçı yumuşak havluyla sıkıştırarak kurulamak","Saç uçlarına krem sürüp bir süre bekleyip durulamak","Islak saçı havluyla sertçe ovup yüksek ısıda kurutmak","Saç tipine uygun şampuan seçip kullanmak"],"dogru":2,"aciklama":"Sert kurulama ve yüksek ısı saç tellerini zayıflatıp koparır. Yumuşak havlu, krem ve uygun şampuan saçı korur."},{"id":"os-1-s25","tur":"coktan-secmeli","soru":"Karma ciltte yağlanma en çok yüzün hangi bölgesinde görülür?","secenekler":["T bölgesinde (alın, burun, çene)","Yanakların dış kısmında","Göz çevresindeki ince deride","Şakaklarda ve kulak önünde"],"dogru":0,"aciklama":"T bölgesi alın, burun ve çeneyi kapsar ve yağlanma en çok orada görülür; yanaklar karma ciltte genellikle kuru kalır."},{"id":"os-1-s26","tur":"coktan-secmeli","soru":"Yüzünün tamamı gün ortasında parlayan, gözenekleri geniş ve sivilceye yatkın biri hangi cilt tipindedir?","secenekler":["Karma cilt","Hassas cilt","Kuru cilt","Yağlı cilt"],"dogru":3,"aciklama":"Parlamanın ve geniş gözeneklerin yüzün tamamında görüldüğü cilt yağlıdır. Karma ciltte yalnız T bölgesi yağlıdır, yanaklar kurudur."},{"id":"os-1-s27","tur":"coktan-secmeli","soru":"Hangisi cilt bakımı adımlarının doğru sırasıdır?","secenekler":["Tonik, temizleme, maske, peeling, nemlendirme","Temizleme, peeling, tonik, nemlendirme, maske","Temizleme, tonik, peeling, maske, nemlendirme","Nemlendirme, temizleme, tonik, peeling, maske"],"dogru":2,"aciklama":"Cilt önce temizlenir, tonik gözenekleri dengeler, peeling ve maske derin bakım yapar; nemlendirici son adım olarak nemi hapseder."},{"id":"os-1-s28","tur":"coktan-secmeli","soru":"Tıraşla ilgili hangisi yanlıştır?","secenekler":["Cilt önce ılık suyla yumuşatılır.","Tıraş kıl çıkış yönünde yapılır.","Tıraştan sonra cildi yatıştıran losyon sürülür.","Tıraş olurken jilet ekip arkadaşıyla paylaşılabilir."],"dogru":3,"aciklama":"Jilet kişiye özeldir; paylaşılırsa kesikler yoluyla enfeksiyon bulaşabilir. Diğer üçü doğru tıraş uygulamasının adımlarıdır."},{"id":"os-1-s29","tur":"coktan-secmeli","soru":"Hangi ikili, vücudun büyümesi ve onarımı için gerekli besin ögesinin başlıca kaynağıdır?","secenekler":["Ekmek ve pirinç","Yumurta ve mercimek","Portakal ve biber","Zeytin ve ceviz"],"dogru":1,"aciklama":"Yumurta ve mercimek protein kaynağıdır; protein büyüme ve onarım içindir. Ekmek ve pirinç karbonhidrat, portakal ve biber vitamin, zeytin ve ceviz yağ kaynağıdır."},{"id":"os-1-s30","tur":"coktan-secmeli","soru":"Hangisi sağlıklı yaşamın beş ögesinden biri değildir?","secenekler":["Yeterli su içmek","Düzenli uyumak","Pahalı bakım ürünleri kullanmak","Zararlı alışkanlıklardan kaçınmak"],"dogru":2,"aciklama":"Beş öge dengeli beslenme, yeterli su, düzenli fiziksel aktivite, düzenli uyku ve zararlı alışkanlıklardan kaçınmaktır. Bakım ürününün fiyatı bu listede yoktur."},{"id":"os-1-s31","tur":"dogru-yanlis","soru":"Şampuanlarda köpürtücü olarak kullanılan madde parabendir.","secenekler":["Doğru","Yanlış"],"dogru":1,"aciklama":"Köpürtücü madde sülfattır. Paraben ise ürünün bozulmasını geciktiren ve mikroorganizma çoğalmasını önleyen koruyucu maddedir."},{"id":"os-1-s32","tur":"dogru-yanlis","soru":"Peeling haftalık uygulanır; ölü deriyi temizleyerek cildin yenilenmesine yardım eder.","secenekler":["Doğru","Yanlış"],"dogru":0,"aciklama":"Peeling ölü deriyi uzaklaştırır; her gün uygulanırsa cildi tahriş edeceğinden haftalık yapılır."},{"id":"os-1-s33","tur":"senaryo","durum":"Öğle yemeğinde sarımsaklı bir yemek yedin; on dakika sonra resepsiyonda konuklarla yüz yüze giriş işlemi yapacaksın. Dolabında diş fırçan, macunun, dil temizleyicin ve gargaran var.","soru":"Ne yaparsın?","secenekler":["Dişlerimi fırçalar, dilimi temizler, en son gargara kullanırım.","Vakit az olduğu için yalnız gargarayla ağzımı çalkalarım.","Dişlerimi fırçalar, dilimi temizlemeden gargara yapıp bankoya dönerim.","Bir sakız çiğner, konuk bankoya gelince çıkarıp atarım."],"dogru":0,"aciklama":"Ağız kokusu bakterilerden gelir; fırça, dil temizleyici ve gargara birlikte etkilidir. Gargara tek başına yeterli değildir, sakız da kokuyu yalnız örter."},{"id":"os-1-s34","tur":"senaryo","durum":"Sabah 07.30, personel soyunma odası. Vardiyaya on dakika var. Arkadaşın tarağını evde unutmuş; sabah toplantısına dağınık saçla çıkmak istemiyor ve senden tarağını istiyor.","soru":"Hangisi doğru davranıştır?","secenekler":["Kişisel olduğunu nazikçe söyler, ona yedek tarak bulmasında yardım ederim.","Tarağımı veririm, geri aldığımda sıcak suyla ve sabunla iyice yıkarım.","Tarağımı veririm; saçı temiz göründüğü için bir sakınca görmem.","Duymamış gibi yapar, hazırlığımı bitirip arkadaşımı odada bırakarak çıkarım."],"dogru":0,"aciklama":"Tarak kişisel bakım ürünüdür; paylaşılırsa kepek ve mikroorganizma bulaşabilir. Kişisel eşya ödünç verilmez; sonradan yıkamak paylaşımı doğru yapmaz. Arkadaşı kırmadan reddetmek ve çözüm bulmak hem hijyenik hem nazik davranıştır."},{"id":"os-1-s35","tur":"senaryo","durum":"Akşam servisi, saat 20.00. Restoranda servis personelisin. Alnındaki sivilce kaşındı ve farkında olmadan elinle dokundun. Mutfak geçidinin yanında el yıkama lavabosu var; iki tabak seni bekliyor.","soru":"İlk adımın ne olur?","secenekler":["Avucuma el dezenfektanı sıkar, tabakları alıp götürürüm.","Elimi önlüğüme silip tabakları alıp götürürüm.","Tabakları götürür, ilk boş anımda ellerimi yıkarım.","Lavaboda ellerimi su ve sabunla yıkar, sonra tabakları götürürüm."],"dogru":3,"aciklama":"Cilde ve yüze dokunan el mikroorganizma taşır; yemeğe değmeden önce yıkanmalıdır. Lavabo varken dezenfektan, su ve sabunun yerini tutmaz."},{"id":"os-1-s36","tur":"senaryo","durum":"Saat 11.00, oda görevlisi olarak 214 numaralı odayı hazırlıyorsun. Banyodaki musluk kapalıyken bile damlatıyor. Konuk havlularını askıya asmış; banyodaki kart, askıya asılan havlunun yeniden kullanılacağını söylüyor.","soru":"Ne yaparsın?","secenekler":["Musluğu sıkıca kapatmayı dener, kimseye söylemeden işime devam ederim.","Musluğu teknik servise bildirir, askıdaki havluları yerinde bırakırım.","Musluğu bildirir, konuk memnun kalsın diye askıdaki havluları yenileriyle değiştiririm.","Musluğu konuk fark edip resepsiyona söyler diye düşünüp bildirmem."],"dogru":1,"aciklama":"Damlayan musluk su israfıdır ve teknik servise bildirilir. Askıdaki havlu konuğun yeniden kullanma isteğidir; değiştirmek hem su hem deterjan israfına yol açar."},{"id":"os-1-s41","tur":"coktan-secmeli","soru":"Havuz başındaki görevli tişört, resepsiyondaki görevli ceket giyiyor. İş kıyafetinin hangi özelliği bu farkı açıklar?","secenekler":["Bedene uygun olması","Düzenli ve ütülü olması","Temiz olması","Yapılan işe uygun olması"],"dogru":3,"aciklama":"İş kıyafeti görev yapılan alana ve mesleğin kurallarına göre seçilir. Bedene uygunluk, ütü ve temizlik her iki kıyafet için de geçerlidir, farkı açıklamaz."},{"id":"os-1-s42","tur":"coktan-secmeli","soru":"Hangisi iş kıyafetinde aranan temel özelliklerden biri değildir?","secenekler":["Temiz ve lekesiz olması","Düzenli ve ütülü olması","Son modaya uygun olması","Bedene uygun olması"],"dogru":2,"aciklama":"İş kıyafeti moda için değil, mesleki kimliği ve kurumu yansıtmak için giyilir; temiz, düzenli ve işe uygun olması aranır."},{"id":"os-1-s43","tur":"coktan-secmeli","soru":"Cuma akşamı haftanın gömleklerinin bakımını yapacak biri için hangisi doğru sıradır?","secenekler":["Yıkama, ayırma, ütüleme, kurutma, saklama","Ayırma, yıkama, kurutma, ütüleme, saklama","Ayırma, ütüleme, yıkama, saklama, kurutma","Yıkama, kurutma, saklama, ayırma, ütüleme"],"dogru":1,"aciklama":"Önce kirli kıyafetler ayrılır, uygun programda yıkanıp kurutulur, ütülenir ve temiz saklanır. Yıkamadan önce ayırmak renk ve kumaş zararını önler."},{"id":"os-1-s44","tur":"coktan-secmeli","soru":"Hangisi kişisel görünüm standartlarına uygun değildir?","secenekler":["Uzun saçı ensede düzgünce toplamak","Servis sırasında şıngırdayan bilezik takmak","Tırnakları kısa ve temiz tutmak","Sade bir kol saati kullanmak"],"dogru":1,"aciklama":"Takılar sade olmalıdır; şıngırdayan bilezik hem dikkat dağıtır hem servis sırasında tehlike yaratır. Diğer üçü standartlara uygundur."},{"id":"os-1-s45","tur":"coktan-secmeli","soru":"Konuk garsona “Teşekkür ederim, Elif Hanım” diyor. Konuğun çalışanı adıyla tanımasını hangi parça sağlamıştır?","secenekler":["Önlük","Bone","Yaka kartı","Kaymaz iş ayakkabısı"],"dogru":2,"aciklama":"Yaka kartı çalışanın adını ve görevini gösterir. Önlük kıyafeti korur, bone saçı, kaymaz ayakkabı da kaymayı önler; hiçbiri ismi göstermez."},{"id":"os-1-s46","tur":"dogru-yanlis","soru":"Kat görevlisi ile aşçının farklı iş kıyafeti giymesi, kıyafetin yapılan işe uygun seçilmesi gerektiğindendir.","secenekler":["Doğru","Yanlış"],"dogru":0,"aciklama":"İş kıyafeti görev alanına ve mesleğin gereklerine göre belirlenir; bu yüzden her bölümün kıyafeti farklı olabilir."},{"id":"os-1-s47","tur":"coktan-secmeli","soru":"İşe başlayan bir stajyere insan kaynakları bir sayfa veriyor: hangi bölüm ne giyer, ayakkabı rengi ne olur, saç nasıl toplanır. Bu sayfa hangi kavramı karşılar?","secenekler":["Meslek ahlakı","Kıyafet kuralları","Görünüm kontrolü","Kişisel koruyucu donanım"],"dogru":1,"aciklama":"Kıyafet kuralları, işletmenin çalışanlardan beklediği giyim ve görünüm standartlarıdır (İngilizcesi dress code). Görünüm kontrolü ise çalışanın kendini aynada gözden geçirmesidir."},{"id":"os-1-s48","tur":"coktan-secmeli","soru":"Mutfakta tezgâh önce deterjanlı suyla silinip sonra dezenfektan uygulanıyor. Dezenfektanın görevi nedir?","secenekler":["Yüzeydeki mikroorganizmaları büyük ölçüde yok etmek","Yüzeydeki tozu ve görünen lekeyi uzaklaştırmak","Çiğ ve pişmiş gıdaların yan yana saklanmasını sağlamak","Çalışanların hastalık taşıyıp taşımadığını anlamak"],"dogru":0,"aciklama":"Deterjan görünen kiri alır; dezenfeksiyon mikroorganizmaları büyük ölçüde yok eder. Çalışanın taşıyıcı olup olmadığına portör muayenesi bakar."},{"id":"os-1-s49","tur":"coktan-secmeli","soru":"Mutfakta tehlikeleri belirleyip soğuk hava deposu sıcaklığı gibi kritik noktaları düzenli ölçen sistem hangisidir?","secenekler":["Sanitasyon","Ergonomi","Dezenfeksiyon","HACCP"],"dogru":3,"aciklama":"HACCP üretimdeki tehlikeleri belirler ve kritik noktaları kontrol altında tutar. Sanitasyon ortamı güvenli hâle getirmektir; sıcaklık çizelgesi tutmak HACCP’ın işidir."},{"id":"os-1-s50","tur":"coktan-secmeli","soru":"Vücut mekaniklerine uygun çalışan bir kat görevlisi gün sonunda neden daha az yorulur?","secenekler":["Aynı işi kasları ve eklemleri en az zorlayarak, daha az güçle yapar.","Daha çok kas çalıştırdığı için vücudu zamanla güçlenir ve yorgunluk hissetmez.","Hareketleri hızlandırdığı için işi daha kısa sürede bitirir.","Daha az oda hazırladığı için kasları dinlenmiş olur."],"dogru":0,"aciklama":"Vücut mekaniği, kasları ve eklemleri en az zorlayacak doğru kullanım demektir; enerji verimli harcanır. Hız ya da az iş yorgunluğun nedeni değildir."},{"id":"os-1-s51","tur":"coktan-secmeli","soru":"Lobide konuk bekleyen görevlilerden hangisi doğru ayakta durur?","secenekler":["Omuzları düşük, sütuna yaslanıp ağırlığı gövdesine vermiş olan","Başı dik, omuzları geride, ağırlığı iki ayağına dengeli vermiş olan","Başı öne eğik, ağırlığı hep tek ayağına vermiş olan","Gövdesini geriye yaslayıp ağırlığı topuklarına vermiş olan"],"dogru":1,"aciklama":"Doğru ayakta durmada baş, omuz ve omurga aynı hizadadır ve ağırlık iki ayağa dağılır. Yaslanmak ve tek ayağa yüklenmek duruşu bozar, beli yorar."},{"id":"os-1-s52","tur":"coktan-secmeli","soru":"Rezervasyon ofisinde ekran başındaki görevlilerden hangisi doğru oturur?","secenekler":["Sandalyenin ucunda, gövdesi ekrana doğru eğik oturan","Bacak bacak üstüne atmış, beli boşta oturan","Ayaklarını sandalyenin altında toplamış, sırtı kamburlaşmış oturan","Sırtı dik, beli arkalığa dayalı, iki ayağı yere tam basan"],"dogru":3,"aciklama":"Doğru oturmada sırt dik, bel destekli ve ayaklar yere tam basar. Sandalyenin ucunda oturmak, bacak bacak üstüne atmak ve kamburlaşmak omurgayı zorlar."},{"id":"os-1-s53","tur":"coktan-secmeli","soru":"Dizlerini bükmeden belden eğilerek ağır valiz kaldırmak neden tehlikelidir?","secenekler":["Bacak kasları gereğinden fazla zorlanır.","Yük omuz eklemlerine binip kollar hemen uyuşur.","Dizler bükülmediği için eklemler hemen aşınır.","Yükün bütün ağırlığı bele biner."],"dogru":3,"aciklama":"Belden eğilince bacak kasları devre dışı kalır ve yük omurgaya biner; en yaygın ve en tehlikeli kaldırma hatalarından biridir. Doğrusu dizleri bükmek ve beli dik tutmaktır."},{"id":"os-1-s54","tur":"coktan-secmeli","soru":"Kat arabasından aldığı çarşaf destesiyle yatağa dönecek bir görevli nasıl dönmelidir?","secenekler":["Ayaklarını sabit tutup yalnız belinden dönmelidir.","Ayaklarıyla adım atıp bütün vücuduyla dönmelidir.","Desteyi öne uzatıp yalnız omuzlarını çevirmelidir.","Hızını kesmeden tek hamlede dönmelidir."],"dogru":1,"aciklama":"Elde yük varken beli burmak omurgayı zorlar; ayaklarla adım atıp bütün vücutla dönmek yükü dengede tutar."},{"id":"os-1-s55","tur":"coktan-secmeli","soru":"Sırt egzersizinden önce hafif tempolu yürüyüş ve kol çevirme hareketleri yapan biri hangisini yapmaktadır?","secenekler":["Esneme hareketi","Güçlendirme hareketi","Isınma","Ara verip hareket etme"],"dogru":2,"aciklama":"Isınma, bedeni harekete hazırlayan kısa ve hafif hareketlerdir. Esneme kası yavaşça uzatır; güçlendirme kası çalıştırıp dayanıklı kılar."},{"id":"os-1-s56","tur":"dogru-yanlis","soru":"Kalabalık bir giriş gününde saatlerce kıpırdamadan durmak, kasları dinlendirdiği için yorgunluğu azaltır.","secenekler":["Doğru","Yanlış"],"dogru":1,"aciklama":"Uzun süre aynı konumda kalan kas yorulur ve gerilir; belirli aralıklarla konum değiştirmek ve birkaç adım atmak kasları rahatlatır."},{"id":"os-1-s57","tur":"senaryo","durum":"Saat 07.45, soyunma odası. Vardiyan on beş dakika sonra resepsiyonda başlıyor. Gömleğini giyerken ön tarafında dünden kalma, çıkmamış bir leke fark ediyorsun. Dolabında yedek gömleğin var.","soru":"Ne yaparsın?","secenekler":["Ceketimi ilikler, lekeyi vardiya boyunca ceketin altında saklarım.","Dolabımdaki yedek gömleği giyer, lekeli olanı yıkanmaya ayırırım.","Lekeyi ıslak mendille ovalar, gömlek ıslak da olsa bankoya çıkarım.","Lekeli gömleğimle başlar, vardiya arasında çıkarmayı denerim."],"dogru":1,"aciklama":"Temiz kıyafet kuralı lekeli gömlekle çalışmayı kabul etmez; yedek gömlek tam bunun için vardır. Saklamak ya da ıslak çıkmak profesyonel imajı zedeler."},{"id":"os-1-s58","tur":"senaryo","durum":"Stajının ilk günü, otelin restoranında akşam servisine çıkacaksın. Üniforman tam; ama bileğinde şıngırdayan birkaç bilezik, boynunda uzun bir kolye var. Servise on dakika kaldı.","soru":"Hangisi doğru davranıştır?","secenekler":["Kolyeyi ve bilezikleri çıkarıp dolabıma koyar, salona sade çıkarım.","Kolyeyi yakamın içine sokar, bilezikleri kolumun üst kısmına iterim.","Şefim uyarana kadar bekler, bir şey derse o zaman çıkarırım.","Takıları üniformamın bir parçası sayar, salona onlarla çıkarım."],"dogru":0,"aciklama":"Aksesuar sade olmalıdır; şıngırdayan takı servis sırasında dikkat dağıtır. Gizlemek ya da uyarı beklemek kuralı yerine getirmez, sorumluluk çalışandadır."},{"id":"os-1-s59","tur":"senaryo","durum":"Mutfak stajındasın, saat 11.30. Kesme tahtasında çiğ tavuk doğramayı yeni bitirdin. Şef, öğle servisi için hemen salatalık ve domates doğramanı istiyor.","soru":"İlk adımın ne olur?","secenekler":["Tahtayı ve bıçağı kâğıt havluyla silip sebzeleri hemen doğrarım.","Ellerimi yıkar, temiz bir tahta ve bıçak alıp sebzeleri öyle doğrarım.","Tahtayı ters çevirir, temiz görünen arka yüzünde doğrarım.","Aynı tahtanın boş köşesinde doğramaya başlarım."],"dogru":1,"aciklama":"Çiğ tavuktan sebzeye mikroorganizma geçmesi çapraz bulaşmadır; salatalık pişmeden yenir. Kâğıt havlu mikroorganizmayı gidermez, tahtanın başka yüzü de aynı riski taşır."},{"id":"os-1-s60","tur":"senaryo","durum":"Öğleden sonra 15.00, otelin girişi. Bellboy olarak görevdesin. Taksiden inen konuğun büyük ve ağır valizi kaldırımda, yerde duruyor; konuk seni bekliyor.","soru":"Valizi nasıl kaldırırsın?","secenekler":["Belimden eğilir, valizi tek hamlede çekerim.","Dizlerimi bükmeden kollarımı uzatıp valizi kaldırırım.","Bir elimle sapından tutar, gövdemi yana bükerek kaldırırım.","Çömelir, belimi dik tutar, valizi bedenime yakın tutarak kaldırırım."],"dogru":3,"aciklama":"Doğru kaldırmada dizler bükülür, bel dik kalır ve yük bedene yakın tutulur; böylece yük bacak kaslarına biner. Diğer şıklar yükü beline bindirir."},{"id":"os-1-s61","tur":"senaryo","durum":"Bir kongre günü, saat 11.00. Sabahtan beri salon kapısında ayakta durup katılımcıları karşılıyorsun. Bacakların ağırlaştı, belin gerilmeye başladı. Şu an kapıda kimse yok.","soru":"Ne yaparsın?","secenekler":["Kapı kasasına omzumla yaslanıp ağırlığımı tek ayağıma veririm.","Aynı biçimde hiç kıpırdamadan durmayı sürdürürüm.","Dik durup ağırlığımı iki ayağıma verir, kapı önünde birkaç adım atarım.","Köşede çömelip belimi gevşeterek bir süre otururum."],"dogru":2,"aciklama":"Uzun süre aynı konumda kalmak kası yorar; konumu değiştirmek ve birkaç adım atmak rahatlatır. Kapıyı bırakmadan, duruşu bozmadan yapılabilecek tek çözüm budur."},{"id":"os-1-s62","tur":"senaryo","durum":"Gece 23.00, resepsiyon. Uzun bir vardiyanın sonundasın; dirseklerinle bankoya yaslanmış, başın öne düşmüş duruyorsun. Döner kapıdan içeri bir konuk giriyor ve bankoya doğru yürüyor.","soru":"Hangisi doğru davranıştır?","secenekler":["Yaslandığım yerden yalnız başımı kaldırır, konuğu gülümseyerek selamlarım.","Arkamdaki sandalyeye oturur, konukla oturduğum yerden ilgilenirim.","Doğrulur, başım dik ve omuzlarım rahat, iki ayağımın üstünde karşılarım.","Kollarımı göğsümde bağlar, arkamdaki duvara yaslanarak beklerim."],"dogru":2,"aciklama":"Doğru duruş hem sağlık hem ilk izlenim için önemlidir: baş dik, omuzlar rahat, ağırlık iki ayakta. Yaslanmak ve oturmak konuğa ilgisizlik gösterir."},{"id":"os-1-s63","tur":"coktan-secmeli","soru":"Hangisi kişisel hijyen uygulamasına örnektir?","secenekler":["Tuvaletten sonra elleri su ve sabunla yıkamak","Kahvaltı büfesindeki yiyeceklerin üstünü örtmek","Mutfaktaki tezgâhı silip dezenfektan uygulamak","Koridordaki halının tozunu süpürgeyle almak"],"dogru":0,"aciklama":"Kişisel hijyen kişinin kendi vücuduna yaptığı düzenli bakım ve temizliktir. Büfeyi örtmek ya da tezgâhı dezenfekte etmek ortamın hijyenine girer, kişinin kendi bedenine değil."},{"id":"os-1-s64","tur":"dogru-yanlis","soru":"Hijyen ve sağlıklı yaşam alışkanlıkları kişinin sağlıklı, rahat ve mutlu yaşama düzeyini, yani yaşam kalitesini artırır.","secenekler":["Doğru","Yanlış"],"dogru":0,"aciklama":"Yaşam kalitesi kişinin sağlıklı, rahat ve mutlu yaşama düzeyidir; temizliğine, uykusuna ve beslenmesine özen gösteren kişide bu düzey yükselir."},{"id":"os-1-s65","tur":"coktan-secmeli","soru":"Tuvaletten sonra ellerini yıkamayan bir garson, elindeki mikroorganizmaları ekmek sepetiyle konuğa taşıyor. Bu yolla konukta ortaya çıkabilecek hastalık türü hangisidir?","secenekler":["Kronik hastalık","Enfeksiyon hastalığı","Alerjik reaksiyon","Obezite"],"dogru":1,"aciklama":"Enfeksiyon hastalığı mikroorganizmaların vücuda girip çoğalmasıyla oluşur ve bulaşabilir. Kronik hastalık ise uzun süren, sağlıksız beslenme gibi nedenlerle riski artan hastalıktır."},{"id":"os-1-s66","tur":"coktan-secmeli","soru":"Lojmanda oda arkadaşın tırnak makasını ödünç istiyor. Bu eşyanın ortak kullanılmamasının asıl nedeni hangisidir?","secenekler":["Başka biri kullanınca makasın ağzı çabucak körelir ve artık iyi kesmez.","Kişisel eşya paylaşmak, otelin çalışanlara verdiği kıyafet kurallarına aykırıdır.","Ortak kullanım hastalıkların kişiden kişiye bulaşmasına yol açabilir.","Ortak kullanılan makas tırnakların düz kesilmesini zorlaştırır."],"dogru":2,"aciklama":"Tırnak makası, tarak ve havlu gibi eşyaların ortak kullanımı bulaşıcı hastalıkların kişiden kişiye geçmesine yol açar. Kıyafet kuralları giyim ve görünümle ilgilidir, eşya paylaşımıyla değil."},{"id":"os-1-s67","tur":"coktan-secmeli","soru":"Resepsiyondaki kalem, merdiven tırabzanı ve konuğun uzattığı banknot için ortak olan özellik hangisidir?","secenekler":["Yalnız kat görevlilerinin temizlemekle sorumlu olduğu eşyalardır.","Üzerlerinde mikroorganizma yaşayamayacak maddelerden yapılır.","Konuğun hiç görmediği arka alanda bulunan eşyalardır.","Gün boyu çok kişinin eli değer; dokunduktan sonra eller yıkanır."],"dogru":3,"aciklama":"Bunlar ortak kullanılan yüzeylerdir: pek çok kişinin dokunduğu için mikroorganizma taşır, bu yüzden eller sonrasında yıkanır. Temiz görünmeleri mikroorganizma olmadığı anlamına gelmez."},{"id":"os-1-s68","tur":"coktan-secmeli","soru":"Konuk döner kapıdan girer girmez, daha tek kelime konuşmadan resepsiyon görevlisinin saçına ve yakasına bakıp otel hakkında bir karar veriyor. Bu durum hangi kavramla açıklanır?","secenekler":["Konuğun ilk izlenimi","Otelin kurumsal itibarı","Çalışanın mesleki yeterliliği","Konuğun memnuniyeti"],"dogru":0,"aciklama":"İlk izlenim, konuğun çalışanı ilk gördüğü anda oluşan düşüncedir. Kurumsal itibar ise otelin zamanla toplum gözünde kazandığı saygınlıktır, tek bir bakışta oluşmaz."},{"id":"os-1-s69","tur":"dogru-yanlis","soru":"Çalışanın temizliği ve görünümü konuk memnuniyetini etkilemez; konuk yalnız aldığı hizmetin hızına bakar.","secenekler":["Doğru","Yanlış"],"dogru":1,"aciklama":"Konuk memnuniyeti, konuğun aldığı hizmetten hoşnut kalmasıdır ve çalışanın temizliği ile görünümü bunu doğrudan etkiler."},{"id":"os-1-s70","tur":"coktan-secmeli","soru":"Dolabının arkasında unutulmuş bir krem buldun. Sürmeden önce ne yaparsın?","secenekler":["Kokusu bozulmamışsa tarihe bakmadan hemen kullanırım.","Ambalajdaki son kullanma tarihine bakar, geçmişse kullanmam.","Önce yüzümün tamamına sürüp bir tepki olup olmadığını beklerim.","Kapağı hep kapalı kaldığı için bozulmadığını kabul ederim."],"dogru":1,"aciklama":"Kişisel bakım ürünlerinde son kullanma tarihi kontrol edilir; tarihi geçmiş ürün kullanılmaz. Koku ya da kapalı kapak ürünün güvenli olduğunu göstermez."},{"id":"os-1-s71","tur":"coktan-secmeli","soru":"Yeni aldığı bakım ürününü sürdükten sonra cildi kızaran bir çalışan ne yapmalıdır?","secenekler":["Cildi alışsın diye ürünü birkaç gün daha kullanmaya devam eder.","Kızarıklığı kapatmak için üstüne başka bir krem sürer.","Ürünü bırakır, sonraki ürünlerde içindekiler bölümünü okur.","Kendisine uymadığı için ürünü bir ekip arkadaşına verir."],"dogru":2,"aciklama":"Cilde zarar veren ürün zararlı kimyasal içerebilir; kullanım bırakılır ve sonraki ürünlerde içindekiler okunur. Kullanmaya devam etmek cildi daha çok tahriş eder."},{"id":"os-1-s72","tur":"coktan-secmeli","soru":"“Biyolojik olarak parçalanabilir” ürün ile “geri dönüştürülebilir” ambalaj arasındaki fark hangisidir?","secenekler":["Birincisi yalnız bir kez kullanılır; ikincisi hiçbir zaman çöpe atılmaz.","Birincisi yalnız plastikten yapılır; ikincisi yalnız camdan yapılır.","İkisi tamamen aynı şeyi anlatır; yalnızca ürünün üzerindeki adları farklıdır.","Birincisi doğada kendiliğinden ayrışır; ikincisi toplanıp yeniden işlenir."],"dogru":3,"aciklama":"Biyolojik olarak parçalanabilir ürün doğada kendiliğinden çözünür; geri dönüştürülebilir ambalaj ise toplandıktan sonra yeniden işlenir. İkisi de çevreyi korur ama yöntemleri farklıdır."},{"id":"os-1-s73","tur":"dogru-yanlis","soru":"Bir kez kullanılıp atılan plastik bardak ve çatallar plastik atığı artırarak çevre kirliliğine yol açar.","secenekler":["Doğru","Yanlış"],"dogru":0,"aciklama":"Tek kullanımlık ürünler bir kez kullanılıp çöpe gider; bu da plastik atık ve çevre kirliliği yaratır."},{"id":"os-1-s74","tur":"coktan-secmeli","soru":"Doğru el yıkamada elleri sabunladıktan hemen sonra hangi basamak gelir?","secenekler":["Parmak arası ve tırnakların ovulması","Ellerin kâğıt havluyla iyice kurulanması","Ellerin bol suyla durulanması","Ellerin ılık suyla ıslatılması"],"dogru":0,"aciklama":"Sıra ıslatma, sabunlama, parmak araları ve tırnakların temizlenmesi, en az 20 saniye yıkama, durulama ve kurulamadır. Durulama, parmak araları ve tırnaklar temizlendikten sonra gelir."},{"id":"os-1-s75","tur":"coktan-secmeli","soru":"Gün boyu ayakta çalışan bir servis görevlisi için hangisi doğru ayak bakımıdır?","secenekler":["Ayakları yıkayıp parmak araları nemliyken hemen çorabını giymek","Her gün yıkamak, parmak aralarını kurulamak, çorabı değiştirmek","Terleyen çorabı akşam kurutup ertesi gün yeniden giymek","Ayaklarını haftada bir yıkayıp çorabını iki günde bir yenisiyle değiştirmek"],"dogru":1,"aciklama":"Ayak bakımı ayakların her gün yıkanması, parmak aralarının iyi kurulanması ve çorabın her gün değiştirilmesidir. Nemli bırakılan parmak araları mantar enfeksiyonuna zemin hazırlar."},{"id":"os-1-s76","tur":"dogru-yanlis","soru":"Ağız ve diş bakımı için dişleri günde bir kez fırçalamak yeterlidir.","secenekler":["Doğru","Yanlış"],"dogru":1,"aciklama":"Dişler günde en az iki kez fırçalanır; buna diş ipi ve dil temizliği de eklenir."},{"id":"os-1-s77","tur":"coktan-secmeli","soru":"Akşam dişini fırçalamadan uyuyan biri, sabah dilini dişlerinde gezdirince kaygan bir tabaka hissediyor. Bu tabaka nedir?","secenekler":["Mine","Florür","Plak","Diş eti"],"dogru":2,"aciklama":"Plak, diş yüzeyinde biriken ve bakteri içeren yapışkan tabakadır; fırça ve diş ipiyle temizlenir. Mine ise dişin kendi sert dış tabakasıdır, sonradan birikmez."},{"id":"os-1-s78","tur":"coktan-secmeli","soru":"Dişini fırçalarken lavaboda sık sık kan gören biri ne yapmalıdır?","secenekler":["Kanama durana kadar dişlerini fırçalamayı bırakmalıdır.","Daha iyi temizlesin diye sert kıllı fırçaya geçmelidir.","Fırçayı bırakıp yalnız ağız gargarası kullanmalıdır.","Kanamayı geçiştirmeden bir diş hekimine görünmelidir."],"dogru":3,"aciklama":"Diş eti kanaması diş eti hastalığının belirtisidir; geçiştirilmez, diş hekimine gidilir. Sert fırça diş etini daha çok zorlar, gargara da fırçanın yerini tutmaz."},{"id":"os-1-s79","tur":"coktan-secmeli","soru":"Personel yurdunda kalan bir stajyer diş fırçasını nasıl saklamalıdır?","secenekler":["Yıkayıp ayrı ve kuru bir fırça kabında bekletmeli","Islakken kapaklı bir kutuya koyup kapağını kapatmalı","Arkadaşlarının fırçalarıyla aynı bardakta tutmalı","Lavabonun nemli kenarına yatırıp öylece bırakmalı"],"dogru":0,"aciklama":"Kullanılmış fırçada bakteri üremesin diye fırça nemden uzak, temiz ve kuru bir ortamda, kendi kabında saklanır. Kapaklı ıslak kutu nemi içeride tutar."},{"id":"os-1-s80","tur":"dogru-yanlis","soru":"Saç tellerinin normalden fazla dökülmesinin nedenlerinden biri özensiz bakımdır.","secenekler":["Doğru","Yanlış"],"dogru":0,"aciklama":"Saç dökülmesi saç tellerinin normalden fazla dökülmesidir ve özensiz bakım bunun nedenlerinden biridir."},{"id":"os-1-s81","tur":"coktan-secmeli","soru":"Ne gün ortasında parlayan ne de yıkayınca gerilen, dengeli ve canlı görünen bir cilt hangi tiptedir?","secenekler":["Karma cilt","Normal cilt","Hassas cilt","Kuru cilt"],"dogru":1,"aciklama":"Normal cilt dengeli ve sorunsuzdur. Karma ciltte ise T bölgesi yağlı, yanaklar kurudur; yani cildin bir kısmı parlar."},{"id":"os-1-s82","tur":"coktan-secmeli","soru":"Yeni bir deodorant deneyen stajyerin koltuk altı kısa süre sonra kızarıp kaşınıyor. Bu durum hangi kavramla açıklanır?","secenekler":["Mantar enfeksiyonu","Pullanma","Alerjik reaksiyon","Batık"],"dogru":2,"aciklama":"Alerjik reaksiyon, vücudun bir maddeye kızarıklık, kaşıntı ya da şişlikle aşırı tepki vermesidir. Mantar enfeksiyonu ise yeni bir ürünle değil, nemli kalan bölgede zamanla gelişir."},{"id":"os-1-s83","tur":"coktan-secmeli","soru":"Tıraştan birkaç gün sonra boynunda kırmızı, ağrılı küçük kabarcıklar çıkan birinde en olası durum hangisidir?","secenekler":["Pullanma; cilt nemlendirilmediği için kuruyup dökülmüştür.","Mantar enfeksiyonu; cilt uzun süre nemli kalmıştır.","Ölü deri; cildin üst katmanındaki hücreler orada birikmiştir.","Batık; kıl yanlış tıraş yüzünden deri altına uzamıştır."],"dogru":3,"aciklama":"Batık, kılın deri altına doğru uzamasıdır ve yanlış tıraş yöntemiyle oluşur. Pullanma ise kuru ciltte görülen ince, beyaz parçalardır; ağrılı kabarcık yapmaz."},{"id":"os-1-s84","tur":"coktan-secmeli","soru":"Sezonun en yoğun haftasında öğün atlayan ve az uyuyan bir çalışan, ekipte dolaşan soğuk algınlığına daha kolay yakalanıyor. Bunun nedeni hangisidir?","secenekler":["Sağlıksız beslenmeyle bağışıklık sistemi zayıflamıştır.","Fazla su içmesi vücut direncini düşürmüştür.","Protein aldığı için kasları hastalığa açık hâle gelmiştir.","Kişisel bakım ürünlerini hiç kimseyle paylaşmamıştır."],"dogru":0,"aciklama":"Bağışıklık sistemi vücudu hastalıklara karşı korur ve sağlıksız beslenmeyle zayıflar. Su ve protein ise sağlıklı yaşamın parçalarıdır, direnci düşürmez."},{"id":"os-1-s85","tur":"dogru-yanlis","soru":"Yıllarca her gün kızartma ve şekerli içecekle beslenip hiç hareket etmemek obeziteye yol açabilir.","secenekler":["Doğru","Yanlış"],"dogru":0,"aciklama":"Obezite vücutta aşırı yağ birikmesidir ve sağlıksız beslenmenin sonuçlarındandır; hareketsizlik de riski artırır."},{"id":"os-1-s86","tur":"coktan-secmeli","soru":"Bir kişinin beslenme, uyku ve hareket gibi günlük alışkanlıklarının bütününe ne ad verilir?","secenekler":["Yaşam kalitesi","Yaşam tarzı","Fiziksel aktivite","Beslenme"],"dogru":1,"aciklama":"Yaşam tarzı günlük alışkanlıkların bütünüdür. Yaşam kalitesi ise bu alışkanlıkların sonucunda ulaşılan sağlıklı, rahat ve mutlu yaşama düzeyidir."},{"id":"os-1-s87","tur":"coktan-secmeli","soru":"Hangisi yeterli su tüketimi alışkanlığına uygundur?","secenekler":["Gün boyu hiç içmeyip akşam bir kerede çok su içmek","Susuzluğu yalnız şekerli ve gazlı içeceklerle gidermek","Suyu gün içine yayarak, vardiya aralarında da içmek","Yalnız yemek yerken birkaç yudum su içmekle yetinmek"],"dogru":2,"aciklama":"Yeterli su tüketimi, vücudun işleyişi için suyun gün içine yayılarak içilmesidir. Bir kerede çok su içmek gün boyunca vücudun ihtiyacını karşılamaz."},{"id":"os-1-s88","tur":"coktan-secmeli","soru":"Hangisi su verimliliğine uygun bir davranıştır?","secenekler":["Elleri sabunlarken suyu açık bırakmak","Damlatan musluğu kimseye bildirmemek","Bulaşığı akan suyun altında tek tek yıkamak","Dişleri fırçalarken musluğu kapalı tutmak"],"dogru":3,"aciklama":"Su verimliliği, suyu ihtiyaç kadar ve israf etmeden kullanmaktır. Sabunlarken suyu açık bırakmak ya da damlatan musluğu bildirmemek suyu boşa harcar."},{"id":"os-1-s89","tur":"coktan-secmeli","soru":"Yaz sezonu için bir otelin mutfağına başvuran aday, gıda ve konaklama çalışanı olarak aldığı eğitimi başvuru dosyasında hangi belgeyle gösterir?","secenekler":["Hijyen eğitimi belgesi","HACCP çizelgesi","Yaka kartı","Kıyafet kuralları sayfası"],"dogru":0,"aciklama":"Hijyen eğitimi belgesi, gıda ve konaklama çalışanlarının hijyen eğitimi aldığını gösterir. HACCP çizelgesi ise mutfakta kritik noktaların ölçüldüğü kayıttır, kişinin eğitimini göstermez."},{"id":"os-1-s90","tur":"coktan-secmeli","soru":"Nezle olan bir komi ellerini yıkamadan kapı kollarına dokunuyor; birkaç gün içinde ekipten birkaç kişi daha hastalanıyor. Bu örnek, kişisel hijyenin hangisini de etkilediğini gösterir?","secenekler":["Kurumsal imaj","Toplum sağlığı","Mesleki kimlik","Ergonomi"],"dogru":1,"aciklama":"Toplum sağlığı, bir arada yaşayan insanların bütününün sağlık durumudur; bir kişinin hijyen eksikliği başkalarını da hasta edebilir. Kurumsal imaj ise otelin dışarıya yansıyan görüntüsüdür."},{"id":"os-1-s91","tur":"coktan-secmeli","soru":"Okulun uygulama otelinde üniformasını giyen öğrenci, omuzlarının dikleştiğini ve kendini bir otelci gibi hissettiğini fark ediyor. Bu duygu hangi kavramla ilgilidir?","secenekler":["Kurumsal itibar","Kişisel görünüm standartları","Mesleki kimlik","Ergonomi"],"dogru":2,"aciklama":"Mesleki kimlik, kişinin mesleğini ve değerlerini görünüşü ve davranışıyla yansıtmasıdır. Kişisel görünüm standartları ise otelin saç, tırnak, takı gibi konularda koyduğu kurallardır."},{"id":"os-1-s92","tur":"coktan-secmeli","soru":"Üniforması kusursuz ama saçı dağınık, tırnakları kirli bir garsonda iş kıyafetiyle ilgili hangi özellik eksiktir?","secenekler":["Bedene uygun olma","Ütülü ve düzenli olma","İşe uygun olma","Kişisel bakımla uyum"],"dogru":3,"aciklama":"Saç düzeni, tırnak temizliği ve genel görünüm kıyafetle uyumlu olmalıdır. Kıyafetin kendisi kusursuz olduğu için ütü ya da beden sorunu yoktur; eksik olan kişisel bakımdır."},{"id":"os-1-s93","tur":"dogru-yanlis","soru":"İş kıyafeti, hareket rahatlığı sağlasın diye çalışanın bedeninden birkaç beden bol seçilmelidir.","secenekler":["Doğru","Yanlış"],"dogru":1,"aciklama":"İş kıyafeti çalışanın bedenine uygun olur: ne dar ne bol. Paçası yere sürünen ya da kolu bileği örten kıyafet düzensiz görünür."},{"id":"os-1-s94","tur":"coktan-secmeli","soru":"Yakası havlanmış, dirseği incelmiş, rengi solmuş bir ceket için doğru karar hangisidir?","secenekler":["Yıpranmış olduğu için artık işte giyilmemelidir.","Temiz ve ütülü olduğu sürece işte giyilebilir.","Sahibi alıştığı için konuk fark etmez, giyilebilir.","Yalnız yoğun günlerde yedek olarak giyilebilir."],"dogru":0,"aciklama":"Eskiyip yırtılan ya da rengi solan kıyafet işte kullanılmaz. Sahibi alıştığı için fark etmese de konuk ilk bakışta görür."},{"id":"os-1-s95","tur":"coktan-secmeli","soru":"Hangisi otelde konuğun görmediği arka alana örnektir?","secenekler":["Lobi","Çamaşırhane","Restoran salonu","Resepsiyon bankosu"],"dogru":1,"aciklama":"Arka alan konuğun görmediği mutfak, çamaşırhane gibi bölümlerdir. Lobi, restoran ve resepsiyon ise konuğun gördüğü ön alandır."},{"id":"os-1-s96","tur":"coktan-secmeli","soru":"Kat görevlisi toz kaldıran bir temizlik işine başlıyor. Eldiveninin yanında hangi kişisel koruyucu donanımı da kullanmalıdır?","secenekler":["Önlük","Yaka kartı","Maske","Sade bir saat"],"dogru":2,"aciklama":"Kişisel koruyucu donanım çalışanı iş kazası ve hastalıktan korur; toz kaldıran işte maske kullanılır. Önlük yalnız kıyafeti kirden korur, solunan tozu engellemez."},{"id":"os-1-s97","tur":"coktan-secmeli","soru":"Yerdeki valize uzanırken dizin bükülüyor ve bacakların seni yeniden ayağa kaldırıyor. Bükülen yer ile seni kaldıran güç sırasıyla hangisidir?","secenekler":["Kas ve eklem","Omurga ve kas","Eklem ve omurga","Eklem ve kas"],"dogru":3,"aciklama":"Eklemler kemiklerin birleştiği oynak yerlerdir; diz bir eklemdir. Kaslar ise kasılıp gevşeyerek güç üretir, ayağa kaldıran güç bacak kaslarından gelir."},{"id":"os-1-s98","tur":"coktan-secmeli","soru":"Düşmek üzere olan koliyi yakalamak için gövdesini birden çeviren görevlinin belinde bir sızı başlıyor. Bu durum hangi kavramla açıklanır?","secenekler":["Kas ve eklem zorlanması","Kas yorgunluğu","Enerjiyi verimli kullanma","Hareket kısıtlılığı"],"dogru":0,"aciklama":"Kas ve eklem zorlanması, yanlış ya da ani bir hareketle kasa ve ekleme fazla yük binmesidir. Kas yorgunluğu ise uzun süre aynı konumda kalınca yavaş yavaş gelişir."},{"id":"os-1-s99","tur":"dogru-yanlis","soru":"Bir bellboyun bel ağrısı yüzünden işe gelememesi yalnız kendisini etkiler; ekibin işi bundan etkilenmez.","secenekler":["Doğru","Yanlış"],"dogru":1,"aciklama":"Bel ve sırt ağrısıyla işe gelemeyen çalışan hem kendisi çalışamaz hem de ekibi eksik bırakır."},{"id":"os-1-s100","tur":"coktan-secmeli","soru":"Telefona hep başını öne eğerek bakan, sırada kambur oturan bir öğrencinin omuzları yıllar içinde öne doğru yuvarlanıyor. Bu durum hangi kavramla açıklanır?","secenekler":["Kas ve eklem zorlanması","Duruş bozukluğu","Hareket kısıtlılığı","Kas yorgunluğu"],"dogru":1,"aciklama":"Duruş bozukluğu, yanlış durma ve oturma alışkanlıkları yüzünden bedenin zamanla doğal dik biçimini kaybetmesidir. Kas ve eklem zorlanması ise ani bir hareketle bir anda olur."},{"id":"os-1-s101","tur":"coktan-secmeli","soru":"Bellboy valizi bagaj arabasına fırlatmıyor; kavrıyor, kaldırıyor ve yavaşça yerine yerleştiriyor. Bellboy hangi ilkeyi uygulamaktadır?","secenekler":["Ara verip hareket etme","Esneme hareketi","Kontrollü hareket","Isınma"],"dogru":2,"aciklama":"Kontrollü hareket, dengeyi koruyarak, acele etmeden ve ani çıkışlar yapmadan hareket etmektir. Isınma ise egzersizden önce bedeni hazırlayan hafif hareketlerdir."},{"id":"os-1-s102","tur":"coktan-secmeli","soru":"Rafın en ucundaki havluya ulaşmak isteyen kat görevlisi için doğru davranış hangisidir?","secenekler":["Kolunu sonuna kadar uzatıp gövdesini yana bükmek","Parmak uçlarında yükselip havluyu hızla çekmek","Dizlerini bükmeden belinden öne doğru iyice eğilmek","Rafa bir adım yaklaşıp havluyu zorlanmadan almak"],"dogru":3,"aciklama":"Eğilme ve uzanma, dengeyi koruyarak ve zorlanmadan yapılır; uzaktaki eşyaya kol zorlanarak değil, yaklaşılarak ulaşılır. Belden eğilmek bütün yükü bele bindirir."},{"id":"os-1-s103","tur":"dogru-yanlis","soru":"Ağır bir koli, kollar öne uzatılarak gövdeden uzakta taşınırsa bel daha az zorlanır.","secenekler":["Doğru","Yanlış"],"dogru":1,"aciklama":"Yük kollar uzatılmadan, gövdenin hemen önünde ve vücuda yakın tutularak taşınır; uzakta tutulan yük beli daha çok zorlar."},{"id":"os-1-s104","tur":"dogru-yanlis","soru":"Sırt ve bel egzersizleri, omurgayı destekleyen kasları güçlendirmek ve esnetmek için düzenli yapılır.","secenekler":["Doğru","Yanlış"],"dogru":0,"aciklama":"Sırt ve bel egzersizleri omurgayı destekleyen kasları güçlendirir ve esnetir; uzun vardiyalardan sonra bedenin daha rahat çalışmasına yardım eder."}],"siralamalar":[{"id":"os-1-r01","konu":"1.1.4","baslik":"Mikroplara 20 saniye: doğru el yıkama","yonerge":"Doğru el yıkama basamaklarını doğru sıraya koy.","adimlar":["Ellerini su ile ıslat.","Avucuna yeterli miktarda sabun al.","Parmak aralarını, tırnaklarını ve baş parmaklarını ovarak ellerini en az 20 saniye yıka.","Sabunu ellerinden su ile durula.","Ellerini temiz bir havlu ya da kâğıt havluyla kurula."],"aciklama":"Eller önce ıslatılır, sabun uygulanır, parmak araları ve tırnaklar temizlenir; en az 20 saniye yıkanır, sonra durulanıp kurulanır."},{"id":"os-1-r02","konu":"1.1.6","baslik":"Banyodan aynaya: saç bakımının altı aşaması","yonerge":"Doğru saç bakımı aşamalarını doğru sıraya koy.","adimlar":["Saçını ılık suyla tamamen ıslat.","Şampuanı saç derisine nazikçe uygula ve köpürt.","Saçında şampuan kalıntısı kalmayacak biçimde bol suyla durula.","Saç kremini saç uçlarına sür, bir süre bekletip durula.","Saçını temiz bir havluyla ovalamadan nazikçe kurula.","Saçın hafif nemliyken tara ve şekil ver."],"aciklama":"Saç kremi, şampuan bol suyla durulandıktan sonra saç uçlarına sürülür; kurulama nazikçe yapılır, tarama da saç hafif nemliyken gelir."},{"id":"os-1-r03","konu":"1.2.2","baslik":"Üniformanın yolculuğu: kirliden dolaba","yonerge":"İş kıyafetinin bakım basamaklarını doğru sıraya koy.","adimlar":["Kirli kıyafetleri temiz olanlardan ayır.","Kıyafetleri uygun programda yıka.","Kıyafetleri kurut.","Kırışıklıkları ütüyle gider.","Kıyafetleri katlayarak ya da askıya asarak temiz biçimde sakla."],"aciklama":"Kıyafet önce temiz ve kirli diye ayrılır; sonra yıkanır, kurutulur ve ütülenir, temiz biçimde saklama ise en sona kalır."},{"id":"os-1-r04","konu":"1.3.3","baslik":"Ağır valiz: beli koruyarak kaldır","yonerge":"Yerdeki ağır bir valizi güvenle kaldırıp taşıma adımlarını doğru sıraya koy.","adimlar":["Valizin tam karşısına geç.","Dizlerini bükerek çömel.","Belini dik tutarak valizi yerden kaldır.","Valizi vücuduna yakın tutarak, dengeni koruyup taşı.","Valizi kontrollü biçimde yere bırak."],"aciklama":"Yük belden eğilerek değil, dizler bükülüp bel dik tutularak kaldırılır; taşırken vücuda yakın tutulur ve denge korunur, bırakırken de hareket kontrollü yapılır. Böylece yük bele değil bütün vücuda dağılır."}]},{"ders":"otelcilik-seyahat","sinif":9,"unite":2,"baslik":"İletişim Teknikleri","onay":true,"kazanimlar":["Doğru iletişim teknikleri ile çalışma arkadaşları ile olumlu ilişkiler kurar.","Doğru iletişim teknikleri ile beden dilini doğru kullanır.","Toplum içinde nezaket ve görgü kurallarını uygular."],"soz":"Konuk senin ne söylediğini unutur; ona nasıl davrandığını unutmaz.","dersler":[{"baslik":"Otelde Her Şey Bir Mesajdır","ilk":"os-2-001"},{"baslik":"Dört Teknik, Tek Hedef: Anlaşılmak","ilk":"os-2-006"},{"baslik":"Kısa, Açık, Net","ilk":"os-2-011"},{"baslik":"Aynı Söz, Başka Etki","ilk":"os-2-015"},{"baslik":"Konuğu Kaybettiren Hatalar","ilk":"os-2-018"},{"baslik":"“Bilmiyorum, Sonra Gelin”","ilk":"os-2-022"},{"baslik":"Doğru İletişim Ne Kazandırır?","ilk":"os-2-026"},{"baslik":"Sektörün Dili: Konukla Konuşmanın İncelikleri","ilk":"os-2-030"},{"baslik":"Konuk Önce Bedeni Okur","ilk":"os-2-034"},{"baslik":"Gözler ve Yüz Ne Söyler?","ilk":"os-2-039"},{"baslik":"Eller, Duruş ve Aradaki Mesafe","ilk":"os-2-044"},{"baslik":"Küçük Hareket, Büyük Mesaj","ilk":"os-2-049"},{"baslik":"Yüz ve Eller Ne Söylüyor?","ilk":"os-2-114"},{"baslik":"Omurga Ne Anlatır?","ilk":"os-2-120"},{"baslik":"Gülümsemek Her Zaman Doğru mu?","ilk":"os-2-052"},{"baslik":"Kibar Olmak Yeter mi?","ilk":"os-2-061"},{"baslik":"İlk Söz: Günaydın","ilk":"os-2-067"},{"baslik":"Kim Kime Tanıştırılır?","ilk":"os-2-070"},{"baslik":"Eli İlk Kim Uzatır?","ilk":"os-2-074"},{"baslik":"Sesin Gülümsüyor mu?","ilk":"os-2-080"},{"baslik":"“Alo” Demeden Önce","ilk":"os-2-084"},{"baslik":"BÜYÜK HARF BAĞIRIR","ilk":"os-2-088"},{"baslik":"İnternet Unutmaz","ilk":"os-2-094"},{"baslik":"Otelin Sesi Sensin","ilk":"os-2-098"},{"baslik":"Sektörün Dili: Dress Code’dan Courtesy Call’a","ilk":"os-2-102"}],"kavramlar":[{"id":"os-2-001","konu":"2.1","terim":"İletişim","ingilizce":"Communication","tanim":"Duygu, düşünce ve bilgilerin konuşarak, yazarak, beden diliyle ve başka yollarla karşılıklı olarak paylaşılması sürecidir.","ornek":"Sabah 07.00, resepsiyon: gece vardiyasından çıkan görevli “312’nin kliması arızalı, teknik servis dokuzda gelecek” diye not bırakır; sabahçı okur ve “Tamam, konuğa ben haber veririm” der.","sektor":"Programın anahtar kavramlarındandır. İletişim yalnız bilgi aktarmak değildir; mesaj karşı tarafta doğru anlaşıldığında tamamlanır. Otelde iş, bilgi doğru kişiye doğru biçimde ulaştığında yürür.","iliskili":["os-2-002","os-2-003","os-2-006"],"kontrol":null,"cizim":"konusma"},{"id":"os-2-002","konu":"2.1","terim":"İletişim süreci","ingilizce":"Communication process","tanim":"Konuşma, dinleme, anlama ve tepki verme adımlarının birbirine bağlı olarak ilerlediği akıştır.","ornek":"Saat 10.00, kat ofisi: kat şefi “405 ve 407 öncelikli, konuklar 14.00’te geliyor” der; görevli dinler, hangi odaya önce gireceğini anlar ve “Anlaşıldı, önce 405” diye karşılık verir.","sektor":"Adımlardan biri aksarsa iletişim eksik kalır: açık konuşsan da dinlenmediysen, dinlesen de karşılık vermediysen iş bitmemiştir. Etkili iletişimin dört aşaması buradan çıkar: mesajı açık iletmek, dikkatle dinlemek, doğru anlamı kurmak ve uygun tepkiyi vermek.","iliskili":["os-2-001","os-2-003","os-2-008","os-2-013"],"kontrol":null,"cizim":"konusma"},{"id":"os-2-107","konu":"2.1","terim":"İletişim biçimleri (sözlü, yazılı, sözsüz)","ingilizce":"Forms of communication (verbal, written, non-verbal)","tanim":"Mesajın konuşarak, yazarak ya da söz kullanmadan beden diliyle iletilmesi biçimindeki üç ana yoldur.","ornek":"Sabah 09.00, resepsiyon: görevli konuğa odanın hazır olduğunu söyler (sözlü), kartı verirken kat planını da bir kâğıda yazar (yazılı) ve gülümseyerek asansörü gösterir (sözsüz).","sektor":"Ders kitabına göre iletişim yalnız konuşmakla olmaz; dinleme, beden dili ve yazılı ifade de iletişimdir. Otelde bu üçü aynı anda çalışır: söylediğin söz, yazdığın not ve duruşun birbirini tutmazsa konuk en çok sözsüz mesaja inanır.","iliskili":["os-2-001","os-2-034","os-2-089"],"kontrol":null,"gorsel":"h2-parmak-alfabesi"},{"id":"os-2-003","konu":"2.1","terim":"Etkili dinleme","ingilizce":"Active listening","tanim":"Karşıdakinin mesajını sözünü kesmeden, dikkatle dinleme, anlamaya çalışma ve ona uygun geri bildirim verme becerisidir.","ornek":"Saat 16.00, resepsiyon: konuk klimasından yakınırken görevli ekrandan başını kaldırır, yüzünü konuğa döner, sonuna kadar dinler ve “Sizi doğru anladıysam klima açılıyor ama soğutmuyor, öyle mi efendim?” diye sorar.","sektor":"Programın anahtar kavramlarındandır. Duymak ile dinlemek aynı şey değildir: duymak kulağın, dinlemek dikkatin işidir. Dinlenen konuk güven duyar; yanlış anlaşılmalar daha başlamadan azalır.","iliskili":["os-2-012","os-2-013","os-2-019","os-2-027","os-2-082"],"kontrol":null,"cizim":"kulak-dinleme"},{"id":"os-2-004","konu":"2.1","terim":"İletişimde ilk izlenim","ingilizce":"First impression","tanim":"Konuğun işletme hakkında, çoğu zaman kurulan ilk iletişimle birlikte edindiği kanıdır.","ornek":"Kapıdan giren konuk, kendisine başını kaldırıp gülümseyen görevliyle telefonuna bakan görevli arasındaki farkı ilk saniyelerde görür.","sektor":"Güler yüz, uygun ses tonu, dikkatli dinleme ve açık ifade konuğa değerli olduğunu hissettirir. İlgisiz ve özensiz bir karşılama ise hizmetin geri kalanı iyi olsa bile onu gölgede bırakır; ilk izlenimi sonradan düzeltmek zordur.","iliskili":["os-2-005","os-2-030","os-2-054","os-2-069"],"kontrol":null,"cizim":"konusma"},{"id":"os-2-005","konu":"2.1","terim":"Kurumu temsil etme","ingilizce":"Representing the establishment","tanim":"Çalışanın konukla kurduğu her iletişimde yalnız kendisi adına değil, çalıştığı işletme adına da konuşuyor olmasıdır.","ornek":"Gece 23.00, resepsiyon: yorgun bir görevli konuğun sorusuna yüzüne bakmadan “Bilmiyorum” der; konuk ertesi gün arkadaşına “O otelde kimse bir şey bilmiyor” diye anlatır.","sektor":"Konuk seni adınla değil otelin adıyla hatırlar. Günlük hayatta fark etmeden kurduğun iletişim iş yerinde bilinçli olarak yönetilir; çünkü sonucu yalnız seni değil, kurumu da bağlar. Turizmde iletişim bu yüzden kurumun imajını doğrudan etkiler.","iliskili":["os-2-004","os-2-028","os-2-030","os-2-066","os-2-100"],"kontrol":null,"cizim":"konusma"},{"id":"os-2-006","konu":"2.1.1","terim":"İletişim teknikleri","ingilizce":"Communication techniques","tanim":"Kişinin kendini doğru ifade etmesini, karşısındakini doğru anlamasını ve iletişimi etkili biçimde yönetmesini sağlayan yöntem ve davranışlardır.","ornek":"Sabah 09.00, resepsiyon: görevli konuğun sorusunu sonuna kadar dinler, “Anlıyorum efendim” der, cevabı kısa ve açık verir, “Başka bir isteğiniz var mı?” diye sorar; dört teknik bir dakikaya sığar.","sektor":"Programın anahtar kavramlarındandır. Dört temel teknik vardır: açık ve anlaşılır konuşma, etkili dinleme, uygun tepki verme ve empati kurma. Teknikler yalnız ne söylediğini değil, nasıl söylediğini ve nasıl dinlediğini de kapsar; hizmet kalitesini doğrudan etkiler.","iliskili":["os-2-007","os-2-003","os-2-008","os-2-009"],"kontrol":null,"cizim":"konusma"},{"id":"os-2-007","konu":"2.1.1","terim":"Açık ve anlaşılır konuşma","ingilizce":"Clear speaking","tanim":"Düşüncelerin sade ve net sözcüklerle, karşıdakinin kolayca anlayacağı biçimde söylenmesidir.","ornek":"Saat 10.00, kat ofisi: kat şefi “Odaları hızlı yapın” demek yerine “405 ve 407 öncelikli, konuklar 14.00’te geliyor” der; herkes ne yapacağını bilir.","sektor":"Açık konuşan personele aynı soru ikinci kez sorulmaz. Kısa ve belirsiz bir cevap ise konuğu tahmin yürütmeye bırakır; tahmin de çoğu zaman yanlış anlaşılmayla biter.","iliskili":["os-2-006","os-2-011","os-2-020"],"kontrol":null,"cizim":"konusma"},{"id":"os-2-008","konu":"2.1.1","terim":"Uygun tepki verme","ingilizce":"Responding appropriately","tanim":"Alınan mesaja, onu anladığını gösteren sözlü ya da sözsüz bir karşılık verilmesidir.","ornek":"Konuk “Odamda havlu eksik” der; görevli “Hemen kat hizmetlerine haber veriyorum efendim” diyerek telefona uzanır.","sektor":"Dinlemek tek başına yetmez; karşılık verilmezse iletişim tamamlanmış sayılmaz. Konuğun isteğine yalnız “Tamam” demek yeterli bir tepki değildir: konuk ne yapılacağını duymak ister.","iliskili":["os-2-006","os-2-002","os-2-013","os-2-025"],"kontrol":null,"cizim":"konusma"},{"id":"os-2-009","konu":"2.1.1","terim":"Empati","ingilizce":"Empathy","tanim":"Kendini karşıdaki kişinin yerine koyarak onun duygu ve düşüncelerini anlamaya çalışma becerisidir.","ornek":"Gece 01.00, resepsiyon: on saatlik yolculuktan gelen konuk odasının hazır olmadığını öğrenince sinirlenir. Görevli “Bu kadar yoldan sonra beklemek gerçekten zor, haklısınız” diyerek söze başlar.","sektor":"Programın anahtar kavramlarındandır. Konuk önce anlaşılmak ister, sonra çözüm. Empati her konuda hak vermek değildir; karşıdakinin ne hissettiğini görmek ve bunu ona göstermektir. Şikâyette savunmaya geçen personel konuğu kaybeder, empati kuran kazanır.","iliskili":["os-2-006","os-2-023","os-2-053","os-2-010"],"kontrol":null,"cizim":"kalp-empati"},{"id":"os-2-010","konu":"2.1.1","terim":"Çözüm odaklı yaklaşım","ingilizce":"Solution-oriented approach","tanim":"Sorunun kimin hatası olduğuna değil, nasıl giderileceğine yoğunlaşan çalışma anlayışıdır.","ornek":"Akşam 20.00, restoran: yanlış tabak gelen konuğa garson “Mutfak karıştırmış” demek yerine “Özür dilerim efendim, hemen doğrusunu getiriyorum” der.","sektor":"Konuğu dikkatle dinlemek, sözünü kesmemek ve çözüme yönelmek etkili iletişimin göstergesidir. Sakin, açık ve çözüm odaklı konuşulduğunda sorun büyümeden kapanır; acele eden ve ilgisiz kalan personel ise memnuniyeti düşürür.","iliskili":["os-2-009","os-2-016","os-2-026","os-2-033","os-2-101"],"kontrol":null},{"id":"os-2-011","konu":"2.1.2","terim":"Sade dil","ingilizce":"Plain language","tanim":"Mesajı kısa ve açık sözcüklerle, gereksiz ayrıntıya girmeden ve karşıdakinin anlayacağı biçimde doğrudan anlatma biçimidir.","ornek":"Konuğa “Odanız henüz hazır değil, yarım saat içinde hazır olacak” denir; kat hizmetlerinin kendi arasında kullandığı kodlar ve kısaltmalar konuğa söylenmez.","sektor":"Hizmette dört özelliğe dikkat edilir: kısa ve anlaşılır ifade, gereksiz ayrıntıdan kaçınma, karşıdakinin anlayacağı dil ve mesajı doğrudan iletme. Meslek terimleri ekip içinde işi hızlandırır; konuğun karşısında ise duvar örer.","iliskili":["os-2-007","os-2-020","os-2-013"],"kontrol":null},{"id":"os-2-012","konu":"2.1.2","terim":"Etkili dinlemenin kuralları","ingilizce":"Rules of active listening","tanim":"Söz kesmemek, dikkati konuşana vermek, anlaşıldığını gösteren karşılıklar vermek, gerektiğinde açıklayıcı soru sormak ve empati kurmaya çalışmak, iyi bir dinleyicinin uyduğu beş ilkedir.","ornek":"Saat 15.30, konuk ilişkileri masası: görevli telefonunun ekranını kapatır, konuğun anlattığını sonuna kadar dinler ve yalnız bir yerde “Bu hangi gün olmuştu efendim?” diye sorar.","sektor":"Dinlemeden verilen tepki iletişimi zayıflatır. İyi dinleyici dinlerken başka işle uğraşmaz, vereceği cevabı kafasında hazırlamaz; anlamadığı yeri tahmin etmez, sorar.","iliskili":["os-2-003","os-2-019","os-2-013","os-2-049"],"kontrol":null,"cizim":"kulak-dinleme"},{"id":"os-2-013","konu":"2.1.2","terim":"Dönüt (geri bildirim)","ingilizce":"Feedback","tanim":"Dinleyenin, mesajı alıp almadığını ve nasıl anladığını karşı tarafa gösteren sözlü ya da sözsüz karşılığıdır.","ornek":"Kat şefi telsizle “405 öncelikli, konuk 14.00’te gelecek” der; kat görevlisi “Anlaşıldı, 405 saat 14.00’ten önce hazır olacak” diye tekrar eder.","sektor":"Programın anahtar kavramlarındandır. Dönüt vermek kadar almak da önemlidir: karşındakinin seni doğru anlayıp anlamadığını kontrol edersin, gerekirse açıklama istersin. Baş sallamak, “anladım” demek de dönüttür; otelde oda numarası, saat ve isim tekrar edilerek doğrulanır.","iliskili":["os-2-008","os-2-025","os-2-027","os-2-049","os-2-083"],"kontrol":null},{"id":"os-2-014","konu":"2.1.2","terim":"İletişim ortamı","ingilizce":"Communication environment","tanim":"Mesajın doğru anlaşılmasını kolaylaştıran ya da zorlaştıran; gürültü, dikkat dağıtan etkenler ve seçilen iletişim kanalı gibi koşullardır.","ornek":"Öğlen 13.00, mutfak: davlumbazın uğultusu içinde söylenen “on iki numaralı masa” sözü “iki numaralı masa” diye duyulur ve tabak yanlış masaya gider.","sektor":"İletişim için yalnız kişilerin değil, ortamın da uygun olması gerekir. Gürültülü yerde sessiz bir köşeye geçilir, mesaj tekrar ettirilir. Kanal da işe göre seçilir: acil iş telefonla, sonradan gerekecek bilgi yazıyla iletilir.","iliskili":["os-2-013","os-2-027","os-2-001"],"kontrol":null},{"id":"os-2-015","konu":"2.1.2","terim":"Üslup","ingilizce":"Manner of speaking","tanim":"Bir şeyi söylerken seçilen sözcüklerin ve ses tonunun oluşturduğu, iletişimin yönünü belirleyen anlatım biçimidir.","ornek":"“Buyurun” sözü gülümseyerek ve sakin bir sesle söylenirse davettir; kaşlar çatık, sert bir sesle söylenirse “Ne istiyorsun?” demektir.","sektor":"Nazik ve saygılı dil iletişimi geliştirir, kaba ve sert söz bozar. Dört alışkanlık üslubu korur: kırıcı sözden kaçınmak, sabırlı ve anlayışlı olmak, farklı görüşe saygı göstermek ve anlaşmazlıkta yapıcı konuşmak. Ders kitabı üslubun yanında duygu kontrolünü de ayrı bir husus olarak sayar: aşırı ve kontrolsüz tepkiler iletişimin yönünü bozar; bu yüzden çalışan sakin, dengeli ve kontrollü davranır.","iliskili":["os-2-016","os-2-022","os-2-024","os-2-033","os-2-081"],"kontrol":null,"cizim":"konusma"},{"id":"os-2-016","konu":"2.1.2","terim":"Yapıcı dil","ingilizce":"Constructive language","tanim":"Anlaşmazlık anında karşıdakini suçlamak yerine sorunu çözmeye ve iş birliğine yönelen konuşma biçimidir.","ornek":"Saat 11.30, resepsiyon: çıkış kuyruğu uzamıştır; görevli arkadaşına “Çok yavaşsın” demek yerine “Sıra uzadı; faturaları ben hazırlayayım, sen ödemeleri al” der.","sektor":"İki çalışan arasındaki gerginlik konuğa hemen yansır. Saygılı konuşmak, suçlayıcı ifadeden kaçınmak, çözüme yönelmek ve iş birliği önermek kısa süreli bir sorunun büyümesini önler.","iliskili":["os-2-015","os-2-010","os-2-032","os-2-024"],"kontrol":null,"cizim":"konusma"},{"id":"os-2-017","konu":"2.1.2","terim":"İletişimde güven","ingilizce":"Trust in communication","tanim":"Kişinin tutarlı davranması ve sözleriyle davranışlarının birbirini tutması sonucunda karşı tarafta oluşan güvenme hâlidir.","ornek":"Görevli “On dakika içinde sizi arayacağım efendim” der ve süre dolmadan arar; konuk onun bir sonraki sözüne de inanır.","sektor":"Güven yoksa en doğru bilgi bile kuşkuyla karşılanır. Tutamayacağın sözü verme, verdiğin sözü tut: konuk da ekip arkadaşın da senden her gün aynı tavrı göreceğini bilmelidir.","iliskili":["os-2-020","os-2-026","os-2-036","os-2-029"],"kontrol":null,"cizim":"konusma"},{"id":"os-2-109","konu":"2.1.2","terim":"Duygu kontrolü","ingilizce":"Emotional control","tanim":"Öfke, sabırsızlık ya da stres altında bile tepkileri ölçülü tutarak sakin, dengeli ve kontrollü davranabilme becerisidir.","ornek":"Saat 12.00, çıkış saati: sıra uzamış, bir konuk sesini yükseltir. Görevli derin bir nefes alır, sakin bir sesle “Haklısınız, bekletildiniz; hemen ilgileniyorum” der.","sektor":"Konuk senin kaçıncı işinle uğraştığını bilmez, yalnız tavrını görür. Sakin kalan personel sorunu büyütmez; kontrolünü kaybeden haklıyken haksız duruma düşer. Bu beceri, “duygusal tepkiyi kontrol edememek” hatasının olumlu karşılığıdır.","iliskili":["os-2-024","os-2-009","os-2-016"],"kontrol":null,"cizim":"kalp-empati"},{"id":"os-2-110","konu":"2.1.2","terim":"Açıklayıcı soru sorma","ingilizce":"Asking clarifying questions","tanim":"Anlaşılmayan ya da eksik kalan yeri tahmin etmek yerine karşıdakine kısa bir soru sorarak açığa kavuşturma davranışıdır.","ornek":"Konuk “Akşam için masa istiyorum” der; görevli “Kaç kişi olacaksınız ve saat kaçta gelmeyi düşünüyorsunuz efendim?” diye sorar.","sektor":"Kitaba göre etkili dinlemenin beş ilkesinden biridir. Tahminle işlem yapmak yanlış oda, yanlış masa ve yanlış saat demektir; tek bir soru bunu önler. Anlamadığı yerde açıklama istememek ise iletişim hatalarından biridir.","iliskili":["os-2-025","os-2-012","os-2-027"],"kontrol":null,"cizim":"konusma"},{"id":"os-2-018","konu":"2.1.3","terim":"İletişimde sık yapılan hatalar","ingilizce":"Communication mistakes","tanim":"Çoğu zaman fark edilmeden yapılan, mesajın doğru anlaşılmasını engelleyen ve karşıda olumsuz algı yaratan söz ve davranışlardır.","ornek":"Saat 13.00, resepsiyon: konuk kart anahtarının çalışmadığını söyler; görevli ekrandan başını kaldırmadan “Bir dakika” der ve dakikalarca başka hiçbir şey söylemez.","sektor":"Yedi yaygın hata vardır: yetersiz dinleme, belirsiz ifade, uygunsuz beden dili, kaba üslup, empati kurmamak, duygusal tepkiyi kontrol edememek ve geri bildirim vermemek. Bunlar birbirini besler; sonucu yanlış anlama, güven kaybı ve iletişim kopukluğudur.","iliskili":["os-2-019","os-2-106","os-2-020","os-2-021","os-2-022","os-2-023","os-2-024","os-2-025"],"kontrol":null,"cizim":"konusma"},{"id":"os-2-019","konu":"2.1.3","terim":"Yetersiz dinleme","ingilizce":"Poor listening","tanim":"Karşıdakini dikkatle ve sonuna kadar dinlemeden tepki verilmesiyle ortaya çıkan iletişim hatasıdır.","ornek":"Konuk “Odamdaki kasa…” diye söze başlar; görevli “Şifreyi unuttunuz, hemen sıfırlatıyorum” diye atılır. Oysa konuk kasanın kapağının hiç kapanmadığını söyleyecektir.","sektor":"Sözü kesilen ya da yarım dinlenen konuk kendini ifade edememiş ve anlaşılmamış hisseder. Tam dinlemeden sunulan çözüm çoğu zaman yanlış soruna çözümdür; iş iki kez yapılır.","iliskili":["os-2-018","os-2-003","os-2-012","os-2-106"],"kontrol":null,"cizim":"kulak-dinleme"},{"id":"os-2-020","konu":"2.1.3","terim":"Belirsiz ve karmaşık ifade","ingilizce":"Vague wording","tanim":"Açık olmayan, dolaylı ya da karışık sözlerle konuşulması biçimindeki iletişim hatasıdır.","ornek":"Konuk “Odam ne zaman hazır olur?” diye sorar. “Galiba birazdan” cevabı yerine “Saat 14.00’te hazır olacak, hazır olunca sizi arayacağım” denir.","sektor":"“Sanırım”, “galiba”, “biraz bekleyin” gibi netlik taşımayan sözler konukta güvensizlik yaratır. Bilmediğin şeyi tahmin etme: “Hemen öğrenip size bilgi vereyim” demek hem nettir hem dürüsttür.","iliskili":["os-2-018","os-2-007","os-2-011","os-2-017"],"kontrol":null,"cizim":"konusma"},{"id":"os-2-021","konu":"2.1.3","terim":"Uygunsuz beden dili","ingilizce":"Inappropriate body language","tanim":"Söz doğru olsa bile göz teması kurmamak, telefona bakmak ya da ilgisiz durmak gibi davranışlarla karşıdakine değer verilmediği izlenimini veren iletişim hatasıdır.","ornek":"Görevli, gözü ekranda ve eli telefonunda “Size nasıl yardımcı olabilirim?” der; konuk yardım göreceğine inanmaz.","sektor":"Konuk sözden önce bedeni okur. Bankoda cep telefonu görünmez; konuk yaklaşırken elindeki iş bırakılır ve yüz ona dönülür.","iliskili":["os-2-018","os-2-034","os-2-036","os-2-051"],"kontrol":null,"cizim":"beden-dili"},{"id":"os-2-106","konu":"2.1.3","terim":"Söz kesme","ingilizce":"Interrupting","tanim":"Karşıdaki kişi cümlesini bitirmeden araya girip konuşmaya başlamak biçimindeki iletişim hatasıdır.","ornek":"Saat 11.00, resepsiyon: konuk “Dün akşam odama…” diye başlar; görevli “Oda servisi mi efendim? Menü odanızda.” diye araya girer. Konuk aslında odasına yanlış bavul bırakıldığını söyleyecektir.","sektor":"Yetersiz dinlemenin en sık görülen biçimidir. Sözü sürekli kesilen kişi önemsenmediğini düşünür, anlatmaktan vazgeçer; sonuç saygı kaybı ve iletişim kopukluğudur. Araya girmek zaman kazandırmaz: konuk bitirsin, sonra sor.","iliskili":["os-2-019","os-2-003","os-2-012","os-2-082"],"kontrol":null,"cizim":"konusma"},{"id":"os-2-022","konu":"2.1.3","terim":"Saygısız ve kaba üslup","ingilizce":"Rude manner","tanim":"Karşıdakini kıran, sert ya da baştan savan sözlerle konuşulması biçimindeki iletişim hatasıdır.","ornek":"Konuk havuzun kaçta kapandığını sorar. “Bilmiyorum, sonra gelin” cevabı yerine “Hemen öğreniyorum efendim” denir.","sektor":"“Bekleyin”, “Bilmiyorum”, “Sonra gelin” hizmet sektöründe olumsuz iletişimin tipik cümleleridir. Aynı bilgi nazik bir cümleyle de verilebilir; aradaki fark konuğun kendini nasıl hissettiğidir.","iliskili":["os-2-018","os-2-015","os-2-033"],"kontrol":null},{"id":"os-2-023","konu":"2.1.3","terim":"Empati kurmamak","ingilizce":"Lack of empathy","tanim":"Karşıdakinin duygu ve düşüncelerini hesaba katmadan konuşarak iletişimi yüzeysel hâle getiren hatadır.","ornek":"Uçağı geciktiği için gece yarısı otele varan ve odasını hazır bulamayan konuğa “Uçağın gecikmesi bizim sorunumuz değil” demek.","sektor":"Sorunun kaynağı otel olmasa bile konuğun yorgunluğu gerçektir. “Bu bizim sorunumuz değil” cümlesi iletişimi tümüyle koparabilir; “Zor bir yolculuk olmuş, hemen ilgileniyorum” cümlesi ise aynı durumda konuğu kazanır.","iliskili":["os-2-018","os-2-009","os-2-053"],"kontrol":null,"cizim":"kalp-empati"},{"id":"os-2-024","konu":"2.1.3","terim":"Duygusal tepkiyi kontrol edememek","ingilizce":"Losing emotional control","tanim":"Öfke, sabırsızlık ya da stresin söze ve davranışa yansıtılması biçimindeki iletişim hatasıdır.","ornek":"Saat 12.00, çıkış saati: bankoda sıra uzamışken görevli, soru soran konuğa “Bir dakika dedim ya!” diye çıkışır.","sektor":"Yoğunluk bir gerekçe değildir; konuk senin kaçıncı işinle uğraştığını bilmez, yalnız sesini duyar. Sakin, dengeli ve kontrollü kalmak mesleğin parçasıdır: öfkeli konuğa sesini yükselterek cevap veren personel haklıyken haksız duruma düşer.","iliskili":["os-2-018","os-2-015","os-2-016"],"kontrol":null},{"id":"os-2-025","konu":"2.1.3","terim":"Geri bildirim vermemek","ingilizce":"Not giving feedback","tanim":"Söyleneni anladığını göstermemek ya da anlamadığı yerde açıklama istememek biçimindeki iletişim hatasıdır.","ornek":"Konuk telefonda ayrı yataklı iki kişilik oda ister; görevli isteği tekrar etmeden kaydeder ve konuğa tek büyük yataklı oda ayrılır.","sektor":"İsteği tam anlamadan yapılan işlem hatalı sonuç verir. Tekrar etmek zaman kaybı değildir; yanlış odayı, yanlış tabağı ve yanlış saati önler.","iliskili":["os-2-018","os-2-013","os-2-027","os-2-008"],"kontrol":null,"cizim":"konusma"},{"id":"os-2-111","konu":"2.1.3","terim":"İletişim kopukluğu","ingilizce":"Communication breakdown","tanim":"Mesajın karşı tarafa ulaşmaması ya da anlaşılmaması yüzünden iki taraf arasında iletişimin kesilmesidir.","ornek":"Konuk sorusunu üç kez sorar, her seferinde “Bilmiyorum” cevabını alır; dördüncü kez sormaz, şikâyetini internete yazar.","sektor":"Yetersiz dinleme, söz kesme, kaba üslup ve “Bu bizim sorunumuz değil” gibi cümlelerin ortak sonucudur. Kopan iletişimi yeniden kurmak, baştan doğru kurmaktan daha zordur.","iliskili":["os-2-018","os-2-019","os-2-112"],"kontrol":null,"cizim":"konusma"},{"id":"os-2-112","konu":"2.1.3","terim":"Yanlış anlaşılma","ingilizce":"Misunderstanding","tanim":"Mesajın söyleyenin kastettiğinden farklı biçimde algılanmasıdır.","ornek":"Mutfakta “On iki numaralı masa” sözü gürültüde “İki numaralı masa” diye duyulur ve tabak yanlış masaya gider.","sektor":"Belirsiz ifade, gürültülü ortam, geri bildirim eksikliği ve dijital yazışmada ses tonunun olmaması yanlış anlamayı doğurur; teyit etme ve dönüt onu önler.","iliskili":["os-2-111","os-2-020","os-2-027"],"kontrol":null,"cizim":"konusma"},{"id":"os-2-026","konu":"2.1.4","terim":"İletişim kurallarının olumlu etkileri","ingilizce":"Benefits of good communication","tanim":"Açık, saygılı ve bilinçli iletişimin güven oluşturması, yanlış anlaşılmaları azaltması, karşılıklı anlayışı artırması ve sorunların çözümünü kolaylaştırması gibi kazanımlardır.","ornek":"Sabah 08.45, vardiya toplantısı: şef günün işlerini açıkça anlatır, ekip sorularını sorar, herkes ne yapacağını bilerek dağılır; gün içinde “Bana kimse söylemedi” cümlesi duyulmaz.","sektor":"Etkisi kişiyle sınırlı kalmaz: sosyal ilişkiler güçlenir, meslek başarısı artar. İletişim kurallarına özen gösterilen iş yerinde iş daha hızlı yürür ve sorunlar büyümeden çözülür.","iliskili":["os-2-017","os-2-027","os-2-028","os-2-010"],"kontrol":null},{"id":"os-2-027","konu":"2.1.4","terim":"Teyit etme","ingilizce":"Confirming (paraphrasing)","tanim":"Karşıdakinin söylediğini kendi cümleleriyle tekrar ederek doğru anlaşılıp anlaşılmadığını kontrol etme davranışıdır.","ornek":"“Yanlış anlamadıysam odanızda sıcak su yok ve bunu dün akşam da bildirdiniz, doğru mu efendim? Hemen teknik servisi yönlendiriyorum.”","sektor":"Özet hem bilgiyi doğrular hem de konuğa “Sizi gerçekten duydum” der. Rezervasyon tarihi, oda numarası, saat ve isim gibi bilgiler mutlaka teyit edilir; açık ifade, etkili dinleme ve teyit birlikte kullanıldığında hata en aza iner.","iliskili":["os-2-013","os-2-003","os-2-025","os-2-026"],"kontrol":null,"cizim":"konusma"},{"id":"os-2-028","konu":"2.1.4","terim":"İletişim ve konuk memnuniyeti","ingilizce":"Communication and guest satisfaction","tanim":"Güler yüzlü, ilgili ve profesyonel iletişimin konuğa değerli olduğunu hissettirerek onun aldığı hizmetten hoşnut kalmasını sağlamasıdır.","ornek":"Otelden ayrılan aile resepsiyona “Her sorumuza güler yüzle cevap verdiniz, seneye yine geleceğiz” der.","sektor":"Turizmde doğru iletişim konuk memnuniyetini doğrudan etkiler: işletme hakkında olumlu bir algı oluşur, hizmet kalitesi yükselir ve otel yeniden tercih edilir. Oda ne kadar iyi olursa olsun, ilgisiz bir cevap konuğun aklında kalan şey olur.","iliskili":["os-2-026","os-2-005","os-2-004","os-2-052"],"kontrol":null,"cizim":"zil-hizmet"},{"id":"os-2-029","konu":"2.1","terim":"Ahilik","ingilizce":"Ahi brotherhood (Akhism)","tanim":"Yalnız kaliteli iş çıkarmayı değil; dürüstlüğü, sözünde durmayı, saygıyı ve güler yüzü de mesleğin şartı sayan esnaf ve zanaatkâr geleneğidir.","ornek":"Çarşıda bir usta çırağına önce “Gelene güler yüz göster, verdiğin sözü tut” diye öğretir; işin inceliği sonra gelir.","sektor":"Bugünün otelciliği aynı şeyi söyler: işini iyi yapmak yetmez, insanlarla doğru iletişim kurmak da gerekir. Güven, o gün de bugün de sözünde durmakla kazanılır.","iliskili":["os-2-017","os-2-026","os-2-015"],"kontrol":null,"gorsel":"h2-ahi-evran-muzesi"},{"id":"os-2-030","konu":"2.1","terim":"Gerçek anı","ingilizce":"Moment of truth","tanim":"Konuğun işletmeyle ya da çalışanla karşılaştığı ve hizmet hakkında kanı edindiği her temas anına sektörde verilen addır.","ornek":"Konuğun oteli telefonla aradığı an, kapıdan girdiği an, bankoda adıyla karşılandığı an ve kahvaltıda masaya oturduğu an ayrı ayrı birer gerçek anıdır.","sektor":"Bir konaklama onlarca küçük temastan oluşur ve her birinde otel yeniden değerlendirilir. Bu yüzden iletişim yalnız resepsiyonun değil, konukla karşılaşan herkesin işidir.","iliskili":["os-2-004","os-2-005","os-2-028"],"kontrol":null,"kitapDisi":true},{"id":"os-2-031","konu":"2.1","terim":"Kısa sohbet","ingilizce":"Small talk","tanim":"Konukla asıl iş dışında, hava ya da yolculuk gibi hafif konularda yapılan kısa ve nazik konuşmadır.","ornek":"Giriş işlemi sürerken görevli “Yolculuğunuz nasıl geçti efendim?” diye sorar; konuk gülümser, bekleme süresi ona daha kısa gelir.","sektor":"Buzları eritir, konuğa bir oda numarası değil bir insan olarak görüldüğünü hissettirir. Ölçüsü kısadır ve konusu güvenlidir: siyaset, din, para ve özel hayat sorulmaz; konuk konuşmak istemiyorsa uzatılmaz.","iliskili":["os-2-004","os-2-009","os-2-015"],"kontrol":null,"kitapDisi":true,"cizim":"konusma"},{"id":"os-2-032","konu":"2.1","terim":"Ben dili","ingilizce":"I-message","tanim":"Karşıdakini suçlamadan, kişinin kendi duygusunu ve ihtiyacını anlatarak konuştuğu ifade biçimidir.","ornek":"“Sen hep geç kalıyorsun” yerine “Vardiya devri gecikince konuk bilgilerini aktaramıyorum, zorlanıyorum” demek.","sektor":"Karşıtı “sen dili”dir: “Sen hep…”, “Sen zaten…” diye başlar, suçlar ve karşıdakini savunmaya iter. Ben dili sakin bir ses tonuyla birlikte kullanıldığında kişi değil, sorun konuşulur.","iliskili":["os-2-016","os-2-015","os-2-024"],"kontrol":null,"kitapDisi":true,"cizim":"konusma"},{"id":"os-2-033","konu":"2.1","terim":"Olumlu dil","ingilizce":"Positive language","tanim":"Konuğa yapılamayanı değil, yapılabileceğini söyleyen, aynı bilgiyi yapıcı sözcüklerle veren konuşma biçimidir.","ornek":"“Deniz manzaralı oda yok” yerine “Bu gece bahçe manzaralı odamız hazır; yarın öğlen deniz manzaralı bir oda boşalıyor, sizin için ayırayım mı?” demek.","sektor":"Olumsuz cevap tek başına bırakılmaz; yanına bir seçenek konur. Gerçeği gizlemek değildir: olmayan şey için söz verilmez, yalnız kapı konuğun yüzüne kapatılmaz.","iliskili":["os-2-015","os-2-022","os-2-010","os-2-016"],"kontrol":null,"kitapDisi":true},{"id":"os-2-113","konu":"2.1.2","terim":"Saygılı iletişim","ingilizce":"Respectful communication","tanim":"Karşıdakinin değerini gözeterek kırıcı sözlerden kaçınan, nazik ve ölçülü bir dille kurulan iletişimdir.","ornek":"Saat 15.00, resepsiyon: görevli konuğun sözünü bitirmesini bekler, “Buyurun efendim” diye karşılık verir ve konuk itiraz etse bile sesini yükseltmez.","sektor":"Konuk hizmetin kalitesini çoğu zaman bu tavırdan okur; saygı sözle, bakışla ve duruşla birlikte gösterilir.","iliskili":["os-2-022","os-2-016","os-2-015"],"kontrol":null,"cizim":"kalp-empati"},{"id":"os-2-034","konu":"2.2","terim":"Beden dili","ingilizce":"Body language","tanim":"Söze gerek kalmadan duruş, jest, mimik, bakış ve mesafeyle duygu ve düşünceleri karşıya yansıtan sözsüz iletişim biçimidir.","ornek":"Saat 14.00, lobi: bavuluyla içeri giren konuk daha tek kelime duymadan, bankodaki görevlinin dik duruşundan ve gülümsemesinden “Doğru yere geldim” diye düşünür.","sektor":"Programın anahtar kavramlarındandır. İnsanlar çoğu zaman farkında olmadan beden diliyle mesaj verir; konuk da senin ne söylediğin kadar nasıl davrandığına bakar. Bu yüzden beden dili bilinçli ve kontrollü kullanılır.","iliskili":["os-2-035","os-2-036","os-2-037","os-2-052"],"kontrol":null,"cizim":"beden-dili"},{"id":"os-2-035","konu":"2.2","terim":"Beden dilinin unsurları","ingilizce":"Elements of body language","tanim":"Göz teması, yüz ifadesi, duruş, el kol hareketleri ve kişiler arasındaki mesafeden oluşan, birlikte tek bir mesaj veren sözsüz iletişim ögeleridir.","ornek":"Konuk bankoya yaklaşırken sırayla şunları görür: görevlinin yüzü, sonra duruşu, sonra elleri. Hepsi aynı şeyi söylüyorsa mesaj nettir.","sektor":"Her birinin ayrı anlamı vardır; ama konuk onları tek tek değil, bütün olarak okur. Göz teması kurup gülümseyen kişi iletişime açık, kollarını bağlayıp bakışını kaçıran kişi kapalı ya da ilgisiz görünür.","iliskili":["os-2-039","os-2-041","os-2-044","os-2-047","os-2-048"],"kontrol":null,"cizim":"beden-dili"},{"id":"os-2-036","konu":"2.2","terim":"Söz ile beden dilinin uyumu","ingilizce":"Congruence","tanim":"Söylenen sözün yüz ifadesi ve duruşla aynı mesajı vermesi hâlidir.","ornek":"Kollarını kavuşturmuş, yere bakan bir görevlinin ağzından çıkan “Size yardımcı olmaktan mutluluk duyarım” cümlesine kimse inanmaz.","sektor":"Söz ile beden çeliştiğinde karşıdaki çoğu zaman bedene inanır. “Size yardımcı olacağım” diyen kişi aynı anda ilgili bir duruş sergilerse inandırıcı olur; uyumsuzluk ise güvensizlik doğurur.","iliskili":["os-2-034","os-2-017","os-2-021","os-2-052","os-2-070"],"kontrol":null,"cizim":"beden-dili"},{"id":"os-2-037","konu":"2.2","terim":"Bağlama göre yorumlama","ingilizce":"Reading body language in context","tanim":"Bir beden hareketine tek başına anlam yüklemeyip onu ortamla, kişiyle ve o andaki durumla birlikte değerlendirme ilkesidir.","ornek":"Kollarını bağlamış bir konuk klimanın altında oturuyorsa üşüyor olabilir; hesabı tartışırken bağladıysa söylenene kapanmış olabilir.","sektor":"Aynı hareket farklı ortamda farklı anlam taşır. Dikkatle gözlemle, bütüne bak; emin değilsen sor. Tek bir harekete bakıp konuk hakkında hüküm vermek, yanlış anlamanın en kısa yoludur.","iliskili":["os-2-034","os-2-038","os-2-043","os-2-046"],"kontrol":null,"cizim":"beden-dili"},{"id":"os-2-038","konu":"2.2","terim":"Beden dilinde kültür farkı","ingilizce":"Cultural differences in body language","tanim":"Bir toplumda olağan ya da olumlu sayılan bir beden hareketinin başka bir toplumda farklı anlaşılabilmesidir.","ornek":"Kahvaltı salonunda Bulgaristan’dan gelen konuk “Çay alır mısınız?” sorusuna başını iki yana sallar; garson “hayır” sanıp uzaklaşır, oysa konuk “evet” demiştir.","sektor":"Dünyanın her yerinden konuk ağırlayan personel kendi alışkanlığını herkes için geçerli saymaz. Hareketin anlamından emin değilse sözle doğrular.","iliskili":["os-2-037","os-2-044","os-2-049","os-2-048","os-2-079"],"kontrol":null,"cizim":"beden-dili"},{"id":"os-2-039","konu":"2.2.1","terim":"Göz teması","ingilizce":"Eye contact","tanim":"Konuşurken ya da dinlerken karşıdakinin gözlerine bakarak ona ilgi ve güven gösterme davranışıdır.","ornek":"Resepsiyon görevlisi oda kartını uzatırken ekrana değil konuğun yüzüne bakarak “İyi konaklamalar dilerim” der.","sektor":"Programın anahtar kavramlarındandır. İlgi ve güven duygusu oluşturur; “Sizi görüyorum, sizinle ilgileniyorum” demektir. Ölçülü olmalıdır: uzun süre gözünü ayırmadan sabit bakmak karşıda baskı ve rahatsızlık yaratabilir.","iliskili":["os-2-040","os-2-035","os-2-054","os-2-012","os-2-075"],"kontrol":null,"cizim":"beden-dili"},{"id":"os-2-040","konu":"2.2.1","terim":"Göz kaçırmak","ingilizce":"Avoiding eye contact","tanim":"Konuşurken bakışları karşıdakinden uzak tutarak çekingenlik, güvensizlik ya da ilgisizlik olarak algılanabilen davranıştır.","ornek":"Konuk “Odam ne zaman hazır olur?” diye sorar; görevli ekrana ve yere bakarak “Birazdan” der. Konuk bu cevaba güvenmez.","sektor":"Bakışı sürekli kaçırmak rahatsızlık ya da iletişimden kaçınma işareti sayılabilir. Kişi utandığı ya da düşündüğü için de gözünü kaçırıyor olabilir; ama bilgi veren bir çalışanda konuk bunu çoğu zaman ilgisizlik diye okur. Bu yüzden zor bir haberi verirken de konuğun yüzüne bakılır.","iliskili":["os-2-039","os-2-037","os-2-021"],"kontrol":null,"cizim":"beden-dili"},{"id":"os-2-041","konu":"2.2.1","terim":"Mimik","ingilizce":"Facial expression","tanim":"Yüz kaslarının hareketiyle oluşan, duyguyu yansıtan yüz ifadeleridir.","ornek":"Konuğun “Oda nasıldı?” sorusuna “Güzeldi” derken dudaklarını büzmesi, aslında bir şeyden memnun kalmadığını düşündürür.","sektor":"Gülümseme samimiyet, kaş çatma hoşnutsuzluk, dudak büzme beğenmeme, kararsızlık ya da memnuniyetsizlik anlatabilir. İfadesiz, ilgisiz bir yüz ise iletişime kapalı olarak okunur.","iliskili":["os-2-042","os-2-043","os-2-035","os-2-053"],"kontrol":null,"gorsel":"h2-ifadeli-maskeler"},{"id":"os-2-042","konu":"2.2.1","terim":"Gülümseme","ingilizce":"Smile","tanim":"Samimiyeti ve olumlu yaklaşımı söze gerek kalmadan gösteren yüz ifadesidir.","ornek":"Sabah 07.30, kahvaltı salonu girişi: görevli her konuğa gülümseyerek “Günaydın” der; konuk güne iyi başlar.","sektor":"Karşılamada güler yüz esastır; ama her ana uymaz. Ciddi bir sorununu anlatan konuğa gülümsemek, derdinin hafife alındığı izlenimini verebilir.","iliskili":["os-2-041","os-2-054","os-2-053","os-2-037","os-2-065"],"kontrol":null,"gorsel":"h2-gulen-yuz"},{"id":"os-2-043","konu":"2.2.1","terim":"Kaş çatmak","ingilizce":"Frowning","tanim":"Çoğu zaman öfke, rahatsızlık ya da hoşnutsuzluk bildiren, kaşların birbirine yaklaştırılmasıyla oluşan yüz ifadesidir.","ornek":"Hesabını inceleyen konuk bir satırda durup kaşlarını çatar; görevli sormasını beklemeden “O kalem dün akşamki oda servisiniz efendim” diye açıklar.","sektor":"Konukta gördüğünde bir sorun olabileceğinin ilk işaretidir; ilgilen. Her zaman kızgınlık değildir: bir şeyi anlamaya çalışan ya da güneşe karşı bakan kişi de kaşını çatar. Kendi yüzünde ise konuğa “Rahatsız ediyorsunuz” der.","iliskili":["os-2-041","os-2-037","os-2-042"],"kontrol":null,"gorsel":"h2-kizgin-yuz-cizimi"},{"id":"os-2-044","konu":"2.2.1","terim":"Jest","ingilizce":"Gesture","tanim":"El ve kol hareketleriyle verilen anlamlı işaretlerdir.","ornek":"Kalabalık bir akşam yemeğinde şef garson, salonun öbür ucundaki garsona eliyle boşalan masayı gösterir; tek söz edilmeden masa toplanır.","sektor":"Yerinde kullanılan jest sözü güçlendirir. Sürekli el kol hareketi yapmak ise heyecan, gerginlik ya da dikkatsizlik izlenimi verebilir.","iliskili":["os-2-045","os-2-046","os-2-035","os-2-038"],"kontrol":null,"cizim":"beden-dili"},{"id":"os-2-045","konu":"2.2.1","terim":"Açık el hareketi","ingilizce":"Open-hand gesture","tanim":"Avuç içi görünecek biçimde yapılan, karşıda dürüstlük ve açıklık duygusu uyandıran el hareketidir.","ornek":"Lobide asansörün yerini soran konuğa bellboy işaret parmağıyla değil, açık eliyle koridoru gösterir: “Şu taraftan, buyurun efendim.”","sektor":"Otelde yön açık elle gösterilir. Parmakla işaret etmek emir verme, sertlik ya da otoriter bir tavır olarak algılanabilir; açık el ise davet eder.","iliskili":["os-2-044","os-2-046","os-2-054"],"kontrol":null,"gorsel":"h2-acik-avuclar"},{"id":"os-2-046","konu":"2.2.1","terim":"Kolları bağlamak","ingilizce":"Crossing one's arms","tanim":"Göğüste kavuşturulan kollarla yapılan; savunma, mesafe koyma ya da iletişime kapalı olma işareti sayılabilen harekettir.","ornek":"Şikâyetini anlatan konuğu kollarını göğsünde kavuşturarak dinleyen görevli, “Haklısınız” dese bile konuğa “Beni ikna edemezsiniz” demiş olur.","sektor":"Konuğun karşısında kollar açık, eller görünür tutulur. Konukta gördüğünde ise hemen hüküm verme: yalnızca üşüyor da olabilir.","iliskili":["os-2-044","os-2-037","os-2-047"],"kontrol":null,"gorsel":"h2-kollar-bagli"},{"id":"os-2-047","konu":"2.2.1","terim":"Duruş (postür)","ingilizce":"Posture","tanim":"Bedenin ayakta dururken ya da otururken aldığı, kişinin ilgisini ve özgüvenini yansıtan biçimdir.","ornek":"Öğleden sonra 15.00, lobi: bellboy duvara yaslanıp omuzlarını düşürmüş bekliyorsa, konuk “Burada kimsenin canı çalışmak istemiyor” diye düşünür.","sektor":"Dik durmak özgüveni, konuğa doğru hafifçe eğilmek ilgiyi ve dikkati gösterir. Kambur durmak isteksizlik ya da özgüven eksikliği, arkaya yaslanmak rahatlık ya da mesafeli bir tavır olarak okunabilir.","iliskili":["os-2-035","os-2-054","os-2-046","os-2-048"],"kontrol":null,"cizim":"beden-dili"},{"id":"os-2-048","konu":"2.2.1","terim":"Mesafe (kişisel alan)","ingilizce":"Personal space","tanim":"İletişim kurarken iki kişinin arasında bıraktığı, rahat ve dengeli bir konuşma için uygun olması gereken açıklıktır.","ornek":"Garson siparişi alırken konuğun üzerine eğilmez, masadan bir adım geride ve dik durur; konuk rahatça konuşur.","sektor":"Fazla yaklaşmak konuğu rahatsız eder, fazla uzak durmak soğuk ve ilgisiz görünür. Konuk geri çekiliyorsa mesafeyi az bulmuştur; iyi personel bunu fark eder ve bir adım açılır.","iliskili":["os-2-035","os-2-047","os-2-038"],"kontrol":null,"cizim":"beden-dili"},{"id":"os-2-049","konu":"2.2.1","terim":"Baş sallamak","ingilizce":"Nodding","tanim":"Dinlerken başı hafifçe aşağı yukarı oynatarak anladığını, onayladığını ve konuşmaya katıldığını gösteren harekettir.","ornek":"Rezervasyon bankosunda konuk isteklerini sıralarken görevli not alır ve her maddede başıyla hafifçe onaylar; konuk dinlendiğinden emin olur.","sektor":"Sözü kesmeden dönüt vermenin en kısa yoludur. Dürüst kullanılmalıdır: anlamadan baş sallamak yanlış bir “evet” demektir ve iş sonunda hatalı yapılır.","iliskili":["os-2-013","os-2-012","os-2-038","os-2-052","os-2-083"],"kontrol":null,"cizim":"beden-dili"},{"id":"os-2-050","konu":"2.2.1","terim":"Saate bakmak","ingilizce":"Checking one's watch","tanim":"Konuşma sırasında yapıldığında sıkılma ya da sabırsızlık işareti olarak okunabilen harekettir.","ornek":"Saat 16.50, resepsiyon: vardiyası 17.00’de bitecek görevli, konuk konuşurken iki kez kol saatine bakar; konuk cümlesini yarıda keser.","sektor":"Konuğa “Artık gidin” demenin sessiz yoludur. Yerinde duramamak, sürekli kıpırdanmak da benzer biçimde gerginlik, huzursuzluk ya da dikkat dağınıklığı diye okunur.","iliskili":["os-2-051","os-2-021","os-2-037"],"kontrol":null,"gorsel":"t13f-kol-saati"},{"id":"os-2-051","konu":"2.2.1","terim":"Telefonla ilgilenmek","ingilizce":"Being on one's phone","tanim":"Biriyle konuşurken sürekli telefona bakarak ilgisizlik ve karşıdakine önem vermeme mesajı veren davranıştır.","ornek":"Akşam 21.00, restoran: hesap isteyen konuk, servis istasyonunun yanında telefonuna bakan garsonla göz göze gelmeye çalışır; sonunda vazgeçip ayağa kalkar.","sektor":"Bağlam burada da belirleyicidir: boş zamanda telefona bakmak başka, konukla konuşurken bakmak başkadır. İş gereği ekrandan bilgi kontrol ediyorsan bunu söylersin: “Rezervasyonunuza bakıyorum efendim.” Söylemezsen konuk seni ilgisiz sanır.","iliskili":["os-2-050","os-2-021","os-2-037"],"kontrol":null,"gorsel":"os-telefonla-ilgilenmek"},{"id":"os-2-114","konu":"2.2.1","terim":"Parmakla işaret etmek","ingilizce":"Pointing with a finger","tanim":"Bir kişiyi ya da yönü işaret parmağıyla göstermektir; karşıdaki bunu emir verme veya sert bir tavır olarak algılayabildiği için kaçınılması gereken bir el hareketidir.","ornek":"Saat 18.00, lobi: restoranın yerini soran konuğa görevli parmağıyla değil, açık eliyle yön gösterir.","sektor":"Otelde yön ve kişi parmakla değil açık elle gösterilir; parmak otoriter, açık el davetkâr okunur. Açık el hareketinin karşıtıdır.","iliskili":["os-2-045","os-2-044","os-2-037"],"kontrol":null,"cizim":"beden-dili"},{"id":"os-2-115","konu":"2.2.1","terim":"Sürekli el hareketi yapmak","ingilizce":"Excessive gesturing","tanim":"Konuşurken ellerin durmadan oynatılmasıdır; dinleyende heyecan, gerginlik ya da dikkatsizlik izlenimi bırakabilen bir davranıştır.","ornek":"Sabah 08.00, bankoda yeni başlayan stajyer konukla konuşurken kalemini çevirip durur; konuk onu gergin sanar.","sektor":"Jest yerinde ve ölçülü olunca sözü güçlendirir, fazla olunca dikkat dağıtır; ellerini sakin tutan personel güven verir.","iliskili":["os-2-044","os-2-116","os-2-037"],"kontrol":null,"cizim":"beden-dili"},{"id":"os-2-116","konu":"2.2.1","terim":"Yerinde duramamak","ingilizce":"Fidgeting","tanim":"Beklerken ya da konuşurken sakin duramayıp sürekli kıpırdanmaktır; gerginlik, huzursuzluk veya dikkat dağınıklığı gibi algılanabilen bir davranıştır.","ornek":"Akşam 21.30, restoran girişi: masa bekleyen konuğun karşısında görevli bir ayağından ötekine geçip durur; konuk acele ettirildiğini düşünür.","sektor":"Konuk, kıpırdanan personeli işine odaklanmamış ya da huzursuz görür; sakin bir duruş güven verir. Saate bakmak da benzer bir sabırsızlık işaretidir.","iliskili":["os-2-050","os-2-115","os-2-047"],"kontrol":null,"cizim":"beden-dili"},{"id":"os-2-117","konu":"2.2.1","terim":"Dudak büzmek","ingilizce":"Pursing the lips","tanim":"Dudakları birbirine bastırıp büzmektir; çoğu zaman bir şeyi beğenmeme, karar verememe ya da memnun olmama anlamına gelebilen yüz ifadesidir.","ornek":"Sabah 10.00, resepsiyon: odanın manzarasını öğrenen konuk dudaklarını büzer; görevli “Başka bir odaya bakmamı ister misiniz?” diye sorar.","sektor":"Konuk her memnuniyetsizliğini söze dökmez; mimiklerini okuyan personel sorun şikâyete dönüşmeden araya girer.","iliskili":["os-2-041","os-2-043","os-2-118"],"kontrol":null,"cizim":"beden-dili"},{"id":"os-2-118","konu":"2.2.1","terim":"İlgisiz yüz ifadesi","ingilizce":"Blank expression","tanim":"Yüzde hiçbir duygu ya da ilgi belirtisi olmadan donuk durmaktır; karşıdakine iletişime kapalı olunduğu veya ilgilenilmediği izlenimini veren yüz ifadesidir.","ornek":"Gece 02.00, resepsiyon: konuk içeri girerken görevli donuk bir yüzle “Hoş geldiniz” der; konuk karşılandığını hissetmez.","sektor":"Söz doğru olsa bile yüzdeki ilgisizlik konuğa değersiz olduğunu hissettirir; gülümseme bu ifadenin karşıtıdır.","iliskili":["os-2-041","os-2-042","os-2-052"],"kontrol":null,"cizim":"beden-dili"},{"id":"os-2-119","konu":"2.2.1","terim":"Uzun süre sabit bakmak","ingilizce":"Staring","tanim":"Karşıdakinin gözlerine bakışını hiç ayırmadan uzun süre bakmaktır; karşı tarafta baskı altında kalma ve rahatsızlık duygusu yaratabilen bir davranıştır.","ornek":"Saat 17.00, banko: görevli konuk konuşurken gözünü bir an bile ayırmadan bakar; konuk bakıştan rahatsız olup bir adım geri çekilir.","sektor":"Göz teması ilgi gösterir, sabit bakış ise rahatsız eder; denge, arada kısa bakış değiştirmekle kurulur.","iliskili":["os-2-039","os-2-040","os-2-048"],"kontrol":null,"cizim":"beden-dili"},{"id":"os-2-120","konu":"2.2.1","terim":"Dik durmak","ingilizce":"Standing upright","tanim":"Omuzları açık, sırtı dik tutarak ayakta durmaktır; kişinin kendine güvendiğini gösteren duruştur.","ornek":"Saat 14.00, otel girişi: konuk yaklaşırken görevli doğrulur, omuzlarını açar ve selamlar.","sektor":"Dik duruş konuğa işini bilen birinin karşısında olduğunu hissettirir; kambur duruşun karşıtıdır.","iliskili":["os-2-047","os-2-122","os-2-121"],"kontrol":null,"cizim":"beden-dili"},{"id":"os-2-121","konu":"2.2.1","terim":"Hafifçe öne eğilmek","ingilizce":"Leaning slightly forward","tanim":"Konuşan kişiye doğru bedeni hafifçe yatırmaktır; dinleyenin ilgisini ve dikkatini gösteren duruştur.","ornek":"Akşam 19.00, resepsiyon: sorununu anlatan konuğa görevli hafifçe öne eğilerek dinler.","sektor":"Aşırı yaklaşmadan, ölçülü yapılan eğilme konuğa dinlendiğini gösterir; empatik beden dilinin parçalarından biridir.","iliskili":["os-2-047","os-2-053","os-2-120"],"kontrol":null,"cizim":"beden-dili"},{"id":"os-2-122","konu":"2.2.1","terim":"Kambur durmak","ingilizce":"Slouching","tanim":"Omuzları düşürüp sırtı bükerek durmaktır; ilgisizlik, isteksizlik ya da özgüven eksikliği izlenimi verebilen duruştur.","ornek":"Öğleden sonra 15.00, lobi: bellboy sırtını duvara verip omuzlarını düşürerek bekler; gelen konuk onu isteksiz sanır.","sektor":"Konuk ilk anda duruşa bakar; toparlanmış bir duruş istekli bir ekip izlenimi verir. Dik durmanın karşıtıdır.","iliskili":["os-2-047","os-2-120","os-2-123"],"kontrol":null,"cizim":"beden-dili"},{"id":"os-2-123","konu":"2.2.1","terim":"Arkaya yaslanmak","ingilizce":"Leaning back","tanim":"Konuşurken gövdeyi geriye atıp yaslanmaktır; duruma göre rahatlık ya da karşıdan uzak durma tavrı olarak yorumlanabilen duruştur.","ornek":"Saat 11.00, ofis görüşmesi: acente temsilcisi koltuğa yaslanıp kollarını bırakınca satış müdürü onun rahat mı, ilgisiz mi olduğunu bağlamdan anlamaya çalışır.","sektor":"Anlamı bağlama göre değişir; müşteri karşısında dik oturmak güvenli seçimdir.","iliskili":["os-2-047","os-2-037","os-2-121"],"kontrol":null,"cizim":"beden-dili"},{"id":"os-2-052","konu":"2.2.2","terim":"Beden dilini doğru kullanmanın önemi","ingilizce":"Importance of body language","tanim":"Olumlu izlenim bırakması, güven oluşturması, yanlış anlamaları azaltması ve empatiyi güçlendirmesi nedeniyle beden dilinin bilinçli kullanılmasına verilen değerdir.","ornek":"Akşam 19.30, restoran: ortak dil bulamadığı konuğa garson gülümser, menüdeki yemeği eliyle gösterir, konuk başını sallayınca o da başıyla onaylar; sipariş tek kelime edilmeden doğru alınır.","sektor":"Etkili beden dilinin beş alışkanlığı vardır: uygun göz teması, güler yüz, dik ve dengeli duruş, yerinde jest ve mimik, karşıdakinin beden dilini doğru yorumlama. İlgisiz duruş ve olumsuz mimik ise konuğa değersiz olduğunu hissettirir; iletişim kopar.","iliskili":["os-2-034","os-2-036","os-2-053","os-2-054","os-2-028"],"kontrol":null,"cizim":"beden-dili"},{"id":"os-2-053","konu":"2.2.2","terim":"Empatik beden dili","ingilizce":"Empathetic body language","tanim":"Yüz ifadesini ve duruşu karşıdakinin o andaki duygusuna uygun hâle getirerek onu anladığını gösterme biçimidir.","ornek":"Akşam 19.00, resepsiyon: cüzdanını kaybettiğini söyleyen konuğu görevli gülümsemeden, ciddi ve ilgili bir yüzle, hafifçe öne eğilerek dinler.","sektor":"Sorun yaşayan konuğa ciddi ve ilgili bir ifadeyle yaklaşmak, duygularının anlaşıldığını gösterir. Her duruma aynı gülümsemeyle karşılık vermek profesyonellik değil, ezberdir.","iliskili":["os-2-009","os-2-042","os-2-052","os-2-023"],"kontrol":null,"cizim":"beden-dili"},{"id":"os-2-054","konu":"2.2.2","terim":"Karşılamada beden dili","ingilizce":"Welcoming body language","tanim":"Konuğu karşılarken dik duruş, göz teması, gülümseme ve nazik jestlerle olumlu bir ilk izlenim oluşturan davranışlardır.","ornek":"Saat 14.00, otel girişi: görevli konuk yaklaşırken doğrulur, gözlerine bakıp gülümser ve açık eliyle içeriyi gösterir; “Hoş geldiniz” sözü bunların ardından gelir.","sektor":"Konuk kendini rahat ve değerli hisseder; işletme daha ilk dakikada olumlu algılanır. Beden dili, turizmde konuk memnuniyetini doğrudan etkileyen bir etkendir.","iliskili":["os-2-004","os-2-039","os-2-042","os-2-045","os-2-047","os-2-069"],"kontrol":null},{"id":"os-2-061","konu":"2.3","terim":"Nezaket","ingilizce":"Courtesy","tanim":"İnsanın başkalarına saygılı, anlayışlı ve dikkatli davranmasını sağlayan kişisel inceliktir.","ornek":"Sabah 08.15, otelin personel girişi: çamaşır arabasını iten kat görevlisine kapıyı tutan stajyer “Buyurun, önce siz.” der.","sektor":"Programın anahtar kavramlarındandır. Turizmde bilgi sonradan öğretilir, nezaket ise ilk günden beklenir: konuk çoğu zaman odanın büyüklüğünü değil, kendisine nasıl davranıldığını hatırlar.","iliskili":["os-2-062","os-2-063","os-2-064","os-2-065","os-2-066"],"kontrol":null,"cizim":"kalp-empati"},{"id":"os-2-062","konu":"2.3","terim":"Görgü kuralları","ingilizce":"Etiquette","tanim":"Toplumun benimsediği, insanların bir arada yaşarken birbirine nasıl davranacağını gösteren yazısız davranış ölçüleridir.","ornek":"Öğle arası, kalabalık bir asansör: binmek isteyenler önce inenlere yol verir. Bunu kimse bir yerde yazdığı için yapmaz; herkes böyle yapılması gerektiğini bilir.","sektor":"Programın anahtar kavramlarındandır. Nezaket kişinin kendi inceliğidir, görgü kuralları ise toplumun ortak ölçüsüdür; ikisi birlikte insanın bulunduğu ortama uyum sağlamasını kolaylaştırır. Otelde bu ölçüler hizmet standardına dönüşür.","iliskili":["os-2-061","os-2-067","os-2-073","os-2-078","os-2-088"],"kontrol":null},{"id":"os-2-063","konu":"2.3","terim":"Teşekkür etme","ingilizce":"Saying thank you","tanim":"Yapılan bir iyiliği, gösterilen sabrı ya da verilen emeği fark ettiğini karşıdakine sözle bildirmektir.","ornek":"Saat 14.10, resepsiyon: odası hazırlanırken lobide bekleyen konuğa anahtarını uzatan görevli “Beklediğiniz için teşekkür ederim efendim.” der.","sektor":"Selamlaşma, dinleme ve özür dilemeyle birlikte nezaketin temel davranışlarındandır. Otelde konuğa da iş arkadaşına da teşekkür edilir; teşekkür edilen kişi emeğinin görüldüğünü anlar.","iliskili":["os-2-061","os-2-064","os-2-087"],"kontrol":null,"gorsel":"os-tesekkur-etme"},{"id":"os-2-064","konu":"2.3","terim":"Özür dileme","ingilizce":"Apologising","tanim":"Yapılan bir hatanın ya da karşıdakine verilen rahatsızlığın sorumluluğunu kabul ettiğini saygılı bir sözle bildirmektir.","ornek":"Akşam 20.30, otelin restoranı: siparişi karıştıran stajyer “Özür dilerim efendim, hemen doğrusunu getiriyorum.” der; bahane saymaz.","sektor":"Özür dilemek zayıflık değil, profesyonelliktir. Özür kısa olur, ardından çözüm gelir; hatasını üstlenmeyen personel küçük bir aksaklığı büyük bir kırgınlığa çevirir.","iliskili":["os-2-061","os-2-063","os-2-101"],"kontrol":null,"cizim":"kalp-empati"},{"id":"os-2-065","konu":"2.3","terim":"Güler yüz","ingilizce":"Friendly manner","tanim":"Karşıdaki kişiye hoş geldiğini ve kendisiyle ilgilenildiğini hissettiren içten, sıcak tavırdır.","ornek":"Gece 23.50: uzun yoldan gelen bir aile lobiye giriyor. Resepsiyon görevlisi başını ekrandan kaldırıp gülümseyerek “Hoş geldiniz.” diyor.","sektor":"“Güler yüz demir kapıyı açar.” Yalnız dudaktaki gülümseme değildir; bakış, ses ve davranış da güler yüzün parçasıdır. Güler yüzlü karşılama konuğa değerli olduğunu hissettirir ve hizmet kalitesini doğrudan etkiler; asık yüzle verilen eksiksiz hizmet bile konuğun gözünde eksik kalır.","iliskili":["os-2-061","os-2-042","os-2-067","os-2-069","os-2-075"],"kontrol":null,"cizim":"kalp-empati"},{"id":"os-2-066","konu":"2.3","terim":"Profesyonel nezaket","ingilizce":"Professional courtesy","tanim":"Turizm çalışanının güler yüzlü karşılamayı, saygılı hitabı ve ortama uygun davranışı her konuğa, her gün aynı özenle göstermesidir.","ornek":"Akşam 18.00, uzun bir vardiyanın sonu: bellboy yorgundur, ama son gelen konuğu da sabah ilk geleni karşıladığı gibi karşılar: “İyi akşamlar efendim, hoş geldiniz. Valizinizi alabilir miyim?”","sektor":"İş yerinde nezaket o günkü keyfe bırakılmaz; hizmetin parçasıdır, çünkü çalışan yalnız kendi adına değil, temsil ettiği kurum adına da davranır. Kurallara özen gösterilmezse kırgınlık, yanlış anlaşılma ve olumsuz izlenim doğar; konuk bunu çalışana değil, otele yazar.","iliskili":["os-2-061","os-2-005","os-2-065","os-2-068"],"kontrol":null,"cizim":"kalp-empati"},{"id":"os-2-067","konu":"2.3.1","terim":"Selamlaşma","ingilizce":"Greeting","tanim":"İki kişi karşılaştığında söz, bakış ve yüz ifadesiyle ilk teması kuran ve iletişimi başlatan davranıştır.","ornek":"Sabah 08.00, kat koridoru: odasından çıkan konukla göz göze gelen kat görevlisi gülümseyerek “Günaydın efendim.” der.","sektor":"İletişimin ilk adımıdır; ilk izlenimi o kurar. Selam yalnız sözden ibaret değildir: aynı “Hoş geldiniz.” güler yüzle söylenince karşılama, başka yere bakarak söylenince baştan savma olur. Söz, ses tonu ve beden dili aynı şeyi söylemelidir.","iliskili":["os-2-004","os-2-039","os-2-065","os-2-068","os-2-069","os-2-079"],"kontrol":null,"cizim":"beden-dili"},{"id":"os-2-068","konu":"2.3.1","terim":"Hitap","ingilizce":"Form of address","tanim":"Karşıdaki kişiye seslenirken seçilen söz ve seslenme biçimidir.","ornek":"Resepsiyonda “Sen hangi odadasın?” değil, “Oda numaranızı öğrenebilir miyim efendim?” denir.","sektor":"Konuğa, senden genç de olsa, “siz” denir; adı biliniyorsa “Ayşe Hanım”, “Mehmet Bey” diye seslenilir. “Abi”, “abla”, “teyze”, “canım” gibi sözler otel dilinde yoktur. Saygılı hitap, konuğa değerli olduğunu hissettirmenin en kısa yoludur.","iliskili":["os-2-066","os-2-067","os-2-069","os-2-071"],"kontrol":null,"cizim":"konusma"},{"id":"os-2-069","konu":"2.3.1","terim":"Konuk karşılama","ingilizce":"Welcoming the guest","tanim":"İşletmeye gelen konuğun selam, güler yüz ve uygun hitapla ilk kez ağırlanmasıdır.","ornek":"Öğleden sonra 15.00, otel girişi: kapıdan giren konuğu gören resepsiyon görevlisi elindeki işi bırakır, göz teması kurar ve “İyi günler efendim, hoş geldiniz.” der.","sektor":"Konuk otel hakkındaki ilk kararını çoğu zaman karşılanırken verir ve bu izlenim konaklamanın geri kalanını etkiler. Konuğu ilk gören personel selamı önce verir; konuğun fark edilmeyi beklemesi karşılamanın en sık yapılan hatasıdır.","iliskili":["os-2-004","os-2-054","os-2-065","os-2-067","os-2-068"],"kontrol":null,"gorsel":"sektor-resepsiyon-checkin"},{"id":"os-2-070","konu":"2.3.1","terim":"Tanışma","ingilizce":"Self-introduction","tanim":"İlk kez karşılaşan kişinin kendini açık, anlaşılır ve düzenli bir biçimde karşısındakine tanıtmasıdır.","ornek":"Stajın ilk günü, personel yemekhanesi: “Merhaba, ben Elif Kaya. Ön büroda staja başladım.”","sektor":"Ad ve görev net söylenir; mırıldanarak ya da yere bakarak yapılan tanışma daha ilk cümlede anlaşılmayı zorlaştırır. Dik duruş, göz teması ve gülümseme söyleneni destekler; söz ile beden dili uyumlu olunca insan güven verir.","iliskili":["os-2-036","os-2-067","os-2-071","os-2-074"],"kontrol":null,"gorsel":"h2-isim-etiketleri"},{"id":"os-2-071","konu":"2.3.1","terim":"Tanıştırma","ingilizce":"Introduction","tanim":"Birbirini tanımayan iki ya da daha çok kişinin üçüncü bir kişi tarafından birbirine tanıtılmasıdır.","ornek":"Ön büro müdürü, yeni başlayan stajyeri vardiya şefinin yanına götürür: “Hakan Bey, bugün aramıza katılan stajyerimiz Elif Kaya.”","sektor":"Adlar doğru ve anlaşılır söylenir, uygun hitap kullanılır. Adı yanlış söylenen kişi daha ilk dakikada önemsenmediğini düşünür; emin değilsen tanıştırmadan önce adı sor.","iliskili":["os-2-068","os-2-070","os-2-072","os-2-073"],"kontrol":null,"cizim":"kalp-empati"},{"id":"os-2-072","konu":"2.3.1","terim":"Ast ve üst","ingilizce":"Subordinate and superior","tanim":"Bir iş yerinde yetki sırasında aşağıda bulunan çalışan ile onun bağlı olduğu, yetkisi daha fazla olan çalışana verilen adlardır.","ornek":"Otelde resepsiyon görevlisi ön büro müdürünün astıdır; ön büro müdürü de genel müdürün astıdır.","sektor":"Tanıştırmada kimin kime tanıtılacağı ve tokalaşmada elini kimin önce uzatacağı bu sıraya göre belirlenir. Sırayı bilen stajyer, ilk gününde bile nerede nasıl davranacağını bilir.","iliskili":["os-2-071","os-2-073","os-2-078"],"kontrol":null,"cizim":"lider"},{"id":"os-2-073","konu":"2.3.1","terim":"Tanıştırmada sıra","ingilizce":"Order of introduction","tanim":"Tanıştırma yapılırken kimin kime tanıtılacağını saygı sırasına göre belirleyen kuraldır.","ornek":"Stajyer genel müdüre tanıtılır: “Müdürüm, bugün staja başlayan arkadaşımız Can Demir.” Genel müdür stajyere tanıtılmaz.","sektor":"Genellikle yaşça küçük olan büyüğe, ast olan üste tanıtılır. Akılda tutmanın yolu: saygı gösterilen kişi yerinde durur, öteki onun yanına getirilir ve ona tanıtılır.","iliskili":["os-2-062","os-2-071","os-2-072","os-2-078"],"kontrol":null,"cizim":"kalp-empati"},{"id":"os-2-074","konu":"2.3.2","terim":"El sıkma","ingilizce":"Handshake","tanim":"İki kişinin selamlaşırken, tanışırken ya da vedalaşırken birbirinin elini kavrayarak güven, saygı ve iletişime açıklık göstermesidir.","ornek":"Toplantı bitiminde acente temsilcisi ile satış müdürü ayağa kalkar, el sıkışarak vedalaşır.","sektor":"Tokalaşma da denir. Yalnız bir temas değil, karşıya verilen bir mesajdır: gücü, süresi ve o sıradaki beden dili “Sana değer veriyorum.” da diyebilir, “Aklım başka yerde.” de.","iliskili":["os-2-067","os-2-075","os-2-076","os-2-077","os-2-078"],"kontrol":null,"gorsel":"t13e-el-sikisma-takim"},{"id":"os-2-075","konu":"2.3.2","terim":"Etkili el sıkma","ingilizce":"Firm handshake","tanim":"Kısa süren, nazik ve kendinden emin biçimde, göz teması ve güler yüzle yapılan tokalaşmadır.","ornek":"Toplantı salonunun kapısı: satış müdürü acente temsilcisine döner, gözlerine bakar, gülümser; elini kısa ve dengeli biçimde sıkıp bırakır.","sektor":"Doğru yapılan el sıkma konuğa değerli olduğunu hissettirir ve işletme hakkında olumlu bir izlenim bırakır. El sıkarken başka yere bakmak ya da o sırada başkasıyla konuşmak tokalaşmanın bütün etkisini siler.","iliskili":["os-2-039","os-2-065","os-2-074","os-2-076","os-2-077"],"kontrol":null,"cizim":"beden-dili"},{"id":"os-2-076","konu":"2.3.2","terim":"Zayıf el sıkma","ingilizce":"Limp handshake","tanim":"Elin gevşek ve isteksizce, karşıdakinin elini kavramadan uzatılmasıyla yapılan tokalaşmadır.","ornek":"Staj görüşmesine gelen öğrenci, insan kaynakları sorumlusunun elini parmak uçlarından tutup hemen bırakır; daha söze başlamadan çekingen bir izlenim bırakmış olur.","sektor":"Karşı tarafta güvensizlik ya da isteksizlik olarak algılanabilir. Staj ve iş görüşmelerinde ilk saniyede verilen bu mesajı sonradan sözle düzeltmek zordur.","iliskili":["os-2-074","os-2-075","os-2-077"],"kontrol":null},{"id":"os-2-077","konu":"2.3.2","terim":"Aşırı güçlü el sıkma","ingilizce":"Overly firm handshake","tanim":"Karşıdakinin elinin gereğinden sert sıkıldığı ya da uzun süre bırakılmadığı tokalaşmadır.","ornek":"Turizm fuarında bir satış temsilcisi ziyaretçinin elini sıkıca kavrayıp uzun uzun sallar; ziyaretçi elini kurtarmaya çalışırken söyleneni dinleyemez.","sektor":"Karşıdakini rahatsız eder ve iletişim daha başlamadan olumsuz bir izlenim doğurur. Ölçü dengedir: ne gevşek ne sert, ne uzun ne aceleci.","iliskili":["os-2-074","os-2-075","os-2-076"],"kontrol":null,"cizim":"el-yikama"},{"id":"os-2-078","konu":"2.3.2","terim":"Eli ilk uzatan","ingilizce":"Who offers the hand first","tanim":"Tokalaşmayı kimin başlatacağını gösteren görgü kuralıdır.","ornek":"Genel müdür elini uzatmadıkça stajyer elini uzatmaz; müdür uzattığında ise bekletmeden karşılık verir.","sektor":"Genellikle yaşça büyük olan ya da üst konumda bulunan kişi elini önce uzatır; buna dikkat etmek saygının göstergesidir. Otelde konuğu karşılayan personel de çoğu zaman önce nazikçe selam verir ve konuğun elini uzatmasını bekler; konuk uzatırsa bekletmeden karşılık verir.","iliskili":["os-2-062","os-2-072","os-2-073","os-2-074","os-2-079"],"kontrol":null,"cizim":"beden-dili"},{"id":"os-2-079","konu":"2.3.2","terim":"Temassız selamlaşma","ingilizce":"Contactless greeting","tanim":"El sıkmanın uygun olmadığı durumlarda dokunmadan, söz ve beden diliyle yapılan selamlaşma biçimidir.","ornek":"Salgın hastalığın yaygın olduğu bir kış günü, resepsiyon: görevli elini uzatmaz; gülümseyip başını hafifçe eğerek “Hoş geldiniz efendim.” der.","sektor":"Salgın dönemlerinde sağlık önlemi olarak, bazen de kişisel tercih, kültür ya da sağlık nedeniyle insanlar el sıkmak istemeyebilir. Konuk elini uzatmıyorsa ısrar edilmez, alınganlık gösterilmez; gülümseme ve baş selamı aynı saygıyı anlatır.","iliskili":["os-2-038","os-2-067","os-2-074","os-2-078"],"kontrol":null,"cizim":"beden-dili"},{"id":"os-2-080","konu":"2.3.3","terim":"Telefonla iletişim","ingilizce":"Telephone communication","tanim":"Kişilerin birbirini görmeden, yalnız ses yoluyla kurduğu iletişimdir.","ornek":"Sabah 09.30: İzmir’den arayan bir konuk hafta sonu için oda soruyor. Oteli hiç görmedi; karşısında yalnız telefonu açan görevlinin sesi var.","sektor":"Beden dili görünmediği için yükü ses tonu, konuşma biçimi ve seçilen sözler taşır; bu yüzden telefonda açık, anlaşılır ve nazik bir dille konuşulur. Telefon çoğu zaman konuğun otelle ilk temasıdır: otel hakkındaki ilk izlenim, konuk daha kapıdan girmeden oluşur.","iliskili":["os-2-004","os-2-081","os-2-082","os-2-084","os-2-086"],"kontrol":null,"gorsel":"t13f-ahize"},{"id":"os-2-081","konu":"2.3.3","terim":"Ses tonu","ingilizce":"Tone of voice","tanim":"Sözlerin hangi duyguyla söylendiğini dinleyen kişiye ileten ses özelliğidir.","ornek":"“Biraz bekleteceğim.” cümlesi nazik ve ilgili bir sesle söylenince rica, aceleci ve bıkkın bir sesle söylenince azar gibi duyulur.","sektor":"Telefonda karşı taraf yüzünü göremez; duygunu yalnız sesinden anlar. Samimi ve saygılı bir ton iletişimi güçlendirir; sert, ilgisiz ya da aceleci ton olumsuz izlenim bırakır. Gülümseyerek konuş: gülümseme sese yansır.","iliskili":["os-2-015","os-2-080","os-2-082","os-2-085"],"kontrol":null,"cizim":"telefon"},{"id":"os-2-082","konu":"2.3.3","terim":"Telefonda dinleme","ingilizce":"Listening on the phone","tanim":"Hattaki kişiyi sözünü kesmeden, dikkati başka işe vermeden ve isteğini doğru anlamaya çalışarak dinlemektir.","ornek":"Arayan konuk rezervasyonundaki sorunu anlatırken görevli elindeki işi bırakır, not alır; konuk bitirince “Doğru anladıysam giriş tarihiniz yanlış görünüyor.” der.","sektor":"Konuğun isteği doğru anlaşılmadan doğru çözüm üretilemez. Sözü kesilen konuk derdini baştan anlatmak zorunda kalır ve sabrı azalır.","iliskili":["os-2-003","os-2-080","os-2-081","os-2-083","os-2-084"],"kontrol":null,"cizim":"kulak-dinleme"},{"id":"os-2-083","konu":"2.3.3","terim":"Kısa geri bildirim","ingilizce":"Verbal acknowledgement","tanim":"Telefonda dinlendiğini karşı tarafa belli etmek için araya konan “evet”, “anlıyorum”, “not alıyorum” gibi kısa sözlerdir.","ornek":"Konuk uçuşunun ertelendiğini uzun uzun anlatıyor; görevli arada “Anlıyorum efendim.”, “Evet, not aldım.” diyor.","sektor":"Yüz yüze konuşmada baş sallamanın yaptığı işi telefonda bu sözler yapar. Hattın öbür ucundaki uzun sessizlik konuğa “Beni dinliyor mu, hat mı kesildi?” diye düşündürür.","iliskili":["os-2-013","os-2-049","os-2-080","os-2-082"],"kontrol":null},{"id":"os-2-084","konu":"2.3.3","terim":"Telefon görüşmesinin sırası","ingilizce":"Call structure","tanim":"Bir telefon görüşmesinin selamla başlayıp kişinin kendini ve kurumunu tanıtması, karşıdakini dinlemesi, gerekli bilgiyi alıp açıklama yapması ve teşekkürle bitirmesi adımlarıyla yürütülmesidir.","ornek":"“İyi günler, ön büro, ben Elif. Size nasıl yardımcı olabilirim?” Konuk dinlenir, istenen bilgi verilir. “Aradığınız için teşekkür ederim, iyi günler dilerim.”","sektor":"Sıra belli olunca hiçbir adım unutulmaz: selam ver, kendini ve kurumu tanıt, dikkatle dinle, gereken bilgiyi al ve açıkla, teşekkür ederek bitir. Düzenli yürüyen görüşme konuğa işini bilen biriyle konuştuğunu hissettirir.","iliskili":["os-2-080","os-2-082","os-2-085","os-2-086","os-2-087"],"kontrol":null},{"id":"os-2-085","konu":"2.3.3","terim":"Kendini ve kurumu tanıtma","ingilizce":"Identifying yourself","tanim":"Telefonu açan ya da arayan kişinin selamdan sonra adını ve çalıştığı kurumu söylemesidir.","ornek":"“İyi akşamlar, resepsiyon, ben Mert. Size nasıl yardımcı olabilirim?”","sektor":"Arayan kişi doğru yeri aradığını ve kiminle konuştuğunu ilk cümlede öğrenir; ad ve kurum bilgisi görüşmeyi düzenli ve güvenilir kılar, konuğu rahatlatır. “Alo?” ya da “Efendim?” diye açılan otel telefonu ise konuğu tedirgin eder.","iliskili":["os-2-081","os-2-084","os-2-087"],"kontrol":null},{"id":"os-2-086","konu":"2.3.3","terim":"Kısa ve öz görüşme","ingilizce":"Keeping the call brief","tanim":"Telefon görüşmesinin gereksiz yere uzatılmadan, açık ve amaca uygun biçimde yürütülmesidir.","ornek":"Kahvaltı saatini soran konuğa görevli saati ve salonun yerini söyler, başka sorusu olup olmadığını sorar ve görüşmeyi bitirir; otelin bütün olanaklarını saymaya girişmez.","sektor":"Hat meşgulken başka konuklar bekler. Kısa konuşmak aceleci konuşmak değildir: konuk bilgisini eksiksiz alır, ama lafın dolandırıldığını hissetmez.","iliskili":["os-2-080","os-2-084","os-2-087"],"kontrol":null,"cizim":"telefon"},{"id":"os-2-087","konu":"2.3.3","terim":"Görüşmeyi sonlandırma","ingilizce":"Closing the call","tanim":"Telefon görüşmesinin teşekkür edilerek ve uygun bir iyi dilek sözüyle bitirilmesidir.","ornek":"“Başka bir isteğiniz var mı efendim? Aradığınız için teşekkür ederim, iyi günler dilerim.”","sektor":"Görüşmenin son cümlesi akılda kalan cümledir. Teşekkürsüz, birden kapanan telefon o ana kadar gösterilen bütün özeni boşa çıkarır.","iliskili":["os-2-063","os-2-084","os-2-085","os-2-086"],"kontrol":null},{"id":"os-2-088","konu":"2.3.4","terim":"Netiket","ingilizce":"Netiquette","tanim":"İnsanların dijital ortamlarda birbirine saygılı, bilinçli ve sorumlu davranmasını sağlayan internet görgü kurallarıdır.","ornek":"Sınıfın mesaj grubunda ödev tarihini yanlış yazan arkadaşıyla alay etmek yerine doğrusunu yazıp “Tarih değişmişti, bilgin olsun.” demek.","sektor":"Programın anahtar kavramlarındandır. Adı İngilizce “net” (ağ, internet) ve “etiquette” (görgü kuralları) sözcüklerinden gelir. İletişim artık yalnız yüz yüze ve telefonla kurulmuyor: konuk otele mesajla, e-postayla, sosyal medyadan da ulaşır ve aynı saygıyı bekler.","iliskili":["os-2-062","os-2-089","os-2-091","os-2-093","os-2-098"],"kontrol":null},{"id":"os-2-089","konu":"2.3.4","terim":"Yazılı mesajda açıklık","ingilizce":"Clarity in written messages","tanim":"Dijital ortamda yazılan mesajın, okuyan kişinin yanlış anlamasına yer bırakmayacak kadar açık, anlaşılır ve saygılı olmasıdır.","ornek":"“Olmaz.” diye biten mesaj ters bir cevap gibi okunur; “O tarihte ne yazık ki boş odamız yok, bir gün sonrası için yardımcı olabilirim.” aynı bilgiyi kırmadan verir.","sektor":"Yazıda ses tonu ve beden dili yoktur; okuyan kişi boşluğu kendi yorumuyla doldurur. Bu yüzden konuğa giden mesajda her şey sözcüklere emanettir.","iliskili":["os-2-007","os-2-088","os-2-090","os-2-091","os-2-092"],"kontrol":null,"cizim":"konusma"},{"id":"os-2-090","konu":"2.3.4","terim":"Göndermeden önce okuma","ingilizce":"Proofreading before sending","tanim":"Yazılan mesajın gönderilmeden önce içerik, üslup ve yazım bakımından bir kez daha gözden geçirilmesidir.","ornek":"Stajyer konuğa yazdığı cevabı göndermeden önce bir kez okur; konuğun adını yanlış yazdığını ve giriş tarihini bir gün kaydırdığını fark edip düzeltir.","sektor":"İnternette hızlı yazmak kolaydır, geri almak zordur. Düşünmeden gönderilen bir cümle hem yanlış anlaşılmaya hem de otelin özensiz görünmesine yol açar.","iliskili":["os-2-089","os-2-095","os-2-099"],"kontrol":null,"cizim":"kitap-ogrenme"},{"id":"os-2-091","konu":"2.3.4","terim":"Büyük harfle yazma","ingilizce":"Writing in all caps","tanim":"Bir mesajın tamamının büyük harflerle yazılmasıdır.","ornek":"“ODANIZ HAZIR DEĞİL, BEKLEYİNİZ” yazan mesaj konuğa azar gibi gelir; “Odanız kısa süre içinde hazır olacak, anlayışınız için teşekkür ederiz.” aynı bilgiyi nazikçe verir.","sektor":"İnternet dilinde çoğu zaman bağırmak anlamına gelir ve kaba sayılır. Art arda dizilen ünlemler de aynı etkiyi yapar; konuğa yazılan mesaj sakin, düzgün ve yazım kurallarına uygun olur.","iliskili":["os-2-088","os-2-089","os-2-092"],"kontrol":null,"gorsel":"h2-caps-lock"},{"id":"os-2-092","konu":"2.3.4","terim":"Emoji","ingilizce":"Emoji","tanim":"Yazışmada duygu ya da durum bildirmek için kullanılan küçük resimli simgedir.","ornek":"Arkadaşına yazdığın mesajda gülen yüz olabilir; konuğa gönderilen rezervasyon teyidinde olmaz.","sektor":"Duyguyu anlatmaya yardım eder, ama aşırı ya da yersiz kullanılırsa yazışmanın ciddiyetini azaltır. Otel adına yazan kişi otelin sesidir; konuk emojili bir cevabı samimiyet değil, ciddiyetsizlik olarak okuyabilir.","iliskili":["os-2-089","os-2-091","os-2-100"],"kontrol":null,"gorsel":"os-emoji"},{"id":"os-2-093","konu":"2.3.4","terim":"Gereksiz mesaj","ingilizce":"Spam","tanim":"Karşı tarafın istemediği, konuyla ilgisi olmayan ya da art arda yinelenen mesajların gönderilmesidir.","ornek":"Sınıf grubuna aynı duyuruyu beş kez yazmak ya da ödev konuşulurken ilgisiz videolar göndermek.","sektor":"Okuyanın zamanını alır ve önemli mesajın arada kaybolmasına yol açar. Cevap gecikti diye iş arkadaşına ya da konuğa aynı mesajı art arda göndermek sabırsızlık olarak algılanır.","iliskili":["os-2-088","os-2-089"],"kontrol":null,"cizim":"konusma"},{"id":"os-2-108","konu":"2.3.4","terim":"Netikette yaygın hatalar","ingilizce":"Common netiquette mistakes","tanim":"Aynı mesajı art arda göndermek, mesajı okundu bırakıp yanıtlamamak, gece geç saatte mesaj atmak ve paylaşımın kalıcı olabileceğini unutmak gibi dijital iletişimde sık düşülen, bir kısmı duruma göre tartışmalı olan kusurlardır.","ornek":"Cuma gecesi 23.50’de bir stajyer, ertesi gün gelecek konuğa aynı transfer mesajını üç kez gönderir; konuk uykudan telefon sesiyle uyanır.","sektor":"Ders kitabı bu davranışları etkinlikte “uygun / duruma göre değişir / uygun değil” diye sınıflandırtır; sonucu vermez. Aynı mesajı art arda göndermek açıkça netikete aykırıdır; okundu bırakmak ve gece geç mesaj atmak ise duruma göre değişir. Konuğun mesajı okundu görünüp cevapsız kalırsa kendini önemsenmemiş hisseder; kısa bir dönüş (mesajınızı aldık, sabah ilk iş yanıtlayacağız) bunu önler. İnternette paylaşılan içerik kalıcı olabilir, bu yüzden göndermeden önce düşünülür.","iliskili":["os-2-088","os-2-091","os-2-093"],"kontrol":null},{"id":"os-2-094","konu":"2.3.4","terim":"Kişisel bilgilere saygı","ingilizce":"Online privacy","tanim":"Başkasına ait ad, telefon numarası, fotoğraf ve mesaj gibi bilgilerin sahibinin izni olmadan paylaşılmamasıdır.","ornek":"Bir konuk, dün havuzda tanıştığı başka bir konuğun telefon numarasını resepsiyondan ister. Görevli numarayı vermez; isterse notunu o konuğa iletebileceğini söyler.","sektor":"İzinsiz paylaşım hem etik hem güvenlik sorunudur. Konuğun fotoğrafını, oda numarasını ya da bilgisini paylaşan personel konuğun güvenini ve otelin adını zedeler; arkadaşının fotoğrafını paylaşmadan önce de izin istenir.","iliskili":["os-2-088","os-2-095","os-2-098"],"kontrol":null,"cizim":"veri-guvenlik"},{"id":"os-2-095","konu":"2.3.4","terim":"Dijital iz","ingilizce":"Digital footprint","tanim":"İnternette yapılan her paylaşımın ve yazılan her yorumun ardında bıraktığı, uzun süre erişilebilir kalabilen kayıttır.","ornek":"Staj yaptığı otelde çektiği üniformalı şaka videosunu paylaşan öğrenci, yıllar sonra bir iş başvurusunda o videoyla karşılaşabilir.","sektor":"Paylaşılan içerik silinse bile bir yerde kalabilir. Yazmadan önce sorulacak soru şudur: bunu yıllar sonra bir işveren ya da bir konuk görse rahatsız olur muyum?","iliskili":["os-2-090","os-2-094","os-2-096","os-2-097"],"kontrol":null,"cizim":"dijital"},{"id":"os-2-096","konu":"2.3.4","terim":"Dijital kimlik","ingilizce":"Digital identity","tanim":"Kişinin internetteki davranışlarının, paylaşımlarının ve bıraktığı izlerin toplamının başkalarının gözünde oluşturduğu çevrim içi portredir.","ornek":"İki öğrenci düşün: birinin hesabında gezi fotoğrafları ve saygılı yorumlar, ötekinin hesabında hakaret dolu tartışmalar var. Onları hiç görmemiş biri bile ikisi hakkında fikir edinir.","sektor":"Paylaşımlarının içeriği, kullandığın dil ve başkalarına verdiğin tepkiler seni tanımayan kişilere kim olduğunu anlatır. Konukla yüz yüze çalışacak biri için dijital kimlik, özgeçmişin görünmeyen sayfasıdır.","iliskili":["os-2-095","os-2-097","os-2-098"],"kontrol":null,"cizim":"dijital"},{"id":"os-2-097","konu":"2.3.4","terim":"Çevrim içi itibar","ingilizce":"Online reputation","tanim":"Bir kişinin ya da işletmenin internetteki paylaşım ve yorumlar yoluyla başkalarının gözünde kazandığı saygınlıktır.","ornek":"Tatil planlayan bir aile, otelin sosyal medya hesabında bir şikâyete verilen sabırlı ve çözüm öneren cevabı görür; “Bu otel konuğunu dinliyor.” diye düşünür.","sektor":"Dijital izler uzun süre erişilebilir kaldığı için itibar yavaş kazanılır, tek bir paylaşımla zedelenebilir. Bu, otel için de çalışan için de geçerlidir.","iliskili":["os-2-095","os-2-096","os-2-100","os-2-105"],"kontrol":null,"gorsel":"h2-otel-yorumlari"},{"id":"os-2-098","konu":"2.3.4","terim":"Sosyal medyada netiket","ingilizce":"Social media etiquette","tanim":"Paylaşım yaparken, yorum yazarken ve başkalarına tepki verirken sosyal ağlarda saygılı bir dil kullanmayı gerektiren görgü kurallarıdır.","ornek":"Beğenmediği bir paylaşımın altına hakaret yazmak yerine görüşünü “Ben farklı düşünüyorum, çünkü…” diye yazan öğrenci.","sektor":"Yorumların ve tepkilerin dijital kimliğini yansıtır. Turizmde çalışan kişi mesai dışında da iş yerinin adını taşır; üniformayla ya da otelin içinde çekilen paylaşım oteli de bağlar.","iliskili":["os-2-088","os-2-094","os-2-096","os-2-099"],"kontrol":null,"cizim":"sosyal-medya"},{"id":"os-2-099","konu":"2.3.4","terim":"Doğru bilgi paylaşma","ingilizce":"Sharing accurate information","tanim":"İnternette bir bilgiyi başkalarına iletmeden önce doğruluğunu denetleme alışkanlığıdır.","ornek":"“Yarın okullar tatilmiş!” mesajını sınıf grubuna iletmeden önce okulun resmî duyurusuna bakmak.","sektor":"Konuğa yanlış bilgi yazmak, geç yazmaktan kötüdür: yanlış servis saati ya da yanlış fiyat konuğu mağdur eder, oteli zor durumda bırakır. Emin değilsen “Kontrol edip size dönüyorum.” de.","iliskili":["os-2-090","os-2-098","os-2-100"],"kontrol":null,"cizim":"kitap-ogrenme"},{"id":"os-2-100","konu":"2.3.4","terim":"Kurum adına dijital iletişim","ingilizce":"Corporate digital communication","tanim":"Bir çalışanın işletmenin e-postası, mesaj hattı ya da sosyal medya hesabı üzerinden işletme adına yaptığı yazışmadır.","ornek":"Otelin sosyal medya hesabına “Havuz kaça kadar açık?” diye yazan konuğa stajyer kendi ağzıyla değil, otel adına cevap verir: “Merhaba, havuz saatlerimizi aşağıda paylaşıyoruz. İyi tatiller dileriz.”","sektor":"Burada kullanılan dil doğrudan kurumun imajıdır: tek bir sert cevap ekran görüntüsüyle herkese ulaşır ve otelin güvenilirliğini zedeler. Nazik, profesyonel ve özenli yazılır.","iliskili":["os-2-005","os-2-092","os-2-097","os-2-101"],"kontrol":null,"cizim":"dijital"},{"id":"os-2-101","konu":"2.3.4","terim":"Çözüm odaklı cevap","ingilizce":"Solution-oriented reply","tanim":"Bir şikâyete ya da soruya savunmaya geçmeden, sorunun nasıl giderileceğini anlatarak verilen nazik cevaptır.","ornek":"Konuk “Mesajıma iki gündür dönülmedi!” yazıyor. Cevap: “Geç dönüş için özür dileriz. Rezervasyonunuzu şimdi kontrol ediyoruz, bugün içinde size bilgi vereceğiz.”","sektor":"Şikâyet eden konukla çevrim içi tartışmaya girilmez; o yazışmayı başka konuklar da okur. Özür, kısa açıklama ve atılacak adım: iyi bir cevap kızgın konuğu kazanır, okuyanlara da otelin konuğunu dinlediğini gösterir.","iliskili":["os-2-010","os-2-064","os-2-097","os-2-100","os-2-105"],"kontrol":null,"cizim":"konusma"},{"id":"os-2-102","konu":"2.3","terim":"Kıyafet kuralı","ingilizce":"Dress code","tanim":"Bir ortamda ya da davette ne tür giysi giyilmesinin beklendiğini bildiren kuraldır.","ornek":"Otelin akşam restoranının girişinde küçük bir not: “Akşam yemeğinde şort ve terlikle girilmemesi rica olunur.”","sektor":"Sektörde İngilizcesiyle söylenir: dress code. Davetiyelerde ve otel restoranlarında karşına çıkar; konuğa bu kuralı kırmadan, nazik bir dille hatırlatmak personelin işidir.","iliskili":["os-2-062","os-2-061"],"kontrol":null,"kitapDisi":true},{"id":"os-2-103","konu":"2.3","terim":"Beklemeye alma","ingilizce":"Putting a caller on hold","tanim":"Telefondaki kişinin, bilgi aranırken ya da görüşme aktarılırken kısa bir süre hatta bekletilmesidir.","ornek":"“Rezervasyonunuzu kontrol etmem için sizi kısa bir süre bekletebilir miyim efendim?” Hatta dönünce: “Beklediğiniz için teşekkür ederim.”","sektor":"Sektörde “hold” denir. Konuk izin istenmeden beklemeye alınmaz; neden bekleyeceği söylenir, hatta dönünce teşekkür edilir. Habersiz ve uzun bekletilen konuk çoğu zaman telefonu kapatır.","iliskili":["os-2-063","os-2-082","os-2-084"],"kontrol":null,"kitapDisi":true},{"id":"os-2-104","konu":"2.3","terim":"Nezaket araması","ingilizce":"Courtesy call","tanim":"Otelin, odasına yerleşen konuğu bir süre sonra arayıp her şeyin yolunda olup olmadığını sormasıdır.","ornek":"Girişten bir süre sonra resepsiyon odayı arar: “İyi akşamlar Ayşe Hanım, odanızdan memnun musunuz, bir isteğiniz var mı?”","sektor":"Sektörde “courtesy call” denir. Küçük bir eksik, şikâyete dönüşmeden giderilir; konuk da düşünüldüğünü hisseder.","iliskili":["os-2-061","os-2-068","os-2-081"],"kontrol":null,"kitapDisi":true,"gorsel":"f3f-oda-telefonu"},{"id":"os-2-105","konu":"2.3","terim":"Konuk yorumu","ingilizce":"Guest review","tanim":"Bir işletmede kalan kişinin oradaki deneyimi hakkındaki görüşünü internette herkesin okuyabileceği biçimde yazmasıdır.","ornek":"Tatilden dönen bir konuk rezervasyon sitesine şunu yazar: “Oda temizdi, resepsiyondaki genç çok ilgiliydi; kahvaltı salonu kalabalıktı.”","sektor":"Sektörde “guest review” ya da “online review” denir. Yeni konuklar otel seçerken bu yorumları okur; otelin verdiği nazik ve çözüm odaklı cevap da yorumun kendisi kadar dikkat çeker.","iliskili":["os-2-097","os-2-100","os-2-101"],"kontrol":null,"kitapDisi":true}],"acikSorular":[{"id":"os-2-y01","konu":"2.1","soru":"Bir resepsiyon görevlisi, şikâyetini anlatan konuğu dinlerken sürekli sözünü kesip bilgisayardaki işlemlerle ilgilenmektedir. Bu iletişim hatasını açıklayınız. Konuğu etkili biçimde dinlemek için iki iletişim tekniği öneriniz.","olcut":[{"metin":"Söz kesme ve ilgisiz davranışın iletişim hatası olduğunu açıklar.","puan":25},{"metin":"Bu hatanın konuk üzerindeki etkisini açıklar.","puan":25},{"metin":"Birinci iletişim tekniğini tanımlar ve bu duruma uygular.","puan":25},{"metin":"İkinci iletişim tekniğini tanımlar ve bu duruma uygular.","puan":25}],"ornek":"Söz kesme, konuğun anlatmasını yarıda bırakır ve “önemsenmediği” izlenimini verir. Teknik 1: etkili dinleme; konuk bitirene kadar beklemek ve sonra özetleyerek anladığını göstermek. Teknik 2: açıklayıcı soru sormak; “Sorununuz ne zaman başladı?” gibi bir soruyla eksik bilgiyi tamamlamak.","ipucu":"Teknikleri yalnızca adıyla değil, bu resepsiyon durumunda ne yapacağınızı yazarak anlatın."},{"id":"os-2-y02","konu":"2.3","soru":"Bir otel çalışanı, şikâyetini dile getiren bir konuğu dinlerken yüzünü asmakta ve kısa cevaplar vermektedir. Nezaket ve görgü kavramlarını açıklayınız. Çalışanın bu durumda yapması gereken en az iki davranışı ve bu davranışların konuk memnuniyetine etkisini yazınız.","olcut":[{"metin":"Nezaket ve görgü kavramlarını doğru tanımlar.","puan":20},{"metin":"Çalışanın bu durumda uyması gereken davranışları en az iki örnekle yazar.","puan":40},{"metin":"Bu davranışların konuk memnuniyetine etkisini açıklar.","puan":40}],"ornek":"Nezaket: kibar ve saygılı davranmak; görgü: toplumun benimsediği, insanların birbirine nasıl davranacağını gösteren yazısız davranış ölçüleridir. Çalışan gülümseyerek konuğa dönmeli, “Anlıyorum, hemen yardımcı oluyorum” gibi kibar bir dil kullanmalı ve özür dilemelidir. Bu davranışlar konuğun kendini önemli hissetmesini sağlar ve memnuniyeti artar.","ipucu":"Nezaketi davranışla (ses tonu, göz teması, kibar sözcük) somutlaştırın."}],"sorular":[{"id":"os-2-s01","tur":"coktan-secmeli","soru":"Konuk anlatırken görevli “Yani 312’nin klimasından söz ediyorsunuz, doğru mu?” diyor. Bu davranış hangi tekniğe örnektir?","secenekler":["Kısa sohbet","Ben dili","Teyit etme","Olumlu dil"],"dogru":2,"aciklama":"Teyit etme, karşıdakinin söylediğini kendi cümlelerimizle tekrar ederek doğru anlaşılıp anlaşılmadığını kontrol etmektir. Kısa sohbet asıl iş dışındaki hafif konuşmadır; burada konu doğrudan konuğun sorunudur."},{"id":"os-2-s02","tur":"coktan-secmeli","soru":"Konukla iletişimde aşağıdaki davranışlardan hangisi yanlıştır?","secenekler":["Konuk cümlesini bitirmeden araya girip çözümü söylemek","Anlaşılmayan yeri tahmin etmek yerine kısa bir soruyla sormak","Söylenenleri kendi cümleleriyle tekrar edip doğrulamak","Dinlediğini baş sallayarak ya da kısa sözlerle göstermek"],"dogru":0,"aciklama":"Söz kesmek yetersiz dinlemedir; konuk anlaşılmamış hisseder ve çözüm çoğu zaman yanlış soruna yönelir. Diğer üçü etkili dinlemenin kurallarındandır."},{"id":"os-2-s03","tur":"coktan-secmeli","soru":"Aşağıdaki davranışlardan hangisi empati kurmaya örnektir?","secenekler":["Gecikmeye öfkelenen konuğa “Bu bizim kuralımız, değiştiremeyiz” demek","Şikâyet eden konuğa, sorunu kapatmak için hemen indirim önermek","Sorunun hangi birimden çıktığını konuğa uzun uzun ve ayrıntılı anlatmak","Çantası kaybolan konuğa, bunun ne kadar can sıkıcı olduğunu fark ettiğini söylemek"],"dogru":3,"aciklama":"Empati, kendini karşıdakinin yerine koyup duygusunu anlamaya çalışmaktır. İndirim ya da açıklama çözüm olabilir, ama konuğun duygusunu fark etmek yerine geçmez."},{"id":"os-2-s04","tur":"coktan-secmeli","soru":"Kat şefinin söylediğini dinleyip anlayan ama hiçbir karşılık vermeyen görevlide iletişim sürecinin hangi adımı eksiktir?","secenekler":["Konuşma","Tepki verme","Dinleme","Anlama"],"dogru":1,"aciklama":"İletişim süreci konuşma, dinleme, anlama ve tepki vermeden oluşur. Görevli dinlemiş ve anlamıştır; ama karşılık vermediği için kat şefi mesajın ulaşıp ulaşmadığını bilemez."},{"id":"os-2-s05","tur":"coktan-secmeli","soru":"Hangi cümle ben diliyle kurulmuştur?","secenekler":["“Siz hep bilgi vermeyi unutuyorsunuz, bu hiç değişmiyor.”","“Vardiya devrinde bilgi gelmeyince işimi yetiştirmekte zorlanıyorum.”","“Sizin yüzünüzden benim işim sürekli aksıyor.”","“Yine kimse bana önemli bir şeyi haber vermemiş.”"],"dogru":1,"aciklama":"Ben dili karşıdakini suçlamadan kişinin kendi duygusunu ve ihtiyacını anlatır. Diğer üç cümle karşıdakini ya da bir grubu suçlar; bu da savunma ve tartışma doğurur."},{"id":"os-2-s06","tur":"coktan-secmeli","soru":"Odanın ne zaman hazır olacağını soran konuğa “Sanırım birazdan, galiba” diyen görevlinin hatasını en iyi hangi cevap giderir?","secenekler":["“Çok yakında efendim, hiç endişelenmeyin, her şey yolunda.”","“Bu konuyu kat ofisine sormanız gerekir efendim, onlar bilir.”","“Şu an yoğunuz, hazır olunca zaten kendiniz görürsünüz.”","“Kat ofisine sordum; 14.00’te hazır olacak, ben haber vereceğim.”"],"dogru":3,"aciklama":"Hata belirsiz ifadedir; çözüm net bir saat vermektir. “Çok yakında” yine belirsizdir, öteki iki cevap ise konuğu çözümsüz bırakan kaba üslup örnekleridir."},{"id":"os-2-s07","tur":"coktan-secmeli","soru":"Yorgun ve üzgün gelen konuğa “Bu bizim sorunumuz değil” demek iletişimi neden koparabilir?","secenekler":["Konuğun duygusu hiç hesaba katılmamıştır","Cümle gereğinden fazla kısadır","Konuğa yanlış bilgi verilmiştir","Ses tonu çok yüksek çıkmıştır"],"dogru":0,"aciklama":"Sorun otelden kaynaklanmasa bile konuğun yorgunluğu gerçektir; bunu yok saymak empati kurmamaktır. Cümlenin kısalığı ya da ses tonu sorunun kaynağı değildir."},{"id":"os-2-s08","tur":"coktan-secmeli","soru":"Girişte kimse selam vermeyen otelde konuk, sonradan çok iyi hizmet alsa da kötü bir izlenimle ayrılabilir. Bu durumu en iyi açıklayan kavram hangisidir?","secenekler":["İletişim kopukluğu","Yanlış anlaşılma","İlk izlenim","Kısa sohbet"],"dogru":2,"aciklama":"Konuk işletme hakkındaki kanıyı çoğu zaman ilk iletişimle edinir. İletişim kopukluğu mesajın ulaşmaması, yanlış anlaşılma ise farklı algılanmasıdır; burada sorun ilk temasın kendisindedir."},{"id":"os-2-s09","tur":"coktan-secmeli","soru":"Bir görevli konuğa “Hemen bakıyorum” dediği hâlde yarım saat dönmüyor. Bu davranışta öncelikle hangisi zedelenir?","secenekler":["Sade dil","Kısa sohbet","Empati","İletişimde güven"],"dogru":3,"aciklama":"Güven, sözle davranışın birbirini tutmasıyla oluşur. “Hemen” denip yarım saat beklenince söz davranışa uymamış olur ve konuğun güveni sarsılır."},{"id":"os-2-s10","tur":"coktan-secmeli","soru":"Konuşurken ellerini durmadan oynatan görevlinin konukta bıraktığı izlenim hangisine yakındır?","secenekler":["Gerginlik ya da dikkatsizlik","Kendine güven ve kararlılık izlenimi","Dürüstlük ve açıklık duygusu","İlgi ve dikkat gösterme izlenimi"],"dogru":0,"aciklama":"Sürekli el hareketi gerginlik ya da dikkatsizlik izlenimi verebilir. Dürüstlük ve açıklık duygusunu veren hareket, avuç içi görünen açık el hareketidir."},{"id":"os-2-s11","tur":"coktan-secmeli","soru":"Konuk anlatırken stajyer sırtını bükmüş, omuzlarını düşürmüş duruyor. Konuk bu duruşu en çok nasıl okur?","secenekler":["İlgi ve dikkat","Özgüven ve kararlılık","İlgisizlik ve isteksizlik","Dürüstlük ve açıklık"],"dogru":2,"aciklama":"Kambur durmak ilgisizlik, isteksizlik ya da özgüven eksikliği izlenimi verir. İlgi ve dikkat ise konuşana doğru hafifçe eğilmekle gösterilir."},{"id":"os-2-s12","tur":"coktan-secmeli","soru":"Lobide yön gösterirken parmakla işaret etmek yerine açık el kullanılması neden tercih edilir?","secenekler":["Açık el uzaktan daha rahat fark edildiği için tercih edilir","Açık el dürüstlük ve açıklık, parmak ise sertlik izlenimi verir","Açık el heyecanı gizler, parmakla göstermek gerginliği ele verir","Parmakla işaret etmek kolu daha çabuk yorar, açık el yormaz"],"dogru":1,"aciklama":"Avuç içi görünen açık el davet eder ve güven verir; parmakla göstermek emir verme ya da sert tavır gibi algılanabilir. Seçim görünürlük ya da yorgunlukla ilgili değil, verilen mesajla ilgilidir."},{"id":"os-2-s13","tur":"coktan-secmeli","soru":"Yere bakarak “Size yardımcı olmaktan mutluluk duyarım” diyen görevlinin sözü neden inandırıcı gelmez?","secenekler":["Söz ile beden dili çelişir, konuk da bedene inanır","Cümle gereğinden fazla resmî ve kalıplaşmış olduğu için","Yere bakmak her zaman ve her kültürde saygısızlık sayıldığı için","“Mutluluk” gibi duygu sözcükleri otelde kullanılmadığı için"],"dogru":0,"aciklama":"Söz ile beden dili uyumlu olmalıdır; çeliştiğinde karşı taraf çoğu zaman beden diline inanır. Bakışın yönü tek başına “her zaman saygısızlık” demek değildir, sorun çelişkidir."},{"id":"os-2-s14","tur":"coktan-secmeli","soru":"Lobide kollarını göğsünde kavuşturmuş bir konuk görüyorsun. Hangisi doğru yaklaşımdır?","secenekler":["Kolları bağlamayı savunma işareti sayar, konuğa hiç yaklaşmam ve beklerim","Yalnız yüz ifadesine bakarım, çünkü kolların bir anlamı olmadığını bilirim","Beden dilini yok sayar, yalnız konuğun söylediklerine göre davranırım","Durumu ortamla birlikte değerlendirir, gerekirse “Yardımcı olabilir miyim?” derim"],"dogru":3,"aciklama":"Bir beden hareketi tek başına yorumlanmaz; kolları bağlamak kapanma da olabilir, üşüme de. Anlamı bağlam belirler ve emin olunmadığında kısa bir soru belirsizliği giderir."},{"id":"os-2-s15","tur":"dogru-yanlis","soru":"Göz teması ilgi ve güven gösterir; ama karşıdakine hiç ayırmadan uzun süre sabit bakmak onu rahatsız edebilir.","secenekler":["Doğru","Yanlış"],"dogru":0,"aciklama":"Göz teması ölçülü olduğunda ilgi gösterir. Uzun süre sabit bakış karşı tarafta baskı altında kalma duygusu yaratır."},{"id":"os-2-s16","tur":"dogru-yanlis","soru":"Zaman kazandırdığı için, konuk sözünü bitirmeden çözümü söylemek etkili dinlemenin bir parçasıdır.","secenekler":["Doğru","Yanlış"],"dogru":1,"aciklama":"Söz kesmek yetersiz dinlemedir. Aceleyle sunulan çözüm çoğu zaman konuğun asıl sorununa değil, görevlinin sandığı soruna yöneliktir."},{"id":"os-2-s17","tur":"dogru-yanlis","soru":"Beden dilinin anlamı bütün toplumlarda aynıdır; bu yüzden bir hareket kültüre bakılmadan yorumlanabilir.","secenekler":["Doğru","Yanlış"],"dogru":1,"aciklama":"Bir toplumda olağan sayılan hareket başka toplumda farklı anlaşılabilir. Farklı ülkelerden konuk ağırlayan personel, emin olmadığı hareketi sözle doğrular."},{"id":"os-2-s18","tur":"dogru-yanlis","soru":"Konuğa çok yaklaşmak da çok uzak durmak da iletişimi bozabilir; rahat bir konuşma için dengeli bir mesafe gerekir.","secenekler":["Doğru","Yanlış"],"dogru":0,"aciklama":"Gereğinden fazla yakınlık konuğu rahatsız eder, fazla uzaklık ise soğuk görünür. Uygun mesafe iletişimi dengeli ve rahat tutar."},{"id":"os-2-s19","tur":"senaryo","durum":"Saat 16.00, resepsiyonda stajyersin. Bilgisayarda bir kaydı tamamlamaya çalışırken bir konuk bankoya gelip odasındaki klimadan yakınmaya başlıyor.","soru":"Ne yaparsın?","secenekler":["Yazmayı sürdürerek “Dinliyorum efendim” der, bitirince ilgilenirim.","Kaydı bırakıp konuğa dönerim, sözünü bitirmesini bekler ve anladığımı kendi cümlemle söylerim.","Konuk anlatırken teknik servisi arar, ona bakarak başımla onaylarım.","Konuk bitirmeden “Teknik servisi hemen gönderiyorum” diyerek konuyu kapatırım."],"dogru":1,"aciklama":"Etkili dinleme dikkati konuşana vermek, söz kesmemek ve anlaşıldığını teyit etmektir. Ekrana ya da telefona bakarak dinlemek uygunsuz beden dilidir; çözümü erkenden söylemek ise yanlış soruna cevap vermek demektir."},{"id":"os-2-s20","tur":"senaryo","durum":"Akşam 20.30, otelin restoranında staj yapıyorsun. Salon kalabalık, canlı müzik çalıyor. Dört kişilik masa siparişini verdi, ama ana yemeklerden birini müzik yüzünden tam duyamadın.","soru":"Ne yaparsın?","secenekler":["Duyamadığım yemeği masadakilerin çoğunun seçtiği yemeğe göre yazarım.","Siparişi mutfağa iletir, tabak gelince yanlışsa değiştiririm.","Mutfağa verirken şefe “bir yemek eksik” diye not düşerim.","Duyduğum kısmı tekrarlar, eksik yemeği sorarak siparişi masayla teyit ederim."],"dogru":3,"aciklama":"Gürültülü ortam mesajı bozar; çözüm anlamadığın yeri tahmin etmek yerine açıklayıcı soruyla sormak ve teyit etmektir. Tahmin ya da sonradan düzeltme konuğu bekletir, mutfağa iki kez iş çıkarır."},{"id":"os-2-s21","tur":"senaryo","durum":"Sabah 09.00, resepsiyon çok yoğun. Bir konuk odasında sıcak su akmadığını söylüyor ve ne zaman ilgilenileceğini soruyor. Teknik servisin nerede olduğunu bilmiyorsun.","soru":"Konuğa nasıl karşılık verirsin?","secenekler":["Teknik servisi arayıp geliş süresini öğrenir, konuğa bu bilgiyi söylerim.","“Şu an çok yoğunuz, sırası gelince sizinle de ilgilenilecektir” derim.","“Beş dakikada hallolur efendim” diyerek konuğu hemen rahatlatırım.","“Bilmiyorum, bu konuyu teknik servise sormanız gerekir” derim."],"dogru":0,"aciklama":"Doğru yol öğrenip net bilgi vermektir. Bilmeden süre vermek tutulamayacak söz olduğu için güveni yıkar; “yoğunuz” ve “bilmiyorum” ise konuğu çözümsüz bırakan kaba üslup örnekleridir."},{"id":"os-2-s22","tur":"senaryo","durum":"Akşam 21.50, restoran. Vardiyan 22.00’de bitiyor ve cebindeki telefon titriyor. Masadaki konuk, yarınki doğum günü yemeği için isteklerini uzun uzun anlatıyor.","soru":"Hangisi doğru davranıştır?","secenekler":["Saatime bir kez bakar, vardiyamın bitmek üzere olduğunu kibarca hissettiririm.","Not alırken başımı kaldırmadan “Evet, evet” diyerek anlatmasını sürdürmesini isterim.","Göz teması kurar, başımla ve kısa sözlerle dinlediğimi gösterir, sonda istenenleri özetlerim.","Telefon önemli olabilir diye göz ucuyla ekrana bakarım."],"dogru":2,"aciklama":"Göz teması ilgiyi, baş sallamak ve kısa sözler dönütü gösterir. Saate ya da telefona bakmak sıkılma ve önem vermeme, göz teması kurmadan not almak ilgisizlik mesajı verir."},{"id":"os-2-s23","tur":"senaryo","durum":"Saat 12.00, çıkış saati; resepsiyonda sıra uzadı. Yanındaki stajyer arkadaşın kayıtları yavaş giriyor ve bu seni rahatsız ediyor. Konuklar bankonun hemen önünde bekliyor.","soru":"Ne yaparsın?","secenekler":["Konukların duyacağı biçimde “Biraz hızlı ol, herkes bekliyor” derim.","Bir şey söylemeden klavyeyi önünden alıp kayıtları kendim girerim.","Bankodan ayrılıp durumu ön büro şefine anlatmaya giderim.","Sakin bir sesle “Sıra uzadı, faturaları ben hazırlayayım mı?” derim."],"dogru":3,"aciklama":"Yapıcı dil suçlamaz; çözüm ve iş birliği önerir. Konukların önünde uyarmak arkadaşını kırar, işi elinden almak saygısızlıktır, yoğun anda bankoyu bırakmak ise sırayı daha da uzatır."},{"id":"os-2-s24","tur":"senaryo","durum":"Akşam 19.00, resepsiyon. Bir konuk üzgün bir yüzle gelip içinde ilaçları olan çantasını kaybettiğini anlatıyor. Alışkanlıkla gülümsediğini fark ediyorsun.","soru":"Ne yaparsın?","secenekler":["“Güler yüz esastır” diyerek gülümsememi sürdürürüm.","Yüz ifademi konuğun üzüntüsüne uydurur, ciddi ve ilgili bir yüzle dinlerim.","Moral vermek için “Olur böyle şeyler” diyerek hafif bir şaka yaparım.","Vakit kaybetmemek için yüzüne bakmadan formu doldurmaya başlarım."],"dogru":1,"aciklama":"Empatik beden dili, yüz ifadesini konuğun duygusuna uydurmaktır. Ciddi bir sorunda gülümsemek ya da şaka yapmak derdi hafife almak, yüze bakmadan işlem yapmak ise ilgisizlik olarak okunur."},{"id":"os-2-s31","tur":"coktan-secmeli","soru":"Sıra bekleyen konuğa “Beklediğiniz için teşekkür ederiz” demek ile “Beklettiğimiz için özür dileriz” demek nasıl ayrılır?","secenekler":["Teşekkür sorumluluğu kabul eder, özür ise gösterilen sabrı fark eder","Teşekkür sabrı fark ettiğimizi, özür sorumluluğu kabul ettiğimizi bildirir","İkisi de aynı şeyi bildirir; yalnız söylenme zamanı ve ses tonu farklıdır","Teşekkür yalnız yazılı, özür yalnız sözlü olarak ifade edilebilir"],"dogru":1,"aciklama":"Teşekkür emeği ya da sabrı fark ettiğimizi, özür ise bir rahatsızlığın sorumluluğunu üstlendiğimizi söyler. Durum gerektirdiğinde ikisi birlikte de kullanılabilir."},{"id":"os-2-s32","tur":"coktan-secmeli","soru":"Yeni gelen kat görevlisi Ayşe ile ön büro şefi tanıştırılacak. Doğru cümle hangisidir?","secenekler":["“Ayşe, seni ön büro şefimizle tanıştırayım.”","“Sıra önemli değil; hangisini söylediğin fark etmez.”","“Ön büro şefim, sizi kat görevlimiz Ayşe ile tanıştırayım.”","“Önce kim konuşursa o, ötekine tanıtılır.”"],"dogru":2,"aciklama":"Tanıştırmada genellikle ast olan üste tanıtılır; kat görevlisi ön büro şefine tanıtılır. İlk cümle sırayı ters çevirir: şef, Ayşe’ye tanıtılmış olur. Öteki ikisi de sırayı yok sayar."},{"id":"os-2-s33","tur":"coktan-secmeli","soru":"Genel müdür ile yeni stajyer tanıştırıldıktan sonra tokalaşmayı genellikle kim başlatır?","secenekler":["Genel müdür; çünkü eli genellikle üst konumdaki kişi önce uzatır","Stajyer; çünkü saygıyı göstermek için ilk adımı ast atar","Tanıştırmayı yapan kişi; çünkü iki tarafı da o yönlendirir","Önce davranan kişi; çünkü tokalaşmada kimin uzatacağına dair bir sıra yoktur"],"dogru":0,"aciklama":"Eli genellikle yaşça büyük ya da üst konumdaki kişi önce uzatır; öteki bekler ve uzatılan ele karşılık verir. Bu sıra saygının göstergesidir."},{"id":"os-2-s34","tur":"coktan-secmeli","soru":"Aşağıdaki tokalaşmalardan hangisi etkili el sıkma sayılır?","secenekler":["Elin gevşek ve isteksizce, kavranmadan uzatıldığı bir tokalaşma","Eli sıkıca kavrayıp uzun süre bırakmayan bir tokalaşma","Ele bakmadan yalnız parmak uçlarıyla yapılan bir tokalaşma","Kısa süren, nazik ve kendinden emin; göz teması kurulan tokalaşma"],"dogru":3,"aciklama":"Etkili el sıkma kısa, nazik ve kendinden emindir. Gevşek tokalaşma güvensizlik ya da isteksizlik, gereğinden sert ve uzun tokalaşma ise rahatsızlık izlenimi verir."},{"id":"os-2-s35","tur":"coktan-secmeli","soru":"Telefonda ses tonu ve seçilen sözler yüz yüze konuşmaya göre neden daha belirleyicidir?","secenekler":["Telefon görüşmeleri çoğu zaman kayda alındığı için sözler önem kazanır","Telefonda yalnız resmî konular konuşulduğu için üslup önem kazanır","Karşı taraf beden dilini göremez; duygu ve ilgi yalnız ses ve sözlerle ulaşır","Telefonda dinlemek yerine yalnız konuşmak gerektiği için ses önem kazanır"],"dogru":2,"aciklama":"Telefonda gülümseme, duruş ve göz teması karşıya ulaşmaz. Konuğa verilen mesajı ses tonu, konuşma biçimi ve sözcükler taşır."},{"id":"os-2-s36","tur":"coktan-secmeli","soru":"Telefonu açan görevli selam verdi. Sıradaki doğru adım hangisidir?","secenekler":["Karşıdakinin isteğini dinlemeye geçmek","Kendini ve kurumunu tanıtmak","Gerekli bilgiyi vermek","Teşekkür edip görüşmeyi bitirmek"],"dogru":1,"aciklama":"Telefon görüşmesi selam, kendini ve kurumu tanıtma, dinleme, bilgi verme ve teşekkürle bitirme sırasıyla yürür. Tanıtmadan dinlemeye geçmek arayanı kime konuştuğunu bilmeden bırakır."},{"id":"os-2-s37","tur":"coktan-secmeli","soru":"Telefonda konuğu dinlerken aşağıdakilerden hangisi yanlıştır?","secenekler":["Dikkati başka işe vermeden dinlemek","Araya “Not alıyorum.” gibi kısa sözler koymak","Konuğun isteğini doğru anlamaya çalışmak","Konuk anlatırken sessizce başka bir kaydı yazmak"],"dogru":3,"aciklama":"Telefonda dinlendiğini belli etmenin yolu kısa geri bildirimlerdir; dikkati başka işe vermek ise konuğun isteğinin yanlış anlaşılmasına yol açar. Sessizlik, konuğa dinlenip dinlenmediğini düşündürür."},{"id":"os-2-s38","tur":"coktan-secmeli","soru":"Netiket ile dijital iz arasındaki fark hangisinde doğru verilmiştir?","secenekler":["Netiket çevrim içi davranış kurallarıdır; dijital iz o davranışların bıraktığı kayıttır","Netiket davranışların bıraktığı kayıt, dijital iz ise davranış kurallarıdır","İkisi aynı kavramın iki adıdır","Netiket yalnız e-postada, dijital iz yalnız sosyal medyada geçerlidir"],"dogru":0,"aciklama":"Netiket internet görgü kurallarını, dijital iz ise yapılan paylaşım ve yorumların ardında kalan, uzun süre erişilebilen kaydı anlatır. Biri kural, öteki sonuçtur."},{"id":"os-2-s39","tur":"coktan-secmeli","soru":"Konuğa yazılacak bir mesajı göndermeden önce bir kez daha okumanın en önemli yararı nedir?","secenekler":["Mesajın karşı tarafa daha hızlı ulaşmasını sağlamak","Mesajı okumayı konuk için zorunlu hâle getirmek","İçerik, üslup ve yazım hatalarını göndermeden fark edip düzeltmek","Gönderilen mesajın kaydını daha sonra tümüyle ortadan kaldırabilmek"],"dogru":2,"aciklama":"Yazılı mesajda beden dili ve ses tonu yoktur; yanlış anlaşılmayı önlemenin yolu gönderilmeden önce içerik ve üslubu gözden geçirmektir. Gönderilen mesaj ve paylaşımlar ise iz bırakabilir."},{"id":"os-2-s40","tur":"coktan-secmeli","soru":"Bir stajyer uygunsuz bir paylaşımını birkaç dakika sonra sildi. Bu neden onu tümüyle kurtarmayabilir?","secenekler":["Silinen paylaşım yalnız işletmelerin hesaplarında sayılır","Paylaşımın kaydı silinse bile bir yerde kalıp başkalarınca görülebilir","İnternette yalnız ilk beş dakikadaki paylaşımlar kayda alınır","Silmek, paylaşımı daha çok kişiye gösterir"],"dogru":1,"aciklama":"Dijital iz, paylaşım ve yorumların uzun süre erişilebilir kalabilen kaydıdır. Silmek izi her zaman yok etmez; çevrim içi itibar bu izlerden etkilenir."},{"id":"os-2-s41","tur":"coktan-secmeli","soru":"Oteli temsilen konuk şikâyetine yazılan cevapta hangisi yanlıştır?","secenekler":["Duyguyu vurgulamak için her cümlenin sonuna birkaç emoji koymak","Göndermeden önce yazım ve üslubu bir kez daha okumak","Cevabı yazarken savunmaya geçmeden çözümü anlatmak","Konuğa nazik ve saygılı bir dille hitap etmek"],"dogru":0,"aciklama":"Aşırı ya da yersiz emoji yazışmanın ciddiyetini azaltır ve konuk tarafından ciddiyetsizlik olarak okunabilir. Diğer üçü kurum adına yapılan dijital iletişimin doğru davranışlarıdır."},{"id":"os-2-s42","tur":"coktan-secmeli","soru":"Karşıdaki kişi sağlık, kültür ya da kişisel tercih nedeniyle el sıkmak istemiyorsa doğru davranış hangisidir?","secenekler":["Elimi uzatıp karşılık vermesini beklemek","Selamlaşmayı atlayıp doğrudan işe geçmek","Nedenini sorup açıklama istemek","Israr etmeden söz ve gülümsemeyle selamlamak"],"dogru":3,"aciklama":"El sıkmanın uygun olmadığı durumlarda karşılıklı saygıyla temassız selamlaşma seçilir. Israr etmek ya da hesap sormak nezakete aykırıdır."},{"id":"os-2-s43","tur":"dogru-yanlis","soru":"Telefonda dinlendiğini göstermek için karşı tarafa “anlıyorum” gibi kısa sözler söylemek, konuğun sözünü kesmek sayıldığı için kaçınılması gereken bir davranıştır.","secenekler":["Doğru","Yanlış"],"dogru":1,"aciklama":"Kısa geri bildirimler konuğun sözünü kesmez; telefonda baş sallamanın karşılığıdır ve dinlendiğini belli eder. Söz kesmek ise cümle bitmeden çözüm sunmaktır."},{"id":"os-2-s44","tur":"dogru-yanlis","soru":"Bir konuğun fotoğrafı, adı ya da odası gibi bilgiler, içerik zararsız görünse bile sahibinin izni olmadan paylaşılmamalıdır.","secenekler":["Doğru","Yanlış"],"dogru":0,"aciklama":"Ölçü içeriğin zararsız görünmesi değil, sahibinin iznidir. İzinsiz paylaşım etik ve güvenlik sorunudur; paylaşılan içerik de dijital iz bırakır."},{"id":"os-2-s45","tur":"senaryo","durum":"Saat 09.10, stajının üçüncü günü. Resepsiyonda bilgisayara giriş listesini yazıyorsun. Kapıdan bir konuk girip bankoya doğru yürüyor; yanındaki görevli telefonda.","soru":"Ne yaparsın?","secenekler":["Cümleyi bitirip ardından başımı kaldırır, konuğa selam veririm.","Konuk bankoya varıp bir şey sorana kadar bekler, ilk sözü ona bırakırım.","Başımı kaldırır, göz teması kurup gülümseyerek “Günaydın efendim, hoş geldiniz” derim.","Başımı kaldırmadan “Arkadaşım birazdan ilgilenecek” diye seslenirim."],"dogru":2,"aciklama":"Konuğu ilk gören personel selamı önce verir; göz teması ve güler yüzle ilk izlenim kurulur. Konuğu bekletmek ya da ekrana bakarak seslenmek “önemsenmiyorum” duygusu yaratır."},{"id":"os-2-s46","tur":"senaryo","durum":"Saat 10.00. Ön büro müdürü seni genel müdürün odasına götürüp tanıştırıyor. Genel müdür ayağa kalkmış, sana bakıp gülümsüyor; elini henüz uzatmadı.","soru":"Nasıl davranırsın?","secenekler":["Göz teması kurup selam veririm; elini uzatırsa kısa ve dengeli sıkarım.","Saygımı göstermek için hemen elimi uzatır, sıkıca kavrarım.","Yere bakarak başımla selam verir, bana bir şey sorulmasını beklerim.","Rahat görünmek için “Merhaba, nasılsınız?” deyip omzuna dokunurum."],"dogru":0,"aciklama":"Eli genellikle üst konumdaki kişi önce uzatır; ast bekler ve kısa, nazik, kendinden emin bir tokalaşmayla karşılık verir. Önce davranmak, sert sıkmak ya da göz temasından kaçmak olumsuz izlenim bırakır."},{"id":"os-2-s47","tur":"senaryo","durum":"Saat 16.20, ön büro. Bir giriş kaydını tamamlamak üzereyken şefinin isteğiyle çalan telefonu açtın. Arayan konuk rezervasyonunda bir yanlışlık olduğunu düşünüyor ve hızlı hızlı anlatıyor.","soru":"Nasıl davranırsın?","secenekler":["Konuğa “Bir saniye” diyip kaydı bitirir, sonra dinlerim.","Arada “Evet” derken kaydı tamamlamayı sürdürürüm.","Konuyu bilmediğimi söyler, şefin aramasını rica ederim.","Kaydı bırakır, kısa geri bildirimler vererek sonuna kadar dinlerim."],"dogru":3,"aciklama":"Telefonda dikkat başka işe verilmeden dinlenir ve kısa sözlerle dinlendiği belli edilir. Kaydı yazarken dinleyen görevli isteği yarım anlar; konuğu bir başkasına yönlendirmek ise sorunu çözmez."},{"id":"os-2-s48","tur":"senaryo","durum":"Akşam 21.00. Otelin sosyal medya hesabına bakan görevliye yardım ediyorsun. Bir konuk herkesin gördüğü bir yoruma “İKİ GÜNDÜR KLİMA BOZUK, REZALET!” yazmış. Görevli cevap taslağını senin hazırlamanı istiyor.","soru":"Hangi taslağı yazarsın?","secenekler":["“Lütfen büyük harfle yazmayınız, sizi anlıyoruz.”","“Özür dileriz; teknik ekibimizi hemen odanıza yönlendiriyoruz.”","“Klimamız dün kontrol edildi, bir sorun görünmüyordu efendim.”","“YAŞANAN AKSAKLIK İÇİN ÇOK ÜZGÜNÜZ!”"],"dogru":1,"aciklama":"Kurum adına yazılan cevap nazik, profesyonel ve çözüm odaklı olur. Konuğa üslup dersi vermek ya da savunmaya geçmek tartışmayı büyütür; büyük harfli cevap ise bağırmaya bağırmayla karşılık vermektir."},{"id":"os-2-s49","tur":"senaryo","durum":"Saat 13.00, havuz başında servise yardım ediyorsun. Otelde ünlü bir futbolcunun kaldığını fark ediyorsun. Sınıf grubundaki arkadaşların “Fotoğrafını çek, at!” diye yazıyor.","soru":"Ne yaparsın?","secenekler":["Fotoğraf çekmem; konuğun kim olduğunu ve odasını da kimseyle paylaşmam.","Uzaktan, fark ettirmeden çekip yalnız sınıf grubuna gönderirim.","Fotoğraf çekmem, ama hangi odada kaldığını gruba yazarım.","Çekerim, yüzünü kapatıp otelin adıyla hikâyemde paylaşırım."],"dogru":0,"aciklama":"Konuğun fotoğrafı, kim olduğu ve odası kişisel bilgidir; sahibinin izni olmadan paylaşılmaz. “Yalnız gruba” atılan içerik de çoğalır ve kalıcı olur; konuğun güvenini ve otelin adını zedeler."},{"id":"os-2-s50","tur":"senaryo","durum":"Mesai bitti, personel soyunma odasındasın. Arkadaşın, üniformalıyken zor bir konuğun taklidini yaptığın bir video çekmiş. “Çok komik oldu, paylaşalım, akşama sileriz” diyor.","soru":"Ne yaparsın?","secenekler":["Paylaşırım, akşam olunca da hemen silerim.","Yalnız yakın arkadaşlarımın göreceği biçimde paylaşırım.","Paylaşmam; arkadaşımdan videoyu silmesini rica ederim.","Otelin adını yazmadan, yüzümü kapatarak paylaşırım."],"dogru":2,"aciklama":"İnternete yüklenen içerik silinse bile bir yerde kalabilir; dijital iz kalıcıdır. Üniformayla yapılan paylaşım oteli de bağlar, konukla alay eden bir video kendi itibarını da otelin itibarını da zedeler."},{"id":"os-2-s51","tur":"coktan-secmeli","soru":"Resepsiyonda kendisinden yaşça küçük bir konuğa seslenen stajyerin hangi cümlesi otel diline uygundur?","secenekler":["“Abi, oda numaran kaçtı, bir bakayım?”","“Mehmet Bey, kartınız hazır efendim.”","“Canım, kartını şuraya bırakır mısın?”","“Sen 205’te kalıyordun, değil mi?”"],"dogru":1,"aciklama":"Konuğa yaşı ne olursa olsun “siz” denir; adı biliniyorsa “Bey” ya da “Hanım” diye seslenilir. “Abi”, “canım” gibi sözler ve “sen” hitabı otel dilinde yer almaz."},{"id":"os-2-s52","tur":"coktan-secmeli","soru":"Staj görüşmesindeki öğrenci, görüşmecinin elini parmak uçlarından tutup hemen bırakıyor. Bu tokalaşma karşı tarafta en çok hangi izlenimi bırakabilir?","secenekler":["Güvensizlik ya da isteksizlik","Baskı kurmak isteyen sert bir tavır","Ölçüsüz bir samimiyet ve rahatlık","Özgüven ve kararlılık"],"dogru":0,"aciklama":"Gevşek ve kavramadan yapılan zayıf el sıkma güvensizlik ya da isteksizlik olarak algılanabilir. Sertlik ve baskı izlenimi ise aşırı güçlü el sıkmaya aittir."},{"id":"os-2-s53","tur":"dogru-yanlis","soru":"Tokalaşmada elin sert sıkılıp uzun süre bırakılmaması kendinden emin olmayı gösterdiği için karşı tarafta olumlu izlenim bırakır.","secenekler":["Doğru","Yanlış"],"dogru":1,"aciklama":"Gereğinden sert ya da uzun el sıkma karşıdakini rahatsız eder ve iletişim başlamadan olumsuz izlenim doğurur. Ölçü dengedir: ne gevşek ne sert, ne uzun ne aceleci."},{"id":"os-2-s54","tur":"coktan-secmeli","soru":"Konuğun oteli telefonla araması, lobiye girmesi ve kahvaltı salonunda karşılanması gibi temasların her birine sektörde ne ad verilir?","secenekler":["Nezaket araması","Kısa sohbet","Gerçek anı","Konuk karşılama"],"dogru":2,"aciklama":"Konuğun işletmeyle karşılaştığı ve hizmet hakkında kanı edindiği her temas anı “gerçek anı”dır. Konuk karşılama bu anlardan yalnız biridir, hepsini kapsamaz."},{"id":"os-2-s55","tur":"coktan-secmeli","soru":"Konuk deniz manzaralı oda istiyor; bu gece boş oda yok, yarın öğlen bir tane boşalacak. Görevlinin hangi cevabı olumlu dile örnektir?","secenekler":["“Deniz manzaralı odamız kalmadı, isterseniz başka bir otele bakabilirsiniz.”","“Deniz manzaralı oda vermek mümkün değil efendim, kusura bakmayın.”","“Merak etmeyin, akşama kadar mutlaka bir oda boşalır.”","“Bu gece bahçe manzaralı oda hazır, yarın deniz manzaralıya geçelim mi?”"],"dogru":3,"aciklama":"Olumlu dil yapılamayanı değil yapılabileceği söyler ve olumsuz cevabın yanına bir seçenek koyar. “Mutlaka boşalır” demek ise olmayan bir şey için söz vermektir."},{"id":"os-2-s56","tur":"coktan-secmeli","soru":"Restoranda konuğa yanlış tabak geldi. Garsonun hangi cevabı çözüm odaklı yaklaşıma örnektir?","secenekler":["“Mutfak karıştırmış efendim, ben doğru yazmıştım.”","“Özür dilerim, hemen doğrusunu getiriyorum.”","“Siparişi siz mi yanlış söylediniz acaba?”","“Şu an çok yoğunuz, biraz beklemeniz gerekecek.”"],"dogru":1,"aciklama":"Çözüm odaklı yaklaşım hatanın kimde olduğuna değil, sorunun nasıl giderileceğine yoğunlaşır. Mutfağı ya da konuğu suçlayan cevaplar sorunu çözmez, büyütür."},{"id":"os-2-s57","tur":"coktan-secmeli","soru":"Hesabını inceleyen konuk bir satırda durup kaşlarını çatıyor. Görevli için en uygun davranış hangisidir?","secenekler":["Konuk bir şey söylemedikçe hiç tepki vermemek","Uzaklaşıp konuğun sakinleşmesini beklemek","Sormasını beklemeden satırı açıklamak","Bu ifadeyi kesin öfke sayıp hemen müdürü çağırmak"],"dogru":2,"aciklama":"Konukta görülen kaş çatma bir sorun olabileceğinin ilk işaretidir, bu yüzden ilgilenilir. Ama her zaman kızgınlık anlamına gelmez; konuk yalnızca bir şeyi anlamaya çalışıyor olabilir."},{"id":"os-2-s58","tur":"coktan-secmeli","soru":"Odasının manzarasını öğrenen konuk “Peki” derken dudaklarını büzüyor. Bu yüz ifadesi görevliye en çok neyi düşündürmelidir?","secenekler":["Manzarayı çok beğenip heyecanlandığını","Görevliye güvenip rahatladığını","Konunun onun için hiç önemli olmadığını","Durumdan memnun kalmamış olabileceğini"],"dogru":3,"aciklama":"Dudak büzmek çoğu zaman beğenmeme, kararsızlık ya da memnuniyetsizlik anlatır. Konuk bunu söze dökmese de mimiği okuyan görevli başka bir seçenek sunarak sorunu şikâyete dönüşmeden çözer."},{"id":"os-2-s59","tur":"coktan-secmeli","soru":"Aynı “Buyurun” sözü gülümseyerek ve sakin sesle söylenince davet, sert bir sesle söylenince “Ne istiyorsun?” gibi algılanıyor. Bu fark hangi kavramla açıklanır?","secenekler":["Üslup","Sade dil","Dönüt","Teyit etme"],"dogru":0,"aciklama":"Üslup, seçilen sözcüklerle ses tonunun birlikte oluşturduğu anlatım biçimidir ve iletişimin yönünü belirler. Sade dil ise mesajın kısa ve anlaşılır olmasıyla ilgilidir, söyleyiş biçimiyle değil."},{"id":"os-2-s60","tur":"coktan-secmeli","soru":"Ertesi sabah gelecek bir grubun özel istekleri gibi sonradan gerekecek bir bilgi vardiya arkadaşına en doğru hangi yolla iletilir?","secenekler":["Koridorda karşılaşınca ağızdan söyleyerek","Yazılı bir notla ya da kayıtla","Telsizden kısa bir anonsla","Molada hatırlandığı kadarıyla anlatarak"],"dogru":1,"aciklama":"İletişim kanalı işe göre seçilir: acil iş telefonla, sonradan gerekecek bilgi yazıyla iletilir. Ağızdan aktarılan bilgi unutulabilir ya da eksik kalabilir."},{"id":"os-2-s61","tur":"dogru-yanlis","soru":"Yoğun saatlerde soru soran konuğa sert çıkışmak, işin yoğunluğu geçerli bir gerekçe olduğu için hoş görülebilir.","secenekler":["Doğru","Yanlış"],"dogru":1,"aciklama":"Yoğunluk bir gerekçe değildir; konuk görevlinin kaçıncı işiyle uğraştığını bilmez, yalnız sesini duyar. Sakin ve kontrollü kalmak mesleğin parçasıdır."},{"id":"os-2-s62","tur":"coktan-secmeli","soru":"Konuk “Akşam için masa istiyorum” diyor. Görevlinin etkili dinlemeye en uygun ilk karşılığı hangisidir?","secenekler":["“Tamam efendim, size iki kişilik bir masa ayırıyorum.”","“Akşamları genelde dolu oluyoruz, bilemiyorum.”","“Kaç kişi ve saat kaçta gelmeyi düşünüyorsunuz?”","“Saat sekiz uygundur herhalde, öyle yazıyorum.”"],"dogru":2,"aciklama":"Eksik kalan bilgi tahmin edilmez, kısa bir soruyla açığa kavuşturulur. Kişi sayısını ya da saati kendi kafasına göre yazan görevli yanlış masa ve yanlış saatle karşılaşır."},{"id":"os-2-s63","tur":"coktan-secmeli","soru":"Telefonda ayrı yataklı oda isteyen konuğun isteği tekrar edilmeden kaydedildi ve konuğa tek büyük yataklı oda ayrıldı. Burada hangi iletişim hatası yapılmıştır?","secenekler":["Saygısız ve kaba üslup","Duygusal tepkiyi kontrol edememek","Empati kurmamak","Geri bildirim vermemek"],"dogru":3,"aciklama":"İsteği tekrar ederek anladığını göstermemek geri bildirim vermemek hatasıdır ve hatalı işleme yol açar. Görevli kaba ya da öfkeli davranmadığı için öteki hatalar bu duruma uymaz."},{"id":"os-2-s64","tur":"coktan-secmeli","soru":"Telefondaki konuğun rezervasyonunu kontrol etmek için onu kısa süre hatta bekletmesi gereken görevli ne yapmalıdır?","secenekler":["İzin isteyip nedenini söyler, dönünce teşekkür eder","Bir şey demeden hattı bekletir, hızla kontrol eder","Konuktan bir saat sonra tekrar aramasını rica eder","Bilgiyi bulana dek konuğu hiç açıklama yapmadan hatta tutar"],"dogru":0,"aciklama":"Konuk izin istenmeden beklemeye alınmaz; neden bekleyeceği söylenir, hatta dönülünce teşekkür edilir. Habersiz bekletilen konuk çoğu zaman telefonu kapatır."},{"id":"os-2-s65","tur":"coktan-secmeli","soru":"Telefonda konuğun sorusu cevaplandı. Görüşmenin sonunda hangisi yapılmalıdır?","secenekler":["Konuk sustuğu anda hemen telefonu kapatmak","Başka isteğini sorup teşekkürle bitirmek","Otelin bütün olanaklarını sırayla anlatmak","“Tamam” deyip konuğun kapatmasını beklemek"],"dogru":1,"aciklama":"Görüşme teşekkür ve iyi dilekle bitirilir; son cümle akılda kalan cümledir. Bütün olanakları saymak ise görüşmeyi gereksiz yere uzatır."},{"id":"os-2-s66","tur":"dogru-yanlis","soru":"Telefonda kısa ve öz konuşmak, konuğa istediği bilgiyi eksik verip görüşmeyi aceleyle bitirmek anlamına gelir.","secenekler":["Doğru","Yanlış"],"dogru":1,"aciklama":"Kısa konuşmak aceleci konuşmak değildir: konuk bilgisini eksiksiz alır, yalnız söz gereksiz yere dolandırılmaz."},{"id":"os-2-s67","tur":"dogru-yanlis","soru":"Konuğa servis saatini yazacak görevli saatten emin değilse, yanlış bilgi vermektense “Kontrol edip size dönüyorum” demelidir.","secenekler":["Doğru","Yanlış"],"dogru":0,"aciklama":"Konuğa yanlış bilgi yazmak geç yazmaktan kötüdür; yanlış servis saati konuğu mağdur eder. Emin olunmayan bilgi önce kontrol edilir."},{"id":"os-2-s68","tur":"dogru-yanlis","soru":"Yazılı mesajda ses tonu ve beden dili olmadığı için tek kelimelik “Olmaz.” cevabı konuğa ters bir cevap gibi gelebilir.","secenekler":["Doğru","Yanlış"],"dogru":0,"aciklama":"Yazıda ses tonu ve beden dili yoktur; okuyan kişi boşluğu kendi yorumuyla doldurur. Bu yüzden konuğa giden mesajda bilgi açık ve nazik cümlelerle verilir."},{"id":"os-2-s69","tur":"coktan-secmeli","soru":"Tatil planlayan bir aile, otelin sosyal medyada bir şikâyete verdiği sabırlı ve çözüm öneren cevabı okuyup “Bu otel konuğunu dinliyor” diye düşünüyor. Bu durum en çok hangi kavramla ilgilidir?","secenekler":["Dijital kimlik","Netiket","Çevrim içi itibar","Doğru bilgi paylaşma"],"dogru":2,"aciklama":"Bir işletmenin internetteki paylaşım ve cevaplarla başkalarının gözünde kazandığı saygınlık çevrim içi itibardır. Dijital kimlik ise kişinin internetteki izlerinden oluşan portresidir."},{"id":"os-2-s70","tur":"coktan-secmeli","soru":"Cevabı gecikti diye konuğa transfer bilgisini birkaç dakika arayla üç kez yazan stajyer hangi netiket hatasını yapmıştır?","secenekler":["Mesajın tamamını büyük harfle yazmak","Konuğun bilgilerini izinsiz paylaşmak","Yazışmada yersiz ve aşırı emoji kullanmak","Gereksiz ve yinelenen mesaj göndermek"],"dogru":3,"aciklama":"Art arda yinelenen mesaj okuyanın zamanını alır ve sabırsızlık olarak algılanır. Stajyer büyük harf ya da emoji kullanmadığı için öteki şıklar bu duruma uymaz."},{"id":"os-2-s71","tur":"coktan-secmeli","soru":"Uzun vardiyasının sonunda yorgun olan bellboy, son gelen konuğu da sabah ilk geleni karşıladığı özenle karşılıyor. Bu davranış en çok hangi kavrama örnektir?","secenekler":["Profesyonel nezaket","Kısa sohbet","Söz ile beden dilinin uyumu","Olumlu dil"],"dogru":0,"aciklama":"Profesyonel nezaket, güler yüzlü karşılamanın ve saygılı hitabın o günkü keyfe bırakılmadan her konuğa, her gün aynı özenle gösterilmesidir."}],"siralamalar":[{"id":"os-2-r01","konu":"2.1.1","baslik":"Bir mesajın yolculuğu","yonerge":"Etkili bir iletişim sürecinin aşamalarını doğru sıraya koy.","adimlar":["Konuşan kişi mesajını açık ve anlaşılır biçimde iletir.","Karşıdaki kişi mesajı dikkatle dinler.","Dinleyen kişi mesajın anlamını doğru kurar.","Dinleyen kişi mesaja uygun sözlü ya da sözsüz bir tepki verir."],"aciklama":"Mesaj iletilmeden dinlenemez, dinlenmeden anlaşılamaz, anlaşılmadan da uygun tepki verilemez. Aşamalardan biri eksik kalırsa iletişim tamamlanmış sayılmaz."},{"id":"os-2-r02","konu":"2.1.1","baslik":"Resepsiyonda klima şikâyeti","yonerge":"Odasındaki klimadan şikâyet eden konukla ilgilenirken izleyeceğin adımları doğru sıraya koy.","adimlar":["Bilgisayardaki işini bırak, konuğa dön ve göz teması kurarak onu sözünü kesmeden sonuna kadar dinle.","Sorunu kendi cümlelerinle özetleyerek doğru anladığını teyit et.","Sorunla hemen ilgileneceğini söyle ve çözüm için harekete geç."],"aciklama":"Konuğu sonuna kadar dinlemeden özetlenecek bir şey olmaz. Sorun teyit edilmeden çözüme geçmek de yanlış işlem yapılmasına yol açar."},{"id":"os-2-r03","konu":"2.3.3","baslik":"Otelin telefonu çalıyor","yonerge":"Konuktan gelen bir telefon görüşmesinin adımlarını doğru sıraya koy.","adimlar":["Konuğu uygun bir selamlama sözüyle karşıla ve adını, otelin adını söyleyerek kendini tanıt.","Konuğu sözünü kesmeden dinle ve gereken bilgileri al.","Konuğun sorusuna ya da isteğine ilişkin açık bir açıklama yap.","Teşekkür et ve görüşmeyi uygun bir iyi dilek sözüyle kapat."],"aciklama":"Telefonda karşı taraf seni göremediği için görüşme selam ve tanıtmayla güven vererek açılır. İstek dinlenip anlaşıldıktan sonra açıklama yapılır, görüşme de teşekkürle kapanır."}]},{"ders":"otelcilik-seyahat","sinif":9,"unite":3,"baslik":"Temel Konaklama Hizmetleri","onay":true,"kazanimlar":["Konaklama işletmelerinin ana departmanlarını ve birbirleriyle ilişkilerini açıklar.","Ön büro departmanında temel düzeydeki iş ve işlemleri yürütür.","Kat hizmetleri departmanında temel düzeydeki iş ve işlemleri yürütür.","Eğlence hizmetleri departmanında temel düzeydeki iş ve işlemleri yürütür.","Konaklama işletmelerinde departmanların özelliğine göre iş planı yapar."],"soz":"Otel tek bir sahne gibidir: ön büro karşılar, kat hizmetleri hazırlar, etkinlik ekibi gülümsetir.","dersler":[{"baslik":"Moyanlıktan Kervansaraya","ilk":"os-3-400"},{"baslik":"Evinden Uzakta Bir Çatı","ilk":"os-3-001"},{"baslik":"Çadırdan Dağ Evine","ilk":"os-3-008"},{"baslik":"Otelde Kim Kime Bağlı?","ilk":"os-3-014"},{"baslik":"Sahnedekiler ve Sahne Arkası","ilk":"os-3-018"},{"baslik":"Otelin Beyni ve Düzeni","ilk":"os-3-022"},{"baslik":"Odadan Sonra En Büyük Gelir","ilk":"os-3-024"},{"baslik":"Lobi Bardan Oda Servisine","ilk":"os-3-029"},{"baslik":"Mutfağın Perde Arkası","ilk":"os-3-033"},{"baslik":"Tabak Salona Çıkmadan Önce","ilk":"os-3-038"},{"baslik":"Eğlence Tesadüfe Bırakılmaz","ilk":"os-3-042"},{"baslik":"Paranın İzini Kim Sürer?","ilk":"os-3-044"},{"baslik":"Doğru İşe Doğru Kişi","ilk":"os-3-049"},{"baslik":"İyi Personel Nasıl Elde Tutulur?","ilk":"os-3-052"},{"baslik":"Görünmeyen Kahramanlar","ilk":"os-3-056"},{"baslik":"Otelin Orkestra Şefi","ilk":"os-3-100"},{"baslik":"Bankonun Önü, Bankonun Arkası","ilk":"os-3-104"},{"baslik":"Sektörün Dili: Gelen, Gelmeyen, Fazla Satılan","ilk":"os-3-107"},{"baslik":"Küçük Otel, Büyük Otel","ilk":"os-3-111"},{"baslik":"Altı Birim, Tek Ekip","ilk":"os-3-115"},{"baslik":"Bankoya Kim Yakışır?","ilk":"os-3-121"},{"baslik":"Yönetenler","ilk":"os-3-125"},{"baslik":"Bankodaki ve Kapıdaki Yüzler","ilk":"os-3-130"},{"baslik":"Valizden Vale’ye","ilk":"os-3-133"},{"baslik":"Gece Vardiyasında Kim Uyanık?","ilk":"os-3-413"},{"baslik":"Bankonun Üstündekiler","ilk":"os-3-135"},{"baslik":"Anahtarlar, Kartlar, Raflar","ilk":"os-3-140"},{"baslik":"Lobide Gözün Gördükleri","ilk":"os-3-145"},{"baslik":"İlk Kâğıtlar, İlk İmza","ilk":"os-3-149"},{"baslik":"Kimlik, Veri ve Özel Konuk","ilk":"os-3-153"},{"baslik":"Konuğun Geçici Cüzdanı","ilk":"os-3-156"},{"baslik":"Vedadan Sonra Kalanlar","ilk":"os-3-159"},{"baslik":"Otelin Sinir Merkezi","ilk":"os-3-162"},{"baslik":"Kim Kime Ne Bildirir?","ilk":"os-3-166"},{"baslik":"Kaç Kişi, Kaç Yatak?","ilk":"os-3-169"},{"baslik":"Bir Odadan Fazlası","ilk":"os-3-175"},{"baslik":"Manzaranın Fiyatı","ilk":"os-3-180"},{"baslik":"Otelin Kalbi Nerede Atar?","ilk":"os-3-200"},{"baslik":"Dört Birim, Dört Değer","ilk":"os-3-205"},{"baslik":"Görünmez Kahramanlar","ilk":"os-3-209"},{"baslik":"Odaya “Hazır” Diyen Kim?","ilk":"os-3-214"},{"baslik":"Bir Çarşafın Yolculuğu","ilk":"os-3-220"},{"baslik":"Doğru İşe Doğru Donanım","ilk":"os-3-225"},{"baslik":"Tekerlekli Depo","ilk":"os-3-229"},{"baslik":"Kırmızı Bez Masaya Değerse","ilk":"os-3-233"},{"baslik":"Önce Güvenlik, Sonra Temizlik","ilk":"os-3-237"},{"baslik":"Makine Çalışmadan Önce","ilk":"os-3-241"},{"baslik":"Odanın Durumu Üç Harfte","ilk":"os-3-244"},{"baslik":"Yatak Hiç Bozulmamışsa?","ilk":"os-3-250"},{"baslik":"“Altın” Değil, “Sarı Renkli Metal”","ilk":"os-3-256"},{"baslik":"Damlayan Musluk Kimin İşi?","ilk":"os-3-260"},{"baslik":"Tek Başına Otel Olmaz","ilk":"os-3-264"},{"baslik":"Kapıyı Kaç Kez Çalarsın?","ilk":"os-3-269"},{"baslik":"Zarf Gibi Köşe","ilk":"os-3-276"},{"baslik":"Kapıya Doğru Sil","ilk":"os-3-280"},{"baslik":"Çekçek Neyi Çeker?","ilk":"os-3-423"},{"baslik":"Tatili Anıya Çeviren Ekip","ilk":"os-3-300"},{"baslik":"Üç Otel, Üç Ayrı Ekip","ilk":"os-3-304"},{"baslik":"Çocuk, Genç, Sporcu: Herkese Bir Yer","ilk":"os-3-309"},{"baslik":"Sahnenin Önü ve Arkası","ilk":"os-3-315"},{"baslik":"Otelin Vitrini Sensin","ilk":"os-3-320"},{"baslik":"Programı Kim Yazar, Kim Uygular?","ilk":"os-3-324"},{"baslik":"Havuz Başından Çocuk Kulübüne","ilk":"os-3-327"},{"baslik":"Perde Açılmadan Önce","ilk":"os-3-331"},{"baslik":"Ses, Işık, Kostüm, Top","ilk":"os-3-337"},{"baslik":"İmzasız Olmaz: Etkinliğin Formları","ilk":"os-3-347"},{"baslik":"Bir Gösteri, Altı Departman","ilk":"os-3-353"},{"baslik":"Hedefin Yoksa Planın da Yok","ilk":"os-3-360"},{"baslik":"Otel Hiç Uyumaz","ilk":"os-3-364"},{"baslik":"Resepsiyonun Bir Günü","ilk":"os-3-368"},{"baslik":"Oda Kalmadıysa Ne Olur?","ilk":"os-3-372"},{"baslik":"Temizliğin Takvimi","ilk":"os-3-377"},{"baslik":"Her Gün mü, Yılda Bir mi?","ilk":"os-3-383"},{"baslik":"Bir Düğün Nasıl Planlanır?","ilk":"os-3-389"},{"baslik":"Ya Yağmur Yağarsa?","ilk":"os-3-393"}],"kavramlar":[{"id":"os-3-400","konu":"3.1","terim":"Moyanlık ve ribat","ingilizce":"Moyanlık and ribat (early Turkish hospitality houses)","tanim":"Ders kitabına göre Orhun Kitabeleri’nde geçen, yolculara hayır amacıyla barınak sağlayan ilk konaklama anlayışını ve onun Karahanlı, Gazneli ve Selçuklu dönemindeki devamı olan yapıları anlatan terimdir.","ornek":"Karlı bir kış akşamı yolda kalan bir tüccar, ücret ödemeden geceyi geçirebileceği bir yapıya sığınır; ona sıcak yemek verilir, hayvanına da bakılır.","sektor":"Ders kitabı bugünkü otelciliğin köklerini bu anlayışa bağlar: konuğu ağırlamak ticaretten önce bir değerdi. Anlayış önce ribatlara, sonra kervansaraylara dönüşmüştür; sıralama kısaca moyanlık, ribat, kervansaray biçimindedir. Konuk ağırlayan her meslek bu geleneğin devamıdır.","iliskili":["os-3-401","os-3-001"],"kontrol":null,"gorsel":"h3a-moyanlik-ve-ribat"},{"id":"os-3-401","konu":"3.1","terim":"Han ve kervansaray geleneği","ingilizce":"Han and caravanserai tradition","tanim":"Ticaret yolları üzerinde yolculara ve hayvanlarına barınma, yeme içme ve güvenlik sunan, bugün çoğu restore edilen tarihî konaklama yapılarıdır.","ornek":"İpek Yolu’ndaki bir kervansarayda akşam olunca yolcular geceyi güvenle geçirir; bir kısmı ibadet eder, hayvanlar ise ahırda dinlenir.","sektor":"Ders kitabına göre kervansaraylar din, dil, ırk ve sosyal statü ayrımı gözetmeden yolculara yeme içme, barınma, hayvan bakımı, güvenlik, ibadet, eğitim, posta ve ticaret hizmetleri sunmuştur; ücretsiz konaklama belirli bir süreyle sınırlıydı. Deniz ticareti geliştikçe kara yolu ticareti önemini yitirmiş, ama hanlar ve kervansaraylar bugün restore edilerek kültürel miras ve konaklama tesisi olarak sürmektedir. Modern otel aynı hizmetlerin çoğunu ücret karşılığında ve çok daha fazla konforla sunar.","iliskili":["os-3-400","os-3-001"],"kontrol":null,"gorsel":"ic2-zazadin-han"},{"id":"os-3-001","konu":"3.1","terim":"Konaklama işletmesi","ingilizce":"Accommodation establishment","tanim":"İnsanların evlerinden uzakta oldukları sürede barınma, dinlenme ve çoğu zaman yeme içme ihtiyaçlarını ücret karşılığında karşılayan ticari kuruluştur.","ornek":"Gece 23.30, Afyonkarahisar: Antalya’ya giden bir aile yolda yorulur, şehir merkezindeki bir otele girip bir gecelik oda tutar; sabah kahvaltıdan sonra yola devam eder.","sektor":"İnsanlar tatil, iş, sağlık ya da spor gibi farklı nedenlerle yolculuk eder; bu yüzden konaklama işletmeleri de çeşitlenir. Ders kitabı onları iki gruba ayırır: temel ve yardımcı konaklama işletmeleri.","iliskili":["os-3-002","os-3-008","os-3-003"],"kontrol":null,"gorsel":"h3a-konaklama-isletmesi"},{"id":"os-3-002","konu":"3.1","terim":"Temel konaklama işletmeleri","ingilizce":"Main accommodation establishments","tanim":"Asıl işi konuğa geceleme hizmeti vermek olan otel, motel, pansiyon, tatil köyü ve butik otelin oluşturduğu gruptur.","ornek":"Kapadokya’ya giden bir çift kayadan oyma odaları olan küçük bir butik oteli, dört kişilik bir aile ise Side’de bir tatil köyünü seçer; ikisi de temel konaklama işletmesidir.","sektor":"Staj ve iş için karşına çıkacak tesislerin çoğu bu gruptadır. Türü bilmek, konuğun ne beklediğini bilmektir: motelde hız ve otopark, butik otelde kişiye özel ilgi, tatil köyünde gün boyu etkinlik aranır.","iliskili":["os-3-001","os-3-003","os-3-008"],"kontrol":null},{"id":"os-3-003","konu":"3.1","terim":"Otel","ingilizce":"Hotel","tanim":"Asıl işlevi konukların konaklama ihtiyacını karşılamak olan; bunun yanında yeme içme, toplantı, kutlama, spor ve eğlence birimleri de bulundurabilen tesistir.","ornek":"Sabah 08.00, Ankara: bir otelin üst katlarında konuklar uyanırken restoranda kahvaltı servisi sürer, toplantı salonunda ise bir şirketin eğitimi için masalar hazırlanır.","sektor":"Otelde hizmet tek bir kişinin işi değildir; oda, yemek, toplantı ve eğlence ayrı ekiplerce üretilir. Bu yüzden otel büyüdükçe departman sayısı da artar; bu birimde öğreneceğin organizasyon yapısı en açık hâliyle otelde görülür.","iliskili":["os-3-002","os-3-007","os-3-015"],"kontrol":null,"gorsel":"t13e-balkonlu-otel-binasi"},{"id":"os-3-004","konu":"3.1","terim":"Motel","ingilizce":"Motel","tanim":"Kara yolu güzergâhında ya da yakınında kurulan; aracıyla yolculuk edenlerin konaklama, yeme içme ve park ihtiyacını karşılayan tesistir.","ornek":"Gece 01.00, Bolu Dağı yolu: uykusu gelen bir sürücü ana yoldan çıkmadan ulaştığı motele girer, aracını odasının önüne park eder ve sabah erkenden yola koyulur.","sektor":"Motel konuğu çoğu zaman tek gece kalır ve yoluna devam eder. Ondan beklenen uzun bir tatil programı değil; kolay ulaşım, güvenli otopark, temiz bir yatak ve hızlı işlemdir. Ders kitabına göre motel en az 10 odalı bir tesistir.","iliskili":["os-3-002","os-3-003"],"kontrol":null,"gorsel":"h3a-motel"},{"id":"os-3-005","konu":"3.1","terim":"Pansiyon","ingilizce":"Guesthouse","tanim":"Yönetimi basit ve oda sayısı az olan; yemeğin işletmece verilebildiği ya da konuğun kendi yemeğini hazırlayabildiği konaklama tesisidir.","ornek":"Sabah 08.30, Amasra: aile pansiyonunun sahibi bahçedeki masaya kahvaltıyı kendi eliyle getirir; akşam konuklar ortak mutfakta balıklarını kendileri pişirir.","sektor":"Pansiyonda çoğu zaman departman yoktur: karşılama, temizlik ve kahvaltı birkaç kişinin, hatta bir ailenin elindedir. Konuk burada lüks değil, sıcak ve samimi bir ev ortamı arar. Ders kitabına göre pansiyon en az 5, en fazla 25 odalıdır.","iliskili":["os-3-002","os-3-014"],"kontrol":null},{"id":"os-3-006","konu":"3.1","terim":"Tatil köyü","ingilizce":"Holiday village","tanim":"Doğal güzellikler içinde geniş bir alana kurulan; konaklama ve yeme içmenin yanında spor ve eğlence imkânları da sunan tesistir.","ornek":"Saat 10.00, Belek: konuklardan biri tenis kortuna, biri su jimnastiğine gider, çocuklar mini kulübe bırakılır; akşam hepsi amfi tiyatrodaki gösteride buluşur.","sektor":"Konuk tatilinin neredeyse tamamını tesisin içinde geçirir. Bu yüzden etkinlik hizmetleri ile yiyecek içecek departmanları burada çok büyüktür ve çok sayıda personel çalıştırır.","iliskili":["os-3-002","os-3-042"],"kontrol":null,"gorsel":"tatil-koyu"},{"id":"os-3-007","konu":"3.1","terim":"Butik otel","ingilizce":"Boutique hotel","tanim":"Özgün bir tasarımı olan, az sayıda odasıyla konuğa kişiye özel ve yüksek standartta hizmet veren oteldir.","ornek":"Saat 15.00, Mardin: restore edilmiş taş bir konakta konuğu kapıda adıyla karşılarlar; her odanın döşemesi farklıdır ve kahvaltıda ne sevdiği bir gün önceden sorulmuştur.","sektor":"Butik oteli büyük otelden ayıran şey büyüklük değil, özendir. Personel konuğu tanır, tercihlerini hatırlar; konuk da bu ilgi için daha yüksek bir ücret ödemeyi kabul eder. Ders kitabına göre butik otel en az 10, en fazla 60 odalıdır.","iliskili":["os-3-002","os-3-003"],"kontrol":null,"gorsel":"t14zb-butik-otel-salon"},{"id":"os-3-008","konu":"3.1","terim":"Yardımcı konaklama işletmeleri","ingilizce":"Supplementary accommodation establishments","tanim":"Temel konaklama işletmelerinin dışında kalan; kamping, apart otel, yüzer tesis, oberj ve hostel gibi tesislerin oluşturduğu gruptur.","ornek":"Bir üniversite öğrencisi İstanbul’da hostelde, karavanlı bir aile Kaş’ta kampingde, kayak tutkunu bir grup ise Uludağ’da dağ evinde kalır.","sektor":"Bu tesislerde konuk ihtiyaçlarının bir bölümünü çoğu zaman kendi karşılar: yemeğini pişirir, çadırını kurar. Hizmet daha sadedir; personel sayısı ve departman sayısı da buna göre azdır.","iliskili":["os-3-001","os-3-002","os-3-009"],"kontrol":null},{"id":"os-3-009","konu":"3.1","terim":"Kamping","ingilizce":"Campsite","tanim":"Deniz, göl, dağ gibi doğal güzelliği olan yerlerde kurulan; konukların geceleme, yeme içme ve dinlenme ihtiyaçlarını çoğunlukla kendi imkânlarıyla karşıladığı tesistir.","ornek":"Akşam 19.00, Olimpos: bir aile kendilerine ayrılan alana çadırını kurar, yemeğini kendi ocağında pişirir; duşu ve elektriği ise tesisin ortak alanlarından kullanır.","sektor":"Kampingde işletme oda değil yer satar: çadır ya da karavan alanı, su, elektrik, duş ve güvenlik. Konuk doğaya yakın olmayı konfora tercih etmiştir. Ders kitabına göre kamping en az 10 üniteli, yani kalınabilen en az 10 yeri olan bir tesistir.","iliskili":["os-3-008","os-3-012"],"kontrol":null,"gorsel":"kamp"},{"id":"os-3-010","konu":"3.1","terim":"Apart otel","ingilizce":"Aparthotel","tanim":"Odaları, konuğun kendi yemeğini hazırlayabileceği mutfak donanımıyla döşenmiş olan ve otel olarak işletilen tesistir.","ornek":"Saat 18.00, Didim: iki haftalığına gelen aile marketten aldıklarını odadaki buzdolabına yerleştirir, akşam yemeğini kendi mutfağında pişirir.","sektor":"Uzun kalan ve kalabalık ailelerin tercihidir; dışarıda yemek yeme masrafı azalır. Resepsiyon ve temizlik hizmeti verildiği için kiralık evden ayrılır. Ders kitabına göre apart otel en az 10 odalıdır.","iliskili":["os-3-008","os-3-005"],"kontrol":null,"gorsel":"t14a-apart-oda"},{"id":"os-3-011","konu":"3.1","terim":"Yüzer tesis","ingilizce":"Floating accommodation facility","tanim":"Turizm amacıyla konaklama ve yiyecek içecek hizmeti veren; denize elverişlilik belgesi bulunan, kendi motoruyla giden ya da çekilerek taşınan deniz aracıdır.","ornek":"Sabah 09.00, Göcek: bir koyda demirli teknede konuklar güvertede kahvaltı eder; kamaraları otel odası gibi her gün toplanır.","sektor":"Burada otel konuğun yanına gider: tesis yer değiştirebilir. Deniz üzerinde hizmet verildiği için can güvenliği kuralları ve gerekli belgeler işin ilk şartıdır.","iliskili":["os-3-008"],"kontrol":null,"gorsel":"os-yuzer-tesis"},{"id":"os-3-012","konu":"3.1","terim":"Oberj (dağ evi)","ingilizce":"Mountain lodge","tanim":"Kış sporları ya da çim sporları yapmak ve doğadan yararlanmak için yapılan yolculuklarda konaklama ihtiyacını karşılayan tesistir.","ornek":"Saat 17.00, Palandöken: gün boyu kayak yapan grup dağ evine döner, ıslak botlarını kurutma odasına bırakır ve şöminenin başında çorba içer.","sektor":"Konuk buraya oda için değil, dağ ve spor için gelir. Kayak odası, kurutma alanı ve sıcak bir ortak salon gibi imkânlar odanın büyüklüğünden daha çok önem taşır.","iliskili":["os-3-008","os-3-009"],"kontrol":null,"cizim":"otel-bina"},{"id":"os-3-013","konu":"3.1","terim":"Hostel","ingilizce":"Hostel","tanim":"Gençlik turizmine uygun olan; yemek veren ya da konuğa kendi yemeğini hazırlama imkânı sunan konaklama işletmesidir.","ornek":"Akşam 20.00, İstanbul Sultanahmet: sırt çantalı üç üniversiteli ortak mutfakta makarna pişirir, ortak salonda başka ülkelerden gelen gezginlerle tanışır.","sektor":"Hostelin gücü uygun fiyat ve ortak yaşam alanlarıdır. Genç gezgin lüks aramaz; temizlik, güvenlik ve yeni insanlarla tanışabileceği bir ortam ister. Ders kitabına göre hostel en az 10 odalıdır.","iliskili":["os-3-008","os-3-005"],"kontrol":null,"gorsel":"sektor-hostel-yatakhane"},{"id":"os-3-014","konu":"3.1","terim":"Organizasyon yapısı","ingilizce":"Organisational structure","tanim":"Bir işletmede işlerin bölümlere nasıl paylaştırıldığını ve bu bölümlerin birbirine nasıl bağlandığını gösteren düzendir.","ornek":"Küçük bir pansiyonda sahibi hem rezervasyonu alır hem kahvaltıyı hazırlar; büyük bir sahil otelinde ise aynı işler ayrı müdürleri olan ayrı departmanlarca yürütülür.","sektor":"Konaklama işletmelerinde tek tip bir organizasyon yoktur. Tesisin türü, konuk profili, sunduğu hizmetler ve çalışan sayısı departman sayısını belirler; her işletme yapısını kendi politikasına göre kurar.","iliskili":["os-3-015","os-3-016","os-3-017"],"kontrol":null,"cizim":"ekip"},{"id":"os-3-015","konu":"3.1","terim":"Departman","ingilizce":"Department","tanim":"Bir işletmede belirli bir işi üstlenen, kendi yöneticisi ve personeli olan bölümdür.","ornek":"Saat 14.00: konuğa oda anahtarını ön büro verir, o odayı kat hizmetleri hazırlamıştır, akşam yemeğini yiyecek içecek sunar; konuk üç ayrı departmanın emeğini tek bir hizmet olarak yaşar.","sektor":"Otelde verilen her hizmetin arkasında o işe odaklanmış bir departman vardır. Uzmanlaşma işi hızlandırır ve kaliteyi yükseltir; ama departmanlar birbirinden kopuk çalışırsa bunun bedelini konuk öder.","iliskili":["os-3-014","os-3-018","os-3-020"],"kontrol":null,"cizim":"ekip"},{"id":"os-3-016","konu":"3.2.1","terim":"Organizasyon şeması","ingilizce":"Organisation chart","tanim":"Bir işletmedeki ya da departmandaki görevleri ve kimin kime bağlı olduğunu kutular ve çizgilerle gösteren çizelgedir.","ornek":"Stajın ilk günü, saat 09.00: insan kaynakları sorumlusu sana duvardaki şemayı gösterir; en üstte genel müdür, altında departman müdürleri, onların altında şefler ve görevliler vardır.","sektor":"Şema, “Bu konuyu kime sormalıyım, izni kimden almalıyım?” sorusunun cevabıdır. Yeni başlayan personel şemaya bakarak kendi yerini, amirini ve hangi departmanın ne iş yaptığını görür.","iliskili":["os-3-014","os-3-017","os-3-015"],"kontrol":null},{"id":"os-3-017","konu":"3.2.1","terim":"Hiyerarşi","ingilizce":"Hierarchy","tanim":"Bir işletmede yetki ve sorumluluğun üstten alta doğru basamak basamak sıralandığı ast üst düzenidir.","ornek":"Saat 11.00, kat koridoru: stajyer bir sorunu kat şefine bildirir; kat şefi çözemezse kat hizmetleri müdürüne, o da gerekirse genel müdüre taşır.","sektor":"Otelin en üst yöneticisi genel müdürdür; departman müdürleri ona bağlıdır. Sorun önce en yakın amire bildirilir; basamak atlamak hem amirini zor durumda bırakır hem de işin çözümünü geciktirir.","iliskili":["os-3-016","os-3-014"],"kontrol":null,"cizim":"lider"},{"id":"os-3-018","konu":"3.1","terim":"Departmanların sınıflandırılması","ingilizce":"Classification of departments","tanim":"Otel departmanlarının gelir durumuna, işlevine ve önem derecesine göre gruplara ayrılmasıdır.","ornek":"Bir otelde restoran her akşam hesap keser ve doğrudan gelir getirir; teknik servis ise fatura kesmez, ama restoranın ocağı onun sayesinde yanar.","sektor":"Gelire göre: doğrudan gelir getiren ve getirmeyen departmanlar. İşleve göre: faaliyet ve hizmet departmanları. Önem derecesine göre: ana ve yardımcı (destek) departmanlar. Sektörde en çok kullanılan ayrım sonuncusudur.","iliskili":["os-3-019","os-3-056","os-3-015"],"kontrol":null,"cizim":"ekip"},{"id":"os-3-019","konu":"3.1","terim":"Ana departmanlar","ingilizce":"Main (operating) departments","tanim":"Konuğa doğrudan hizmet üreten ve otelin asıl işini yürüten departmanlardır.","ornek":"Bir konuğun bir günü: sabah resepsiyondan bilgi alır, öğlen restoranda yemek yer, döndüğünde odası toplanmıştır, akşam gösteriyi izler; dört ana departmanla karşılaşmıştır.","sektor":"Konaklama hizmetlerini ön büro ile kat hizmetleri birlikte yürütür; yanlarında yiyecek içecek ve etkinlik hizmetleri yer alır. Muhasebe, insan kaynakları ve destek departmanları ise bu hizmetlerin kaydını, insanını ve altyapısını sağlar. Ders kitabı muhasebeyi ayrı bir başlıkta anlatır, destek birimleri sayarken de ona yer verir.","iliskili":["os-3-018","os-3-022","os-3-024"],"kontrol":null},{"id":"os-3-020","konu":"3.1","terim":"Departmanlar arası iş birliği","ingilizce":"Interdepartmental co-operation","tanim":"Otel departmanlarının konuğa kesintisiz hizmet verebilmek için birbirine bilgi vermesi ve işlerini birbirine göre ayarlamasıdır.","ornek":"Saat 12.30: kat hizmetleri 210 numaralı odanın hazır olduğunu ön büroya bildirir; resepsiyon lobide bekleyen aileyi beş dakika içinde odasına yerleştirir.","sektor":"Konuk departmanları görmez, oteli görür: nerede aksama olursa olsun “Bu otel kötü” der. Kat hizmetleri gecikirse ön büro oda veremez; teknik servis gecikirse oda satılamaz; zincirin her halkası bir sonrakini etkiler.","iliskili":["os-3-015","os-3-022","os-3-023"],"kontrol":null,"cizim":"is-birligi"},{"id":"os-3-021","konu":"3.1","terim":"Ön yüz ve arka yüz","ingilizce":"Front of house and back of house","tanim":"Otelde konuğun gördüğü, personelle yüz yüze geldiği alanlar ile konuğun görmediği hazırlık ve destek alanları arasındaki ayrımdır.","ornek":"Akşam 20.00: konuk restoranda sakin bir servis görür; kapının arkasındaki mutfakta, bulaşıkhanede ve depoda ise onlarca kişi o tabak için çalışmaktadır.","sektor":"Resepsiyon, lobi ve restoran ön yüzdür; mutfak, çamaşırhane, depo ve ofisler arka yüzdür. Arka yüzdeki düzen bozulursa bunu ilk hisseden ön yüzdeki konuk olur.","iliskili":["os-3-019","os-3-056","os-3-020"],"kontrol":null,"kitapDisi":true},{"id":"os-3-022","konu":"3.1.1","terim":"Ön büro departmanı","ingilizce":"Front office (FO) department","tanim":"Konuğun otelle ilk temasından ayrılışına kadar bütün süreci yöneten ve departmanlar arasındaki bilgi akışını sağlayan merkezî departmandır.","ornek":"Saat 16.00, lobi: konuk resepsiyona “Odamda ampul yanmıyor” der; görevli isteği kaydeder, teknik servise iletir ve konuğa ne zaman ilgilenileceğini söyler.","sektor":"Ön büro otelin beyni ve aynasıdır: konuk isteklerini ilgili departmana iletir, diğer bölümleri yönlendirir. Konuğun ilk ve son izlenimi burada oluşur. Büyüklüğe göre resepsiyon, rezervasyon, ön kasa, danışma ve santral bölümlerinden oluşur; ayrıntısı 3.2’de işlenir.","iliskili":["os-3-023","os-3-020","os-3-019"],"kontrol":null,"gorsel":"t13d-resepsiyon-ahsap-banko"},{"id":"os-3-412","konu":"3.1.1","terim":"Üniformalı hizmetler","ingilizce":"Uniformed services","tanim":"Bellboy, kapı görevlisi ve vale gibi üniformalarıyla tanınan; konuğu kapıda karşılayan, bagaj ve araç işlerinde yardımcı olan ön büro ekibidir.","ornek":"Saat 15.00, otel girişi: kapı görevlisi taksinin kapısını açar, bellboy valizleri arabaya dizer, vale konuğun aracını otoparka götürür; üçü de aynı ekibin üyesidir.","sektor":"Ders kitabı bu ekibi 3.1.1’de “danışma” bölümü, büyük otellerin ön büro şemasında ise “üniformalı hizmetler” adıyla anar; ekibi danışma şefi yönetir. Konuğun otelde karşılaştığı ilk yüzlerdendir; görünüşleri ve davranışları ilk izlenimi etkiler.","iliskili":["os-3-128","os-3-133","os-3-134"],"kontrol":null,"cizim":"uniforma"},{"id":"os-3-023","konu":"3.1.2","terim":"Kat hizmetleri departmanı","ingilizce":"Housekeeping (HK) department","tanim":"Yalnız odaların değil; koridor, lobi, havuz çevresi ve bahçe dâhil bütün tesisin temizlik, düzen ve bakımından sorumlu olan departmandır.","ornek":"Saat 11.00, üçüncü kat: görevli çıkış yapılan odayı yeni konuk için hazırlar, damlatan musluğu kat şefine bildirir, komodinde unutulan saati de teslim eder.","sektor":"Bir tesisin konaklama işletmesi sayılmasının temel şartı güvenli ve hijyenik barınmadır; bunu kat hizmetleri sağlar. Otelin sattığı ürünü, yani odayı, satışa hazırlayan odur; bu yüzden ön büroyla sürekli haberleşir. Konuk odaları, genel alanlar ve çamaşırhane bölümlerinden oluşur; ayrıntısı 3.3’te işlenir.","iliskili":["os-3-022","os-3-020","os-3-019"],"kontrol":null,"gorsel":"h3a-kat-hizmetleri-departmani"},{"id":"os-3-024","konu":"3.1.3","terim":"Yiyecek içecek departmanı","ingilizce":"Food and beverage (F&B) department","tanim":"Konukların tesisteki bütün yeme içme ihtiyaçlarının planlandığı, hazırlandığı ve sunulduğu departmandır.","ornek":"Sabah 06.00: mutfakta kahvaltı hazırlığı başlar; gün boyu restoran, barlar ve oda servisi çalışır, gece yarısı son siparişle birlikte ertesi günün hazırlığı yapılır.","sektor":"Otelde oda satışından sonra en büyük gelir genellikle yiyecek içecekten gelir. Malzemenin satın alınmasından depoda saklanmasına, mutfakta hazırlanmasından masaya servis edilmesine kadar zincirin tamamı bu departmanın elindedir. Konuk tabağındakinin güvenli olduğunu sorgulamaz, buna güvenir. Bu güveni korumak için hijyen ve sanitasyon kuralları mutfakta pazarlık konusu değildir; kanun da meslek ahlakı da bunu ister.","iliskili":["os-3-025","os-3-033","os-3-019"],"kontrol":null,"gorsel":"h3a-yiyecek-icecek-departmani"},{"id":"os-3-025","konu":"3.1.3","terim":"Restoran","ingilizce":"Restaurant","tanim":"Konuklara masada ya da büfeden yemek servisi yapılan, yiyecek içecek departmanının ana faaliyet alanıdır.","ornek":"Akşam 19.30, sahil oteli: ana restoranda açık büfe akşam yemeği sürerken havuz başındaki ikinci restoranda konuklar menüden seçtikleri balığı bekler.","sektor":"Bir otelde birden fazla restoran bulunabilir. Restoranlar menü türüne göre (alakart, tabldot) ya da servis biçimine göre (açık büfe) birbirinden ayrılır.","iliskili":["os-3-026","os-3-027","os-3-028"],"kontrol":null,"gorsel":"t13e-restoran-salonu"},{"id":"os-3-026","konu":"3.1.3","terim":"Alakart","ingilizce":"À la carte","tanim":"Menüdeki her yemeğin ayrı ayrı fiyatlandırıldığı ve konuğun dilediğini seçerek sipariş verdiği menü ve servis türüdür.","ornek":"Akşam 20.00, otelin balık restoranı: konuk menüyü inceler, başlangıç olarak çorba, ana yemek olarak levrek ister; hesabına yalnız seçtiği iki yemeğin fiyatı yazılır.","sektor":"Alakartta yemek sipariş gelince hazırlanır; konuk seçme özgürlüğü ve özel ilgi için bekler. Garsonun menüyü iyi bilmesi ve doğru öneride bulunması satışı doğrudan artırır.","iliskili":["os-3-025","os-3-027","os-3-028"],"kontrol":null,"cizim":"gastronomi"},{"id":"os-3-410","konu":"3.1.3","terim":"Gıda alerjisi bildirimi","ingilizce":"Food allergy notification","tanim":"Konuğun bildirdiği gıda alerjisinin tahminle geçiştirilmeden mutfağa sorulması ve siparişe yazılı not düşülmesidir.","ornek":"Akşam 19.30, restoran: anne çocuğunun yer fıstığı alerjisi olduğunu söyler; garson menüde emin olmadığı için şefe sorar ve siparişe “yer fıstığı alerjisi” yazar.","sektor":"Alerjide pazarlık ve tahmin yoktur; alerjen içeren yemek “ayıklanarak” güvenli hâle gelmez. Garson bilmiyorsa sorar, bildiğini de siparişe yazar.","iliskili":["os-3-026"],"kontrol":null,"kitapDisi":true,"gorsel":"h3a-gida-alerjisi-bildirimi"},{"id":"os-3-027","konu":"3.1.3","terim":"Tabldot","ingilizce":"Table d'hôte","tanim":"Yemekleri önceden belirlenmiş olan ve tek bir fiyatla sunulan sabit menü türüdür.","ornek":"Öğlen 12.30, tur grubu için ayrılan salon: herkese sırayla aynı çorba, aynı ana yemek ve aynı tatlı servis edilir; fiyat kişi başı tektir.","sektor":"Mutfak ne pişireceğini ve kaç porsiyon çıkaracağını önceden bilir; hazırlık kolaylaşır, israf azalır, servis hızlanır. Grup yemeklerinde bu yüzden sık tercih edilir.","iliskili":["os-3-025","os-3-026","os-3-028"],"kontrol":null,"cizim":"gastronomi"},{"id":"os-3-028","konu":"3.1.3","terim":"Açık büfe","ingilizce":"Buffet service","tanim":"Yemeklerin bir tezgâhta topluca sergilendiği ve konukların istediklerini kendilerinin aldığı servis biçimidir.","ornek":"Sabah 08.00, kahvaltı salonu: konuklar büfeden peynir, zeytin ve böreği kendileri alır; aşçı büfenin ucundaki ocakta isteyene omlet yapar, görevliler boşalan tepsileri yeniler.","sektor":"Kısa sürede çok sayıda konuğa hizmet verilebilir. Büfenin dolu, temiz ve düzenli kalması, sıcak yemeğin sıcak, soğuk yemeğin soğuk tutulması hem görüntü hem gıda güvenliği için önemlidir.","iliskili":["os-3-025","os-3-026","os-3-027"],"kontrol":null,"cizim":"zil-hizmet"},{"id":"os-3-029","konu":"3.1.3","terim":"Bar","ingilizce":"Bar","tanim":"Otelde içecek hazırlamaya ve sunmaya odaklanan yiyecek içecek satış noktasıdır.","ornek":"Saat 17.00: lobi barda iş görüşmesi yapan iki konuğa çay servis edilir, havuz barda limonata hazırlanır, vitamin barda sporcular için portakal sıkılır.","sektor":"Barlar bulundukları yere ve sundukları içeceğe göre adlandırılır: lobi bar, havuz bar, vitamin bar gibi. Konuğun gün içinde en sık uğradığı noktalardandır; hızlı ve güler yüzlü servis burada özellikle göze çarpar.","iliskili":["os-3-024","os-3-025"],"kontrol":null},{"id":"os-3-030","konu":"3.1.3","terim":"Ziyafet (banket)","ingilizce":"Banqueting","tanim":"Düğün, nişan, toplantı ve konser gibi kalabalık organizasyonların yiyecek içecek hizmetini yürüten bölümdür.","ornek":"Cumartesi 19.00, balo salonu: bir düğün için masalar numaralanmış, örtüler serilmiş, servis ekibi aynı anda servise çıkmak üzere kapıda sıralanmıştır.","sektor":"Bu organizasyonlara otelde kalmayan çok sayıda kişi gelir ve oteli ilk kez görür; iyi geçen bir düğün otelin en etkili tanıtımıdır. Ziyafet günlerinde mutfak, servis, teknik servis ve kat hizmetleri birlikte çalışır.","iliskili":["os-3-024","os-3-020"],"kontrol":null,"gorsel":"t13f-banket-salonu"},{"id":"os-3-031","konu":"3.1.3","terim":"Oda servisi","ingilizce":"Room service","tanim":"Konuğun restorana inmesine gerek kalmadan siparişinin odasına götürüldüğü yiyecek içecek hizmetidir.","ornek":"Gece 23.30: geç saatte otele varan konuk telefonla çorba ve tost ister; görevli siparişi tepsiyle odaya çıkarır, kapıyı çalıp kendini tanıtır.","sektor":"Çoğu zaman ek ücretli, “ekstra” bir hizmettir; büyük otellerde günün her saatinde verilebilir. Sipariş doğru odaya, sıcak ve eksiksiz ulaşmalıdır; ücreti de konuğun hesabına işlenmelidir.","iliskili":["os-3-024","os-3-032","os-3-022"],"kontrol":null,"gorsel":"t14b-oda-servisi-tepsi"},{"id":"os-3-032","konu":"3.1.3","terim":"Minibar","ingilizce":"Minibar","tanim":"Konuk odasındaki küçük buzdolabında içecek ve atıştırmalıkların konuğa sunulduğu hizmettir.","ornek":"Saat 10.00, oda kontrolü: görevli minibardan iki şişe su ile bir çikolatanın eksildiğini görür, formuna yazar ve eksilenleri tamamlar.","sektor":"Minibar otelin konseptine göre ücretli ya da ücretsiz olabilir. Ücretliyse tüketimin günü gününe konuğun hesabına işlenmesi gerekir; kaydedilmeyen her ürün otel için kayıptır.","iliskili":["os-3-031","os-3-024"],"kontrol":null,"cizim":"icecek-bar"},{"id":"os-3-033","konu":"3.1.3","terim":"Mutfak","ingilizce":"Kitchen","tanim":"Yiyeceklerin reçetelere ve hijyen standartlarına uygun olarak hazırlandığı, yiyecek içecek departmanının üretim merkezidir.","ornek":"Akşam 18.00: akşam servisinden bir saat önce mutfağın her bölümü kendi işindedir; biri sosu kısar, biri salatayı hazırlar, biri tatlıyı süsler.","sektor":"Büyük otellerde mutfak, menünün çeşidine ve otelin kapasitesine göre uzmanlık bölümlerine ayrılır. Hepsinin yönetildiği ve işlerin eşgüdümünün sağlandığı merkeze ana mutfak denir. Konuk mutfağı görmez, ama memnuniyeti doğrudan oradan çıkan tabağa bağlıdır.","iliskili":["os-3-034","os-3-035","os-3-024"],"kontrol":null,"gorsel":"sektor-mutfak"},{"id":"os-3-034","konu":"3.1.3","terim":"Sıcak kısım","ingilizce":"Hot kitchen","tanim":"Sosların, tencere yemeklerinin, ızgaraların ve diğer temel sıcak yemeklerin pişirildiği mutfak bölümüdür.","ornek":"Akşam 19.45: ızgaradaki aşçı köfteleri çevirirken yanındaki aşçı kazandaki etli yemeği son kez karıştırır; ikisi de aynı masanın siparişine yetişmeye çalışır.","sektor":"Servis saatinde mutfağın en yoğun ve en sıcak yeridir. Ateş, kızgın yağ ve buharla çalışıldığı için dikkat ve iş güvenliği burada her şeyden önce gelir.","iliskili":["os-3-033","os-3-035","os-3-036"],"kontrol":null,"cizim":"mutfak"},{"id":"os-3-035","konu":"3.1.3","terim":"Soğuk kısım","ingilizce":"Cold kitchen (garde manger)","tanim":"Zeytinyağlıların, mezelerin, salataların ve soğuk sosların hazırlandığı mutfak bölümüdür.","ornek":"Saat 17.00: soğuk kısımdaki aşçı açık büfe için meze tabaklarını tek tek süsler, salataları servis saatine kadar soğuk dolapta bekletir.","sektor":"Soğuk yemeklerin bir bölümü hiç pişirilmeden, kalanı da pişirilip soğutularak sunulur; bu yüzden el hijyeni, temiz tezgâh ve soğuk saklama burada çok önemlidir. Tabağın görünüşü de bu bölümün ustalık alanıdır.","iliskili":["os-3-033","os-3-034","os-3-028"],"kontrol":null},{"id":"os-3-036","konu":"3.1.3","terim":"Aperitif ve garnitür bölümü","ingilizce":"Soup and vegetable section (entremetier)","tanim":"Çorbaların, makarnaların ve yemeklerin yanına eklenen garnitürlerin hazırlandığı mutfak bölümüdür.","ornek":"Öğlen 12.00: bu bölümdeki aşçı günün çorbasını kazanda hazır tutar; ızgaradan çıkan etin yanına konacak pilavı ve haşlanmış sebzeyi tabağa yetiştirir.","sektor":"Ana yemeği tamamlayan her şey buradan çıkar. Et ne kadar iyi pişmiş olursa olsun, yanındaki pilav soğuksa konuk tabağın tamamını kusurlu bulur.","iliskili":["os-3-033","os-3-034"],"kontrol":null},{"id":"os-3-037","konu":"3.1.3","terim":"Pastane","ingilizce":"Pastry section","tanim":"Tatlıların, pastaların, ekmeklerin ve bütün unlu mamullerin üretildiği mutfak bölümüdür.","ornek":"Gece 04.00: otel uyurken pastanedeki usta kahvaltının poğaçalarını ve ekmeklerini fırına verir; öğleden sonra da akşamki düğünün pastasını süsler.","sektor":"Pastanede ölçü ve sabır esastır; malzeme terazide tartılır, göz kararı çalışılmaz. Sabah büfesindeki taze ekmek kokusu konuğun güne ilişkin ilk izlenimlerinden biridir.","iliskili":["os-3-033","os-3-039"],"kontrol":null,"gorsel":"t14b-pastane-hamur"},{"id":"os-3-038","konu":"3.1.3","terim":"Kasaphane","ingilizce":"Butchery","tanim":"Et, tavuk ve balığın pişirilmeden önce ayıklandığı, porsiyonlandığı ve marine edildiği ön hazırlık bölümüdür.","ornek":"Sabah 09.00: kasaphanedeki görevli akşam servisi için bonfileleri eşit ağırlıkta dilimler, terbiyeler ve soğuk dolaba kaldırır.","sektor":"Et, mutfağın en pahalı malzemelerindendir; eşit porsiyon hem konuğa adil servis hem de maliyet kontrolü demektir. Çiğ et ayrı alanda, ayrı gereçlerle ve soğukta işlenir; yoksa mikroplar diğer yiyeceklere bulaşabilir.","iliskili":["os-3-033","os-3-034","os-3-045"],"kontrol":null,"gorsel":"os-kasaphane"},{"id":"os-3-039","konu":"3.1.3","terim":"Kahvaltı bölümü","ingilizce":"Breakfast section","tanim":"Sabah servis edilen sıcak ve soğuk bütün kahvaltılıkların hazırlandığı mutfak bölümüdür.","ornek":"Sabah 05.30: kahvaltı ekibi yumurtaları haşlar, peynir ve zeytin tabaklarını dizer, menemen için domatesleri doğrar; büfe ilk konuk gelmeden hazır olmalıdır.","sektor":"Kahvaltı, pek çok konuğun otelde yediği tek öğündür ve ayrılmadan önceki son izlenimdir. Bu ekip güne herkesten önce başlar.","iliskili":["os-3-033","os-3-037","os-3-028"],"kontrol":null},{"id":"os-3-040","konu":"3.1.3","terim":"Personel mutfağı","ingilizce":"Staff kitchen","tanim":"Otel çalışanlarının yemeklerinin hazırlandığı ayrı mutfak alanıdır.","ornek":"Saat 11.30, personel yemekhanesi: öğle servisi başlamadan önce garsonlar ve kat görevlileri sırayla yemeğini yer; menüde çorba, etli nohut ve pilav vardır.","sektor":"Uzun vardiyada ayakta çalışan personelin iyi beslenmesi gerekir. Çalışanına özenle yemek çıkaran otel ona değer verdiğini gösterir; bu da konuğa verilen hizmete yansır.","iliskili":["os-3-033","os-3-049"],"kontrol":null,"gorsel":"h3a-personel-mutfagi"},{"id":"os-3-041","konu":"3.1.3","terim":"Bulaşıkhane","ingilizce":"Dishwashing area (stewarding)","tanim":"Mutfak gereçlerinin ve servis takımlarının hijyenik biçimde yıkanıp yeniden kullanıma hazırlandığı bölümdür.","ornek":"Akşam 21.00: salondan gelen tabaklar önce artıklarından sıyrılır, makinede yıkanır, kuruyunca raflara dizilir; bir sonraki masa için temiz tabak hazırdır.","sektor":"Bulaşıkhane durursa servis de durur: temiz tabak, bardak ve çatal olmadan tek bir masa bile açılamaz. Yere düşen ya da kirlenen her gereç doğrudan buraya gönderilir, silinip yeniden kullanılmaz.","iliskili":["os-3-033","os-3-024"],"kontrol":null,"cizim":"mutfak"},{"id":"os-3-042","konu":"3.1.4","terim":"Etkinlik hizmetleri departmanı","ingilizce":"Events and entertainment department","tanim":"Konukların boş zamanlarını eğlenceli ve verimli geçirmeleri için spor, oyun ve gösteri gibi etkinlikleri planlayan ve yürüten departmandır.","ornek":"Saat 10.30, havuz başı: ekip su jimnastiğini başlatır; öğleden sonra dart turnuvası, akşam 21.30’da amfi tiyatroda halk oyunları gösterisi vardır.","sektor":"Animasyon ve rekreasyon olarak da anılır. Yalnız eğlendirmez; konuğun otele bağlanmasını sağlar ve otelin imajını güçlendirir. Etkinlikler alanına, konuğun katılma biçimine, yaş grubuna ve içeriğine göre çeşitlenir; ayrıntısı 3.4’te işlenir.","iliskili":["os-3-043","os-3-062","os-3-006","os-3-019"],"kontrol":null,"gorsel":"h3a-etkinlik-hizmetleri-departmani"},{"id":"os-3-043","konu":"3.1.4","terim":"Etkinlik yönetim süreci","ingilizce":"Event management process","tanim":"Bir etkinliğin planlama, organizasyon, koordinasyon ve denetim adımlarıyla baştan sona yönetilmesidir.","ornek":"Türk gecesi için ekip önce konukların yaşına ve beklentisine bakar, sonra kostümü ve ses sistemini ayarlar, teknik servis ve restoranla saatleri konuşur; ertesi gün kaç konuğun katıldığını değerlendirir.","sektor":"Planlama: konuk profiline göre hangi etkinliğin yapılacağına karar verilir. Organizasyon: personel, bütçe ve ekipman belirlenir. Koordinasyon: ekipler yönlendirilir, diğer departmanlarla iş birliği kurulur. Denetim: sonuç ve katılım değerlendirilir, eksikler düzeltilir. İyi bir etkinlik rastlantı değildir.","iliskili":["os-3-042","os-3-020"],"kontrol":null,"gorsel":"h3a-etkinlik-yonetim-sureci"},{"id":"os-3-062","konu":"3.1.4","terim":"Etkinlik çeşitleri","ingilizce":"Types of activities","tanim":"Konaklama işletmelerindeki etkinliklerin alanına, katılım biçimine, yaş grubuna ve içeriğine göre ayrıldığı gruplardır.","ornek":"Sabah 10.00, bir tatil köyü: çocuklar mini kulüpte oyun oynar; akşam 21.30’da yetişkinler amfi tiyatroda oturup halk oyunları gösterisini izler.","sektor":"Alanına göre açık ya da kapalı alan etkinliği vardır. Katılım biçimine göre etken (aktif) etkinlikte konuk oyunun içindedir, edilgen (pasif) etkinlikte yalnız izler. Yaş grubuna göre çocuk (mini club), genç ve yetişkin animasyonu; içeriğine göre sportif ya da sosyokültürel (halk oyunları, Türk gecesi gibi) etkinlik ayrılır. Aynı etkinlik birden çok gruba girebilir.","iliskili":["os-3-042","os-3-043","os-3-006"],"kontrol":null,"gorsel":"t13b-sahne-gosterisi"},{"id":"os-3-044","konu":"3.1.5","terim":"Muhasebe departmanı","ingilizce":"Accounts department","tanim":"Otelin bütün parasal hareketlerini izleyen, kaydeden ve yönetime raporlayan departmandır.","ornek":"Sabah 09.00: muhasebe görevlisi bir önceki günün restoran, bar ve oda gelirlerini kayıtlarla karşılaştırır; tutmayan bir hesabı ilgili departmana sorar.","sektor":"Otelin finansal aynası ve iç denetim mekanizmasıdır. Üç temel görevi vardır: konuk hesaplarını ve ödemeleri kontrol etmek, gereksiz harcamayı ve suistimali önlemek, kâr-zarar durumunu dönemsel raporlarla yönetime sunmak. İşlemler bugün bütün departmanlara bağlı otomasyon programlarıyla yürütülür.","iliskili":["os-3-045","os-3-046","os-3-047"],"kontrol":null,"cizim":"ekip"},{"id":"os-3-045","konu":"3.1.5","terim":"Maliyet ve gelirler bölümü","ingilizce":"Cost and income control section","tanim":"Otelin bütün birimlerinden gelen hasılatı izleyen ve giderleri denetleyerek maliyet kontrolü yapan muhasebe bölümüdür.","ornek":"Ay sonu, saat 15.00: görevli restoranın bu ayki gelirini geçen yılın aynı ayıyla karşılaştırır; gelir aynı kaldığı hâlde et giderinin arttığını görüp nedenini araştırır.","sektor":"Z raporu (günlük kasa kapanış raporu) gibi gelir belgelerini inceler, geçmiş dönemlerle karşılaştırma yapar. Bir otel dolu olduğu hâlde zarar edebilir; gelirin ne kadarının gidere gittiğini bu bölüm gösterir ve yönetimi zamanında uyarır.","iliskili":["os-3-044","os-3-038","os-3-048"],"kontrol":null,"cizim":"para-butce"},{"id":"os-3-046","konu":"3.1.5","terim":"Krediler bölümü","ingilizce":"Credit control section","tanim":"Otelin vadeli, yani ödemesi sonradan yapılacak satışlarını yöneten ve alacakların tahsilatını izleyen muhasebe bölümüdür.","ornek":"Bir seyahat acentesi yaz boyunca gönderdiği grupların ücretini ay sonunda toplu ödemek ister; krediler bölümü acentenin talebini inceler, bir limit belirler ve ödeme gününü takip eder.","sektor":"Acenteler ve şirketler çoğu zaman peşin ödemez. Bu bölüm kime, ne kadar ve ne süreyle vade tanınacağına bakar; süresi dolan alacağın peşine düşer. Tahsil edilemeyen satış, hiç yapılmamış satıştan daha pahalıya gelir.","iliskili":["os-3-044","os-3-047"],"kontrol":null},{"id":"os-3-047","konu":"3.1.5","terim":"Genel kasa bölümü","ingilizce":"General cashier's office","tanim":"Otelin bütün nakit akışının güvenliğinden sorumlu olan muhasebe bölümüdür.","ornek":"Sabah 08.30: genel kasa görevlisi günün döviz kurlarını kontrol eder, banka hesaplarına bakar; öğleden sonra personelin avans ödemelerini hazırlar.","sektor":"Günlük döviz kurlarını izlemek, banka hesaplarını kontrol etmek, personelin maaş ve avans ödemelerini yapmak bu bölümün işidir. Otelin parası tek elden ve kayıtlı yönetildiğinde hata da kötüye kullanım da azalır.","iliskili":["os-3-044","os-3-046"],"kontrol":null},{"id":"os-3-048","konu":"3.1.5","terim":"Depo ve ambar bölümü","ingilizce":"Receiving and stores section","tanim":"Satın alınan malzemeyi teslim alırken kontrol eden, uygun koşullarda saklayan ve ihtiyaç duyan departmana çıkışını yapan bölümdür.","ornek":"Sabah 07.30, mal kabul kapısı: görevli gelen sebze kasalarını sayar, tartar, faturayla karşılaştırır; ezik domates kasasını kabul etmez ve tutanağa yazar.","sektor":"Otele giren her malzemenin kontrol noktasıdır: ürün faturaya ve şartnameye uygun mu diye bakılır. Kontrol edilmeden alınan eksik ya da bozuk mal önce mutfağın, sonra konuğun sorunu olur. Depodan malzeme de kayıtla çıkar.","iliskili":["os-3-044","os-3-059","os-3-045"],"kontrol":null,"cizim":"ekip"},{"id":"os-3-419","konu":"3.1.5","terim":"Z raporu","ingilizce":"Z report (end-of-day report)","tanim":"Kasa ya da satış kayıtlarının gün sonunda kapatılıp günlük satış ve gelir toplamlarının çıkarıldığı rapordur.","ornek":"Gece 23.45, restoran kasası: kasiyer gün sonunda Z raporunu alır; ertesi sabah muhasebe bu raporu fişlerle karşılaştırır.","sektor":"Ders kitabı Z raporunu, maliyet ve gelirler bölümünün incelediği gelir belgelerine örnek olarak verir. Rapordaki tutar ile kasadaki para ve fişler uyuşmuyorsa fark araştırılır.","iliskili":["os-3-045","os-3-044","os-3-047"],"kontrol":null,"cizim":"grafik"},{"id":"os-3-049","konu":"3.1.6","terim":"İnsan kaynakları departmanı","ingilizce":"Human resources (HR) department","tanim":"Doğru işe doğru kişinin seçilmesi, eğitilmesi ve çalışanların memnun biçimde işletmede kalması için çalışan merkezî departmandır.","ornek":"Nisan ayı, sezon öncesi: insan kaynakları yaz için kaç garson ve kat görevlisi gerektiğini departman müdürleriyle belirler, ilanları yayımlar ve görüşmelere başlar.","sektor":"Turizm emek yoğun bir sektördür: hizmetin kalitesi onu veren kişinin yeteneğine ve isteğine bağlıdır. İnsan kaynakları bütün departmanlarla çalışır; aralarında uyumu sağlayan hakem gibidir. Adil ve tarafsız olmak zorundadır, çünkü çalışan onun tutumunu işletmenin tutumu sayar.","iliskili":["os-3-050","os-3-051","os-3-055"],"kontrol":null,"cizim":"ekip"},{"id":"os-3-050","konu":"3.1.6","terim":"Personel planlaması ve işe alım","ingilizce":"Workforce planning and recruitment","tanim":"İşletmenin kaç ve hangi nitelikte çalışana ihtiyacı olduğunun belirlenmesi, ilan verilmesi ve görüşmelerle en uygun adayın seçilmesidir.","ornek":"Saat 14.00, insan kaynakları ofisi: resepsiyon için başvuran adayla görüşme yapılır; yabancı dili, iletişimi ve vardiyalı çalışmaya uygunluğu değerlendirilir.","sektor":"İş görüşmesine mülakat denir. Yanlış kişiyi işe almak pahalıdır: eğitimine harcanan zaman boşa gider, konuk da bu arada kötü hizmet alır. Görüşmeye hazırlıklı, bakımlı ve dakik gelen aday bir adım öne geçer.","iliskili":["os-3-049","os-3-051"],"kontrol":null,"cizim":"ekip"},{"id":"os-3-051","konu":"3.1.6","terim":"Oryantasyon","ingilizce":"Induction (orientation)","tanim":"İşe yeni başlayan personelin işletmeye, işine ve çalışma arkadaşlarına alışması için yürütülen uyum sürecidir.","ornek":"Stajın ilk günü, saat 09.00: sana otel gezdirilir, personel girişi ve soyunma odası gösterilir, kurallar anlatılır, amirinle ve ekibinle tanıştırılırsın.","sektor":"İnsan kaynakları yalnız uyum sürecini değil, çalışanların mesleki gelişimi için verilen eğitimleri de düzenler. İlk günlerinde kime ne soracağını bilen personel daha az hata yapar ve işe daha çabuk ısınır.","iliskili":["os-3-049","os-3-050","os-3-016"],"kontrol":null,"cizim":"ekip"},{"id":"os-3-052","konu":"3.1.6","terim":"Performans ve ücret yönetimi","ingilizce":"Performance and pay management","tanim":"Çalışanların başarısının ölçülmesi ve maaş ile prim, ödül gibi yan haklarının buna göre planlanmasıdır.","ornek":"Sezon sonu: konuk anketlerinde adı en çok teşekkürle geçen garson ayın personeli seçilir ve ödüllendirilir.","sektor":"Emeğinin görüldüğünü ve adil ölçüldüğünü bilen çalışan işine daha çok sarılır. Ölçme herkese aynı ölçütle yapılmazsa ödül ekipte kırgınlığa dönüşür.","iliskili":["os-3-049","os-3-053"],"kontrol":null,"cizim":"para-butce"},{"id":"os-3-053","konu":"3.1.6","terim":"Kariyer ve motivasyon çalışmaları","ingilizce":"Career development and motivation","tanim":"Personelin yükselme yolunun planlanması, stresini azaltacak etkinliklerin düzenlenmesi ve sorunlarıyla ilgilenilmesidir.","ornek":"Kasım ayı: sezonu kapatan otel bütün çalışanlarına bir yemek verir; üç yıldır başarıyla çalışan komi, eğitimini tamamlayıp garsonluğa yükseltilir.","sektor":"Bir basamak yukarı çıkmaya terfi denir. Önünde bir yol gören çalışan kalır, görmeyen başka otele gider. İnsan kaynaklarının amacı yalnız personel bulmak değil, iyi personeli işletmede tutmaktır.","iliskili":["os-3-052","os-3-054","os-3-049"],"kontrol":null,"cizim":"lider"},{"id":"os-3-054","konu":"3.1.6","terim":"Personel devir hızı","ingilizce":"Staff turnover","tanim":"Belirli bir dönemde işletmeden ayrılan ve yerine yenisi alınan çalışanların, toplam çalışanlara göre ne kadar çok olduğunu gösteren ölçüdür.","ornek":"Bir otelde resepsiyon ekibi her yaz baştan kurulur; sürekli gelen konuklar tanıdık bir yüz göremez ve her defasında isteklerini yeniden anlatmak zorunda kalır.","sektor":"Devir hızı yüksekse otel sürekli yeni personel arar ve eğitir; deneyim birikmez, hizmet kalitesi dalgalanır. Başarılı bir otel konuğunu kaybetmek istemediği gibi iyi yetişmiş personelini de kaybetmek istemez.","iliskili":["os-3-053","os-3-049"],"kontrol":null,"kitapDisi":true,"cizim":"ekip"},{"id":"os-3-055","konu":"3.1.6","terim":"Özlük dosyası","ingilizce":"Personnel file","tanim":"Bir çalışanın işe girişinden ayrılışına kadar kimlik, sözleşme, izin, sigorta ve disiplin gibi belgelerinin saklandığı dosyadır.","ornek":"Yıllık izne çıkmak isteyen garson izin formunu doldurur; insan kaynakları formu onaylatır ve bir örneğini özlük dosyasına koyar.","sektor":"İnsan kaynaklarının yasal görevlerindendir: özlük dosyalarını tutar, disiplin işlemlerini yürütür, sigorta ve izin gibi yasal hakları takip eder. Dosyadaki bilgiler kişiseldir; yetkisi olmayan kimseyle paylaşılmaz.","iliskili":["os-3-049","os-3-052"],"kontrol":null},{"id":"os-3-056","konu":"3.1.7","terim":"Destek departmanları","ingilizce":"Support departments","tanim":"Ana departmanların işini daha kaliteli, hızlı ve hatasız yapabilmesi için arka planda çalışan yardımcı departmanlardır.","ornek":"Akşam 20.00: konuk restoranda yalnız garsonu görür; oysa o masadaki ışığı teknik servis yanık tutar, tabaktaki balığı satın alma temin eder, hesabı çıkaran sistemi bilgi işlem çalışır durumda tutar.","sektor":"Doğrudan oda ya da yiyecek içecek satmadıkları için “doğrudan gelir getirmeyen departmanlar” diye de anılırlar. Ama onlar olmadan ana departmanlar çalışamaz. Büyük otellerde başlıcaları satış ve pazarlama, teknik servis, güvenlik, satın alma ve bilgi işlemdir.","iliskili":["os-3-057","os-3-058","os-3-018"],"kontrol":null},{"id":"os-3-057","konu":"3.1.7","terim":"Satış ve pazarlama","ingilizce":"Sales and marketing department","tanim":"Pazar araştırması, tanıtım ve kurumsal satış çalışmalarıyla otele konuk kazandıran destek departmanıdır.","ornek":"Ocak ayı, İstanbul: satış temsilcisi bir turizm fuarında acentelerle görüşür, bir şirketle de yıl boyu yapacağı toplantılar için anlaşma imzalar.","sektor":"Boş kalan oda ertesi güne saklanamaz; o gecenin geliri geri gelmez. Bu departman doluluğu artırarak otelin ekonomik sürekliliğini sağlar; verdiği sözü tutmak ise diğer departmanların işidir.","iliskili":["os-3-056","os-3-022"],"kontrol":null,"cizim":"megafon"},{"id":"os-3-058","konu":"3.1.7","terim":"Teknik servis","ingilizce":"Maintenance (engineering) department","tanim":"Arızaları gideren, periyodik bakımları yapan ve tesisin enerji kullanımını yöneten destek departmanıdır.","ornek":"Saat 15.20: kat hizmetleri 318 numaralı odanın klimasının su damlattığını bildirir; teknik servis görevlisi arızayı giderir ve odanın yeniden satılabileceğini haber verir.","sektor":"Isıtma, soğutma, aydınlatma ve sıcak su gibi konforun kesintisiz sürmesi ona bağlıdır. Arızalı oda satılamaz; arızayı geç öğrenen teknik servis geç onarır, bu yüzden görülen her arıza hemen bildirilir.","iliskili":["os-3-056","os-3-023","os-3-020"],"kontrol":null,"cizim":"ekip"},{"id":"os-3-059","konu":"3.1.7","terim":"Satın alma","ingilizce":"Purchasing department","tanim":"Otelin ihtiyaç duyduğu malzeme ve hizmetleri en uygun kalite ve fiyat dengesiyle tedarik eden destek departmanıdır.","ornek":"Pazartesi 10.00: mutfak şefi haftalık sebze ihtiyacını bildirir; satın alma görevlisi tedarikçilerden fiyat alır, kaliteyi ve fiyatı karşılaştırıp siparişi verir.","sektor":"Mutfağın, kat hizmetlerinin ve diğer bütün birimlerin işini yapabilmesi doğru malzemenin zamanında gelmesine bağlıdır. En ucuz ürün her zaman en uygun ürün değildir: çabuk yıpranan havlu otele daha pahalıya gelir.","iliskili":["os-3-056","os-3-048"],"kontrol":null,"cizim":"ekip"},{"id":"os-3-060","konu":"3.1.7","terim":"Güvenlik","ingilizce":"Security department","tanim":"Tesisin, konukların ve çalışanların güvenliğini günün her saatinde gözeten destek departmanıdır.","ornek":"Gece 02.00: güvenlik görevlisi otoparkı ve personel girişini dolaşır, kamera odasındaki arkadaşıyla telsizle haberleşir.","sektor":"Konuk kendini güvende hissettiği otele yeniden gelir; huzurlu ortam işletmeye duyulan güvenin temelidir. Şüpheli bir kişi ya da durumla karşılaşan personel kendisi müdahale etmez; hemen güvenliğe ve amirine haber verir.","iliskili":["os-3-056","os-3-017"],"kontrol":null,"gorsel":"h3a-guvenlik"},{"id":"os-3-061","konu":"3.1.7","terim":"Bilgi işlem","ingilizce":"Information technology (IT) department","tanim":"Otelin otomasyon sistemlerini, bilgisayar ağını ve dijital verilerinin güvenliğini yöneten destek departmanıdır.","ornek":"Sabah 07.50: resepsiyondaki program açılmaz, çıkış yapacak konuklar sıraya girer; bilgi işlem görevlisi sistemi birkaç dakikada yeniden çalıştırır.","sektor":"Rezervasyon, konuk hesabı ve oda durumu aynı sistemde tutulur; sistem durursa otelin bütün departmanları yavaşlar. Bilgi işlem, bilginin hızlı ve hatasız akmasını sağlar. Şifreni kimseyle paylaşmamak ve ekranı açık bırakmamak da veri güvenliğinin senin payına düşen kısmıdır.","iliskili":["os-3-056","os-3-044"],"kontrol":null,"cizim":"kitap-ogrenme"},{"id":"os-3-100","konu":"3.2","terim":"Ön büronun görevleri","ingilizce":"Front office functions","tanim":"Konuğu rezervasyondan ayrılışa kadar izleyen; karşılama, kayıt, oda verme, hesap tutma ve bilgi verme işlerini yürütürken bütün bölümlerle konuk arasında bağ kuran çalışmaların tümüdür.","ornek":"Sabah 08.30, lobi: bir görevli çıkış yapan konuğun hesabını kapatır, yanındaki telefonda yarınki rezervasyonu alır, bir diğeri kat hizmetlerine hangi odaların öncelikli olduğunu bildirir; hepsi ön büronun işidir.","sektor":"Ders kitabı ön büroyu orkestra şefine benzetir: her işi kendisi yapmaz, ama herkesin doğru zamanda doğru işi yapmasını sağlar. Konuğun otelle ilk ve son teması burada olduğu için ilk ve son izlenim de burada oluşur.","iliskili":["os-3-101","os-3-104","os-3-105"],"kontrol":null,"cizim":"resepsiyon"},{"id":"os-3-101","konu":"3.2","terim":"Konuk döngüsü","ingilizce":"Guest cycle","tanim":"Her konuk için aynı sırayla yinelenen dört evreden, yani varış öncesi, varış, konaklama ve ayrılıştan oluşan hizmet akışıdır.","ornek":"Antalya’da bir otel: Ayşe Hanım pazartesi telefonla oda ayırtır, cuma günü gelip kaydını yaptırır, hafta sonu otelde kalır, pazar öğlen hesabını ödeyip ayrılır; dört evre tamamlanmıştır.","sektor":"Varış öncesinde rezervasyon alınır ve oda ayrılır; varışta karşılama ve kayıt yapılır; konaklamada istekler ve harcamalar izlenir; ayrılışta hesap kapatılır ve konuk uğurlanır. Hangi evrede olduğunu bilen görevli sıradaki işi de bilir. Kitaptaki İngilizce adları: Pre-arrival (varış öncesi), Arrival / Check-in (varış, karşılama), Stay (konaklama) ve Departure / Check-out (ayrılış).","iliskili":["os-3-102","os-3-103","os-3-149"],"kontrol":null,"cizim":"resepsiyon"},{"id":"os-3-102","konu":"3.2","terim":"Check-in (giriş işlemi)","ingilizce":"Check-in","tanim":"Konuğun tesise gelişinde karşılanması, kaydının yapılması ve oda anahtarının teslim edilmesiyle tamamlanan işlemdir.","ornek":"Saat 14.20, resepsiyon: görevli konuğu selamlar, rezervasyonunu bulur, kimliğini alıp konaklama belgesini imzalatır ve kapı kartını “İyi tatiller dileriz” diyerek uzatır.","sektor":"Konuk döngüsünün varış evresidir. Uzun yoldan gelen konuk bekletilmek istemez; hızlı, güler yüzlü ve hatasız bir giriş, konaklamanın geri kalanına iyi bir başlangıç sağlar.","iliskili":["os-3-101","os-3-152","os-3-103"],"kontrol":null,"gorsel":"sektor-resepsiyon-checkin"},{"id":"os-3-103","konu":"3.2","terim":"Check-out (çıkış işlemi)","ingilizce":"Check-out","tanim":"Konuğun ayrılırken hesabının incelenip tahsil edilmesi, anahtarın geri alınması ve konuğun uğurlanmasıyla tamamlanan işlemdir.","ornek":"Sabah 10.45, resepsiyon: görevli hesap dökümünü konuğa gösterir, ödemeyi alır, faturayı verir, kapı kartını geri alır ve “Yine bekleriz” diyerek uğurlar.","sektor":"Konuk döngüsünün ayrılış evresidir ve konuğun otelden aklında kalan son sahnedir. Hesapta çıkan bir hata ya da uzun bir kuyruk günlerce süren iyi hizmetin önüne geçebilir.","iliskili":["os-3-101","os-3-156","os-3-159"],"kontrol":null,"cizim":"resepsiyon"},{"id":"os-3-104","konu":"3.2","terim":"Görülebilen ön büro işlemleri","ingilizce":"Guest-facing front office operations","tanim":"Resepsiyon bankosunda ya da lobide, konuğun gözü önünde ve onunla doğrudan iletişim kurularak yapılan işlemlerdir.","ornek":"Saat 16.00, lobi: bir görevli yeni gelen konuğun kaydını yaparken yanındaki görevli de başka bir konuğa müzeye nasıl gidileceğini haritada gösterir.","sektor":"Bilgi verme, kayıt ve yerleştirme, konuk isteklerini izleme, döviz bozma, tahsilat ve santral hizmetleri bu gruptadır. Konuk burada yalnız işlemi değil, personelin nezaketini ve dürüstlüğünü de görür.","iliskili":["os-3-105","os-3-100","os-3-106"],"kontrol":null,"gorsel":"h3a-gorulebilen-on-buro-islemleri"},{"id":"os-3-105","konu":"3.2","terim":"Arka büro işlemleri","ingilizce":"Back office operations","tanim":"Ön büro personelinin konuğun görmediği yerde, bankonun arkasında ya da ayrı ofislerde yürüttüğü idari ve teknik işlerdir.","ornek":"Saat 15.00, banko arkasındaki ofis: rezervasyon şefi önümüzdeki haftanın doluluğuna bakar, ön büro müdürü ise gelecek ayın vardiya çizelgesini gözden geçirir.","sektor":"Oda müsaitliğini izlemek, rezervasyonları sisteme işlemek, konuk hesaplarını takip etmek, rapor hazırlamak, acentelerle sözleşme yapmak ve vardiya planlamak bu gruptadır. Öteki bölümlere yazılı ya da dijital not (memorandum) göndermek de buradan yürür; konuk bu işleri görmez ama eksikliğini hemen hisseder.","iliskili":["os-3-104","os-3-100","os-3-162"],"kontrol":null,"cizim":"grafik"},{"id":"os-3-106","konu":"3.2","terim":"Kambiyo işlemleri","ingilizce":"Foreign exchange","tanim":"Konuğun yabancı parasının, ilan edilen kur üzerinden Türk lirasına çevrilmesi gibi döviz işlemleridir.","ornek":"Akşam 19.00, resepsiyon: Alman konuk taksi için bir miktar avro bozdurmak ister; görevli panodaki kuru gösterir, parayı konuğun önünde sayar ve fişini verir.","sektor":"Para işinde tek ölçü dürüstlüktür: kur açıkça ilan edilir, para konuğun gözü önünde sayılır, işlem kayda geçer. Küçük bir eksik bile konuğun otele duyduğu güveni sarsar.","iliskili":["os-3-104","os-3-145","os-3-118"],"kontrol":null,"gorsel":"doviz"},{"id":"os-3-107","konu":"3.2.4","terim":"Walk-in konuk","ingilizce":"Walk-in guest","tanim":"Önceden rezervasyon yaptırmadan doğrudan tesise gelip oda isteyen konuktur.","ornek":"Gece 22.30, Afyonkarahisar: yolda yorulan bir aile otoparka girer ve resepsiyona “Bu gece için boş odanız var mı?” diye sorar.","sektor":"Ders kitabı bu konuğu oda fiyatları panosu anlatılırken anar: fiyatı ilk kez bankoda öğrenecek olan odur. Boş kalacak bir oda satıldığı için otel kazanır; görevli için de iyi bir satış fırsatıdır.","iliskili":["os-3-146","os-3-108","os-3-183"],"kontrol":null,"gorsel":"h3a-walk-in-konuk"},{"id":"os-3-108","konu":"3.5.1","terim":"No-show konuk","ingilizce":"No-show","tanim":"Rezervasyonu olduğu hâlde iptal etmeden ve haber vermeden tesise gelmeyen konuktur.","ornek":"Gece 24.00, resepsiyon: bugün gelmesi beklenen 208 numaralı odanın konuğu ne gelmiş ne aramıştır; görevli durumu kayda geçirir ve sabah rezervasyon birimine bildirir.","sektor":"O gece oda boş kalır ve satılamayan gece geri gelmez. Oteller bu yüzden rezervasyonu kredi kartı ya da şirket garantisiyle güvenceye almak ister; gelmeyen konuk için ne yapılacağını işletmenin kuralı belirler. Ders kitabı “no-show” sözünü iş planı bölümünde, fazla rezervasyonla birlikte anar.","iliskili":["os-3-107","os-3-109","os-3-150"],"kontrol":null,"gorsel":"h3a-no-show-konuk"},{"id":"os-3-109","konu":"3.5.1","terim":"Overbooking (fazla rezervasyon)","ingilizce":"Overbooking","tanim":"İptallere ve gelmeyen konuklara karşı önlem olarak tesisin oda kapasitesinden fazla rezervasyon almasıdır.","ornek":"Temmuz, Bodrum: otel bir gece için odalarının tamamından birkaç fazla rezervasyon almıştır; iptal beklenenden az çıkınca akşam gelen son konuğa verilecek oda kalmaz.","sektor":"Ders kitabı fazla rezervasyonu iş planı bölümünde ayrıca işler; uygulama etkinliğinde ise “çifte rezervasyon” senaryosu olarak geçer. Oda bulunamazsa konuk kapıda bırakılmaz: amire haber verilir, konuk için eşdeğer bir tesiste yer ayarlanır ve özür dilenir.","iliskili":["os-3-108","os-3-151","os-3-127"],"kontrol":null},{"id":"os-3-110","konu":"3.2","terim":"Logbook (vardiya defteri)","ingilizce":"Logbook (handover book)","tanim":"Vardiyada yaşanan önemli olayların ve sonraki vardiyanın bilmesi gerekenlerin yazıldığı, vardiyalar arası iletişim defteridir.","ornek":"Sabah 07.00, resepsiyon: gündüz görevlisi defteri açar ve gece yazılan notu okur: “305 numaralı odanın konuğu 09.00’da taksi istiyor; 112 numaralı odanın kliması arızalı, teknik servise bildirildi.”","sektor":"Otel yirmi dört saat açıktır ama kimse yirmi dört saat çalışmaz; bilgi defterle devredilir. Deftere yazılmayan iş, sonraki vardiya için hiç olmamış gibidir ve konuk aynı isteği ikinci kez söylemek zorunda kalır.","iliskili":["os-3-162","os-3-130","os-3-129"],"kontrol":null,"kitapDisi":true},{"id":"os-3-420","konu":"3.2","terim":"Profil inceleme","ingilizce":"Guest profile review","tanim":"Konuk gelmeden önce kayıtlarındaki geçmiş konaklamaların, tercihlerin ve özel isteklerin gözden geçirilmesidir.","ornek":"Perşembe 16.00, rezervasyon ofisi: görevli cuma gelecek konuğun kaydına bakar; geçen sefer sessiz oda istediğini görür ve odayı buna göre ayırır.","sektor":"Ders kitabı profil incelemeyi konuk döngüsünün varış öncesi evresine, rezervasyon alımı ve oda blokajıyla birlikte yazar. Konuk tarihçe kartı bu inceleme için kullanılabilecek kayıtlardandır.","iliskili":["os-3-160","os-3-101","os-3-403"],"kontrol":null,"cizim":"sosyal-medya"},{"id":"os-3-111","konu":"3.2.1","terim":"Ön büro organizasyon şeması","ingilizce":"Front office organisation chart","tanim":"Ön büroda kimin kime bağlı olduğunu, görev, yetki ve sorumlulukları ast üst sırasıyla gösteren çizelgedir.","ornek":"Stajın ilk günü: resepsiyon şefi personel panosundaki şemayı gösterir; stajyer, resepsiyon görevlisinin şefe, şefin de ön büro müdürüne bağlı olduğunu görür.","sektor":"Şema, bir sorun çıktığında kime gidileceğini söyler: stajyer amirine, amiri kendi üstüne bildirir. Şemanın biçimi her otelde aynı değildir; tesis büyüdükçe basamak ve birim sayısı artar.","iliskili":["os-3-112","os-3-113","os-3-114"],"kontrol":null},{"id":"os-3-112","konu":"3.2.1","terim":"Küçük ölçekli otelde ön büro","ingilizce":"Front office in a small hotel","tanim":"Butik otel gibi küçük tesislerde resepsiyon, santral ve bazen bagaj taşıma gibi birçok görevin tek kişide toplandığı yalın yapıdır.","ornek":"Alaçatı’da bir butik otel, saat 17.00: aynı görevli telefona bakar, gelen çiftin kaydını yapar ve valizlerini üst kata çıkarmalarına yardım eder.","sektor":"Bu otellerde çok yönlü beceri ve samimiyet öne çıkar. Konuk çoğu zaman tek bir yüz görür; o kişinin tavrı, otelin tavrı olur.","iliskili":["os-3-111","os-3-113","os-3-114"],"kontrol":null,"cizim":"resepsiyon"},{"id":"os-3-113","konu":"3.2.1","terim":"Orta ölçekli otelde ön büro","ingilizce":"Front office in a mid-sized hotel","tanim":"Görevlerin ayrışmaya başladığı, ön büro müdürüne bağlı şeflerin ve ayrı görevlilerin bulunduğu yapıdır.","ornek":"Kuşadası’nda bir tatil oteli: rezervasyon memuru telefonla oda ayırır, resepsiyon şefi bankodaki ekibi yönetir, ödemeleri ön kasa görevlisi alır.","sektor":"Resepsiyon şefi, rezervasyon memuru ve ön kasa elemanı gibi unvanlar bu ölçekte belirir. Uzmanlaşma başlamıştır ama ekip küçük olduğu için bilgi hâlâ kısa yoldan dolaşır.","iliskili":["os-3-112","os-3-114","os-3-126"],"kontrol":null,"gorsel":"h3a-orta-olcekli-otelde-on"},{"id":"os-3-114","konu":"3.2.1","terim":"Büyük ölçekli otelde ön büro","ingilizce":"Front office in a large hotel","tanim":"Her işin ayrı bir birimde uzman personelle yürütüldüğü, raporlama sırası kesin olan çok basamaklı yapıdır.","ornek":"Belek’te büyük bir tatil köyü: rezervasyon, santral, konuk ilişkileri, gece denetimi ve üniformalı hizmetler ayrı ekiplerdir; her ekibin kendi sorumlusu vardır.","sektor":"Genel müdüre bağlı odalar bölümü müdürü bulunur; onun altında ön büro müdürü yer alır. Bellboy ve concierge gibi kıyafetiyle tanınan ekip “üniformalı hizmetler” adını taşır. Uzmanlaşma hizmeti hızlandırır; bilgi ise ancak düzenli raporlamayla doğru yere ulaşır.","iliskili":["os-3-113","os-3-125","os-3-128"],"kontrol":null},{"id":"os-3-415","konu":"3.2.1","terim":"Odalar bölümü müdürü","ingilizce":"Rooms division manager","tanim":"Büyük otellerde genel müdüre bağlı çalışan; ön büro ve kat hizmetleri gibi oda işlerini yürüten bölümlerin üstünde yer alan yöneticidir.","ornek":"Belek’te beş yıldızlı bir tatil köyü, sabah 08.30: odalar bölümü müdürü toplantıda ön büro müdüründen ve kat hizmetleri müdüründen gün içindeki giriş ve çıkış yoğunluğunu dinler, iş bölümünü buna göre kararlaştırır.","sektor":"Ders kitabına göre büyük ölçekli otelde genel müdürün altında odalar bölümü müdürü, onun altında ön büro müdürü bulunur; kat hizmetleri müdürü de büyük tesislerde odalar bölümü müdürüne karşı sorumludur. Küçük ve orta ölçekli tesislerde bu basamak genellikle yoktur.","iliskili":["os-3-125","os-3-204","os-3-114"],"kontrol":null,"cizim":"lider"},{"id":"os-3-115","konu":"3.2.2","terim":"Rezervasyon birimi","ingilizce":"Reservations","tanim":"Konaklama taleplerini alan, oda satışını gerçekleştiren ve bu kayıtları tutan ön büro birimidir.","ornek":"Saat 11.00, rezervasyon ofisi: görevli, ağustosun ilk haftası için arayan aileye boş oda tiplerini ve fiyatları söyler, kaydı sisteme işler.","sektor":"Konukla ilk temas çoğu zaman buradadır. Kitap bu birimde doğru ve güvenilir olmayı, dijital okuryazarlığı ve dikkatli çalışmayı öne çıkarır: yanlış girilen tek bir tarih, kapıda oda bekleyen bir konuk demektir.","iliskili":["os-3-131","os-3-127","os-3-150"],"kontrol":null,"cizim":"resepsiyon"},{"id":"os-3-116","konu":"3.2.2","terim":"Resepsiyon","ingilizce":"Reception (front desk)","tanim":"Konukları karşılayan, giriş işlemlerini yapan ve oda tahsis eden ön büro birimidir.","ornek":"Saat 14.00, lobi: otobüsten inen konuklar bankoya yönelir; görevliler sırayla kayıtlarını yapar ve oda kartlarını verir.","sektor":"Otelin en görünür noktasıdır. Öne çıkan özellikler etkili iletişim, empati ve profesyonel dış görünümdür; konuk aklındaki her soruyu önce buraya getirir.","iliskili":["os-3-130","os-3-126","os-3-135"],"kontrol":null,"cizim":"resepsiyon"},{"id":"os-3-117","konu":"3.2.2","terim":"Bell desk (bagaj hizmetleri)","ingilizce":"Bell desk","tanim":"Bagaj taşıma, konuğu odasına yerleştirme ve genel bilgilendirme işlerini yürüten ön büro birimidir.","ornek":"Saat 15.10, otel girişi: bellboy valizleri arabaya dizer, konukla birlikte asansöre yürür ve odaya varınca klimanın nasıl çalıştığını gösterir.","sektor":"Nazik ve saygılı olmak, sorumluluk bilinci ve fiziksel dayanıklılık bu birimin öne çıkan özellikleridir. Konuğun eşyası emanettir; tek bir valizin karışması bütün karşılamayı gölgeler.","iliskili":["os-3-133","os-3-148","os-3-128"],"kontrol":null,"cizim":"bavul"},{"id":"os-3-118","konu":"3.2.2","terim":"Ön büro kasası","ingilizce":"Front office cashier","tanim":"Konuk hesaplarını takip eden, ödemeleri alan ve fatura düzenleyen ön büro birimidir.","ornek":"Sabah 09.30, resepsiyon: ön kasa görevlisi çıkış yapan konuğun hesabını ekranda açar, ödemeyi kartla alır ve faturasını verir.","sektor":"Dürüstlük, mahremiyete saygı ve hesap yapabilme becerisi burada şarttır. Konuğun ne harcadığı yalnız konuğu ilgilendirir; kasada çıkan açık ise parayla birlikte güveni de eksiltir. Ders kitabına göre ön kasa aynı zamanda döviz işlemlerinin yapıldığı mali merkezdir; otomasyon programları sayesinde görevleri çoğu tesiste resepsiyonla birleştirilmiştir.","iliskili":["os-3-156","os-3-159","os-3-137"],"kontrol":null},{"id":"os-3-119","konu":"3.2.2","terim":"Santral","ingilizce":"Switchboard","tanim":"Tesisin telefon trafiğini yöneten, mesajları ileten ve uyandırma hizmeti veren ön büro birimidir.","ornek":"Sabah 06.30, santral: görevli 214 numaralı odayı arar ve “Günaydın efendim, saat altı buçuk; uyandırma servisiniz” der.","sektor":"Kitap bu birimde düzgün diksiyonu ve sabrı öne çıkarır; santral memuru konuğu görmez, konuk da yalnız sesi duyar. Yangın ya da sağlık sorunu gibi acil durumlarda haberleşmeyi santral yönetir: 112 aranır, amire hemen haber verilir. Unutulan tek bir uyandırma ise kaçan bir uçak olabilir.","iliskili":["os-3-129","os-3-168","os-3-116"],"kontrol":null,"gorsel":"t14b-santral-fisleri"},{"id":"os-3-402","konu":"3.2.3","terim":"Uyandırma hizmeti (wake-up call)","ingilizce":"Wake-up call","tanim":"Konuğun istediği saatte telefonla ya da sistem aracılığıyla uyandırılmasını sağlayan, santralin kaydedip yerine getirdiği hizmettir.","ornek":"Gece 22.30, 214 numaralı odadaki konuk sabah 05.30’a uyandırma ister; santral memuru saati ve oda numarasını konuğa tekrar eder, talebi sisteme girer ve zamanı gelince arar.","sektor":"Ders kitabı uyandırma hizmetini santral memurunun görevleri arasında sayar: talep sisteme kaydedilir ve belirlenen saatte titizlikle yapılır. Saat ve oda numarasını konuğa geri okumak yanlış kayıtları önler. Sabah uçuşu ya da toplantısı olan konuk için bu küçük hizmet güvenin ölçüsüdür.","iliskili":["os-3-119","os-3-116"],"kontrol":null,"gorsel":"t14b-uyandirma-telefon"},{"id":"os-3-120","konu":"3.2.2","terim":"Concierge (danışma)","ingilizce":"Concierge","tanim":"Konuklara şehir turu, bilet ve özel istekler konusunda yol gösteren ön büro birimidir.","ornek":"Akşam 18.00, İstanbul: konuk “Bu akşam Boğaz’da balık yemek istiyoruz” der; concierge uygun bir restoranda masa ayırtır ve taksi çağırır.","sektor":"Sorun çözme becerisi, geniş genel kültür ve yardımseverlik ister. İyi bir concierge şehri avucunun içi gibi bilir; konuğun “Bu otelde her şeyi hallediyorlar” demesini sağlayan çoğu zaman odur.","iliskili":["os-3-128","os-3-117","os-3-132"],"kontrol":null},{"id":"os-3-121","konu":"3.2.3","terim":"Ön büro personelinin genel özellikleri","ingilizce":"Front office staff qualities","tanim":"Bakımlı bir dış görünüş, olumlu kişisel özellikler ve mesleğin gerektirdiği bilgi ile beceriler, ön büroda çalışacak kişide aranan üç yetkinlik grubudur.","ornek":"Mayıs ayı, iş görüşmesi: ön büro müdürü adayın önce duruşuna ve kıyafetine bakar, sonra İngilizce bir soru sorar, en son “Sinirli bir konukla karşılaşsan ne yaparsın?” der.","sektor":"Ön büro çalışanı otelin profesyonelliğini temsil eder; konuk oteli çoğu zaman bankodaki kişiye bakarak değerlendirir. Üç grubun biri eksikse öteki ikisi onu kapatmaz.","iliskili":["os-3-122","os-3-123","os-3-124"],"kontrol":null,"cizim":"resepsiyon"},{"id":"os-3-122","konu":"3.2.3","terim":"Ön büroda dış görünüş","ingilizce":"Personal appearance (grooming)","tanim":"Kişisel hijyen ve bakım, temiz ve ütülü üniforma, dik ve kendinden emin duruş ile sade bir görünümden oluşan fiziksel özelliklerdir.","ornek":"Sabah 06.45, personel soyunma odası: görevli vardiyaya çıkmadan önce aynada yakasına, isim kartına ve ayakkabılarına bakar.","sektor":"Kitap kadınlarda sade makyajı, erkeklerde günlük tıraşı da bu başlıkta sayar. Özenli görünüm süs değil, konuğa gösterilen saygıdır; konuk daha tek söz duymadan otele ilk notunu verir.","iliskili":["os-3-121","os-3-123","os-3-130"],"kontrol":null,"cizim":"uniforma"},{"id":"os-3-123","konu":"3.2.3","terim":"Ön büro personelinin kişisel özellikleri","ingilizce":"Personal qualities","tanim":"Nazik, güler yüzlü ve sabırlı olmak; empati kurabilmek, sorun çözebilmek, hızlı karar verebilmek, dürüst olmak ve sır saklayabilmek gibi karakter özellikleridir.","ornek":"Saat 23.00, resepsiyon: uçağı geciken konuk sinirle bankoya gelir; görevli sakin kalır, sözünü kesmeden dinler ve “Çok yorulmuşsunuz, hemen odanıza alalım” der.","sektor":"Ön büro, konuğun kim olduğunu, hangi odada kaldığını ve ne harcadığını bilir; sır saklamak bu yüzden işin parçasıdır. Dürüstlük ise para ve anahtar emanet edilen bir bölümde vazgeçilmezdir.","iliskili":["os-3-121","os-3-124","os-3-154"],"kontrol":null},{"id":"os-3-124","konu":"3.2.3","terim":"Ön büro personelinin bilişsel ve teknik becerileri","ingilizce":"Cognitive and technical skills","tanim":"En az bir yabancı dili iyi konuşmak, otel otomasyon programlarını kullanmak, pazarlama ve satış tekniklerini bilmek, zamanı ve kriz anını yönetebilmek gibi sonradan kazanılan yetkinliklerdir.","ornek":"Saat 12.00, resepsiyon: görevli bir yandan İngiliz konuğa kahvaltı saatlerini İngilizce anlatır, bir yandan ekrandan çıkışı geciken odaları izler.","sektor":"Bu beceriler doğuştan gelmez; okulda, stajda ve işte kazanılır. Yabancı dil bilen ve otel programını iyi kullanan görevli hem konuğu bekletmez hem de mesleğinde daha hızlı yükselir.","iliskili":["os-3-121","os-3-136","os-3-183"],"kontrol":null,"cizim":"resepsiyon"},{"id":"os-3-125","konu":"3.2.3","terim":"Ön büro müdürü","ingilizce":"Front office manager","tanim":"Ön büronun bütün hizmetlerini planlayan, personelini yöneten, standartları belirleyip denetleyen ve öteki bölümlerle eşgüdümü sağlayan en üst düzey ön büro yöneticisidir.","ornek":"Pazartesi 09.00, bölüm toplantısı: müdür haftanın doluluk tahminini paylaşır, yoğun günler için vardiyaları güçlendirir ve yeni karşılama standardını anlatır.","sektor":"Dört ana işi vardır: planlama ve bütçe, personel yönetimi, standart belirleme ve denetim, koordinasyon. Vardiya çizelgelerini hazırlayan ve günlük işleyişin aksamamasını sağlayan müdür yardımcısı onun yükünü paylaşır.","iliskili":["os-3-126","os-3-127","os-3-114","os-3-185"],"kontrol":null,"cizim":"resepsiyon"},{"id":"os-3-185","konu":"3.2.3","terim":"Ön büro müdür yardımcısı","ingilizce":"Assistant front office manager","tanim":"Ön büro müdürünün operasyonel yükünü paylaşan, vardiya çizelgelerini hazırlayan ve günlük işleyişin aksamamasını sağlayan yöneticidir.","ornek":"Cuma sabahı 08.30, ön büro ofisi: müdür yardımcısı hafta sonu yoğunluğuna göre vardiya çizelgesini düzenler ve müdürün toplantıda olduğu saatlerde bankodaki ekibe yol gösterir.","sektor":"Müdür toplantıdayken ya da izindeyken günlük işleyiş durmaz; bunu müdür yardımcısı sürdürür. Kitap onu müdürün yükünü paylaşan, çizelgeleri hazırlayan kişi olarak anar; bilgi akışının kesilmemesi onun işidir.","iliskili":["os-3-125","os-3-126"],"kontrol":null,"cizim":"resepsiyon"},{"id":"os-3-126","konu":"3.2.3","terim":"Resepsiyon şefi","ingilizce":"Reception supervisor","tanim":"Giriş ve çıkış işlemlerinin doğruluğunu denetleyen, resepsiyon görevlilerinin vardiyasını planlayan ve onlara yol gösteren, bankodaki ekibin lideridir.","ornek":"Saat 13.30, resepsiyon: şef, akşam gelecek önemli konuğun odasının ayrıldığını kontrol eder; o sırada şikâyeti olan bir konuğu yeni görevliden devralıp kendisi dinler.","sektor":"Görevlinin yetkisini aşan konu şefe gider: şikâyet, özel istek, önemli konuk için oda ayırma. Kat hizmetleri ve teknik servisle sürekli haberleşerek odaların zamanında hazır olmasını da o izler.","iliskili":["os-3-130","os-3-125","os-3-116"],"kontrol":null,"cizim":"resepsiyon"},{"id":"os-3-127","konu":"3.2.3","terim":"Rezervasyon şefi","ingilizce":"Reservations supervisor","tanim":"Oda ayırma işlerini yürüten birimi yöneten, yapılan kayıtların doğruluğunu denetleyen, grup rezervasyonlarını ve oda kontenjanlarını izleyen sorumludur.","ornek":"Saat 10.00, rezervasyon ofisi: şef, bir acentenin kırk kişilik grup talebini inceler, o tarihlerdeki boş odalara bakar ve memura hangi odaların ayrılacağını söyler.","sektor":"Otelin sattığı şey odadır ve satılamayan gece geri gelmez. Doluluk tahminleri hazırlar, fiyat kararlarının uygulanmasını sağlar, ekibine iş başında eğitim verir; satış ve pazarlama bölümüyle sürekli iletişim hâlindedir.","iliskili":["os-3-131","os-3-115","os-3-167"],"kontrol":null,"cizim":"resepsiyon"},{"id":"os-3-403","konu":"3.2.3","terim":"Oda blokajı","ingilizce":"Room block","tanim":"Bir grup, acente ya da önemli bir konuk için belirli tarihlerde bazı odaların satışa kapatılıp ayrılmasıdır.","ornek":"Pazartesi 10.00, rezervasyon şefi: cumartesi gelecek bir düğün grubu için üçüncü kattaki odaları sistemde ayırır; o odalar artık başka konuğa satılamaz.","sektor":"Ders kitabı oda blokajını konuk döngüsünün varış öncesi evresine koyar (rezervasyon alımı, oda blokajı, profil inceleme) ve resepsiyon şefinin VIP blokajlarını koordine ettiğini söyler. Blokaj gerektiğinden fazla tutulursa satılabilecek oda boş kalır, az tutulursa grup konukları odasız kalır.","iliskili":["os-3-101","os-3-127","os-3-126"],"kontrol":null},{"id":"os-3-128","konu":"3.2.3","terim":"Danışma şefi","ingilizce":"Head concierge","tanim":"Konukların özel isteklerini karşılayan ve bellboy, kapı görevlisi, vale gibi üniformalı hizmetler ekibini yöneten sorumludur.","ornek":"Saat 17.00, lobi: danışma şefi akşam vardiyasındaki bellboylara gelecek grubun saatini bildirir, ardından bir konuğa ertesi günkü Kapadokya turu için yer ayırtır.","sektor":"Ekibinin vardiya düzenini hazırlar, hizmet standartlarını denetler ve iş başında eğitim verir. Konuklara şehir turu, restoran ve ulaşım konusunda bilgi verdiği için bilgisinin güncel ve doğru olması gerekir.","iliskili":["os-3-120","os-3-133","os-3-134"],"kontrol":null},{"id":"os-3-129","konu":"3.2.3","terim":"Gece müdürü","ingilizce":"Night manager","tanim":"Tesisin gece vardiyasındaki bütün sorumluluğunu üstlenen, günün hesaplarını denetleyip kapatan ve gece güvenliğini izleyen yöneticidir.","ornek":"Gece 02.00, resepsiyon: lobi sessizdir; gece müdürü gün içindeki hesap kayıtlarını tek tek kontrol eder, o sırada geç gelen bir konuğun girişini de yapar.","sektor":"Ders kitabına göre gece müdürü 23.00’ten sabah 07.00’ye kadar tesisin bütün sorumluluğunu üstlenir. Günün hesaplarının denetlenip kapatılmasına gece denetimi (night audit) denir: hatalı kayıtlar düzeltilir, doluluk ve gelir raporları sabaha hazır edilir. Gece herkes uyurken otelin hem kasası hem güvenliği ona emanettir; dürüstlük bu işin temelidir.","iliskili":["os-3-125","os-3-166","os-3-156"],"kontrol":null},{"id":"os-3-130","konu":"3.2.3","terim":"Resepsiyon görevlisi","ingilizce":"Receptionist","tanim":"Konukları karşılayan, giriş ve çıkış işlemlerini yapan, oda tahsis eden, bilgi veren ve istekleri ilgili bölümlere ileten temel ön büro personelidir.","ornek":"Saat 16.40, resepsiyon: görevli yeni gelen konuğun kaydını yapar, kahvaltı saatini söyler, ardından “Odamda havlu eksik” diyen başka bir konuk için kat hizmetlerini arar.","sektor":"Kitap onu “işletmenin aynası” diye tanımlar. Konuğun kişisel verilerini korur, para işlemlerini dürüstçe yapar; kat hizmetlerine oda durumunu, teknik servise arızayı bildirerek bölümler arasındaki bilgi akışını sağlar.","iliskili":["os-3-126","os-3-102","os-3-162"],"kontrol":null},{"id":"os-3-131","konu":"3.2.3","terim":"Rezervasyon memuru","ingilizce":"Reservations agent","tanim":"Telefon, e-posta ve internet üzerinden gelen oda taleplerini karşılayan, müsaitliği kontrol edip kesin kaydı oluşturan görevlidir.","ornek":"Saat 09.15, telefon: “Bayram tatili için dört kişilik yeriniz var mı?” diye soran konuğa memur boş oda tiplerini ve fiyatlarını söyler, kaydı adını harf harf doğrulayarak girer.","sektor":"Konuk oteli görmeden önce onun sesini duyar ya da e-postasını okur. Oda tiplerini, fiyatları ve otelin olanaklarını eksiksiz bilmesi gerekir; yanlış verilen bilgi, sonradan bankoda çıkan bir tartışmadır.","iliskili":["os-3-127","os-3-150","os-3-169"],"kontrol":null},{"id":"os-3-132","konu":"3.2.3","terim":"Konuk ilişkileri","ingilizce":"Guest relations","tanim":"Memnuniyeti artırmak, hizmeti kişiye özel kılmak ve şikâyetleri profesyonelce yönetmekle görevli ön büro birimidir.","ornek":"Saat 12.00, Marmaris: konuk ilişkileri görevlisi, otele üçüncü kez gelen çiftin evlilik yıl dönümünü kayıtlardan görür ve odalarına bir kutlama notu bıraktırır.","sektor":"VIP konukların ve otele tekrar tekrar gelen konukların (repeat guest) tercihlerini izler; anketleri ve internet yorumlarını inceleyerek neyin düzeltilmesi gerektiğini ortaya koyar. Şikâyeti empatiyle dinlenen konuk otele yeniden gelebilir; dinlenmeyen konuk ise yaşadığını başkalarına anlatır.","iliskili":["os-3-160","os-3-161","os-3-155"],"kontrol":null},{"id":"os-3-133","konu":"3.2.3","terim":"Bellboy (bagaj görevlisi)","ingilizce":"Bell attendant (porter)","tanim":"Konuğun bagajlarını taşıyan, ona odasına kadar eşlik eden ve odayı tanıtan üniformalı görevlidir.","ornek":"Saat 14.30, otel girişi: bellboy valizleri araçtan alır, konuğa odasına kadar eşlik eder, kapı kartının nasıl kullanıldığını ve acil çıkışın yerini gösterir.","sektor":"Kitapta “bellboy ve portör” diye geçer; Türkçesi bagaj görevlisidir. Konuk erken geldiğinde ya da çıkıştan sonra şehirde vakit geçirecekse bagajı bagaj odasında (luggage room) emanete alınır. Çoğu zaman konuğun karşılaştığı ilk personeldir.","iliskili":["os-3-117","os-3-148","os-3-134","os-3-186"],"kontrol":null,"gorsel":"t13f-bagaj-arabalari"},{"id":"os-3-186","konu":"3.2.3","terim":"Bagaj odası (luggage room)","ingilizce":"Luggage room","tanim":"Konuğun erken geldiğinde ya da çıkıştan sonra bagajını güvenle bıraktığı, bellboy ekibinin yönettiği emanet odasıdır.","ornek":"Sabah 10.00: uçağı akşam kalkacak konuk odasını boşaltır; bellboy valizleri etiketleyerek bagaj odasına alır, akşam konuk dönünce teslim eder.","sektor":"Eşya konuğun emanetidir: kime ait olduğu etiketle belli olur, teslimde konuğun kendisi olduğundan emin olunur. Bu hizmet konuğa çıkış sonrası günü şehirde rahatça geçirme imkânı verir.","iliskili":["os-3-133","os-3-117"],"kontrol":null},{"id":"os-3-134","konu":"3.2.3","terim":"Kapı görevlisi","ingilizce":"Doorman","tanim":"Giriş kapısında konukları karşılayıp uğurlayan, araç kapılarını açan ve konuğa yol gösteren üniformalı görevlidir.","ornek":"Yağmurlu bir akşam, saat 20.00: kapı görevlisi şemsiyesiyle taksiye yürür, kapıyı açar ve “Hoş geldiniz efendim” diyerek konuğu girişe kadar getirir.","sektor":"Kitap onu danışma şefinin yönettiği üniformalı hizmetler ekibinde, bellboy ve valeyle (konuğun aracını park eden görevli) birlikte anar. Otelin kapıdaki yüzüdür; konuk daha bankoya varmadan nasıl karşılanacağını ondan anlar.","iliskili":["os-3-128","os-3-133"],"kontrol":null,"cizim":"resepsiyon"},{"id":"os-3-411","konu":"3.2.3","terim":"Vale (araç park görevlisi)","ingilizce":"Valet (valet parking attendant)","tanim":"Konuğun aracını otelin girişinde teslim alıp park eden ve konuk istediğinde geri getiren üniformalı görevlidir.","ornek":"Akşam 19.00, otel girişi: konuk aracını kapıya bırakır, vale anahtarı alıp ona bir numara kartı verir; konuk dönmek istediğinde araç kapıda hazırdır.","sektor":"Vale, araçla gelen konuğu otelin kapısında karşılayan ilk kişilerden biridir; konuğun aracı da bagajı gibi onun emanetidir. Ders kitabına göre vale, danışma şefinin yönettiği üniformalı hizmetler ekibinde bellboy ve kapı görevlisiyle birlikte yer alır; araç ve vale hizmetlerini yönetmek danışma ekibinin görevleri arasındadır.","iliskili":["os-3-134","os-3-412","os-3-128"],"kontrol":null,"cizim":"resepsiyon"},{"id":"os-3-413","konu":"3.2.3","terim":"Santral memuru","ingilizce":"Telephone operator (switchboard operator)","tanim":"Tesisin iç ve dış telefon görüşmelerini yönlendiren, mesajları ileten, uyandırma taleplerini kaydedip zamanında yerine getiren ve acil durumlarda haberleşmeyi yöneten ön büro görevlisidir.","ornek":"Sabah 06.30, santral: memur, bir gece önce sisteme girilen uyandırma taleplerini sırayla yerine getirir; 214 numaralı odayı arar ve konuk telefona çıkana kadar sabırla bekler.","sektor":"Santral memuru sesiyle çalışır: konuk onu görmez, yalnız nezaketini ve sakinliğini duyar. Yangın, sağlık sorunu ya da güvenlik ihlali gibi anlarda telefon trafiğini yöneterek haberin ilgili birimlere hızla ulaşmasını sağlar.","iliskili":["os-3-119","os-3-402","os-3-129"],"kontrol":null,"cizim":"telefon"},{"id":"os-3-414","konu":"3.2.3","terim":"Gece denetimi","ingilizce":"Night audit","tanim":"Günün sonunda konuk hesaplarının, gelirlerin ve kayıtların kontrol edilip hataların düzeltilmesi ve gün sonu işleminin yapılmasıdır.","ornek":"Gece 02.00, resepsiyon: gece müdürü gün içinde işlenen oda ve restoran harcamalarını tek tek kontrol eder, yanlış odaya işlenmiş bir kaydı düzeltir ve gün sonu işlemini başlatır.","sektor":"Ders kitabı gün sonu işlemini gece müdürünün görevleri arasında sayar; büyük otellerin ön büro şemasında ise “gece denetimi” ayrı bir birim olarak yer alır. Sabaha doluluk ve gelir raporları bu işlemin sonunda hazır olur.","iliskili":["os-3-129","os-3-156","os-3-419"],"kontrol":null,"cizim":"saat-zaman"},{"id":"os-3-135","konu":"3.2.4","terim":"Resepsiyon bankosu","ingilizce":"Reception desk (front desk)","tanim":"Konuklarla personelin buluştuğu, kayıt ve ödeme işlemlerinin yapıldığı ana çalışma alanıdır.","ornek":"Saat 08.00, lobi: gündüz vardiyası başlarken görevli bankonun üstünü toplar, kalemleri ve boş formları yerine koyar.","sektor":"Banko otelin vitrinidir. Üzerinde dağınık kâğıt, çay bardağı ya da kişisel telefon durması konuğa özensizlik mesajı verir; konuğa ait belgeler de başkasının göreceği biçimde bırakılmaz.","iliskili":["os-3-116","os-3-136","os-3-137"],"kontrol":null,"gorsel":"karsilama-bankosu"},{"id":"os-3-136","konu":"3.2.4","terim":"Bilgisayar terminali (PMS)","ingilizce":"Computer terminal (PMS)","tanim":"Tesisin oda ve konuk durumunun izlendiği otel yazılımının kurulu olduğu bilgisayar sistemidir.","ornek":"Saat 13.00, resepsiyon: görevli ekranda hangi odaların hazır olduğuna bakar ve erken gelen konuğa hazır olan odalardan birini verir.","sektor":"Bu yazılıma otel otomasyon sistemi ya da PMS (property management system) denir; rezervasyon, kayıt, oda durumu ve konuk hesabı aynı programda tutulur. Formların çoğu artık bu sistemde dijital olarak yönetilir; yanlış girilen veri ise bütün bölümlere yanlış gider.","iliskili":["os-3-143","os-3-156","os-3-124"],"kontrol":null,"cizim":"dijital"},{"id":"os-3-137","konu":"3.2.4","terim":"POS cihazı","ingilizce":"POS terminal (point of sale)","tanim":"Banka ya da kredi kartıyla ödeme almak ve kart üzerinde ön provizyon işlemi yapmak için kullanılan cihazdır.","ornek":"Çıkış sırasında görevli “Kartınız temassız mı efendim?” diye sorar; konuk kartını cihaza yaklaştırır ve fiş çıkar.","sektor":"Tutar konuğa söylenmeden ve gösterilmeden işlem yapılmaz; kart konuğun gözünün önünden ayrılmaz. Yanlış tuşlanan tek bir rakam hem konuğu hem kasayı uğraştıran bir düzeltme demektir.","iliskili":["os-3-138","os-3-118","os-3-103"],"kontrol":null,"gorsel":"t14b-pos-cihazi"},{"id":"os-3-138","konu":"3.2.4","terim":"Ön provizyon","ingilizce":"Pre-authorisation","tanim":"Konuğun kredi kartındaki belirli bir tutarın, harcamalara karşı güvence olarak geçici süreyle ayrılması işlemidir.","ornek":"Giriş sırasında görevli “Ekstra harcamalarınız için kartınızdan provizyon alacağım efendim; bu tutar hesabınızdan çekilmiyor, yalnız ayrılıyor” der.","sektor":"Provizyon tahsilat değildir: tutar karttan çekilmez, yalnızca ayrılır ve çıkışta gerçek hesaba göre işlem yapılır. Konuğa önceden açıklanmazsa telefonuna gelen bildirim “Benden habersiz para çekildi” şikâyetine dönüşür.","iliskili":["os-3-137","os-3-102","os-3-156"],"kontrol":null},{"id":"os-3-139","konu":"3.2.4","terim":"Pasaport okuyucu","ingilizce":"Passport scanner","tanim":"Konuğun kimlik ya da pasaport bilgilerini okuyup otel sistemine hızla aktaran cihazdır.","ornek":"Saat 15.00, resepsiyon: görevli Hollandalı konuğun pasaportunu cihaza yerleştirir; ad, soyad ve belge numarası ekrandaki kayıt alanlarına kendiliğinden dolar.","sektor":"Elle yazarken bir harf ya da rakam kolayca yanlış girilir; cihaz hem girişi hızlandırır hem de yasal kimlik bildiriminin hatasız yapılmasını sağlar. Okuma bitince belge konuğa hemen geri verilir.","iliskili":["os-3-153","os-3-152","os-3-102"],"kontrol":null,"cizim":"pasaport"},{"id":"os-3-140","konu":"3.2.4","terim":"Kapı kartı programlama makinesi","ingilizce":"Key card encoder","tanim":"Elektronik kapı kartını, konuğun konaklama süresi boyunca kendi odasının kapısını açacak biçimde programlayan cihazdır.","ornek":"Girişte görevli kartı makineye yerleştirir, oda numarasını ve ayrılış tarihini girer; kart artık yalnız 412’nin kapısını, yalnız o tarihe kadar açar.","sektor":"Tesislerin büyük bölümünde anahtarın yerini elektronik kart almıştır. Kartın süresi dolunca kapıyı açmaz; kaybolursa yenisi programlanır. Kartı isteyen kişinin o odanın konuğu olduğundan emin olunmadan kart yapılmaz.","iliskili":["os-3-141","os-3-142","os-3-102"],"kontrol":null,"cizim":"resepsiyon"},{"id":"os-3-141","konu":"3.2.4","terim":"Anahtar ve mesaj panosu","ingilizce":"Key and message rack","tanim":"Kapı kartı yerine anahtar kullanan tesislerde, her oda için ayrılmış gözlerine oda anahtarlarının ve konuğa bırakılan notların konduğu panodur.","ornek":"Safranbolu’da bir konak otel: dışarı çıkan konuk anahtarını bankoya bırakır; akşam döndüğünde görevli anahtarla birlikte gözde bekleyen notu da verir.","sektor":"Elektronik kart kullanan tesislerde bu işi bilgisayar görür. Anahtarın gözde durması konuğun o sırada dışarıda olduğunu gösterebilir; bu yüzden anahtar, odanın konuğu olduğundan emin olunmayan kişiye verilmez.","iliskili":["os-3-140","os-3-143","os-3-154"],"kontrol":null,"gorsel":"os-anahtar-panosu"},{"id":"os-3-142","konu":"3.2.4","terim":"Genel pas anahtarı","ingilizce":"Grand master key","tanim":"Acil durumlarda kullanılmak üzere güvenli biçimde saklanan ve tesisin bütün oda kapılarını açabilen anahtardır.","ornek":"Gece 03.00: bir odadan duman kokusu geldiği bildirilir, kapıyı açan olmaz; yetkili amir genel pas anahtarıyla, güvenlik görevlisi eşliğinde odaya girer.","sektor":"Bütün kapıları açan bir anahtar, otelin en büyük emanetidir. Kimin, ne zaman ve neden aldığı kayda geçer; yetkisiz kişiye verilmez. Kaybolması bütün konukların güvenliğini ilgilendirir ve hemen amire bildirilir.","iliskili":["os-3-140","os-3-168","os-3-129"],"kontrol":null,"kitapDisi":true,"cizim":"resepsiyon"},{"id":"os-3-143","konu":"3.2.4","terim":"Oda durum panosu","ingilizce":"Room rack","tanim":"Bilgisayarın kullanılmadığı durumlarda odaların boş, dolu, kirli ya da temiz olduğunu ve konaklama bilgilerini bir bakışta gösteren araçtır.","ornek":"Küçük bir pansiyon, saat 12.00: görevli panoya bakar; 3 numaralı oda “temiz” olarak işaretlenmiştir, yeni gelen konuğu oraya yerleştirir.","sektor":"Bugün bu işi çoğu tesiste otel yazılımı yapar, ama mantık aynıdır: satılacak oda hem boş hem temiz olmalıdır. Pano ya da ekran güncel değilse konuk kirli ya da dolu bir odaya gönderilir.","iliskili":["os-3-136","os-3-163","os-3-141"],"kontrol":null,"gorsel":"os-oda-durum-panosu"},{"id":"os-3-144","konu":"3.2.4","terim":"Folyo havuzu","ingilizce":"Folio bucket (pit)","tanim":"Her konuğa ait belgelerin ve makbuzların oda numarasına göre gruplanıp topluca saklandığı dosya rafıdır.","ornek":"Akşam 21.00, resepsiyon: restorandan gelen imzalı adisyon 318 numaralı odanın gözüne konur; çıkışta konuk sorarsa belge hazırdır.","sektor":"Kitapta “pit” adıyla da geçer. Konuk hesabındaki bir kaleme itiraz ettiğinde imzalı belge buradan çıkarılır; belgesi bulunamayan harcamanın tahsili zordur.","iliskili":["os-3-156","os-3-157","os-3-159"],"kontrol":null,"gorsel":"h3a-folyo-havuzu"},{"id":"os-3-145","konu":"3.2.4","terim":"Döviz panosu","ingilizce":"Exchange rate board","tanim":"Tesisin uyguladığı güncel döviz kurlarını konukların görebileceği biçimde gösteren panodur.","ornek":"Sabah 09.00, resepsiyon: görevli günün kurlarını panoya işler; öğlen para bozduran konuk hangi kurun uygulandığını panodan kendisi okur.","sektor":"Amaç şeffaflıktır: konuk kuru yalnız görevliden duymaz, kendisi de görür. Pano güncel değilse ya da bankoda söylenen kurla uyuşmuyorsa konuk aldatıldığını düşünür.","iliskili":["os-3-106","os-3-146"],"kontrol":null},{"id":"os-3-146","konu":"3.2.4","terim":"Oda fiyatları panosu","ingilizce":"Room rates board","tanim":"Tesisin oda fiyatlarının, özellikle rezervasyonsuz gelen konukların görebileceği bir yerde ilan edildiği panodur.","ornek":"Gece 22.30: rezervasyonsuz gelen aile bankoda beklerken panodaki çift kişilik oda fiyatını okur; görevlinin söylediği fiyat panodakiyle aynıdır.","sektor":"Fiyatın açıkça ilan edilmesi hem konuğu hem görevliyi korur: kimse “Bana fazla fiyat söylendi” diyemez. Bankoda söylenen fiyat ile panoda yazan fiyat birbirini tutmalıdır.","iliskili":["os-3-107","os-3-145","os-3-169"],"kontrol":null,"cizim":"para-butce"},{"id":"os-3-147","konu":"3.2.4","terim":"Duyuru panosu","ingilizce":"Notice board","tanim":"Tesiste kalan konukları bilgilendirmek için lobide, ön büroya yakın bir yerde duran panodur.","ornek":"Kapadokya’da bir otel, akşam 19.00: grup rehberi panoya “Yarın balon turu için lobide buluşma 05.15” notunu asar.","sektor":"Grup hâlinde kalan konuklara ulaşmak için rehberler de bu panoyu yoğun biçimde kullanır. Tarihi geçmiş bir duyuru panoda kalırsa konuğu yanlış yönlendirir; pano her gün gözden geçirilir.","iliskili":["os-3-146","os-3-145"],"kontrol":null,"cizim":"megafon"},{"id":"os-3-148","konu":"3.2.4","terim":"Bagaj arabası","ingilizce":"Luggage trolley","tanim":"Bellboyların ağır valizleri güvenli ve hızlı biçimde odalara taşımasına yarayan tekerlekli araçtır.","ornek":"Saat 14.00, otel girişi: grubun valizleri otobüsten indirilir; bellboylar bunları arabalara dizer ve kat kat odalara dağıtır.","sektor":"Konuğun valizi yerde sürüklenmez, üst üste gelişigüzel atılmaz. Araba hem konuğun eşyasını hem personelin belini korur; lobiden geçtiği için temiz ve bakımlı olması da otelin özenini gösterir.","iliskili":["os-3-133","os-3-117"],"kontrol":null,"cizim":"bavul"},{"id":"os-3-149","konu":"3.2.4","terim":"Konuk döngüsünde kullanılan formlar","ingilizce":"Front office forms","tanim":"Konaklamayı yasal, mali ve operasyonel açıdan kayıt altına alan ve konuk döngüsünün her evresinde kullanılan belgelerdir.","ornek":"Bir konuğun dosyası: gelmeden önce rezervasyon formu ve teyit mektubu, girişte konaklama belgesi, kalırken folyo, ayrılırken fatura ve anket.","sektor":"Rezervasyonda rezervasyon formu ile teyit mektubu; girişte konaklama belgesi ile VIP bildirim formu; konaklamada folyo, ödeme fişi ve düzeltme fişi; ayrılışta fatura, konuk tarihçe kartı ve anket kullanılır. Çoğu bugün dijitaldir, ama her birinin görevi aynı kalmıştır.","iliskili":["os-3-101","os-3-150","os-3-156"],"kontrol":null,"cizim":"belge-form"},{"id":"os-3-150","konu":"3.2.4","terim":"Rezervasyon formu","ingilizce":"Reservation form","tanim":"Konuğun konaklama talebini kayıt altına almak, izlemek ve onaylamak için kullanılan temel belgedir.","ornek":"Saat 10.20, telefon: görevli konuğun adını, geliş ve ayrılış tarihini, kişi sayısını, oda tipini ve “bebek yatağı” isteğini forma tek tek işler.","sektor":"Formda kişisel bilgiler, konaklama tarihleri, oda tercihi, ödeme ya da garanti bilgisi ve özel istekler yer alır. Konuk gelmeden doldurulur; ön büro konuğu neyle karşılayacağını bu formdan öğrenir.","iliskili":["os-3-151","os-3-131","os-3-149"],"kontrol":null,"cizim":"belge-form"},{"id":"os-3-404","konu":"3.2.4","terim":"Fiyat kodu","ingilizce":"Rate code","tanim":"Rezervasyon kaydında, konuğa hangi fiyat tarifesinin uygulanacağını gösteren kısa koddur.","ornek":"Bir şirket çalışanı için rezervasyon yapan görevli, kayıtta kurumsal tarifeyi gösteren kodu seçer; konuk gelince oda fiyatı sistemde doğru çıkar.","sektor":"Ders kitabı rezervasyon formunun ödeme bilgileri bölümünde garanti yöntemiyle birlikte fiyat kodunu sayar. Aynı oda acente, şirket ya da kampanya gibi farklı tarifelerle satılabilir; yanlış kod seçilirse çıkışta hesap yanlış çıkar. Kodların adları işletmeden işletmeye değişir.","iliskili":["os-3-150","os-3-146","os-3-136"],"kontrol":null},{"id":"os-3-151","konu":"3.2.4","terim":"Teyit mektubu","ingilizce":"Confirmation letter","tanim":"Tesisin rezervasyon talebini kabul ettiğini ve tarih, oda tipi, fiyat, iptal şartları gibi ayrıntıları onayladığını konuğa bildiren yazılı belgedir.","ornek":"Rezervasyondan birkaç dakika sonra konuğun e-postasına bir yazı düşer: rezervasyon numarası, giriş ve ayrılış tarihleri, oda tipi, toplam tutar ve iptal koşulları.","sektor":"Konuk ile işletme arasında sözleşme niteliği taşır ve otelin konukla kurduğu ilk yazılı iletişimdir. Kapıda “Bana deniz manzaralı oda söylenmişti” tartışması çıktığında bakılacak belge budur. Ders kitabındaki örnek mektupta giriş saati 14.00, ayrılış saati 12.00 olarak yazılıdır; konaklama tipi (örneğin oda kahvaltı), toplam tutar ve iptal politikası da yer alır (örnekte giriş tarihinden 24 saat öncesine kadar yapılan iptallerde ücret iadesi vardır). Bu koşullar işletmeden işletmeye değişir.","iliskili":["os-3-150","os-3-109","os-3-149"],"kontrol":null,"cizim":"belge-form"},{"id":"os-3-152","konu":"3.2.4","terim":"Konaklama belgesi","ingilizce":"Registration card","tanim":"Girişte konuğun kimlik ve konaklama bilgilerinin yazıldığı, konuğun imzalayarak tesisin kurallarını ve kişisel verilerinin işlenmesini kabul ettiği belgedir.","ornek":"Saat 15.20, resepsiyon: görevli belgeyi konuğa uzatır ve “Bilgilerinizi kontrol edip şurayı imzalar mısınız efendim?” der.","sektor":"Konuğun ıslak imzasını taşıdığı için yasal açıdan en kritik ön büro belgesidir; kitap onu otel ile konuğun “tanışma formu” diye anlatır. İmzasız belge, eksik yapılmış bir giriştir.","iliskili":["os-3-153","os-3-154","os-3-102"],"kontrol":null},{"id":"os-3-153","konu":"3.2.4","terim":"Kimlik Bildirim Sistemi (KBS)","ingilizce":"Identity Notification System (KBS)","tanim":"Konaklama tesislerinin, kalan konukların kimlik bilgilerini emniyet birimlerine iletmek için kullandığı bildirim sistemidir.","ornek":"Gece 23.50, resepsiyon: geç gelen konuğun kimlik bilgileri pasaport okuyucuyla sisteme alınır ve kimlik bildirimi sistem üzerinden yapılır.","sektor":"Kimlik bildirimi tercihe bağlı değil, yasal zorunluluktur. “Kimliğim yanımda değil, sonra getiririm” diyen konuğun kaydına görevli kendi başına karar vermez; durumu amirine bildirir.","iliskili":["os-3-152","os-3-139","os-3-154"],"kontrol":null,"cizim":"resepsiyon"},{"id":"os-3-154","konu":"3.2.4","terim":"KVKK (Kişisel Verilerin Korunması Kanunu)","ingilizce":"Personal Data Protection Law","tanim":"Kişisel verilerin nasıl toplanacağını, işleneceğini ve korunacağını düzenleyen 6698 sayılı Kişisel Verilerin Korunması Kanunu’dur.","ornek":"Telefonda biri “Arkadaşım sizde kalıyor, hangi odada?” diye sorar; görevli oda numarası vermez, “Dilerseniz adınızı alayım, mesajınızı kendisine ileteyim” der.","sektor":"Ön büro konuğun kimliğini, telefonunu, oda numarasını ve harcamalarını bilir; bunları korumak hem yasal sorumluluk hem meslek ahlakıdır. Konuk bilgisi yetkisiz kişiyle paylaşılmaz, ekranda ya da banko üstünde açık bırakılmaz.","iliskili":["os-3-152","os-3-160","os-3-123"],"kontrol":null,"cizim":"etik-terazi"},{"id":"os-3-155","konu":"3.2.4","terim":"VIP bildirim formu","ingilizce":"VIP notification form","tanim":"Çok önemli sayılan bir konuğun gelişini, hazırlık yapmaları için ilgili bütün bölümlere önceden bildiren belgedir.","ornek":"Perşembe günü formda şu yazar: “Cuma 16.00, 501 numaralı oda; odaya meyve tabağı ve çiçek, kapıda ön büro müdürü karşılayacak.”","sektor":"VIP, “very important person” sözünün kısaltmasıdır. Form yönetime, kat hizmetlerine, mutfağa ve güvenliğe gider; amaç konuk kapıdan girmeden bütün hazırlığın bitmiş olmasıdır. Kimin geleceği bilgisi otel dışında konuşulmaz. Ders kitabındaki formda dört alan öne çıkar: konuğun adı ve VIP derecesi, geliş ve ayrılış tarihleri, hazırlanacak ikramlar (meyve tabağı, çiçek, içecek) ve karşılama protokolü (genel müdürün ya da ön büro müdürünün karşılaması).","iliskili":["os-3-132","os-3-163","os-3-168"],"kontrol":null,"cizim":"belge-form"},{"id":"os-3-405","konu":"3.2.4","terim":"VIP derecesi (VIP 1-2-3)","ingilizce":"VIP level (VIP 1, 2, 3)","tanim":"Çok önemli konuğun önem derecesini gösteren ve hazırlığın kapsamını yönlendiren, bildirim formundaki üç dereceli (1, 2, 3) işaretlemedir.","ornek":"Perşembe 15.00, ön büro: formu hazırlayan görevli konuk için ilgili dereceyi işaretler; kat hizmetleri ve mutfak ikramı ile oda düzenini bu dereceye göre hazırlar.","sektor":"Ders kitabındaki formda üç kutu bulunur; hangi derecenin neyi kapsadığı (ikram, kimin karşılayacağı) kitapta tanımlanmaz ve işletmeden işletmeye değişir. İşe başlayınca işletmenin kendi derece listesi öğrenilir. Yanlış derece, önemli konuğa eksik karşılama ya da gereksiz masraf demektir.","iliskili":["os-3-155","os-3-132","os-3-126"],"kontrol":null},{"id":"os-3-156","konu":"3.2.4","terim":"Folyo","ingilizce":"Guest folio","tanim":"Konuğun girişinden ayrılışına kadar yaptığı bütün harcamaların ve ödemelerin tarih sırasıyla kaydedildiği hesaptır.","ornek":"202 numaralı odanın hesabı: iki gecelik oda ücreti, bir akşam yemeği, bir minibar kullanımı; çıkışta kredi kartıyla ödeme yapılınca bakiye sıfırlanır.","sektor":"Kitap onu konuğun otel içindeki “geçici cüzdanı” diye anlatır; otel yazılımı her konuk için kendiliğinden açar. Çıkışta verilen fatura bu kayda dayanır. Acentelerin ya da grupların hesabının tutulduğu türüne master folyo denir.","iliskili":["os-3-159","os-3-157","os-3-158"],"kontrol":null,"cizim":"belge-form"},{"id":"os-3-157","konu":"3.2.4","terim":"Ödeme fişi","ingilizce":"Paid-out voucher","tanim":"Resepsiyon kasasından nakit çıkışı yapıldığını gösteren belgedir.","ornek":"Saat 21.00: 108 numaralı odanın konuğu adına çiçekçiye kasadan ödeme yapılır; görevli fişi doldurur, imzalatır ve tutarı konuğun hesabına borç yazar.","sektor":"Sektörde “paid-out” diye anılır. İki durumda düzenlenir: konuk adına dışarıya yapılan küçük ödemeler (taksi, eczane, çiçek) ve otelin küçük, acil nakit ihtiyaçları. Fişi olmayan her nakit çıkışı gün sonunda kasa açığı olarak görünür.","iliskili":["os-3-156","os-3-118","os-3-158"],"kontrol":null,"cizim":"belge-form"},{"id":"os-3-158","konu":"3.2.4","terim":"Düzeltme fişi","ingilizce":"Correction voucher","tanim":"Konuk hesabına yanlışlıkla işlenen tutarı düzeltmek ya da konuğa indirim tanımlamak için kullanılan belgedir.","ornek":"Sabah 10.30: bir spa harcamasının 402 numaralı odanın hesabına iki kez girildiği fark edilir; görevli fazla yazılan tutar için düzeltme fişi düzenler, amiri de onaylar.","sektor":"Yanlış kayıt sistemden silinmez; eksi tutarlı bir fişle hesap dengelenir, böylece kimin neyi neden düzelttiği görünür kalır. Konuk memnuniyetsizliği nedeniyle yapılan indirime “allowance” denir; işlemi yapan personelin yanında yetkilinin de onayı bulunur.","iliskili":["os-3-156","os-3-157","os-3-159"],"kontrol":null,"cizim":"belge-form"},{"id":"os-3-159","konu":"3.2.4","terim":"Fatura","ingilizce":"Invoice","tanim":"Konuğun aldığı hizmetlerin bedelini, vergileri ve ödeme ayrıntılarını gösteren, mali ve yasal değeri olan belgedir.","ornek":"Çıkışta görevli “Faturayı şirket adına mı düzenleyelim efendim? Vergi dairesi ve vergi numaranızı alabilir miyim?” diye sorar.","sektor":"Folyonun resmiyete dökülmüş hâlidir ve ayrılış evresinde düzenlenir. Bugün kâğıt faturanın yerini büyük ölçüde e-fatura ve e-arşiv fatura almıştır; bu hem hız hem kâğıt tasarrufu sağlar. Hatasız ve açık bir fatura konukla otel arasındaki güvenin temelidir.","iliskili":["os-3-156","os-3-103","os-3-118"],"kontrol":null,"cizim":"belge-form"},{"id":"os-3-406","konu":"3.2.4","terim":"KDV ve konaklama vergisi","ingilizce":"VAT and accommodation tax","tanim":"Faturada oda, yiyecek ve içecek gibi hizmet bedellerine eklenen katma değer vergisi ile konaklamaya ayrıca uygulanan vergi kalemidir.","ornek":"Çıkışta konuk faturaya bakar: oda ve restoran harcaması satırlarının yanında bir KDV sütunu, altında da ayrı bir konaklama vergisi satırı vardır; görevli bu kalemleri konuğa açıklar.","sektor":"Ders kitabı faturayı tanımlarken vergileri (KDV, konaklama vergisi) açıkça sayar; kitaptaki örnek faturada KDV yüzde 10, konaklama vergisi yüzde 2 görünür. Oranlar ve uygulama mevzuata göre değişebilir, bu yüzden gerçek faturada güncel mevzuat esas alınır. Vergi kalemlerini açıklayabilen görevli çıkışta tartışmayı baştan önler.","iliskili":["os-3-159","os-3-156","os-3-103"],"kontrol":null,"cizim":"para-butce"},{"id":"os-3-160","konu":"3.2.4","terim":"Konuk tarihçe kartı","ingilizce":"Guest history card","tanim":"Konuğun geçmiş konaklamalarına ait bilgilerin, tercihlerinin, harcama alışkanlıklarının ve varsa şikâyetlerinin tutulduğu kayıttır.","ornek":"Konuk ikinci kez gelir; görevli kayıtta “üst kat, asansöre uzak, sessiz oda” notunu görür ve konuğa sormadan öyle bir oda ayırır.","sektor":"Konuğa tercihleriyle hatırlandığını hissettirmek sadakat doğurur. Bu kayıt konuğun özel bilgisidir; korunması KVKK gereği yasal sorumluluktur ve yalnız daha iyi hizmet vermek için kullanılır.","iliskili":["os-3-132","os-3-154","os-3-161"],"kontrol":null,"gorsel":"h3a-konuk-tarihce-karti"},{"id":"os-3-161","konu":"3.2.4","terim":"Anket (geri bildirim formu)","ingilizce":"Guest feedback form","tanim":"Konukların konaklama deneyimini değerlendirdiği ve işletmeye hizmetini iyileştirmesi için bilgi sağlayan formdur.","ornek":"Çıkışta görevli “Aldığınız hizmeti bizim için değerlendirir misiniz?” diyerek formu uzatır; konuk resepsiyon, oda temizliği ve yemek için ayrı ayrı puan verir.","sektor":"Kitap bu formu otelin “memnuniyet karnesi” diye anlatır: konuğun beklentisi ile sunulan hizmet arasındaki farkı gösterir. Kötü puan saklanmaz; düzeltilecek olan puan değil, hizmettir. Ders kitabındaki örnek formda resepsiyon, oda temizliği, personel nezaketi, yiyecek içecek kalitesi ve genel atmosfer gibi alanlar 1’den (çok zayıf) 5’e (çok iyi) puanlanır; sonda konuğa oteli yeniden tercih edip etmeyeceği sorulur.","iliskili":["os-3-132","os-3-160","os-3-103"],"kontrol":null,"cizim":"belge-form"},{"id":"os-3-416","konu":"3.2.4","terim":"Rezervasyon garantisi","ingilizce":"Reservation guarantee","tanim":"Konuk gelmezse otelin gelir kaybetmemesi için rezervasyonun kredi kartı ya da şirket garantisi gibi bir yöntemle güvenceye alınmasıdır.","ornek":"Saat 10.20, telefon: rezervasyon memuru konuğun kredi kartı bilgisini alır ve rezervasyonu “garantili” olarak kaydeder.","sektor":"Ders kitabı rezervasyon formundaki ödeme bilgileri bölümünde garanti yöntemi olarak kredi kartı ve şirket garantisini sayar; fiyat kodu da aynı bölümde yazılır. Garantinin kapsamı ve gelmeyen konuktan ne tahsil edileceği işletmenin kuralına göredir.","iliskili":["os-3-426","os-3-150","os-3-404"],"kontrol":null,"cizim":"sozlesme"},{"id":"os-3-418","konu":"3.2.4","terim":"Master folyo","ingilizce":"Master folio","tanim":"Tek bir konuğun değil, acente ya da grup gibi birden çok kişinin ortak harcamalarının tutulduğu folyo türüdür.","ornek":"Saat 18.00, resepsiyon: otuz kişilik tur grubunun ortak konaklama ücreti rehber adına açılan tek bir folyoya işlenir.","sektor":"Konuk folyosu tek kişinin hesabını tutarken master folyo acentenin ya da grubun ortak hesabını tutar. Grup hesabındaki bir hata onlarca kişiyi etkiler; bu yüzden kayıtlar dikkatle kontrol edilir.","iliskili":["os-3-156","os-3-144","os-3-159"],"kontrol":null,"cizim":"resepsiyon"},{"id":"os-3-162","konu":"3.2.5","terim":"Ön büroda bilgi akışı","ingilizce":"Interdepartmental communication","tanim":"Ön büronun, konuktan ya da bir bölümden aldığı bilgiyi ilgili bölüme zamanında iletmesi ve sonucunu izlemesidir.","ornek":"Saat 20.15: konuk odasına girer, klima çalışmıyordur ve resepsiyonu arar; görevli teknik servise haber verir, bir süre sonra konuğu arayıp sorunun çözülüp çözülmediğini sorar.","sektor":"Kitap ön büroyu bütün bölümleri birbirine bağlayan “sinir merkezi” diye tanımlar. Bilgiyi iletmek işin yarısıdır; öteki yarısı sonucunu izlemektir. Konuğun konforu tek bir bölümün değil, bölümlerin uyumunun eseridir.","iliskili":["os-3-163","os-3-164","os-3-110"],"kontrol":null,"gorsel":"h3a-on-buroda-bilgi-akisi"},{"id":"os-3-163","konu":"3.2.5","terim":"Ön büronun kat hizmetleriyle iş birliği","ingilizce":"Front office and housekeeping cooperation","tanim":"Odaların temiz ya da kirli olduğu bilgisinin, VIP hazırlıklarının ve odalarda görülen arızaların iki bölüm arasında karşılıklı bildirilmesidir.","ornek":"Saat 12.30: resepsiyon, erken gelen konuk için kat hizmetlerini arar; kat şefi “310 on beş dakikaya hazır” der ve oda hazır olunca haber verir.","sektor":"Amaç konuğun bekletilmeden temiz bir odaya yerleşmesidir. Ön büro odayı satar, kat hizmetleri hazırlar; ikisi haberleşmezse ya konuk lobide bekler ya da hazır olmayan odaya gönderilir.","iliskili":["os-3-162","os-3-143","os-3-155"],"kontrol":null},{"id":"os-3-164","konu":"3.2.5","terim":"Ön büronun teknik servisle iş birliği","ingilizce":"Front office and maintenance cooperation","tanim":"Odalardaki klima, televizyon, su gibi arızaların ve genel bakım ihtiyaçlarının ön büro tarafından teknik servise bildirilip sonucunun izlenmesidir.","ornek":"Saat 09.00: çıkış yapan konuk “Duşun suyu ılık akıyordu” der; görevli arızayı teknik servise bildirir ve onarım bitene kadar odaya yeni konuk yerleştirilmez.","sektor":"İki nedeni vardır: satışa hazır oda sayısını korumak ve konuğun konforunu sağlamak. Bildirilmeyen arıza bir sonraki konuğa kalır; arızalı oda ise satılamayan odadır.","iliskili":["os-3-162","os-3-163","os-3-130"],"kontrol":null,"cizim":"resepsiyon"},{"id":"os-3-165","konu":"3.2.5","terim":"Ön büronun yiyecek içecek bölümüyle iş birliği","ingilizce":"Front office and food and beverage cooperation","tanim":"Oda servisi harcamalarının, kahvaltı ve yemek sayılarının ve VIP ikram isteklerinin iki bölüm arasında bildirilmesidir.","ornek":"Akşam 18.00: ön büro, yarın sabah otelde kaç kişinin kahvaltı edeceğini restorana bildirir; mutfak hazırlığını bu sayıya göre yapar.","sektor":"Yiyecek içecek bölümü sektörde F&B (food and beverage) diye anılır. Restoran ya da oda servisi harcaması konuğun hesabına işlenmezse otel para kaybeder; yanlış odaya işlenirse başka bir konuk haksız yere borçlanır.","iliskili":["os-3-156","os-3-155","os-3-162"],"kontrol":null,"cizim":"is-birligi"},{"id":"os-3-166","konu":"3.2.5","terim":"Ön büronun muhasebeyle iş birliği","ingilizce":"Front office and accounting cooperation","tanim":"Gün sonu raporlarının, fatura ayrıntılarının, kredi limitlerinin ve kasa işlemlerinin ön büro ile muhasebe arasında paylaşılmasıdır.","ornek":"Sabah 08.00: gece hazırlanan gün sonu raporu ve kasa kayıtları muhasebeye teslim edilir; muhasebe rakamları kendi kayıtlarıyla karşılaştırır.","sektor":"Amaç tesisin mali kayıtlarının hatasız tutulması ve nakit akışının denetlenmesidir. Ön büro parayı tahsil eder, muhasebe kayıtların doğruluğunu izler; iki bölümün rakamı birbirini tutmalıdır.","iliskili":["os-3-129","os-3-159","os-3-118"],"kontrol":null,"cizim":"resepsiyon"},{"id":"os-3-167","konu":"3.2.5","terim":"Ön büronun satış ve pazarlamayla iş birliği","ingilizce":"Front office and sales and marketing cooperation","tanim":"Grup rezervasyonlarının, kampanya ayrıntılarının ve acente anlaşmalarının satış ve pazarlama bölümü ile ön büro arasında paylaşılmasıdır.","ornek":"Pazartesi sabahı satış bölümü yeni kampanyayı ön büroya yazıyla bildirir; hafta içinde arayan konuğa rezervasyon memuru aynı fiyatı ve aynı koşulları söyler.","sektor":"Amaç doluluğu artırmak ve konuğa doğru fiyat ile doğru bilgiyi vermektir. İnternette görülen kampanyadan bankodaki görevlinin haberi yoksa konuk kime inanacağını bilemez.","iliskili":["os-3-127","os-3-115","os-3-162"],"kontrol":null},{"id":"os-3-168","konu":"3.2.5","terim":"Ön büronun güvenlikle iş birliği","ingilizce":"Front office and security cooperation","tanim":"VIP konuk girişlerinin, kayıp eşyaların ve acil durum uygulamalarının ön büro ile güvenlik bölümü arasında birlikte yürütülmesidir.","ornek":"Saat 17.00: lobideki koltukta sahipsiz bir çanta bulunur; resepsiyon görevlisi çantayı karıştırmaz, güvenliğe ve amirine haber verir, olay kayda geçer.","sektor":"Amaç konukların huzurlu ve güvenli bir ortamda kalmasıdır. Şüpheli ya da tehlikeli bir durumda görevli kendi başına müdahale etmez: güvenliğe ve amirine bildirir; her zaman önce can güvenliği gelir.","iliskili":["os-3-119","os-3-142","os-3-155"],"kontrol":null,"cizim":"is-birligi"},{"id":"os-3-169","konu":"3.2.6","terim":"Oda tipleri","ingilizce":"Room types","tanim":"Odaların yatak sayısına, büyüklüğüne ve sunduğu konfor düzeyine göre ayrıldığı gruplardır.","ornek":"Rezervasyon memuru telefonda sorar: “Tek büyük yataklı mı, iki ayrı yataklı mı istersiniz?” Cevaba göre double ya da twin oda ayırır.","sektor":"Oda tipini bilmeyen görevli oda satamaz. Sektörde oda tipleri İngilizce adlarıyla kullanılır; yanlış tip ayrılırsa hata, konuk odanın kapısını açtığında ortaya çıkar.","iliskili":["os-3-170","os-3-171","os-3-172"],"kontrol":null,"gorsel":"h3a-oda-tipleri"},{"id":"os-3-170","konu":"3.2.6","terim":"Single room (tek kişilik oda)","ingilizce":"Single room","tanim":"Bir kişinin konaklaması için düzenlenmiş, tek yataklı odadır.","ornek":"Ankara’da bir şehir oteli: iki günlük toplantı için gelen satış temsilcisi tek başınadır ve single oda ayırtmıştır.","sektor":"İş için tek başına seyahat eden konukların çok olduğu şehir otellerinde sık istenir. Görevli rezervasyon alırken önce kişi sayısını sorar; oda tipi ondan sonra belli olur.","iliskili":["os-3-169","os-3-171"],"kontrol":null,"gorsel":"os-single-room"},{"id":"os-3-171","konu":"3.2.6","terim":"Double room (çift kişilik oda)","ingilizce":"Double room","tanim":"İki kişinin konaklaması için düzenlenmiş, içinde bir büyük yatak bulunan odadır.","ornek":"Balayı için gelen çift rezervasyonda özellikle “tek büyük yatak” ister; görevli double oda ayırır.","sektor":"İki kişinin birlikte yattığı büyük yatağa sektörde “French bed” denir. Double ile twin en çok karıştırılan iki oda tipidir: ikisi de iki kişiliktir, fark yatak düzenindedir.","iliskili":["os-3-172","os-3-170","os-3-169"],"kontrol":null,"gorsel":"os-double-room"},{"id":"os-3-172","konu":"3.2.6","terim":"Twin room (iki yataklı oda)","ingilizce":"Twin room","tanim":"İçinde tek kişilik iki ayrı yatak bulunan, iki kişilik odadır.","ornek":"Bir fuara birlikte gelen iki iş arkadaşı aynı odada kalacaktır; rezervasyon memuru “İki ayrı yatak, yani twin oda ayırıyorum” diye doğrular.","sektor":"Arkadaşlar, kardeşler ya da iş arkadaşları çoğu zaman ayrı yatak ister. Rezervasyonda yatak düzenini sormamak girişte oda değiştirmek zorunda kalmak demektir; dolu günde bu her zaman mümkün olmaz.","iliskili":["os-3-171","os-3-173","os-3-169"],"kontrol":null,"gorsel":"t12l-iki-yatakli-oda"},{"id":"os-3-173","konu":"3.2.6","terim":"Triple room (üç kişilik oda)","ingilizce":"Triple room","tanim":"Üç kişinin kalabileceği biçimde, üç ayrı yatakla ya da bir büyük ve bir tek kişilik yatakla düzenlenen odadır.","ornek":"Anne, baba ve on yaşındaki çocuk: anne baba için büyük yatak, çocuk için ayrı bir tek kişilik yatak bulunan triple oda verilir.","sektor":"Bazı tesislerde üçüncü kişi için çift kişilik odaya portatif bir ek yatak açılır. Görevli yatak isteğini rezervasyonda sorar; ek yatağın hazırlanması kat hizmetlerine önceden bildirilir.","iliskili":["os-3-174","os-3-172","os-3-163"],"kontrol":null,"gorsel":"os-triple"},{"id":"os-3-174","konu":"3.2.6","terim":"Quadruple room (dört kişilik oda)","ingilizce":"Quadruple room","tanim":"İçinde dört kişi için ayrı yatak bulunan ya da iki portatif ek yatak açılabilen odadır.","ornek":"Yarıyıl tatili, Uludağ: iki çocuklu aile tek odada kalmak ister; rezervasyon memuru oteldeki az sayıdaki dört kişilik odadan birini ayırır.","sektor":"Kitapta “quadro room” diye geçer. Daha çok ailelerin geldiği yaz ve kış tatil tesislerinde, az sayıda bulunur; bu yüzden erken dolar ve rezervasyonda önceden ayrılması gerekir.","iliskili":["os-3-173","os-3-175","os-3-169"],"kontrol":null,"gorsel":"h3a-quadruple-room"},{"id":"os-3-175","konu":"3.2.6","terim":"Bağlantılı oda (connecting room)","ingilizce":"Connecting rooms","tanim":"Aralarında içeriden açılabilen bir kapı bulunan, birbirine bağlı iki ayrı odadır.","ornek":"İki çocuklu aile: anne baba bir odada, çocuklar yandaki odada kalır; ara kapı açık durur, kimse koridora çıkmadan öteki odaya geçer.","sektor":"Kitapta “connection room” diye yazılır; sektörde yaygın adı “connecting room”dur. Kalabalık aileler için uygundur. Odalar ayrı konuklara verildiğinde ara kapı kilitli tutulur; bunun kontrolü konuğun mahremiyeti ve güvenliği için şarttır.","iliskili":["os-3-174","os-3-177","os-3-169"],"kontrol":null,"cizim":"oda"},{"id":"os-3-176","konu":"3.2.6","terim":"Engelli odası","ingilizce":"Accessible room","tanim":"Tekerlekli sandalye kullanan ya da hareket kısıtı olan konukların rahatça kullanabilmesi için geniş kapı ve özel banyo gibi teknik standartlarla hazırlanmış odadır.","ornek":"Tekerlekli sandalye kullanan konuk rezervasyonda bunu belirtir; görevli asansöre yakın, kapısı geniş ve banyosu uygun olan odayı onun adına ayırır.","sektor":"Kitapta “disabled room” adıyla geçer; günümüzde “accessible room” (erişilebilir oda) denmesi daha yaygındır. Bu oda bir ayrıcalık değil, haktır; ihtiyacı olan konuğa öncelikle ayrılır ve özel ihtiyaç rezervasyonda mutlaka not edilir.","iliskili":["os-3-169","os-3-150"],"kontrol":null,"gorsel":"t13e-erisilebilir-wc"},{"id":"os-3-177","konu":"3.2.6","terim":"Suite (süit oda)","ingilizce":"Suite","tanim":"Yatak odasına ek olarak oturma alanı ya da ayrı bir salonu bulunan geniş odadır.","ornek":"İstanbul’da bir otel: uzun süre kalacak iş insanı, konuklarını odasında ağırlayabilmek için ayrı salonu olan bir süit ister.","sektor":"İngilizce yazımı “suite”tir; Türkçede süit ya da suit oda denir. Standart odadan pahalıdır ve sayıca azdır; otelin gelirinde olduğu kadar prestijinde de payı vardır.","iliskili":["os-3-178","os-3-179","os-3-182"],"kontrol":null,"gorsel":"sektor-suit"},{"id":"os-3-178","konu":"3.2.6","terim":"Junior süit","ingilizce":"Junior suite","tanim":"Lüks odaların ilk basamağı olan, yatak ve oturma bölümü genellikle tek bir geniş alanda yer alan odadır.","ornek":"Konuk standart odayı dar bulur ama süit bütçesini aşar; görevli arada kalan seçeneği, köşesinde koltuk takımı bulunan junior suite’i önerir.","sektor":"Süitten farkı, oturma bölümünün ayrı bir oda olmamasıdır. Standart oda ile süit arasında bir basamak oluşturur; görevlinin elinde konuğa sunabileceği bir ara seçenek olur.","iliskili":["os-3-177","os-3-179","os-3-183"],"kontrol":null,"gorsel":"h3a-junior-suit"},{"id":"os-3-179","konu":"3.2.6","terim":"Kral dairesi","ingilizce":"Presidential suite (royal suite)","tanim":"Tesisin en üst düzey konaklama birimi olan, içinde oturma odası, yemek alanı, toplantı salonu ve mutfak gibi ayrı bölümler bulunabilen dairedir.","ornek":"Resmî ziyaret için gelen heyetin başkanı otelin en üst katındaki dairede kalır; görüşmelerini dairenin kendi toplantı salonunda yapar.","sektor":"Lüks odalar junior suite’ten kral dairesine doğru basamak basamak büyür; fark yalnız metrekare değil, mahremiyet ve kişiye özel hizmettir. Özel karşılama, kâhya (butler) hizmeti ve özel salon kullanımı bu düzeyde sunulur.","iliskili":["os-3-177","os-3-178","os-3-155"],"kontrol":null,"gorsel":"t14zb-baskanlik-suiti"},{"id":"os-3-180","konu":"3.2.6","terim":"Deniz manzaralı oda","ingilizce":"Sea view room","tanim":"Penceresi ya da balkonu denize bakan, tatil tesislerinde en çok istenen ve en değerli sayılan odadır.","ornek":"Fethiye’de bir otel: aynı büyüklükteki iki odadan denize bakanı, arka cepheye bakandan daha yüksek fiyatla satılır.","sektor":"Standart fiyata “manzara farkı” eklenerek satılır; otel aynı büyüklükteki odadan daha çok gelir elde eder. Konuğa söz verilen manzara ile odadan görünen manzara aynı olmalıdır.","iliskili":["os-3-181","os-3-182","os-3-183"],"kontrol":null,"gorsel":"t13e-tahta-kapili-oda-deniz"},{"id":"os-3-181","konu":"3.2.6","terim":"Kara manzaralı oda","ingilizce":"Land view room","tanim":"Denize değil kara tarafına bakan, tesisin giriş düzeyindeki en uygun fiyatlı odasıdır.","ornek":"Otelin ilanındaki “… fiyatından başlayan” ifadesinde yazan rakam, çoğu zaman kara manzaralı odanın fiyatıdır.","sektor":"En düşük fiyat bu odayla gösterilir ve konuk çekmek için kullanılır; kampanyalı satışlarda ve grup rezervasyonlarında temel oda budur. Görevli bu odayı küçümseyerek değil, dürüstçe tanıtarak satar.","iliskili":["os-3-180","os-3-182","os-3-183"],"kontrol":null,"cizim":"oda"},{"id":"os-3-182","konu":"3.2.6","terim":"Köşe oda","ingilizce":"Corner room","tanim":"Binanın köşesinde yer alan, genellikle iki cepheye bakan, sessiz ve geniş odadır.","ornek":"Konuk “Sessiz bir oda olsun” der; görevli koridorun sonundaki, iki yöne penceresi olan köşe odayı önerir.","sektor":"Fiyatı standart odadan yüksek, süitten düşüktür; böylece ikisinin arasında bir seçenek oluşturur. Sessizlik isteyen ya da biraz daha geniş alan arayan konuğa önerilebilecek iyi bir seçenektir.","iliskili":["os-3-180","os-3-181","os-3-177"],"kontrol":null,"cizim":"oda"},{"id":"os-3-183","konu":"3.2.6","terim":"Upselling (üst segment satış)","ingilizce":"Upselling","tanim":"Girişte ya da rezervasyonda konuğa, ayırttığından daha üst bir oda tipinin fiyat farkıyla önerilmesidir.","ornek":"Girişte görevli: “Kara manzaralı odanız hazır efendim. Dilerseniz küçük bir farkla sizi deniz manzaralı odamıza alabilirim.”","sektor":"Konuk daha iyi bir odada kalır, otel aynı geceden daha çok gelir elde eder. Teklif dürüstçe yapılır ve ısrar edilmez; konuk “hayır” derse ayırttığı oda aynı güler yüzle verilir.","iliskili":["os-3-184","os-3-180","os-3-124"],"kontrol":null,"cizim":"para-butce"},{"id":"os-3-184","konu":"3.2.6","terim":"Upgrade (üst odaya alma)","ingilizce":"Upgrade","tanim":"Konuğun, ayırttığından daha üst bir oda tipine çoğu zaman fiyat farkı alınmadan, tesisin jesti olarak yerleştirilmesidir.","ornek":"Evlilik yıl dönümünü kutlayan çift standart oda ayırtmıştır; otelde boş bir junior suite vardır ve resepsiyon şefinin onayıyla çift o odaya alınır.","sektor":"Upselling’de konuk farkı öder, upgrade’de otel ikram eder. Karar görevlinin değil amirin yetkisindedir; otele sürekli gelen ya da bir aksaklık yaşamış konuğun gönlünü almanın yollarından biridir.","iliskili":["os-3-183","os-3-178","os-3-126"],"kontrol":null,"kitapDisi":true},{"id":"os-3-417","konu":"3.2.6","terim":"Kâhya hizmeti","ingilizce":"Butler service","tanim":"Üst düzey lüks odalarda konuğa özel bir görevlinin ayrıldığı, isteklerinin kişisel olarak karşılandığı ayrıcalıklı hizmettir.","ornek":"Akşam 18.00, kral dairesi: kâhya, konuğun istediği saatte akşam yemeğinin daire içinde hazırlanmasını ister ve ertesi sabahki toplantı kıyafetinin ütülenmesini kat hizmetlerine iletir.","sektor":"Ders kitabına göre kâhya hizmeti, özel karşılama ve VIP lounge erişimiyle birlikte odanın lüks düzeyini belirleyen ayrıcalıklı hizmetlerdendir. Odanın lüks düzeyi yalnız metrekareye değil, bu hizmetlerin yoğunluğuna ve hitap ettiği konuk kitlesine (iş insanı, devlet yetkilisi, balayı çifti) de bağlıdır.","iliskili":["os-3-179","os-3-178","os-3-177"],"kontrol":null,"cizim":"zil-hizmet"},{"id":"os-3-200","konu":"3.3","terim":"Kat hizmetlerinin görevleri","ingilizce":"Duties of housekeeping","tanim":"Konuk odalarını ve ortak alanları temiz, düzenli ve hijyenik tutmak, konuğun sağlığını korumak ve otelin eşyasını, zeminini, tekstilini uzun ömürlü kılmak biçiminde özetlenen sorumlulukların bütünüdür.","ornek":"Sabah 08.00: bir görevli 3. katta çıkış yapmış odayı hazırlarken bir başkası lobinin camlarını siler, çamaşırhanede de dünün çarşafları yıkanır; üçü de aynı departmanın işidir.","sektor":"Konuk ilk anda lobiyi fark eder, ama otele yeniden gelip gelmeyeceğine çoğu zaman odanın temizliği karar verdirir. Bu departman yalnız temizlik yapmaz; otelin varlıklarını korur, su ve enerji tasarrufuyla sürdürülebilirliğe de katkı sağlar. Ders kitabına göre Yeşil Anahtar (çevreye duyarlı işletilen konaklama tesislerine verilen uluslararası çevre ödülü) ve sürdürülebilir turizm gibi küresel standartlar, atık yönetiminden su tasarrufuna kadar pek çok alanda kat hizmetlerini sektörde öncü konuma getirmiştir.","iliskili":["os-3-205","os-3-206","os-3-207"],"kontrol":null,"cizim":"kat-hizmeti"},{"id":"os-3-201","konu":"3.3.1","terim":"Kat hizmetleri organizasyon şeması","ingilizce":"Housekeeping organisation chart","tanim":"Kat hizmetlerinde hangi unvanların bulunduğunu, kimin kime bağlı olduğunu ve yetkinin kimde olduğunu gösteren çizelgedir.","ornek":"İşe yeni başlayan stajyere ilk gün şema gösterilir: “Sen oda görevlisinin yanında çalışacaksın; o kat şefine, kat şefi de kat hizmetleri müdürüne bağlı.”","sektor":"Her otelin şeması farklıdır; yapıyı otelin boyutu, türü, bulunduğu yer ve ağırladığı konuk profili belirler. Otel büyüdükçe kadro genişler ve arada yeni yönetim basamakları ile birimler oluşur. Kime bağlı olduğunu bilen personel sorunu kime bildireceğini de bilir.","iliskili":["os-3-202","os-3-203","os-3-204"],"kontrol":null,"cizim":"kat-hizmeti"},{"id":"os-3-202","konu":"3.3.1","terim":"Küçük ölçekli tesiste kat hizmetleri","ingilizce":"Housekeeping in a small hotel","tanim":"Genellikle bir kat şefi ile ona bağlı birkaç kat görevlisinden oluşan, herkesin birden çok işi üstlendiği yalın yapıdır.","ornek":"Ayvalık’ta bir butik otel: kat şefi sabah odaları dağıtır, öğlene doğru kendisi de bir oda hazırlar; çarşaflar anlaşmalı bir çamaşırhaneye gönderilir.","sektor":"Ders kitabı bu yapıya üç yıldızlı ve butik otelleri örnek verir. Çamaşırhane hizmeti çoğu zaman dışarıdan alınır; az kişiyle çalışıldığı için çok yönlü personel değerlidir.","iliskili":["os-3-201","os-3-203","os-3-214"],"kontrol":null},{"id":"os-3-203","konu":"3.3.1","terim":"Orta ölçekli tesiste kat hizmetleri","ingilizce":"Housekeeping in a mid-sized hotel","tanim":"İşlerin birbirinden ayrılmaya başladığı; kat hizmetleri müdürü, kat şefleri, kat görevlileri ve meydancıların bulunduğu yapıdır.","ornek":"Bir tatil otelinde odalar kat görevlilerine, lobi ve koridorlar meydancılara verilir; ikisini de şefler denetler, hepsi müdüre bağlıdır.","sektor":"Ders kitabı örnek olarak dört yıldızlı otelleri ve tatil otellerini verir. Odalar ile genel alanların ayrı ekiplere verilmesi uzmanlaşmanın ilk adımıdır; müdür her odayı kendisi denetleyemez, bu işi şefleri eliyle yürütür.","iliskili":["os-3-202","os-3-204","os-3-211"],"kontrol":null},{"id":"os-3-204","konu":"3.3.1","terim":"Büyük ölçekli tesiste kat hizmetleri","ingilizce":"Housekeeping in a large hotel","tanim":"Müdür, müdür yardımcısı ve ofis sorumlusundan çamaşırhane şefine, terziye ve çiçekçiye kadar her işin o işte uzmanlaşmış ayrı personele verildiği geniş yapıdır.","ornek":"Antalya’da bir tatil köyünde sabah toplantısına kat şefleri, meydan şefi ve çamaşırhane şefi ayrı ayrı katılır; her biri kendi ekibinin gününü planlar.","sektor":"Ders kitabı örnek olarak beş yıldızlı otelleri ve tatil köylerini verir. Uzmanlaşma kaliteyi yükseltir, ama ekipler arasında güçlü bir koordinasyon ister; yoksa bilgi kademeler arasında kaybolur.","iliskili":["os-3-203","os-3-212","os-3-220"],"kontrol":null},{"id":"os-3-421","konu":"3.3.1","terim":"Kat hizmetleri sekreteri (ofis sorumlusu)","ingilizce":"Housekeeping secretary (office clerk)","tanim":"Büyük ölçekli tesislerde kat hizmetleri ofisinin yazışma, kayıt ve bilgi akışı gibi ofis işlerini yürüten görevlidir.","ornek":"Sabah 08.00, kat hizmetleri ofisi: sekreter katlardan gelen arıza ve kayıp eşya bildirimlerini deftere işler, arızaları teknik servise iletir.","sektor":"Bilgi akışı ve kayıt tutma ofisin işidir; yanlış ya da eksik kayıt ön büro ile kat hizmetleri arasında oda durumu tutarsızlığına yol açar.","iliskili":["os-3-204","os-3-201","os-3-422"],"kontrol":null,"cizim":"belge-form"},{"id":"os-3-422","konu":"3.3.1","terim":"Çiçekçi","ingilizce":"Florist","tanim":"Büyük ölçekli tesislerde kat hizmetleri kadrosunda yer alan, çiçek düzenlemeleriyle ilgilenen görevlidir.","ornek":"Sabah 08.30, büyük bir tatil köyünün kat hizmetleri bölümü: çiçekçi lobi ve restoran masaları için taze çiçek aranjmanları hazırlar.","sektor":"Kitap çiçekçiyi yalnız büyük ölçekli tesislerin kat hizmetleri kadrosunda sayar; küçük ve orta ölçekli tesislerde bu görev ayrı bir unvan olarak görünmez. Çiçek düzenlemeleri lobi ve ortak alanların görünümüne katkı sağlar.","iliskili":["os-3-204","os-3-421"],"kontrol":null,"cizim":"doga"},{"id":"os-3-205","konu":"3.3.2","terim":"Odalar birimi","ingilizce":"Rooms section","tanim":"Konuk odalarının temizliğinden, düzeninden ve hijyen standartlarına uygun hazırlanmasından sorumlu kat hizmetleri birimidir.","ornek":"Saat 11.00, 4. kat: oda görevlisi çıkış yapmış odanın çarşaflarını değiştirir, banyoyu temizler, bukletleri tamamlar ve odayı kat şefinin denetimine hazırlar.","sektor":"Bu birimin öne çıkan değeri mahremiyettir: oda, konuğun otel içindeki özel alanıdır. Eşyasına dokunulmadığını, çekmecesinin açılmadığını bilen konuk otele güvenir.","iliskili":["os-3-206","os-3-214","os-3-215"],"kontrol":null},{"id":"os-3-206","konu":"3.3.2","terim":"Genel alanlar birimi","ingilizce":"Public areas section","tanim":"Lobi, restoranlar, asansörler ve genel tuvaletler gibi konukların ortak kullandığı alanların temizliğini ve bakımını yapan kat hizmetleri birimidir.","ornek":"Sabah 06.30, lobi: konuklar kahvaltıya inmeden önce meydancı zemini siler, giriş kapısının camındaki parmak izlerini alır.","sektor":"Bu birimin öne çıkan değeri estetiktir. Konuk otele girerken ilk izlenimini, ayrılırken son izlenimini bu alanlardan alır; lekeli bir cam ya da bakımsız bir tuvalet, odalardaki bütün emeği gölgede bırakabilir.","iliskili":["os-3-205","os-3-217","os-3-218"],"kontrol":null,"gorsel":"t13e-mermer-lobi-koltuk"},{"id":"os-3-207","konu":"3.3.2","terim":"Çamaşırhane ve depolar birimi","ingilizce":"Laundry and stores section","tanim":"Çarşaf, havlu gibi tesis tekstilinin ve personel üniformalarının yıkanması, ütülenmesi ve korunmasıyla ilgilenen kat hizmetleri birimidir.","ornek":"Öğleden sonra 14.00, çamaşırhane: sabah toplanan çarşaflar yıkanıp ütülenmiş, katlanmış ve ertesi günün odaları için raflara dizilmiştir.","sektor":"Bu birimin öne çıkan değeri sürdürülebilirliktir: suyu ve enerjiyi verimli kullanmak hem çevreyi hem bütçeyi korur. Çamaşırhane aksarsa katlarda oda, restoranda masa hazırlanamaz.","iliskili":["os-3-220","os-3-221","os-3-224"],"kontrol":null,"cizim":"kat-hizmeti"},{"id":"os-3-208","konu":"3.3.2","terim":"Kat hizmetleri ofisi","ingilizce":"Housekeeping office","tanim":"Departmanın kayıtlarının tutulduğu ve ön büro, teknik servis gibi diğer departmanlarla bilgi akışının sağlandığı kat hizmetleri birimidir.","ornek":"Saat 10.15: oda görevlisi 208 numaralı odada musluğun damladığını bildirir; ofis arızayı kaydeder ve teknik servise iletir.","sektor":"Bu birimin öne çıkan değeri dürüstlük ve sorumluluktur: kayıt doğruysa bilgi güvenilirdir. Büyük otelde ofis işlerini kat hizmetleri sekreteri (ofis sorumlusu) yürütür. Sektörde bu birime “housekeeping office” denir; her katta bulunan küçük depo olan “kat ofisi” ile karıştırılmamalıdır.","iliskili":["os-3-205","os-3-244","os-3-264"],"kontrol":null},{"id":"os-3-209","konu":"3.3.3","terim":"Kat hizmetleri personelinin genel özellikleri","ingilizce":"Qualities of housekeeping staff","tanim":"Dış görünüş, kişisel özellikler ve bilişsel-teknik beceriler olmak üzere üç başlıkta toplanan, bu departmanda çalışan herkesten beklenen niteliklerdir.","ornek":"Kat şefi yeni stajyere bakar: üniforması ütülü, saçı toplu, konukla karşılaşınca gülümsüyor ve verilen işi zamanında bitiriyor; üç başlığın üçü de yerinde.","sektor":"Dış görünüş: kişisel hijyen ve bakım, temiz ve ütülü üniforma, işe uygun ayakkabı, dik duruş, fiziksel dayanıklılık. Kişisel özellikler: nezaket, güler yüz, sabır, empati, pratik düşünme, dürüstlük. Beceriler: ayrıntıya dikkat, temizlik kimyasallarını tanıma, iş sağlığı ve güvenliği kurallarına uyma, zamanı iyi kullanma ve kriz anlarını yönetme.","iliskili":["os-3-210","os-3-215","os-3-269"],"kontrol":null},{"id":"os-3-210","konu":"3.3.3","terim":"Dürüstlük ve sır saklama","ingilizce":"Honesty and discretion","tanim":"Konuğa ait hiçbir şeyi sahiplenmemek ve odada görülen ya da duyulan hiçbir şeyi başkasına anlatmamak biçimindeki temel meslek değeridir.","ornek":"Oda görevlisi komodinin üstünde bırakılmış bir miktar para görür; yerinden oynatmaz, odada kimin kaldığını da arkadaşlarına anlatmaz.","sektor":"Kat hizmetleri otelin en mahrem alanında, çoğu zaman konuk yokken çalışır; bu yüzden teknik beceri kadar etik de aranır. Güven bir kez sarsılırsa en temiz oda bile konuğu geri getirmez.","iliskili":["os-3-209","os-3-256","os-3-270"],"kontrol":null,"cizim":"etik-terazi"},{"id":"os-3-211","konu":"3.3.3","terim":"Kat hizmetleri müdürü","ingilizce":"Executive housekeeper","tanim":"Departmanın en yetkili yöneticisi olarak bütçeyi, personeli ve malzeme stoklarını yöneten, temizlik standartlarını belirleyip denetleyen kişidir.","ornek":"Sezon başında müdür yeni personelin eğitim programını hazırlar, deterjan ve çarşaf stokunu gözden geçirir, ön büro müdürüyle oda teslim saatlerini konuşur.","sektor":"Büyük tesiste odalar bölümü müdürüne, küçük ve orta büyüklükteki tesiste genel müdüre karşı sorumludur. Dört ana görevi vardır: planlama ve bütçeleme, personel yönetimi, standart belirleme ve denetim, diğer departmanlarla koordinasyon. Sektörde “executive housekeeper” denir.","iliskili":["os-3-212","os-3-214","os-3-201"],"kontrol":null,"cizim":"kat-hizmeti"},{"id":"os-3-212","konu":"3.3.3","terim":"Kat hizmetleri müdür yardımcısı","ingilizce":"Assistant executive housekeeper","tanim":"Müdür ile sahadaki personel arasında köprü olan; odaları ve genel alanları her gün denetleyen, çalışma çizelgelerini hazırlayan ve stokları izleyen yöneticidir.","ornek":"Sabah 09.00: müdür yardımcısı haftalık çalışma çizelgesini panoya asar, ardından katlara çıkıp iki odayı ve lobiyi denetler.","sektor":"Müdürün koyduğu standart onun eliyle sahada gerçeğe dönüşür. Temizlik malzemesi, tekstil ve buklet stokunu izleyip sipariş listesini hazırlar; odalarda görülen arızaları teknik servise bildirir ve onarımı takip eder. Çalışma çizelgesi sektörde “shift” çizelgesi diye de anılır.","iliskili":["os-3-211","os-3-214","os-3-213"],"kontrol":null,"cizim":"lider"},{"id":"os-3-213","konu":"3.3.3","terim":"Kat hizmetleri sabah toplantısı","ingilizce":"Morning briefing","tanim":"Vardiya başında şefin ekibiyle yaptığı; günün doluluk durumunun, öncelikli odaların ve özel isteklerin paylaşılıp görevlerin dağıtıldığı kısa toplantıdır.","ornek":"Sabah 08.00, kat hizmetleri ofisi: kat şefi “Bugün çıkış çok; 410’a öğlen önemli bir konuk geliyor, önce o oda hazırlanacak” der ve oda listelerini dağıtır.","sektor":"Sektörde “briefing” denir. Birkaç dakikalık bu toplantı gün boyu sorulacak pek çok soruyu baştan cevaplar; şef bu sırada ekibin kıyafetinin ve hazırlığının yerinde olup olmadığını da görür.","iliskili":["os-3-212","os-3-214","os-3-215"],"kontrol":null,"kitapDisi":true},{"id":"os-3-214","konu":"3.3.3","terim":"Kat şefi","ingilizce":"Floor supervisor","tanim":"Oda görevlilerine iş dağıtan, temizliği biten odaları yerinde denetleyen ve standarda uygun bulduğu odaya “satışa hazır” onayını veren saha yöneticisidir.","ornek":"Saat 12.30: kat şefi 305 numaralı odaya girer; yatağa, banyoya ve aynaya bakar. Her şey yerindeyse elindeki tabletten odayı “hazır” olarak işaretler.","sektor":"Onun onay vermediği oda konuğa verilmez; bu yüzden operasyonun gözü ve kulağı sayılır. Kat ofisindeki buklet, havlu ve çarşaf stokunu kontrol eder, oda görevlilerine rehberlik eder, arızayı teknik servise bildirip onarımı izler. Sektörde “housekeeping supervisor” da denir.","iliskili":["os-3-215","os-3-262","os-3-248"],"kontrol":null},{"id":"os-3-215","konu":"3.3.3","terim":"Oda görevlisi","ingilizce":"Room attendant","tanim":"Kat şefinin kendisine verdiği konuk odalarını temizleyen, düzenleyen ve hijyen standartlarına uygun biçimde hazırlayan görevlidir.","ornek":"Sabah 08.30: görevli kat arabasını havlu, çarşaf ve bukletle yükler, listesindeki ilk odanın kapısını çalar.","sektor":"Kat görevlisi de denir. Güne kat arabasını yükleyerek başlar; odada gördüğü arızayı hemen kat şefine bildirir, unutulmuş bir eşya görürse kayda geçirilmesi için hemen şefine haber verir, gün sonunda kirli tekstili çamaşırhaneye teslim eder ve kat ofisini düzenli bırakır. Ders kitabına göre bir oda görevlisi, tesisin kapasitesine ve oda tiplerine bağlı olarak günde ortalama 10-15 odayı satışa hazır hâle getirir. Ders kitabında kadın görevli için “maid”, erkek görevli için “valet” adları geçer; bugün sektörde ikisi için de “room attendant” tercih edilir.","iliskili":["os-3-214","os-3-229","os-3-273"],"kontrol":null,"cizim":"oda"},{"id":"os-3-216","konu":"3.3.3","terim":"Malzeme taşıyıcı","ingilizce":"Housekeeping porter","tanim":"Temiz ve kirli tekstili çamaşırhane ile kat ofisleri arasında taşıyan, katlara malzeme ulaştıran ve ağır işleri üstlenen görevlidir.","ornek":"Saat 07.45: malzeme taşıyıcı temiz çarşaf ve havluları servis asansörüyle katlara çıkarır; görevliler işe başladığında kat ofisleri doludur.","sektor":"Sektörde “porter” denir. Buklet, temizlik kimyasalı ve sarf malzemesini ana depodan katlara getirir; halı yıkama makinesi gibi ağır ekipmanı taşır, perdeleri indirip takar, mobilyaların yerini değiştirir; katlarda biriken çöpü ve geri dönüşüm atığını toplama merkezine götürür. O aksarsa oda görevlisi malzeme beklerken zaman kaybeder.","iliskili":["os-3-215","os-3-230","os-3-224"],"kontrol":null,"gorsel":"t13d-camasir-yuku-tasiyan"},{"id":"os-3-217","konu":"3.3.3","terim":"Meydan şefi","ingilizce":"Public area supervisor","tanim":"Lobi, restoran, toplantı salonu ve havuz gibi ortak alanların temizliğini planlayan, meydancıların işini düzenleyen ve sonucu denetleyen yöneticidir.","ornek":"Akşam 18.00: toplantı salonundaki etkinlik bitince meydan şefi iki meydancıyı salona yönlendirir, iş bitince salonu kendisi kontrol eder.","sektor":"Meydancıların vardiyasını ve eğitimini düzenler; cila makinesi ve vakum gibi ekipmanın bakımını, kimyasal stokunu takip eder; iç mekân bitkilerinin ve dekoratif unsurların bakımını da izler. Konuğun otel hakkındaki ilk ve son izlenimi onun sorumluluk alanında oluşur.","iliskili":["os-3-218","os-3-206","os-3-227"],"kontrol":null},{"id":"os-3-218","konu":"3.3.3","terim":"Meydancı","ingilizce":"Public area attendant","tanim":"Lobi, koridor, restoran, asansör ve genel tuvalet gibi ortak alanları temizleyen, zeminlerin makineyle bakımını yapan görevlidir.","ornek":"Öğlen 13.00: meydancı lobi tuvaletindeki kâğıt havlu ve sabunu tamamlar, aynaları siler, sonra asansörün metal kapılarını parlatır.","sektor":"İngilizcede “houseman” da denir. Zemin yıkama ve cila makinelerini, profesyonel vakumları kullanır; camları ve metal yüzeyleri parlatır; oda görevlilerine ağır eşya taşıma, çöp toplama ve kirli tekstili çamaşırhaneye ulaştırmada yardım eder. Lobi otelin vitrinidir; vitrini her an temiz tutan odur.","iliskili":["os-3-217","os-3-206","os-3-280"],"kontrol":null,"gorsel":"h3b-merdiven-paspas"},{"id":"os-3-219","konu":"3.3.3","terim":"Havuzcu","ingilizce":"Pool attendant","tanim":"Havuz çevresinin temizliğinden, düzeninden ve bu alandaki konuk güvenliğinden sorumlu olan görevlidir.","ornek":"Sabah 08.00, havuz başı: havuzcu şezlongları siler ve dizer, ıslak zemine uyarı levhasını koyar, gelen konuklara temiz havlu verir.","sektor":"Şezlong, sehpa ve zeminleri düzenli temizler; kirli havluları toplayıp çamaşırhaneye gönderir; can kurtarma ekipmanının erişilebilir olduğunu kontrol eder. Havuz suyunun kimyasal değerlerini teknik servis izler; havuzcu onunla ve peyzaj birimiyle eşgüdümlü çalışır. Islak zemin hem kayma hem mikrop riski taşır.","iliskili":["os-3-218","os-3-243","os-3-265"],"kontrol":null},{"id":"os-3-220","konu":"3.3.3","terim":"Çamaşırhane şefi","ingilizce":"Laundry supervisor","tanim":"Yatak takımı, havlu, restoran örtüsü ve üniforma gibi tesisteki bütün tekstilin yıkanması, bakımı ve korunmasından sorumlu teknik yöneticidir.","ornek":"Otel tam doluyken çamaşırhane şefi işleri yeniden sıralar: çarşaflar öğlene, restoran örtüleri akşam servisine yetişecek biçimde makineye girer.","sektor":"Yıkama, kurutma, ütüleme ve katlama işlerinin akışını ve personelin iş dağılımını düzenler; tekstil stokunu ve kimyasal tüketimini izler; kumaşa uygun yıkama programının seçilmesini ve leke çıkarma işini yönetir; personeli kimyasal ve makine kullanımı konusunda eğitir. İyi yönetilen çamaşırhane otelin maliyetini doğrudan düşürür.","iliskili":["os-3-221","os-3-222","os-3-207"],"kontrol":null},{"id":"os-3-221","konu":"3.3.3","terim":"Çamaşır yıkayıcı","ingilizce":"Laundry attendant (washer)","tanim":"Kirli tekstili türüne, rengine ve kir derecesine göre ayırıp endüstriyel makinelerde uygun programda yıkayan teknik personeldir.","ornek":"Yıkayıcı beyaz çarşafları, renkli üniformaları ve çok lekeli restoran örtülerini üç ayrı sepete ayırır; her biri ayrı programda yıkanır.","sektor":"Deterjan, dezenfektan ve yumuşatıcı miktarını teknik talimata göre ayarlar; yıkama sonrası çıkmayan lekeye özel işlem uygular. Yanlış ayrılan tek bir renkli parça bütün beyaz çarşafları boyayabilir; iyi yıkanmamış havlu ise konuğun sağlığını tehlikeye atar.","iliskili":["os-3-220","os-3-222","os-3-224"],"kontrol":null},{"id":"os-3-222","konu":"3.3.3","terim":"Ütücü","ingilizce":"Presser","tanim":"Yıkanan tekstili ütüleyip katlayarak ya da askıya alarak konuğa sunulacak son biçimine getiren çamaşırhane personelidir.","ornek":"Ütücü çarşafı silindir ütüden geçirirken köşesinde çıkmamış bir leke fark eder; çarşafı ayırır ve yeniden yıkanmak üzere bildirir.","sektor":"Çarşaf ve masa örtüsü gibi düz parçalar silindir ütüde, üniformalar ve konuk giysileri pres ya da el ütüsüyle ütülenir. Ütüleme aynı zamanda son kalite kontrolüdür: leke, sökük ve yırtık burada fark edilir. Ütü makinelerinin ve buhar kazanının günlük bakımı da ütücünün işidir.","iliskili":["os-3-221","os-3-223","os-3-232"],"kontrol":null,"gorsel":"t14b-utu-gomlek"},{"id":"os-3-223","konu":"3.3.3","terim":"Terzi","ingilizce":"Tailor","tanim":"Konukların, personelin ve işletmenin tekstil ürünlerini onaran, üniformaların tadilatını yapan kat hizmetleri personelidir.","ornek":"Akşam yemeğinden önce bir konuğun ceket düğmesi kopar; ceket terziye gönderilir ve yemek saatinden önce konuğa geri ulaştırılır.","sektor":"Yeni personelin üniformasını bedenine göre ayarlar; perde, masa örtüsü, nevresim ve havlu gibi demirbaşları onarır. Onarılan her parça yeniden kullanılır; bu, otel için doğrudan tasarruftur.","iliskili":["os-3-222","os-3-220","os-3-275"],"kontrol":null},{"id":"os-3-224","konu":"3.3.3","terim":"Tekstil döngüsü","ingilizce":"Linen cycle","tanim":"Kirli çarşaf ve havluların odadan toplanıp çamaşırhanede yıkanması, ütülenmesi ve temiz olarak yeniden katlara dönmesiyle tamamlanan akıştır.","ornek":"Sabah 304 numaralı odadan toplanan çarşaf gün içinde yıkanır ve ütülenir; ertesi sabah bir kat ofisinin rafında temiz olarak bekler.","sektor":"Döngünün her halkasında ayrı biri çalışır: oda görevlisi toplar, malzeme taşıyıcı taşır, yıkayıcı yıkar, ütücü ütüler. Halkalardan biri aksarsa temiz çarşaf yetişmez, oda konuğa geç teslim edilir. Kirli ve temiz tekstil hiçbir aşamada birbirine değmez.","iliskili":["os-3-216","os-3-221","os-3-232"],"kontrol":null,"gorsel":"os-tekstil-dongusu"},{"id":"os-3-225","konu":"3.3.4","terim":"Kat hizmetleri donanımları","ingilizce":"Housekeeping equipment","tanim":"Temizlik ve oda hazırlığında kullanılan elektrikli araçların, el araçlarının, temizlik kimyasallarının, konuk ürünlerinin ve tekstilin tümüdür.","ornek":"Kat ofisinin kapısı açılır: bir köşede vakum süpürge, rafta renk renk bezler, ayrı bir bölmede kimyasallar, karşı rafta bukletler ve temiz havlular durur.","sektor":"Temel ilke “doğru işe, doğru donanım, doğru yöntem”dir. Doğru kullanılan donanım işi hızlandırır, kaynak israfını önler ve iş kazası riskini azaltır; yanlış kullanılan donanım hem yüzeye hem çalışana zarar verir. Ders kitabına göre elektrikli araçlarda üç genel kural geçerlidir: kullanım kılavuzuna uygunluk; kullanım öncesi kablo, fiş ve gövde kontrolü; ergonomi. Vakum süpürge kablosundan çekilmez, fiş başlığından tutulur; toz torbası ve filtre düzenli temizlenir. Cila makinesinde önce zemin tipi kontrol edilir, ıslak zeminde uyarı levhası kullanılır.","iliskili":["os-3-226","os-3-229","os-3-233"],"kontrol":null,"gorsel":"h3b-temizlik-dolabi"},{"id":"os-3-226","konu":"3.3.4","terim":"Vakum süpürge","ingilizce":"Vacuum cleaner","tanim":"Halı ve sert zeminlerdeki tozu ve kiri hava emişiyle içine çeken elektrikli temizlik makinesidir.","ornek":"Oda görevlisi halıyı süpürdükten sonra makineyi kapatır, fişi başlığından tutarak prizden çıkarır ve kabloyu düzgünce sarar.","sektor":"Makine kablosundan çekilerek taşınmaz; fiş prizden kablodan değil, fiş başlığından tutularak çıkarılır. Toz torbası ve filtreler düzenli temizlenirse emiş gücü düşmez. Kullanmadan önce kablo, fiş ve gövde kontrol edilir.","iliskili":["os-3-225","os-3-241","os-3-242"],"kontrol":null,"gorsel":"t14b-vakum-hali"},{"id":"os-3-227","konu":"3.3.4","terim":"Cila makinesi","ingilizce":"Floor polisher","tanim":"Mermer ve granit gibi sert zeminleri temizleyip parlatan elektrikli makinedir.","ornek":"Gece 01.00, lobi boşalmıştır: meydancı uyarı levhalarını yerleştirir ve mermer zemini cila makinesiyle parlatır.","sektor":"Kullanmadan önce zeminin türü kontrol edilir; her zemin aynı işleme uygun değildir. Islak zeminde çalışılırken kaygan zemin uyarı levhası mutlaka konur. İş için konukların az olduğu saat seçilir.","iliskili":["os-3-225","os-3-218","os-3-243"],"kontrol":null},{"id":"os-3-228","konu":"3.3.4","terim":"Yeşil kat hizmetleri","ingilizce":"Green housekeeping","tanim":"Temizlikte kimyasal, su ve enerji kullanımını azaltarak çevreyi ve insan sağlığını korumayı amaçlayan çalışma yaklaşımıdır.","ornek":"Bir otel banyo derzlerini güçlü kimyasal yerine buharlı temizleyiciyle temizler; konuk isterse havlusunu ikinci gün de kullanır, gereksiz yıkama yapılmaz.","sektor":"Son yıllarda yaygınlaşan bu yaklaşım kimyasalı azaltan buharlı temizleyicilerin kullanımını teşvik eder. Atık yönetimi ve su tasarrufu gibi konular kat hizmetlerini sürdürülebilir turizmde öne çıkarır; Yeşil Anahtar gibi çevre etiketleri de otelden bu tür uygulamalar bekler.","iliskili":["os-3-225","os-3-275","os-3-238"],"kontrol":null,"cizim":"doga"},{"id":"os-3-229","konu":"3.3.4","terim":"Kat arabası","ingilizce":"Housekeeping trolley","tanim":"Oda görevlisinin gün boyu kullanacağı temizlik malzemesini, tekstili ve buklet ürünlerini odadan odaya taşıdığı, “gezici depo” işlevi gören tekerlekli araçtır.","ornek":"Sabah 08.20: görevli çarşaf ve havluları alt raflara, bukletleri ve temizlik ürünlerini üst bölmelere dizer; araba koridora eksiksiz çıkar.","sektor":"Ağır tekstil alta, hafif malzeme üste konur: dengeli yüklenen araba görevliyi yormaz ve kolay sürülür. Kimyasallar gıda maddelerinden ve konuk eşyalarından ayrı tutulur. Eksiksiz yüklenen araba, gün içinde malzeme için geri dönmeyi önler; bu da zaman demektir.","iliskili":["os-3-230","os-3-231","os-3-215"],"kontrol":null,"gorsel":"h3b-temizlik-arabasi"},{"id":"os-3-230","konu":"3.3.4","terim":"Kat ofisi","ingilizce":"Floor pantry","tanim":"Her katta bulunan; temiz tekstilin, buklet malzemelerinin ve temizlik malzemesinin saklandığı, kat arabasının hazırlandığı küçük depodur.","ornek":"Gün sonunda oda görevlisi arabasını boşaltır, kalan havluları rafa dizer, kat ofisini süpürür ve kapısını kilitler.","sektor":"Stokunu kat şefi kontrol eder, eksikleri malzeme taşıyıcı tamamlar; tertipli tutmak ise o katın oda görevlisinin işidir. Dağınık bir kat ofisinde aranan malzeme bulunmaz, sabah işe geç başlanır.","iliskili":["os-3-229","os-3-216","os-3-214"],"kontrol":null,"gorsel":"h3b-camasir-dolabi"},{"id":"os-3-231","konu":"3.3.4","terim":"Buklet malzemeleri","ingilizce":"Guest amenities","tanim":"Şampuan, sabun ve duş jeli gibi, konuğun kullanması için odaya ve banyoya konan kişisel bakım ürünleridir.","ornek":"Çıkış yapmış odanın banyosunda görevli yarım kalan şampuanı alır, seti eksiksiz ve aynı düzende yeniden yerleştirir.","sektor":"Kat arabasında taşınır, stoku kat ofisinde tutulur. Eksik buklet konuğun banyoda ilk fark ettiği özensizliktir; resepsiyonu arayıp sabun istemek zorunda kalan konuk bunu unutmaz.","iliskili":["os-3-229","os-3-230","os-3-232"],"kontrol":null,"cizim":"kat-hizmeti"},{"id":"os-3-232","konu":"3.3.4","terim":"Oda tekstili","ingilizce":"Room linen","tanim":"Çarşaf, nevresim, havlu ve bornoz gibi, konuk odasında kullanılan kumaş ürünlerin tümüdür.","ornek":"Görevli yeni konuk için yatağa temiz çarşaf serer; banyoya el havlusu, banyo havlusu ve ayak havlusunu otelin belirlediği düzende yerleştirir.","sektor":"Konuğun tenine doğrudan değen ürünlerdir; lekeli bir havlu ya da üstünde saç kalmış bir çarşaf temizliğe duyulan güveni bir anda bitirir. Yırtık ya da lekeli parça odaya konmaz, ayrılır.","iliskili":["os-3-231","os-3-224","os-3-276"],"kontrol":null,"gorsel":"t13e-tekstil-dolap"},{"id":"os-3-233","konu":"3.3.4","terim":"Mikrofiber bez","ingilizce":"Microfibre cloth","tanim":"Çok ince liflerden dokunduğu için tozu ve kiri yaymadan tutan, toz alma ve parlatmada kullanılan temizlik bezidir.","ornek":"Görevli aynayı kuru bir mikrofiber bezle parlatır; aynanın üzerinde ne tüy ne iz kalır.","sektor":"Tüy bırakmaz ve az kimyasalla iş görür. Otelde bu bezler renk kodludur: her renk ayrı bir alanda kullanılır, böylece mikrop bir yüzeyden ötekine taşınmaz.","iliskili":["os-3-234","os-3-235","os-3-278"],"kontrol":null,"gorsel":"h3b-mikrofiber-bez"},{"id":"os-3-234","konu":"3.3.4","terim":"Renk kodlama sistemi","ingilizce":"Colour-coding system","tanim":"Her alan için ayrı renkte bez ve araç kullanarak mikrobun bir alandan ötekine taşınmasını önleyen düzendir.","ornek":"Görevli klozeti kırmızı bezle, lavaboyu sarı bezle siler; çalışma masasının tozunu almak için arabasından toz almaya ayrılmış temiz bezi alır.","sektor":"Kırmızı, tuvaletin ve yüksek riskli alanların; sarı, lavabo ve banyo yüzeylerinin rengidir. Ders kitabında genel toz alma ve mobilya için mavi bez gösterilir; mavi ile yeşilin hangi alana ait olduğu otelden otele değişebildiği için işe başlarken otelin kendi renk tablosu öğrenilir. Değişmeyen kural şudur: tuvalette kullanılan bez, durulansa bile başka yüzeye değmez.","iliskili":["os-3-233","os-3-235","os-3-262"],"kontrol":null},{"id":"os-3-235","konu":"3.3.4","terim":"Temizlikte çapraz bulaşma","ingilizce":"Cross-contamination","tanim":"Bezin, eldivenin ya da elin, kirli bir yüzeydeki mikrobu temiz bir yüzeye taşımasıdır.","ornek":"Klozeti sildiği bezi durulayıp telefon ahizesini silen görevli gözle görülmeyen mikrobu konuğun yüzüne yaklaştıracağı bir eşyaya taşımış olur.","sektor":"Gözle görülmez, kokusu yoktur; ama konuğun sağlığını ve otelin adını tehlikeye atar. Yüzey temiz görünse de hijyenik olmayabilir: “görünür temizlik” ile hijyen aynı şey değildir. Renk kodlu bez ve doğru eldiven kullanımı bunun için vardır.","iliskili":["os-3-234","os-3-233","os-3-282"],"kontrol":null,"cizim":"mikrop"},{"id":"os-3-236","konu":"3.3.4","terim":"Yüzey temizleyiciler","ingilizce":"Surface cleaners","tanim":"Banyo, cam ve mobilya gibi farklı yüzey türlerinin her biri için ayrı üretilen deterjan ve dezenfektanlardır.","ornek":"Görevlinin sepetinde üç ayrı şişe durur: biri cam ve ayna, biri banyo yüzeyleri, biri mobilya içindir; her şişenin üstünde etiketi vardır.","sektor":"Her yüzeyin ürünü ayrıdır; banyo için üretilen güçlü bir ürün ahşap mobilyanın cilasını bozabilir. Deterjan kiri çıkarır, dezenfektan mikrobu azaltır; yüzey önce temizlenir, sonra dezenfekte edilir.","iliskili":["os-3-237","os-3-240","os-3-281"],"kontrol":null,"gorsel":"h3b-sprey-siseler"},{"id":"os-3-237","konu":"3.3.4","terim":"Temizlik kimyasallarında güvenlik","ingilizce":"Chemical safety","tanim":"Kimyasal temizlik ürünlerinin etiketi okunarak, eldivenle, birbirine karıştırılmadan ve kendi kabında kullanılmasına ilişkin kuralların bütünüdür.","ornek":"Görevli tanımadığı bir şişeyle karşılaşır: önce etiketini okur, eldivenini takar, emin olamadığı noktayı kat şefine sorar.","sektor":"İki ürün asla birbirine karıştırılmaz: çamaşır suyu, asitli ürünlerle (tuz ruhu, kireç çözücü) ya da amonyaklı ürünlerle birleşince zehirli gaz çıkarır. Etiketsiz şişedeki ürün kullanılmaz, ürün içecek şişesine konmaz. Kimyasalla çalışırken ortam havalandırılır; kapalı, havasız banyoda pencere ya da kapı açık tutulur. Keskin bir koku çıkarsa oradan hemen uzaklaşılır ve amire haber verilir; ürün göze ya da cilde değerse bol suyla yıkanır ve ürünün güvenlik bilgi formundaki talimata bakılır, nefes darlığı gibi bir belirti varsa 112 aranır.","iliskili":["os-3-236","os-3-238","os-3-239"],"kontrol":null,"gorsel":"lastik-eldiven"},{"id":"os-3-238","konu":"3.3.4","terim":"Dozaj","ingilizce":"Dosage (dilution)","tanim":"Temizlik ürününün, üreticinin etiketinde ya da talimatında yazan miktar ve oranda (gerekiyorsa suyla seyreltilerek) kullanılmasıdır.","ornek":"Meydancı zemin temizleyicisini kovaya göz kararı boşaltmaz; etiketteki ölçüyü okur ve ürünü ölçü kabıyla ekler.","sektor":"Fazla ürün daha iyi temizlemez: yüzeyde yapışkan kalıntı bırakır, zemini kayganlaştırır ve ürünü boşa harcar. Az ürün ise kiri çözmez. Doğru dozaj hem temizlik hem tasarruf demektir.","iliskili":["os-3-237","os-3-236","os-3-275"],"kontrol":null,"kitapDisi":true,"cizim":"kat-hizmeti"},{"id":"os-3-239","konu":"3.3.4","terim":"Güvenlik bilgi formu","ingilizce":"Safety data sheet (SDS)","tanim":"Bir kimyasal ürünün tehlikelerini, güvenli kullanımını, saklama koşullarını ve kaza anında yapılacakları anlatan, üreticinin hazırladığı belgedir.","ornek":"Çamaşırhaneye yeni bir leke çıkarıcı gelir; çamaşırhane şefi ürünün güvenlik bilgi formunu dosyaya koyar ve ekibe hangi koruyucunun takılacağını gösterir.","sektor":"Kısaca GBF, İngilizcede SDS denir. Ürün göze sıçradığında ne yapılacağı tahminle değil, bu formla bilinir. Formların nerede durduğunu bilmek ve ürün etiketindeki uyarı işaretlerini tanımak her çalışanın hem hakkı hem görevidir.","iliskili":["os-3-237","os-3-238","os-3-220"],"kontrol":null,"kitapDisi":true,"cizim":"uyari"},{"id":"os-3-240","konu":"3.3.4","terim":"Nötr temizleyici","ingilizce":"Neutral cleaner","tanim":"pH değeri nötre yakın olan, yani belirgin biçimde ne asidik ne alkali olan, bu yüzden yüzeye zarar verme riski en düşük günlük temizlik ürünüdür.","ornek":"Lobi mermerini silecek meydancı kireç çözücüye değil, nötr zemin temizleyicisine uzanır; mermer asitle temas ederse matlaşır.","sektor":"Ürünlerin asitlik derecesi pH cetveliyle gösterilir: 7 nötrdür, altı asidik, üstü alkalidir. Asidik ürün kireci, alkali ürün yağı çözer; ikisi de yanlış yüzeyde kalıcı hasar bırakabilir. Yüzeyi tanımıyorsan güçlü ürüne uzanma, amirine sor.","iliskili":["os-3-236","os-3-237","os-3-227"],"kontrol":null,"kitapDisi":true},{"id":"os-3-241","konu":"3.3.4","terim":"Ekipman kontrolü","ingilizce":"Equipment check","tanim":"Elektrikli bir cihazı çalıştırmadan önce kablosuna, fişine ve gövdesine bakarak hasar olup olmadığını denetleme adımıdır.","ornek":"Görevli vakum süpürgenin kablosunda soyulmuş bir yer görür; makineyi prize takmaz, durumu kat şefine bildirir.","sektor":"Hasarlı ekipman asla kullanılmaz ve hemen bildirilir; soyulmuş bir kablo elektrik çarpması riskidir. Her cihazın kapasitesi ve kullanım sınırı kılavuzunda yazar; makine kılavuzuna uygun kullanılır.","iliskili":["os-3-226","os-3-227","os-3-242"],"kontrol":null,"cizim":"kurallar-liste"},{"id":"os-3-242","konu":"3.3.4","terim":"Temizlikte ergonomi","ingilizce":"Ergonomics","tanim":"İşi, bedeni zorlamayacak ve yaralamayacak duruş ve hareketlerle yapma bilgisidir.","ornek":"Görevli çarşafı yatağın altına sıkıştırırken belini bükmez, dizlerini kırarak çömelir; vakum süpürgeyi kullanırken de yükü bacaklarına verir.","sektor":"Kat hizmetleri bedenle yapılan bir iştir: gün boyu eğilir, kaldırır, iter ve çeker. Yanlış duruş bugün yorgunluk, yıllar içinde bel ve sırt sorunu demektir. Doğru duruş, mesleği uzun yıllar sağlıkla yapabilmenin şartıdır.","iliskili":["os-3-241","os-3-226","os-3-276"],"kontrol":null,"cizim":"beden-dili"},{"id":"os-3-243","konu":"3.3.4","terim":"Kaygan zemin uyarı levhası","ingilizce":"Wet floor sign","tanim":"Islak ya da kaygan zemini konuklara ve çalışanlara haber veren, ayaklı sarı uyarı işaretidir.","ornek":"Meydancı koridoru silmeye başlamadan önce iki uca birer sarı levha koyar; zemin tamamen kuruyunca levhaları toplar.","sektor":"Üzerinde çoğunlukla “Dikkat! Islak Zemin / Caution! Wet Floor” yazar. Levha, su zemine değmeden önce konur; dökülen bir sıvı görüldüğünde de ilk iş levhayı koymaktır. Islak zeminde kayan bir konuk hem yaralanma hem de otel için sorumluluk demektir.","iliskili":["os-3-227","os-3-280","os-3-219"],"kontrol":null,"gorsel":"os-kaygan-zemin-levhasi"},{"id":"os-3-244","konu":"3.3.4","terim":"Matbu form","ingilizce":"Printed form","tanim":"Belirli bir işlemi her seferinde aynı düzenle kayda geçirmek için önceden hazırlanmış, boş yerleri doldurulan belgedir.","ornek":"Bir oda görevlisi aynı gün içinde minibar kontrol formunu doldurur, gördüğü arıza için de arıza bildirim formu düzenler.","sektor":"Kat hizmetlerinin beş temel formu vardır: oda durum çizelgesi, kayıp ve bulunmuş eşya formu, arıza bildirim formu, minibar kontrol formu ve kat raporu. Üç kural hepsinde geçerlidir: kayıt o anki gerçek durumu yansıtır, konuk bilgisi yetkisiz kişiyle paylaşılmaz, form tablette doldurulsa da sorumluluk değişmez.","iliskili":["os-3-245","os-3-256","os-3-262"],"kontrol":null,"cizim":"belge-form"},{"id":"os-3-245","konu":"3.3.4","terim":"Oda durum çizelgesi","ingilizce":"Room status report","tanim":"Her odanın dolu mu boş mu, temiz mi kirli mi olduğunu gösteren ve kat hizmetleri ile ön büro arasındaki bilgi akışını sağlayan belgedir.","ornek":"Saat 13.00: kat şefi çizelgede 202 numaralı odayı “boş temiz” olarak işaretler; resepsiyon, bekleyen konuğu o odaya yerleştirir.","sektor":"İki departman arasındaki en kritik belgedir. Çizelge yanlışsa ya konuk kirli odaya çıkar ya da temiz oda boş bekler. Odanın numarası, tipi, durumu, konuğun ayrılış tarihi ve özel notlar bu çizelgede yer alır.","iliskili":["os-3-246","os-3-255","os-3-264"],"kontrol":null,"cizim":"oda"},{"id":"os-3-246","konu":"3.3.4","terim":"Oda durum kodları","ingilizce":"Room status codes","tanim":"Odanın o anki durumunu uzun cümle yerine birkaç harfle anlatan, uluslararası düzeyde kullanılan kısaltmalardır.","ornek":"Kat şefi telsizle “206 VD” der; karşıdaki herkes odanın boş olduğunu ama henüz temizlenmediğini anlar.","sektor":"Başlıcaları: OCC (dolu), V (boş), VC (boş temiz), VD (boş kirli), OOO (arızalı), DND (rahatsız etmeyin), C/O (çıkış yapmış), SO (yatağı kullanılmamış), DL (çift kilit). Kodlar ekip içindir; konuğa kod söylenmez, “Odanız hazır” denir.","iliskili":["os-3-247","os-3-248","os-3-249"],"kontrol":null},{"id":"os-3-247","konu":"3.3.4","terim":"OCC","ingilizce":"Occupied","tanim":"Odada o sırada bir konuğun konakladığını, yani odanın dolu olduğunu gösteren oda durum kodudur.","ornek":"Çizelgede 201 numaralı odanın karşısında “OCC / Dirty” yazar: oda doludur ve günlük temizliği henüz yapılmamıştır.","sektor":"Dolu odada konuğun eşyası vardır; görevli kapıyı kuralına göre çalar, ortalığı düzenler, ama çekmeceyi, valizi, dolabı açmaz. Kodun yanına temizlik durumu da yazılır: “Clean” temiz, “Dirty” kirli demektir.","iliskili":["os-3-246","os-3-248","os-3-253"],"kontrol":null,"cizim":"oda"},{"id":"os-3-248","konu":"3.3.4","terim":"V ve VC kodları","ingilizce":"Vacant / Vacant clean","tanim":"Odada konaklayan kimse olmadığını (V) ve boş odanın temizlenmiş, satışa hazır olduğunu (VC) gösteren oda durum kodlarıdır.","ornek":"Ön büro ekranında 202 numaralı oda “VC” görünür; gelen konuk bekletilmeden bu odaya yerleştirilir.","sektor":"Ön büro bir odayı konuğa normalde VC olduğunda verir. Bu kod kat şefinin denetiminden sonra verilir; denetlenmeden “temiz” yazılan oda, konuğun önünde açılan kötü bir sürprize dönüşebilir.","iliskili":["os-3-249","os-3-214","os-3-247"],"kontrol":null},{"id":"os-3-249","konu":"3.3.4","terim":"VD","ingilizce":"Vacant dirty","tanim":"Konuğu ayrılmış, ama henüz temizlenmemiş boş odayı gösteren oda durum kodudur.","ornek":"Saat 12.10: 206 numaralı odanın konuğu çıkış yapar, oda çizelgede VD olur; görevli odayı hazırlayıp kat şefi onaylayınca kod VC’ye döner.","sektor":"VD’den VC’ye geçen süre otelin hızını gösterir: oda ne kadar çabuk hazırlanırsa bekleyen konuk o kadar erken yerleşir. Hız uğruna denetim atlanmaz.","iliskili":["os-3-248","os-3-252","os-3-246"],"kontrol":null,"gorsel":"h3b-dagnik-yatak"},{"id":"os-3-250","konu":"3.3.4","terim":"OOO","ingilizce":"Out of order","tanim":"Teknik bir sorun nedeniyle satışa kapatılmış, konuğa verilemeyen odayı gösteren oda durum kodudur.","ornek":"205 numaralı odanın kliması arızalıdır; çizelgede “OOO” görünür, nota “klima arızası, teknik servis” yazılır ve arıza giderilene kadar oda satılmaz.","sektor":"Satılamayan her gece otel için gelir kaybıdır; bu yüzden arıza hemen bildirilir ve onarım takip edilir. Arıza giderilince oda temizlenip denetlenir, sonra yeniden satışa açılır.","iliskili":["os-3-251","os-3-260","os-3-265"],"kontrol":null},{"id":"os-3-251","konu":"3.3.4","terim":"OOS","ingilizce":"Out of service","tanim":"Küçük bir eksik ya da kısa süren bir işlem nedeniyle geçici olarak konuğa verilmeyen, ama kısa sürede yeniden satılabilecek odayı gösteren koddur.","ornek":"Halısı yıkanan oda, halı kuruyana kadar birkaç saat OOS gösterilir; akşam olmadan yeniden satışa açılır.","sektor":"OOO ile karıştırılmamalıdır: OOO’da oda ciddi bir arıza ya da onarım nedeniyle satıştan çıkarılmıştır, OOS’ta ise yalnız kısa süreliğine bekletilir. Ayrımı her otel kendi sisteminde tanımlar; işe başlarken otelin kullandığı kodlar öğrenilir.","iliskili":["os-3-250","os-3-246","os-3-260"],"kontrol":null,"kitapDisi":true,"cizim":"oda"},{"id":"os-3-252","konu":"3.3.4","terim":"C/O kodu","ingilizce":"Check-out","tanim":"Konuğun odadan ve tesisten ayrıldığını, yani çıkış yaptığını gösteren oda durum kodudur.","ornek":"Çizelgede 203 numaralı oda “C/O / Dirty” görünür; notlar bölümünde “genel temizlik yapılacak” yazar.","sektor":"Çıkış yapılan oda günün en kapsamlı temizliğini ister: çarşaf ve havlular değişir, buklet tamamlanır, oda havalandırılır. Temizliğe başlamadan önce unutulmuş eşya olup olmadığına bakılır.","iliskili":["os-3-249","os-3-256","os-3-276"],"kontrol":null,"cizim":"resepsiyon"},{"id":"os-3-253","konu":"3.3.4","terim":"SO","ingilizce":"Sleep out","tanim":"Kayıtta dolu görünen, ama yatağı hiç kullanılmamış odayı gösteren oda durum kodudur.","ornek":"Sabah 09.30: görevli 318 numaralı odaya girer; valiz yerinde, yatak ise dün yapıldığı gibi durmaktadır. Durumu kat şefine bildirir.","sektor":"Konuğun geceyi odasında geçirmediğini düşündürür ve ön büronun bilmesi gereken bir durumdur. Oda görevlisi yorum yapmaz, tahmin yürütmez; gördüğünü bildirir, gerisini ön büro değerlendirir.","iliskili":["os-3-247","os-3-255","os-3-254"],"kontrol":null,"gorsel":"h3b-valizli-oda"},{"id":"os-3-254","konu":"3.3.4","terim":"DL","ingilizce":"Double lock","tanim":"Odanın içeriden kilitlendiğini gösteren oda durum kodudur.","ornek":"Görevlinin anahtarı 412 numaralı odanın kapısını açmaz; oda içeriden kilitlenmiştir. Görevli zorlamaz, odayı DL olarak kat şefine bildirir.","sektor":"Konuk rahatsız edilmek istemiyor olabilir; bu yüzden kapı zorlanmaz, ısrarla çalınmaz. Durum uzun sürerse ne yapılacağına oda görevlisi değil, kat şefi ve ön büro karar verir.","iliskili":["os-3-271","os-3-253","os-3-246"],"kontrol":null,"gorsel":"h3b-kapi-kilidi"},{"id":"os-3-255","konu":"3.3.4","terim":"Oda durumu tutarsızlığı","ingilizce":"Room status discrepancy","tanim":"Bir odanın kat hizmetleri kaydındaki durumu ile ön büro kaydındaki durumunun birbirini tutmamasıdır.","ornek":"Listede 210 numaralı oda boş görünür; oysa görevli odada bir valiz ve kullanılmış bir yatak bulur. Hiçbir şeye dokunmadan kat şefine haber verir.","sektor":"Hatalı ya da geç işlenen bir kayıttan doğar ve operasyonu aksatır: boş sanılan dolu odaya yeni konuk gönderilebilir. Kayıt bu yüzden tahminle değil, odada görülen gerçek duruma göre ve anında tutulur.","iliskili":["os-3-245","os-3-253","os-3-264"],"kontrol":null,"cizim":"oda"},{"id":"os-3-256","konu":"3.3.4","terim":"Kayıp ve bulunmuş eşya formu","ingilizce":"Lost and found form","tanim":"Konuğun unuttuğu eşyanın ne olduğunu, nerede, ne zaman ve kim tarafından bulunduğunu, nerede saklandığını ve kime teslim edildiğini kayda geçiren belgedir.","ornek":"Saat 14.30: 304 numaralı odada bulunan kol saati için form açılır; cinsi, rengi, bulunduğu yer, bulan personel ve saklandığı yer yazılır.","sektor":"Dört bölümü vardır: eşyanın tanımı, bulunuş bilgileri, muhafaza bilgileri ve teslim bilgileri. Eşyayı bulan görevli onu hemen kat şefine ulaştırır; ders kitabına göre eşya bulunduğu andan itibaren en geç 15 dakika içinde kayıt altına alınır ve ön büroya bilgi verilir. Bulunan eşyanın içi karıştırılmaz: cüzdanın içi kurcalanmaz, telefonun mesajlarına bakılmaz.","iliskili":["os-3-257","os-3-258","os-3-259"],"kontrol":null},{"id":"os-3-257","konu":"3.3.4","terim":"Tarafsız eşya tanımı","ingilizce":"Neutral item description","tanim":"Bulunan eşyanın forma, değeri hakkında hüküm vermeden, yalnız görünen özellikleriyle yazılması kuralıdır.","ornek":"Görevli forma “altın yüzük” yazmaz; “sarı renkli metal yüzük, üzerinde beyaz taş” yazar.","sektor":"Eşyanın gerçekten altın olup olmadığını görevli bilemez. “Altın” yazılan yüzük kaplama çıkarsa kayıt da personel de şüphe altında kalır; tarafsız tanım ikisini de korur.","iliskili":["os-3-256","os-3-258","os-3-210"],"kontrol":null},{"id":"os-3-258","konu":"3.3.4","terim":"Kayıp eşya takip defteri","ingilizce":"Lost and found log book","tanim":"Bulunan bütün eşyaların tarih sırasıyla yazıldığı; her eşyanın bulunuşundan teslimine kadar bütün aşamalarının tek yerden izlendiği kayıt defteridir.","ornek":"Haftalar sonra arayan konuğa görevli defterden bakarak cevap verir: “Güneş gözlüğünüz havuz başında bulunmuş ve kayda geçmiş, depomuzda duruyor efendim.”","sektor":"Her eşyaya bir kayıt numarası verilir; aynı numara eşyanın üstüne takılan etikete (tag) yazılır. Deftere silinmez mürekkeple yazılır, karalama yapılmaz; yanlış girişin üstü tek çizgiyle çizilip paraflanır. Defter yalnız yetkili personelin ulaşabildiği güvenli bir yerde durur. Eşyanın ne kadar saklanacağını işletmenin prosedürü belirler; bu süre genellikle 90 gündür, bazı işletmelerde daha uzundur. Ders kitabı, teslim alınmayan eşyanın tasfiye kayıtlarının işletme politikasına göre genellikle 6 ay ya da 1 yıl tutulduğunu söyler; öğretmen notunda bu süre genellikle 90 gündür. Hangisi uygulanacaksa işletmenin prosedürü geçerlidir.","iliskili":["os-3-256","os-3-259","os-3-267"],"kontrol":null},{"id":"os-3-259","konu":"3.3.4","terim":"Sahiplik doğrulaması","ingilizce":"Proof of ownership","tanim":"Bulunmuş eşyayı almak isteyen kişinin gerçekten sahibi olduğunun, eşya teslim edilmeden önce kontrol edilmesidir.","ornek":"Telefonunu almaya gelen konuktan ekran kilidini açması istenir; kilit açılınca teslim bölümü imzalanır ve telefon verilir.","sektor":"Doğrulama yolları: eşyanın ayrıntılı tarifi, fatura gösterme, telefonun ekran kilidini açma. Eşyayı önce gösterip “Bu sizin mi?” diye sormak yanlış kişiye teslime yol açabilir. Teslim, alan kişinin kimlik bilgisi kaydedilerek ve iki tarafın imzasıyla yapılır.","iliskili":["os-3-256","os-3-258","os-3-257"],"kontrol":null},{"id":"os-3-260","konu":"3.3.4","terim":"Arıza bildirim formu","ingilizce":"Maintenance work order","tanim":"Odalarda ya da genel alanlarda görülen teknik sorunu, yerini ve aciliyetini teknik servise yazılı olarak ileten belgedir.","ornek":"Forma şöyle yazılır: “402 numaralı oda, banyo bataryası su sızdırıyor, öncelik: önemli.” Teknik servis yanına doğru parçayı alarak gelir.","sektor":"Arıza fark edildiği anda bildirilir: küçük bir sızıntı bekledikçe büyür ve pahalanır. Tanım kısa ve net yazılır; “banyo bozuk” yerine “batarya sızdırıyor” denir. Formda öncelik işaretlenir: acil, önemli ya da rutin. Onarım bitince kat hizmetleri ya da ön büro arızanın giderildiğini doğrular, oda yeniden satışa hazırlanır. Form dört bölümden oluşur: arıza konumu ve kaynağı, arıza tanımı, teknik servis müdahalesi (yapılan işlem, kullanılan parça, durum: tamamlandı / parça bekleniyor / dış servis gerekli) ve onay ile teslimat (teknisyen ve bölüm sorumlusunun imzası).","iliskili":["os-3-250","os-3-265","os-3-262"],"kontrol":null,"cizim":"belge-form"},{"id":"os-3-261","konu":"3.3.4","terim":"Minibar kontrol formu","ingilizce":"Minibar consumption form","tanim":"Konuğun minibardan tükettiği ürünlerin oda oda kaydedilip ön büro kasasına bildirildiği belgedir.","ornek":"Görevli 301 numaralı odanın minibarını kontrol eder: bir su ve iki meyve suyu eksiktir. Tüketimi hemen forma yazar ve eksikleri tamamlar.","sektor":"Tüketim, odaya girildiği anda forma ya da otel sistemine işlenir; eksik ya da yanlış kayıt, çıkışta konukla yaşanan tartışmanın başlıca nedenidir. Ürünlerin son kullanma tarihi ve ambalajı her gün kontrol edilir, tarihi geçen ürün hemen değiştirilir. Kontrol sırasında konuğun eşyasına dokunulmaz, minibarın kapağı uzun süre açık bırakılmaz.","iliskili":["os-3-244","os-3-264","os-3-275"],"kontrol":null,"cizim":"icecek-bar"},{"id":"os-3-407","konu":"3.3.4","terim":"Parstock (standart stok)","ingilizce":"Par stock (standard stock level)","tanim":"Minibarda her ürün için bulunması gereken standart miktar olup kontrol sonunda ürünlerin tamamlandığı düzeydir.","ornek":"301 numaralı odada minibarın standardı iki su ve iki soda; konuk bir su içmiş. Görevli tüketilen miktarı forma yazar ve suyu tamamlayarak stoğu yeniden iki yapar.","sektor":"Ders kitabındaki minibar kontrol formunda “mevcut stok (parstock)”, “tüketilen (consumed)”, birim fiyat ve toplam tutar sütunları bulunur. Her oda kontrolden sonra standart stoğa döner; böylece sonraki konuk eksik minibarla karşılaşmaz ve tüketim hesabı kolay çıkar.","iliskili":["os-3-261","os-3-032","os-3-118"],"kontrol":null},{"id":"os-3-262","konu":"3.3.4","terim":"Kat raporu","ingilizce":"Housekeeper's report","tanim":"Kat şefinin temizlenen her odayı madde madde denetleyip onayladığı günlük kontrol listesidir.","ornek":"Kat şefi 402 numaralı odada lavaboda bir saç teli görür; raporda banyo hijyeni sütununu işaretler ve oda “gözden geçir” notuyla görevliye döner.","sektor":"Günlük kontrol listesi de denir. Sütunlarında yatak düzeni, banyo hijyeni, toz ve yüzey, buklet ve tekstil, teknik durum ve onay yer alır. Yalnız görünen temizliğe değil hijyene de bakılır: renk kodlu bez kullanımı ve dezenfeksiyon da denetlenir. Şef hatayı azarlayarak değil, usta-çırak ilişkisi içinde göstererek düzelttirir.","iliskili":["os-3-214","os-3-263","os-3-234"],"kontrol":null,"cizim":"belge-form"},{"id":"os-3-263","konu":"3.3.4","terim":"Saat yönünde denetim","ingilizce":"Clockwise inspection","tanim":"Odanın, kapı girişinden başlayıp saat yönünde dolaşılarak hiçbir nokta atlanmadan kontrol edilmesi yöntemidir.","ornek":"Kat şefi kapıdan girer; duvar boyunca hep aynı yönde ilerleyerek gardıroba, yatağa, pencereye ve çalışma masasına sırayla bakar, turu başladığı kapıda bitirir.","sektor":"Rastgele bakan göz köşeleri atlar; hep aynı yönde dolaşan göz atlamaz. Denetim sırasında gereksiz yanan lamba kapatılır, damlayan musluk hemen bildirilir.","iliskili":["os-3-262","os-3-214","os-3-275"],"kontrol":null},{"id":"os-3-264","konu":"3.3.5","terim":"Kat hizmetleri ve ön büro iş birliği","ingilizce":"Housekeeping–front office co-operation","tanim":"Oda durum raporları, önemli konuklar (VIP) ve geç çıkışlar konusunda iki departmanın sürekli bilgi alışverişi yapmasıdır.","ornek":"Resepsiyon kat hizmetlerini arar: “508 numaralı odanın konuğu saat 15.00’e kadar kalacak.” Kat şefi o odayı sona bırakır, erken gelecek konuğun odasını öne alır.","sektor":"Amaç, odanın konuğa zamanında ve kusursuz teslim edilmesidir. Ön büro odayı satar, kat hizmetleri hazırlar; biri ötekinden habersiz kalırsa konuk ya lobide bekler ya da hazır olmayan odaya çıkar.","iliskili":["os-3-245","os-3-255","os-3-265"],"kontrol":null},{"id":"os-3-265","konu":"3.3.5","terim":"Kat hizmetleri ve teknik servis iş birliği","ingilizce":"Housekeeping–maintenance co-operation","tanim":"Arıza bildirimleri, periyodik bakımlar ve tadilat çalışmaları konusunda iki departmanın birlikte çalışmasıdır.","ornek":"Oda görevlisi sabah 216 numaralı odada ampulün yanmadığını bildirir; teknik servis öğlene kadar değiştirir, konuk akşam döndüğünde hiçbir şey fark etmez.","sektor":"Kat hizmetleri odalara her gün giren departmandır; arızayı ilk gören çoğu zaman odur. Bu iş birliği hem otelin varlıklarını hem konuğun güvenliğini korur: gevşek bir priz yalnız konfor değil, güvenlik sorunudur.","iliskili":["os-3-260","os-3-250","os-3-264"],"kontrol":null,"cizim":"kat-hizmeti"},{"id":"os-3-266","konu":"3.3.5","terim":"Kat hizmetleri ve yiyecek içecek iş birliği","ingilizce":"Housekeeping–food and beverage co-operation","tanim":"Oda servisi tepsilerinin toplanması ve restoran tekstilinin temizliği konusunda iki departmanın iş birliği yapmasıdır.","ornek":"Sabah 09.00: görevli koridorda kapı önüne bırakılmış bir kahvaltı tepsisi görür ve oda servisine haber verir; tepsi kısa sürede alınır.","sektor":"Koridorda saatlerce bekleyen tepsi hem kötü görünür hem kokar. Restoranın masa örtüsü ve peçeteleri de çamaşırhanede yıkanır; örtü yetişmezse masa hazırlanamaz. Amaç hijyen standardını ve görsel estetiği korumaktır.","iliskili":["os-3-207","os-3-224","os-3-264"],"kontrol":null,"cizim":"is-birligi"},{"id":"os-3-267","konu":"3.3.5","terim":"Kat hizmetleri ve güvenlik iş birliği","ingilizce":"Housekeeping–security co-operation","tanim":"Kayıp ve bulunan eşyalar ile şüpheli durumların bildirilmesi konusunda iki departmanın birlikte çalışmasıdır.","ornek":"Görevli katta, kapıları tek tek yoklayan birini fark eder; yanına gidip sorgulamaz, hemen kat şefine haber verir, o da güvenliği arar.","sektor":"Kat görevlisi koridorlarda en çok bulunan kişidir; olağan dışı durumu ilk o görür. Görevi müdahale etmek değil, bildirmektir. Bu iş birliği konuğun da personelin de güvenliğini sağlar.","iliskili":["os-3-258","os-3-270","os-3-274"],"kontrol":null},{"id":"os-3-268","konu":"3.3.5","terim":"Kat hizmetleri ve satın alma iş birliği","ingilizce":"Housekeeping–purchasing co-operation","tanim":"Temizlik malzemesi, buklet ve tekstil ihtiyacının zamanında belirlenip satın alma departmanından istenmesidir.","ornek":"Sezon öncesi sayımda havlu stokunun azaldığı görülür; kat hizmetleri müdürü ihtiyacı satın almaya bildirir, yeni havlular sezon açılmadan gelir.","sektor":"Biten deterjan ya da eksik havlu odanın hazırlanamaması demektir. İhtiyacı doğru ve zamanında bildirmek hizmetin kesilmemesini sağlar; gereğinden fazla istemek ise parayı depoda bekletir. İki departman böylece maliyeti de kontrol eder.","iliskili":["os-3-211","os-3-231","os-3-232"],"kontrol":null},{"id":"os-3-269","konu":"3.3.6","terim":"Kat hizmetleri personelinin genel kuralları","ingilizce":"Housekeeping staff rules","tanim":"Profesyonel tutum ve disiplin, konuk mahremiyeti ve odaya giriş standartları ile iş sağlığı, güvenliği ve sürdürülebilirlik başlıklarında toplanan çalışma esaslarıdır.","ornek":"Görevli işe vaktinde ve ütülü üniformasıyla gelir, koridorda alçak sesle konuşur, odaya kuralına göre girer, çıkarken gereksiz yanan ışığı söndürür.","sektor":"Temiz ve ütülü üniforma mesleğe duyulan saygının ilk işaretidir; işe zamanında başlamak ve işi eksiksiz bitirmek hatasız hizmetin gereğidir. Güçlü kimyasallar ve yüksekte çalışma gibi riskler nedeniyle iş sağlığı ve güvenliği kuralları bu departmanda hayati önem taşır.","iliskili":["os-3-270","os-3-273","os-3-275"],"kontrol":null,"cizim":"kurallar-liste"},{"id":"os-3-270","konu":"3.3.6","terim":"Sessizlik ve gizlilik","ingilizce":"Quietness and confidentiality","tanim":"Konukların dinlendiği koridor ve odalarda gürültü yapmama; boş odalar ve konuk bilgileri hakkında yalnız yetkili birimlerle konuşma kuralıdır.","ornek":"Koridorda bir kişi görevliye “306’da kim kalıyor, oda boş mu?” diye sorar; görevli “Bu konuda resepsiyon size yardımcı olur efendim” der.","sektor":"Kimin hangi odada kaldığı, odanın boş olup olmadığı ya da konuğun ne zaman çıktığı bilgisi kötü niyetli birinin işine yarayabilir. Arabayı duvara çarpmak, koridorda seslenmek ya da yüksek sesle konuşmak ise dinlenen konuğu rahatsız eder.","iliskili":["os-3-269","os-3-210","os-3-274"],"kontrol":null,"cizim":"oda"},{"id":"os-3-271","konu":"3.3.6","terim":"Lütfen rahatsız etmeyin kartı","ingilizce":"Do Not Disturb (DND)","tanim":"Konuğun odasına girilmesini ve rahatsız edilmeyi istemediğini bildirmek için kapıya astığı karttır.","ornek":"Saat 11.00: 204 numaralı odanın kapısında kart asılıdır. Görevli kapıyı çalmaz, odayı listesinde işaretler ve kat şefine bildirir.","sektor":"Kapıdaki bu kart girişin kesinlikle yasak olduğunu ve odanın sessiz kalması gerektiğini bildirir; çoğunlukla kırmızı renkte hazırlanır. Kısaltması olan DND, oda durum kodu olarak da kullanılır. Kart uzun süre asılı kalırsa ne yapılacağına oda görevlisi kendi başına karar vermez, kat şefine haber verir. Kimi tesislerde kartın yerini kapıdaki ışıklı bir gösterge alır.","iliskili":["os-3-272","os-3-273","os-3-254"],"kontrol":null,"gorsel":"t14b-dnd-kapi-askisi"},{"id":"os-3-272","konu":"3.3.6","terim":"Lütfen odamı temizleyin kartı","ingilizce":"Make up room (MUR)","tanim":"Konuğun odasının temizlenmesini istediğini bildirmek için kapıya astığı karttır.","ornek":"Sabah 09.15: görevli koridora çıktığında 207 numaralı odanın kapısında bu kartı görür; listesindeki sırayı değiştirip önce o odaya girer.","sektor":"Genellikle yeşil renklidir ve iş sırasında önceliği belirler: konuk açıkça hizmet istemiştir, bekletilmez. Sektörde bu istek kısaca MUR diye anılır.","iliskili":["os-3-271","os-3-273","os-3-215"],"kontrol":null,"gorsel":"os-rahatsiz-etmeyin-karti"},{"id":"os-3-273","konu":"3.3.6","terim":"3x3 metodu","ingilizce":"3x3 knocking method","tanim":"Odaya girmeden önce kapıya üç kez vurup “Kat hizmetleri / Housekeeping” diye seslenmeyi ve bunu toplam üç kez yapmayı öngören giriş kuralıdır.","ornek":"Görevli 310 numaralı odanın kapısına üç kez vurur, “Housekeeping” diye seslenir ve bekler; cevap gelmeyince aynısını iki kez daha yapar, ancak ondan sonra kapıyı açar.","sektor":"Odanın boş olduğu bilinse bile her seferinde uygulanır. Konuk duşta, uykuda ya da telefonda olabilir; habersiz açılan kapı konuğun özel alanına izinsiz girmektir.","iliskili":["os-3-271","os-3-272","os-3-274"],"kontrol":null,"cizim":"kat-hizmeti"},{"id":"os-3-274","konu":"3.3.6","terim":"Pas anahtarı","ingilizce":"Master key","tanim":"Görevlinin sorumlu olduğu odaların tümünü açan, vardiya başında teslim alınıp vardiya sonunda geri verilen anahtar ya da karttır.","ornek":"Görevli sabah pas anahtarını imza karşılığı alır, gün boyu üzerinde taşır; kat arabasının üstüne bir an bile bırakmaz.","sektor":"Sektörde “master key” ya da “pass key” denir. Bu anahtar konukların eşyasına açılan kapıdır: başkasına verilmez. “Odamı açar mısınız?” diyen kişiye kapı açılmaz; kişi kibarca resepsiyona yönlendirilir, çünkü kimin hangi odada kaldığını doğrulamak ön büronun işidir. Anahtar kaybolursa hemen amire bildirilir.","iliskili":["os-3-273","os-3-270","os-3-267"],"kontrol":null,"kitapDisi":true,"cizim":"resepsiyon"},{"id":"os-3-275","konu":"3.3.6","terim":"Tasarruf ve bilinçli kullanım","ingilizce":"Saving resources","tanim":"Gereksiz yanan ışığı söndürmek, suyu boşa akıtmamak ve malzemeyi ölçülü kullanmak biçimindeki çalışma alışkanlığıdır.","ornek":"Görevli boş odadan çıkarken açık kalmış banyo ışığını kapatır, damlayan musluğu kat şefine bildirir.","sektor":"Yüzlerce odada her gün tekrarlanan küçük israflar büyük bir faturaya dönüşür. Tasarruf hem işletme ekonomisi hem de çevre için bir zorunluluktur; temizlik kalitesinden ödün vermek anlamına gelmez.","iliskili":["os-3-269","os-3-228","os-3-263"],"kontrol":null},{"id":"os-3-276","konu":"3.3.7","terim":"Yatak yapımı","ingilizce":"Bed making","tanim":"Yatağın temiz çarşaf ve nevresimle, otelin belirlediği standartta, gergin ve kırışıksız biçimde hazırlanması işidir.","ornek":"Görevli alt çarşafı yatağın ortasına hizalayarak serer, köşeleri sırayla sıkıştırır; çarşafın üstünde tek kırışık kalmaz.","sektor":"Konuğun odaya girince ilk baktığı yerlerden biri yataktır. Gereken malzeme: çarşaf, nevresim takımı, yastık kılıfları ve yatağı koruyan alez. Üstünde saç, leke ya da yırtık olan çarşaf kullanılmaz. Çalışırken bel bükülmez, dizler kırılır.","iliskili":["os-3-277","os-3-232","os-3-242"],"kontrol":null,"gorsel":"sektor-yatak-yapimi"},{"id":"os-3-277","konu":"3.3.7","terim":"Zarf köşe tekniği","ingilizce":"Hospital corner (envelope corner)","tanim":"Alt çarşafın köşesini üçgen biçiminde katlayıp yatağın altına sıkıştırarak zarf kapağına benzeyen düzgün ve gergin bir köşe elde etme yöntemidir.","ornek":"Görevli çarşafın yan kenarını yatağın altına sıkıştırır, kalan köşeyi yukarı kaldırıp üçgen yapar, alt kenarı sıkıştırır, üçgeni indirir ve onu da yatağın altına iter.","sektor":"Altı adımdır: çarşafı yay, yanını sıkıştır, köşeyi kaldırıp üçgen yap, alt kenarı sıkıştır, üçgeni indir, zarfı sıkıştır. Bu köşe çarşafı gece boyunca yerinde tutar; düzgün bir köşe konuğa odanın özenle hazırlandığını söyler.","iliskili":["os-3-276","os-3-232","os-3-242"],"kontrol":null},{"id":"os-3-278","konu":"3.3.7","terim":"Cam yüzey temizliği","ingilizce":"Glass cleaning","tanim":"Camın; hazırlık, solüsyonu püskürtüp bezle ovma, çekçekle sıyırma ve kenarları kuru bezle tamamlama adımlarıyla iz bırakmadan temizlenmesidir.","ornek":"Meydancı lobi camına solüsyonu püskürtür, mikrofiber bezle ovar, çekçeği “S” çizerek tek seferde indirir; kenarda kalan damlaları kuru bezle alır.","sektor":"Gereken malzeme: eldiven, mikrofiber bez, cam temizleme ürünü ve profesyonel çekçek. Cam hatayı saklamaz: tek parmak izi ışıkta hemen görünür. Köşeler ve çerçeve en sona, kuru ve temiz bir beze kalır.","iliskili":["os-3-279","os-3-233","os-3-281"],"kontrol":null,"gorsel":"h3b-cam-silici"},{"id":"os-3-279","konu":"3.3.7","terim":"S yöntemi","ingilizce":"S-pattern","tanim":"Bezin, mopun ya da çekçeğin yüzey üzerinde “S” harfi çizer gibi, hiçbir boşluk bırakmadan gezdirilmesi tekniğidir.","ornek":"Görevli çalışma masasını silerken bezi bir uçtan ötekine “S” çizerek ilerletir; silinmemiş şerit kalmaz.","sektor":"Camda çekçek, zeminde mop, mobilyada bez aynı hareketle kullanılır. Rastgele silmek bazı yerleri atlar, kiri de temizlenmiş yere geri taşır; S yönteminde hiçbir nokta atlanmaz.","iliskili":["os-3-278","os-3-280","os-3-281"],"kontrol":null,"gorsel":"t13d-duz-mop-zemin"},{"id":"os-3-280","konu":"3.3.7","terim":"Zemin temizliği","ingilizce":"Floor cleaning","tanim":"Zeminin; alanı güvenliğe alma, kuru temizlik, ıslak temizlik ve kuruma ile son kontrol adımlarıyla temizlenmesidir.","ornek":"Meydancı koridora “Dikkat! Islak Zemin” levhasını koyar, önce kuru mopla tozu toplar, sonra deterjanlı suyla “S” çizerek paspaslar ve zemin kuruyunca levhayı kaldırır.","sektor":"Sıra bozulmaz. Kuru temizlik atlanırsa toz ıslak mopun altında çamura döner, kum da zemini çizer. Levha konmadan su zemine değmez; zemin kurumadan da levha kalkmaz.","iliskili":["os-3-243","os-3-279","os-3-283"],"kontrol":null,"gorsel":"t14b-paspas-zemin"},{"id":"os-3-281","konu":"3.3.7","terim":"Yüzey temizliği işlem sırası","ingilizce":"Surface cleaning procedure","tanim":"Yüzeye uygun ürünü ve doğru renkte bezi seçme, ürünü püskürtme, “S” yöntemiyle ovma, kuru bezle kurulayıp parlatma ve köşeleri kontrol etme adımlarının düzenli sırasıdır.","ornek":"Görevli komodin için mobilya ürününü ve toz bezini seçer, ürünü püskürtür, yüzeyi “S” çizerek siler, kuru bezle parlatır ve kenarlara son kez bakar.","sektor":"İşe iş kıyafeti ve eldivenle başlanır; iş bitince kullanılan malzeme temizlenip yerine kaldırılır. Sıradaki ilk adım en önemlisidir: yanlış ürün yüzeye, yanlış bez konuğun sağlığına zarar verir.","iliskili":["os-3-279","os-3-234","os-3-236"],"kontrol":null,"gorsel":"sektor-temizlik-malzemeleri"},{"id":"os-3-282","konu":"3.3.7","terim":"Sık temas edilen yüzeyler","ingilizce":"High-touch surfaces","tanim":"Konukların ve çalışanların gün içinde elleriyle en çok dokunduğu, bu yüzden mikrobun en kolay taşındığı yüzeylerdir.","ornek":"Görevli odada kapı kolunu, ışık anahtarını, telefon ahizesini ve televizyon kumandasını ayrıca siler ve dezenfekte eder.","sektor":"Genel alanda asansör düğmesi, kapı kolu ve tırabzan da bu gruptadır. Temiz göründükleri için kolayca atlanırlar; oysa her elin değdiği bu noktalar göründüğünden çok daha fazla mikrop taşır. Bu yüzeyler önce temizlenir, sonra dezenfekte edilir.","iliskili":["os-3-235","os-3-236","os-3-281"],"kontrol":null,"kitapDisi":true,"gorsel":"os-sik-temas-yuzey"},{"id":"os-3-283","konu":"3.3.7","terim":"Çıkışa doğru çalışma","ingilizce":"Working towards the exit","tanim":"Zemin temizliğine kapıya en uzak noktadan başlanıp çıkışa doğru ilerlenmesi kuralıdır.","ornek":"Görevli banyo zeminini en dipteki köşeden başlayarak siler ve geri geri kapıya doğru gelir; çıkarken temiz zemine basmaz.","sektor":"Tersini yapan, çıkmak için sildiği ıslak zemine basar: hem ayak izi bırakır hem kayma riskine girer. Odada da aynı mantık geçerlidir: zemin, odadan çıkmadan hemen öncesine bırakılır.","iliskili":["os-3-280","os-3-279","os-3-243"],"kontrol":null,"kitapDisi":true},{"id":"os-3-285","konu":"3.3.7","terim":"Üstten alta, temizden kirliye çalışma","ingilizce":"Top to bottom, clean to dirty","tanim":"Odada yüksek yüzeylerden zemine doğru, aynı zamanda daha temiz alanlardan daha kirli alanlara doğru ilerlemeyi öngören çalışma sırasıdır.","ornek":"Görevli önce rafların ve çalışma masasının tozunu alır, zemini en sona bırakır; banyoda kullandığı bezle masaya geri dönmez.","sektor":"Toz yukarıdan aşağı düşer: önce yüksek yüzeyi siler, sonra zemini temizleyen görevli aynı yeri iki kez yapmaz. Banyo ve tuvalet en kirli alan sayıldığı için oradaki bez ve eldiven odanın temiz bölümlerine dönmez. Ayrıntılı sıra işletmeden işletmeye küçük farklar gösterebilir; otelin kendi standardı işe başlarken öğrenilir.","iliskili":["os-3-283","os-3-235","os-3-234"],"kontrol":null,"kitapDisi":true,"cizim":"kat-hizmeti"},{"id":"os-3-284","konu":"3.3.7","terim":"Gece hazırlığı","ingilizce":"Turndown service","tanim":"Konuk akşam yemeğinde ya da dışarıdayken odasının gece uykusuna hazırlanması hizmetidir.","ornek":"Akşam 19.30: görevli yatak örtüsünü kaldırır, yorganın bir köşesini açar, perdeleri kapatır, başucu lambasını yakar ve kullanılmış havluları yeniler.","sektor":"Sektörde İngilizcesiyle “turndown service” denir; akşam vardiyasının işidir ve daha çok üst sınıf otellerde sunulur. Odasına dönen konuk, biri onu düşünmüş gibi hisseder; iyi otelle sıradan oteli ayıran bu tür ayrıntılardır.","iliskili":["os-3-276","os-3-232","os-3-215"],"kontrol":null,"kitapDisi":true,"gorsel":"h3b-yatakta-havlu-susu"},{"id":"os-3-423","konu":"3.3.7","terim":"Çekçek","ingilizce":"Squeegee","tanim":"Cam gibi düz yüzeylerdeki suyu ve temizlik solüsyonunu sıyırarak yüzeyi iz bırakmadan kurutan el aracıdır.","ornek":"Meydancı lobi camına solüsyon sıktıktan sonra çekçeği camın üstünden “S” çizerek tek seferde indirir.","sektor":"Cam temizliğinde mikrofiber bezle birlikte kullanılan temel araçtır; tek seferde ve S çizerek çekmek iz kalmasını önler.","iliskili":["os-3-278","os-3-279","os-3-424"],"kontrol":null,"cizim":"kat-hizmeti"},{"id":"os-3-424","konu":"3.3.7","terim":"Mop","ingilizce":"Mop","tanim":"Zemin temizliğinde kullanılan, saplı ve lifli uçlu, kuru ya da ıslak kullanılabilen temizlik aracıdır.","ornek":"Meydancı koridorda önce mikrofiber kuru mopla tozu toplar, sonra ıslak mopla deterjanlı suyla zemini siler.","sektor":"Kuru mop tozu toplar, ıslak mop deterjanlı suyla zemini siler. Kitap kuru temizlik için mikrofiber kuru mopu, ıslak temizlik için paslanmaz çelik saplı mopu sayar; uyarı levhası konmadan ıslak mopa başlanmaz.","iliskili":["os-3-280","os-3-279","os-3-423"],"kontrol":null,"cizim":"kat-hizmeti"},{"id":"os-3-425","konu":"3.3.7","terim":"Alez","ingilizce":"Mattress protector","tanim":"Yatağı sıvıdan, lekeden ve tozdan koruyan, çarşafın altına serilen koruyucu örtüdür.","ornek":"Oda görevlisi yatağı hazırlarken önce alezi serer, üstüne alt çarşafı gerer.","sektor":"Oda görevlisi yatak yaparken alezi çarşafın altına serer; sıvı ve leke yatağa geçmediği için hijyen korunur ve yatak daha uzun süre kullanılır. Ders kitabı alezi yatak yapımının gerekli malzemeleri arasında sayar.","iliskili":["os-3-276","os-3-277"],"kontrol":null,"cizim":"kat-hizmeti"},{"id":"os-3-300","konu":"3.4","terim":"Etkinlik hizmetlerinin görevleri","ingilizce":"Duties of the entertainment department","tanim":"Konukların tatilini gündüz aktiviteleri, spor, çocuk kulübü ve gece gösterileriyle zenginleştirmek için bu departmanın üstlendiği işlerin bütünüdür.","ornek":"Sabah 10.30’da havuz başında su jimnastiği, 15.00’te çocuk kulübünde boyama atölyesi, 21.30’da amfi tiyatroda dans gösterisi: üçünü de aynı departman planlar ve sunar.","sektor":"Yeni ders kitabında bölümün adı etkinlik hizmetleridir; sektörde çoğu yerde hâlâ “animasyon” denir. İyi yürütülen etkinlikler doluluğu artırır ve konuğu otele bağlar: konuk tatilden döndüğünde çoğu zaman odasını değil, katıldığı etkinlikleri anlatır. Ders kitabı aynı departmandan yer yer “eğlence hizmetleri” diye de söz eder (eğlence müdürü, eğlence hizmetleri departmanı).","iliskili":["os-3-301","os-3-303","os-3-304"],"kontrol":null},{"id":"os-3-301","konu":"3.4","terim":"Animasyon","ingilizce":"Animation (entertainment)","tanim":"Otelde konukların hoş vakit geçirmesi için düzenlenen oyun, spor, gösteri ve eğlence etkinliklerine sektörde verilen addır.","ornek":"Bodrum’da bir tatil köyünde konuk resepsiyona “Bu akşam animasyon saat kaçta?” diye sorar; görevli günlük aktivite çizelgesini gösterir.","sektor":"Sözcüğün anlamı “canlandırma”dır; Latince “anima” (can, ruh) kökünden gelir. Ders kitabı bölümü “etkinlik hizmetleri” diye adlandırır, ama unvanlarda eski ad yaşar: animasyon şefi, animatör. İş ilanlarında ve otelde iki adı da duyarsın.","iliskili":["os-3-300","os-3-326","os-3-325"],"kontrol":null,"cizim":"festival"},{"id":"os-3-303","konu":"3.4","terim":"Gönüllü katılım","ingilizce":"Voluntary participation","tanim":"Konuğun bir etkinliğe hiçbir zorlama olmadan, kendi isteğiyle katılması ilkesidir.","ornek":"Saat 11.00, havuz başı: animatör şezlongda kitap okuyan konuğu su topu maçına davet eder; konuk “Teşekkürler, ben izleyeyim.” deyince gülümseyip “Keyifli okumalar.” diyerek ayrılır.","sektor":"Israrla oyuna çekilen konuk eğlenmez, rahatsız olur. Davet edilir, zorlanmaz: “hayır” diyen konuğa saygı da hizmetin parçasıdır.","iliskili":["os-3-300","os-3-327","os-3-323"],"kontrol":null,"kitapDisi":true,"cizim":"festival"},{"id":"os-3-304","konu":"3.4.1","terim":"Etkinlik hizmetleri organizasyon şeması","ingilizce":"Organisation chart of the entertainment department","tanim":"Departmanda kimin hangi görevde olduğunu ve kimin kime bağlı çalıştığını gösteren çizimdir.","ornek":"Sezonun ilk günü, personel odası: yeni başlayan animatör duvardaki şemaya bakar; kendi adının animasyon şefinin altında, şefin adının da müdürün altında yazdığını görür.","sektor":"Şema işletmenin büyüklüğüne ve türüne (şehir oteli, tatil köyü) göre değişir, ama mantık aynıdır: herkes sorununu kime ileteceğini ve kimden talimat alacağını bilir. Şemada yalnız adlar değil, yetki ve sorumluluk sırası da görünür.","iliskili":["os-3-305","os-3-306","os-3-307"],"kontrol":null,"cizim":"ekip"},{"id":"os-3-305","konu":"3.4.1","terim":"Küçük ölçekli işletmede etkinlik hizmetleri","ingilizce":"Entertainment services in a small property","tanim":"Butik otel gibi küçük tesislerde, az sayıda ve birden çok işi yapabilen personelle yürütülen, sorumluluğu işletme müdüründe olan etkinlik düzenidir.","ornek":"Alaçatı’da bir butik otel cumartesi akşamı için dışarıdan bir müzik grubuyla anlaşır; sandalyeleri resepsiyon görevlisi ile garson birlikte dizer.","sektor":"Ayrı bir etkinlik departmanı yoktur; etkinlik gerektiğinde hizmet çoğunlukla dışarıdan, dönemlik olarak alınır. Küçük tesiste “Bu benim işim değil.” denmez: çok yönlü personel her işe el atar.","iliskili":["os-3-304","os-3-306","os-3-307"],"kontrol":null},{"id":"os-3-306","konu":"3.4.1","terim":"Orta ölçekli işletmede etkinlik hizmetleri","ingilizce":"Entertainment services in a medium-sized property","tanim":"Tatil oteli gibi orta büyüklükteki tesislerde, bir animasyon şefi ile ona bağlı küçük bir çekirdek ekibin bağımsız birim olarak çalıştığı etkinlik düzenidir.","ornek":"Side’de bir tatil otelinde ekip her sabah 09.30’da şefin çevresinde toplanır: biri sporu, biri çocuk kulübünü, biri de akşamın müziğini üstlenir.","sektor":"Belirli bir hiyerarşi oluşmuştur. Çekirdek ekipte spor, çocuk ve müzik (DJ) işlerine bakan birkaç kişi bulunur (ders kitabına göre bir animasyon şefi ve 3-5 kişilik çekirdek ekip); herkes birden çok etkinlikte görev alır.","iliskili":["os-3-304","os-3-305","os-3-325"],"kontrol":null},{"id":"os-3-307","konu":"3.4.1","terim":"Büyük ölçekli işletmede etkinlik hizmetleri","ingilizce":"Entertainment services in a large resort","tanim":"Tatil köyü gibi büyük tesislerde, her alanın kendi uzmanının ve yöneticisinin bulunduğu çok katmanlı etkinlik düzenidir.","ornek":"Belek’te büyük bir tatil köyünde akşam gösterisine dansçılar, ses ve ışık ekibi, kostüm sorumlusu ve sahne yöneticisi aynı anda hazırlanır; hepsinin işi ayrıdır.","sektor":"En üstte etkinlik hizmetleri müdürü, altında branş şefleri (spor, çocuk kulübü gibi alanların şefleri), teknik ekip ve kalabalık bir animatör kadrosu yer alır. Ekip büyüdükçe uzmanlaşma artar, görev tanımı netleşir.","iliskili":["os-3-304","os-3-306","os-3-324"],"kontrol":null},{"id":"os-3-408","konu":"3.4.1","terim":"Branş şefi","ingilizce":"Section head (activity branch supervisor)","tanim":"Büyük işletmelerde spor, çocuk kulübü, sahne gibi bir etkinlik alanının (branşın) sorumluluğunu taşıyan şeftir.","ornek":"Büyük bir tatil köyünde sabah 09.00, spor şefi gün programını spor animatörlerine dağıtır; çocuk kulübü şefi de kendi ekibini toplar.","sektor":"Ders kitabına göre büyük ölçekli işletmede etkinlik hizmetleri müdürünün altında branş şefleri, teknik ekip ve kalabalık bir animatör kadrosu bulunur. Müdür işi branşlara böler, her alanın uzmanı kendi ekibini yönetir. Küçük işletmede bu kademe yoktur; aynı kişi birkaç işi birden yapar.","iliskili":["os-3-307","os-3-324","os-3-325"],"kontrol":null,"cizim":"lider"},{"id":"os-3-309","konu":"3.4.2","terim":"Çocuk kulübü (mini club)","ingilizce":"Kids' club (mini club)","tanim":"Animatör gözetiminde eğitici ve eğlenceli etkinliklere çocuk konukların katıldığı, etkinlik hizmetlerine bağlı birimdir.","ornek":"Saat 10.00, çocuk kulübü: anne, kayıt formunu imzalayarak kızını bırakır; içeride yüz boyama başlamak üzeredir.","sektor":"Genellikle 12 yaşına kadar olan çocuklara hizmet verir; ders kitabında 4-12 yaş grubu diye geçer, alt sınır tesise göre değişir. Bu birimde sabır, çocuk sevgisi, empati ve yaratıcılık aranır. Çocuklu aileler otel seçerken çocuk kulübüne özellikle bakar; çocuğu mutlu olan aile rahat tatil yapar.","iliskili":["os-3-329","os-3-330","os-3-345"],"kontrol":null,"gorsel":"h3b-cocuk-kulubu-odasi"},{"id":"os-3-311","konu":"3.4.2","terim":"Gençlik kulübü","ingilizce":"Teenage club","tanim":"Çocuk kulübüne büyük, yetişkin etkinliklerine küçük gelen genç konuklar için ayrı etkinliklerin yürütüldüğü kulüptür.","ornek":"Saat 16.00, Kemer’de bir tatil köyü: animatör plaj voleybolu turnuvası için takımları kurar; lobide telefonuna bakan iki genç de davet edilince takıma katılır.","sektor":"Genellikle 11-18 yaş arasındaki konuklara yöneliktir; sınır tesise göre değişir (ders kitabındaki etkinlikte gençlik grubu 13-17 yaş olarak verilir). Sektörde “teenage club” denir. Gençler hareketli, rekabetli ve arkadaşlarıyla yapabilecekleri etkinlikleri sever; sıkılan genç ailenin tatilini de zorlaştırır.","iliskili":["os-3-309","os-3-312","os-3-303"],"kontrol":null,"kitapDisi":true,"gorsel":"h3b-genclik-oyun-salonu"},{"id":"os-3-312","konu":"3.4.2","terim":"Spor ve rekreasyon birimi","ingilizce":"Sports and recreation unit","tanim":"Konukların fiziksel sağlığını destekleyen turnuvaları, su jimnastiğini ve spor etkinliklerini düzenleyen birimdir.","ornek":"Sabah 10.30, havuz: spor animatörü müziği açar, su jimnastiği başlar; öğleden sonra aynı ekip plajda voleybol turnuvası yönetir.","sektor":"Rekreasyon, boş zamanı dinlendirici ve yenileyici etkinliklerle değerlendirmek demektir. Bu birimde dinamik yapı, spor yeterliliği ve iş sağlığı ve güvenliği (İSG) bilinci aranır: sakatlanan konuk için tatil o an biter.","iliskili":["os-3-328","os-3-344","os-3-311"],"kontrol":null,"gorsel":"t14zb-otel-spor-salonu"},{"id":"os-3-315","konu":"3.4.2","terim":"Sahne ve gece animasyonu birimi","ingilizce":"Stage and evening entertainment unit","tanim":"Dans gösterisi, skeç, pandomim ve seyircinin de katıldığı yarışmalar gibi sahne performanslarını sunan birimdir.","ornek":"Saat 21.30, amfi tiyatro: ışıklar kararır, dans ekibi sahneye çıkar; gösterinin sonunda seyirciler arasından gönüllü olanlarla bir yarışma yapılır.","sektor":"Skeç kısa, güldürücü sahne oyunudur; pandomim ise sözsüz, yalnız beden hareketi ve mimikle anlatımdır, bu yüzden farklı dilleri konuşan konukların hepsine ulaşır. Bu birimde sahne disiplini, estetik bakış, yabancı dil ve özgüven aranır.","iliskili":["os-3-332","os-3-335","os-3-318"],"kontrol":null,"cizim":"ekip"},{"id":"os-3-318","konu":"3.4.2","terim":"Teknik birim (ses / ışık / DJ)","ingilizce":"Technical unit (sound, lighting, DJ)","tanim":"Bütün etkinliklerin ses, müzik ve ışık sistemlerini kuran ve etkinlik boyunca yöneten birimdir.","ornek":"Saat 19.00, amfi tiyatro: gösteriye iki buçuk saat var; teknik ekip hoparlörleri dener, mikrofonların pilini değiştirir, ışıkları tek tek yakıp söndürür.","sektor":"DJ, etkinliğin havasına göre müziği seçip çalan kişidir. Bu birimde teknik donanım bilgisi, hızlı sorun çözme ve dikkat aranır: gösterinin ortasında susan mikrofon, günlerce çalışılmış bir emeği gölgede bırakır.","iliskili":["os-3-331","os-3-337","os-3-340"],"kontrol":null,"gorsel":"os-teknik-birim"},{"id":"os-3-319","konu":"3.4.2","terim":"Tanıtım birimi","ingilizce":"Promotion unit","tanim":"Etkinlikleri konuklara duyuran ve konukların memnuniyetiyle ilgili geri bildirimleri toplayan birimdir.","ornek":"Öğle 12.30, restoran girişi: tanıtım görevlisi konuklara “Bu akşam 21.30’da Türk gecemiz var, sizi de bekleriz.” diyerek günün programını hatırlatır.","sektor":"En iyi hazırlanmış etkinlik bile duyurulmazsa boş salona oynar: haberi olmayan konuk gelmez. Bu birimde güler yüz, etkili iletişim, ikna yeteneği ve nezaket aranır.","iliskili":["os-3-348","os-3-351","os-3-315"],"kontrol":null,"cizim":"megafon"},{"id":"os-3-320","konu":"3.4.3","terim":"Etkinlik personelinin dış görünüşü","ingilizce":"Appearance of entertainment staff","tanim":"Kişisel hijyen ve bakım, temiz ve ütülü üniforma, işe uygun ayakkabı, zinde görünüm ve fiziksel dayanıklılıktan oluşan, etkinlik personelinden beklenen özelliklerdir.","ornek":"Sabah 09.15, personel soyunma odası: animatör temiz tişörtünü giyer, spor ayakkabısının bağcığını sıkar, yaka kartını takar; gün boyu güneş altında ayakta olacaktır.","sektor":"Etkinlik personeli otelin vitrinidir: konukla en uzun süre ve en yakından temas eden ekiptir. Konuk yalnız ne yaptığına değil, nasıl göründüğüne de bakar.","iliskili":["os-3-321","os-3-322","os-3-326"],"kontrol":null,"cizim":"uniforma"},{"id":"os-3-321","konu":"3.4.3","terim":"Etkinlik personelinin kişisel özellikleri","ingilizce":"Personal qualities of entertainment staff","tanim":"Nazik, güler yüzlü, sabırlı, empati sahibi, dışa dönük ve sosyal olma, ekip çalışmasına yatkınlık, dürüstlük ve sır saklayabilme gibi, etkinlik personelinde aranan karakter özellikleridir.","ornek":"Saat 17.00, dart turnuvası: finali kaybeden konuk sinirlenir; animatör sakin kalır, “Çok iyi oynadınız, yarın rövanşı bekliyoruz.” diyerek onu gülümsetir.","sektor":"Animatör konukla çok vakit geçirir ve onun hakkında çok şey öğrenir; duyduğunu başkasına taşımaması güvenin temelidir. Enerji bir gün düşebilir, nezaket düşmez.","iliskili":["os-3-320","os-3-322","os-3-323"],"kontrol":null,"cizim":"ekip"},{"id":"os-3-322","konu":"3.4.3","terim":"Etkinlik personelinin bilişsel ve teknik becerileri","ingilizce":"Cognitive and technical skills of entertainment staff","tanim":"Ayrıntıya dikkat, en az bir yabancı dilde iletişim, hızlı karar verme, güçlü hafıza ve beklenmedik durumda yaratıcı çözüm üretme gibi, etkinlik personelinde aranan becerilerdir.","ornek":"Akşam 21.40: gösterinin ortasında müzik kesilir; sunucu animatör hemen seyirciyle alkışlı bir oyun başlatır, teknik ekip sorunu çözene kadar sahne boş kalmaz.","sektor":"Sahne metnini de konuğun adını da hatırlamak hafıza ister; adıyla çağrılan konuk kendini özel hisseder. Yabancı dil bilmeyen animatör, konukların bir bölümünü oyunun dışında bırakır.","iliskili":["os-3-320","os-3-321","os-3-326"],"kontrol":null,"cizim":"ekip"},{"id":"os-3-323","konu":"3.4.3","terim":"Samimiyet sınırı","ingilizce":"Professional boundary","tanim":"Etkinlik personelinin konuğa gösterdiği sıcaklığın, konuk ile personel arasındaki ilişkinin ve nezaketin dışına taşmaması ilkesidir.","ornek":"Bir konuk animatörden telefon numarasını ister ve akşam dışarıda buluşmayı önerir; animatör nazikçe teşekkür eder, otelin kuralı gereği kabul edemeyeceğini söyler.","sektor":"Animatör işi gereği konuğa en yakın personeldir; bu yüzden sınırı en iyi bilen de o olmalıdır. Samimiyet nezaket içinde kalırsa güven verir, laubaliliğe dönerse şikâyete yol açar.","iliskili":["os-3-321","os-3-326","os-3-303"],"kontrol":null,"kitapDisi":true,"cizim":"pasaport"},{"id":"os-3-324","konu":"3.4.3","terim":"Etkinlik hizmetleri müdürü","ingilizce":"Entertainment manager","tanim":"Konuk deneyimini tasarlayan ve departmanın bütün işleyişini yöneten en üst düzey etkinlik yöneticisidir.","ornek":"Mart ayı, Antalya: sezon açılmadan müdür yaz programını hazırlar, alınacak ekipmanın bütçesini çıkarır ve yeni animatörlerle iş görüşmesi yapar.","sektor":"Beş ana görevi vardır: işletmenin konseptine ve konuk profiline uygun yıllık programı hazırlamak, bütçeyi yönetmek, ekibi seçip eğitmek, diğer departmanlarla eşgüdümü sağlamak ve konuk geri bildirimleriyle kaliteyi denetlemek. Bazı tesislerde “animasyon müdürü” ya da “eğlence müdürü” denir.","iliskili":["os-3-325","os-3-307","os-3-353"],"kontrol":null},{"id":"os-3-325","konu":"3.4.3","terim":"Animasyon şefi","ingilizce":"Chief animator","tanim":"Etkinlik hizmetleri müdürüne bağlı çalışan, planlanan etkinliklerin sahada eksiksiz uygulanmasından sorumlu olan ekip lideridir.","ornek":"Sabah 09.30 toplantısı: şef günlük programı okur, “Su topu sende, dart sende, akşam sunumu bende.” diyerek görevleri dağıtır.","sektor":"Günlük programın akışını ve zamanlamasını yönetir, animatörlere görev dağıtır, sahada konukların şikâyet ve önerilerini dinler, etkinlik alanlarının İSG kurallarına uygunluğunu denetler ve günü müdüre raporlar. Sahada sorun çıkınca animatörün ilk haber vereceği kişi şefidir.","iliskili":["os-3-324","os-3-326","os-3-348"],"kontrol":null,"cizim":"festival"},{"id":"os-3-326","konu":"3.4.3","terim":"Animatör","ingilizce":"Animator (entertainer)","tanim":"Konukları oyun, spor, yarışma ve gösterilerle eğlendiren, etkinlikleri hazırlayıp sunan etkinlik hizmetleri görevlisidir.","ornek":"Saat 11.00, havuz başı: animatör mikrofonu alır, “Günaydın! On dakika sonra su topu başlıyor, takımlara iki kişi daha arıyoruz.” diye duyuru yapar.","sektor":"Oyun, spor ve çocuk kulübü animatörü gibi uzmanlık alanlarına ayrılır. Konuğun gün boyu en sık gördüğü yüzlerden biridir; konuk çoğu zaman oteli animatörün adıyla hatırlar.","iliskili":["os-3-327","os-3-328","os-3-329"],"kontrol":null,"cizim":"festival"},{"id":"os-3-327","konu":"3.4.3","terim":"Oyun animatörü","ingilizce":"Games animator","tanim":"Havuz başında, plajda ve açık alanlarda gündüz oyunlarını planlayıp yöneten görevlidir.","ornek":"Saat 15.00, havuz kenarı: oyun animatörü dart tahtasını asar, kuralları iki dilde anlatır, puanları tahtaya yazar.","sektor":"Dart, su topu, voleybol ve masa tenisi gibi oyunları yönetir; konukları nezaketle davet eder, kuralları açıklar ve katılanları kaynaştırır. Oyun alanını ve malzemeyi hazırlar, İSG kurallarını uygular; konuklarla yakın olduğu için akşam gösterisinin duyurusunu da o yapar.","iliskili":["os-3-326","os-3-328","os-3-303"],"kontrol":null},{"id":"os-3-328","konu":"3.4.3","terim":"Spor animatörü","ingilizce":"Sports animator","tanim":"Sabah jimnastiği, su aerobiği, plaj voleybolu ve turnuvalar gibi spor etkinliklerini planlayıp yöneten görevlidir.","ornek":"Sabah 08.30, bahçe: spor animatörü matları serer, katılanlara “Zorlandığınız hareketi yapmayın, kendi hızınızda devam edin.” der.","sektor":"Etkinlikten önce sahayı ve araç gereci güvenlik açısından gözden geçirir; kimsenin kendini zorlayıp sakatlanmasına izin vermez. Topların, raketlerin ve matların toplanması, temiz tutulması ve yerine kaldırılması da ondan beklenir.","iliskili":["os-3-312","os-3-344","os-3-327"],"kontrol":null},{"id":"os-3-329","konu":"3.4.3","terim":"Çocuk kulübü animatörü","ingilizce":"Mini club animator","tanim":"Çocukların güvenli, eğitici ve eğlenceli bir ortamda vakit geçirmesini sağlayan görevlidir.","ornek":"Saat 11.00: animatör çocukları define avı için bahçeye çıkarmadan önce tek tek sayar; bahçeye varınca yeniden sayar.","sektor":"Define avı, atölye, boyama ve mini disko gibi etkinlikler düzenler; alanın güvenliğini kontrol eder ve çocukları bir an bile yalnız bırakmaz. Çocukları sevgiyle karşılar, kayıt formunu özenle doldurur ve aileyi bilgilendirir. Yalnız bir oyun arkadaşı değil, aile ile otel arasındaki güven köprüsüdür.","iliskili":["os-3-309","os-3-330","os-3-347"],"kontrol":null},{"id":"os-3-330","konu":"3.4.3","terim":"Teslim alma ve teslim etme kaydı","ingilizce":"Sign-in and sign-out record","tanim":"Çocuğun kulübe kim tarafından, ne zaman bırakıldığının ve kime teslim edildiğinin yazıyla kayıt altına alınmasıdır.","ornek":"Saat 12.00, çocuk kulübü: animatör çocuğu teslim ederken kayıt formundaki veli adına bakar, anneye imza attırır ve saati yazar.","sektor":"Çocuk yalnız kayıt formunda veli ya da yetkili kişi olarak yazılı kişiye teslim edilir; tanınmayan biri “akrabasıyım” dese bile çocuk verilmez, animatör şefe ve veliye haber verir. Kayıt çocuğu da aileyi de animatörü de korur.","iliskili":["os-3-329","os-3-347","os-3-309"],"kontrol":null,"kitapDisi":true,"cizim":"belge-form"},{"id":"os-3-331","konu":"3.4.3","terim":"Ses ve ışık yöneticisi","ingilizce":"Sound and lighting manager","tanim":"Gösterilerin ses ve ışık sistemlerini kuran, deneyen ve gösteri sırasında yöneten teknik görevlidir.","ornek":"Saat 21.30, kabin: dansçılar sahneye girerken müziği başlatır, solo bölümünde ışığı tek bir dansçının üzerine toplar.","sektor":"Hoparlör, telsiz mikrofon, mikser ve ışık robotlarını kurar, her gösteriden önce ses ve ışık provası yapar, gösteride müzik geçişlerini ve ışık senaryosunu yönetir. Ekipmanın düzenli bakımı ve arızaya anında müdahale de onun işidir; elektrik bağlantılarının ve kabloların İSG kurallarına uygun olmasını sağlar.","iliskili":["os-3-318","os-3-337","os-3-340"],"kontrol":null,"gorsel":"h3b-isik-mikser"},{"id":"os-3-332","konu":"3.4.3","terim":"Sahne yöneticisi","ingilizce":"Stage manager","tanim":"Gösterinin sahne akışından, provalarından ve sahne arkasındaki düzenden sorumlu olan görevlidir.","ornek":"Gösteri sırasında sahne arkasında elinde akış listesiyle durur; “İkinci grup hazır olsun, otuz saniye sonra sahnedesiniz.” diye fısıldar.","sektor":"Dansçıların ve oyuncuların provasını yönetir; kostüm, dekor ve makyajın sahneye uygunluğunu takip eder; sanatçıların sahneye giriş çıkış zamanını ayarlar. Sahne arkasında düzen yoksa seyirci bunu sahnede boşluk olarak görür.","iliskili":["os-3-333","os-3-334","os-3-336"],"kontrol":null,"cizim":"lider"},{"id":"os-3-333","konu":"3.4.3","terim":"Koreograf","ingilizce":"Choreographer","tanim":"Gösterilerdeki dans ve hareket düzenini müziğe ve temaya göre tasarlayan, ekibe öğreten sanat görevlisidir.","ornek":"Saat 14.00, prova salonu: koreograf yeni gösterinin ilk sekiz adımını gösterir, ekip aynanın karşısında aynı anda yapana kadar tekrar ettirir.","sektor":"Figürleri öğretir, provaları yönetir ve ekibin uyumunu denetler; hareketin müzik ve ışıkla uyuşması için sahne yöneticisi ve teknik ekiple birlikte çalışır. Halk oyunları gibi geleneksel değerleri modern dansla buluşturmak da onun işidir.","iliskili":["os-3-335","os-3-332","os-3-336"],"kontrol":null,"cizim":"festival"},{"id":"os-3-334","konu":"3.4.3","terim":"Kostüm sorumlusu","ingilizce":"Costume supervisor","tanim":"Gösterilerde kullanılan kıyafet ve aksesuarların hazırlanmasından, bakımından ve sayımından sorumlu olan görevlidir.","ornek":"Gösteriden bir saat önce kostümleri sırasıyla askıya dizer; gösteri sırasında sahne arkasında bekler, bir dakikada kıyafet değiştirecek dansçıya yardım eder.","sektor":"Sektörde “kostümcü” de denir. Gösterinin temasına uygun kıyafetleri seçer ve eksikleri tamamlar; kıyafetlerin temiz, ütülü ve sağlam kalmasını sağlar, ufak yırtık ve sökükleri diker; depoyu düzenli tutar, hiçbir parça kaybolmasın diye sayım yapar. Sahnede izlenen karakterin gerçek görünmesi kostümün ayrıntılarına gösterilen özene bağlıdır.","iliskili":["os-3-346","os-3-332","os-3-350"],"kontrol":null,"cizim":"lider"},{"id":"os-3-335","konu":"3.4.3","terim":"Dans ekibi","ingilizce":"Dance team","tanim":"Modern dans, halk oyunları ve temalı gösterileri sahnede sergileyen sanatçı grubudur.","ornek":"Saat 16.00: o akşam gösteri olsa da olmasa da ekip prova salonundadır; koreografiyi baştan sona iki kez geçer.","sektor":"Günlük provalara katılır, koreografiyi ezberler ve kondisyonunu yüksek tutar. Dans dil gerektirmez; farklı ülkelerden konuklarla bağ kurmanın en kısa yoludur. Sahne makyajı, kostüm bakımı ve kişisel temizlik ekibin disiplin kurallarındandır.","iliskili":["os-3-333","os-3-336","os-3-315"],"kontrol":null,"gorsel":"h3b-halk-dansi-ekibi"},{"id":"os-3-336","konu":"3.4.3","terim":"Prova","ingilizce":"Rehearsal","tanim":"Gösterinin seyirci karşısına çıkmadan önce, hataları görmek ve gidermek için baştan sona denenmesidir.","ornek":"Saat 18.00, amfi tiyatro: seyirci gelmeden ekip gösteriyi kostümlü olarak bir kez oynar; ışığın geç yandığı sahne not edilip düzeltilir.","sektor":"İki türü vardır: sanatçıların hareket ve akışı çalıştığı sahne provası ile teknik ekibin her gösteriden önce yaptığı ses ve ışık provası. Provada çıkan hata düzeltilir, seyirci önünde çıkan hata otelin adına yazılır.","iliskili":["os-3-332","os-3-331","os-3-335"],"kontrol":null,"gorsel":"h3b-sahne-prova"},{"id":"os-3-337","konu":"3.4.4","terim":"Ses sistemleri","ingilizce":"Sound systems","tanim":"Sesi dengeleyen, netleştiren ve alana eşit biçimde yayan mikser, hoparlör ve telsiz mikrofon gibi donanımlardır.","ornek":"Havuz başı oyununda animatör telsiz mikrofonla dolaşır; sesi en arkadaki şezlongdan da rahatça duyulur.","sektor":"Amfi tiyatroda, havuz başında, diskoda ve lobi etkinliklerinde kullanılır. Mikser, mikrofon ve müzik gibi farklı kaynaklardan gelen sesin düzeyini ayarlayan masadır. Fazla açılan ses dinlenmek isteyen konuğu rahatsız eder; denge işin ustalığıdır.","iliskili":["os-3-340","os-3-331","os-3-318"],"kontrol":null,"cizim":"megafon"},{"id":"os-3-340","konu":"3.4.4","terim":"Işık sistemleri","ingilizce":"Lighting systems","tanim":"Sahnede dikkatin toplanacağı noktayı belirleyen ve gösterinin atmosferini güçlendiren ışık robotu, takip spotu ve kontrol masası gibi donanımlardır.","ornek":"Saat 22.00: sahne kararır, tek bir takip spotu yanar ve sahneye yürüyen şarkıcıyı adım adım izler.","sektor":"Gece gösterilerinde, dans performanslarında ve konserlerde kullanılır. Işık robotu, yönü ve rengi uzaktan değiştirilebilen hareketli projektördür; takip spotu sahnedeki kişiyi izleyen güçlü ışıktır. Işık senaryosu kontrol masasından, DMX adı verilen sistemle yönetilir.","iliskili":["os-3-337","os-3-331","os-3-346"],"kontrol":null,"gorsel":"ek-sahne-isiklari"},{"id":"os-3-344","konu":"3.4.4","terim":"Spor ve rekreasyon donanımı","ingilizce":"Sports and recreation equipment","tanim":"Konukların spor etkinliklerini ve turnuvaları güvenli biçimde yapmasını sağlayan voleybol filesi, dart seti, yoga matı ve top gibi araçlardır.","ornek":"Saat 16.45, plaj: animatör turnuvadan önce filenin direklerini sallayarak dener, kumdaki taşları toplar.","sektor":"Plajda, spor sahalarında, havuz çevresinde ve fitness alanında kullanılır. Yıpranmış bir file ya da çatlak bir raket yalnız oyunu değil, konuğu da tehlikeye atar; bozuk ekipmanla etkinlik başlatılmaz.","iliskili":["os-3-328","os-3-312","os-3-352"],"kontrol":null,"gorsel":"sektor-fitness"},{"id":"os-3-345","konu":"3.4.4","terim":"Çocuk kulübü donanımı","ingilizce":"Kids' club equipment","tanim":"Çocukların hareket becerisini ve yaratıcılığını geliştiren, güvenli bir oyun alanı oluşturan eğitici oyuncak, boya seti ve mini sahne gibi araçlardır.","ornek":"Sabah 09.45: animatör boya kalemlerini sayar, ucu kırık makası ayırır, oyuncakları siler; kapı 10.00’da açılacaktır.","sektor":"Çocuk kulübünde ve çocuk parklarında kullanılır. Seçerken ilk ölçüt çocuğun sağlığı ve güvenliğidir: kırık, keskin ya da yaşa uygun olmayan oyuncak alandan kaldırılır.","iliskili":["os-3-309","os-3-329","os-3-344"],"kontrol":null,"gorsel":"sektor-cocuk-oyun-alani"},{"id":"os-3-346","konu":"3.4.4","terim":"Sahne ve kostüm donanımı","ingilizce":"Stage and costume equipment","tanim":"Gösterinin görsel inandırıcılığını artıran ve karakterleri canlandırmaya yarayan temalı kostüm, peruk ve dekor panosu gibi malzemelerdir.","ornek":"Korsan temalı gecede sahneye gemi görünümlü bir dekor panosu konur; animatörler korsan kostümü ve perukla çıkar.","sektor":"Sahne arkasında hazır tutulur; tiyatro ve parodi gösterilerinde kullanılır. Seyirci sahnedeki emeği önce gözüyle görür: sökük bir kostüm bütün gösterinin değerini düşürür.","iliskili":["os-3-334","os-3-340","os-3-332"],"kontrol":null,"gorsel":"t13b-peruk-kostum"},{"id":"os-3-409","konu":"3.4.4","terim":"Peruk ve dekor panoları","ingilizce":"Wigs and scenery panels","tanim":"Sahnede karakteri canlandırmak için takılan saç takımlarından ve gösterinin arka planını kuran levhalardan oluşan sahne malzemeleridir.","ornek":"Akşam gösterisinde animatör gri peruğu takarak yaşlı bir sihirbaza dönüşür; arkasındaki panoda eski bir kale resmi vardır.","sektor":"Otelin etkinlik ekibi, sahne gösterilerinde karakteri inandırıcı kılmak için peruk ve dekor panolarını kullanır. Ders kitabına göre bu donanım tematik kostümlerle birlikte “sahne ve kostüm” grubunda yer alır; kullanım alanı sahne arkası, tiyatro ve parodi gösterileridir.","iliskili":["os-3-346","os-3-334","os-3-332"],"kontrol":null,"cizim":"festival"},{"id":"os-3-347","konu":"3.4.4","terim":"Aktivite katılım (kayıt) formu","ingilizce":"Activity registration form","tanim":"Çocuk kulübüne ya da okçuluk, dalış gibi riskli spor etkinliklerine katılan konukların bilgilerinin ve onaylarının alındığı belgedir.","ornek":"Saat 10.00: baba, oğlunu çocuk kulübüne bırakırken forma oda numarasını, telefonunu ve çocuğun fıstık alerjisini yazıp imzalar.","sektor":"Form doldurulmadan çocuk kulübe, konuk riskli etkinliğe alınmaz. Alerji gibi sağlık bilgisi buradan öğrenilir; bir sorun olduğunda kime ulaşılacağı da bu formda yazılıdır.","iliskili":["os-3-330","os-3-329","os-3-348"],"kontrol":null,"cizim":"resepsiyon"},{"id":"os-3-348","konu":"3.4.4","terim":"Aktivite çizelgesi","ingilizce":"Activity schedule","tanim":"Konuklara sunulacak etkinliklerin zamanını, yerini ve içeriğini gösteren, günlük ya da haftalık hazırlanıp ilan edilen programdır.","ornek":"Lobideki panoda şu yazılıdır: “10.30 su jimnastiği - havuz · 15.00 dart - bahçe · 21.30 dans gösterisi - amfi tiyatro”.","sektor":"Konuk gününü buna bakarak planlar, animatör de nerede ve ne zaman görevli olduğunu buradan görür. Çizelgede yazan etkinlik yazdığı saatte başlar; haber vermeden yapılan iptal güveni sarsar.","iliskili":["os-3-319","os-3-325","os-3-347"],"kontrol":null,"cizim":"takvim"},{"id":"os-3-349","konu":"3.4.4","terim":"Etkinlik malzeme talep formu","ingilizce":"Material requisition form","tanim":"Aktivite ve gösteriler için gereken boya, ödül, kostüm parçası gibi sarf malzemelerinin depodan istenmesinde kullanılan belgedir.","ornek":"Perşembe günü animatör cumartesi yapılacak çocuk şenliği için forma “parmak boyası, balon, madalya” yazar ve şefine imzalatır.","sektor":"Sarf malzemesi, kullanıldıkça biten malzemedir. Yazılı talep hem deponun stok kaydını doğru tutar hem de malzemenin etkinlikten önce hazır olmasını sağlar; son dakikada sözle istenen malzeme çoğu zaman yetişmez.","iliskili":["os-3-350","os-3-352","os-3-345"],"kontrol":null},{"id":"os-3-350","konu":"3.4.4","terim":"Etkinlik hizmetlerinde zimmet formu","ingilizce":"Equipment issue form","tanim":"Personele teslim edilen telsiz, mikrofon gibi teknik donanımın ya da kostümün sorumluluğunun kimde olduğunu kayıt altına alan belgedir.","ornek":"Sezon başında animatöre bir telsiz ve iki kostüm verilir; teslim alırken formu imzalar, sezon sonunda aynı formla geri verir.","sektor":"Zimmet, bir malın korunması için belirli bir kişiye imza karşılığı teslim edilmesidir. Kimin neyi aldığı belli olunca kaybolan ya da bozulan malzemenin izi sürülebilir; personel de kendisine ait olmayan bir kayıptan sorumlu tutulmaz.","iliskili":["os-3-349","os-3-334","os-3-352"],"kontrol":null,"cizim":"belge-form"},{"id":"os-3-351","konu":"3.4.4","terim":"Etkinlik memnuniyet anketi","ingilizce":"Guest satisfaction survey","tanim":"Yapılan etkinliklerin konuk gözündeki başarısını ölçmek ve geliştirilecek yönleri belirlemek için uygulanan soru formudur.","ornek":"Cuma akşamı gösteri çıkışında konuklara kısa bir anket verilir; çoğu konuk “müzik çok yüksekti” diye yazınca ertesi hafta ses düzeyi düşürülür.","sektor":"Ders kitabında “konuk memnuniyet anketi” adıyla geçer. Anket doldurtmak yetmez; sonuçlar okunur ve programa yansıtılır. Konuk önerisinin dikkate alındığını görünce değer gördüğünü hisseder.","iliskili":["os-3-319","os-3-324","os-3-348"],"kontrol":null,"cizim":"zil-hizmet"},{"id":"os-3-352","konu":"3.4.4","terim":"Etkinlik hizmetlerinde arıza bildirim formu","ingilizce":"Fault report form","tanim":"Ses, ışık ya da spor ekipmanında ortaya çıkan aksaklığın teknik servise yazıyla bildirilmesinde kullanılan belgedir.","ornek":"Saat 14.00: animatör sahnedeki bir hoparlörden cızırtı geldiğini fark eder, formu doldurup teknik servise iletir; arıza akşam gösterisinden önce giderilir.","sektor":"Sözle söylenen arıza unutulabilir, yazılan arızanın takibi yapılır. Arızalı ekipmanı kullanmayı sürdürmek ya da kendi başına onarmaya çalışmak, özellikle elektrikli cihazlarda ciddi kaza riskidir.","iliskili":["os-3-358","os-3-349","os-3-344"],"kontrol":null,"cizim":"belge-form"},{"id":"os-3-353","konu":"3.4.5","terim":"Etkinlik hizmetlerinde departmanlar arası iş birliği","ingilizce":"Interdepartmental co-operation in entertainment","tanim":"Hizmetin sorunsuz sunulabilmesi için etkinlik ekibinin ön büro, yiyecek içecek, kat hizmetleri, teknik servis ve güvenlik ile birlikte çalışmasıdır.","ornek":"Cumartesi akşamı havuz başı partisi: mutfak ikramı hazırlar, teknik servis ses sistemini kurar, güvenlik girişte durur, kat hizmetleri sabaha alanı temizler.","sektor":"Hiçbir departman tek başına tam bir konuk deneyimi yaratamaz. Konuk sahnede yalnız animatörü görür; ama o gösterinin arkasında beş departmanın daha emeği vardır.","iliskili":["os-3-354","os-3-355","os-3-358"],"kontrol":null},{"id":"os-3-354","konu":"3.4.5","terim":"Etkinlik hizmetleri ve ön büro iş birliği","ingilizce":"Co-operation with the front office","tanim":"Ön büronun konuk profiline ait yaş, milliyet ve ilgi alanı bilgilerini etkinlik hizmetleriyle paylaşmasına dayanan ortak çalışmadır.","ornek":"Pazartesi sabahı ön büro, o hafta otelde çok sayıda çocuklu aile olacağını bildirir; şef haftalık programa iki çocuk etkinliği daha ekler.","sektor":"Bu bilgi sayesinde konuk kendisine uygun etkinliğe yönlendirilir ve kişiye özel hizmet sunulur. Ön büro da konuğun “Bu akşam ne var?” sorusuna cevap verebilmek için günlük programı bilmelidir.","iliskili":["os-3-353","os-3-348","os-3-355"],"kontrol":null},{"id":"os-3-355","konu":"3.4.5","terim":"Etkinlik hizmetleri ve yiyecek içecek iş birliği","ingilizce":"Co-operation with food and beverage","tanim":"Temalı gecelerin, havuz başı ikramlarının ve özel organizasyonların yiyecek içecek departmanıyla birlikte planlanmasıdır.","ornek":"Çarşamba akşamı Türk gecesi: sahnede halk oyunları gösterisi varken büfede yöresel yemekler, bahçede gözleme tezgâhı yer alır.","sektor":"Temalı gece, belirli bir konu çevresinde müziği, süslemesi ve yemeği birlikte kurgulanan akşamdır. Lezzet ile eğlence birleşince konuğun bütün duyularına hitap eden bir deneyim ortaya çıkar.","iliskili":["os-3-353","os-3-354","os-3-357"],"kontrol":null},{"id":"os-3-357","konu":"3.4.5","terim":"Etkinlik hizmetleri ve kat hizmetleri iş birliği","ingilizce":"Co-operation with housekeeping","tanim":"Aktivite alanlarının ve çocuk kulübünün hijyeninin sağlanması ile kostümlerin temizlenmesi konusunda kat hizmetleriyle yürütülen ortak çalışmadır.","ornek":"Gece 23.30: gösteri biter, konuklar ayrılır; kat hizmetleri ekibi amfi tiyatroyu temizler, kullanılan kostümler çamaşırhaneye gider.","sektor":"Amaç konuğa sağlıklı ve temiz bir eğlence ortamı sunmaktır. Çocukların yere oturduğu, oyuncakların elden ele geçtiği çocuk kulübünde hijyen, ailelerin en çok dikkat ettiği konudur.","iliskili":["os-3-353","os-3-309","os-3-358"],"kontrol":null},{"id":"os-3-358","konu":"3.4.5","terim":"Etkinlik hizmetleri ve teknik servis iş birliği","ingilizce":"Co-operation with maintenance (engineering)","tanim":"Ses ve ışık sistemlerinin bakımı ile sahne güvenliğinin sağlanması için teknik servisle yürütülen ortak çalışmadır.","ornek":"Saat 17.00: teknik servis görevlisi sahnenin elektrik panosunu ve yerdeki kabloları kontrol eder; açıkta kalan bir uzatma kablosunu sabitler.","sektor":"Teknik aksaklıklar önceden önlenirse gösteri kesintisiz ve güvenli olur. Elektrik işine eğitimi olmayan personel karışmaz; görevi, sorunu fark edip doğru kişiye bildirmektir.","iliskili":["os-3-352","os-3-331","os-3-359"],"kontrol":null,"cizim":"is-birligi"},{"id":"os-3-359","konu":"3.4.5","terim":"Etkinlik hizmetleri ve güvenlik iş birliği","ingilizce":"Co-operation with security","tanim":"Kalabalık etkinliklerde düzenin sağlanması ve acil durumların yönetilmesi için güvenlik birimiyle yürütülen ortak çalışmadır.","ornek":"Yılbaşı gecesi: güvenlik görevlileri salonun acil çıkış kapılarının önünün açık olduğunu kontrol eder ve kalabalığın akışını izler.","sektor":"Konuk ancak kendini güvende hissederse rahatça eğlenir. Acil durumda animatör kendi başına hareket etmez: konukları sakin tutar, güvenliğe ve amirine haber verir.","iliskili":["os-3-353","os-3-358","os-3-325"],"kontrol":null,"cizim":"is-birligi"},{"id":"os-3-360","konu":"3.5","terim":"İş planı","ingilizce":"Business plan (work plan)","tanim":"İşletmenin hedeflerini, bu hedeflere ulaşmak için izleyeceği yolu ve karşılaşabileceği riskleri önceden yazıya döken yol haritasıdır.","ornek":"Kasım ayı, Fethiye’de bir otel: müdür ve departman şefleri toplanır; gelecek sezonun hedeflerini, kaç personel gerektiğini ve olası sorunlara karşı ne yapılacağını yazar.","sektor":"Yalnız yatırımcı için hazırlanan bir belge değildir: ön bürodan kat hizmetlerine, mutfaktan pazarlamaya bütün departmanları aynı hedefte buluşturur. Her departman kendi iş akışına göre belirli dönemlere yayılan planını yapar. Plansız iş, o günün tesadüflerine kalır.","iliskili":["os-3-361","os-3-362","os-3-363"],"kontrol":null,"cizim":"girisim-isletme"},{"id":"os-3-361","konu":"3.5","terim":"SMART hedef","ingilizce":"SMART goal","tanim":"Belirli, ölçülebilir, ulaşılabilir, ilgili ve zamana bağlı olacak biçimde konmuş hedeftir.","ornek":"“Konuklar daha memnun olsun.” bir dilektir; “Yaz sonuna kadar giriş işlemindeki bekleme şikâyetlerini yarıya indireceğiz.” ise SMART hedeftir.","sektor":"Ad, İngilizce beş sözcüğün baş harflerinden oluşur: specific (belirli), measurable (ölçülebilir), achievable (ulaşılabilir), relevant (ilgili), time-bound (zamana bağlı). Dördüncü harf başka kaynaklarda realistic (gerçekçi) diye de açılır. Ölçülemeyen hedefe ulaşılıp ulaşılmadığı bilinemez.","iliskili":["os-3-360","os-3-363","os-3-362"],"kontrol":null,"cizim":"hedef-basari"},{"id":"os-3-362","konu":"3.5","terim":"B planı","ingilizce":"Contingency plan (plan B)","tanim":"Sistem arızası ya da fazla rezervasyon gibi beklenmedik durumlarda uygulanmak üzere önceden hazırlanan yedek plandır.","ornek":"Saat 20.00, açık havada gala yemeği: yağmur başlar; ekip önceden hazırlanan plana göre yarım saat içinde masaları balo salonuna taşır.","sektor":"İş planının kriz ve risk yönetimi bölümünde yer alır. Kriz anında düşünmeye vakit yoktur: ne yapılacağı önceden yazılmışsa ekip paniğe kapılmaz, konuk da sorunu çoğu zaman fark etmez.","iliskili":["os-3-360","os-3-372","os-3-396"],"kontrol":null,"cizim":"takvim"},{"id":"os-3-363","konu":"3.5","terim":"İnsan kaynakları planlaması","ingilizce":"Human resources planning","tanim":"İş planında gereken personel sayısının, görevlerinin, yeterliliklerinin ve alacakları eğitimlerin önceden belirlenmesidir.","ornek":"Nisan ayı: otel yaz sezonu için kaç kat görevlisi ve kaç resepsiyon görevlisi gerektiğini hesaplar; yeni başlayacaklar için mayısta bir haftalık eğitim planlar.","sektor":"Personelin motivasyonunu ve mesleki gelişimini artıracak eğitimler de bu planın parçasıdır. Eksik personelle hizmet aksar, fazla personelle maliyet artar; eğitimsiz personel ise iyi planı bile uygulayamaz.","iliskili":["os-3-360","os-3-364","os-3-365"],"kontrol":null,"cizim":"takvim"},{"id":"os-3-364","konu":"3.5.1","terim":"Vardiya","ingilizce":"Shift","tanim":"Yirmi dört saat hizmet veren işletmede günün dilimlere bölünmesi ve her dilimde ayrı bir ekibin çalışması düzenidir.","ornek":"Resepsiyonda sabah ekibi 07.00’de işi gece ekibinden devralır; öğleden sonra yerini akşam ekibine bırakır.","sektor":"Otel hiç kapanmaz; konuk gece 03.00’te de resepsiyonda birini bulmalıdır. Vardiya saatleri işletmeye göre değişir. Vardiya düzenlemeleri iş planının insan kaynakları bölümünde yer alır.","iliskili":["os-3-365","os-3-366","os-3-363"],"kontrol":null},{"id":"os-3-365","konu":"3.5","terim":"Vardiya çizelgesi","ingilizce":"Duty roster (rota)","tanim":"Hangi personelin hangi gün, hangi vardiyada çalışacağını ve izin günlerini gösteren tablodur.","ornek":"Cuma günü personel panosuna gelecek haftanın çizelgesi asılır; stajyer salı ve çarşamba sabah, perşembe akşam vardiyasında olduğunu görür.","sektor":"Sektörde “shift listesi” ya da “rota” da denir. Yoğun saatlere daha çok personel yazılır. Çizelgeye bakmadan plan yapan ya da amirine sormadan arkadaşıyla vardiya değiştiren personel ekibi zor durumda bırakır.","iliskili":["os-3-364","os-3-366","os-3-363"],"kontrol":null,"kitapDisi":true,"cizim":"takvim"},{"id":"os-3-366","konu":"3.5.1","terim":"Vardiya devri","ingilizce":"Shift handover","tanim":"İşi bırakan ekibin, yarım kalan işleri ve önemli bilgileri işi devralan ekibe yazılı ve sözlü olarak aktarmasıdır.","ornek":"Sabah 07.00: gece görevlisi “214’ün kliması arızalı, teknik servise bildirildi, konuk 09.00’da aranacak” notunu deftere yazar ve sabahçıya ayrıca söyler.","sektor":"Ön büroda bu notlar vardiya defterine (log book) yazılır. Kâğıt parçasına alınıp deftere geçirilmeyen şikâyet, vardiya değişince kaybolur; konuk aynı sorunu ikinci kez anlatmak zorunda kalır ve öfkelenir.","iliskili":["os-3-364","os-3-365","os-3-371"],"kontrol":null,"cizim":"ekip"},{"id":"os-3-368","konu":"3.5.1","terim":"Ön büro iş planı","ingilizce":"Front office work plan","tanim":"Ön büronun satış, operasyon, insan kaynakları ve konuk ilişkileri işlerini önceden düzenleyen, konuk memnuniyeti ile kârlılığı birlikte gözeten plandır.","ornek":"Sezon öncesi toplantı: ön büro müdürü giriş ve çıkış işlemlerinin standardını, vardiya düzenini ve şikâyetlerin nasıl ele alınacağını ekibiyle birlikte yazıya döker.","sektor":"Dört bileşeni vardır: satış stratejileri, operasyonel süreçler, insan kaynakları ve konuk ilişkileri (şikâyet yönetimi, kişiye özel hizmet, geri bildirimlerin incelenmesi). Ders kitabı her bileşenin yanına geliştirdiği beceriyi de yazar: satış stratejileri - finansal okuryazarlık, operasyonel süreçler - zaman yönetimi ve planlama, insan kaynakları - iş birliği ve iletişim, konuk ilişkileri - empati ve problem çözme. Dürüstlük, sorumluluk ve saygı gibi değerler de plana girer: plan yalnız ne yapılacağını değil, nasıl davranılacağını da söyler.","iliskili":["os-3-369","os-3-371","os-3-372"],"kontrol":null},{"id":"os-3-369","konu":"3.5.1","terim":"Ön büro planında satış stratejileri","ingilizce":"Sales strategies in the front office plan","tanim":"Oda fiyatlarının belirlenmesini, paket satışlarını ve konuğa ek hizmet önerilmesini kapsayan plan bileşenidir.","ornek":"Giriş sırasında görevli balayı çiftine “Dilerseniz küçük bir farkla deniz manzaralı odamıza geçebilirsiniz.” diye öneride bulunur.","sektor":"Konuğa daha üst bir oda ya da ek hizmet önermeye sektörde “upselling” denir. Doğru yapıldığında konuk ihtiyacına uygun hizmeti alır, otelin geliri artar; ısrara dönerse konuk kendini baskı altında hisseder.","iliskili":["os-3-368","os-3-371","os-3-372"],"kontrol":null},{"id":"os-3-371","konu":"3.5.1","terim":"Ön büro günlük iş akışı","ingilizce":"Front office daily workflow","tanim":"Ön büroda bir gün içinde yapılan işlerin saat dilimlerine göre sıralanmasıdır.","ornek":"Sabah vardiya devri ve gece raporlarının okunması, ardından çıkış yoğunluğu, öğleye doğru boşalan odalar için kat hizmetleriyle iletişim, öğleden sonra girişler.","sektor":"Hangi saatte hangi işin yoğunlaşacağını bilen ekip hazırlıklı olur: çıkış saatinde kasada, giriş saatinde bankoda yeterli görevli bulunur. Giriş ve çıkış hızı, anahtar teslimi ve bagaj hizmeti standartları iş planının operasyonel süreçler bölümünde yer alır; saatler işletmeye göre değişir. Ders kitabındaki örnek zaman tünelinde 07.00-08.00 vardiya devri (gece raporları ve log book notlarının incelenmesi), 08.00-11.00 çıkış yoğunluğu (konukların uğurlanması, ödemelerin alınması), 11.00-13.00 boşalan odalar için kat hizmetleriyle koordinasyon yer alır; 14.00-16.00 konukların tesise giriş yapmaya başladığı saatlerdir.","iliskili":["os-3-368","os-3-366","os-3-369"],"kontrol":null},{"id":"os-3-372","konu":"3.5.1","terim":"Fazla rezervasyon eylem planı","ingilizce":"Overbooking action plan","tanim":"Otelin oda sayısından fazla rezervasyon aldığı durumda konuğu mağdur etmemek için izlenecek adımları önceden belirleyen plandır.","ornek":"Ağustosta bir cumartesi: otel tam doludur ve rezervasyonlu iki konuk daha gelecektir; ön büro müdürü sabahtan anlaşmalı otelde iki oda ayırtır.","sektor":"Fazla rezervasyon (overbooking), rezervasyon yaptırıp gelmeyen (no-show) konukların yol açacağı gelir kaybına karşı bilerek alınan bir risktir; iyi yönetilmezse otelin imajına zarar verir. Plan dört aşamadan oluşur: önleme ve izleme, hazırlık, konukla iletişim, telafi ve takip.","iliskili":["os-3-373","os-3-374","os-3-375"],"kontrol":null},{"id":"os-3-373","konu":"3.5.1","terim":"Önleme ve izleme","ingilizce":"Prevention and monitoring","tanim":"Fazla rezervasyon planının, doluluğun her gün takip edildiği ve rezervasyonların garantili ve garantisiz olarak ayrıldığı ilk aşamasıdır.","ornek":"Sabah 08.00: rezervasyon görevlisi o günün listesini açar; garantisiz rezervasyonları arayıp gelip gelmeyeceklerini teyit eder.","sektor":"Garantili rezervasyonda konuk ödeme güvencesi vermiştir, geç gelse de odası tutulur; garantisiz rezervasyonda böyle bir güvence yoktur. Sorun ne kadar erken görülürse çözmek o kadar kolaydır.","iliskili":["os-3-372","os-3-374","os-3-376"],"kontrol":null,"cizim":"festival"},{"id":"os-3-374","konu":"3.5.1","terim":"Hazırlık aşaması","ingilizce":"Preparation stage","tanim":"Fazla rezervasyon planının, konuğun yönlendirilebileceği benzer kalitedeki otellerle önceden anlaşma yapıldığı ikinci aşamasıdır.","ornek":"Sezon başında ön büro müdürü aynı caddedeki benzer bir otelin müdürüyle görüşür; iki otel yoğun günlerde birbirine konuk yönlendirmek üzere anlaşır.","sektor":"Konuk daha düşük kalitede bir tesise gönderilirse mağduriyeti ikiye katlanır. Anlaşma önceden yapılmamışsa gece yarısı oda aramak hem zordur hem pahalıdır.","iliskili":["os-3-372","os-3-373","os-3-375"],"kontrol":null},{"id":"os-3-375","konu":"3.5.1","terim":"Konukla iletişim aşaması","ingilizce":"Guest communication stage","tanim":"Fazla rezervasyon planının, durumun konuğa nazikçe açıklandığı ve çözüm seçeneklerinin sunulduğu üçüncü aşamasıdır.","ornek":"Saat 22.00: yetkili, konuğu bankonun sakin köşesine alır ve “Sizden özür diliyoruz; bu gece için anlaşmalı otelimizde aynı tipte bir oda ayırdık.” der.","sektor":"Konuk yorgun ve haklıdır; bahane değil, çözüm duymak ister. Durum dürüstçe söylenir, suç sisteme ya da başka bir görevliye atılmaz. Bu görüşmeyi çoğunlukla yetkili yapar; stajyer konuğu bekletmeden amirine haber verir.","iliskili":["os-3-372","os-3-374","os-3-376"],"kontrol":null,"cizim":"konusma"},{"id":"os-3-376","konu":"3.5.1","terim":"Telafi ve takip","ingilizce":"Compensation and follow-up","tanim":"Fazla rezervasyon planının, konuğun mağduriyetinin ücretsiz transfer, yemek ikramı ya da sonraki konaklamada indirim gibi yollarla giderildiği son aşamasıdır.","ornek":"Otel konuğu kendi aracıyla anlaşmalı otele götürür, akşam yemeğini ikram eder; ertesi sabah konuk aranır ve odası hazır olunca geri getirilir.","sektor":"İyi telafi edilen bir hata konuğu kaybettirmez, hatta bağlılığını artırabilir. Takip yapılmazsa telafi yarım kalır: konuk “Beni gönderip unuttular.” diye düşünür.","iliskili":["os-3-372","os-3-375","os-3-373"],"kontrol":null},{"id":"os-3-426","konu":"3.5.1","terim":"Garantili ve garantisiz rezervasyon","ingilizce":"Guaranteed and non-guaranteed reservation","tanim":"Konuğun ödeme güvencesi verdiği ve odanın geç gelse de tutulduğu rezervasyon garantili, böyle bir güvencenin olmadığı rezervasyon garantisizdir.","ornek":"Akşam 18.00, ön büro: görevli rezervasyon listesine bakar; kredi kartıyla garanti vermiş konuğun odasını gece boyunca tutar, garantisiz rezervasyonun sahibini arayıp gelip gelmeyeceğini sorar.","sektor":"Kitaba göre fazla rezervasyon eylem planının ilk aşamasında doluluk takibiyle birlikte rezervasyonlar garantili ve garantisiz diye ayrılır; gelmeyen konuk riski bu ayrımdan okunur.","iliskili":["os-3-416","os-3-373","os-3-109"],"kontrol":null,"cizim":"sozlesme"},{"id":"os-3-377","konu":"3.5.2","terim":"Kat hizmetleri iş planı","ingilizce":"Housekeeping work plan","tanim":"Kat hizmetlerinin hijyen ve konfor beklentisini hatasız karşılamak için temizlik işlerini, malzemeyi ve personeli önceden düzenleyen plandır.","ornek":"Sabah 08.00, kat ofisi: kat şefi plana bakarak her görevliye odalarını dağıtır; o haftanın periyodik işi olan havalandırma kapağı temizliğini de listeye ekler.","sektor":"Dört bileşeni vardır: temizlik takvimi, envanter yönetimi (buklet, tekstil ve kimyasalların stok takibi), personel dağılımı (kat şefleri ve meydancıların görev alanı ve vardiyaları) ve hijyen standartları (kimyasal kullanım talimatları, yüzey temizlik kuralları). Amaç temizlik standardını korurken kaynakları boşa harcamamaktır.","iliskili":["os-3-378","os-3-381","os-3-382"],"kontrol":null,"cizim":"kurallar-liste"},{"id":"os-3-378","konu":"3.5.2","terim":"Temizlik takvimi","ingilizce":"Cleaning schedule","tanim":"Günlük oda temizliğinin, genel alan bakımının ve periyodik temizliklerin ne zaman yapılacağını gösteren plan bileşenidir.","ornek":"Takvimde şu yazılıdır: “Her gün: odalar ve lobi · Her pazartesi: 3. kat havalandırma kapakları · Ayın ilk haftası: koridor zeminlerinin cilası”.","sektor":"Takvim olmazsa her gün yapılan iş yapılır, arada bir yapılması gereken iş unutulur. Unutulan iş bir gün konuğun gözüne çarpar: tozlu bir havalandırma kapağı, temiz bir odanın bütün emeğini siler.","iliskili":["os-3-377","os-3-382","os-3-383"],"kontrol":null,"cizim":"takvim"},{"id":"os-3-381","konu":"3.5.2","terim":"İş planı çizelgesi","ingilizce":"Work schedule chart","tanim":"Yapılacak işi, yapılacağı yeri, işin günlük, haftalık, aylık ya da sezonluk oluşunu ve görevli personeli satır satır gösteren belgedir.","ornek":"Kat ofisinin duvarındaki çizelgede “5. kat koridor halısı - aylık - leke kontrolü - görevli: Ayşe Hanım” satırı yer alır.","sektor":"Çizelgeye bakan herkes bugün neyin, nerede, kim tarafından yapılacağını görür. Farklı katlarda çalışan iki görevlinin aynı standartta iş çıkarmasını bu yazılı düzen sağlar.","iliskili":["os-3-377","os-3-378","os-3-382"],"kontrol":null,"kitapDisi":true,"cizim":"takvim"},{"id":"os-3-382","konu":"3.5.2","terim":"Periyodik temizlik planı","ingilizce":"Periodic cleaning plan","tanim":"Günlük temizliğin ulaşamadığı ayrıntılara yönelik derin temizlik ve bakım işlerinin haftalık, aylık ya da sezonluk aralıklara bağlanmasıdır.","ornek":"Odada toz her gün alınır; perdelerin yıkanması ya da halının şampuanlanması ise plana yazılı aralıklarla yapılır.","sektor":"Plan yapılırken doluluk oranına bakılır: derin temizlik ve bakım için en uygun zaman otelin en sakin olduğu dönemdir. Düzenli bakım halının, mobilyanın ve tekstilin ömrünü uzatır; otel hem daha temiz kalır hem daha az yenileme masrafı yapar.","iliskili":["os-3-384","os-3-385","os-3-387"],"kontrol":null},{"id":"os-3-383","konu":"3.5.2","terim":"Günlük işler","ingilizce":"Daily tasks","tanim":"Kat hizmetlerinde her gün yinelenen oda temizliği, toz alma ve genel alanların bakımı gibi işlerdir.","ornek":"Saat 10.00, 3. kat: kat görevlisi odanın yatağını yapar, banyoyu temizler, çöpü boşaltır, tozu alır ve bukleti tamamlar.","sektor":"Temizlik takviminin temelidir; aksadığı gün konuk hemen fark eder. Günlük iş hızlı yapılır, ama kalite düşmez: süre kısalırken standart değişmez.","iliskili":["os-3-378","os-3-384","os-3-382"],"kontrol":null,"gorsel":"h6-dagilmis-yatak"},{"id":"os-3-384","konu":"3.5.2","terim":"Haftalık işler","ingilizce":"Weekly tasks","tanim":"Her gün gerekmeyen, haftada bir yapılan ayrıntılı temizlik işleridir.","ornek":"Salı günü kat görevlisi, konuğu çıkış yapmış odalarda tavandaki havalandırma kapaklarını (menfezleri) söküp temizler.","sektor":"Ders kitabının örneği menfez ve havalandırma kapaklarının temizliğidir; amaç hava kalitesi ve hijyendir. Hangi işin hangi aralıkla yapılacağı işletmeye göre değişebilir.","iliskili":["os-3-383","os-3-385","os-3-382"],"kontrol":null},{"id":"os-3-385","konu":"3.5.2","terim":"Aylık işler","ingilizce":"Monthly tasks","tanim":"Ayda bir yapılan, yüzeylerin görünümünü ve dayanıklılığını korumaya yönelik daha kapsamlı işlerdir.","ornek":"Ayın ilk pazartesi gecesi lobi zemini cilalanır; ertesi gün camların dış yüzeyi silinir.","sektor":"Ders kitabının örnekleri cilalama ve camların dış yüzey temizliğidir; amaç estetik ve korumadır. Cila zemini çizilmeye karşı korur ve parlak gösterir; iş, konuğun en az olduğu saatte yapılır ve ıslak zemin uyarı levhası konur.","iliskili":["os-3-384","os-3-386","os-3-382"],"kontrol":null,"cizim":"takvim"},{"id":"os-3-386","konu":"3.5.2","terim":"Altı aylık işler","ingilizce":"Six-monthly tasks","tanim":"Yılda iki kez yapılan halı yıkama, koltuk döşemesi temizliği ve genel ilaçlama gibi derinlemesine arındırma işleridir.","ornek":"Kasım ayında bir kat konuğa kapatılır: halılar makineyle yıkanır, koltuklar temizlenir, kat ilaçlanır; kuruyup havalanınca yeniden satışa açılır.","sektor":"Amaç günlük temizliğin çıkaramadığı birikmiş kiri ve mikrobu gidermektir. İlaçlamayı eğitimli ekip yapar; iş sırasında oda satışa kapatılır ve ön büroya bildirilir.","iliskili":["os-3-385","os-3-387","os-3-382"],"kontrol":null,"gorsel":"f3g-hali-yikama"},{"id":"os-3-387","konu":"3.5.2","terim":"Yıllık (sezonluk) işler","ingilizce":"Annual (seasonal) tasks","tanim":"Yılda bir ya da sezon arasında yapılan boya badana, yatakların döndürülmesi ve derin bakım gibi yenileme işleridir.","ornek":"Marmaris’te sezonluk bir otel kasımda kapanır; kış boyunca odalar boyanır, yataklar çevrilir, bozuk mobilyalar onarılır ve otel nisanda yenilenmiş olarak açılır.","sektor":"Amaç otelin varlıklarını (yatak, mobilya, bina) korumak ve yenilemektir. Yatak belirli aralıklarla çevrilirse her yeri eşit yıpranır ve ömrü uzar. Bu işler konuğun olmadığı ya da en az olduğu dönemde yapılır.","iliskili":["os-3-386","os-3-382","os-3-385"],"kontrol":null,"cizim":"takvim"},{"id":"os-3-388","konu":"3.5.2","terim":"Sıfır atık hedefi","ingilizce":"Zero waste goal","tanim":"Otelde atığın oluşmadan önlenmesini, kaçınılamayan atığın ise en aza indirilmesini amaçlayan çevreci hedeftir.","ornek":"Sabah 09.00, kat ofisi: kat şefi tek kullanımlık küçük şampuan şişeleri yerine duvara takılan dolum şişelerine geçilmesini önerir; odalara “Havlunuzu asarsanız değiştirmeyiz” kartı konur.","sektor":"Ders kitabı kat hizmetlerinde atık kaynaklarını dört başlıkta ele alır: buklet malzemeleri (tek kullanımlık küçük plastik şişeler), tekstil ürünleri (her gün değiştirilen çarşaf ve havlu), ambalajlar (plastik poşetli terlik, plastik çöp torbası) ve temizlik kimyasalları (sert kimyasallı, plastik ambalajlı ürünler). Her birine çevre dostu bir seçenek aranır. Personelin bilgilendirilmesi, ürün seçimi, oda temizlik standardı, konuk bilgilendirme ve denetim hedefin başarısını belirler.","iliskili":["os-3-377","os-3-383","os-3-382"],"kontrol":null,"gorsel":"t13b-kompost"},{"id":"os-3-389","konu":"3.5.3","terim":"Etkinlik iş planı","ingilizce":"Event work plan","tanim":"Bir etkinliğin fikir aşamasından konuğun otelden memnun ayrılmasına kadar bütün sürecini önceden düzenleyen plandır.","ornek":"Haziranda otelde bir düğün yapılacaktır; ekip iki ay önceden temayı, salonu, bütçeyi, günün akışını ve yağmur yağarsa ne yapılacağını yazar.","sektor":"Altı bileşeni vardır: etkinlik konsepti, mekân ve lojistik, bütçe ve finans, operasyonel iş akışı, pazarlama ve tanıtım, risk ve kriz yönetimi. Biri eksik kalırsa etkinlik o noktadan aksar.","iliskili":["os-3-390","os-3-391","os-3-392"],"kontrol":null},{"id":"os-3-390","konu":"3.5.3","terim":"Etkinlik konsepti","ingilizce":"Event concept","tanim":"Etkinliğin amacını, temasını ve hitap edeceği hedef kitleyi tanımlayan plan bileşenidir.","ornek":"“Çocuklu aileler için, cumartesi öğleden sonra, bahçede korsan temalı define avı”: amaç, tema ve hedef kitle tek cümlede bellidir.","sektor":"Düğün, kongre ve spor etkinliği birbirinden çok farklı hazırlık ister; planın geri kalanı konsepte göre kurulur. Hedef kitle, etkinliğin kimler için yapıldığıdır: çocuk, genç ve yetişkin aynı etkinlikten aynı keyfi almaz.","iliskili":["os-3-389","os-3-391","os-3-395"],"kontrol":null},{"id":"os-3-391","konu":"3.5.3","terim":"Mekân ve lojistik","ingilizce":"Venue and logistics","tanim":"Etkinliğin yapılacağı yerin seçimini, oturma düzenini, ses, ışık, sahne gibi teknik ekipmanı ve dekorasyonu kapsayan plan bileşenidir.","ornek":"İki yüz kişilik düğün için balo salonu seçilir; masaların yeri çizilir, sahne ve ses sistemi bir gün önceden kurulur.","sektor":"Yanlış dizilmiş masalar ya da denenmemiş ses sistemi son saatte paniğe yol açar. Mekân konuk sayısına, etkinliğin türüne ve güvenliğe uygun olmalıdır; uygun yer yoksa etkinlik oraya sığdırılmaya çalışılmaz.","iliskili":["os-3-389","os-3-390","os-3-393"],"kontrol":null,"gorsel":"sektor-konferans-salonu"},{"id":"os-3-392","konu":"3.5.3","terim":"Bütçe ve finans","ingilizce":"Budget and finance","tanim":"Etkinliğin gelir kalemlerini, yiyecek içecek, personel ve ekipman gibi tahmini giderlerini ve kâr hedefini belirleyen plan bileşenidir.","ornek":"Şef, çocuk şenliği için balon, boya ve ödül giderlerini tek tek yazar; toplam, ayrılan bütçeyi aşınca ödül sayısını azaltır.","sektor":"Bütçe, bir iş için ayrılan paranın nereye, ne kadar harcanacağını gösteren hesaptır. Bütçesiz etkinlikte ya para yarı yolda biter ya da gereğinden fazla harcanır; ikisi de işletmeye zarardır.","iliskili":["os-3-389","os-3-391","os-3-395"],"kontrol":null,"gorsel":"t13b-hesap-rapor"},{"id":"os-3-393","konu":"3.5.3","terim":"Operasyonel iş akışı","ingilizce":"Operational workflow","tanim":"Hazırlık aşamasından etkinliğin bitişine kadar bütün sürecin sırasıyla ve saat saat planlanmasıdır.","ornek":"“17.00 masa düzeni kontrolü · 18.00 ses ve ışık provası · 19.00 konukların karşılanması · 19.30 açılış · 23.00 kapanış ve toplanma”.","sektor":"Herkes hangi dakikada nerede olacağını bilirse işler çakışmaz. Akış yazılı değilse biri ses sistemini, öteki masaları bekler; konuklar ise çoktan kapıdadır.","iliskili":["os-3-389","os-3-398","os-3-391"],"kontrol":null},{"id":"os-3-395","konu":"3.5.3","terim":"Pazarlama ve tanıtım","ingilizce":"Marketing and promotion","tanim":"Etkinliğin hedef kitleye duyurulmasını, gerekiyorsa bilet satışını ve yeni konuk kazanma yollarını içeren plan bileşenidir.","ornek":"Yılbaşı galası için kasımda otelin internet sitesine ve sosyal medya hesabına duyuru konur; resepsiyona afiş asılır, bilet satışı başlar.","sektor":"Duyuru hedef kitlenin baktığı yerde yapılır: otelde kalan konuğa pano ve ekranla, dışarıdaki konuğa internetle ulaşılır. Duyurulmayan etkinliğe kimse gelmez.","iliskili":["os-3-389","os-3-390","os-3-397"],"kontrol":null},{"id":"os-3-396","konu":"3.5.3","terim":"Etkinlikte risk ve kriz yönetimi","ingilizce":"Risk and crisis management for events","tanim":"Teknik arıza, hava değişikliği ya da acil durum gibi olasılıklara karşı alternatif planların önceden hazırlanmasıdır.","ornek":"Açık hava konserinden önce ekip hava durumuna bakar; yağmur olasılığına karşı kapalı salonu boş tutar ve yedek bir mikrofon hazırlar.","sektor":"“Olmaz” denen şey bir gün olur. Önceden düşünülmüş bir alternatif varsa etkinlik iptal edilmez, yalnız yeri ya da yöntemi değişir. Can güvenliğini ilgilendiren durumda etkinlik durdurulur; hiçbir gösteri konuğun güvenliğinden önemli değildir.","iliskili":["os-3-389","os-3-362","os-3-393"],"kontrol":null},{"id":"os-3-397","konu":"3.5.3","terim":"Etkinlik programı hazırlama","ingilizce":"Preparing an activity programme","tanim":"Hangi etkinliğin hangi gün ve saatte, nerede ve kimin sorumluluğunda yapılacağının belirlenip onaydan sonra duyurulması işidir.","ornek":"Pazar akşamı şef gelecek haftanın programını hazırlar: konuk listesine bakar, etkinlikleri günlere dağıtır, müdüre onaylatır ve panoya astırır.","sektor":"Sıra şöyledir: programın türüne karar verilir (günlük, haftalık, sezonluk), etkinlikler seçilir, tarih ve saatleri belirlenir, yetkili onaylar, program personele ve konuklara ulaştırılır. Seçimde konuk profiline, tesisin alan ve donanımına, personel sayısına ve hava durumuna bakılır.","iliskili":["os-3-398","os-3-395","os-3-393"],"kontrol":null,"kitapDisi":true,"cizim":"takvim"},{"id":"os-3-398","konu":"3.5","terim":"Etkinlik akışının üç aşaması","ingilizce":"Three stages of an activity","tanim":"Bir etkinliğin başlangıç (giriş), uygulama ve kapanış (sonuç) olarak planlanan bölümleridir.","ornek":"Dart turnuvası: başlangıçta animatör kuralları ve güvenli atış mesafesini anlatır, uygulamada maçlar oynanır, kapanışta birinciye madalya verilir ve herkes alkışlanır.","sektor":"Başlangıçta katılımcı ne yapacağını ve güvenlik kurallarını öğrenir; kapanışta teşekkür edilir, alan toplanır. Planda etkinliğin adı, yaş grubu, süresi, araç gereci, alanı, görev dağılımı ve güvenlik önlemleri de yazılır. Yaş grubuna uygun hitap ve açık yönerge katılımı artırır.","iliskili":["os-3-393","os-3-397","os-3-396"],"kontrol":null},{"id":"os-3-399","konu":"3.5","terim":"Yaş grubuna göre etkinlik planlama","ingilizce":"Age-group activity planning","tanim":"Etkinliği çocuk, genç ya da yetişkin konukların beklentisine, becerisine ve güvenliğine uygun biçimde hazırlama işidir.","ornek":"Aynı tatil köyünde sabah çocuklar için bahçede define avı, öğleden sonra gençler için plaj voleybolu turnuvası, akşam yetişkinler için bilgi yarışması gecesi planlanır.","sektor":"Her yaş grubu için aynı sorular sorulur: bu konuk tatilden ne bekler, hangi donanım gerekir, hangi departmanlarla iş birliği yapılır, yaşa özgü riskler neler? Çocukta gözetim ve güvenlik her şeyin önündedir; genç arkadaşlarıyla yapabileceği, rekabetli etkinliklerden hoşlanır; yetişkin seçenek ister ve zorlanmaz. Ders kitabındaki etkinlik planlama çalışmasında çocuk 4-12, gençlik 13-17, yetişkin 18 yaş ve üzeri olarak ayrılır; yaş sınırları tesise göre değişir. Hitap dili de yaşa göre ayarlanır.","iliskili":["os-3-390","os-3-398","os-3-311","os-3-309"],"kontrol":null},{"id":"os-3-427","konu":"3.5","terim":"İş akış diyagramı","ingilizce":"Workflow diagram (flowchart)","tanim":"Bir işin adımlarını, adımların sırasını ve departmanlar arası geçişleri şekil ve oklarla gösteren çizimdir.","ornek":"Perşembe 10.00, ön büro toplantısı: müdür, arızalı bir odanın satışa hazır hâle gelme sürecini tahtaya kutular ve oklarla çizer; resepsiyondan teknik servise, oradan kat hizmetlerine geçen yolu herkes görür.","sektor":"Organizasyon şeması kimin kime bağlı olduğunu, iş akış diyagramı ise işin hangi sırayla ve hangi birimden geçtiğini gösterir; ikisi karıştırılmamalıdır.","iliskili":["os-3-016","os-3-393","os-3-371"],"kontrol":null,"cizim":"belge-form"}],"acikSorular":[{"id":"os-3-y01","konu":"3.1","soru":"Bir butik otelin ana departmanlarını sayınız ve bu departmanların neden ana departman sayıldığını belirtiniz. Bunlardan ikisinin birbirine bilgi vererek nasıl çalıştığını bir örnekle açıklayınız.","olcut":[{"metin":"En az üç ana departmanı doğru adlandırır.","puan":30},{"metin":"Her departmanın konuğa doğrudan hizmet veren bir birim olduğunu belirtir.","puan":30},{"metin":"İki departmanın birbirine bilgi vererek çalıştığını somut bir örnekle açıklar.","puan":40}],"ornek":"Ana departmanlar: ön büro, kat hizmetleri ve yiyecek içecek. Ön büro, hangi odanın boş ve temiz olduğunu kat hizmetlerinden öğrenir; kat hizmetleri temizlediği odayı ön büroya bildirir; böylece oda yeni konuğa verilebilir. Bu bilgi akışı konuğa kesintisiz hizmet sağlar.","ipucu":"Departman adlarını yazarken her birinin konuğa doğrudan hizmet verdiğini gösterin."},{"id":"os-3-y02","konu":"3.3","soru":"Bir otelde bir oda temizlenmiş, ancak kat şefi odayı “satışa hazır” olarak işaretlememiştir. Kat hizmetlerinde bir odanın satışa hazır sayılması için en az üç kontrolü açıklayınız ve kat şefinin bu kontrolü neden yaptığını belirtiniz. Kararın ön büro ile ilişkisini de yazınız.","olcut":[{"metin":"Odanın satışa hazır sayılması için en az üç kontrolü yazar.","puan":50},{"metin":"Kat şefinin bu kontrolü neden yaptığını açıklar.","puan":20},{"metin":"Kararın ön büro ile ilişkisini (satış, rezervasyon, konuk girişi) açıklar.","puan":30}],"ornek":"Kontroller: yatağın temiz ve düzgün serilmiş olması, banyonun temizliği, aynanın ve yatağın kontrolü, eksik malzemenin tamamlanması. Kat şefi bu kontrolü, konuğa kusursuz bir oda sunulması için yapar. Oda ön büro sisteminde hazır olarak görünmeden ön büro bu odaya konuk yerleştiremez; bu yüzden kat şefinin onayı satış ve giriş işlemlerini belirler.","ipucu":"Kontrolleri sayarken odanın görünen ve görünmeyen yönlerini (banyo, teknik donanım) düşünün."}],"sorular":[{"id":"os-3-s01","tur":"coktan-secmeli","soru":"Sırt çantasıyla gezen, uygun fiyat ve ortak yaşam alanı arayan genç bir gezgin için hangi tesis en uygundur?","secenekler":["Butik otel","Tatil köyü","Hostel","Motel"],"dogru":2,"aciklama":"Hostelin gücü uygun fiyat ve ortak yaşam alanlarıdır; gençlik turizmine uygundur. Butik otel kişiye özel ve yüksek standartlı hizmet verdiği için daha pahalıdır, motel ise araçla yolculuk edenlere yöneliktir."},{"id":"os-3-s02","tur":"coktan-secmeli","soru":"Gece 01.00’de Bolu Dağı yolunda uykusu gelen bir sürücü, ana yoldan çıkmadan odasının önüne aracını park edip sabah yola devam edecek. Hangi tesisi seçer?","secenekler":["Motel","Oberj","Kamping","Apart otel"],"dogru":0,"aciklama":"Motel, kara yolu güzergâhında kurulur ve araçla yolculuk edenin konaklama, yeme içme ve park ihtiyacını karşılar. Oberj dağ ve spor yolculukları, kamping doğa içinde çadır ya da karavan konaklaması içindir."},{"id":"os-3-s03","tur":"coktan-secmeli","soru":"Stajının ilk gününde “Bu konuyu kime sormalıyım, izni kimden almalıyım?” sorusunun cevabını hangi belgede ararsın?","secenekler":["Vardiya çizelgesinde","Özlük dosyasında","Oda durum çizelgesinde","Organizasyon şemasında"],"dogru":3,"aciklama":"Organizasyon şeması görevleri ve kimin kime bağlı olduğunu gösterir. Vardiya çizelgesi yalnız kimin hangi gün çalışacağını, oda durum çizelgesi odaların durumunu gösterir; amiri bunlardan öğrenemezsin."},{"id":"os-3-s04","tur":"dogru-yanlis","soru":"Konaklama işletmesinin türü ve büyüklüğü değişse de organizasyon yapısı her işletmede aynı kalır.","secenekler":["Doğru","Yanlış"],"dogru":1,"aciklama":"Tesisin türü, konuk profili, hizmetleri ve çalışan sayısı yapıyı belirler. Pansiyonda sahip birçok işi birlikte yürütürken büyük otelde ayrı müdürleri olan departmanlar bulunur."},{"id":"os-3-s05","tur":"coktan-secmeli","soru":"Boş kalan oda ertesi güne saklanamaz. Bu yüzden fuarlara katılarak acentelerle anlaşma yapan ve doluluğu artırmaya çalışan destek departmanı hangisidir?","secenekler":["Satın alma","Satış ve pazarlama","Bilgi işlem","Güvenlik"],"dogru":1,"aciklama":"Satış ve pazarlama pazar araştırması, tanıtım ve kurumsal satışla otele konuk kazandırır. Satın alma malzeme tedarik eder, bilgi işlem otomasyon sistemini yönetir, güvenlik ise tesisin ve konukların güvenliğini gözetir."},{"id":"os-3-s06","tur":"coktan-secmeli","soru":"Ön büro neden otelin “sinir merkezi” sayılır?","secenekler":["Bilgiyi ilgili bölüme iletip sonucunu da izlediği için","Odaları temizleyip satışa hazır hâle getirdiği için","Otelin bütün parasal hareketlerini kaydettiği için","Personelin işe alımını ve eğitimini yürüttüğü için"],"dogru":0,"aciklama":"Ön büro bütün bölümleri birbirine bağlar: bilgiyi iletir ve sonucunu izler. Odaları hazırlamak kat hizmetlerinin, parasal kayıtlar muhasebenin, işe alım insan kaynaklarının işidir."},{"id":"os-3-s07","tur":"coktan-secmeli","soru":"Akşam 20.00’de balık restoranında konuk menüden çorba ile levrek seçiyor; hesabına yalnız bu iki yemeğin fiyatı yazılıyor. Hangi menü türü uygulanmaktadır?","secenekler":["Tabldot","Açık büfe","Ziyafet menüsü","Alakart"],"dogru":3,"aciklama":"Alakartta her yemek ayrı fiyatlıdır ve konuk dilediğini seçer. Tabldotta yemekler önceden belirlenmiş, fiyat tektir; açık büfede konuk yemeği tezgâhtan kendisi alır."},{"id":"os-3-s08","tur":"coktan-secmeli","soru":"Bonfileler akşam servisi için eşit ağırlıkta dilimlenip terbiyelenecek, ama henüz pişirilmeyecek. Bu ön hazırlık mutfağın hangi bölümünde yapılır?","secenekler":["Sıcak kısım","Kasaphane","Soğuk kısım","Aperitif ve garnitür bölümü"],"dogru":1,"aciklama":"Kasaphane et, tavuk ve balığı pişirmeden önce ayıklar, porsiyonlar ve marine eder. Sıcak kısım pişirme işini yapar, soğuk kısım ise meze ve salata hazırlar."},{"id":"os-3-s09","tur":"coktan-secmeli","soru":"Cumartesi akşamı balo salonunda iki yüz kişilik bir düğün yemeği verilecek. Servis hangi bölümün sorumluluğundadır?","secenekler":["Oda servisinin","Lobi barın","Ziyafet (banket) bölümünün","Alakart restoranın"],"dogru":2,"aciklama":"Ziyafet bölümü düğün, nişan ve toplantı gibi kalabalık organizasyonların yiyecek içecek hizmetini yürütür. Oda servisi tek tek odalara sipariş götürür; restoran ve bar günlük satış noktalarıdır."},{"id":"os-3-s10","tur":"dogru-yanlis","soru":"Otellerde oda satışından sonra en büyük gelir genellikle yiyecek içecek departmanından elde edilir.","secenekler":["Doğru","Yanlış"],"dogru":0,"aciklama":"Malzemenin alınmasından servise kadar bütün zincir yiyecek içecek departmanındadır ve oda gelirinden sonra en büyük gelir genellikle buradan gelir."},{"id":"os-3-s11","tur":"coktan-secmeli","soru":"Bir seyahat acentesi yaz boyunca gönderdiği grupların ücretini ay sonunda toplu ödemek istiyor. Acentenin vadesini ve limitini hangi muhasebe bölümü belirler?","secenekler":["Genel kasa bölümü","Depo ve ambar bölümü","Maliyet ve gelirler bölümü","Krediler bölümü"],"dogru":3,"aciklama":"Krediler bölümü kime, ne kadar ve ne süreyle vade tanınacağına bakar ve alacağı izler. Genel kasa nakit akışını, maliyet ve gelirler bölümü ise hasılatı ve giderleri izler."},{"id":"os-3-s12","tur":"coktan-secmeli","soru":"Mal kabul kapısında bir görevli sebze kasalarını sayıp tartıyor, faturayla karşılaştırıyor ve ezik domates kasasını kabul etmiyor. Hangi muhasebe bölümünde çalışıyor?","secenekler":["Krediler bölümünde","Depo ve ambar bölümünde","Genel kasa bölümünde","Maliyet ve gelirler bölümünde"],"dogru":1,"aciklama":"Depo ve ambar bölümü gelen malı faturaya ve şartnameye uygunluk açısından teslim alırken kontrol eder. Krediler vadeli satışları, genel kasa nakdi, maliyet ve gelirler hasılatı izler."},{"id":"os-3-s13","tur":"coktan-secmeli","soru":"Stajının ilk günü otel sana gezdirilip personel girişi ve soyunma odası gösterildi, amirinle ve ekibinle tanıştırıldın. Bu sürecin adı nedir?","secenekler":["Mülakat","Terfi","Oryantasyon","Performans değerlendirmesi"],"dogru":2,"aciklama":"Oryantasyon, yeni personelin işletmeye, işine ve ekibine alışması için yapılan uyum sürecidir. Mülakat işe alımdaki görüşmedir, terfi yükselmedir."},{"id":"os-3-s14","tur":"coktan-secmeli","soru":"Kat hizmetleri, 318 numaralı odanın kliması su damlattığı için odayı bildirdi. Arızayı gidermesi ve odanın yeniden satılabileceğini haber vermesi gereken departman hangisidir?","secenekler":["Teknik servis","Güvenlik","Bilgi işlem","Satın alma"],"dogru":0,"aciklama":"Arızaları gidermek ve bakım yapmak teknik servisin işidir; arızalı oda satılamaz. Bilgi işlem otomasyon sistemini yönetir, satın alma ise malzeme tedarik eder."},{"id":"os-3-s15","tur":"senaryo","durum":"Saat 11.15. Kat hizmetlerinde staj yapıyorsun ve bir kat görevlisine yardım ediyorsun. Temizlediğiniz odada klimanın halıya su damlattığını fark ediyorsun. Konuk dışarıda, görevli banyoyla meşgul.","soru":"İlk adımın ne olur?","secenekler":["Damlayan yerin altına havlu serer, konuk dönünce kendisine söylersin.","Görevliyi ve kat şefini bilgilendirip arızayı teknik servise ilettirirsin.","Odanın temizliğini bitirir, işin sonunda arızayı görevliye anlatırsın.","Klimanın kapağını açıp suyun nereden damladığına bakarsın."],"dogru":1,"aciklama":"Arızayı ilk gören çoğu zaman kat hizmetleridir ve hemen bildirir; teknik servis giderince oda yeniden satılabilir. Havlu geçici çözümdür, kapağı açmak ise teknik servisin işidir."},{"id":"os-3-s16","tur":"senaryo","durum":"Akşam 20.10, açık büfe restoranında servise yardım ediyorsun. Büfe çok kalabalık. Pilav tepsisindeki servis kaşığı elinden yere düşüyor; arkanda konuklar sıra bekliyor.","soru":"Ne yaparsın?","secenekler":["Kaşığı peçeteyle iyice silip tepsiye geri koyarsın.","Kaşığı çeşmede yıkayıp hemen tepsiye geri koyarsın.","Kaşığı bulaşıkhaneye gönderir, tepsiye temiz bir kaşık koyarsın.","Kaşığı yerde bırakıp konukların başka bir gereç almasını beklersin."],"dogru":2,"aciklama":"Yere düşen ya da kirlenen her gereç doğrudan bulaşıkhaneye gönderilir; silinip ya da çabucak yıkanıp yeniden kullanılmaz. Gıda güvenliği hızdan önce gelir."},{"id":"os-3-s17","tur":"senaryo","durum":"Gece 22.40, resepsiyonda stajyersin; şefin yanındaki konukla ilgileniyor. Telefonu açıyorsun: 412 numaralı odadaki konuk odasına çorba ve tost istediğini söylüyor.","soru":"Ne yaparsın?","secenekler":["İsteği ve oda numarasını yazıp oda servisine iletir, ücreti hesaba işletirsin.","Oda servisinin numarasını verip konuğun kendisinin aramasını rica edersin.","Siparişi doğrudan mutfağa iletir, tepsiyi de odaya kendin çıkarırsın.","Şefinin işi bitene kadar konuğu telefonda bekletip ona devredersin."],"dogru":0,"aciklama":"Ön büro konuğun isteğini ilgili birime iletir. Oda servisi ek ücretli bir hizmettir; ücret konuğun hesabına işlenmezse otel para kaybeder."},{"id":"os-3-s18","tur":"senaryo","durum":"Sabah 07.40, mal kabul kapısında depo görevlisine yardım ediyorsun. Görevli içeride telefonda. Gelen araçtan on kasa domates iniyor, faturada on iki kasa yazıyor. Şoför acelesi olduğunu söyleyip teslim belgesini imzalamanı istiyor.","soru":"Ne yaparsın?","secenekler":["Şoförü bekletmemek için belgeyi imzalar, eksiği sonra söylersin.","Faturaya güvenip on iki kasa teslim alınmış sayar, belgeyi imzalarsın.","Eksik kasaları kendin şoföre iade eder, depo görevlisine haber vermezsin.","İmzalamaz, farkı hemen depo görevlisine bildirirsin."],"dogru":3,"aciklama":"Depo ve ambar bölümü malı faturaya uygun mu diye teslim alırken kontrol eder. Eksiği imzadan sonra söylemek kaybın otele yazılması demektir; karar yetkisi depo görevlisindedir."},{"id":"os-3-s19","tur":"senaryo","durum":"Saat 14.30, personel girişinden otele dönüyorsun. Tanımadığın, kimlik kartı takmamış bir kişi “Teknik servisten çağırdılar, kapıyı tutar mısın?” diyerek arkandan içeri girmek istiyor.","soru":"Ne yaparsın?","secenekler":["Kibarlık olsun diye kapıyı tutar, içeri girmesine izin verirsin.","Adını ve bölümünü sorar, söyledikleri tutarlıysa içeri alırsın.","Kibarca güvenlik noktasına yönlendirir, güvenliğe de haber verirsin.","Arkasından gidip nereye gittiğini kendin izlersin."],"dogru":2,"aciklama":"Şüpheli bir kişiyle karşılaşan personel kendisi müdahale etmez; güvenliğe ve amirine bildirir. Kimliksiz birine kapı tutmak herkesin güvenliğini tehlikeye atar."},{"id":"os-3-s20","tur":"coktan-secmeli","soru":"Ayşe Hanım pazartesi telefonla oda ayırttı. Cuma günü otele gelip kaydını yaptırıyor. Konuk döngüsünün hangi evresindedir?","secenekler":["Varış","Varış öncesi","Konaklama","Ayrılış"],"dogru":0,"aciklama":"Karşılama ve kayıt işlemleri varış evresindedir; oda ayırtmak varış öncesinde yapılmıştı. Konaklama evresi odaya yerleşip kalmayı, ayrılış ise hesabın kapatılmasını kapsar."},{"id":"os-3-s21","tur":"coktan-secmeli","soru":"Aşağıdakilerden hangisi konuğun görmediği bir arka büro işlemidir?","secenekler":["Yeni gelen konuğun kaydını yapmak","Konuğun avrosunu ilan edilen kurdan bozmak","Konuğa müzenin yolunu haritada göstermek","Gelecek ayın vardiya çizelgesini hazırlamak"],"dogru":3,"aciklama":"Vardiya planlamak, rezervasyonları işlemek ve rapor hazırlamak banko arkasında yapılan arka büro işleridir. Kayıt, döviz bozma ve bilgi verme konuğun gözü önünde yapılan görülebilen işlemlerdir."},{"id":"os-3-s22","tur":"dogru-yanlis","soru":"Rezervasyonu olduğu hâlde iptal etmeden ve haber vermeden tesise gelmeyen konuğa walk-in denir.","secenekler":["Doğru","Yanlış"],"dogru":1,"aciklama":"Bu konuk no-show’dur. Walk-in, önceden rezervasyon yaptırmadan doğrudan gelip oda isteyen konuktur."},{"id":"os-3-s23","tur":"coktan-secmeli","soru":"Küçük ölçekli bir butik otelde ön büro için hangisi doğrudur?","secenekler":["Her görev için ayrı bir birim sorumlusu bulunur.","Resepsiyon, santral ve bazen bagaj görevleri tek kişide toplanır.","Odalar bölümü müdürü ön büro müdürünün üstünde yer alır.","Gece denetimi ayrı bir birim olarak çalışır."],"dogru":1,"aciklama":"Küçük tesiste ayrı birimler yoktur; çok yönlü personel birkaç görevi birlikte yürütür. Müdür basamakları ve ayrı birimler büyük ölçekli otelin özelliğidir."},{"id":"os-3-s24","tur":"coktan-secmeli","soru":"Sabah 06.30’da 214 numaralı odayı arayıp “Günaydın, uyandırma servisiniz” diyen görevli ön büronun hangi biriminde çalışıyor?","secenekler":["Santral","Concierge","Bell desk","Rezervasyon birimi"],"dogru":0,"aciklama":"Telefon trafiğini yönetmek, mesaj iletmek ve uyandırma hizmeti vermek santralin işidir. Concierge konuğa bilgi ve özel istek konusunda yardım eder, bell desk bagajla ilgilenir."},{"id":"os-3-s25","tur":"coktan-secmeli","soru":"Bellboy valizleri araçtan alıp konuğa odasına kadar eşlik ediyor, klimanın nasıl çalıştığını da gösteriyor. Bu hizmet ön büronun hangi birimine aittir?","secenekler":["Concierge","Resepsiyon","Ön kasa","Bell desk"],"dogru":3,"aciklama":"Bell desk bagaj taşıma, konuğu odasına yerleştirme ve bilgilendirme işlerini yürütür. Concierge şehir turu ve bilet gibi özel isteklerde yol gösterir; resepsiyon kayıt işlemlerini yapar."},{"id":"os-3-s26","tur":"coktan-secmeli","soru":"Aşağıdakilerden hangisi ön büro personelinde aranan bilişsel ve teknik becerilerdendir?","secenekler":["Sır saklayabilmek","En az bir yabancı dili iyi konuşmak","Temiz ve ütülü üniforma giymek","Sabırlı ve güler yüzlü olmak"],"dogru":1,"aciklama":"Yabancı dil ve otel programlarını kullanmak okulda, stajda ve işte kazanılan teknik becerilerdir. Sır saklamak ve sabır kişisel özellik, üniforma ise dış görünüştür."},{"id":"os-3-s27","tur":"coktan-secmeli","soru":"Gece 02.00’de lobi sessizken geç gelen bir konuğun girişini yapan ve aynı anda gün içindeki hesap kayıtlarını tek tek kontrol eden yönetici kimdir?","secenekler":["Resepsiyon şefi","Rezervasyon şefi","Gece müdürü","Danışma şefi"],"dogru":2,"aciklama":"Gece müdürü gece vardiyasında tesisin bütün sorumluluğunu üstlenir ve günün hesaplarını denetleyip kapatır. Öteki şefler gündüz vardiyasında kendi birimlerini yönetir."},{"id":"os-3-s28","tur":"dogru-yanlis","soru":"Bellboy, kapı görevlisi ve vale, danışma şefinin yönettiği üniformalı hizmetler ekibinde yer alır.","secenekler":["Doğru","Yanlış"],"dogru":0,"aciklama":"Kitaba göre danışma şefi konukların özel isteklerini karşılar ve bu üniformalı ekibi yönetir."},{"id":"os-3-s29","tur":"coktan-secmeli","soru":"Giriş sırasında konuk “Kartımdan şimdi para mı çekiyorsunuz?” diye soruyor. Ön provizyonu doğru anlatan cevap hangisidir?","secenekler":["Tutar hemen karttan çekilir, çıkışta fazlası konuğa iade edilir.","Yalnız kartın geçerli olup olmadığına bakılır, hiçbir tutar ayrılmaz.","Tutar, odanın ücretinin ön ödemesi olarak karttan tahsil edilir.","Tutar çekilmez, geçici olarak ayrılır; çıkışta gerçek hesaba göre işlem yapılır."],"dogru":3,"aciklama":"Provizyon tahsilat değildir: tutar yalnız ayrılır. Konuğa önceden açıklanmazsa telefonuna gelen bildirim “benden habersiz para çekildi” şikâyetine dönüşür."},{"id":"os-3-s30","tur":"coktan-secmeli","soru":"Bilgisayarı olmayan küçük bir pansiyonda görevli yeni gelen konuğa 3 numaralı odanın temiz ve boş olduğunu bir bakışta nereden görür?","secenekler":["Anahtar ve mesaj panosundan","Oda durum panosundan","Folyo havuzundan","Oda fiyatları panosundan"],"dogru":1,"aciklama":"Oda durum panosu odaların boş, dolu, kirli ya da temiz olduğunu gösterir; satılacak oda hem boş hem temiz olmalıdır. Anahtar ve mesaj panosu anahtar ile notları, folyo havuzu belgeleri tutar."},{"id":"os-3-s31","tur":"coktan-secmeli","soru":"Girişte konuk, bilgilerini kontrol ettikten sonra tesisin kurallarını ve kişisel verilerinin işlenmesini kabul ettiğini ıslak imzasıyla onaylıyor. Bu belge hangisidir?","secenekler":["Rezervasyon formu","Teyit mektubu","Konaklama belgesi","Konuk tarihçe kartı"],"dogru":2,"aciklama":"Konaklama belgesi imzalı olduğu için yasal açıdan en kritik ön büro belgesidir. Rezervasyon formu konuk gelmeden doldurulur, teyit mektubu ise rezervasyonu onaylayan yazıdır."},{"id":"os-3-s32","tur":"coktan-secmeli","soru":"Konuk kapıda “Bana deniz manzaralı oda söylenmişti” diyerek tartışıyor. Rezervasyondan sonra konuğa gönderilen ve oda tipi, fiyat, iptal şartlarını onaylayan hangi belgeye bakılır?","secenekler":["Teyit mektubuna","Rezervasyon formuna","VIP bildirim formuna","Konaklama belgesine"],"dogru":0,"aciklama":"Teyit mektubu tesisin rezervasyonu kabul ettiğini ve ayrıntıları onayladığını konuğa bildirir. Rezervasyon formu talebin ön büroda kayda geçirildiği belgedir; konaklama belgesi ise girişte imzalanır."},{"id":"os-3-s33","tur":"dogru-yanlis","soru":"Konuk hesabına yanlışlıkla işlenen bir tutar, kayıt sistemden silinerek düzeltilir.","secenekler":["Doğru","Yanlış"],"dogru":1,"aciklama":"Yanlış kayıt silinmez; eksi tutarlı bir düzeltme fişiyle hesap dengelenir. Böylece kimin neyi neden düzelttiği görünür kalır."},{"id":"os-3-s34","tur":"coktan-secmeli","soru":"Konuğun isteğiyle çiçekçiye kasadan nakit ödeme yapıldı ve tutar konuğun hesabına borç yazıldı. Bu işlem için hangi belge düzenlenir?","secenekler":["Düzeltme fişi","Ödeme fişi","Fatura","Minibar kontrol formu"],"dogru":1,"aciklama":"Ödeme fişi (paid-out) konuk adına dışarıya yapılan nakit ödemeler için düzenlenir. Düzeltme fişi yanlış işlenmiş tutarı düzeltir, fatura ise ayrılışta hizmet bedelini belgeler."},{"id":"os-3-s35","tur":"coktan-secmeli","soru":"Konuk ikinci kez geliyor. Görevli kayıtta “sessiz oda, asansöre uzak” notunu görüp konuğa sormadan öyle bir oda ayırıyor. Bu notlar hangi kayıttan geliyor?","secenekler":["Anket formundan","VIP bildirim formundan","Konuk tarihçe kartından","Folyodan"],"dogru":2,"aciklama":"Konuk tarihçe kartı geçmiş konaklamalardaki tercihleri ve özel istekleri tutar. Folyo yalnız harcamaları gösterir; anket konuğun değerlendirmesini alır."},{"id":"os-3-s36","tur":"coktan-secmeli","soru":"Çıkış yapan konuk duşun suyunun ılık aktığını söyledi. Görevli arızayı teknik servise bildirdi ve onarım bitene kadar odaya yeni konuk yerleştirmiyor. Bunun nedeni nedir?","secenekler":["Bildirilmeyen arıza sonraki konuğa kalır ve arızalı oda satılamaz.","Teknik servis yalnızca boş ve temiz odalarda çalışabilir.","Arıza bedeli çıkış yapan konuğun hesabından düşülecektir.","Odanın temizliği arıza giderilmeden tamamlanamayacağı için bekler."],"dogru":0,"aciklama":"Ön büro arızayı bildirip sonucunu izleyerek hem satışa hazır oda sayısını hem de konuğun konforunu korur. Konuğa yanlış bir oda vermek, sorunu başkasına devretmek demektir."},{"id":"os-3-s37","tur":"dogru-yanlis","soru":"Double odada tek büyük yatak, twin odada ise tek kişilik iki ayrı yatak bulunur.","secenekler":["Doğru","Yanlış"],"dogru":0,"aciklama":"İkisi de iki kişiliktir; fark yatak düzenindedir. Rezervasyonda yatak düzenini sormamak girişte oda değiştirmeye yol açabilir."},{"id":"os-3-s38","tur":"coktan-secmeli","soru":"İki çocuklu bir aile, çocuklar yandaki odada kalsın ama kimse koridora çıkmadan odalar arasında geçebilsin istiyor. Hangi oda tipini ayırırsın?","secenekler":["Quadruple oda","Triple oda","Junior suite","Bağlantılı oda"],"dogru":3,"aciklama":"Bağlantılı odalar aralarındaki içeriden açılabilen kapıyla birbirine bağlı iki ayrı odadır. Quadruple ve triple tek odadır; junior suite ise oturma bölümü olan tek bir geniş alandır."},{"id":"os-3-s39","tur":"senaryo","durum":"Akşam vardiyasında resepsiyondasın. Telefondaki kişi otelde kalan bir konuğun arkadaşı olduğunu söylüyor ve onun hangi odada kaldığını soruyor. Acelesi olduğunu, sürpriz yapacağını da ekliyor.","soru":"Ne yaparsın?","secenekler":["Arayanın adını sorar, adı uyuyorsa oda numarasını verirsin.","Oda numarasını söylemez ama katını söylersin.","Oda numarasını vermez, adını ve mesajını alıp konuğa iletmeyi önerirsin.","Konuğun kimlik bilgilerini doğrulayamayacağını söyleyip telefonu kapatırsın."],"dogru":2,"aciklama":"Konuk bilgisi (oda numarası dâhil) yetkisiz kişiyle paylaşılmaz; bu KVKK gereği yasal sorumluluktur. Mesajı iletmek hem konuğu korur hem arayana yardım eder."},{"id":"os-3-s40","tur":"senaryo","durum":"Sabah vardiyasındasın. Çıkış yapan konuk hesabında minibar harcamasının iki kez yazıldığını söylüyor; ekranda bunun doğru olduğunu sen de görüyorsun. Arkasında iki konuk daha bekliyor.","soru":"Ne yaparsın?","secenekler":["Özür diler, amirinin onayıyla düzeltme fişi düzenlersin.","Fazla yazılan kaydı sistemden silip hesabı hemen kapatırsın.","Tutarı tahsil edip farkı sonradan iade edeceğimizi söylersin.","Farkı kendi cebinden ödeyip konuyu kapatırsın."],"dogru":0,"aciklama":"Yanlış kayıt silinmez; eksi tutarlı düzeltme fişiyle dengelenir ve amir onaylar. Böylece kimin neyi neden düzelttiği görünür kalır."},{"id":"os-3-s41","tur":"senaryo","durum":"Gece 23.00, resepsiyondasın. Elinde teyit mektubu olan bir konuk geliyor, ama sistemde bütün odalar dolu görünüyor. Konuk yorgun ve bankoda bekliyor.","soru":"İlk adımın ne olur?","secenekler":["Rezervasyonunun geçersiz olduğunu söyleyip başka otel aramasını istersin.","Yakındaki otellere telefon edip kendin yer bulmaya çalışırsın.","Temizliği bitmemiş bir odanın kartını verip konuğu odaya yollarsın.","Özür diler, konuğu oturtur ve hemen amirine haber verirsin."],"dogru":3,"aciklama":"Fazla rezervasyon durumunu konuğa açıklamak ve çözümü sunmak yetkilinin işidir; stajyer konuğu bekletmeden amirine haber verir. Rezervasyonu geçersiz saymak ya da hazır olmayan odaya göndermek konuğu mağdur eder."},{"id":"os-3-s42","tur":"senaryo","durum":"Öğleden sonra bankodasın. Tanımadığın biri gelip “Kartımı odada unuttum, 316’ya yeni kart yapar mısınız?” diyor. Yanında kimliği yok ve acele ettiğini söylüyor.","soru":"Ne yaparsın?","secenekler":["Bekletmemek için 316’nın kartını hemen programlarsın.","Kart yapmaz, nazikçe bekletip durumu amirine bildirirsin.","Adını sorar, kayıtla uyuşuyorsa kartı yaparsın.","Bir bellboy çağırıp odayı ona açtırırsın."],"dogru":1,"aciklama":"Kartı isteyen kişinin o odanın konuğu olduğundan emin olunmadan kart yapılmaz. Yalnızca ad söylemesi kimliği kanıtlamaz; karar amirdedir."},{"id":"os-3-s43","tur":"senaryo","durum":"Giriş yapan çift kara manzaralı oda ayırtmış. Deniz manzaralı bir odanın boş olduğunu görüyorsun ve fark ödeyerek geçebileceklerini söylüyorsun; konuk “Hayır, teşekkürler” diyor.","soru":"Ne yaparsın?","secenekler":["Teşekkür eder, ayırttıkları odayı güler yüzle teslim edersin.","Kara manzaralı odanın pek iyi olmadığını söyleyip teklifi yenilersin.","Amirine sormadan çifti ücretsiz üst odaya alırsın.","Kendi kararınla indirim yapıp teklifi bir kez daha yinelersin."],"dogru":0,"aciklama":"Upselling dürüstçe yapılır ve ısrar edilmez; konuk “hayır” derse ayırttığı oda aynı güler yüzle verilir. Ücretsiz üst oda ise upgrade’dir ve amirin yetkisindedir."},{"id":"os-3-s44","tur":"senaryo","durum":"Gece vardiyasında santralde stajyersin. 207 numaralı odadan arayan konuk eşinin fenalaştığını ve nefes almakta zorlandığını söylüyor.","soru":"İlk adımın ne olur?","secenekler":["Odaya kendin çıkar, elinden gelen müdahaleyi yaparsın.","Sabah ilk iş bir doktora haber vereceğini söylersin.","En yakın nöbetçi eczanenin yerini tarif edersin.","112’yi arar, gece müdürüne hemen haber verirsin."],"dogru":3,"aciklama":"Sağlık sorununda önce can güvenliği gelir: 112 aranır ve amire haber verilir. Santral acil durumlarda haberleşmeyi yönetir; eğitimsiz müdahale ya da oyalamak zaman kaybettirir."},{"id":"os-3-s45","tur":"coktan-secmeli","soru":"Küçük ve orta büyüklükteki bir tesiste kat hizmetleri müdürü kime karşı sorumludur?","secenekler":["Odalar müdürüne","Genel müdüre","Ön büro müdürüne","Satın alma müdürüne"],"dogru":1,"aciklama":"Odalar müdürü basamağı büyük tesislerde bulunur; orada kat hizmetleri müdürü odalar müdürüne karşı sorumludur. Küçük ve orta tesiste bu basamak olmadığı için genel müdüre bağlıdır."},{"id":"os-3-s46","tur":"coktan-secmeli","soru":"Odadaki çekmecenin açılmadığını, eşyaya dokunulmadığını bilen konuk otele güvenir. Kat hizmetlerinin hangi biriminin öne çıkan değeri mahremiyettir?","secenekler":["Genel alanlar birimi","Çamaşırhane ve depolar birimi","Odalar birimi","Kat hizmetleri ofisi"],"dogru":2,"aciklama":"Oda konuğun otel içindeki özel alanı olduğu için odalar biriminde mahremiyet öne çıkar. Genel alanlarda estetik, çamaşırhanede sürdürülebilirlik, ofiste dürüstlük ve sorumluluk öne çıkar."},{"id":"os-3-s47","tur":"coktan-secmeli","soru":"Oda görevlisi 305 numaralı odanın temizliğini bitirdi. Odayı yerinde denetleyip “satışa hazır” onayını vermesi gereken kişi kimdir?","secenekler":["Malzeme taşıyıcı","Meydancı","Oda görevlisinin kendisi","Kat şefi"],"dogru":3,"aciklama":"Onay vermeden oda konuğa verilmez; bu denetim kat şefinin işidir. Malzeme taşıyıcı ve meydancı oda temizliği sonucunu onaylamaz."},{"id":"os-3-s48","tur":"coktan-secmeli","soru":"Kat ofisleri ile çamaşırhane arasında tekstil taşımayı asıl işi olarak yapan, ana depodan katlara temizlik malzemesi ulaştıran ve perdeleri indirip takan görevli kimdir?","secenekler":["Meydancı","Malzeme taşıyıcı","Havuzcu","Ütücü"],"dogru":1,"aciklama":"Malzeme taşıyıcı (porter) tekstil ve malzeme taşıma ile ağır işleri üstlenir. Meydancı genel alanları temizler, havuzcu havuz çevresiyle ilgilenir, ütücü tekstili ütüler."},{"id":"os-3-s49","tur":"dogru-yanlis","soru":"Küçük ölçekli konaklama tesislerinde çamaşırhane hizmeti çoğu zaman dışarıdan alınır.","secenekler":["Doğru","Yanlış"],"dogru":0,"aciklama":"Az kişiyle çalışan küçük tesislerde çarşaflar çoğu kez anlaşmalı bir çamaşırhaneye gönderilir."},{"id":"os-3-s50","tur":"coktan-secmeli","soru":"Çıkış yapmış odanın banyosunda klozeti ve lavaboyu ayrı bezlerle silecek görevli renk kodlama sistemine göre hangi bezleri kullanır?","secenekler":["Klozet için sarı, lavabo için kırmızı","Klozet için mavi, lavabo için kırmızı","Klozet için kırmızı, lavabo için sarı","Klozet için kırmızı, lavabo için mavi"],"dogru":2,"aciklama":"Kırmızı tuvalet ve yüksek riskli alanların, sarı lavabo ve banyo yüzeylerinin rengidir. Ders kitabında mavi genel toz alma ve mobilya için gösterilir; bu yüzden lavaboda kullanılmaz."},{"id":"os-3-s51","tur":"coktan-secmeli","soru":"Klozeti sildiğin bezi iyice durulayıp lavabo yüzeyinde kullanmak neden yanlıştır?","secenekler":["Durulansa bile mikrop bir yüzeyden ötekine taşınabilir.","Islak bez lavabo yüzeyinde leke ve iz bırakır.","Kırmızı bez lavabonun yüzeyini çizebilir.","Bez durulanırken gereğinden çok su harcanır."],"dogru":0,"aciklama":"Çapraz bulaşma gözle görülmez; yüzey temiz görünse de hijyenik olmayabilir. Renk kodlu bez bunu önlemek içindir."},{"id":"os-3-s52","tur":"dogru-yanlis","soru":"Çamaşır suyu ile kireç çözücü karıştırılırsa temizleme gücü artar, bu yüzden aynı kovada kullanılabilir.","secenekler":["Doğru","Yanlış"],"dogru":1,"aciklama":"Çamaşır suyu asitli ürünlerle karışınca zehirli gaz çıkarır. Ürünler asla birbirine karıştırılmaz."},{"id":"os-3-s53","tur":"coktan-secmeli","soru":"Vakum süpürge kullanımıyla ilgili aşağıdakilerden hangisi yanlıştır?","secenekler":["Kullanmadan önce kablo, fiş ve gövdeyi kontrol etmek","Fişi prizden kablosundan çekerek çıkarmak","Toz torbasını ve filtreyi düzenli temizlemek","Fişi başlığından tutarak prizden çıkarmak"],"dogru":1,"aciklama":"Kablodan çekmek kabloyu soyar ve elektrik çarpması riski doğurur; fiş başlığından tutulur. Kablo, fiş ve gövde kontrolü ile torba ve filtre temizliği doğru uygulamalardır."},{"id":"os-3-s54","tur":"coktan-secmeli","soru":"Görevli 206 numaralı odayı hazırladı ve kat şefi denetleyip onayladı. Çizelgede oda durum kodu hangisinden hangisine geçer?","secenekler":["VC’den VD’ye","OOO’dan VC’ye","VD’den VC’ye","OCC’den VD’ye"],"dogru":2,"aciklama":"VD, konuğu ayrılmış ama temizlenmemiş boş odadır; temizlenip denetlenince VC (boş temiz, satışa hazır) olur. Hız uğruna denetim atlanmaz."},{"id":"os-3-s55","tur":"coktan-secmeli","soru":"Sabah 09.30’da görevli 318 numaralı odada valizi yerinde, yatağı ise önceki gün yapıldığı gibi buluyor. Bu durumu kat şefine hangi kodla bildirir?","secenekler":["SO","DL","DND","C/O"],"dogru":0,"aciklama":"SO kayıtta dolu görünen ama yatağı hiç kullanılmamış odayı gösterir. DL odanın içeriden kilitli olduğunu, C/O ise konuğun çıkış yaptığını bildirir."},{"id":"os-3-s56","tur":"coktan-secmeli","soru":"Bulduğun yüzüğü forma “sarı renkli metal yüzük” diye yazıyorsun, “altın yüzük” yazmıyorsun. Bunun nedeni nedir?","secenekler":["Formda eşyanın cinsini yazmak için yeterli yer olmadığı için","Eşyanın değerini konuktan saklamak için","Sigorta bedelini düşük göstermek için","Değerini bilemediğin için yalnız görünen özellikleri yazarsın."],"dogru":3,"aciklama":"Tarafsız tanım, değeri hakkında hüküm vermemeyi sağlar. “Altın” yazılan yüzük kaplama çıkarsa kayıt da personel de şüphe altında kalır."},{"id":"os-3-s57","tur":"coktan-secmeli","soru":"Kat şefi 402 numaralı odada lavaboda bir saç teli görüyor, banyo hijyeni sütununu işaretliyor ve odayı görevliye geri veriyor. Hangi formu kullanıyor?","secenekler":["Oda durum çizelgesi","Arıza bildirim formu","Kat raporu","Minibar kontrol formu"],"dogru":2,"aciklama":"Kat raporu, şefin temizlenen her odayı madde madde denetleyip onayladığı günlük kontrol listesidir. Oda durum çizelgesi yalnız odanın durumunu gösterir."},{"id":"os-3-s58","tur":"dogru-yanlis","soru":"Teknik servis arızayı onardıktan sonra kat hizmetleri ya da ön büro arızanın giderildiğini doğrular ve oda yeniden satışa hazırlanır.","secenekler":["Doğru","Yanlış"],"dogru":0,"aciklama":"Onarım bitince arızanın giderildiği doğrulanır, oda temizlenip denetlenir ve ancak sonra yeniden satışa açılır."},{"id":"os-3-s59","tur":"coktan-secmeli","soru":"3x3 metodunu uygulayan oda görevlisi odaya girmeden önce ne yapar?","secenekler":["Kapıya üç kez vurup “Housekeeping” diye seslenir ve bunu toplam üç kez yineler.","Kapıya bir kez vurup üç saniye bekler, sonra odaya girer.","Kapıya üç kez vurur, cevap gelmezse bir tur daha yapıp girer.","Resepsiyondan odanın boş olduğunu öğrenir, sonra üç kez vurup girer."],"dogru":0,"aciklama":"3x3, oda boş olduğu bilinse bile her seferinde uygulanır. Konuk duşta, uykuda ya da telefonda olabilir; habersiz açılan kapı konuğun özel alanına izinsiz girmektir."},{"id":"os-3-s60","tur":"coktan-secmeli","soru":"Saat 11.00’de listendeki 204 numaralı odanın kapısında “Lütfen rahatsız etmeyin” kartı asılı. Ne yaparsın?","secenekler":["Kapıyı bir kez çalıp konuktan temizlik izni istersin.","Kartı kapıdan alıp resepsiyona teslim edersin.","Pas anahtarıyla içeri bakıp konuğun olup olmadığını kontrol edersin.","Kapıyı çalmaz, odayı listede işaretleyip kat şefine bildirirsin."],"dogru":3,"aciklama":"Kart girişin kesinlikle yasak olduğunu bildirir; ne yapılacağına oda görevlisi kendi başına karar vermez, kat şefi karar verir."},{"id":"os-3-s61","tur":"dogru-yanlis","soru":"Kayıp eşya takip defterinde yanlış yazılan bir giriş, okunmayacak biçimde karalanarak düzeltilir.","secenekler":["Doğru","Yanlış"],"dogru":1,"aciklama":"Deftere silinmez mürekkeple yazılır; yanlış girişin üstü tek çizgiyle çizilip paraflanır, karalama yapılmaz."},{"id":"os-3-s62","tur":"coktan-secmeli","soru":"Koridor zeminini temizlerken uyarı levhasını yerleştirdin. Islak mopa geçmeden hemen önce hangi adımı yaparsın?","secenekler":["Zemini kuru bezle kurularsın.","Kuru mopla tozu toplarsın.","Uyarı levhasını toplarsın.","Deterjanı doğrudan zemine dökersin."],"dogru":1,"aciklama":"Kuru temizlik atlanırsa toz ıslak mopun altında çamura döner, kum da zemini çizer. Levha zemin kuruyana kadar yerinde kalır."},{"id":"os-3-s63","tur":"coktan-secmeli","soru":"Yatak yapımıyla ilgili aşağıdakilerden hangisi yanlıştır?","secenekler":["Üstünde saç teli kalmış çarşafı hafifçe silkeleyip kullanmak","Alt çarşafın köşesini zarf köşe tekniğiyle sıkıştırmak","Çarşafın altına alez sererek yatağı korumak","Bel bükmeden dizleri kırarak çalışmak"],"dogru":0,"aciklama":"Üstünde saç, leke ya da yırtık olan çarşaf kullanılmaz. Zarf köşe çarşafı yerinde tutar, alez yatağı sıvıdan ve lekeden korur."},{"id":"os-3-s64","tur":"senaryo","durum":"Stajının ikinci haftasındasın; çıkış yapmış bir odanın banyosunda klozeti kırmızı bezle sildin. Odaya geçince çalışma masasının tozlu olduğunu fark ediyorsun. Elinde yalnız kırmızı bez var; temiz bezler koridordaki arabanda duruyor.","soru":"Ne yaparsın?","secenekler":["Kırmızı bezi sıcak suyla iyice durulayıp masayı onunla silersin.","Kırmızı bezin kullanılmamış yüzünü çevirip masayı öyle silersin.","Masa pek kirli görünmediği için silmeden odadan çıkarsın.","Arabandan toz bezini alıp masayı onunla silersin."],"dogru":3,"aciklama":"Tuvalette kullanılan bez durulansa bile başka yüzeye değmez; çapraz bulaşma gözle görülmez. Doğru bez birkaç adım ötededir, kısa yol hijyeni bozar."},{"id":"os-3-s65","tur":"senaryo","durum":"Saat 12.30; çıkış yapılmış 304 numaralı odada temizliğe başlamadan önce etrafa bakıyorsun. Komodinin çekmecesinde bir kol saati duruyor. Konuk bir saat önce otelden ayrılmış.","soru":"İlk adımın ne olur?","secenekler":["Saati kat arabana koyar, vardiya bitince resepsiyona teslim edersin.","Saati hemen kat şefine ulaştırır, kayda geçirilmesini sağlarsın.","Konuğun telefonunu otel kaydından bulup kendin aramaya çalışırsın.","Konuk nasılsa arar diye saati çekmecede bırakıp temizliğe geçersin."],"dogru":1,"aciklama":"Bulunan eşya fark edildiği anda şefe ulaştırılır ve forma kaydedilir; ders kitabına göre bulunduğu andan itibaren en geç 15 dakika içinde kayıt altına alınır. Bekletmek hem eşyayı hem seni riske atar."},{"id":"os-3-s66","tur":"senaryo","durum":"Genel tuvaleti temizliyorsun; klozetteki kireç lekesi çıkmıyor. Yanındaki arkadaşın “Kireç çözücünün üstüne biraz çamaşır suyu dök, anında açar” diyor. İki şişe de arabanda duruyor.","soru":"Ne yaparsın?","secenekler":["Pencereyi açıp iki ürünü az miktarda karıştırarak denersin.","Önce çamaşır suyunu döküp bekler, sonra kireç çözücüyü eklersin.","İki ürünü karıştırmaz, etiketi okur, gerekirse şefine sorarsın.","Maskeni takıp iki ürünü kovada karıştırır, fırçayla uygularsın."],"dogru":2,"aciklama":"Çamaşır suyu asitli ürünlerle (kireç çözücü) birleşince zehirli gaz çıkarır; az miktar ya da maske riski ortadan kaldırmaz. Etiket okunur, emin olunmayan noktada amire sorulur."},{"id":"os-3-s67","tur":"senaryo","durum":"Koridorda arabanla çalışırken iyi giyimli bir kişi yanına geliyor: “Kartımı odada unutmuşum, 415’i açıverir misiniz?” diyor. Acelesi olduğunu söylüyor ve kapının önünde bekliyor.","soru":"Hangisi doğru davranıştır?","secenekler":["Konuğu bekletmemek için pas anahtarınla kapıyı hemen açarsın.","Adını sorar, söylediği ad sana inandırıcı gelirse kapıyı açarsın.","Odada kimin kaldığını listenden okuyup ona söyler, sonra açarsın.","Kapıyı açmaz, kişiyi kibarca resepsiyona yönlendirirsin."],"dogru":3,"aciklama":"Pas anahtarı konukların eşyasına açılan kapıdır; kişinin o odanın konuğu olduğunu doğrulamak ön büronun işidir. Konuk bilgisi yetkisiz kişiyle paylaşılmaz."},{"id":"os-3-s68","tur":"senaryo","durum":"Listende 210 numaralı oda “boş temiz” görünüyor; son kontrol için kapıyı kuralına göre çalıp giriyorsun. İçeride açık bir valiz ve kullanılmış bir yatak var, odada kimse yok.","soru":"Ne yaparsın?","secenekler":["Listede boş yazdığı için valizi kat ofisine taşır, odayı baştan temizlersin.","Hiçbir şeye dokunmadan çıkar, durumu hemen kat şefine bildirirsin.","Bir yanlışlık olmuştur diye düşünüp kapıyı kapatır, işine devam edersin.","Valizin içine bakıp kime ait olduğunu bulmaya çalışırsın."],"dogru":1,"aciklama":"Kat hizmetleri ile ön büro kayıtlarının tutmaması oda durumu tutarsızlığıdır: boş sanılan dolu odaya yeni konuk gönderilebilir. Eşyaya dokunulmaz, gördüğün bildirilir."},{"id":"os-3-s69","tur":"senaryo","durum":"Akşam 17.00; lobi koridorunda bir konuğun içeceği dökülmüş, zemin ıslak. Paspas arabana gidip dönmen birkaç dakika sürecek ve koridordan sürekli konuk geçiyor. Hemen yanındaki dolapta bir uyarı levhası var.","soru":"İlk adımın ne olur?","secenekler":["Levhayı sonraya bırakıp hemen arabana koşar, dönünce ıslak yeri silersin.","Islak yerin üstüne birkaç kâğıt peçete bırakıp kendi işine devam edersin.","Levhayı ıslak yerin yanına koyar, sonra malzemeni alırsın.","Küçük bir ıslaklık olduğu için kendiliğinden kurumasını beklersin."],"dogru":2,"aciklama":"Dökülen sıvı görüldüğünde ilk iş uyarı levhasını koymaktır; malzeme gelene kadar levha konukları kaymaya karşı uyarır. Islak zeminde kayan konuk hem yaralanma hem sorumluluk demektir."},{"id":"os-3-s70","tur":"coktan-secmeli","soru":"Ders kitabında “etkinlik hizmetleri” adıyla geçen bölüme sektörde yaygın olarak ne denir?","secenekler":["Animasyon","Organizasyon","Operasyon","Rezervasyon"],"dogru":0,"aciklama":"Animasyon (canlandırma), konukların hoş vakit geçirmesi için düzenlenen oyun, spor ve gösteri etkinliklerine verilen addır. Unvanlarda hâlâ yaşar: animasyon şefi, animatör."},{"id":"os-3-s71","tur":"dogru-yanlis","soru":"Etkinliklere katılım gönüllüdür; animatör konuğu davet eder, ama katılmak istemeyen konuğa ısrar etmez.","secenekler":["Doğru","Yanlış"],"dogru":0,"aciklama":"Israrla oyuna çekilen konuk eğlenmez, rahatsız olur. “Hayır” diyen konuğa saygı da hizmetin parçasıdır."},{"id":"os-3-s72","tur":"coktan-secmeli","soru":"En iyi hazırlanmış gösteri bile haberi olmayan konuk gelmediği için boş salona oynayabilir. Etkinlikleri konuklara duyurmak ve memnuniyet geri bildirimlerini toplamak hangi birimin görevidir?","secenekler":["Teknik birim","Tanıtım birimi","Spor ve rekreasyon birimi","Sahne ve gece animasyonu birimi"],"dogru":1,"aciklama":"Tanıtım birimi etkinlikleri duyurur ve geri bildirim toplar. Teknik birim ses, ışık ve müziği yönetir; sahne birimi gösterileri sunar."},{"id":"os-3-s73","tur":"coktan-secmeli","soru":"Sabah 09.30 toplantısında günlük programı okuyup görev dağıtan, sahada konukların şikâyetlerini dinleyen ve günü etkinlik hizmetleri müdürüne raporlayan kişi kimdir?","secenekler":["Sahne yöneticisi","Oyun animatörü","Animasyon şefi","Koreograf"],"dogru":2,"aciklama":"Animasyon şefi müdüre bağlı çalışan ve programın sahada eksiksiz uygulanmasından sorumlu ekip lideridir. Sahne yöneticisi gösteri akışını, koreograf dans düzenini yönetir."},{"id":"os-3-s74","tur":"coktan-secmeli","soru":"Gösteriden bir saat önce kostümleri askıya dizen, sökükleri diken ve depodaki parçaların sayımını yapan görevli kimdir?","secenekler":["Kostüm sorumlusu","Sahne yöneticisi","Koreograf","Ses ve ışık yöneticisi"],"dogru":0,"aciklama":"Kostüm sorumlusu kıyafetlerin temiz, ütülü ve sağlam kalmasını sağlar ve depo sayımı yapar. Sahne yöneticisi akışı, koreograf dansı yönetir."},{"id":"os-3-s75","tur":"coktan-secmeli","soru":"Aşağıdakilerden hangisi etkinlik personelinin kişisel (karakter) özelliklerinden biridir?","secenekler":["Temiz ve ütülü üniforma giymek","En az bir yabancı dilde iletişim kurmak","Güçlü bir hafızaya sahip olmak","Sır saklayabilmek"],"dogru":3,"aciklama":"Animatör konuk hakkında çok şey öğrenir; duyduğunu taşımamak bir karakter özelliğidir. Üniforma dış görünüşe, yabancı dil ve hafıza bilişsel ve teknik becerilere girer."},{"id":"os-3-s76","tur":"dogru-yanlis","soru":"Çocuk kulübünde kayıt formunda adı yazılı olmayan ama “akrabasıyım” diyen bir kişiye çocuk teslim edilebilir.","secenekler":["Doğru","Yanlış"],"dogru":1,"aciklama":"Çocuk yalnız kayıt formunda veli ya da yetkili kişi olarak yazılı kişiye teslim edilir. Tanınmayan biri akrabayım dese bile animatör şefe ve veliye haber verir."},{"id":"os-3-s77","tur":"coktan-secmeli","soru":"Baba oğlunu çocuk kulübüne bırakırken oda numarasını, telefonunu ve çocuğun fıstık alerjisini bir forma yazıp imzalıyor. Bu hangi formdur?","secenekler":["Zimmet formu","Etkinlik malzeme talep formu","Aktivite katılım formu","Memnuniyet anketi"],"dogru":2,"aciklama":"Aktivite katılım formu çocuk kulübüne ya da riskli etkinliğe katılanın bilgilerini ve onayını alır; alerji gibi sağlık bilgisi de buradan öğrenilir."},{"id":"os-3-s78","tur":"coktan-secmeli","soru":"Sezon başında animatöre bir telsiz ve iki kostüm verilirken form imzalatılıyor. Zimmet formunun asıl amacı nedir?","secenekler":["Kaybolan ya da bozulan malzemede sorumluyu belli etmek","Etkinliğe katılan konukların izin vermesini sağlamak","Ekipman arızasını yazılı olarak teknik servise bildirmek","Etkinlik için gerekli sarf malzemesini depodan istemek"],"dogru":0,"aciklama":"Zimmet, bir malın imza karşılığı belirli bir kişiye teslim edilmesidir; böylece kayıpların izi sürülür ve personel kendisine ait olmayan bir kayıptan sorumlu tutulmaz."},{"id":"os-3-s79","tur":"coktan-secmeli","soru":"Gösterinin son bölümünde sahneye yürüyen şarkıcıyı adım adım izleyen güçlü ışığa ne denir?","secenekler":["Işık robotu","Dekor panosu","Ses mikseri","Takip spotu"],"dogru":3,"aciklama":"Takip spotu sahnedeki kişiyi izleyen güçlü ışıktır. Işık robotu yönü ve rengi uzaktan değiştirilen hareketli projektördür; mikser ise sesi dengeler."},{"id":"os-3-s80","tur":"coktan-secmeli","soru":"Pazartesi sabahı ön büro, o hafta otelde çok sayıda çocuklu aile olacağını etkinlik şefine bildiriyor. Bu paylaşım hangi bilgiye dayanır?","secenekler":["Odaların günlük temizlik ve bakım raporuna","Konukların yaş, milliyet ve ilgi alanı bilgisine","Ses ve ışık sistemlerinin bakım takvimine","Akşam büfesinde çıkacak yemeklerin listesine"],"dogru":1,"aciklama":"Ön büro konuk profilini paylaşır; böylece konuk kendine uygun etkinliğe yönlendirilir ve şef programa çocuk etkinlikleri ekler."},{"id":"os-3-s81","tur":"coktan-secmeli","soru":"Aşağıdaki hedef cümlelerinden hangisi “ölçülebilir” olma ölçütünü karşılar?","secenekler":["Giriş bekleme şikâyetlerini yarıya indirmek","Konukları hizmetimizden her zaman memnun etmek","Ön büro ekibini daha iyi çalıştırmak","Hizmet kalitesini sürekli artırmak"],"dogru":0,"aciklama":"SMART hedefte “M” (measurable) ulaşılıp ulaşılmadığının sayıyla anlaşılmasını ister. Diğer cümleler dilek düzeyinde kalır, ölçülemez."},{"id":"os-3-s82","tur":"dogru-yanlis","soru":"İş planı yalnız yatırımcılar için hazırlanan bir belgedir; departmanların günlük işleyişiyle ilgisi yoktur.","secenekler":["Doğru","Yanlış"],"dogru":1,"aciklama":"İş planı bütün departmanları aynı hedefte buluşturur ve her departman kendi iş akışına göre kendi planını yapar."},{"id":"os-3-s83","tur":"dogru-yanlis","soru":"Vardiya devrinde yarım kalan işler ve önemli bilgiler, işi devralan ekibe yazılı ve sözlü olarak aktarılır.","secenekler":["Doğru","Yanlış"],"dogru":0,"aciklama":"Deftere yazılmayan iş sonraki vardiya için hiç olmamış gibidir; konuk aynı isteği ikinci kez söylemek zorunda kalır."},{"id":"os-3-s84","tur":"coktan-secmeli","soru":"Sabah 08.00’de rezervasyon görevlisi günün listesini açıyor, garantisiz rezervasyonları arayıp gelip gelmeyeceklerini teyit ediyor. Fazla rezervasyon eylem planının hangi aşamasındadır?","secenekler":["Hazırlık","Konukla iletişim","Telafi ve takip","Önleme ve izleme"],"dogru":3,"aciklama":"Doluluğun her gün izlenmesi ve rezervasyonların garantili ve garantisiz diye ayrılması ilk aşamadır; sorun ne kadar erken görülürse çözmek o kadar kolaydır."},{"id":"os-3-s85","tur":"coktan-secmeli","soru":"Fazla rezervasyon planında benzer kalitedeki otellerle önceden anlaşma neden hazırlık aşamasında yapılır?","secenekler":["Konuğa indirim tanımlamak için önceden bütçe ayırmak gerekir.","Gece yarısı oda aramak zor ve pahalıdır; konuk düşük kaliteye gönderilmemeli.","Anlaşmalı otel, rezervasyon sayısını önceden azaltmak zorundadır.","Konuğun şikâyeti ancak anlaşmalı otelde çözülebilir hâle gelir."],"dogru":1,"aciklama":"Anlaşma önceden yapılmamışsa kriz anında çözüm bulunamayabilir. Hazırlık, durumu konuğa açıklamadan önce yapılan hazırlıktır."},{"id":"os-3-s86","tur":"coktan-secmeli","soru":"Halı yıkama ve boya badana gibi periyodik işler neden otelin en sakin döneminde planlanır?","secenekler":["Yoğun dönemde temizlik malzemesi bulunamaz.","Sakin dönemde personel sayısı artar.","Odalar satıştan çıksa bile gelir kaybı en az olur.","Yoğun dönemde halı yıkama makineleri çalışmaz."],"dogru":2,"aciklama":"Derin temizlik ve bakım için doluluk oranına bakılır; en sakin dönem, odaları satıştan çıkarmanın bedelinin en düşük olduğu dönemdir."},{"id":"os-3-s87","tur":"coktan-secmeli","soru":"Marmaris’te sezonluk bir otel kasımda kapanıyor; kış boyunca odalar boyanıyor ve yataklar çevriliyor. Bu işler hangi aralıkta yapılan işlerdendir?","secenekler":["Altı aylık","Aylık","Haftalık","Yıllık (sezonluk)"],"dogru":3,"aciklama":"Boya badana ve yatakların döndürülmesi yılda bir yapılan yenileme işleridir. Altı aylıkta halı yıkama ve ilaçlama, aylıkta cilalama ve cam dış yüzeyi bulunur."},{"id":"os-3-s88","tur":"coktan-secmeli","soru":"Açık hava konserinden önce ekip hava durumuna bakıyor, yağmur olasılığına karşı kapalı salonu boş tutuyor ve yedek mikrofon hazırlıyor. Bu etkinlik iş planının hangi bileşenidir?","secenekler":["Mekân ve lojistik","Risk ve kriz yönetimi","Bütçe ve finans","Pazarlama ve tanıtım"],"dogru":1,"aciklama":"Teknik arıza, hava değişikliği gibi olasılıklara karşı alternatif plan hazırlamak risk ve kriz yönetimidir. Mekân ve lojistik, asıl mekânın seçimini ve donanımını kapsar."},{"id":"os-3-s89","tur":"senaryo","durum":"Saat 17.00, çocuk kulübünde stajyersin. Kayıt formunda velisi olarak annesi yazan altı yaşındaki bir çocuğu almak için tanımadığın bir adam geliyor: “Dayısıyım, annesi gönderdi.” Animatör birkaç metre ötede diğer çocuklarla ilgileniyor.","soru":"Ne yaparsın?","secenekler":["Çocuk onu tanıyıp sarılırsa teslim eder, saati forma yazarsın.","Kimliğini gösterirse adını forma yazıp çocuğu teslim edersin.","Çocuğu vermez, beklemesini rica edip animatöre haber verirsin.","Adama güvenmediğini söyleyip kulüpten çıkmasını istersin."],"dogru":2,"aciklama":"Çocuk yalnız kayıt formunda veli ya da yetkili kişi olarak yazılı kişiye teslim edilir. Kimlik göstermek ya da çocuğun sarılması formda yazılı olmayı yerine koymaz; sert davranmak da gerekmez."},{"id":"os-3-s90","tur":"senaryo","durum":"Saat 20.30, akşam gösterisine bir saat var. Sahnenin yanında, konukların geçeceği yoldaki uzatma kablosunun kılıfının soyulduğunu ve içindeki tellerin göründüğünü fark ediyorsun. Ekip prova telaşında.","soru":"İlk adımın ne olur?","secenekler":["Kabloya dokunmaz, hemen şefine ve teknik servise bildirirsin.","Kabloyu elektrik bandıyla sarıp provaya devam edersin.","Ekibi telaşlandırmamak için gösteri bitince söylemek üzere not alırsın.","Fişi çekip kabloyu kendin yenisiyle değiştirirsin."],"dogru":0,"aciklama":"Hasarlı ekipman kullanılmaz ve hemen bildirilir; elektrik işine eğitimi olmayan personel karışmaz. Soyulmuş kablo elektrik çarpması riskidir ve konuklar o yoldan geçecektir."},{"id":"os-3-s91","tur":"senaryo","durum":"Saat 11.00, havuz başında animatöre yardım ediyorsun. Su topu maçı için bir kişi eksik. Şezlongdaki konuğu davet ettin; “Teşekkürler, dinlenmek istiyorum.” dedi. Yanındaki arkadaşın “Bir daha sor, gelir.” diyor.","soru":"Ne yaparsın?","secenekler":["Bileğinden tutup gülerek oyun alanına doğru götürürsün.","İyi dinlenmeler dileyip başka bir konuğu davet edersin.","Mikrofondan adını anons edip herkese alkışlatırsın.","Yanına oturup kabul edene kadar ikna etmeye çalışırsın."],"dogru":1,"aciklama":"Etkinliğe katılım gönüllüdür; israrla oyuna çekilen konuk eğlenmez, rahatsız olur. “Hayır” diyen konuğa saygı hizmetin parçasıdır."},{"id":"os-3-s92","tur":"senaryo","durum":"Saat 14.50, resepsiyonda sabah vardiyasının son dakikaları. Bir konuk odasındaki klimanın çalışmadığını söyledi; küçük bir kâğıda not aldın. Teknik servisin telefonu meşgul çalıyor ve on dakika sonra vardiyan bitiyor.","soru":"Ne yaparsın?","secenekler":["Kâğıdı bankoya bırakır, akşam ekibinin görüp ilgileneceğini umarsın.","Yarın sabah geldiğinde ilk iş teknik servisi araman gerektiğini kendine not edersin.","Vardiya defterine yazar, devralan görevliye ve şefine de söylersin.","Konuğa teknik servisi odasından kendisinin aramasını söylersin."],"dogru":2,"aciklama":"Deftere yazılmayan iş sonraki vardiya için hiç olmamış gibidir; konuk aynı isteği ikinci kez söylemek zorunda kalır. Bilgi yazılı ve sözlü devredilir."},{"id":"os-3-s93","tur":"senaryo","durum":"Saat 22.15, ön büroda stajyersin; şefin arka ofiste. Rezervasyonu olan bir aile uzun bir yolculuktan geliyor, ama sistemde boş oda görünmüyor. Baba yorgun ve sesini yükseltmeye başlıyor.","soru":"İlk adımın ne olur?","secenekler":["Özür diler, oturmalarını rica edip hemen şefini çağırırsın.","Sistemin hata yaptığını, senin suçun olmadığını anlatırsın.","Rezervasyonlarının geçersiz olduğunu, oda kalmadığını söylersin.","Yakındaki bir oteli kendin arayıp aileyi oraya gönderirsin."],"dogru":0,"aciklama":"Konuk bahane değil çözüm duymak ister; durumu açıklamak ve seçenek sunmak yetkilinin işidir. Suçu sisteme atmak ya da kendi başına karar vermek durumu kötüleştirir."},{"id":"os-3-s94","tur":"senaryo","durum":"Saat 16.00. Akşam 20.00’de bahçede yapılacak çocuk şenliğinin hazırlığındasın. Gökyüzü kararıyor, hava durumu akşam için sağanak gösteriyor. Etkinlik planında yağmur durumunda kapalı salonun kullanılacağı yazıyor; şef toplantıda ama telefonla ulaşılabiliyor.","soru":"Ne yaparsın?","secenekler":["Yağmur yağmayabilir diye düşünür, kimseye bir şey söylemezsin.","Şefe sormadan şenliği iptal edip panodaki duyuruyu indirirsin.","Malzemeleri kendi kararınla salona taşıyıp duyuruyu değiştirirsin.","Durumu şefine bildirir, yedek plandaki salon için onay istersin."],"dogru":3,"aciklama":"Risk ve kriz yönetimi, alternatif planın önceden hazırlanmasıdır. Planı uygulama ve konuklara duyurma kararı yetkilidedir; şef bilgilendirilir ve onay alınır."},{"id":"os-3-s95","tur":"coktan-secmeli","soru":"Ders kitabına göre Anadolu’daki konaklama geleneği hangi sırayla gelişmiştir?","secenekler":["Ribat, moyanlık, kervansaray","Kervansaray, ribat, moyanlık","Moyanlık, ribat, kervansaray","Moyanlık, kervansaray, ribat"],"dogru":2,"aciklama":"Hayır amacıyla kurulan ilk konaklama yeri olan moyanlık önce ribatlara, sonra kervansaraylara dönüşmüştür."},{"id":"os-3-s96","tur":"coktan-secmeli","soru":"Rezervasyon şefi cumartesi gelecek bir düğün grubu için üçüncü kattaki bazı odaları satışa kapatıp ayırıyor. Bu işlemin adı nedir?","secenekler":["Oda blokajı","Overbooking","Upselling","Upgrade"],"dogru":0,"aciklama":"Oda blokajı grup ya da acente için belirli tarihlerde odaların satışa kapatılmasıdır. Overbooking kapasiteden fazla rezervasyondur; upselling ve upgrade ise konuğu üst bir odaya almakla ilgilidir."},{"id":"os-3-s97","tur":"coktan-secmeli","soru":"Minibar kontrol formundaki “mevcut stok (parstock)” neyi gösterir?","secenekler":["Konuğun tükettiği ürünlerin toplam tutarını","Ürünlerin son kullanma tarihini ve ambalajını","Her ürünün birim fiyatı ile toplam tutarını","Her ürün için bulunması gereken standart miktarı"],"dogru":3,"aciklama":"Parstock, kontrol sonunda ürünlerin tamamlandığı standart düzeydir; tüketilen ve birim fiyat formda ayrı sütunlardır."},{"id":"os-3-s98","tur":"senaryo","durum":"Sabah 08.30, lobi zeminini silmek için kovaya zemin temizleyicisi koyacaksın. Ürünün etiketinde kovaya ne kadar konacağı yazıyor. Yanındaki arkadaşın “Etikete bakma, daha çok koy, zemin daha iyi temizlenir” diyor.","soru":"Ne yaparsın?","secenekler":["Arkadaşının dediği gibi daha iyi temizlesin diye bol koyarsın.","Etikette yazan miktarı ölçü kabıyla eklersin.","Kalıntı kalmasın diye çok az koyar, kir çıkmazsa tekrar silersin.","Miktarı göz kararı ayarlar, kalıntı kalırsa sonra silersin."],"dogru":1,"aciklama":"Fazla ürün daha iyi temizlemez; yüzeyde yapışkan kalıntı bırakır, zemini kayganlaştırır ve ürünü boşa harcar. Az ürün kiri çözmez. Doğru dozaj hem temizlik hem tasarruftur."},{"id":"os-3-s99","tur":"coktan-secmeli","soru":"Amasra’da oda sayısı az ve yönetimi basit bir tesiste konuklar akşam yemeklerini ortak mutfakta kendileri pişirebiliyor. Bu tesis hangisidir?","secenekler":["Butik otel","Tatil köyü","Motel","Pansiyon"],"dogru":3,"aciklama":"Pansiyonun oda sayısı az, yönetimi basittir ve konuk yemeğini kendisi de hazırlayabilir. Butik otel de küçüktür ama kişiye özel, yüksek standartta hizmet verir."},{"id":"os-3-s100","tur":"coktan-secmeli","soru":"Mardin’de restore edilmiş taş bir konakta her odanın döşemesi farklı; konuğa kahvaltıda ne sevdiği bir gün önceden soruluyor. Bu tesisin türü hangisidir?","secenekler":["Pansiyon","Hostel","Butik otel","Apart otel"],"dogru":2,"aciklama":"Özgün tasarım, az oda ve kişiye özel yüksek standartta hizmet butik oteli tanımlar. Pansiyon da küçüktür ama yalın yönetimli, basit bir tesistir."},{"id":"os-3-s101","tur":"coktan-secmeli","soru":"Aşağıdakilerden hangisi yardımcı konaklama işletmelerinden biridir?","secenekler":["Motel","Apart otel","Butik otel","Tatil köyü"],"dogru":1,"aciklama":"Apart otel; kamping, yüzer tesis, oberj ve hostelle birlikte yardımcı konaklama grubundadır. Motel, butik otel ve tatil köyü ise temel konaklama işletmeleridir."},{"id":"os-3-s102","tur":"dogru-yanlis","soru":"Apart otelin odalarında konuğun kendi yemeğini hazırlayabileceği mutfak donanımı bulunur.","secenekler":["Doğru","Yanlış"],"dogru":0,"aciklama":"Apart otel, odaları mutfak donanımlı olarak döşenen ve otel olarak işletilen tesistir; konuk marketten aldığını odasında pişirebilir."},{"id":"os-3-s103","tur":"coktan-secmeli","soru":"Göcek’te demirli bir teknede konuklar kamarada geceliyor, güvertede kahvaltı ediyor. Teknenin yüzer tesis sayılması için hangi belgesi olmalıdır?","secenekler":["Konaklama belgesi","Denize elverişlilik belgesi","Kimlik Bildirim Sistemi kaydı","Teyit mektubu"],"dogru":1,"aciklama":"Yüzer tesis, denize elverişlilik belgesi bulunan ve turizm amacıyla konaklama hizmeti veren deniz aracıdır. Konaklama belgesi ise girişte konuğun imzaladığı belgedir."},{"id":"os-3-s104","tur":"coktan-secmeli","soru":"Stajyer bir sorunu kat şefine, kat şefi çözemeyince kat hizmetleri müdürüne iletiyor. Sorunun basamak basamak yukarı taşınması hangi düzeni gösterir?","secenekler":["Oryantasyon","Hiyerarşi","Vardiya devri","Departmanlar arası iş birliği"],"dogru":1,"aciklama":"Hiyerarşi, yetki ve sorumluluğun üstten alta basamak basamak sıralandığı ast üst düzenidir. İş birliği ise farklı departmanların birbirine bilgi vermesidir, aynı bölümdeki basamakları anlatmaz."},{"id":"os-3-s105","tur":"coktan-secmeli","soru":"Aşağıdakilerden hangisi otelin konuğun görmediği “arka yüz” alanlarından biridir?","secenekler":["Lobi","Resepsiyon bankosu","Restoran salonu","Bulaşıkhane"],"dogru":3,"aciklama":"Bulaşıkhane, konuğun görmediği hazırlık ve destek alanlarındandır. Restoran salonu ise konuğun personelle yüz yüze geldiği ön yüzdür."},{"id":"os-3-s106","tur":"dogru-yanlis","soru":"Kampingte konuklar geceleme ve yeme içme ihtiyaçlarını çoğunlukla tesisin oda ve restoran hizmetiyle karşılar.","secenekler":["Doğru","Yanlış"],"dogru":1,"aciklama":"Kampingte konuk bu ihtiyaçları çoğunlukla kendi imkânlarıyla, örneğin kendi çadırı ve ocağıyla karşılar; tesis duş, elektrik gibi ortak alanları sunar."},{"id":"os-3-s107","tur":"coktan-secmeli","soru":"Tur grubu için ayrılan salonda herkese aynı çorba, aynı ana yemek ve aynı tatlı veriliyor; fiyat kişi başı tek. Bu menü türü hangisidir?","secenekler":["Tabldot","Alakart","Açık büfe","Oda servisi"],"dogru":0,"aciklama":"Tabldotta yemekler önceden belirlenmiştir ve tek fiyatla sunulur. Alakartta ise konuk menüden seçer ve her yemek ayrı fiyatlandırılır."},{"id":"os-3-s108","tur":"coktan-secmeli","soru":"Açık büfe için meze tabakları ve zeytinyağlılar mutfağın hangi bölümünde hazırlanır?","secenekler":["Soğuk kısım","Sıcak kısım","Kasaphane","Aperitif ve garnitür bölümü"],"dogru":0,"aciklama":"Zeytinyağlılar, mezeler, salatalar ve soğuk soslar soğuk kısımda hazırlanır. Sıcak kısımda ise tencere yemekleri, soslar ve ızgaralar pişirilir."},{"id":"os-3-s109","tur":"coktan-secmeli","soru":"Günün çorbası ile ızgaradan çıkan etin yanına konacak pilav ve haşlanmış sebze mutfağın hangi bölümünde hazırlanır?","secenekler":["Soğuk kısım","Kahvaltı bölümü","Pastane","Aperitif ve garnitür bölümü"],"dogru":3,"aciklama":"Çorbalar, makarnalar ve yemeklerin yanına eklenen garnitürler aperitif ve garnitür bölümünün işidir. Soğuk kısım ise meze ve salata hazırlar."},{"id":"os-3-s110","tur":"dogru-yanlis","soru":"Bir çalışanın sözleşmesi, izin formları ve sigorta belgeleri özlük dosyasında saklanır.","secenekler":["Doğru","Yanlış"],"dogru":0,"aciklama":"Özlük dosyası, çalışanın işe girişinden ayrılışına kadar kimlik, sözleşme, izin, sigorta ve disiplin belgelerinin tutulduğu dosyadır."},{"id":"os-3-s111","tur":"coktan-secmeli","soru":"Anne, çocuğunun yer fıstığı alerjisi olduğunu söylüyor; garson tatlının içeriğinden emin değil. Doğru davranış hangisidir?","secenekler":["Tatlıda fıstık görünmüyorsa servis eder.","Tatlının fıstıksız olduğunu tahmin edip söyler.","Şefe sorar ve siparişe alerji notunu yazar.","Tatlıyı sipariş listesinden kendisi çıkarır, kimseye sormaz."],"dogru":2,"aciklama":"Gıda alerjisi tahminle geçiştirilmez; mutfağa sorulur ve siparişe yazılı not düşülür. Görünüşe göre karar vermek, alerjeni gözden kaçırabilir."},{"id":"os-3-s112","tur":"coktan-secmeli","soru":"Ay sonunda bir görevli restoranın gelirinin aynı kaldığını ama et giderinin arttığını görüp nedenini araştırıyor. Hangi muhasebe bölümünde çalışıyor?","secenekler":["Maliyet ve gelirler bölümü","Krediler bölümü","Genel kasa bölümü","Depo ve ambar bölümü"],"dogru":0,"aciklama":"Hasılatı izleyip giderleri denetleyerek maliyet kontrolü yapmak maliyet ve gelirler bölümünün işidir. Depo ve ambar bölümü malı teslim alıp saklar, gider analizi yapmaz."},{"id":"os-3-s113","tur":"coktan-secmeli","soru":"Resepsiyon ekibi her yaz baştan kurulan bir otelde sürekli gelen konuklar hep tanımadığı yüzlerle karşılaşıyor. Bu sorun hangi kavramla açıklanır?","secenekler":["Oryantasyon sürecinin uzun sürmesi","Personel devir hızının yüksekliği","Hiyerarşinin çok basamaklı olması","Vardiya devrinin yazılı yapılması"],"dogru":1,"aciklama":"Ayrılan ve yerine yenisi alınan çalışan sayısı çoksa personel devir hızı yüksektir; konuk tanıdık yüz göremez. Oryantasyon ise yeni personelin uyum sürecidir, ekibin her yıl değişmesini anlatmaz."},{"id":"os-3-s114","tur":"dogru-yanlis","soru":"Overbooking, tesisin iptallere karşı önlem olarak oda kapasitesinden daha az rezervasyon almasıdır.","secenekler":["Doğru","Yanlış"],"dogru":1,"aciklama":"Overbooking, iptallere ve gelmeyen konuklara karşı kapasiteden fazla rezervasyon almaktır; iptal az çıkarsa son gelen konuğa oda kalmayabilir."},{"id":"os-3-s115","tur":"coktan-secmeli","soru":"Mutfak şefi haftalık sebze ihtiyacını bildiriyor; bir görevli tedarikçilerden fiyat alıp kalite ve fiyatı karşılaştırarak sipariş veriyor. Bu görevli hangi departmandadır?","secenekler":["Depo ve ambar bölümü","Satış ve pazarlama","Maliyet ve gelirler bölümü","Satın alma"],"dogru":3,"aciklama":"İhtiyacı en uygun kalite ve fiyat dengesiyle tedarik etmek satın almanın işidir. Depo ve ambar bölümü ise gelen malı kontrol edip saklar, siparişi vermez."},{"id":"os-3-s116","tur":"coktan-secmeli","soru":"Sabah resepsiyondaki otel programı açılmıyor ve çıkış yapacak konuklar sıraya giriyor. Sorunu hangi destek departmanı çözer?","secenekler":["Teknik servis","Bilgi işlem","Güvenlik","Satın alma"],"dogru":1,"aciklama":"Otomasyon sistemlerini ve bilgisayar ağını bilgi işlem yönetir. Teknik servis klima, su, elektrik gibi tesis arızalarıyla ve bakımla ilgilenir."},{"id":"os-3-s117","tur":"coktan-secmeli","soru":"Alman konuk taksi için avro bozdurmak istiyor; görevli panodaki kuru gösterip parayı konuğun önünde sayıyor. Bu hangi işlemdir?","secenekler":["Ön provizyon","Ödeme fişi düzenleme","Kambiyo işlemi","Düzeltme fişi düzenleme"],"dogru":2,"aciklama":"Yabancı paranın ilan edilen kurdan Türk lirasına çevrilmesi kambiyo işlemidir. Ön provizyon ise kredi kartında güvence tutarı ayırmaktır."},{"id":"os-3-s118","tur":"dogru-yanlis","soru":"Kapı kartı programlama makinesiyle hazırlanan kart, konuğun odasını yalnız ayrılış tarihine kadar açar.","secenekler":["Doğru","Yanlış"],"dogru":0,"aciklama":"Görevli makineye oda numarasını ve ayrılış tarihini girer; kart yalnız o odanın kapısını, yalnız o tarihe kadar açar."},{"id":"os-3-s119","tur":"coktan-secmeli","soru":"Aşağıdakilerden hangisi check-out (çıkış) işleminin bir adımıdır?","secenekler":["Konaklama belgesini imzalatmak","Kapı kartını programlamak","Kimlik bildirimini yapmak","Kapı kartını geri almak"],"dogru":3,"aciklama":"Çıkışta hesap incelenip tahsil edilir, kart geri alınır ve konuk uğurlanır. Konaklama belgesini imzalatmak ise giriş işleminin adımıdır."},{"id":"os-3-s120","tur":"coktan-secmeli","soru":"Gece görevlisi, “305’in konuğu 09.00’da taksi istiyor” notunu sabah ekibi okusun diye nereye yazar?","secenekler":["Konuğun tarihçe kartındaki not alanı","Kayıp eşya takip defteri","Logbook (vardiya defteri)","Folyo"],"dogru":2,"aciklama":"Logbook, vardiyada olanların ve sonraki vardiyanın bilmesi gerekenlerin yazıldığı iletişim defteridir. Tarihçe kartı ise konuğun geçmiş konaklamalarını ve tercihlerini tutar."},{"id":"os-3-s121","tur":"coktan-secmeli","soru":"Büyük bir otelde ön büro müdürü ile kat hizmetleri müdürünün üstünde yer alıp genel müdüre bağlı çalışan yönetici kimdir?","secenekler":["Gece müdürü","Odalar bölümü müdürü","Ön büro müdür yardımcısı","Resepsiyon şefi"],"dogru":1,"aciklama":"Odalar bölümü müdürü, ön büro ve kat hizmetleri gibi oda işlerini yürüten bölümlerin üstündedir. Gece müdürü yalnız gece vardiyasından sorumludur."},{"id":"os-3-s122","tur":"dogru-yanlis","soru":"VIP bildirim formunda konuğun önem derecesi beş dereceli bir puanla gösterilir.","secenekler":["Doğru","Yanlış"],"dogru":1,"aciklama":"VIP derecesi formda üç dereceli (1, 2, 3) olarak işaretlenir; kat hizmetleri ve mutfak hazırlığı bu dereceye göre yapılır."},{"id":"os-3-s123","tur":"coktan-secmeli","soru":"Konuk “Bu akşam Boğaz’da balık yemek istiyoruz” diyor. Uygun restoranda masa ayırtıp taksi çağıran ön büro birimi hangisidir?","secenekler":["Santral","Concierge (danışma)","Rezervasyon birimi","Bell desk (bagaj hizmetleri)"],"dogru":1,"aciklama":"Concierge; şehir turu, bilet ve özel isteklerde konuğa yol gösterir. Rezervasyon birimi ise otelin kendi odalarının satışını yapar."},{"id":"os-3-s124","tur":"coktan-secmeli","soru":"Gece 22.30’da konuk sabah 05.30’a uyandırma istiyor. Santral memuru talebi alırken ne yapar?","secenekler":["Saati ve oda numarasını konuğa tekrar eder.","Talebi aklında tutar, sisteme girmez.","Talebi sabah ekibine sözlü bırakmakla yetinir.","Konuğa telefonunun alarmını kurmasını önerir."],"dogru":0,"aciklama":"Santral, saati ve oda numarasını konuğa tekrar ederek doğrular, talebi sisteme girer ve zamanı gelince arar. Talebi yalnız akılda tutmak unutulma riskini doğurur."},{"id":"os-3-s125","tur":"coktan-secmeli","soru":"Bir acentenin kırk kişilik grup talebini inceleyen, o tarihlerdeki boş odalara bakıp memura hangi odaların ayrılacağını söyleyen sorumlu kimdir?","secenekler":["Resepsiyon şefi","Danışma şefi","Rezervasyon şefi","Konuk ilişkileri görevlisi"],"dogru":2,"aciklama":"Rezervasyon şefi grup rezervasyonlarını ve oda kontenjanlarını izler, kayıtları denetler. Resepsiyon şefi ise bankoda giriş ve çıkış işlemlerini yönetir."},{"id":"os-3-s126","tur":"dogru-yanlis","soru":"Konaklama vergisi faturada KDV’nin içinde gösterilir; ayrı bir satır olarak yer almaz.","secenekler":["Doğru","Yanlış"],"dogru":1,"aciklama":"Faturada hizmet bedellerinin yanında KDV, altında ise konaklamaya ayrıca uygulanan konaklama vergisi ayrı bir satır olarak yer alır."},{"id":"os-3-s127","tur":"coktan-secmeli","soru":"Şikâyeti olan bir konuğu yeni görevliden devralıp kendisi dinleyen ve giriş-çıkış işlemlerinin doğruluğunu denetleyen bankodaki ekip lideri kimdir?","secenekler":["Danışma şefi","Rezervasyon şefi","Santral memuru","Resepsiyon şefi"],"dogru":3,"aciklama":"Resepsiyon şefi bankodaki ekibin lideridir; giriş ve çıkışları denetler, görevlilere yol gösterir. Danışma şefi ise üniformalı hizmetleri ve konukların özel isteklerini yönetir."},{"id":"os-3-s128","tur":"coktan-secmeli","soru":"Uçağı akşam kalkacak konuk sabah odasını boşaltıyor ama valizleriyle şehri gezmek istemiyor. Bellboy valizleri nereye alır?","secenekler":["Kat ofisine","Kayıp eşya deposuna","Konuğun boşalttığı odaya","Bagaj odasına"],"dogru":3,"aciklama":"Bagaj odası, konuğun erken geldiğinde ya da çıkıştan sonra bagajını güvenle bıraktığı emanet odasıdır. Boşalan oda ise yeni konuk için hazırlanacağından kullanılamaz."},{"id":"os-3-s129","tur":"coktan-secmeli","soru":"Akşam konuk aracını otel girişine bırakıyor; görevli anahtarı alıp ona bir numara kartı veriyor. Bu görevli kimdir?","secenekler":["Kapı görevlisi","Vale","Bellboy","Güvenlik görevlisi"],"dogru":1,"aciklama":"Vale, konuğun aracını girişte teslim alıp park eder ve istendiğinde geri getirir. Kapı görevlisi ise konuğu karşılar, araç kapısını açar ama aracı park etmez."},{"id":"os-3-s130","tur":"dogru-yanlis","soru":"Garantisiz rezervasyonu olan konuğun odası, konuk geç gelse de gece boyunca tutulur.","secenekler":["Doğru","Yanlış"],"dogru":1,"aciklama":"Gece boyunca tutulan oda garantili rezervasyonun odasıdır. Garantisiz rezervasyonda ödeme güvencesi yoktur; görevli konuğu arayıp gelip gelmeyeceğini sorar."},{"id":"os-3-s131","tur":"coktan-secmeli","soru":"Gece müdürünün yanlış odaya işlenmiş bir restoran harcamasını düzeltip gün sonu işlemini başlatması hangi çalışmanın parçasıdır?","secenekler":["Gece denetimi","Vardiya devri","Profil inceleme","Oda blokajı"],"dogru":0,"aciklama":"Gece denetiminde günün hesapları ve kayıtları kontrol edilir, hatalar düzeltilir ve gün sonu yapılır. Vardiya devri ise yarım kalan işlerin sonraki ekibe aktarılmasıdır."},{"id":"os-3-s132","tur":"coktan-secmeli","soru":"Restorandan gelen imzalı adisyon, çıkışta hazır olsun diye 318 numaralı odanın gözüne konuyor. Bu raf hangisidir?","secenekler":["Anahtar ve mesaj panosu","Oda durum panosu","Duyuru panosu","Folyo havuzu"],"dogru":3,"aciklama":"Folyo havuzunda her konuğun belgeleri ve makbuzları oda numarasına göre saklanır. Anahtar ve mesaj panosunda ise anahtarlar ve konuğa bırakılan notlar durur."},{"id":"os-3-s133","tur":"coktan-secmeli","soru":"Geç gelen konuğun kimlik bilgileri emniyet birimlerine hangi sistem üzerinden bildirilir?","secenekler":["Kimlik Bildirim Sistemi (KBS)","Bilgisayar terminali (PMS)","Pasaport okuyucu","Otel otomasyon programının konuk ekranı"],"dogru":0,"aciklama":"KBS, kalan konukların kimlik bilgilerini emniyet birimlerine iletmek için kullanılır. Pasaport okuyucu bilgiyi yalnız otel sistemine aktarır, bildirimi yapmaz."},{"id":"os-3-s134","tur":"dogru-yanlis","soru":"Upselling, konuğun ayırttığından daha üst bir odaya fiyat farkı alınmadan yerleştirilmesidir.","secenekler":["Doğru","Yanlış"],"dogru":1,"aciklama":"Upselling’de üst oda konuğa fiyat farkıyla önerilir. Fiyat farkı alınmadan tesisin jesti olarak yapılan yerleştirme upgrade’dir."},{"id":"os-3-s136","tur":"coktan-secmeli","soru":"Otuz kişilik tur grubunun ortak konaklama ücreti rehber adına açılan tek bir hesaba işleniyor. Bu hesap hangisidir?","secenekler":["Folyo havuzu","Konuk tarihçe kartı","Ödeme fişi","Master folyo"],"dogru":3,"aciklama":"Master folyo, acente ya da grup gibi birden çok kişinin ortak harcamalarının tutulduğu folyodur. Folyo havuzu ise belgelerin oda numarasına göre saklandığı raftır."},{"id":"os-3-s137","tur":"coktan-secmeli","soru":"Çıkışta konuk faturanın şirket adına düzenlenmesini istiyor. Görevli konuktan hangi bilgiyi almalıdır?","secenekler":["Pasaport ya da kimlik numarası","Vergi dairesi ve vergi numarası","Kredi kartının son kullanma tarihi","Rezervasyon numarası"],"dogru":1,"aciklama":"Faturanın mali ve yasal değeri vardır; şirket adına kesilecekse vergi dairesi ve vergi numarası gerekir. Pasaport numarası kimlik kaydı içindir, faturayı şirkete bağlamaz."},{"id":"os-3-s139","tur":"coktan-secmeli","soru":"Satış bölümü yeni kampanyayı ön büroya bildirmeyi unutursa en olası sorun hangisidir?","secenekler":["Odalar zamanında temizlenemez.","Rezervasyon memuru konuğa yanlış fiyat söyler.","Gün sonu raporu muhasebeye zamanında ulaştırılamaz.","Arızalı oda satışa açılır."],"dogru":1,"aciklama":"Kampanya ve fiyat bilgisi satıştan ön büroya akmazsa telefonda konuğa farklı fiyat ve koşul söylenir. Oda temizliği ise kat hizmetleriyle iş birliğinin konusudur."},{"id":"os-3-s140","tur":"coktan-secmeli","soru":"Lobideki koltukta sahipsiz bir çanta bulundu. Resepsiyon görevlisinin doğru davranışı hangisidir?","secenekler":["İçine bakıp sahibini bulmaya çalışır.","Çantayı kayıp eşya deposuna kendisi taşır.","Çantayı karıştırmadan güvenliğe ve amirine bildirir.","Lobideki konuklara çantanın kime ait olduğunu tek tek sorar."],"dogru":2,"aciklama":"Sahipsiz eşyada ön büro güvenlikle birlikte çalışır: çanta karıştırılmaz, güvenliğe ve amire haber verilir, olay kayda geçer. Çantayı açmak hem güvenlik hem mahremiyet açısından risklidir."},{"id":"os-3-s141","tur":"coktan-secmeli","soru":"Tekerlekli sandalye kullanan bir konuk için ayrılacak odada öncelikle ne aranır?","secenekler":["Geniş kapı ve uygun banyo","Deniz manzarası","Ayrı oturma salonu","Yandaki odaya bağlantı kapısı"],"dogru":0,"aciklama":"Engelli odası geniş kapı ve özel banyo gibi teknik standartlarla hazırlanır. Manzara ya da salon konforla ilgilidir, erişilebilirliği sağlamaz."},{"id":"os-3-s142","tur":"dogru-yanlis","soru":"Havlu stokunun azaldığını gören kat hizmetleri müdürü yeni havluları doğrudan tedarikçiden kendisi satın alır.","secenekler":["Doğru","Yanlış"],"dogru":1,"aciklama":"Kat hizmetleri ihtiyacı zamanında belirler ve satın alma departmanından ister; tedarik satın almanın işidir."},{"id":"os-3-s143","tur":"coktan-secmeli","soru":"Evlilik yıl dönümünü kutlayan çift standart oda ayırtmış; resepsiyon şefinin onayıyla fiyat farkı alınmadan boş junior süite alınıyor. Bu uygulama hangisidir?","secenekler":["Upselling","Upgrade","Oda blokajı","Kâhya hizmeti"],"dogru":1,"aciklama":"Upgrade, konuğun tesisin jesti olarak çoğu zaman fiyat farkı alınmadan üst odaya yerleştirilmesidir. Upselling’de ise üst oda fiyat farkıyla önerilir."},{"id":"os-3-s144","tur":"coktan-secmeli","soru":"Kral dairesinde kalan konuğa özel bir görevli ayrılıyor; akşam yemeği ve kıyafet ütüsü gibi istekleri bu kişi karşılıyor. Hizmetin adı nedir?","secenekler":["Kâhya hizmeti","Concierge hizmeti","Oda servisi","Gece hazırlığı"],"dogru":0,"aciklama":"Kâhya hizmetinde üst düzey lüks odadaki konuğa özel bir görevli ayrılır. Concierge ise bütün konuklara bilet, tur ve özel isteklerde yol gösterir."},{"id":"os-3-s145","tur":"coktan-secmeli","soru":"Oda görevlisi komodinin üstünde bırakılmış bir miktar para görüyor. Meslek değerine uygun davranış hangisidir?","secenekler":["Parayı korumak için kayıp eşya deposuna götürür.","Parayı sayıp miktarını kat arkadaşlarına söyler.","Parayı çekmeceye koyup üstünü kapatır.","Parayı yerinden oynatmaz, kimseye anlatmaz."],"dogru":3,"aciklama":"Dürüstlük ve sır saklama gereği konuğa ait hiçbir şeye dokunulmaz, odada görülen başkasına anlatılmaz. Kayıp eşya işlemi yalnız konuğun unuttuğu eşya içindir, odada kalan konuğun parası için değil."},{"id":"os-3-s146","tur":"dogru-yanlis","soru":"Oda görevlisi pas anahtarını kolay ulaşmak için gün boyu kat arabasının üstünde bırakabilir.","secenekler":["Doğru","Yanlış"],"dogru":1,"aciklama":"Pas anahtarı birçok odayı açtığı için vardiya başında imzayla alınır ve gün boyu üzerinde taşınır; kat arabasının üstüne bir an bile bırakılmaz."},{"id":"os-3-s147","tur":"coktan-secmeli","soru":"Kat şefinin vardiya başında “410’a öğlen önemli bir konuk geliyor, önce o oda hazırlanacak” deyip oda listelerini dağıttığı kısa buluşma hangisidir?","secenekler":["Oryantasyon","Sabah toplantısı","Vardiya devri","Kat raporu"],"dogru":1,"aciklama":"Sabah toplantısında doluluk, öncelikli odalar ve özel istekler paylaşılır, görevler dağıtılır. Vardiya devri ise işi bırakan ekibin bilgiyi devralan ekibe aktarmasıdır."},{"id":"os-3-s148","tur":"coktan-secmeli","soru":"Ütücü, çarşafı silindir ütüden geçirirken köşede çıkmamış bir leke fark ediyor. Ne yapmalıdır?","secenekler":["Lekeli köşeyi içe katlayıp rafa koyar.","Çarşafı ütüleyip kat ofisine gönderir.","Lekeyi nemli bir bezle silip ütülemeye devam eder.","Çarşafı ayırıp yeniden yıkanması için bildirir."],"dogru":3,"aciklama":"Ütücü tekstili konuğa sunulacak son biçimine getirir; lekeli çarşaf ayrılır ve yeniden yıkanır. Lekeyi katlayıp gizlemek, lekeli çarşafın konuğa ulaşmasına yol açar."},{"id":"os-3-s149","tur":"coktan-secmeli","soru":"Tekstil döngüsünün doğru sırası hangisidir?","secenekler":["Yıkama, odadan toplama, katlara dönüş, ütüleme","Odadan toplama, ütüleme, yıkama, katlara dönüş","Ütüleme, yıkama, odadan toplama, katlara dönüş","Odadan toplama, yıkama, ütüleme, katlara dönüş"],"dogru":3,"aciklama":"Kirli tekstil odadan toplanır, çamaşırhanede yıkanıp ütülenir ve temiz olarak katlara döner. Ütüleme yıkamadan önce yapılırsa kir kumaşa sabitlenir ve iş boşa gider."},{"id":"os-3-s150","tur":"dogru-yanlis","soru":"Banyo zemini silinirken kapıya en yakın noktadan başlanıp dibe doğru ilerlenir.","secenekler":["Doğru","Yanlış"],"dogru":1,"aciklama":"Çıkışa doğru çalışma kuralına göre kapıya en uzak noktadan başlanır ve kapıya doğru gelinir; böylece temiz zemine basılmaz."},{"id":"os-3-s151","tur":"coktan-secmeli","soru":"Bir otel banyo derzlerini güçlü kimyasal yerine buharlı temizleyiciyle temizliyor, konuk isterse havlusunu ikinci gün de kullanıyor. Bu hangi yaklaşımdır?","secenekler":["Yeşil kat hizmetleri","Renk kodlama sistemi","Periyodik temizlik planı","Saat yönünde denetim"],"dogru":0,"aciklama":"Yeşil kat hizmetleri kimyasal, su ve enerji kullanımını azaltarak çevreyi ve insan sağlığını korur. Renk kodlama ise mikrobun alandan alana taşınmasını önlemeye yöneliktir."},{"id":"os-3-s152","tur":"coktan-secmeli","soru":"Lobi mermerini silecek meydancı neden kireç çözücü yerine nötr temizleyici seçer?","secenekler":["Nötr temizleyici zemini daha çabuk kurutur.","Kireç çözücü yalnız halılar için üretilir.","Nötr temizleyici dezenfektan yerine geçer.","Mermer asitle temas ederse matlaşır."],"dogru":3,"aciklama":"Nötr temizleyicinin pH değeri nötre yakındır, yüzeye zarar verme riski en düşüktür; asidik kireç çözücü mermeri matlaştırır. Seçimin nedeni kuruma hızı değil, yüzeyin korunmasıdır."},{"id":"os-3-s153","tur":"coktan-secmeli","soru":"Görevli vakum süpürgenin kablosunda soyulmuş bir yer görüyor. Ne yapmalıdır?","secenekler":["Soyulan yeri bantlayıp kullanmaya devam eder.","Odayı çabucak bitirip sonra bildirir.","Makineyi başka bir prize takıp dener.","Makineyi prize takmaz, kat şefine bildirir."],"dogru":3,"aciklama":"Ekipman kontrolünde hasar görülen cihaz çalıştırılmaz ve amire bildirilir. Bantlayıp kullanmak elektrik çarpması riskini ortadan kaldırmaz."},{"id":"os-3-s154","tur":"dogru-yanlis","soru":"Alez, alt çarşafın üstüne serilen koruyucu örtüdür.","secenekler":["Doğru","Yanlış"],"dogru":1,"aciklama":"Alez yatağı sıvıdan, lekeden ve tozdan korumak için çarşafın altına serilir; alt çarşaf onun üstüne gerilir."},{"id":"os-3-s155","tur":"coktan-secmeli","soru":"Çizelgede 201 numaralı odanın karşısında “OCC / Dirty” yazıyor. Bu ne anlama gelir?","secenekler":["Oda boş, temizlenmeyi bekliyor.","Oda arızalı, satışa kapalı.","Oda dolu, günlük temizliği yapılmamış.","Konuk çıkmış, genel temizlik yapılacak."],"dogru":2,"aciklama":"OCC odada konuk kaldığını, “Dirty” ise temizliğin henüz yapılmadığını gösterir. Boş ve temizlenmemiş oda VD koduyla gösterilir."},{"id":"os-3-s156","tur":"coktan-secmeli","soru":"Halısı yıkanan bir oda, halı kuruyana kadar birkaç saat konuğa verilmeyecek ve akşam yeniden satışa açılacak. Çizelgede hangi kodla gösterilir?","secenekler":["OOS","OOO","VD","DL"],"dogru":0,"aciklama":"OOS, kısa süreli bir işlem nedeniyle geçici olarak satılmayan odayı gösterir. OOO ise teknik bir sorun nedeniyle satışa kapatılmış, arıza giderilene kadar verilmeyen odadır."},{"id":"os-3-s158","tur":"dogru-yanlis","soru":"Branş şefi, büyük işletmelerde spor, çocuk kulübü ya da sahne gibi tek bir etkinlik alanının sorumluluğunu taşır.","secenekler":["Doğru","Yanlış"],"dogru":0,"aciklama":"Büyük işletmelerde her etkinlik alanının (branşın) kendi şefi vardır; örneğin spor şefi programı spor animatörlerine dağıtır."},{"id":"os-3-s159","tur":"coktan-secmeli","soru":"Kayıp telefonunu almaya gelen konuktan, teslimden önce ekran kilidini açması isteniyor. Bu adımın adı nedir?","secenekler":["Tarafsız eşya tanımı","Profil inceleme","Kimlik bildirimi","Sahiplik doğrulaması"],"dogru":3,"aciklama":"Bulunan eşyayı isteyen kişinin gerçekten sahibi olduğu teslimden önce kontrol edilir. Tarafsız eşya tanımı ise eşyanın forma yalnız görünen özellikleriyle yazılmasıdır."},{"id":"os-3-s160","tur":"coktan-secmeli","soru":"Minibar kontrol formuna yazılan tüketim bilgisi hangi birime bildirilir?","secenekler":["Satın alma departmanına","Ön büro kasasına","Teknik servise","Güvenlik birimine"],"dogru":1,"aciklama":"Minibar kontrol formu, tüketilen ürünleri oda oda kaydedip ön büro kasasına bildirir; böylece tutar konuğun hesabına işlenir. Satın alma ise ürünlerin tedarikiyle ilgilenir."},{"id":"os-3-s161","tur":"coktan-secmeli","soru":"Koridorda biri görevliye “306’da kim kalıyor, oda boş mu?” diye soruyor. Görevli ne der?","secenekler":["“Resepsiyon size yardımcı olur efendim.”","“Şu an boş, konuk akşam gelecek.”","“Kim kaldığını bilmiyorum ama oda dolu.”","“Listeme bakıp hemen söyleyeyim efendim.”"],"dogru":0,"aciklama":"Boş odalar ve konuk bilgileri hakkında yalnız yetkili birimlerle konuşulur; kişi resepsiyona yönlendirilir. Odanın dolu ya da boş olduğunu söylemek bile güvenlik açığı yaratır."},{"id":"os-3-s163","tur":"coktan-secmeli","soru":"Lobi camına solüsyon püskürtülüp mikrofiber bezle ovuldu. Sıradaki adım hangisidir?","secenekler":["Kenarları kuru bezle tamamlamak","Uyarı levhasını yerleştirmek","Çekçekle suyu sıyırmak","Kuru mopla tozu toplamak"],"dogru":2,"aciklama":"Cam temizliğinde ovmadan sonra çekçekle sıyrılır, en sonda kenarlar kuru bezle tamamlanır. Kenarları sıyırmadan önce kurulamak, çekçeğin bıraktığı damlaları alamaz."},{"id":"os-3-s164","tur":"coktan-secmeli","soru":"Türk gecesinden sonraki gün kaç konuğun katıldığının değerlendirilmesi, etkinlik yönetim sürecinin hangi adımıdır?","secenekler":["Planlama","Denetim","Organizasyon","Koordinasyon"],"dogru":1,"aciklama":"Etkinlik yönetimi planlama, organizasyon, koordinasyon ve denetim adımlarından oluşur; sonucu değerlendirmek denetimdir. Koordinasyon ise etkinlik öncesinde birimlerle saatlerin ayarlanmasıdır."},{"id":"os-3-s165","tur":"coktan-secmeli","soru":"Gösterinin ortasında müzik kesiliyor; sunucu animatör hemen seyirciyle alkışlı bir oyun başlatıyor. Animatör hangi beceriyi gösteriyor?","secenekler":["Yabancı dilde iletişim kurma","Yaratıcı çözüm üretme","Ekip çalışmasına yatkın olma","Fiziksel dayanıklılığını koruma"],"dogru":1,"aciklama":"Beklenmedik durumda hızlı karar verip yaratıcı çözüm üretmek, etkinlik personelinin bilişsel becerilerindendir. Fiziksel dayanıklılık ise dış görünüş ve zindelikle ilgili özelliktir."},{"id":"os-3-s166","tur":"dogru-yanlis","soru":"Gösterilerde kullanılan kostümlerin temizlenmesi, etkinlik hizmetleri ile kat hizmetlerinin iş birliği alanlarından biridir.","secenekler":["Doğru","Yanlış"],"dogru":0,"aciklama":"Etkinlik ekibi aktivite alanlarının ve çocuk kulübünün hijyeni ile kostümlerin temizliği için kat hizmetleriyle birlikte çalışır."},{"id":"os-3-s167","tur":"coktan-secmeli","soru":"Bir konuk animatörden telefon numarasını isteyip akşam dışarıda buluşmayı öneriyor. Animatörün doğru davranışı hangisidir?","secenekler":["Konuğu kırmamak için numarasını verir.","Hiç cevap vermeden yanından uzaklaşır.","Nazikçe teşekkür edip kural gereği kabul etmez.","Konuğu resepsiyona şikâyet edeceğini söyleyerek uyarır."],"dogru":2,"aciklama":"Samimiyet sınırı gereği sıcaklık, konuk-personel ilişkisinin ve nezaketin dışına taşmaz; teklif kibarca geri çevrilir. Cevapsız uzaklaşmak ise nezaket kuralına uymaz."},{"id":"os-3-s168","tur":"coktan-secmeli","soru":"Gösteri sırasında sahne arkasında akış listesiyle durup “İkinci grup hazır olsun, otuz saniye sonra sahnedesiniz” diyen görevli kimdir?","secenekler":["Sahne yöneticisi","Koreograf","Kostüm sorumlusu","Ses ve ışık yöneticisi"],"dogru":0,"aciklama":"Sahne yöneticisi gösterinin sahne akışından ve sahne arkasındaki düzenden sorumludur. Koreograf ise dans adımlarını tasarlayıp ekibe öğretir, gösterinin akışını yönetmez."},{"id":"os-3-s169","tur":"coktan-secmeli","soru":"Animatör cumartesi yapılacak çocuk şenliği için parmak boyası, balon ve madalyayı depodan istemek üzere hangi formu doldurur?","secenekler":["Etkinlik malzeme talep formu","Zimmet formu","Aktivite katılım formu","Arıza bildirim formu"],"dogru":0,"aciklama":"Boya, ödül, kostüm parçası gibi sarf malzemeleri depodan malzeme talep formuyla istenir. Zimmet formu ise telsiz, kostüm gibi geri verilecek donanımın sorumlusunu kaydeder."},{"id":"os-3-s170","tur":"dogru-yanlis","soru":"“17.00 masa kontrolü, 18.00 ses provası, 19.00 konukların karşılanması” biçiminde saat saat yapılan plan, etkinliğin operasyonel iş akışıdır.","secenekler":["Doğru","Yanlış"],"dogru":0,"aciklama":"Operasyonel iş akışı, hazırlıktan bitişe kadar bütün sürecin sırasıyla ve saat saat planlanmasıdır."},{"id":"os-3-s171","tur":"coktan-secmeli","soru":"Açık havadaki gala yemeğinde yağmur başlıyor; ekip önceden hazırladığı plana göre masaları yarım saatte balo salonuna taşıyor. Bu hangi planın uygulanmasıdır?","secenekler":["SMART hedef","Temizlik takvimi","B planı","Fazla rezervasyon eylem planı"],"dogru":2,"aciklama":"B planı, beklenmedik durumlar için önceden hazırlanan yedek plandır. SMART hedef ise işletmenin ulaşmak istediği ölçülebilir sonucu tanımlar, yedek plan değildir."},{"id":"os-3-s172","tur":"coktan-secmeli","soru":"Stajyer salı ve çarşamba sabah, perşembe akşam çalışacağını hangi belgeden öğrenir?","secenekler":["Vardiya çizelgesinden","Logbook’tan (vardiya defterinden)","Organizasyon şemasından","Aktivite çizelgesinden"],"dogru":0,"aciklama":"Vardiya çizelgesi, kimin hangi gün hangi vardiyada çalışacağını ve izin günlerini gösterir. Logbook ise vardiyada olanların sonraki ekibe yazıldığı defterdir."},{"id":"os-3-s173","tur":"coktan-secmeli","soru":"Fazla rezervasyon nedeniyle oda verilemeyecek konuğa durumun nazikçe açıklanıp anlaşmalı otelde ayrılan odanın önerildiği aşama hangisidir?","secenekler":["Önleme ve izleme","Hazırlık aşaması","Konukla iletişim aşaması","Telafi ve takip"],"dogru":2,"aciklama":"Konukla iletişim aşamasında durum nazikçe açıklanır ve çözüm sunulur. Hazırlık aşamasında ise benzer otellerle önceden anlaşma yapılır; konukla konuşulmaz."},{"id":"os-3-s174","tur":"dogru-yanlis","soru":"Teknik servis fatura kesmediği için otelin işleyişinde önemsiz bir departmandır.","secenekler":["Doğru","Yanlış"],"dogru":1,"aciklama":"Doğrudan gelir getirmese de teknik servis olmadan restoranın ocağı yanmaz, arızalı oda satılamaz; departmanlar yalnız gelire göre değil işlevine ve önemine göre de sınıflandırılır."},{"id":"os-3-s175","tur":"coktan-secmeli","soru":"Tek kullanımlık küçük şampuan şişeleri yerine duvara takılan dolum şişelerine geçilmesi hangi hedefe hizmet eder?","secenekler":["Renk kodlama sistemi","Periyodik temizlik planı","Sıfır atık hedefi","Upselling"],"dogru":2,"aciklama":"Sıfır atık hedefi atığı oluşmadan önlemeyi ve kalanı en aza indirmeyi amaçlar; dolum şişesi plastik atığı azaltır. Periyodik temizlik planı ise derin temizliği zamana bağlar."},{"id":"os-3-s176","tur":"coktan-secmeli","soru":"“Çocuklu aileler için, cumartesi öğleden sonra, korsan temalı define avı.” Bu cümle etkinlik iş planının hangi bileşenini tanımlar?","secenekler":["Bütçe ve finans","Pazarlama ve tanıtım","Etkinlik konsepti","Risk ve kriz yönetimi"],"dogru":2,"aciklama":"Konsept, etkinliğin amacını, temasını ve hedef kitlesini tanımlar; cümlede tema ve hedef kitle bellidir. Bütçe ise gelir, gider ve kâr hedefiyle ilgilidir."},{"id":"os-3-s177","tur":"coktan-secmeli","soru":"Dart turnuvasında animatörün kuralları ve güvenli atış mesafesini anlattığı bölüm, etkinlik akışının hangi aşamasıdır?","secenekler":["Başlangıç (giriş)","Uygulama","Kapanış (sonuç)","Denetim"],"dogru":0,"aciklama":"Kuralların ve güvenlik bilgisinin verildiği bölüm başlangıçtır; maçlar uygulamada oynanır, ödül kapanışta verilir. Denetim etkinlik akışının değil, yönetim sürecinin adımıdır."},{"id":"os-3-s178","tur":"dogru-yanlis","soru":"Büyük ölçekli bir otelin ön bürosunda rezervasyon, santral ve gece denetimi gibi işler ayrı ekiplerce yürütülür.","secenekler":["Doğru","Yanlış"],"dogru":0,"aciklama":"Büyük ölçekli otelde her iş ayrı bir birimde uzman personelle yürütülür ve her ekibin kendi sorumlusu vardır."},{"id":"os-3-s179","tur":"coktan-secmeli","soru":"Müdür, arızalı odanın satışa hazır olma sürecini resepsiyondan teknik servise, oradan kat hizmetlerine geçen kutular ve oklarla tahtaya çiziyor. Bu çizim hangisidir?","secenekler":["Organizasyon şeması","Oda durum çizelgesi","İş akış diyagramı","Vardiya çizelgesi"],"dogru":2,"aciklama":"İş akış diyagramı bir işin adımlarını, sırasını ve departmanlar arası geçişleri şekil ve oklarla gösterir. Organizasyon şeması ise kimin kime bağlı olduğunu gösterir, işin adımlarını değil."},{"id":"os-3-s180","tur":"coktan-secmeli","soru":"Kat hizmetleri ile ön büro arasında her odanın dolu-boş, temiz-kirli durumunu ileten belge hangisidir?","secenekler":["Kat raporu","Oda durum çizelgesi","Minibar kontrol formu","Arıza bildirim formu"],"dogru":1,"aciklama":"Oda durum çizelgesi odaların doluluk ve temizlik durumunu gösterip iki bölüm arasında bilgi akışını sağlar. Kat raporu ise kat şefinin her odayı madde madde denetlediği kontrol listesidir."}],"siralamalar":[{"id":"os-3-r01","konu":"3.2","baslik":"Bir konuğun otel yolculuğu","yonerge":"Ön büroda bir konuğun konuk döngüsündeki işlemlerini doğru sıraya koy.","adimlar":["Konuğun konaklama talebini rezervasyon formuna kaydet.","Rezervasyonun kabul edildiğini bildiren teyit mektubunu konuğa gönder.","Otele gelen konuğu karşıla, kayıt kartını doldurt ve oda anahtarını teslim et.","Konaklama boyunca konuğun isteklerini karşıla ve harcamalarını folyoya işle.","Konuğun hesabını incele, ödemesini al ve konuğu uğurla."],"aciklama":"Konuk döngüsü dört evreden oluşur: varış öncesi (rezervasyon ve teyit), varış (karşılama ve kayıt), konaklama (istekler ve folyo) ve ayrılış (hesap, ödeme, uğurlama). Folyo konaklama boyunca tutulur; ayrılışta hesap bu kayda göre kapatılır."},{"id":"os-3-r02","konu":"3.3.7","baslik":"Zarf köşe: kusursuz yatağın sırrı","yonerge":"Zarf köşe tekniğiyle yatak yapmanın adımlarını doğru sıraya koy.","adimlar":["İş kıyafetini giy ve kullanacağın malzemeleri hazırla.","Alt çarşafı yatağın üzerine düzgünce yay.","Çarşafın yan kısmını boydan boya yatağın altına sıkıştır.","Açıkta kalan köşeyi yukarı kaldırıp üçgen oluştur.","Köşeyi tutarken alt kenarı yatağın altına sıkıştır.","Oluşan üçgeni aşağı indir.","Zarf biçimini yatağın altına tamamen sıkıştırıp çarşafı gerginleştir."],"aciklama":"Çarşaf yayılmadan sıkıştırılamaz; yan kısım sabitlendikten sonra köşe üçgen yapılır, alt kenar tutulurken sıkıştırılır ve üçgen indirilip altına itilince köşe zarf gibi gergin kalır."},{"id":"os-3-r03","konu":"3.3.7","baslik":"Kaymayan, parlayan zemin","yonerge":"Kat hizmetlerinde zemin temizliğinin adımlarını doğru sıraya koy.","adimlar":["“Dikkat! Islak Zemin” levhasını yerleştir; eldiveni, temiz suyu ve kimyasalı hazırla.","Kuru mop ya da süpürgeyle zemindeki tozu topla.","Islak mopla zemini deterjanlı suyla “S” çizerek paspasla.","Zeminin kurumasını bekle ve son kontrolü yap."],"aciklama":"Önce alan uyarı levhasıyla güvenliğe alınır ki kimse kayıp düşmesin; toz kuru temizlikle toplandıktan sonra zemin ıslak mopla silinir. Zemin kuruyup son kontrol yapılınca iş tamamlanır."},{"id":"os-3-r04","konu":"3.5.1","baslik":"Oda yok, konuk kapıda: overbooking planı","yonerge":"Ön büronun fazla rezervasyon (overbooking) eylem planındaki adımları doğru sıraya koy.","adimlar":["Günlük doluluğu izle; garantili ve garantisiz rezervasyonları ayır.","Odalar yetmeyecekse konuğu yönlendirebileceğin benzer kalitede bir otelle anlaş.","Durumu konuğa nazikçe açıkla ve hazırladığın çözüm seçeneklerini sun.","Konuğa ücretsiz transfer, akşam yemeği ikramı ya da sonraki konaklamada indirim tanımla."],"aciklama":"Ders kitabındaki plan dört aşamalıdır: önleme ve izleme, hazırlık, konukla iletişim, telafi ve takip. Sorunu önce fark etmek, sonra çözümü hazırlamak gerekir; konuğa ancak hazır bir seçenek sunulabilir ve mağduriyet en son telafi edilir."}]},{"ders":"otelcilik-seyahat","sinif":9,"unite":4,"baslik":"Seyahat Acenteliği Hizmetleri","onay":true,"kazanimlar":["Seyahat acentelerinin organizasyon yapısını açıklar; seyahat acentelerinde çalışan personelin sorumluluklarını sıralar.","Seyahat acentelerinin operasyonel süreçlerini açıklar; seyahat acentelerini yasal, yapısal ve fonksiyonel olarak sınıflandırır.","Seyahat acenteliğinin hukuki çerçevesini açıklar.","Seyahat acentelerinin iş birliği yaptığı kurum / kuruluşlarla ilişkilerini açıklar.","Seyahat formalitelerini açıklar."],"soz":"Konuk bir tatil satın alır; acente ona verdiği sözün arkasında durur.","dersler":[{"baslik":"Tatilin Arkasındaki Köprü","ilk":"os-4-001"},{"baslik":"Acentenin Bölümleri","ilk":"os-4-004"},{"baslik":"Küçük Acentede Herkes Her İşte","ilk":"os-4-129"},{"baslik":"Masanın Arkasındaki Üç Departman","ilk":"os-4-132"},{"baslik":"Satışın Verdiği Sözü Kim Tutar?","ilk":"os-4-008"},{"baslik":"Masanın Bu Tarafındakiler","ilk":"os-4-010"},{"baslik":"Bilgi, Bilet, Vize: Kim Bakar?","ilk":"os-4-014"},{"baslik":"Sahadaki Yüzler","ilk":"os-4-020"},{"baslik":"Bir Tatil Fikri Nasıl Tura Dönüşür?","ilk":"os-4-024"},{"baslik":"Satıştan Sahaya, Sahadan Ankete","ilk":"os-4-027"},{"baslik":"A, B, C: Kim Neye Yetkili?","ilk":"os-4-030"},{"baslik":"Gelen, Giden, Yurt İçi: Acente Türleri","ilk":"os-4-034"},{"baslik":"Toptancı mı, Perakendeci mi?","ilk":"os-4-037"},{"baslik":"Yeriniz Ayrıldı mı?","ilk":"os-4-041"},{"baslik":"Oda Var mı, Yok mu?","ilk":"os-4-046"},{"baslik":"Yolun Dili","ilk":"os-4-052"},{"baslik":"Fiyatın ve Ekranın Arkası","ilk":"os-4-056"},{"baslik":"Turu Kim Üretir, Kim Satar?","ilk":"os-4-062"},{"baslik":"Acente Açmak İçin Ne Gerekir?","ilk":"os-4-066"},{"baslik":"TÜRSAB Ne İş Yapar?","ilk":"os-4-069"},{"baslik":"Acenteyi Bağlayan Diğer Kurallar","ilk":"os-4-073"},{"baslik":"Dört Kanun, Bir Acente","ilk":"os-4-076"},{"baslik":"Bir Turun Arkasında Kaç İşletme Var?","ilk":"os-4-078"},{"baslik":"Devlet Tarafı","ilk":"os-4-085"},{"baslik":"Kısaltmalar Ormanı","ilk":"os-4-089"},{"baslik":"Sınırdan Geçmeden Önce","ilk":"os-4-095"},{"baslik":"Vize: Amacın Ne?","ilk":"os-4-097"},{"baslik":"Başvuru Dosyası","ilk":"os-4-104"},{"baslik":"Dosyada Hangi Kâğıtlar Olmalı?","ilk":"os-4-124"},{"baslik":"Dört Renk, Dört Pasaport","ilk":"os-4-110"},{"baslik":"Pasaport Nasıl Çıkarılır?","ilk":"os-4-115"},{"baslik":"Ya Yolda Bir Şey Olursa?","ilk":"os-4-118"}],"kavramlar":[{"id":"os-4-001","konu":"4.1","terim":"Seyahat acentesi","ingilizce":"Travel agency","tanim":"Turistlere bilgi veren, tur ve paket tur hazırlayan, konaklama, ulaştırma, gezi, spor ve eğlence hizmetlerini sağlayıp satan, kâr amaçlı ticari kuruluştur.","ornek":"Cumartesi 11.00, İzmir’de bir acente: dört kişilik bir aile Kapadokya’ya gitmek ister; görevli uçuşu, oteli ve balon turunu tek masada, tek görüşmede ayarlar.","sektor":"Tanım 1618 sayılı Kanun’a dayanır. Acente, hizmeti üreten otel ve hava yolu ile tatile çıkacak kişi arasında köprüdür: konuk onlarca işletmeyle tek tek uğraşmaz, güvendiği tek bir muhatapla konuşur.","iliskili":["os-4-002","os-4-003","os-4-066"],"kontrol":null,"cizim":"acente"},{"id":"os-4-002","konu":"4.1","terim":"Seyahat acentesinin hizmetleri","ingilizce":"Travel agency services","tanim":"Operasyon yürütme, biletleme, vize işlemleri, araç kiralama, bilgi verme ve turistik ürün satışı, bir acentenin konuğuna sunduğu altı temel iştir.","ornek":"Pazartesi 10.00: aynı acentede bir görevli Roma uçuşu için bilet keser, yan masadaki arkadaşı bir konuğun vize dosyasını hazırlar, operasyon ise akşamki havalimanı transferini planlar.","sektor":"Acenteye gelen konuk çoğu zaman tek bir iş için gelir, ama ihtiyacı birden fazladır: bilet alan kişiye otel, otel alan kişiye transfer gerekir. İyi acenteci bu ihtiyacı konuk söylemeden görür. Pasaport düzenleme ise acentenin işi değildir; pasaportu devlet, nüfus müdürlüğü çıkarır.","iliskili":["os-4-001","os-4-016","os-4-017"],"kontrol":null,"cizim":"acente"},{"id":"os-4-003","konu":"4.1","terim":"Acentenin organizasyon yapısı","ingilizce":"Organisational structure of a travel agency","tanim":"Bir işletmede kimin hangi işi yapacağını, kimin kime bağlı olduğunu ve bölümlerin birbiriyle nasıl çalışacağını gösteren düzendir.","ornek":"Orta ölçekli bir acentenin şemasında en üstte genel müdür, altında genel müdür yardımcısı, onun altında operasyon, satış, vize ve muhasebe sorumluları ile onlara bağlı personel yer alır.","sektor":"Küçük (butik) acentede satış ve operasyonu çoğu zaman aynı kişiler yürütür; acente büyüdükçe iş tanımları netleşir ve uzmanlaşma artar. Büyük ölçekli acentede ürün planlama ve satın alma, operasyon, satış ve pazarlama, finans ve muhasebe, müşteri ilişkileri ve insan kaynakları ayrı departmanlardır. Ders kitabındaki büyük ölçekli şemanın en üstünde yönetim kurulu ve CEO / genel müdür yer alır; altında ürün planlama ve satın alma, operasyon, satış ve pazarlama, finans ve muhasebe, müşteri ilişkileri (CRM) ve insan kaynakları bulunur. CRM, müşteri ilişkileri yönetimi demektir: konuğun tercihlerini kaydeder ve satıştan sonra da ilişkiyi sürdürür.","iliskili":["os-4-001","os-4-004","os-4-010"],"kontrol":null,"cizim":"acente"},{"id":"os-4-004","konu":"4.1","terim":"Operasyon departmanı","ingilizce":"Operations department","tanim":"Satılmış turun transfer, konaklama, rehberlik ve gezi gibi hizmetlerini sahada aksamadan yürüten bölümdür.","ornek":"Gece 02.30, Antalya Havalimanı: uçak bir saat gecikir; operasyon transfer aracının saatini değiştirir ve otele geç giriş olacağını bildirir.","sektor":"Konuk broşürü unutur, sahada yaşadığını hatırlar. Büyük ölçekli acentede ayrı bir departmandır ve genel müdüre bağlı çalışır; turist rehberi, otel rehberi ve transfer elemanı bu işin sahadaki yüzleridir.","iliskili":["os-4-005","os-4-028","os-4-012"],"kontrol":null,"cizim":"ekip"},{"id":"os-4-005","konu":"4.1","terim":"Rezervasyon bölümü","ingilizce":"Reservations department","tanim":"Turda kullanılacak otel odalarını ve uçak, otobüs gibi araçlardaki yerleri istenen tarih ve özelliklerde ayırtan bölümdür.","ornek":"Salı 09.15: rezervasyon görevlisi, cuma günkü Pamukkale turu için oteli arar ve grubun odalarının hazır olduğunu teyit ettirir.","sektor":"Ayırtılan her yer operasyona bildirilir; bildirilmeyen rezervasyon sahada sürpriz demektir. Tur tarihi yaklaştıkça yerler yeniden teyit edilir.","iliskili":["os-4-004","os-4-015","os-4-041"],"kontrol":null,"cizim":"resepsiyon"},{"id":"os-4-006","konu":"4.1","terim":"Satış ve pazarlama bölümü","ingilizce":"Sales and marketing department","tanim":"Acentenin ürünlerini hedef kitleye tanıtan ve satışını gerçekleştiren bölümdür.","ornek":"Mart ayında bir acente yaz turlarını sosyal medyada duyurur; arayan konuklara satış temsilcileri bütçelerine uygun seçenekleri anlatır.","sektor":"Satış konuğa söz verir; o sözün tutulabilmesi için neyin satıldığı operasyona eksiksiz aktarılmalıdır. Hazırlanan tur satılamazsa en iyi program da kâğıt üzerinde kalır.","iliskili":["os-4-013","os-4-009","os-4-004"],"kontrol":null},{"id":"os-4-007","konu":"4.1","terim":"Muhasebe bölümü","ingilizce":"Accounts department","tanim":"Acentenin gelir ve giderlerini kaydeden, otel ve ulaştırma firması gibi iş ortaklarına yapılacak ödemeleri takip eden bölümdür.","ornek":"Ay sonunda muhasebe elemanı, o ay çalışılan otellerin faturalarını kontrol eder ve ödeme günlerini takvime işler.","sektor":"Büyük acentelerde finans ve muhasebe adıyla ayrı bir departmandır. Ödemesini zamanında yapan acenteye otel yoğun sezonda da oda ayırır; iş ortakları arasındaki güven burada sınanır.","iliskili":["os-4-003","os-4-080"],"kontrol":null,"cizim":"para-butce"},{"id":"os-4-129","konu":"4.1","terim":"Genel müdür yardımcısı","ingilizce":"Deputy general manager","tanim":"Orta ölçekli acentede genel müdürün hemen altında yer alan, işlerin bir bölümünü onunla birlikte yürüten üst düzey yöneticidir.","ornek":"Genel müdür fuardayken pazartesi sabahı operasyon toplantısını genel müdür yardımcısı yapar ve haftanın turlarını gözden geçirir.","sektor":"Kitabın orta ölçekli acente şemasında (Şema 4.2) genel müdürün hemen altında yer alır. Sıra Sizde etkinliğindeki yönetim kademesi sıralamasında da bu unvan vardır.","iliskili":["os-4-011","os-4-003","os-4-130"],"kontrol":null,"cizim":"lider"},{"id":"os-4-130","konu":"4.1","terim":"Havalimanı operasyon sorumlusu","ingilizce":"Airport operations officer","tanim":"Orta ölçekli acentede havalimanındaki karşılama ve transfer işlerini yöneten, transfer elemanlarının çalışmasını düzenleyen görevlidir.","ornek":"Gece 01.15, Dalaman Havalimanı: uçak erken indiğinde sorumlu transfer elemanlarını yeniden görevlendirir ve araç sayısını artırır.","sektor":"Kitap bu unvanı orta ölçekli acentenin şemasında transfer elemanıyla birlikte gösterir. Havalimanında sorun çıktığında transfer elemanı sorumlusuna haber verir.","iliskili":["os-4-022","os-4-129","os-4-003"],"kontrol":null,"cizim":"ucak"},{"id":"os-4-131","konu":"4.1","terim":"Küçük ölçekli acente","ingilizce":"Small-scale travel agency","tanim":"Az sayıda personelle çalışan, bölümler yerine tek tek görevlilerin bulunduğu ve her kişinin birkaç işi birlikte yürüttüğü acentedir.","ornek":"Pazartesi 09.00, beş kişilik bir acentede: aynı görevli sabah konuğa Kapadokya turunu satar, öğleden sonra da turun transferini ayarlar.","sektor":"Kitaptaki Şema 4.1’de küçük ölçekli acentenin başında müdür bulunur; altında enformasyon, operasyon, rezervasyon, satış ve pazarlama sorumluları ile muhasebe elemanı, sahada ise turist rehberi, otel rehberi ve transfer elemanı yer alır. Acente büyüdükçe iş tanımları netleşir ve uzmanlaşma artar.","iliskili":["os-4-003","os-4-132","os-4-004"],"kontrol":null,"cizim":"acente"},{"id":"os-4-132","konu":"4.1","terim":"Ürün planlama ve satın alma departmanı","ingilizce":"Product planning and purchasing department","tanim":"Büyük acentede tur ürününü tasarlayan ve gereken hizmetleri otel, ulaşım gibi tedarikçilerden satın alan departmandır.","ornek":"Kasım ayında departman, gelecek yaz için Karadeniz yayla turunu çizer ve otellerle oda fiyatlarını görüşür.","sektor":"Kitabın büyük ölçekli acente şemasındaki (Şema 4.3) ilk departmandır. Operasyonel sürecin ilk iki aşaması olan planlama ile tedarik ve sözleşme bu bölümün işine denk düşer.","iliskili":["os-4-012","os-4-024","os-4-003"],"kontrol":null,"cizim":"ekip"},{"id":"os-4-133","konu":"4.1","terim":"Müşteri ilişkileri (CRM) departmanı","ingilizce":"Customer relationship management (CRM) department","tanim":"Büyük acentede konuklarla satıştan önce ve sonra iletişimi yürüten, tercihlerini ve geri bildirimlerini kayıt altında tutan departmandır.","ornek":"Tur dönüşünden bir hafta sonra departman konuklara anket gönderir, şikâyetleri not eder ve tercihlerini kaydeder.","sektor":"Kitapta büyük ölçekli şemada ayrı kutu olarak yer alır. Memnun kalan konuk yeniden gelir ve başkalarına önerir; bu yüzden satıştan sonraki iletişim de işin parçasıdır.","iliskili":["os-4-003","os-4-134","os-4-006"],"kontrol":null,"cizim":"ekip"},{"id":"os-4-134","konu":"4.1","terim":"İnsan kaynakları departmanı","ingilizce":"Human resources department","tanim":"Büyük acentede personelin işe alınması, eğitimi ve iş tanımlarının düzenlenmesiyle ilgilenen departmandır.","ornek":"Yaz sezonu öncesinde departman, havalimanı karşılama için transfer elemanı arar, adayları görüşür ve iş tanımını verir.","sektor":"Kitabın büyük ölçekli şemasında yer alır. İyi bir iş tanımı, çalışanın kendi sorumluluğunu bilmesini sağlar.","iliskili":["os-4-003","os-4-133","os-4-010"],"kontrol":null,"cizim":"ekip"},{"id":"os-4-008","konu":"4.1.1","terim":"Bölümler arası iş birliği","ingilizce":"Interdepartmental co-operation","tanim":"Acentedeki bölümlerin birbirinden kopuk değil, bilgiyi zamanında paylaşarak tek bir ekip gibi çalışmasıdır.","ornek":"Satış bölümü bir gruba vejetaryen menü sözü verir; bunu aynı gün operasyona yazar, operasyon da restorana bildirir. Konuk masaya oturduğunda yemeği hazırdır.","sektor":"Bölümlerin uzmanlığı kadar aralarındaki bilgi akışı da acentenin rekabet gücünü belirler. İş birliği güçlü olduğunda operasyondaki aksaklıklar ve konuk şikâyetleri azalır.","iliskili":["os-4-009","os-4-004","os-4-006"],"kontrol":null,"cizim":"is-birligi"},{"id":"os-4-009","konu":"4.1.1","terim":"Satış vaadi","ingilizce":"Sales promise","tanim":"Konuğa satış sırasında söylenen ya da yazılan ve tur boyunca yerine getirilmesi gereken sözdür.","ornek":"Broşürde “deniz manzaralı oda” yazıyorsa konuk kapıyı açtığında denizi görmeyi bekler; otoparka bakan oda, verilen sözün tutulmaması demektir.","sektor":"Satışın verdiği sözü sahada operasyon tutar. Tutulamayacak söz satış anında konuğu sevindirir, tatilde şikâyete döner; bu yüzden emin olunmayan şey vaat edilmez, önce sorulur.","iliskili":["os-4-008","os-4-006","os-4-028"],"kontrol":null},{"id":"os-4-010","konu":"4.1.2","terim":"İş tanımı","ingilizce":"Job description","tanim":"Bir çalışanın hangi işleri yapacağını ve nelerden sorumlu olduğunu yazılı olarak belirten açıklamadır.","ornek":"İşe yeni başlayan rezervasyon memuruna ilk gün görevlerinin yazılı olduğu belge verilir: hangi kayıtları tutacağı ve kime rapor vereceği bellidir.","sektor":"Acentedeki mesleklerin görev ve sorumlulukları Mesleki Yeterlilik Kurumunun (MYK) meslek standartlarında tanımlanmıştır. İş tanımı net olunca “Bu benim işim değildi” tartışması çıkmaz; iş sahipsiz kalmaz.","iliskili":["os-4-003","os-4-011","os-4-023"],"kontrol":null,"cizim":"acente"},{"id":"os-4-011","konu":"4.1.2","terim":"Seyahat acentesi yöneticisi","ingilizce":"Travel agency manager","tanim":"Acentenin bütün faaliyetlerini yürüten, çalışanları yöneten, satışları denetleyen ve bütçeyi takip eden kişidir.","ornek":"Pazartesi 08.45: yönetici haftalık toplantıda o hafta çıkacak turları, eksik rezervasyonları ve gelen bir konuk şikâyetini ekibiyle gözden geçirir.","sektor":"Küçük acentede unvanı acente müdürü, orta ve büyük acentede genel müdürdür; işlerin bir bölümünü genel müdür yardımcısına devreder. Operasyon bittikten sonraki işlemlerin tamamlanmasından da o sorumludur.","iliskili":["os-4-003","os-4-010","os-4-012"],"kontrol":null,"cizim":"acente"},{"id":"os-4-012","konu":"4.1.2","terim":"Ürün planlama ve operasyon sorumlusu","ingilizce":"Product planning and operations officer","tanim":"Acentenin konuklara sunacağı turu tasarlayan, pazarlanmasını ve satıldığı biçimde uygulanmasını sağlayan kişidir.","ornek":"Kış başında Karadeniz yayla turunu planlar: güzergâhı çizer, otellerle görüşür; yazın tur çıktığında programın söz verildiği gibi yürüdüğünü takip eder.","sektor":"Ürünü kâğıtta kuran da sahada yürüten de aynı sorumluluk zincirindedir. Sahadaki ekip (rehber, otel rehberi, transfer elemanı) onun planına göre hareket eder.","iliskili":["os-4-004","os-4-025","os-4-018"],"kontrol":null,"cizim":"grafik"},{"id":"os-4-013","konu":"4.1.2","terim":"Seyahat acentesi satış görevlisi","ingilizce":"Travel sales consultant","tanim":"Acentenin her türlü ürününü yerli ve yabancı konuklara tanıtan ve satan kişidir.","ornek":"Saat 14.00: balayı için gelen çifte satış görevlisi önce bütçelerini ve beklentilerini sorar, sonra üç seçenek sunar.","sektor":"Şemalarda satış temsilcisi olarak da geçer. İyi satış en pahalı ürünü değil, doğru ürünü satmaktır: memnun dönen konuk ertesi yıl yine aynı masaya oturur.","iliskili":["os-4-006","os-4-009","os-4-043"],"kontrol":null,"cizim":"acente"},{"id":"os-4-014","konu":"4.1.2","terim":"Enformasyon memuru","ingilizce":"Information officer","tanim":"Konuklara seyahat, vize, gümrük, döviz ve gidilecek yer hakkında doğru bilgi veren acente görevlisidir.","ornek":"Bir konuk “Bu ülkeye kimlikle girilir mi?” diye sorar; enformasyon memuru ezberden cevaplamaz, güncel kuralı resmî kaynaktan kontrol edip öyle söyler.","sektor":"Küçük acentenin şemasında da orta ölçekli acentenin şemasında da yer alan bir görevdir. Yanlış bilgi, sınır kapısından geri dönen bir konuk demektir; bu yüzden bilmediğini tahmin etmez.","iliskili":["os-4-017","os-4-095","os-4-096"],"kontrol":null},{"id":"os-4-015","konu":"4.1.2","terim":"Acente rezervasyon memuru","ingilizce":"Agency reservations clerk","tanim":"Konaklama, ulaştırma ve yemek için gereken yerleri ayırtan ve kayıtlarını tutan görevlidir.","ornek":"Saat 16.40: memur otelden gelen onay e-postasını dosyaya ekler ve oda sayısını tur listesiyle karşılaştırır.","sektor":"Tek bir tarih ya da isim hatası, sahada kapıda kalan konuk demektir. İyi rezervasyon memuru her kaydı iki kez okur; sözlü onayla yetinmez, yazılı teyit ister.","iliskili":["os-4-005","os-4-041","os-4-044"],"kontrol":null,"cizim":"resepsiyon"},{"id":"os-4-016","konu":"4.1.2","terim":"Bilet personeli","ingilizce":"Ticketing agent","tanim":"Uçak, otobüs, tren ve gemi gibi ulaştırma araçlarının biletlerini konuk adına düzenleyen acente görevlisidir.","ornek":"Bilet personeli konuğun adını ve soyadını pasaportuna bakarak harf harf yazar, ekrandaki kaydı konuğa bir kez de sesli okur.","sektor":"Biletteki ad, kimlik ya da pasaporttaki adla aynı olmalıdır; küçük bir yazım hatası yolcuya havalimanında sorun çıkarır. Rezervasyon sistemlerini kullanmayı bilmek bu görevin temel becerisidir.","iliskili":["os-4-042","os-4-058","os-4-002"],"kontrol":null},{"id":"os-4-017","konu":"4.1.2","terim":"Vize sorumlusu","ingilizce":"Visa officer","tanim":"Yurt dışı seyahatlerinde konuk adına vize başvurusunun evrakını hazırlayan ve süreci takip eden görevlidir.","ornek":"Vize sorumlusu konuğa gereken belgelerin listesini verir, eksik banka dökümünü fark eder ve randevu gününden önce tamamlatır.","sektor":"Acentenin sunduğu vize danışmanlığı ve başvuru takibi hizmetine sektörde “visa handling” denir. Vizeyi acente değil, gidilecek ülkenin konsolosluğu verir; bu yüzden konuğa “Vizeniz kesin çıkar” sözü verilmez.","iliskili":["os-4-097","os-4-108","os-4-106"],"kontrol":null,"cizim":"pasaport"},{"id":"os-4-018","konu":"4.1.2","terim":"Tur sorumlusu","ingilizce":"Tour co-ordinator","tanim":"Satılan turun dosyasını hazırlayıp rehbere, şoföre ve otele gereken bilgilerin ulaşmasını sağlayan görevlidir.","ornek":"Perşembe 17.00: tur sorumlusu ertesi sabah çıkacak Efes turunun katılımcı listesini, kalkış noktalarını ve saatlerini rehbere teslim eder.","sektor":"Dosyada kimin, ne zaman, nereden alınacağı ve nerede kalacağı yazar. Dosyadaki tek yanlış saat, sahada bütün bir grubun beklemesi demektir.","iliskili":["os-4-012","os-4-054","os-4-020"],"kontrol":null,"cizim":"acente"},{"id":"os-4-019","konu":"4.1.2","terim":"MICE sorumlusu","ingilizce":"MICE co-ordinator","tanim":"Toplantı, teşvik gezisi, konferans ve sergi gibi iş amaçlı etkinliklerin organizasyonunu yürüten acente görevlisidir.","ornek":"Bir firma Antalya’da üç günlük bayi toplantısı ister; MICE sorumlusu salonu, konaklamayı, transferleri ve gala yemeğini tek programda toplar.","sektor":"MICE; Meetings, Incentives, Conferences, Exhibitions sözcüklerinin baş harfleridir. Bu etkinliklerde konuk tatilci değil, iş insanıdır: dakiklik ve teknik hazırlık her şeyden önce gelir.","iliskili":["os-4-061","os-4-003"],"kontrol":null},{"id":"os-4-020","konu":"4.1.2","terim":"Profesyonel turist rehberi","ingilizce":"Professional tourist guide","tanim":"Bakanlıkça yetkilendirilmiş olarak yerli ve yabancı konuklara tarihî, kültürel ve doğal değerleri doğru bilgiyle tanıtan ve gezi programını yöneten uzman kişidir.","ornek":"Sabah 09.30, Efes Antik Kenti: rehber grubunu Celsus Kütüphanesi’nin önünde toplar, anlatımını yapar ve eserlere dokunulmaması gerektiğini hatırlatır.","sektor":"6326 sayılı Turist Rehberliği Meslek Kanunu’na göre rehberlik odasına kayıtlı çalışır. Kültür varlıklarının korunmasına özen göstermek de görevidir. Konuk ülkeyi rehberin gözünden tanır.","iliskili":["os-4-089","os-4-054","os-4-023"],"kontrol":null,"cizim":"acente"},{"id":"os-4-121","konu":"4.1.2","terim":"Rehber kokartı","ingilizce":"Tourist guide badge (guide licence card)","tanim":"Kültür ve Turizm Bakanlığı tarafından verilen, kişinin profesyonel turist rehberi olarak çalışmaya yetkili olduğunu gösteren belgedir.","ornek":"Sabah 08.45, otel lobisi: rehber yakasındaki kokartıyla tur otobüsüne binecek grubun karşısına çıkar ve kendini tanıtır.","sektor":"Ders kitabına göre profesyonel turist rehberi, rehberlik odasına kayıtlıdır ve Bakanlığın verdiği kokartla yetkilendirilmiştir. Acente rehber bulurken kokart sahibi olup olmadığına bakar; kokartsız kişiye rehberlik yaptırmak hem acenteyi hem konuğu riske sokar.","iliskili":["os-4-020","os-4-089","os-4-086"],"kontrol":null,"cizim":"acente"},{"id":"os-4-021","konu":"4.1.2","terim":"Otel rehberi","ingilizce":"Hotel representative","tanim":"Acentenin konuklarını otelde karşılayan, konaklama boyunca sorularını yanıtlayan ve sorunlarını otelle birlikte çözen acente görevlisidir.","ornek":"Sabah 10.00, lobi: otel rehberi yeni gelen konuklara bilgilendirme toplantısı yapar; dönüş transfer saatlerini ve ek turları anlatır.","sektor":"Konuğun oteldeki “acentesi”dir. Sorunu konuk adına resepsiyonla tartışarak değil, resepsiyonla birlikte çalışarak çözer; çözemediğini operasyona bildirir.","iliskili":["os-4-022","os-4-034","os-4-004"],"kontrol":null,"cizim":"otel-bina"},{"id":"os-4-022","konu":"4.1.2","terim":"Transfer elemanı","ingilizce":"Transfer representative","tanim":"Konukları havalimanı, otel ve gezi noktaları arasında karşılayan, araca yönlendiren ve yol boyunca onlara eşlik eden görevlidir.","ornek":"Gece 01.15, havalimanı gelen yolcu çıkışı: transfer elemanı elinde acentenin tabelasıyla bekler, listesindeki konukları tek tek işaretleyip araca alır.","sektor":"Sektörde transferman da denir; orta ölçekli acentelerde havalimanındaki işleri havalimanı operasyon sorumlusu yönetir. Ders kitabına göre bu görevde çalışmak için Transfer Elemanı Kimlik Kartı gerekir. Konuğun Türkiye’de gördüğü ilk yüz çoğu zaman odur; listede eksik ya da fazla kişi varsa kendi başına karar vermez, operasyonu arar.","iliskili":["os-4-055","os-4-021","os-4-004"],"kontrol":null},{"id":"os-4-023","konu":"4.1.2","terim":"Meslek etiği","ingilizce":"Professional ethics","tanim":"Bir mesleği yaparken uyulması gereken doğruluk, dürüstlük, gizlilik, tarafsızlık, yasalara saygı ve mesleki sorumluluk gibi ilkelerin bütünüdür.","ornek":"Rehber, programda yazan köy pazarını “Zaman kalmadı” diyerek atlayıp grubu yalnız komisyon aldığı mağazaya götürürse konuğun hakkını çiğnemiş olur.","sektor":"Hizmet kalitesini yalnız mesleki bilgi değil, iletişim becerisi ve etik duruş da belirler. Konuğun pasaport bilgisini izinsiz paylaşmamak gizlilik ilkesidir. Etik dışı tek bir davranış acentenin adını, hatta ülkenin turizm imajını zedeler.","iliskili":["os-4-077","os-4-083","os-4-071"],"kontrol":null,"cizim":"egitim-kariyer"},{"id":"os-4-128","konu":"4.1.2","terim":"Mesleki Yeterlilik Kurumu (MYK)","ingilizce":"Vocational Qualifications Authority (MYK)","tanim":"Türkiye’de mesleklerin standartlarını ve yeterlilik koşullarını belirleyen kamu kurumudur.","ornek":"Pazartesi 09.00, staj öncesi hazırlık: öğrenci, acentede çalışacağı rezervasyon memurunun görevlerini meslek standardından tek tek okur.","sektor":"Kitap, acente mesleklerinin görev ve sorumluluklarını (Tablo 4.1) MYK’ya göre verir; iş tanımının dayanağı bu standartlardır.","iliskili":["os-4-010","os-4-020"],"kontrol":null,"cizim":"egitim-kariyer"},{"id":"os-4-024","konu":"4.2","terim":"Operasyonel süreç","ingilizce":"Operational process","tanim":"Bir seyahat fikrinin doğmasından konuğun evine dönmesine ve seyahatin değerlendirilmesine kadar acentede yürütülen işlerin bütünüdür.","ornek":"Bir Ege turu ocakta planlanır, şubatta oteller ve otobüs firmasıyla anlaşılır, martta satışa çıkar, mayısta yapılır; haziranda konukların görüşleri değerlendirilir.","sektor":"Beş aşaması vardır: planlama ve geliştirme, tedarik ve sözleşme, satış–pazarlama–rezervasyon, turun gerçekleşmesi ve satış sonrası değerlendirme. Arka plandaki düzen iyi işlerse konuk yalnız rahat bir tatil görür ve acenteye bağlanır.","iliskili":["os-4-025","os-4-026","os-4-028"],"kontrol":null,"cizim":"saat-zaman"},{"id":"os-4-025","konu":"4.2","terim":"Seyahatin planlanması ve geliştirilmesi","ingilizce":"Travel planning and product development","tanim":"Turun nereye, ne zaman, kimler için ve hangi hizmetlerle yapılacağının araştırılıp tasarlandığı ilk aşamadır.","ornek":"Ürün planlama sorumlusu, lise gezileri için iki günlük bir Çanakkale programı tasarlar: şehitlik ziyareti, müze, konaklama ve yemek molaları saat saat belirlenir.","sektor":"Kötü planlanan tur sahada düzelmez. Mesafeler, müze kapanış saatleri ve mevsim bu aşamada hesaba katılmazsa sonraki dört aşama da aksar.","iliskili":["os-4-024","os-4-012","os-4-026"],"kontrol":null},{"id":"os-4-026","konu":"4.2","terim":"Tedarik süreci ve sözleşme","ingilizce":"Procurement and contracting","tanim":"Tasarlanan tur için gereken oda, koltuk, yemek ve rehberlik gibi hizmetlerin işletmelerden sağlanması ve yazılı anlaşmaya bağlanmasıdır.","ornek":"Acente, yaz sezonu için Bodrum’daki bir otelle oda fiyatını, tarihleri ve iptal koşullarını yazan bir sözleşme imzalar.","sektor":"Sürecin ikinci aşamasıdır. Hizmeti sağlayan otel, hava yolu, restoran gibi işletmelere tedarikçi denir. Sözlü anlaşma yoğun sezonda unutulur; yazılı sözleşme hem acenteyi hem konuğu korur.","iliskili":["os-4-025","os-4-079","os-4-057"],"kontrol":null,"cizim":"sozlesme"},{"id":"os-4-027","konu":"4.2","terim":"Satış, pazarlama ve rezervasyon aşaması","ingilizce":"Sales, marketing and booking stage","tanim":"Hazırlanan ürünün tanıtıldığı, konuğa satıldığı ve konuk adına yerlerin kayda geçirildiği aşamadır.","ornek":"Tur internet sitesinde yayımlanır; arayan konuğun adı, kişi sayısı ve ödeme bilgisi kaydedilir, yeri ayrılır.","sektor":"Sürecin üçüncü aşamasıdır. Kayıttaki her bilgi sonraki aşamada operasyonun elindeki tek kaynaktır; eksik yazılan özel istek, sahada unutulmuş istek olur.","iliskili":["os-4-024","os-4-041","os-4-006"],"kontrol":null,"cizim":"megafon"},{"id":"os-4-028","konu":"4.2","terim":"Saha operasyonu","ingilizce":"Field operations","tanim":"Turun fiilen gerçekleştiği; karşılama, transfer, konaklama, rehberlik ve gezilerin uygulandığı aşamadır.","ornek":"Sabah 07.30: otobüs otelin önündedir, rehber listeyi kontrol eder, operasyon öğle yemeği yenecek restoranı arayıp kişi sayısını doğrular.","sektor":"Sürecin dördüncü aşaması ve konuğun gördüğü tek kısımdır. Aylarca süren hazırlık burada birkaç günde sınanır; aksaklık hemen operasyona bildirilir, saklanmaz.","iliskili":["os-4-004","os-4-024","os-4-029"],"kontrol":null,"cizim":"grafik"},{"id":"os-4-029","konu":"4.2","terim":"Satış sonrası değerlendirme","ingilizce":"Post-sale evaluation","tanim":"Seyahat bittikten sonra konuklardan geri bildirim alınıp turun güçlü ve zayıf yönlerinin incelendiği son aşamadır.","ornek":"Tur dönüşü yapılan ankette konukların çoğu öğle yemeği molasını kısa bulur; acente bir sonraki turda molayı uzatır.","sektor":"Sürecin beşinci aşamasıdır ve bir sonraki turun planlamasını besler. Şikâyet, ücretsiz bir danışmanlıktır: dinleyen acente aynı hatayı ikinci kez yapmaz.","iliskili":["os-4-024","os-4-028","os-4-025"],"kontrol":null,"gorsel":"h4-geri-bildirim-karti"},{"id":"os-4-030","konu":"4.2.1","terim":"Seyahat acentelerinin sınıflandırılması","ingilizce":"Classification of travel agencies","tanim":"Acentelerin yasal, fonksiyonel ve yapısal olmak üzere üç ayrı ölçüte göre gruplara ayrılmasıdır.","ornek":"Aynı acente yasal olarak A grubu, fonksiyonel olarak karşılayıcı, yapısal olarak perakendeci olabilir.","sektor":"Yasal: A, B, C grubu. Fonksiyonel: karşılayıcı (incoming), yurt dışı gönderici (outgoing), yurt içi gönderici (ingoing). Yapısal: toptancı, perakendeci, zincir. Üç ölçüt birbirinin yerine geçmez; acenteye üç ayrı pencereden bakar.","iliskili":["os-4-031","os-4-034","os-4-037"],"kontrol":null,"cizim":"acente"},{"id":"os-4-031","konu":"4.2.1","terim":"A grubu seyahat acentesi","ingilizce":"Group A travel agency","tanim":"Paket tur düzenleme, biletleme ve transfer dâhil bütün acentelik faaliyetlerini yapmaya yetkili, en geniş kapsamlı acente grubudur.","ornek":"Almanya’dan gelen bir grubu karşılayan, aynı hafta Türk konuklarını Balkan turuna gönderen acente A grubu olmak zorundadır.","sektor":"Türkiye’de tur operatörü işlevini de A grubu acenteler yerine getirir; bunun için ayrı bir hukuki düzenleme yoktur. Yetki geniş olduğu için sorumluluk da geniştir.","iliskili":["os-4-032","os-4-033","os-4-062"],"kontrol":null,"cizim":"acente"},{"id":"os-4-032","konu":"4.2.1","terim":"B grubu seyahat acentesi","ingilizce":"Group B travel agency","tanim":"Uluslararası kara, deniz ve hava ulaştırma araçlarının biletlerini ve A grubu acentelerin düzenlediği turların biletlerini satmaya yetkili acente grubudur.","ornek":"Bir B grubu acente, konuğuna Atina uçak biletini keser ve A grubu bir acentenin hazırladığı Yunan Adaları turunu satar; ama o turu kendisi düzenleyemez.","sektor":"Kendi adına tur düzenleme yetkisi yoktur. Sınavda en çok karıştırılan nokta: B grubu, C grubunun değil A grubunun turlarının biletini satar.","iliskili":["os-4-031","os-4-033","os-4-030"],"kontrol":null,"cizim":"acente"},{"id":"os-4-033","konu":"4.2.1","terim":"C grubu seyahat acentesi","ingilizce":"Group C travel agency","tanim":"Yalnızca Türk vatandaşları için yurt içi turlar düzenleyip satmaya yetkili acente grubudur.","ornek":"Bir C grubu acente, Ankara’dan kalkan hafta sonu Safranbolu–Amasra turunu düzenler; yurt dışı turu düzenleyemez.","sektor":"Üç grubun en dar yetkilisidir. Konuk, acentenin belge grubuna bakarak ondan hangi hizmeti alabileceğini anlayabilir; acente de yetkisini aşan işi satmaz.","iliskili":["os-4-031","os-4-032","os-4-036"],"kontrol":null,"cizim":"acente"},{"id":"os-4-034","konu":"4.2.1","terim":"Karşılayıcı (incoming) acente","ingilizce":"Incoming (inbound) agency","tanim":"Yurt dışındaki tur operatörlerinin gönderdiği konukları Türkiye’de karşılayan ve seyahatleri boyunca onlarla ilgilenen acentedir.","ornek":"İngiltere’den Dalaman’a inen grubu havalimanında karşılayıp Marmaris’teki otele götüren, tatil boyunca sorunlarıyla ilgilenen acente karşılayıcıdır.","sektor":"Tur operatörünün Türkiye’deki temsilcisi ve konuğun buradaki muhatabıdır; havalimanı–otel transferlerini o düzenler. Operatörün gözünde Türkiye’nin kalitesi, bu acentenin kalitesi kadardır.","iliskili":["os-4-035","os-4-036","os-4-055"],"kontrol":null,"cizim":"acente"},{"id":"os-4-035","konu":"4.2.1","terim":"Yurt dışı gönderici (outgoing) acente","ingilizce":"Outgoing (outbound) agency","tanim":"Yerli konukları başka ülkelere gönderen, yurt dışı turlar düzenleyen acentedir.","ornek":"İstanbul’daki bir acente, bayram tatili için Prag–Viyana–Budapeşte turu hazırlar ve katılacak konukların vize dosyalarını takip eder.","sektor":"Vize, pasaport ve gümrük işlemleri de işin içine girdiği için yapısı daha karmaşıktır; küçük çaplı bir tur operatörü gibi çalışır.","iliskili":["os-4-034","os-4-036","os-4-017"],"kontrol":null,"cizim":"acente"},{"id":"os-4-036","konu":"4.2.1","terim":"Yurt içi gönderici (ingoing) acente","ingilizce":"Domestic (ingoing) agency","tanim":"Ülkede yaşayan kişiler için yurt içinde turlar düzenleyen acentedir.","ornek":"İzmir’den kalkan otobüslü Kapadokya turunda konuklar, güzergâh üzerindeki Uşak ve Afyonkarahisar’dan da tura katılabilir.","sektor":"Konaklama, yeme içme, ulaşım ve rehberlik hizmetini sağlar; konuğu güzergâhta kendisine en yakın noktadan alır, gerekirse transfer düzenler. “Incoming” ile karıştırılmamalıdır: incoming yabancı konuğu karşılar, ingoing yerli konuğu yurt içinde gezdirir.","iliskili":["os-4-034","os-4-035","os-4-033"],"kontrol":null,"cizim":"acente"},{"id":"os-4-037","konu":"4.2.1","terim":"Toptancı seyahat acentesi","ingilizce":"Wholesale travel agency","tanim":"Otel, hava yolu, transfer gibi tedarikçilerden büyük miktarda hizmet satın alıp bunları perakendeci acentelere satan acentedir.","ornek":"Bir toptancı, yaz için bir otelden çok sayıda geceleme satın alır ve bu odaları küçük acentelere dağıtır.","sektor":"Çok alan ucuza alır: yüksek hacim birim maliyeti düşürür. Son tüketiciyle değil, başka acentelerle çalışır; buna işletmeden işletmeye satış, yani B2B (business-to-business) denir.","iliskili":["os-4-038","os-4-040","os-4-056"],"kontrol":null,"cizim":"acente"},{"id":"os-4-038","konu":"4.2.1","terim":"Perakendeci seyahat acentesi","ingilizce":"Retail travel agency","tanim":"Tur, konaklama, ulaşım ve ek hizmetleri doğrudan son tüketiciye, yani konuğun kendisine satan acentedir.","ornek":"Mahalledeki acenteye giren emekli çift, vitrindeki Karadeniz turunu sorar; görevli onlara programı anlatır ve satışı yapar.","sektor":"Türkiye’de en yaygın acente türüdür ve genellikle komisyon karşılığı çalışır. Gücü konuk ilişkisindedir: danışmanlık yapar, kişinin ihtiyacına göre ürün seçer.","iliskili":["os-4-037","os-4-039","os-4-040"],"kontrol":null,"cizim":"acente"},{"id":"os-4-039","konu":"4.2.1","terim":"Komisyon","ingilizce":"Commission","tanim":"Acentenin, satışına aracılık ettiği ürün ya da hizmetin bedeli üzerinden aldığı paydır.","ornek":"Acente bir otelin odasını konuğa satar; otel, satış bedelinin önceden anlaşılan bir bölümünü acenteye bırakır.","sektor":"Perakendeci acentenin temel geliridir. Komisyon gizli bir kazanç değil, sözleşmeyle belirlenmiş aracılık ücretidir; konuğu yalnız yüksek komisyon veren yere yönlendirmek ise etik değildir.","iliskili":["os-4-038","os-4-056","os-4-064"],"kontrol":null,"cizim":"acente"},{"id":"os-4-040","konu":"4.2.1","terim":"Zincir seyahat acentesi","ingilizce":"Travel agency chain","tanim":"Birden çok şubesi bulunan, yurt içinde ve yurt dışında faaliyet gösterebilen acentedir.","ornek":"Aynı tabelayı taşıyan acentenin Ankara, İzmir ve Antalya şubelerinde konuk aynı turu aynı fiyat ve aynı koşullarla bulur.","sektor":"Toptancı ya da perakendeci işlevi görebilir; onu ayıran şube ağıdır. İki avantajı vardır: standartlaşma (her şubede aynı hizmet) ve ölçek avantajı (toplu alım, ortak tanıtım). Asıl sınavı merkezden kalite kontrolüdür.","iliskili":["os-4-037","os-4-038","os-4-030"],"kontrol":null,"cizim":"otel-bina"},{"id":"os-4-041","konu":"4.2.2","terim":"Rezervasyon (booking)","ingilizce":"Booking (reservation)","tanim":"Konuk için uçak, otel, tur ya da başka bir hizmetin önceden ayrılmasıdır.","ornek":"Ağustos tatili için mayısta otel odası ayırtan konuğun kaydı bir rezervasyon numarasıyla saklanır.","sektor":"Genellikle bir rezervasyon numarası ya da PNR ile takip edilir. Acentede “booking” sözcüğü her gün duyulur; overbooking, opsiyon ve no-show gibi pek çok terim onun üzerine kuruludur.","iliskili":["os-4-042","os-4-043","os-4-044"],"kontrol":null},{"id":"os-4-042","konu":"4.2.2","terim":"PNR","ingilizce":"PNR (Passenger Name Record)","tanim":"Hava yolu rezervasyonunda yolcunun adı, uçuşu ve rotası gibi bilgilerin saklandığı kayıt ve bu kayda ulaşmayı sağlayan rezervasyon kodudur.","ornek":"Konuk havalimanındaki kiosk cihazına biletindeki kodu ve soyadını yazar; uçuş bilgileri ekrana gelir.","sektor":"Ders kitabına göre harf ve rakamlardan oluşan altı haneli bir koddur. Konuk bilet değişikliği için aradığında acentecinin ilk sorusu budur: “PNR numaranız nedir?”","iliskili":["os-4-041","os-4-016","os-4-058"],"kontrol":null,"cizim":"doga"},{"id":"os-4-043","konu":"4.2.2","terim":"Opsiyon","ingilizce":"Option (option date)","tanim":"Kesinleşmemiş bir rezervasyonda, ödemenin yapılması için tanınan son tarih ya da süredir.","ornek":"Satış görevlisi “Yerinizi cuma 17.00’ye kadar tutabiliyorum efendim” der; konuk o saate kadar ödeme yapmazsa yer başkasına satılır.","sektor":"Opsiyon tarihi konuğa açıkça söylenir. Süreyi uzatmak için yeri ayıran otelin ya da hava yolunun onayı gerekir; görevli kendi başına söz vermez.","iliskili":["os-4-041","os-4-044","os-4-013"],"kontrol":null,"cizim":"saat-zaman"},{"id":"os-4-044","konu":"4.2.2","terim":"Konfirmasyon","ingilizce":"Confirmation","tanim":"Rezervasyonun kesinleştiğinin, hizmeti verecek işletme tarafından yazılı olarak onaylanmasıdır.","ornek":"Otel, acentenin gönderdiği rezervasyon talebine “Onaylanmıştır” yanıtını ve bir onay numarasını e-postayla yollar.","sektor":"Sektörde “konfirme almak” denir. Onayı gelmemiş rezervasyon, yapılmamış rezervasyon gibidir; konuğa “Yeriniz hazır” demeden önce yazılı onay beklenir.","iliskili":["os-4-041","os-4-043","os-4-045"],"kontrol":null,"kitapDisi":true,"cizim":"acente"},{"id":"os-4-045","konu":"4.2.2","terim":"Voucher","ingilizce":"Voucher","tanim":"Konuğun bir hizmeti satın aldığını kanıtlayan; üzerinde konaklama, transfer ya da tur ayrıntılarının yazdığı hizmet belgesidir.","ornek":"Konuk otele vardığında resepsiyona acentenin verdiği voucherı gösterir; görevli tarihleri ve oda tipini belgeden kontrol eder.","sektor":"Hizmet çeki de denir. Konuk için “bu hizmeti satın aldım” belgesidir; otel de konuğu bu belgeyle tanır. Üzerindeki bilgi rezervasyonla aynı olmalıdır; fark varsa konukla tartışılmaz, acente aranır.","iliskili":["os-4-041","os-4-044","os-4-080"],"kontrol":null,"cizim":"bilet"},{"id":"os-4-046","konu":"4.2.2","terim":"Overbooking","ingilizce":"Overbooking","tanim":"Bir işletmenin, bazı rezervasyonların iptal olacağını hesaplayarak kapasitesinden fazla rezervasyon kabul etmesidir.","ornek":"Bir otel her gün birkaç iptal olduğunu bildiği için oda sayısından fazla rezervasyon alır; o gün herkes gelirse birkaç konuğa oda kalmaz.","sektor":"Amaç odanın ya da koltuğun boş kalmamasıdır. Açıkta kalan konuk çoğunlukla aynı ya da daha üst sınıf bir tesise yerleştirilir; acente görevlisi durumu hemen operasyona bildirir.","iliskili":["os-4-048","os-4-047","os-4-041"],"kontrol":null,"cizim":"resepsiyon"},{"id":"os-4-047","konu":"4.2.2","terim":"Stop-sale","ingilizce":"Stop-sale","tanim":"Tedarikçinin belirli bir dönem için satışı geçici olarak durdurması ve bunu acentelere bildirmesidir.","ornek":"Bir otel bayram haftası için dolduğunu görünce acentelere “Şu tarihler arasında satış durdurulmuştur” mesajı gönderir.","sektor":"Mesajı görmeden satış yapan acente, olmayan bir odayı satmış olur. Bu yüzden satıştan önce güncel durum her seferinde sistemden kontrol edilir.","iliskili":["os-4-046","os-4-057","os-4-041"],"kontrol":null,"gorsel":"h4-tukendi-notu"},{"id":"os-4-048","konu":"4.2.2","terim":"No-show","ingilizce":"No-show","tanim":"Rezervasyonu olduğu hâlde konuğun, iptal ettirmeden hizmetin verileceği yere gelmemesi durumudur.","ornek":"Konuk 20.00 uçuşuna bilet almıştır; haber vermeden havalimanına gelmez, koltuğu boş gider.","sektor":"Genellikle ücret iadesi yapılmaz, çünkü yer başkasına satılamamıştır. Vize gecikmesi ya da hastalık herkesin başına gelebilir; asıl hata bunun işletmeye zamanında bildirilmemesidir.","iliskili":["os-4-049","os-4-050","os-4-051"],"kontrol":null},{"id":"os-4-049","konu":"4.2.2","terim":"Go-show","ingilizce":"Go-show","tanim":"Rezervasyonu olmadığı hâlde hizmet almak üzere doğrudan gelen yolcu ya da konuktur.","ornek":"Sabah 06.00, havalimanı bankosu: rezervasyonu olmayan bir yolcu, boş koltuk çıkar umuduyla uçuşun check-in sırasında bekler.","sektor":"No-show’un tersidir. Otelde rezervasyonsuz gelen konuğa walk-in denir. Acente, son dakika satışını hizmeti verecek işletmeye bildirmezse konuk sahada go-show gibi görünür; bu yüzden her satış aynı gün teyit ettirilir.","iliskili":["os-4-048","os-4-044","os-4-046"],"kontrol":null,"kitapDisi":true,"cizim":"acente"},{"id":"os-4-050","konu":"4.2.2","terim":"Son dakika satışı","ingilizce":"Last-minute sale","tanim":"Dolmayan yerlerin, hizmet tarihine çok az kala indirimli fiyatla satışa sunulmasıdır.","ornek":"Cuma günü çıkacak turda iki konuğun vizesi yetişmez; acente boşalan iki yeri çarşamba günü indirimli olarak duyurur.","sektor":"Sektörde “last minute” diye anılır. Boş giden koltuğun ve boş kalan odanın geliri bir daha geri gelmez; son dakika satışı bu kaybı azaltır.","iliskili":["os-4-048","os-4-065","os-4-041"],"kontrol":null,"cizim":"saat-zaman"},{"id":"os-4-051","konu":"4.2.2","terim":"İptal koşulları","ingilizce":"Cancellation policy","tanim":"Rezervasyonun hangi tarihe kadar ücretsiz iptal edilebileceğini ve sonrasında ne kadar kesinti yapılacağını belirleyen kurallardır.","ornek":"Satış görevlisi sözleşmeyi imzalatmadan önce “Şu tarihten sonra iptalde kesinti uygulanır” diyerek ilgili maddeyi konuğa gösterir.","sektor":"Koşullar otelden otele, turdan tura değişir. Satış anında açıkça söylenmeyen iptal koşulu, sonradan en sık şikâyet konusu olan başlıklardandır.","iliskili":["os-4-048","os-4-043","os-4-074"],"kontrol":null,"kitapDisi":true,"cizim":"sozlesme"},{"id":"os-4-052","konu":"4.2.2","terim":"Charter","ingilizce":"Charter flight","tanim":"Belirli bir grup ya da acente için kiralanan tarifesiz uçuştur.","ornek":"Yaz sezonunda bir tur operatörü, konuklarını her cumartesi Düsseldorf’tan Antalya’ya kiraladığı uçakla getirir.","sektor":"Genellikle paket turlarda kullanılır. Uçağın tamamı kiralandığı için boş kalan her koltuk kiralayanın zararıdır.","iliskili":["os-4-062","os-4-063","os-4-065"],"kontrol":null,"cizim":"ucak"},{"id":"os-4-053","konu":"4.2.2","terim":"Stopover","ingilizce":"Stopover","tanim":"Uzun yolculuklarda varış noktasına ulaşmadan önce aktarma noktasında verilen ara duraktır.","ornek":"İstanbul’dan Tokyo’ya giden konuk, yolculuğunu Doha’da bölerek iki uçuş arasında şehirde bir gece geçirir.","sektor":"Biletleme ve konaklama planlamasında önemlidir: ara durakta otel, transfer, hatta vize gerekebilir. Acente aktarma süresini ve o ülkenin giriş kurallarını konuğa önceden söyler.","iliskili":["os-4-101","os-4-054","os-4-016"],"kontrol":null},{"id":"os-4-054","konu":"4.2.2","terim":"Itinerary","ingilizce":"Itinerary","tanim":"Tur ya da seyahat boyunca izlenecek güzergâhı, saatleri ve hizmetlerin sırasını gösteren programdır.","ornek":"Programda “2. gün: 08.00 kahvaltı, 09.00 Göreme Açık Hava Müzesi, 13.00 öğle yemeği, 15.00 çömlek atölyesi” yazar.","sektor":"Türkçesi güzergâh ya da tur programıdır. Konuk sabah kaçta hazır olacağını buradan öğrenir; rehberin, şoförün ve otelin de ortak planıdır. Programda yazan yer gerekçesiz atlanmaz.","iliskili":["os-4-018","os-4-020","os-4-063"],"kontrol":null,"gorsel":"sektor-harita-pusula"},{"id":"os-4-055","konu":"4.2.2","terim":"Transfer","ingilizce":"Transfer","tanim":"Konuğun havalimanı, otel ve gezi noktaları arasında acentenin düzenlediği araçla taşınmasıdır.","ornek":"Uçaktan inen konuğu çıkışta acentenin görevlisi karşılar ve bavullarıyla birlikte minibüsle oteline götürür.","sektor":"Özellikle karşılayıcı acentelerin düzenlediği bir hizmettir. Tatilin ilk ve son anısıdır: geç gelen araç, çok iyi geçen bir haftayı gölgeleyebilir.","iliskili":["os-4-022","os-4-034","os-4-082"],"kontrol":null},{"id":"os-4-056","konu":"4.2.2","terim":"Net fiyat","ingilizce":"Net rate (commission net rate)","tanim":"Tedarikçinin acenteye verdiği, acentenin kazancı eklenmemiş fiyattır.","ornek":"Otel acenteye bir odayı net fiyatla verir; acente bu fiyatın üzerine kendi payını ekleyerek satış fiyatını belirler.","sektor":"Net fiyat ticari bir sırdır; konuğa ya da rakip acenteye söylenmez. Komisyonlu çalışmada ise satış fiyatı bellidir ve acente bu fiyatın üzerinden komisyon alır.","iliskili":["os-4-039","os-4-037","os-4-057"],"kontrol":null,"cizim":"para-butce"},{"id":"os-4-057","konu":"4.2.2","terim":"Kontenjan (allotment)","ingilizce":"Allotment","tanim":"Otelin ya da hava yolunun, belirli bir dönem için belirli sayıda oda ya da koltuğu bir acenteye ayırmasıdır.","ornek":"Bir otel yaz sezonu için her gece belirli sayıda odasını bir tur operatörüne ayırır; operatör bu odaları kendi konuklarına satar.","sektor":"Sektörde “allotman” diye de söylenir. Kullanılmayacak odalar belirlenen tarihe kadar otele geri bildirilir; garantili kontenjanda ise satılamayan odanın bedeli yine ödenir.","iliskili":["os-4-026","os-4-065","os-4-047"],"kontrol":null},{"id":"os-4-058","konu":"4.2.2","terim":"Bilgisayarlı rezervasyon sistemi (CRS)","ingilizce":"Computerised reservation system (CRS)","tanim":"Acentenin uçuş, otel ve benzeri hizmetlerde boş yer sorup anında rezervasyon yapmasını sağlayan bilgisayar sistemidir.","ornek":"Bilet personeli ekrana tarih ve güzergâhı yazar; sistem birkaç saniyede uygun uçuşları ve fiyatları listeler.","sektor":"Telefonla tek tek yer sorma dönemini bitirmiştir. Sisteme girilen her harf kayda dönüşür; yanlış yazılan ad, yanlış kesilmiş bilet demektir.","iliskili":["os-4-059","os-4-042","os-4-016"],"kontrol":null,"cizim":"resepsiyon"},{"id":"os-4-059","konu":"4.2.2","terim":"GDS","ingilizce":"GDS (Global Distribution System)","tanim":"Hava yollarını, otelleri, araç kiralama şirketlerini ve acenteleri birbirine bağlayan küresel rezervasyon ağıdır.","ornek":"Acente görevlisi tek ekrandan hem Londra uçuşunu hem oradaki oteli hem de kiralık aracı sorgulayıp ayırtır.","sektor":"Türkçesi küresel dağıtım sistemidir; en bilinenleri Amadeus, Sabre ve Travelport’tur. Biletleme alanında çalışmak isteyen birinin öğreneceği ilk araçlardandır.","iliskili":["os-4-058","os-4-042","os-4-093"],"kontrol":null,"kitapDisi":true,"cizim":"dunya-global"},{"id":"os-4-060","konu":"4.2.2","terim":"Fam trip","ingilizce":"Familiarisation trip (fam trip)","tanim":"Bir bölgeyi ve oradaki tesisleri acente çalışanlarına tanıtmak için düzenlenen tanıtım gezisidir.","ornek":"Yeni açılan bir otel, sezon öncesinde acentelerin satış görevlilerini iki günlüğüne ağırlar ve odalarını, restoranlarını gezdirir.","sektor":"Mantığı basittir: satış görevlisi görmediği oteli anlatamaz, gördüğünü içtenlikle satar.","iliskili":["os-4-061","os-4-013"],"kontrol":null,"kitapDisi":true,"cizim":"bavul"},{"id":"os-4-061","konu":"4.2.2","terim":"Teşvik gezisi (incentive)","ingilizce":"Incentive travel","tanim":"Şirketlerin, çalışanlarını ya da bayilerini ödüllendirmek ve daha verimli çalışmaya özendirmek için düzenlettiği gezidir.","ornek":"Bir sigorta şirketi, yılın en başarılı satış ekibini üç günlüğüne Kapadokya’ya gönderir.","sektor":"MICE’ın “I” harfidir. Parayı tatile giden kişi değil, şirket öder. Fam trip ile karıştırılmamalıdır: biri çalışanı ödüllendirir, öteki bölgeyi acentelere tanıtır.","iliskili":["os-4-019","os-4-060"],"kontrol":null,"kitapDisi":true,"cizim":"trofe-odul"},{"id":"os-4-127","konu":"4.2.2","terim":"Vize işlemleri (visa handling)","ingilizce":"Visa handling","tanim":"Yurt dışı turlarına katılacak konuğa acentenin vize konusunda yol göstermesi ve başvurunun sonucunu izlemesi hizmetidir.","ornek":"Salı 11.00, bir acentede: vize görevlisi Prag turuna yazılan konuğa belge listesini verir, randevusunu aldırır ve sonucu takip eder.","sektor":"Kitabın 4.2.2 terim listesinde ayrı madde olarak geçer. Acente başvuruyu hazırlar ve izler; vizeyi veren konsolosluktur, bu yüzden sonuç garanti edilmez.","iliskili":["os-4-017","os-4-097","os-4-108"],"kontrol":null,"cizim":"pasaport"},{"id":"os-4-062","konu":"4.2.3","terim":"Tur operatörü","ingilizce":"Tour operator","tanim":"Ulaşım, konaklama, rehberlik ve etkinlikleri talep oluşmadan önce bir araya getirip paket hâlinde satışa sunan işletmedir.","ornek":"Bir tur operatörü kış aylarında, gelecek yaz için otellerden oda, hava yollarından koltuk ayırır ve bunları tek fiyatlı tatil paketlerine dönüştürür.","sektor":"Paket turun “üreticisi”, yani toptancısıdır. Türkiye’de hukuken ayrı bir tur operatörü statüsü yoktur; 1618 sayılı Kanun çerçevesinde bu işlevi A grubu acenteler yerine getirir.","iliskili":["os-4-063","os-4-064","os-4-031"],"kontrol":null},{"id":"os-4-063","konu":"4.2.3","terim":"Paket tur","ingilizce":"Package tour","tanim":"Ulaşım, konaklama ve rehberlik gibi birden çok hizmetin bir araya getirilip tek fiyatla satıldığı hazır seyahat ürünüdür.","ornek":"Uçak bileti, dört gece otel, kahvaltı, transfer ve rehberli şehir turu tek fiyatla “Paris Turu” adıyla satılır.","sektor":"Konuk her hizmeti ayrı ayrı aramaz, tek sözleşmeyle hepsini alır. Paket turda hizmetin eksik verilmesine karşı konuğu koruyan özel kurallar ve zorunlu sigorta vardır.","iliskili":["os-4-062","os-4-068","os-4-074"],"kontrol":null,"gorsel":"t13b-seyahat-brosuru"},{"id":"os-4-064","konu":"4.2.3","terim":"Üretici – aracı ayrımı","ingilizce":"Producer versus intermediary","tanim":"Tur operatörünün paket turu oluşturan taraf, seyahat acentesinin ise bu hazır ürünü konuğa ulaştıran satış noktası olmasıdır.","ornek":"Operatör bir Ege turunu hazırlayıp fiyatını belirler; mahalledeki acente bu turu vitrine koyar, konuğa satar ve anlaşılan komisyonu alır.","sektor":"Operatör toptancı / üretici, acente perakendeci / aracıdır. Operatör maliyetin üzerine kâr payı ekleyerek, acente komisyonla kazanır. Operatör katalog ve reklama büyük bütçe ayırır; acente çoğu zaman operatörün hazır broşürünü kullanır.","iliskili":["os-4-062","os-4-039","os-4-065"],"kontrol":null,"cizim":"acente"},{"id":"os-4-065","konu":"4.2.3","terim":"Finansal risk","ingilizce":"Financial risk","tanim":"Önceden satın alınan oda ya da koltuğun satılamaması durumunda doğan zarar ihtimalidir.","ornek":"Operatör yaz için garantili ayırttığı odaların bir kısmını satamaz; boş kalan odaların bedelini yine de otele öder.","sektor":"Tur operatörü talep oluşmadan önce kapasite satın aldığı ve kontenjan garantisi verdiği için riski üstlenir. Seyahat acentesi ise ürünün sahibi değildir; konuğun talebine göre mevcut ürünlerden seçip sattığı için satılamayan yerden zarar etmez.","iliskili":["os-4-062","os-4-064","os-4-050"],"kontrol":null,"cizim":"uyari"},{"id":"os-4-066","konu":"4.3","terim":"1618 sayılı Kanun","ingilizce":"Law No. 1618 (Travel Agencies Act)","tanim":"Türkiye’de seyahat acentelerinin kuruluş şartlarını, çalışma esaslarını ve TÜRSAB ile ilişkilerini düzenleyen temel kanundur.","ornek":"Bir girişimci acente açmak istediğinde ilk bakacağı metin budur: hangi belgeyi kimden alacağı ve hangi grupta çalışabileceği burada yazar.","sektor":"Tam adı Seyahat Acentaları ve Seyahat Acentaları Birliği Kanunu’dur; 1972’de yürürlüğe girmiştir. Amaç sektörün disiplin içinde çalışması ve tüketicinin korunmasıdır. Mevzuatı bilen acenteci hem konuğunu hem kendini korur.","iliskili":["os-4-067","os-4-069","os-4-073"],"kontrol":null,"cizim":"etik-terazi"},{"id":"os-4-067","konu":"4.3","terim":"Seyahat acentesi işletme belgesi","ingilizce":"Travel agency operating licence","tanim":"Bir işletmenin seyahat acenteliği yapabilmesi için Kültür ve Turizm Bakanlığından alması zorunlu olan resmî izin belgesidir.","ornek":"Konuk, internette gördüğü acentenin belge numarasını sorar; görevli numarayı söyler ve belgenin ofiste asılı olduğunu gösterir.","sektor":"Ders kitabına göre acente iki şartla işe başlar: Bakanlıktan işletme belgesini alır ve TÜRSAB’a üye olur. Belgeyi TÜRSAB değil, Bakanlık verir. Belgesiz tur satan kişi kaçak çalışıyordur; konuğun başına bir şey gelirse arkasında duracak kimse yoktur.","iliskili":["os-4-066","os-4-070","os-4-086"],"kontrol":null,"cizim":"acente"},{"id":"os-4-068","konu":"4.3","terim":"Zorunlu paket tur sigortası","ingilizce":"Compulsory package tour insurance","tanim":"Acentenin, paket turda söz verdiği hizmetin eksik verilmesi ya da hiç verilmemesi riskine karşı konuklarını güvenceye almak için yaptırmak zorunda olduğu sigortadır.","ornek":"Acente paket turdaki hizmeti eksik ya da hiç veremezse, konuğun uğradığı zarara karşı bu sigorta devreye girer.","sektor":"6502 sayılı Tüketicinin Korunması Hakkında Kanun’la uyumlu bir yükümlülüktür. Seyahat sağlık sigortasıyla karıştırılmamalıdır: paket tur sigortasını konuk değil, acente yaptırır.","iliskili":["os-4-063","os-4-076","os-4-118"],"kontrol":null},{"id":"os-4-069","konu":"4.3.1","terim":"TÜRSAB","ingilizce":"Association of Turkish Travel Agencies (TÜRSAB)","tanim":"Türkiye’de seyahat acenteliği mesleğinin kurumsal ve hukuki temsilcisi olan Türkiye Seyahat Acentaları Birliğidir.","ornek":"Acentenin internet sitesindeki belge numarası ve TÜRSAB üyeliği, konuğa karşısındakinin kayıtlı bir acente olduğunu gösterir.","sektor":"1972’de yürürlüğe giren 1618 sayılı Kanun’la kurulmuştur. Kanun onu “kamu kurumu niteliğinde meslek kuruluşu” olarak tanımlar; sektörde hem düzenleyici hem denetleyici bir rolü vardır. Gerektiğinde devlete danışmanlık yapar, pazar araştırması yürütür ve tanıtıma destek verir.","iliskili":["os-4-066","os-4-070","os-4-071"],"kontrol":null,"cizim":"acente"},{"id":"os-4-070","konu":"4.3.1","terim":"Zorunlu üyelik","ingilizce":"Compulsory membership","tanim":"Seyahat acenteliği yapmak isteyen her işletmenin, işletme belgesini aldıktan sonra TÜRSAB’a üye olmak zorunda olmasıdır.","ornek":"Yeni kurulan bir acente Bakanlıktan belgesini alır, ardından TÜRSAB üyeliğini tamamlar; satışa ondan sonra başlar.","sektor":"Belgeli bir acentenin çalışanı, müşteri “TÜRSAB üyesi misiniz?” diye sorduğunda rahatça “evet” diyebilir; çünkü üyelik isteğe bağlı değil, hukuken zorunludur. Ders kitabına göre bu zorunluluğun amacı kayıt dışı faaliyeti önlemek ve herkesin aynı standartlara uymasını sağlamaktır.","iliskili":["os-4-069","os-4-067","os-4-072"],"kontrol":null,"cizim":"etik-terazi"},{"id":"os-4-071","konu":"4.3.1","terim":"Mesleki disiplin ve etik denetim","ingilizce":"Professional discipline and ethical oversight","tanim":"TÜRSAB’ın, üye acentelerin meslek ilkelerine uygun davranıp davranmadığını izlemesi ve etik dışı uygulamaları denetlemesidir.","ornek":"Bir konuk, acentenin programda yazan geziyi yapmadığını belirterek TÜRSAB’a şikâyette bulunur; birlik şikâyeti değerlendirir.","sektor":"Tüketici şikâyetlerini değerlendirmek birliğin yasal görevlerindendir. Zorunlu sigorta ve paket tur kurallarına uyulmasını takip ederek sektörde güven ortamını korur.","iliskili":["os-4-069","os-4-023","os-4-072"],"kontrol":null,"cizim":"etik-terazi"},{"id":"os-4-072","konu":"4.3.1","terim":"Haksız rekabet","ingilizce":"Unfair competition","tanim":"Bir işletmenin dürüstlük kurallarına aykırı yollarla rakiplerinin önüne geçmeye çalışmasıdır.","ornek":"Belgesi olmayan bir kişi sosyal medyada çok ucuza tur satar; ne sigorta yaptırır ne kurallara uyar, dürüst çalışan acentelerin konuğunu elinden alır.","sektor":"Haksız rekabeti önlemek TÜRSAB’ın görevleri arasındadır. Kurala uyan acentenin maliyeti vardır; kuralsız çalışan hem konuğu riske atar hem dürüst işletmeye zarar verir.","iliskili":["os-4-071","os-4-070","os-4-067"],"kontrol":null,"cizim":"festival"},{"id":"os-4-073","konu":"4.3.2","terim":"Seyahat Acentaları Yönetmeliği","ingilizce":"Travel Agencies Regulation","tanim":"1618 sayılı Kanun’un nasıl uygulanacağını ayrıntılı olarak gösteren yönetmeliktir.","ornek":"Kanun “acente işletme belgesi alır” der; belgenin hangi şartlarla ve nasıl alınacağının ayrıntısı yönetmelikte yazar.","sektor":"Kanun genel kuralı koyar, yönetmelik uygulamayı anlatır. Acenteyi bağlayan başka yönetmelikler de vardır: Seyahat Acentaları Birliği Yönetmeliği, Turizm Amaçlı Sportif Faaliyet Yönetmeliği ve turizm işletmelerinin Bakanlıkla, birbirleriyle ve müşterileriyle ilişkilerini düzenleyen yönetmelik bunlardandır.","iliskili":["os-4-066","os-4-074","os-4-075"],"kontrol":null,"cizim":"bavul"},{"id":"os-4-074","konu":"4.3.2","terim":"Paket Tur Sözleşmeleri Yönetmeliği","ingilizce":"Package Tour Contracts Regulation","tanim":"Turu satan acente ile turu satın alan tüketici arasındaki paket tur sözleşmesinin kurallarını belirleyen yönetmeliktir.","ornek":"Konuk tur sözleşmesini imzalamadan önce programı, fiyata dâhil hizmetleri ve iptal koşullarını yazılı olarak görür.","sektor":"Söz uçar, sözleşme kalır. Konuğa imzalatılan sözleşme bir formalite değil, iki tarafın da hakkını koruyan belgedir; satış görevlisi sözleşmeyi konuğa okutmadan imzalatmaz.","iliskili":["os-4-063","os-4-076","os-4-051"],"kontrol":null,"cizim":"sozlesme"},{"id":"os-4-122","konu":"4.3.2","terim":"Acentenin tâbi olduğu diğer yönetmelikler","ingilizce":"Other regulations governing travel agencies","tanim":"Acenteyi 1618 sayılı Kanun ve paket tur kurallarının yanında bağlayan; birliği, turizm amaçlı sportif faaliyetleri ve turizm işletmelerinin ilişkilerini düzenleyen yönetmeliklerdir.","ornek":"Bir acente rafting turu satacağı zaman yalnız paket tur kurallarına değil, turizm amaçlı sportif faaliyetleri düzenleyen yönetmeliğe de uyduğundan emin olur.","sektor":"Üç yönetmelik bu kartın konusudur: Seyahat Acentaları Birliği Yönetmeliği, Turizm Amaçlı Sportif Faaliyet Yönetmeliği ve Turizm İşletmelerinin Bakanlıkla Birbirleriyle ve Müşterileriyle İlişkileri Hakkında Yönetmelik. Ders kitabı acentenin tâbi olduğu mevzuatı uzun bir liste olarak verir: bir ana kanun, birkaç yönetmelik ve ticaret, tüketici ile veri güvenliği kanunları. Acente çalışanı hepsini ezbere bilmez; ama satışını yaptığı ürünün hangi kurala bağlı olduğunu ve nerede arayacağını bilir.","iliskili":["os-4-073","os-4-074","os-4-076"],"kontrol":null,"cizim":"kurallar-liste"},{"id":"os-4-075","konu":"4.3.2","terim":"Mesafeli sözleşme","ingilizce":"Distance contract","tanim":"Satıcı ile tüketicinin yüz yüze gelmeden, internet ya da telefon gibi araçlarla kurduğu sözleşmedir.","ornek":"Konuk gece 23.00’te evinden, acentenin internet sitesi üzerinden bir hizmet satın alır ve onayını ekrandaki kutuyu işaretleyerek verir.","sektor":"Kuralları Mesafeli Sözleşmeler Yönetmeliği ile belirlenir; ders kitabı bu yönetmeliği acentelerin tâbi olduğu mevzuat arasında sayar. İnternet üzerinden satışı ayrıca 6563 sayılı Elektronik Ticaretin Düzenlenmesi Hakkında Kanun düzenler. Konuğa bilgi, satın almadan önce açık ve eksiksiz verilir.","iliskili":["os-4-074","os-4-076","os-4-077"],"kontrol":null},{"id":"os-4-076","konu":"4.3.2","terim":"Tüketicinin Korunması Hakkında Kanun","ingilizce":"Consumer Protection Act (Law No. 6502)","tanim":"Mal ya da hizmet satın alan tüketicinin haklarını koruyan 6502 sayılı kanundur.","ornek":"Broşürde beş yıldızlı otel yazdığı hâlde daha alt sınıf bir otele yerleştirilen konuk, hakkını bu kanuna dayanarak arar.","sektor":"Acentenin konuğu aynı zamanda bir tüketicidir. Zorunlu paket tur sigortası bu kanunla uyumlu bir yükümlülüktür. Acente ayrıca bir ticari işletme olarak 6102 sayılı Türk Ticaret Kanunu’na da tâbidir.","iliskili":["os-4-068","os-4-074","os-4-071"],"kontrol":null,"cizim":"etik-terazi"},{"id":"os-4-077","konu":"4.3.2","terim":"Kişisel Verilerin Korunması Kanunu (KVKK)","ingilizce":"Personal Data Protection Act (Law No. 6698)","tanim":"Kişilerin ad, kimlik numarası, pasaport bilgisi gibi verilerinin nasıl toplanacağını, saklanacağını ve korunacağını düzenleyen 6698 sayılı kanundur.","ornek":"Vize dosyası için alınan pasaport fotokopisi yalnız başvuru için kullanılır; masada açıkta bırakılmaz, mesajlaşma gruplarında paylaşılmaz.","sektor":"Acente her gün pasaport, kimlik, banka dökümü gibi hassas belgelerle çalışır. Konuğun bilgisini izinsiz paylaşmak hem gizlilik ilkesine hem de kanuna aykırıdır.","iliskili":["os-4-023","os-4-108","os-4-075"],"kontrol":null,"cizim":"etik-terazi"},{"id":"os-4-135","konu":"4.3.2","terim":"Türk Ticaret Kanunu (6102)","ingilizce":"Turkish Commercial Code (Law No. 6102)","tanim":"Ticari işletmelerin kuruluşunu, işleyişini ve ticari ilişkilerini düzenleyen 6102 sayılı kanundur.","ornek":"Bir acente, otelle yaptığı yazılı sözleşmeyi ve faturalarını ticari kayıt düzenine uygun biçimde saklar.","sektor":"Seyahat acentesi ticari bir işletme olduğu için 1618 sayılı özel Kanun’un yanında bu genel kanuna da bağlıdır.","iliskili":["os-4-066","os-4-136","os-4-077"],"kontrol":null,"cizim":"etik-terazi"},{"id":"os-4-136","konu":"4.3.2","terim":"Elektronik Ticaretin Düzenlenmesi Hakkında Kanun (6563)","ingilizce":"Law on the Regulation of Electronic Commerce (Law No. 6563)","tanim":"İnternet gibi elektronik ortamlarda yapılan ticari satışların kurallarını belirleyen 6563 sayılı kanundur.","ornek":"Acentenin internet sitesinden tur satan görevli, satıştan önce fiyatı, hizmet kapsamını ve satıcı bilgilerini sitede açıkça gösterir.","sektor":"İnternetten satış yapan her acente bu kanuna uymak zorundadır; mesafeli sözleşme kurallarıyla birlikte düşünülür.","iliskili":["os-4-135","os-4-076","os-4-077"],"kontrol":null,"cizim":"etik-terazi"},{"id":"os-4-078","konu":"4.4","terim":"Paydaş","ingilizce":"Stakeholder","tanim":"Bir işletmenin çalışmalarından etkilenen ya da onu etkileyen kişi, kurum ve işletmelerin her biridir.","ornek":"Bir kültür turunun paydaşları konuk, acente, otel, otobüs firması, rehber, müze ve gidilen kasabanın esnafıdır.","sektor":"Acente, turizm ürününü oluşturan farklı hizmetleri bir araya getiren bir orkestra şefi gibidir. Başlıca paydaşları Kültür ve Turizm Bakanlığı, mülki idare amirlikleri ve belediyeler, TÜRSAB, konaklama ve ulaştırma işletmeleri ile sigorta şirketleridir.","iliskili":["os-4-079","os-4-085"],"kontrol":null,"cizim":"is-birligi"},{"id":"os-4-079","konu":"4.4.1","terim":"Hizmet satın alınan işletmeler","ingilizce":"Service suppliers","tanim":"Acentenin turunu oluşturmak için hizmet aldığı konaklama, yiyecek içecek, ulaştırma ve alışveriş işletmeleridir.","ornek":"İki günlük Gaziantep turu için acente bir otelle, iki restoranla, bir otobüs firmasıyla ve Bakırcılar Çarşısı’ndaki bir atölyeyle anlaşır.","sektor":"Dört temel işletme türü vardır. Dikkat: otel ve otobüs firması hizmet sağlayıcıdır; Bakanlık, TÜRSAB ve konsolosluk ise ilişkili kurumdur. Sınavda bu iki grup birbirine karıştırılır.","iliskili":["os-4-080","os-4-082","os-4-085"],"kontrol":null},{"id":"os-4-080","konu":"4.4.1","terim":"Konaklama işletmeleriyle iş birliği","ingilizce":"Co-operation with accommodation providers","tanim":"Acentenin, konuklarının kalacağı otel, tatil köyü ve pansiyon gibi tesislerle yaptığı anlaşmalara dayanan çalışma ilişkisidir.","ornek":"Acente, sezon başında Kuşadası’ndaki bir otelle fiyat ve oda sayısı üzerinde anlaşır; sezon boyunca konuklarını o otele gönderir.","sektor":"Paket turun en büyük parçası çoğu zaman konaklamadır. Otel acenteye oda, acente otele konuk getirir; iki taraf da birbirine muhtaçtır. Otelde staj yapan öğrenci, voucherla gelen konuğu bu ilişkinin sonucu olarak karşılar.","iliskili":["os-4-079","os-4-045","os-4-057"],"kontrol":null},{"id":"os-4-081","konu":"4.4.1","terim":"Yiyecek içecek işletmeleriyle iş birliği","ingilizce":"Co-operation with food and beverage outlets","tanim":"Acentenin, tur sırasında grubun yemek yiyeceği restoran ve benzeri işletmelerle önceden yaptığı anlaşmadır.","ornek":"Saat 12.30, Hatay turu: grup restorana vardığında masalar kurulmuş, menü hazırdır; çünkü acente günü, saati ve kişi sayısını önceden bildirmiştir.","sektor":"Anlaşmalı restoran kalabalık gruba hazırlıklıdır, acente de kalitesinden emindir. Alerji ve özel beslenme istekleri restorana önceden yazılı bildirilir.","iliskili":["os-4-079","os-4-008"],"kontrol":null},{"id":"os-4-082","konu":"4.4.1","terim":"Ulaştırma işletmeleriyle iş birliği","ingilizce":"Co-operation with transport providers","tanim":"Acentenin, konuklarını taşıyacak hava yolu, otobüs, gemi ve araç kiralama firmalarıyla kurduğu çalışma ilişkisidir.","ornek":"Acente, okul gezisi için bir otobüs firmasından araç kiralar; yola çıkmadan önce aracın ve firmanın belgelerini kontrol eder.","sektor":"Araç kiralık da olsa konuk karşısında acenteyi görür ve hesabı ondan sorar. Bu yüzden yalnız fiyata değil, firmanın belgelerine, sigortasına ve güvenliğe verdiği öneme de bakılır.","iliskili":["os-4-079","os-4-087","os-4-055"],"kontrol":null,"cizim":"is-birligi"},{"id":"os-4-083","konu":"4.4.1","terim":"Alışveriş işletmeleriyle iş birliği","ingilizce":"Co-operation with shopping outlets","tanim":"Acentenin, tur programında konukların uğrayacağı hediyelik eşya, halı, deri, kuyum gibi mağazalarla kurduğu ilişkidir.","ornek":"Kapadokya turunda grup bir çömlek atölyesine uğrar; usta çarkta nasıl çalıştığını gösterir, isteyen alışveriş yapar.","sektor":"Alışveriş, turun doğal bir parçasıdır ve yöre esnafına kazandırır. Etik sınır şudur: konuk alışverişe zorlanmaz, programdaki bir ziyaret komisyon için iptal edilmez.","iliskili":["os-4-079","os-4-023","os-4-039"],"kontrol":null},{"id":"os-4-084","konu":"4.4","terim":"Sigorta şirketleriyle iş birliği","ingilizce":"Co-operation with insurance companies","tanim":"Acentenin, zorunlu sigortalarını yaptırmak ve konuklarına seyahat sigortası sunmak için sigorta şirketleriyle çalışmasıdır.","ornek":"Yurt dışı turu satan görevli, konuğun vize dosyasına eklenecek seyahat sağlık sigortası poliçesini anlaşmalı sigorta şirketinden düzenletir.","sektor":"Ders kitabı sigorta şirketlerini acentenin başlıca paydaşları arasında sayar. Poliçenin neyi kapsadığını konuğa doğru anlatmak görevlinin işidir; kapsamda olmayan şey için söz verilmez.","iliskili":["os-4-118","os-4-068","os-4-119"],"kontrol":null,"cizim":"is-birligi"},{"id":"os-4-085","konu":"4.4.2","terim":"İlişkili kurum ve kuruluşlar","ingilizce":"Related institutions and organisations","tanim":"Acentenin hizmet satın almadığı, ama izin, denetim, temsil ve iş birliği için muhatap olduğu kamu kurumları, meslek örgütleri ve uluslararası kuruluşlardır.","ornek":"Acente belgesi için Bakanlıkla, üyeliği için TÜRSAB’la, rehber bulmak için rehber odasıyla, bilet satışı için IATA’yla ilişki kurar.","sektor":"Üç grupta düşünülür: kamu kurumları (bakanlıklar, valilik, belediye), meslek örgütleri ve sivil toplum kuruluşları (TÜRSAB, TUREB, TÜROB, TÜROFED), uluslararası kuruluşlar (UN Tourism, IATA, UFTAA).","iliskili":["os-4-079","os-4-086","os-4-093"],"kontrol":null,"cizim":"ekip"},{"id":"os-4-086","konu":"4.4.2","terim":"Kültür ve Turizm Bakanlığı","ingilizce":"Ministry of Culture and Tourism","tanim":"Seyahat acentelerine işletme belgesi veren ve onları denetleyen en üst kamu otoritesidir.","ornek":"Bakanlık denetçileri bir acenteyi ziyaret eder; belgesini ve sattığı turların kurallara uygunluğunu inceler.","sektor":"Acentenin kuruluşundan denetimine kadar ilk muhatabıdır; sürdürülebilir turizm standartlarını da o belirler. Denetime her gün hazır olan acente, konuğuna da her gün hazırdır.","iliskili":["os-4-067","os-4-085","os-4-087"],"kontrol":null,"gorsel":"os-kultur-turizm-bakanligi"},{"id":"os-4-087","konu":"4.4.2","terim":"Ulaştırma ve Altyapı Bakanlığı","ingilizce":"Ministry of Transport and Infrastructure","tanim":"Kara yolu yolcu taşımacılığı ve havacılık güvenliği standartlarını belirleyen, acentelerin uyum sağlaması gereken bakanlıktır.","ornek":"Acente tur için otobüs kiralarken firmanın yolcu taşımaya yetkili olduğunu gösteren yetki belgesini sorar.","sektor":"Ders kitabı kara yolu taşımacılığında örnek olarak D2 yetki belgesini anar. Yetki belgesi olmayan araçla yola çıkmak hem kurala aykırıdır hem konuğu riske atar; bedelini acente öder.","iliskili":["os-4-082","os-4-086","os-4-088"],"kontrol":null,"cizim":"saglik-kalp"},{"id":"os-4-088","konu":"4.4.2","terim":"Yerel yönetimler","ingilizce":"Local authorities","tanim":"Acentenin bölgesel tanıtım, çevre düzeni ve yerel etkinlik izinleri konusunda iş birliği yaptığı belediyeler ve valiliklerdir.","ornek":"Bir acente, belediyenin düzenlediği kiraz festivali için özel tur hazırlar; otobüslerin park yeri ve program belediyeyle birlikte planlanır.","sektor":"Valilik ve kaymakamlık gibi mülki idare amirlikleri de acentenin paydaşıdır. Yerel yönetimle iyi ilişki, festival ve etkinlik turlarında işleri kolaylaştırır. Ders kitabı başlıca kurumlar arasında “mülki idare amirlikleri ve belediyeleri” sayar; mülki idare amirlikleri il ve ilçede devleti temsil eden valilik ve kaymakamlıklardır; yerel etkinlik izinleri ve bölgesel tanıtım konularında acenteyle iş birliği yapılır.","iliskili":["os-4-085","os-4-086","os-4-078"],"kontrol":null},{"id":"os-4-089","konu":"4.4.2","terim":"TUREB","ingilizce":"Union of Tourist Guides (TUREB)","tanim":"Rehber odalarının bağlı olduğu, turist rehberlerini temsil eden Türkiye Turist Rehberleri Birliğidir.","ornek":"Acente, Japonca bilen bir rehbere ihtiyaç duyar; bölgedeki rehber odasına başvurarak belgeli bir rehber bulur.","sektor":"Acenteler nitelikli tur için profesyonel rehberi buradan temin eder ve rehber odalarıyla sürekli iletişimdedir. Belgesiz kişiye rehberlik yaptırmak acenteyi de sorumlu duruma düşürür.","iliskili":["os-4-020","os-4-085","os-4-090"],"kontrol":null,"cizim":"acente"},{"id":"os-4-090","konu":"4.4.2","terim":"TÜROB","ingilizce":"Hotel Association of Türkiye (TÜROB)","tanim":"Konaklama sektörünün profesyonelleşmesi ve uluslararası standartlara ulaşması için çalışan Türkiye Otelciler Birliğidir.","ornek":"Sezon öncesinde TÜROB yetkilileri, otellerin ortak sorunlarını ve beklentilerini kamuoyuyla paylaşır.","sektor":"Bir sivil toplum kuruluşudur. Acentenin en önemli iş ortağı otellerdir; otelcilerin örgütünü tanımak, masanın öbür tarafını tanımaktır.","iliskili":["os-4-091","os-4-080","os-4-085"],"kontrol":null},{"id":"os-4-091","konu":"4.4.2","terim":"TÜROFED","ingilizce":"Turkish Hoteliers Federation (TÜROFED)","tanim":"Turizmin gelişmesi ve Türkiye’nin dünya turizmindeki rekabet gücünün artması için kamu ve özel sektörle iş birliği yapan Türkiye Otelciler Federasyonudur.","ornek":"TÜROFED temsilcileri uluslararası bir turizm fuarında Türkiye’nin konaklama sektörünü tanıtır.","sektor":"Sürdürülebilirlik, kalite, istihdam ve dijital dönüşüm alanlarında çalışır. Adı TÜROB ile karıştırılır: biri birlik, öteki federasyondur.","iliskili":["os-4-090","os-4-085"],"kontrol":null},{"id":"os-4-092","konu":"4.4.2","terim":"UN Tourism (Dünya Turizm Örgütü)","ingilizce":"UN Tourism (World Tourism Organization)","tanim":"Küresel turizm politikalarını ve turizmde etik ilkeleri izleyen, Birleşmiş Milletlere bağlı uluslararası kuruluştur.","ornek":"Acentelerin ve bakanlıkların kullandığı “turist” ve “ziyaretçi” tanımları bu kuruluşun tanımlarına dayanır.","sektor":"Eski kısaltması UNWTO’dur; ders kitabında iki ad da geçer. Tur operatörünün tanımı da kitapta bu kuruluşa dayandırılır. Acente için referans kurumdur: ortak dil ve ortak etik ilkeler buradan gelir.","iliskili":["os-4-093","os-4-094","os-4-085"],"kontrol":null,"gorsel":"h4-unwto-madrid"},{"id":"os-4-093","konu":"4.4.2","terim":"IATA","ingilizce":"International Air Transport Association (IATA)","tanim":"Hava yolu şirketlerini bir araya getiren ve uçak bileti satan acentelerin yetkilendirilmesini yöneten Uluslararası Hava Taşımacılığı Birliğidir.","ornek":"Bir acente uçak biletini kendi adına kesebilmek için IATA’dan yetki alır.","sektor":"Yetkilendirmeye akreditasyon denir. Acentelerin sattığı biletlerin bedelini hava yollarına aktaran ödeme sistemi BSP’yi (Billing and Settlement Plan) de IATA yönetir. Ulusal bir örgüt olan TÜRSAB ile karıştırılmamalıdır.","iliskili":["os-4-016","os-4-059","os-4-094"],"kontrol":null,"cizim":"ucak"},{"id":"os-4-094","konu":"4.4.2","terim":"UFTAA","ingilizce":"United Federation of Travel Agents' Associations (UFTAA)","tanim":"Ülkelerin seyahat acenteleri birliklerini dünya ölçeğinde bir araya getiren federasyondur.","ornek":"Farklı ülkelerin acente birlikleri UFTAA çatısı altında bir araya gelerek ortak sorunları konuşur ve iş bağlantıları kurar.","sektor":"Acenteleri uluslararası düzeyde temsil eder ve küresel iş ağları sağlar. Üç uluslararası kuruluş şöyle ayrılır: UN Tourism politika ve etik, IATA hava yolu ve bilet, UFTAA acente birlikleri.","iliskili":["os-4-092","os-4-093","os-4-069"],"kontrol":null},{"id":"os-4-137","konu":"4.4.2","terim":"Rehber odası","ingilizce":"Tourist guides’ chamber","tanim":"Profesyonel turist rehberlerinin kayıtlı olduğu meslek kuruluşudur.","ornek":"Acente Japonca bilen bir rehber arar ve bölgedeki rehber odasından kayıtlı, kokartlı rehberlerin bilgisini ister.","sektor":"Kitaba göre rehber, rehberlik odasına kayıtlı olarak çalışır; odalar TUREB’le bağlantılıdır. Acente nitelikli rehberi buradan bulur.","iliskili":["os-4-089","os-4-020","os-4-121"],"kontrol":null,"cizim":"acente"},{"id":"os-4-095","konu":"4.5","terim":"Seyahat formaliteleri","ingilizce":"Travel formalities","tanim":"Uluslararası seyahatte güvenlik ve düzen için yolcunun yerine getirmek zorunda olduğu pasaport, vize ve sağlık belgesi gibi resmî işlemlerdir.","ornek":"Yurt dışı turuna yazılan konuğa acente ilk gün bir liste verir: pasaport süresi, vize, sigorta ve gerekiyorsa aşı belgesi.","sektor":"İki tarafı da korur: yolcu güvenle seyahat eder, gidilen ülke sınırını ve halk sağlığını denetler. Tek eksik belge bütün tatili iptal ettirebilir; bu yüzden kontrol tur gününe bırakılmaz.","iliskili":["os-4-110","os-4-097","os-4-096"],"kontrol":null,"gorsel":"os-seyahat-formaliteleri"},{"id":"os-4-096","konu":"4.5","terim":"Gümrük","ingilizce":"Customs","tanim":"Ülkeye giren ve çıkan eşya ile paranın sınır kapılarında, havalimanlarında ve limanlarda denetlendiği resmî birimdir.","ornek":"Yurt dışından dönen yolcu bavulunu aldıktan sonra gümrük kontrolünden geçer; beyan edeceği eşyası varsa ilgili bankoya gider.","sektor":"Yurt dışı gönderici acentelerin konuklarına bilgi verdiği konulardandır. Belirli sınırın üzerindeki para ya da eşya beyan edilir; sınırlar değişebildiği için görevli tahmin yürütmez, güncel kuralı resmî kaynaktan kontrol eder.","iliskili":["os-4-095","os-4-014","os-4-035"],"kontrol":null},{"id":"os-4-097","konu":"4.5.1","terim":"Vize","ingilizce":"Visa","tanim":"Bir devletin, sınırlarından içeri girecek yabancıya verdiği; seyahatin amacını ve kalış süresini belirleyen resmî izindir.","ornek":"Konuğun pasaportundaki vize etiketinde hangi tarihler arasında ve kaç gün kalabileceği yazar; süre dolmadan ülkeden çıkması gerekir.","sektor":"Ülkeler vizeyi kamu güvenliğini sağlamak ve göçü yönetmek için uygular. Vize türü seyahatin amacına göre seçilir; acente başvuruya yardım eder ama kararı o ülkenin makamları verir.","iliskili":["os-4-098","os-4-106","os-4-017"],"kontrol":null,"cizim":"pasaport"},{"id":"os-4-098","konu":"4.5.1","terim":"Turistik vize","ingilizce":"Tourist visa","tanim":"Yabancı bir ülkeye gezi ve tatil amacıyla gitmek için alınan vizedir.","ornek":"Yılbaşında Viyana’ya gidecek aile, tur tarihinden haftalar önce turistik vize başvurusu yapar.","sektor":"Acentelerin tur konukları için en sık hazırladığı başvurudur. Bu vizeyle gidilen ülkede çalışılamaz.","iliskili":["os-4-097","os-4-100","os-4-104"],"kontrol":null},{"id":"os-4-099","konu":"4.5.1","terim":"Öğrenci vizesi","ingilizce":"Student visa","tanim":"Eğitim görmek amacıyla yurt dışına çıkacak kişilere verilen vizedir.","ornek":"Yurt dışındaki bir dil okuluna kaydolan öğrenci, okulun kabul yazısıyla öğrenci vizesine başvurur.","sektor":"Turizm öğrencisi için de gündeme gelebilir: yurt dışında öğrenim görecek kişi turistik vizeyle değil, amacına uygun vizeyle gider.","iliskili":["os-4-097","os-4-100","os-4-098"],"kontrol":null,"cizim":"pasaport"},{"id":"os-4-100","konu":"4.5.1","terim":"Çalışma vizesi","ingilizce":"Work visa","tanim":"Yurt dışında çalışmak üzere gidecek kişilere verilen vizedir.","ornek":"Yurt dışındaki bir otelde iş bulan genç aşçı, işverenin gönderdiği belgelerle çalışma vizesine başvurur.","sektor":"Yurt dışında bir otelde ya da gemide çalışacak turizmci turistik vizeyle gitmez. Yanlış vizeyle çalışmak kişiyi gittiği ülkede zor durumda bırakır.","iliskili":["os-4-097","os-4-098","os-4-099"],"kontrol":null,"cizim":"pasaport"},{"id":"os-4-101","konu":"4.5.1","terim":"Transit vize","ingilizce":"Transit visa","tanim":"Bir ülkeye giderken başka bir ülkeden geçmek için alınan geçiş vizesidir.","ornek":"Otobüsle yapılan bir Avrupa turunda güzergâh üç ülkeden geçiyorsa acente her birinin geçiş kuralına ayrı ayrı bakar.","sektor":"Yalnız varılacak ülkenin değil, yol üzerindeki ülkelerin şartı da kontrol edilir. Aktarmalı uçuşlarda bazı ülkeler havalimanından çıkmayacak yolcudan bile vize isteyebilir.","iliskili":["os-4-097","os-4-053","os-4-102"],"kontrol":null},{"id":"os-4-102","konu":"4.5.1","terim":"Kapıda vize","ingilizce":"Visa on arrival","tanim":"Önceden başvurmaya gerek kalmadan, ülkeye girişte sınır kapısında ya da havalimanında yetkili memurun verdiği vizedir.","ornek":"Uçakta dağıtılan bilgi formunu dolduran yolcu, inişte pasaport kontrolünden önce vize bankosuna gider ve vizesini orada alır.","sektor":"Her ülke bu uygulamayı yapmaz, yapanlar da her vatandaşa yapmaz. Acente “Kapıda alırsınız” demeden önce güncel kuralı resmî kaynaktan doğrular.","iliskili":["os-4-097","os-4-105","os-4-101"],"kontrol":null,"cizim":"pasaport"},{"id":"os-4-103","konu":"4.5.1","terim":"Resmî görev vizesi","ingilizce":"Official visa","tanim":"Devletin verdiği bir görevle yurt dışına gidecek kişilere verilen vizedir.","ornek":"Uluslararası bir toplantıya ülkesi adına katılacak bir kamu görevlisi, görevlendirme yazısıyla bu vizeye başvurur.","sektor":"Süresi görevin süresine göre belirlenir. Vize türlerini akılda tutmanın yolu amaca bakmaktır: gezi, öğrenim, çalışma, geçiş, görev.","iliskili":["os-4-097","os-4-113","os-4-098"],"kontrol":null,"gorsel":"t13b-vize-kasesi"},{"id":"os-4-104","konu":"4.5.1","terim":"Schengen vizesi","ingilizce":"Schengen visa","tanim":"Aralarındaki sınır kontrollerini kaldırmış olan Avrupa ülkelerinin oluşturduğu Schengen Bölgesi’ne girmek için alınan ortak vizedir.","ornek":"Paris–Amsterdam–Brüksel turuna katılan konuk, üç ülke için üç ayrı vize değil, tek bir Schengen vizesi alır.","sektor":"Başvuruda bölgenin tamamında geçerli bir seyahat sağlık sigortası istenir; acente dosyayı hazırlarken poliçeyi de ekler. Bölgeye üye ülkeler zamanla değiştiği için güncel liste resmî kaynaktan kontrol edilir.","iliskili":["os-4-097","os-4-118","os-4-108"],"kontrol":null},{"id":"os-4-105","konu":"4.5.1","terim":"e-Vize","ingilizce":"e-Visa","tanim":"Konsolosluğa gitmeden, internet üzerinden başvurularak alınan elektronik vizedir.","ornek":"Konuk evindeki bilgisayardan başvuru formunu doldurur, ücreti kartla öder; onay belgesi e-postasına gelir.","sektor":"Konsoloslukta sıra beklemeyi ortadan kaldırır. Her ülke her vatandaşa e-vize vermez; acente güncel kuralı kontrol eder ve konuğu yalnız resmî başvuru sitesine yönlendirir.","iliskili":["os-4-097","os-4-102","os-4-106"],"kontrol":null,"kitapDisi":true},{"id":"os-4-106","konu":"4.5.1","terim":"Konsolosluk","ingilizce":"Consulate","tanim":"Bir devletin başka bir ülkedeki, kendi vatandaşlarının işlemlerini yürüten ve yabancıların vize başvurularını karara bağlayan temsilciliğidir.","ornek":"Yurt dışı turunda pasaportunu kaybeden konuğu rehber, o şehirdeki Türk konsolosluğuna yönlendirir.","sektor":"Vize için hangi belgelerin isteneceğini gidilecek ülkenin konsolosluğu belirler. Yurt dışında başı derde giren vatandaşın başvuracağı yer de kendi ülkesinin konsolosluğudur.","iliskili":["os-4-097","os-4-107","os-4-108"],"kontrol":null},{"id":"os-4-107","konu":"4.5.1","terim":"Vize başvuru merkezi","ingilizce":"Visa application centre","tanim":"Konsolosluk adına başvuru evrakını ve biyometrik verileri teslim alan yetkili aracı kurumdur.","ornek":"Konuk randevu saatinde başvuru merkezine gider; görevli evrakını kontrol eder, biyometrik kaydını alır ve dosyayı konsolosluğa iletir.","sektor":"Aracı kurum yalnız evrakı toplar; vize kararını konsolosluk verir. Başvuru aracı kurum üzerinden ya da doğrudan konsolosluğa yapılır; evrak güncel ve eksiksiz, pasaport yıpranmamış olmalıdır.","iliskili":["os-4-106","os-4-108","os-4-109"],"kontrol":null,"cizim":"pasaport"},{"id":"os-4-123","konu":"4.5.1","terim":"Vize başvuru aracı kurumları","ingilizce":"Visa application service providers (VFS Global, iDATA, BLS)","tanim":"Bazı ülkelerin konsolosluklarına yapılan vize başvurularında evrakı ve biyometrik veriyi konsolosluk adına toplayan, VFS Global, iDATA ve BLS gibi özel şirketlerdir.","ornek":"Bir konuk İspanya turuna katılacaktır; acente görevlisi başvurunun, konsolosluğun çalıştığı aracı kurumdan randevu alınarak yapılacağını söyler.","sektor":"Bu kurumlar yalnız başvuruyu alır, vize kararını konsolosluk verir. Hangi ülkenin hangi kurumla çalıştığı ve hangi ek ücreti istediği ülkeye göre değişir; acente başvuru öncesi bunu ilgili konsolosluğun resmî sitesinden doğrular.","iliskili":["os-4-107","os-4-106","os-4-108"],"kontrol":null,"cizim":"pasaport"},{"id":"os-4-108","konu":"4.5.1","terim":"Vize başvuru belgeleri","ingilizce":"Visa application documents","tanim":"Konsolosluğun vize başvurusunda istediği pasaport, başvuru formu, fotoğraf, sigorta, rezervasyon, mali durum ve meslek belgelerinden oluşan dosyadır.","ornek":"Vize sorumlusu konuğun dosyasını son kez sayar: pasaport, imzalı form, fotoğraf, sigorta poliçesi, uçak ve otel rezervasyonu, banka dökümü, iş yeri yazısı, nüfus kayıt örneği.","sektor":"İstenen belgeler vizenin amacına ve ülkeye göre değişir; pasaportun seyahat bittikten sonra da bir süre geçerli olması beklenir. Eksik ya da gerçeğe aykırı belge ret nedenidir; acente konuğun belgesini “düzeltmez”, gerçeğe aykırı evrak hazırlamaz.","iliskili":["os-4-017","os-4-109","os-4-118"],"kontrol":null,"cizim":"pasaport"},{"id":"os-4-124","konu":"4.5.1","terim":"Vizenin temel gerekleri","ingilizce":"Core visa requirements","tanim":"Konsolosluğun vize başvurusunda genellikle istediği pasaport, form, fotoğraf, sigorta, mali durum, rezervasyon ve meslek belgelerinin kitaptaki ayrıntılı listesidir.","ornek":"Vize sorumlusu konuğun dosyasını kitaptaki listeye göre kontrol eder: pasaportun boş sayfası var, fotoğraf ölçüye uygun, banka dökümü imzalı ve kaşeli, sigorta tüm Schengen ülkelerini kapsıyor.","sektor":"Ders kitabına göre pasaport seyahat bitiminden sonra en az 3-6 ay daha geçerli olmalı ve en az 2 boş sayfası bulunmalıdır. Başvuru formu konsolosluğun ya da aracı kurumun (VFS Global, iDATA, BLS) sitesinden doldurulup imzalanır. Biyometrik fotoğraf 35x45 mm boyutunda, arka fonu beyaz, son 6 ayda çekilmiş 2 adettir. Sigorta tüm Schengen ülkelerinde geçerli ve teminatlıdır. Mali durum için son 3 aya ait imzalı, kaşeli banka hesap dökümü istenir. Uçak ve otel rezervasyonları eklenir. Mesleki belgeler çalışanlarda maaş bordrosu, SGK işe giriş bildirgesi ve izin belgesi; şirket sahiplerinde vergi levhası ve imza sirküleridir. Tam vukuatlı nüfus kayıt örneği e-Devlet’ten barkodlu alınabilir. Her ülkenin ortak istediği belgeler arasında ikametgâh belgesi ve evlilerde aile cüzdanı da sayılır. Liste ülkeye ve vize amacına göre değişebilir.","iliskili":["os-4-108","os-4-109","os-4-118"],"kontrol":null},{"id":"os-4-109","konu":"4.5.1","terim":"Biyometrik fotoğraf","ingilizce":"Biometric photograph","tanim":"Kişinin yüz hatlarının net biçimde tanınabilmesi için belirli ölçü ve kurallara göre çekilen resmî belge fotoğrafıdır.","ornek":"Fotoğrafçı konuğa “Başınızı dik tutun, objektife bakın, ağzınız kapalı olsun” der; arka fon düz ve açık renklidir.","sektor":"Hem pasaport hem vize başvurusunda istenir ve yakın zamanda çekilmiş olmalıdır. Kurala uymayan fotoğraf başvurunun geri çevrilmesine yol açabilir; küçük ayrıntı büyük gecikme demektir.","iliskili":["os-4-108","os-4-115","os-4-110"],"kontrol":null},{"id":"os-4-110","konu":"4.5.1","terim":"Pasaport","ingilizce":"Passport","tanim":"Yetkili makamlarca düzenlenen, kişinin yabancı bir ülkede kimliğini ve uyruğunu kanıtlayan temel seyahat belgesidir.","ornek":"Havalimanında görevli memur konuğun pasaportunu kontrol eder ve çıkış işlemini yapar; konuk ancak bundan sonra uçağa geçer.","sektor":"Türkiye’de pasaport işlemleri 5682 sayılı Pasaport Kanunu’na dayanır; günümüz pasaportları yüksek güvenlikli, biyometrik belgelerdir. Otelde yabancı konuğun kaydı pasaport bilgileriyle yapılır.","iliskili":["os-4-111","os-4-115","os-4-097"],"kontrol":null,"cizim":"pasaport"},{"id":"os-4-111","konu":"4.5.1","terim":"Umuma mahsus pasaport","ingilizce":"Ordinary passport","tanim":"Bordo kapaklı olan, resmî bir görevi ya da özel bir hakkı bulunmayan bütün vatandaşların alabildiği en yaygın pasaporttur.","ornek":"Yaz tatilinde ailesiyle Yunan adalarına gidecek bir lise öğrencisi bordo pasaport çıkarır.","sektor":"Gezi, iş ve eğitim amacıyla kullanılır. Acentelerin vize işlemi yaptığı konukların çoğu bu pasaportu taşır; alırken harç ve defter bedeli ödenir.","iliskili":["os-4-110","os-4-112","os-4-116"],"kontrol":null,"cizim":"pasaport"},{"id":"os-4-112","konu":"4.5.1","terim":"Hususi damgalı pasaport","ingilizce":"Special passport","tanim":"Yeşil kapaklı olan, belirli derecedeki devlet memurlarına, emeklilerine ve kanunda sayılan yakınlarına verilen pasaporttur.","ornek":"Yüksek dereceli bir devlet memuru, hak kazandığı yeşil pasaportla birçok ülkeye vize başvurusu yapmadan gidebilir.","sektor":"Sahibine birçok ülkeye vizesiz girme kolaylığı sağlar; harçtan muaftır, yalnız defter bedeli ödenir. Acente aynı turdaki konukların pasaport türüne göre vize ihtiyacını ayrı ayrı kontrol eder. Ders kitabına göre yeşil pasaport 160’tan fazla ülkeye (Schengen dâhil) vizesiz seyahat imkânı verir ve 10 yıl geçerlidir.","iliskili":["os-4-111","os-4-113","os-4-114"],"kontrol":null,"gorsel":"h4-yesil-pasaport"},{"id":"os-4-113","konu":"4.5.1","terim":"Hizmet damgalı pasaport","ingilizce":"Service passport","tanim":"Gri kapaklı olan, devlet adına yurt dışında resmî görev yapacak kişilere yalnız görev süresiyle sınırlı olarak verilen pasaporttur.","ornek":"Erasmus+ projesiyle İtalya’ya gidecek turizm lisesi öğrencileri ve öğretmenleri için okul, gri pasaport işlemlerini başlatır.","sektor":"Turistik amaçla kullanılamaz ve görev bitince iade edilir. Yeşil pasaportla karıştırılır: yeşil pasaport kişinin memuriyet durumuna, gri pasaport verilen göreve bağlıdır.","iliskili":["os-4-112","os-4-117","os-4-103"],"kontrol":null,"gorsel":"h4-gri-pasaport"},{"id":"os-4-114","konu":"4.5.1","terim":"Diplomatik pasaport","ingilizce":"Diplomatic passport","tanim":"Siyah kapaklı olan, Dışişleri Bakanlığının diplomatlara ve devlet adına görev yapan üst düzey yetkililere verdiği pasaporttur.","ornek":"Yurt dışına atanan bir büyükelçi göreve diplomatik pasaportla gider.","sektor":"Veren makam Dışişleri Bakanlığıdır. Renk – tür eşleşmesi sık sorulur: bordo – umuma mahsus, yeşil – hususi damgalı, gri – hizmet damgalı, siyah – diplomatik.","iliskili":["os-4-111","os-4-112","os-4-113"],"kontrol":null,"cizim":"pasaport"},{"id":"os-4-115","konu":"4.5.1","terim":"Pasaport başvurusu","ingilizce":"Passport application","tanim":"Randevu alınarak nüfus müdürlüğüne şahsen yapılan; kimlik, biyometrik fotoğraf ve ödeme bilgisiyle tamamlanan resmî işlemdir.","ornek":"Öğrenci e-Devlet’ten randevu alır; randevu günü kimlik kartı ve fotoğrafıyla ilçe nüfus müdürlüğüne gider, yanında annesi de bulunur.","sektor":"Randevu 199 numaralı telefon hattından, internetten, NVI Mobil uygulamasından ya da e-Devlet üzerinden alınır. Kimlik olarak nüfus cüzdanı, T.C. kimlik kartı ya da geçici kimlik belgesi kabul edilir; sürücü belgesi, kurum kimliği ve aile cüzdanı kabul edilmez. Daha önce alınmış, iptal edilmemiş pasaportlar da başvuruda getirilir. Ergin olmayanların başvurusunda anne ya da baba hazır bulunur; bulunamıyorsa yazılı izin, yani muvafakat belgesi gerekir.","iliskili":["os-4-110","os-4-116","os-4-109"],"kontrol":null,"cizim":"pasaport"},{"id":"os-4-116","konu":"4.5.1","terim":"Pasaport harcı ve defter bedeli","ingilizce":"Passport fee and booklet charge","tanim":"Bir pasaport çıkarılırken devlete ödenen harç ile pasaport defterinin kendi ücreti olan defter bedelinden oluşan iki ayrı ödemedir.","ornek":"Üniversite öğrencisi öğrenci belgesini gösterir; harç ödemez, yalnız defter bedelini yatırır.","sektor":"Harç pasaportun süresine göre artar; tutarlar her yıl güncellendiği için ezberlenmez, resmî siteden bakılır. Hususi ve hizmet damgalı pasaportlar harçtan muaftır; öğrenci olduğunu belgeleyenler de belirli bir yaşa kadar harç ödemez. Ders kitabına göre öğrenci olduğunu belgeleyenlere 25 yaşını doldurana kadar harç alınmaz, yalnız pasaport defter bedeli ödenir.","iliskili":["os-4-115","os-4-111","os-4-112"],"kontrol":null},{"id":"os-4-117","konu":"4.5.1","terim":"Hizmet damgalı pasaport talep formu","ingilizce":"Service passport request form","tanim":"Görevlendirilen kişiye gri pasaport verilmesi için çalıştığı kurumun düzenleyip onayladığı resmî formdur.","ornek":"Okul müdürlüğü, proje için görevlendirilen öğretmenin kimlik, unvan ve görev tarihlerini forma yazar; form imzalanıp mühürlendikten sonra nüfus müdürlüğüne götürülür.","sektor":"Dijital ortamda doldurulup yazıcıdan çıkarılır; ön ve arka yüzü tek yaprakta, ıslak imzalı ve mühürlü olmalıdır. Kitaptaki forma göre düzenlendiği tarihten itibaren 60 gün geçerlidir. Resmî formda günlük konuşma dili kullanılmaz; tek hata evrakın geri dönmesine yol açar.","iliskili":["os-4-113","os-4-115"],"kontrol":null,"cizim":"pasaport"},{"id":"os-4-138","konu":"4.5.1","terim":"Pasaport başvurusunda gerekli belgeler","ingilizce":"Documents required for a passport application","tanim":"Kimlik belgesi, biyometrik fotoğraf, harç ve defter bedelinin ödendiğini gösteren dekont, varsa eski pasaport ve ergin olmayanlar için yasal temsilcinin izni gibi başvuruda nüfus müdürlüğüne verilen belgelerdir.","ornek":"Pazartesi 09.00, ilçe nüfus müdürlüğü: lise öğrencisi kimlik kartını, fotoğrafını, ödeme dekontunu ve annesini birlikte getirir; iptal edilmemiş eski pasaportunu da yanında taşır.","sektor":"Kitaptaki liste bordo (umuma mahsus) pasaport içindir. Eksik belge randevunun boşa gitmesine yol açar; acente çalışanı konuğuna listeyi önceden söyler.","iliskili":["os-4-115","os-4-116","os-4-110"],"kontrol":null,"cizim":"pasaport"},{"id":"os-4-139","konu":"4.5.1","terim":"Hizmet damgalı pasaport taahhüt belgesi","ingilizce":"Undertaking form for service passport","tanim":"Hak sahibi kişinin, hizmet damgalı pasaport alan ergin çocuğunun hak şartlarını kaybetmesi hâlinde bunu nüfus müdürlüğüne bildireceğini yazdığı belgedir.","ornek":"Perşembe 14.00, bir kamu kurumunun insan kaynakları birimi: hak sahibi görevli, ergin çocuğu için doldurduğu hizmet damgalı pasaport talep formunun arka yüzündeki taahhüdü imzalar.","sektor":"Kitaba göre taahhüt belgesi talep formunun arka yüzünde yer alır ve yalnız ergin çocuklar için doldurulur. Çocuk şartları kaybederse nüfus müdürlüğüne bildirmek hak sahibinin sorumluluğundadır.","iliskili":["os-4-117","os-4-113","os-4-115"],"kontrol":null,"cizim":"pasaport"},{"id":"os-4-140","konu":"4.5.1","terim":"Tam vukuatlı nüfus kayıt örneği","ingilizce":"Full civil registration record","tanim":"Kişinin nüfus kaydındaki aile bilgilerini ve evlilik, doğum gibi olayları gösteren, e-Devlet’ten barkodlu alınabilen belgedir.","ornek":"Vize dosyasını hazırlayan konuk, e-Devlet’ten barkodlu tam vukuatlı nüfus kayıt örneğini alır ve çıktısını dosyaya koyar.","sektor":"Kitabın vize başvuru belgeleri listesinde yer alır; her ülke ortak olarak ister. Acente konuğa e-Devlet’ten alınabildiğini hatırlatır.","iliskili":["os-4-108","os-4-124"],"kontrol":null,"cizim":"belge-form"},{"id":"os-4-118","konu":"4.5.2","terim":"Seyahat sağlık sigortası","ingilizce":"Travel health insurance","tanim":"Yolculuk sırasında ortaya çıkan acil sağlık giderlerini ve poliçede yazan diğer beklenmedik masrafları karşılayan sigortadır.","ornek":"Roma’da ayağını burkan konuk hastaneye gider; tedavi masrafı, yanındaki poliçe kapsamında sigorta şirketince karşılanır.","sektor":"Seyahat sigortası da denir; yurt içi ve yurt dışı seyahatler için yapılabilir. Schengen vizesi başvurusunda istenen belgelerdendir. Acentenin yaptırdığı zorunlu paket tur sigortasından farklıdır: bu sigorta yolcunun kendi sağlığını ve eşyasını korur.","iliskili":["os-4-119","os-4-120","os-4-104"],"kontrol":null,"cizim":"bavul"},{"id":"os-4-119","konu":"4.5.2","terim":"Sigorta poliçesi","ingilizce":"Insurance policy","tanim":"Sigortanın neyi, hangi tarihler arasında ve hangi koşullarla karşıladığını gösteren yazılı sözleşmedir.","ornek":"Satış görevlisi konuğa poliçeyi verirken tarihleri gösterir: “Sigortanız gidiş gününüzde başlıyor, dönüş gününüzde bitiyor efendim.”","sektor":"Üç şeye bakılır: kapsam, seyahatin ilk gününden son gününe kadar bütün süreyi içermesi ve teminatlar. Tarihi bir gün eksik yazılmış poliçe vize başvurusunda sorun çıkarabilir.","iliskili":["os-4-118","os-4-120","os-4-084"],"kontrol":null,"cizim":"sigorta-semsiye"},{"id":"os-4-120","konu":"4.5.2","terim":"Teminat","ingilizce":"Cover","tanim":"Sigorta şirketinin, poliçede yazan bir durum gerçekleştiğinde karşılamayı üstlendiği güvencedir.","ornek":"Konuk Uludağ’da kayak yapacaktır; görevli poliçeyi açar, kış sporlarının kapsamda olup olmadığına bakar ve gerekiyorsa ek teminat önerir.","sektor":"Temel teminatlara istenirse ek teminatlar eklenir. Görevli poliçede yazmayan bir şeyi “Sigorta karşılar” diye söylemez; emin değilse sigorta şirketine sorar.","iliskili":["os-4-119","os-4-118"],"kontrol":null,"cizim":"sigorta-semsiye"},{"id":"os-4-125","konu":"4.5","terim":"Döviz beyan formu","ingilizce":"Currency declaration form","tanim":"Yolcunun sınırı geçerken yanında taşıdığı, belirli sınırı aşan döviz ve nakit parayı gümrüğe bildirdiği formdur.","ornek":"Yurt dışına çıkacak bir iş insanı yanındaki nakit tutar sınırı aştığı için havalimanında formu doldurup gümrük görevlisine verir.","sektor":"Ders kitabı döviz beyan formlarını, uluslararası seyahatlerde bulundurulması gereken temel belgeler arasında sayar. Eksik ya da yanlış beyan ciddi yaptırım doğurabilir; sınırlar değişebildiği için acente tutar tahmin etmez, güncel kuralı resmî kaynaktan doğrular ve konuğu önceden bilgilendirir.","iliskili":["os-4-096","os-4-095","os-4-118"],"kontrol":null,"cizim":"belge-form"},{"id":"os-4-126","konu":"4.5","terim":"Vekâletname ve seyahat izin belgesi","ingilizce":"Power of attorney and travel consent letter","tanim":"Kişinin kendi adına işlem yapması için başkasına verdiği yazılı yetki ile reşit olmayan yolcuya yasal temsilcisinin yazılı izin verdiğini gösteren belgelerdir.","ornek":"Bir anne kızının yalnız yapacağı yurt dışı geziyi acenteye bildirir; acente görevlisi, gidilecek ülke ve hava yolunun istediği yazılı izin belgesini önceden hazırlamasını söyler.","sektor":"Ders kitabı bu belgeleri uluslararası seyahatte bulundurulması gereken belgeler arasında sayar. Bu belgeler çoğu zaman noterde düzenlenir; hangi durumda hangisinin istendiği ülkeye ve taşıyıcıya göre değişir. Acente konuğa “bir şey olmaz” demez, belgeyi resmî kaynaktan doğrulayıp yolculuktan önce tamamlatır.","iliskili":["os-4-125","os-4-115","os-4-118"],"kontrol":null,"cizim":"sozlesme"}],"sorular":[{"id":"os-4-s01","tur":"coktan-secmeli","soru":"Bir konuk acenteye gelip dört şey istiyor. Hangisi acentenin altı temel hizmeti arasında yer almaz?","secenekler":["Roma uçuşu için bilet kesilmesi","Yeni pasaportunun acentece çıkarılması","Hafta sonu için araç kiralanması","İtalya vizesi başvurusunun hazırlanması"],"dogru":1,"aciklama":"Pasaportu acente değil, devlet (nüfus müdürlüğü) düzenler. Bilet, araç kiralama ve vize işlemleri ise acentenin altı temel işindendir."},{"id":"os-4-s02","tur":"coktan-secmeli","soru":"Tur satıldı. Pazartesi sabahı gruba otobüs ayarlanacak, otelle karşılama saati netleşecek, rehber görevlendirilecek. Bu işleri sahada yürüten bölüm hangisidir?","secenekler":["Satış ve pazarlama","Rezervasyon","Operasyon","Muhasebe"],"dogru":2,"aciklama":"Satılmış turun transfer, konaklama ve rehberlik hizmetlerini aksamadan yürütmek operasyonun işidir. Rezervasyon yalnızca oda ve koltukları ayırtır, işi sahada yürütmez."},{"id":"os-4-s03","tur":"coktan-secmeli","soru":"Acentenin broşüründe “deniz manzaralı oda” yazıyor, ama otel otoparka bakan bir oda verdi. Acente açısından bu durum nasıl değerlendirilir?","secenekler":["Verilen satış vaadi tutulmamıştır ve konuk haklı olarak şikâyet edebilir.","Oda tipi otelin takdirindedir, bu yüzden acente sorumlu tutulamaz.","Broşür yalnız tanıtım içindir, bu yüzden hiçbir bağlayıcılığı yoktur.","Yüksek sezonda manzara garantisi verilemez, bu durum olağandır."],"dogru":0,"aciklama":"Konuğa yazılı ya da sözlü verilen söz, tur boyunca yerine getirilmesi gereken satış vaadidir. Oda tipini otel belirlese de sözü veren acentedir."},{"id":"os-4-s04","tur":"coktan-secmeli","soru":"Konuk, Londra gezisinden önce “Vize gerekir mi, yanıma ne kadar döviz alabilirim, gümrükte neye dikkat etmeliyim?” diye soruyor. Bu soruları yanıtlaması beklenen acente görevlisi kimdir?","secenekler":["Bilet personeli","Acente rezervasyon memuru","Tur sorumlusu","Enformasyon memuru"],"dogru":3,"aciklama":"Vize, gümrük, döviz ve gidilecek yer hakkında bilgi vermek enformasyon memurunun işidir. Bilet personeli bilet düzenler, rezervasyon memuru yer ayırtır."},{"id":"os-4-s05","tur":"dogru-yanlis","soru":"Vize sorumlusu, evrakı eksiksiz olan konuğa vizesinin kesin çıkacağı sözünü verebilir.","secenekler":["Doğru","Yanlış"],"dogru":1,"aciklama":"Vize kararını gidilecek ülkenin konsolosluğu verir. Evrakı eksiksiz hazırlamak başvuruyu güçlendirir ama sonucu garanti etmez; tutulamayacak söz vermek de satış vaadini zedeler."},{"id":"os-4-s06","tur":"coktan-secmeli","soru":"Aşağıdaki rehber davranışlarından hangisi meslek etiğine aykırıdır?","secenekler":["Programdaki durakları yazıldığı gibi gezdirmek","Konukların özel bilgilerini başkalarıyla paylaşmamak","Komisyon almak için programı değiştirip nedenini saklamak","Gezilen yer hakkında bildiği doğru bilgiyi aktarmak"],"dogru":2,"aciklama":"Meslek etiği doğruluk ve dürüstlük ister. Programı kişisel çıkar için değiştirip konuğa gerçek nedeni söylememek bu ilkelere aykırıdır; diğer şıklar etik davranıştır."},{"id":"os-4-s07","tur":"coktan-secmeli","soru":"Bir acente yeni bir Karadeniz turu hazırlıyor. Otellerle sözleşme imzalamadan önce hangi iş yapılmış olmalıdır?","secenekler":["Turun nereye, ne zaman ve kimler için yapılacağının tasarlanması","Turun konuklara satılması ve rezervasyonların alınması","Saha operasyonunun yürütülmesi","Konuklardan geri bildirim toplanması"],"dogru":0,"aciklama":"Süreç planlama ile başlar; ancak tasarlanmış tur için oda, koltuk gibi hizmetler tedarik edilip sözleşmeye bağlanır. Satış ve saha tedarikten, değerlendirme saha sonrasından gelir."},{"id":"os-4-s08","tur":"coktan-secmeli","soru":"Aşağıdaki acentelerden hangisi C grubu belgesiyle çalışabilir?","secenekler":["Yurt dışına paket turlar düzenleyip bunları satan acente","Yabancı konuklar için Türkiye turları hazırlayan acente","Yalnız uluslararası uçak ve deniz bileti satan, tur düzenlemeyen acente","Türk konuklar için Ankara’dan Safranbolu–Amasra turu düzenleyen acente"],"dogru":3,"aciklama":"C grubu yalnız Türk vatandaşları için yurt içi tur düzenler. Yurt dışı tur ve yabancı konuk işi A grubunun, yalnız bilet satışı B grubunun alanındadır."},{"id":"os-4-s09","tur":"coktan-secmeli","soru":"B grubu bir acentede çalışıyorsun. Konuk Yunan Adaları turunu istiyor. Hangisini yapabilirsin?","secenekler":["Uçak, otel ve rehberliği birleştirip kendi paket turumu oluştururum.","A grubu bir acentenin hazırladığı turun biletini satabilirim.","Yeni bir Yunan Adaları turunu kendi adıma düzenleyip satarım.","C grubu bir acenteden turu alıp kendi adıma yeniden düzenlerim."],"dogru":1,"aciklama":"B grubu kara, deniz ve hava biletlerini ve A grubu acentelerin düzenlediği turların biletini satabilir; kendi adına tur düzenleme yetkisi yoktur."},{"id":"os-4-s10","tur":"dogru-yanlis","soru":"Hem yurt dışından gelen konukları karşılayıp hem Türk konukları yurt dışı turuna gönderen bir acentenin A grubu olması gerekir.","secenekler":["Doğru","Yanlış"],"dogru":0,"aciklama":"A grubu paket tur, biletleme ve transfer dâhil bütün faaliyetlere yetkilidir. C grubu yabancı konuk ağırlayamaz, B grubu tur düzenleyemez."},{"id":"os-4-s11","tur":"coktan-secmeli","soru":"Dalaman’da İngiltere’deki bir tur operatörünün gönderdiği konukları havalimanında karşılayıp tatilleri boyunca ilgilenen acente hangi türdür?","secenekler":["Yurt dışı gönderici (outgoing) acente","Yurt içi gönderici (ingoing) acente","Karşılayıcı (incoming) acente","Toptancı seyahat acentesi"],"dogru":2,"aciklama":"Yurt dışından gelen konukları ülkede karşılayan acente incoming’dir. Outgoing yerli konukları yurt dışına, ingoing yerli konukları yurt içinde gezdirir."},{"id":"os-4-s12","tur":"coktan-secmeli","soru":"Bir acente yaz için bir otelden yüzlerce geceleme satın alıyor ve bu odaları mahalledeki küçük acentelere dağıtıyor. Bu acente hangi türdür?","secenekler":["Toptancı seyahat acentesi","Perakendeci seyahat acentesi","Karşılayıcı (incoming) acente","Zincir seyahat acentesi"],"dogru":0,"aciklama":"Hizmeti toplu alıp başka acentelere satan toptancıdır. Perakendeci ise doğrudan son tüketiciye, yani konuğun kendisine satar."},{"id":"os-4-s13","tur":"coktan-secmeli","soru":"Konuk uçuşunu değiştirmek için acenteyi arıyor. Acentecinin hava yolu rezervasyon kaydını bulmak için ondan istemesi gereken bilgi hangisidir?","secenekler":["Otelin onay numarası (konfirmasyon)","Hizmet belgesi numarası (voucher)","Satış durdurma bildirimi (stop-sale)","Altı haneli rezervasyon kodu (PNR)"],"dogru":3,"aciklama":"PNR, yolcunun adı, uçuşu ve rotası gibi bilgilerin saklandığı hava yolu kaydına ulaştıran koddur. Konfirmasyon ve voucher otel ve hizmet belgeleridir."},{"id":"os-4-s14","tur":"coktan-secmeli","soru":"Konuk “Yerimi üç gün tutun, ödemeyi sonra yaparım.” diyor ve acente ona ödeme için son bir tarih tanıyor. Bu tarih ya da süreye ne denir?","secenekler":["Konfirmasyon","Opsiyon","Kontenjan","Voucher"],"dogru":1,"aciklama":"Opsiyon, kesinleşmemiş rezervasyonda ödeme için tanınan son tarihtir. Konfirmasyon ise rezervasyonun işletme tarafından yazılı olarak kesinleştiğini gösterir."},{"id":"os-4-s15","tur":"coktan-secmeli","soru":"Otel, acentenin rezervasyonunu yaptığı konuğu gece yarısına kadar bekledi; konuk gelmedi, arayıp iptal de etmedi. Bu durumun adı nedir?","secenekler":["Go-show","Overbooking","No-show","Stop-sale"],"dogru":2,"aciklama":"Rezervasyonu olup iptal ettirmeden gelmeyen konuk no-show’dur. Go-show bunun tersidir: rezervasyonsuz gelip doğrudan hizmet isteyen konuktur."},{"id":"os-4-s16","tur":"coktan-secmeli","soru":"Bir otel 100 odası için 104 rezervasyon alıyor; geçmiş sezonlarda her zaman birkaç konuk gelmemişti. Bu uygulamaya ne denir?","secenekler":["Overbooking","Stop-sale","Kontenjan","Son dakika satışı"],"dogru":0,"aciklama":"Bazı rezervasyonların iptal olacağını hesaplayıp kapasitenin üzerinde rezervasyon almak overbooking’dir. Stop-sale ise tedarikçinin satışı geçici durdurmasıdır; kontenjan da ayrılmış yer sayısını anlatır."},{"id":"os-4-s17","tur":"coktan-secmeli","soru":"Konuk, otelin resepsiyonuna acentenin verdiği ve kaç gece, hangi oda tipini ve hangi pansiyon türünü satın aldığını yazan belgeyi gösteriyor. Bu belgenin adı nedir?","secenekler":["Itinerary","Konfirmasyon","Opsiyon","Voucher"],"dogru":3,"aciklama":"Voucher, konuğun hizmeti satın aldığını kanıtlayan hizmet belgesidir. Itinerary tur programını gösterir; konfirmasyon otelin rezervasyonu onayladığını bildirir."},{"id":"os-4-s18","tur":"dogru-yanlis","soru":"Charter uçuşta uçağın tamamı bir tur operatörü ya da acente tarafından kiralandığı için boş kalan koltukların zararını kiralayan üstlenir.","secenekler":["Doğru","Yanlış"],"dogru":0,"aciklama":"Charter, belirli bir grup ya da acente için kiralanan tarifesiz uçuştur. Uçak kiralandığı için dolmayan koltuklar kiralayanın zararıdır; tarifeli uçuşta bu risk hava yolundadır."},{"id":"os-4-s19","tur":"coktan-secmeli","soru":"Acente masasındaki bilgisayardan Amadeus gibi bir ağa girip birçok hava yolunun ve otelin boş yerlerini aynı anda görüyorsun. Bu küresel rezervasyon ağının ortak adı nedir?","secenekler":["BSP","GDS","PNR","MICE"],"dogru":1,"aciklama":"GDS, hava yollarını, otelleri, araç kiralama şirketlerini ve acenteleri birbirine bağlayan küresel rezervasyon ağıdır. PNR ise bu ağdaki tek bir yolcu kaydıdır."},{"id":"os-4-s20","tur":"coktan-secmeli","soru":"Paket turları üreten bir işletme, yaz için bir otelden garantili 200 oda ayırttı, ama 40’ı satılamadı. Boş kalan odaların bedelini hangi taraf öder?","secenekler":["Tur operatörü","Perakendeci seyahat acentesi","Otelin kendisi","Odayı satın almayan konuklar"],"dogru":0,"aciklama":"Operatör talep oluşmadan önce kapasite satın aldığı ve garanti verdiği için finansal riski üstlenir. Perakendeci acente ürünün sahibi değildir, mevcut ürünlerden seçip sattığı için satılamayan yerden zarar etmez."},{"id":"os-4-s21","tur":"coktan-secmeli","soru":"Konuk, acentenin belge numarasını soruyor. Acente bu işletme belgesini hangi kurumdan almıştır?","secenekler":["Türkiye Seyahat Acentaları Birliği (TÜRSAB)","Ulaştırma ve Altyapı Bakanlığı","Kültür ve Turizm Bakanlığı","Acentenin bulunduğu ilin belediyesi"],"dogru":2,"aciklama":"İşletme belgesini Kültür ve Turizm Bakanlığı verir. TÜRSAB’a ise belge alındıktan sonra üye olunur; belgeyi birlik vermez."},{"id":"os-4-s22","tur":"coktan-secmeli","soru":"1618 sayılı Kanun’a göre TÜRSAB’ın hukuki niteliği nedir?","secenekler":["Gönüllü üyelikle çalışan turizm derneği","Bakanlığa bağlı bir genel müdürlük","Uluslararası acente birlikleri federasyonu","Kamu kurumu niteliğinde meslek kuruluşu"],"dogru":3,"aciklama":"Kanun TÜRSAB’ı kamu kurumu niteliğinde meslek kuruluşu sayar; üyelik zorunlu olduğu için gönüllü bir dernek değildir. Dünya ölçeğindeki federasyon UFTAA’dır."},{"id":"os-4-s23","tur":"dogru-yanlis","soru":"Ders kitabına göre bir acente işletme belgesini aldıktan sonra TÜRSAB üyeliği isteğe bağlı olduğu için satışa hemen başlayabilir.","secenekler":["Doğru","Yanlış"],"dogru":1,"aciklama":"Acente iki şartla işe başlar: Bakanlıktan işletme belgesini alır ve TÜRSAB’a üye olur. Üyelik hukuken zorunludur; amacı kayıt dışı faaliyeti önlemektir."},{"id":"os-4-s24","tur":"coktan-secmeli","soru":"Acentenin sattığı turda otel rezervasyonu iptal oldu ve söz verilen hizmet hiç verilemedi. Konukları bu riske karşı güvenceye alan, acentenin yaptırmak zorunda olduğu sigorta hangisidir?","secenekler":["Seyahat sağlık sigortası","Zorunlu paket tur sigortası","Acente iş yeri sigortası","Araç kasko sigortası"],"dogru":1,"aciklama":"Zorunlu paket tur sigortası, söz verilen hizmetin eksik verilmesi ya da hiç verilmemesi riskine karşı yaptırılır. Seyahat sağlık sigortası ise yolcunun kendi sağlık giderlerini karşılar."},{"id":"os-4-s25","tur":"coktan-secmeli","soru":"Bir görevli, konuğun pasaport fotokopisini izinsiz biçimde bir mesajlaşma grubunda paylaşıyor. Bu davranış öncelikle hangi kanuna aykırıdır?","secenekler":["Kişisel Verilerin Korunması Kanunu (6698)","1618 sayılı Seyahat Acentaları Kanunu","Tüketicinin Korunması Hakkında Kanun (6502)","6326 sayılı Turist Rehberliği Meslek Kanunu"],"dogru":0,"aciklama":"Pasaport bilgisi kişisel veridir; toplanması, saklanması ve korunması 6698 sayılı KVKK ile düzenlenir. Diğer kanunlar acente, tüketici ve rehberlik işleriyle ilgilidir."},{"id":"os-4-s26","tur":"coktan-secmeli","soru":"Acente, 35 kişilik bir gezi grubu için transfer ayarlıyor. Aşağıdakilerden hangisi acentenin hizmet satın aldığı taraftır?","secenekler":["TÜRSAB","Konsolosluk","Otobüs firması","Kültür ve Turizm Bakanlığı"],"dogru":2,"aciklama":"Otel, restoran, otobüs gibi turu oluşturan hizmetler işletmelerden satın alınır. TÜRSAB, konsolosluk ve Bakanlık hizmet satılan taraf değil, izin, denetim ve temsil için muhatap olunan kuruluşlardır."},{"id":"os-4-s27","tur":"coktan-secmeli","soru":"Acente uçak bileti satabilmek için akreditasyon alacak ve ödemelerini BSP üzerinden yapacak. Bu yetkilendirmeyi hangi uluslararası kuruluş yönetir?","secenekler":["UFTAA","TUREB","UN Tourism","IATA"],"dogru":3,"aciklama":"IATA, hava yollarını bir araya getirir ve uçak bileti satan acentelerin yetkilendirilmesini yönetir. UFTAA ülkelerin acente birliklerinin dünya federasyonudur."},{"id":"os-4-s28","tur":"coktan-secmeli","soru":"Yurt dışındaki bir otelde aşçı olarak iş bulan genç, o ülkeye hangi vizeyle gitmelidir?","secenekler":["Turistik (gezi) vizesi","Çalışma vizesi","Transit (geçiş) vizesi","Öğrenci (eğitim) vizesi"],"dogru":1,"aciklama":"Vize seyahatin amacına göre alınır; yurt dışında çalışacak kişiye çalışma vizesi verilir. Turistik vize gezi ve tatil amacı içindir."},{"id":"os-4-s29","tur":"coktan-secmeli","soru":"Konuk, evindeki bilgisayardan başvuru formunu doldurup ücreti kartla ödüyor ve onay belgesini e-postayla alıyor. Bu vize türü hangisidir?","secenekler":["e-Vize","Kapıda vize","Transit vize","Schengen vizesi"],"dogru":0,"aciklama":"Konsolosluğa gitmeden internetten başvurulup alınan vize e-vizedir. Kapıda vize ise sınır kapısında ya da havalimanında verilir."},{"id":"os-4-s30","tur":"coktan-secmeli","soru":"Pasaport kapak renkleri ve türleri eşleştirmelerinden hangisi doğrudur?","secenekler":["Yeşil kapak: diplomatik pasaport","Bordo kapak: hususi damgalı pasaport","Gri kapak: hizmet damgalı pasaport","Siyah kapak: umuma mahsus pasaport"],"dogru":2,"aciklama":"Gri hizmet damgalı, yeşil hususi damgalı, bordo umuma mahsus, siyah ise diplomatik pasaporttur. En yaygın olanı bordo pasaporttur."},{"id":"os-4-s31","tur":"dogru-yanlis","soru":"Hususi damgalı (yeşil) pasaport, hizmet damgalı (gri) pasaport gibi yalnız görev süresince geçerlidir ve turistik gezide kullanılamaz.","secenekler":["Doğru","Yanlış"],"dogru":1,"aciklama":"Bu özellik gri pasaportundur; verilen göreve bağlıdır. Yeşil pasaport ise belirli derecedeki devlet memurlarına, emeklilerine ve kanunda sayılan yakınlarına verilir, kişinin memuriyet durumuna bağlıdır."},{"id":"os-4-s32","tur":"coktan-secmeli","soru":"Lise öğrencisi Elif yaz tatilinde yurt dışına çıkmak için bordo pasaport başvurusu yapacak. Hangisi doğru adımdır?","secenekler":["Aracı kurumdan randevu alıp evraklarını vize başvuru merkezine teslim etmesi","Kimlik ve fotoğrafıyla bir seyahat acentesine başvuru dosyası bırakması","Belediyeden randevu alıp pasaport dosyasını oraya teslim etmesi","Randevu alıp kimlik, fotoğraf ve ödeme bilgisiyle nüfus müdürlüğüne gitmesi"],"dogru":3,"aciklama":"Pasaport başvurusu randevuyla nüfus müdürlüğüne şahsen yapılır. Vize başvuru merkezi vize evrakını toplar, pasaport çıkarmaz; acente pasaport düzenleyemez."},{"id":"os-4-s33","tur":"dogru-yanlis","soru":"Sağlık sigortası poliçesinde kapsam ve teminatların yanında, poliçenin seyahatin ilk gününden son gününe kadar bütün süreyi içerip içermediğine de bakılır.","secenekler":["Doğru","Yanlış"],"dogru":0,"aciklama":"Üç şeye bakılır: kapsam, teminatlar ve seyahatin tamamını içeren süre. Tarihi bir gün eksik yazılmış poliçe vize başvurusunda sorun çıkarabilir."},{"id":"os-4-s44","tur":"coktan-secmeli","soru":"Bir acente çok sayıda şubesinde hizmeti aynı kalitede tutuyor ve toplu alımla ölçek avantajı sağlıyor. Bu acente hangi türdür?","secenekler":["Karşılayıcı (incoming) acente","Zincir seyahat acentesi","C grubu seyahat acentesi","Yurt içi gönderici acente"],"dogru":1,"aciklama":"Birden çok şubesi olan, hizmeti şubeler arasında standart tutan ve toplu alımla ölçek avantajı sağlayan acente zincir acentedir. Diğerleri faaliyet alanına ya da belge grubuna göre ayrılır."},{"id":"os-4-s45","tur":"dogru-yanlis","soru":"Paris–Amsterdam–Brüksel turuna katılan konuğun, Schengen Bölgesi’nde üç ülkeye girdiği için üç ayrı Schengen vizesi alması gerekir.","secenekler":["Doğru","Yanlış"],"dogru":1,"aciklama":"Schengen Bölgesi’ne tek ortak vize ile girilir; üye ülkeler arasında sınır kontrolü kalktığı için her ülke için ayrı vize gerekmez."},{"id":"os-4-s46","tur":"coktan-secmeli","soru":"Acente, Efes turu için belgeli bir rehber arıyor. Rehber odalarının bağlı olduğu, turist rehberlerini temsil eden birlik hangisidir?","secenekler":["TUREB","TÜROB","TÜROFED","UFTAA"],"dogru":0,"aciklama":"TUREB, rehber odalarının bağlı olduğu Türkiye Turist Rehberleri Birliğidir. TÜROB otelcileri, TÜROFED otelci federasyonunu, UFTAA acente birliklerinin dünya federasyonunu temsil eder."},{"id":"os-4-s34","tur":"senaryo","durum":"Gece 01.30, havalimanı. Transfer elemanına yardım eden stajyersin. Listede on iki konuk var, ama aracın başında on üç kişi bekliyor. Listede adı olmayan konuk “Ben de bu acentedenim, voucherım telefonumda.” diyor; şoför acele ediyor.","soru":"Ne yaparsın?","secenekler":["Yer var diye konuğu araca alır, şoföre yola çıkmasını söylerim.","Listede adı yok diyerek konuğa taksiyle gitmesini söylerim.","Aracı bekletir, durumu telefonla hemen operasyona bildirip yönlendirme beklerim.","Telefondaki voucherın görüntüsü doğru görünüyorsa kendim onaylarım."],"dogru":2,"aciklama":"Listede olmayan konuğun hakkı ancak operasyondan doğrulanır. Listeye bakmadan almak yanlış kişiyi taşıtabilir, geri çevirmek gerçek konuğu mağdur eder; kararı operasyon verir."},{"id":"os-4-s35","tur":"senaryo","durum":"Saat 15.00, satış masasında bir görevlinin yanında staj yapıyorsun. Görevli kısa süreliğine ayrıldı. Avrupa turuyla ilgilenen konuk sana dönüp “Vizem kesin çıkar, değil mi? Çıkmayacaksa hiç yazılmayayım.” diyor.","soru":"Ne yaparsın?","secenekler":["“Evrakınız tamsa vizeniz kesin çıkar efendim, merak etmeyin.” derim.","“Bugüne kadar kimse reddedilmedi, siz de alırsınız.” derim.","“Vize işlerine ben bakmıyorum, bir bilgim yok.” deyip susarım.","Vize kararını konsolosluğun verdiğini söyler, görevliyi çağırırım."],"dogru":3,"aciklama":"Vize kararını gidilecek ülkenin konsolosluğu verir; kesin söz vermek tutulamayacak bir satış vaadidir. Susmak da konuğu ortada bırakır; doğru olan gerçeği söyleyip yetkili görevliyi çağırmaktır."},{"id":"os-4-s36","tur":"senaryo","durum":"Saat 10.20. Rezervasyon ekranında bir otel için “bayram haftası stop-sale” mesajı görünüyor. Yanında çalıştığın satış görevlisi telefonda; karşındaki konuk tam o hafta, o oteli istiyor ve “Geçen yıl da siz ayarlamıştınız.” diyor.","soru":"Ne yaparsın?","secenekler":["Konuğu kırmamak için kaydını alır, “Yeriniz hazır.” diye söz veririm.","Otelin o hafta satışa kapalı olduğunu söyler, görevliye haber veririm.","“Belki açılır.” diyerek ödemesini alır, sonrasını otele bırakırım.","“O otel dolu, yapacak bir şey yok.” diyerek konuğu uğurlarım."],"dogru":1,"aciklama":"Stop-sale, tedarikçinin satışı geçici olarak durdurduğu anlamına gelir; o tarihe yer söz vermek tutulamayacak vaattir. Doğrusu durumu açıkça söylemek ve görevliyle alternatif aramaktır."},{"id":"os-4-s37","tur":"senaryo","durum":"Cuma 16.45. Konuğun opsiyonu saat 17.00’de doluyor. Konuk arıyor: “Maaşım pazartesi yatacak, yerimi pazartesiye kadar tutar mısınız?” Satış görevlisi başka bir konukla görüşüyor, telefon sende.","soru":"Ne yaparsın?","secenekler":["“Tabii efendim, pazartesiye kadar yeriniz sizde.” derim.","“Opsiyon uzamaz, saat beşte yeriniz iptal olacak.” deyip kapatırım.","Söz vermeden not alır, görevliye sorup konuğu geri ararım.","Kimseye sormadan sistemde opsiyon tarihini kendim değiştiririm."],"dogru":2,"aciklama":"Opsiyonu uzatmak acentenin ve işletmenin yetkisindedir. Söz vermek ya da kesin “hayır” demek yerine yetkiliye danışmak konuğu da acenteyi de korur; sürenin dolmasına az kaldığı için hızlı davranılır."},{"id":"os-4-s38","tur":"senaryo","durum":"Saat 11.00, vize bölümü. Yirmi kişilik grubun pasaport fotokopilerini taratıyorsun. Bir çalışma arkadaşın “Hepsini benim telefonuma, mesajlaşma grubuna at; evden bakarım, daha hızlı olur.” diyor.","soru":"Ne yaparsın?","secenekler":["Göndermem; acentenin kullandığı güvenli yolu sorumluya sorarım.","Arkadaşım kıdemli olduğu için fotoğrafları hemen gruba atarım.","Yalnız ilk sayfaları gönderir, akşam olunca gruptan silerim.","Konukların adını kapatır, numaraları açık bırakıp gönderirim."],"dogru":0,"aciklama":"Pasaport bilgisi kişisel veridir (KVKK); izinsiz paylaşılan veri sonradan silinse bile geri alınamaz. Kısmi ya da eksik gizleme de riski ortadan kaldırmaz; acentenin belirlediği yol kullanılır."},{"id":"os-4-s39","tur":"senaryo","durum":"Kapadokya turunun ikinci günü, stajyer olarak gruba eşlik ediyorsun. Programda yazan köy pazarı ziyareti yapılmadan otobüs bir mağazaya yöneliyor. İki konuk yanına gelip “Programda pazar vardı, neden gitmedik?” diye soruyor.","soru":"Ne yaparsın?","secenekler":["“Zaman kalmadı, pazar zaten kapalıydı.” diyerek konuyu kapatırım.","Grubun önünde rehbere dönüp neden gitmediğimizin hesabını sorarım.","Konuklara rehberin komisyon aldığını düşündüğümü anlatırım.","Nedenini bilmediğimi söyler, durumu hemen operasyona bildiririm."],"dogru":3,"aciklama":"Programdaki söz tutulmuyorsa bunu operasyona bildirmek gerekir; bilmediğin nedeni uydurmak, rehberi konuklar önünde suçlamak ya da tahmin yürütmek hem yanlış bilgi verir hem etiğe aykırıdır."},{"id":"os-4-s40","tur":"senaryo","durum":"Saat 14.30, vize masası. Konuk banka dökümünü uzatıp “Bakiye biraz düşük görünüyor. Siz bilgisayarda rakamı düzeltiverin, kimse anlamaz.” diyor. Vize sorumlusu öğle arasında, dosyaları sen düzenliyorsun.","soru":"Ne yaparsın?","secenekler":["Konuk memnun kalsın diye rakamı düzeltir, dosyaya eklerim.","Kibarca reddeder, durumu vize sorumlusuna bildiririm.","Dökümü dosyadan çıkarır, eksik belgeyle başvuruyu gönderirim.","“Bu yaptığınız sahtecilik!” diyerek konuğu herkesin içinde azarlarım."],"dogru":1,"aciklama":"Gerçeğe aykırı belge hazırlanmaz; sahte evrak başvurunun reddine neden olur. Belgeyi sessizce çıkarmak ya da konuğu azarlamak da çözüm değildir; nazik bir ret ve sorumluya bildirim doğru yoldur."},{"id":"os-4-s41","tur":"senaryo","durum":"Perşembe 18.10. Cumartesi sabahı çıkacak İtalya turundan bir konuk arıyor: “Vizem yetişmedi, eşimle ben gelemiyoruz.” Operasyon sorumlusu toplantıda, mesajı sen aldın.","soru":"Ne yaparsın?","secenekler":["Bilgiyi hemen operasyon sorumlusuna yazılı olarak iletirim.","Yarın sabah nasılsa görüşürüz diye not alır, mesaiden çıkarım.","Konuğa paranın tamamının iade edileceğini kendim söylerim.","Otele ve hava yoluna iptali kimseye sormadan kendim bildiririm."],"dogru":0,"aciklama":"Tur cumartesi sabahı çıkacağından iptal, iade ve otel bildirimi gibi kararlar süre dolmadan operasyonun verdiği kararlardır. Yazılı bildirim hem hızlıdır hem kayıt bırakır; kendi başına söz vermek yetkiyi aşar."},{"id":"os-4-s42","tur":"senaryo","durum":"Saat 17.20, biletleme masası. Yarın sabah uçacak bir konuğun biletini dosyaya koyarken soyadının pasaporttakinden bir harf farklı yazıldığını görüyorsun. Bileti kesen görevli az önce çıktı.","soru":"Ne yaparsın?","secenekler":["Tek harf fark eder mi diyerek bileti dosyaya koyar, işime bakarım.","Hava yolu sistemine girip soyadını kendi bildiğim gibi düzeltirim.","Farkı hemen sorumluya bildirir, pasaport bilgisiyle bileti birlikte gösteririm.","Konuğu arayıp sorunu havalimanında çözmesini söylerim."],"dogru":2,"aciklama":"Bilet adı pasaporttakiyle birebir aynı olmalıdır; küçük bir fark bile yolcunun uçağa alınmamasına yol açabilir. Düzeltme yetkili görevlinin işidir, bu yüzden sorun geç kalmadan ona bildirilir."},{"id":"os-4-s43","tur":"senaryo","durum":"Saat 12.15. Kayak tatiline gidecek konuk poliçesini alırken soruyor: “Kayak yaparken sakatlanırsam bu sigorta karşılar, değil mi?” Poliçede kış sporlarının yazıp yazmadığını bilmiyorsun.","soru":"Ne yaparsın?","secenekler":["“Tabii efendim, seyahat sigortası her şeyi karşılar.” derim.","“Sanmıyorum, kayak genelde kapsam dışıdır.” diye tahmin yürütürüm.","“Orasını sigorta şirketine sorarsınız.” diyerek poliçeyi teslim ederim.","Poliçeye bakar, emin olamazsam sigorta şirketine ya da yetkiliye danışırım."],"dogru":3,"aciklama":"Kapsam poliçede yazanla belirlenir; tahminle “evet” ya da “hayır” demek konuğu yanıltır. Poliçeyi okuyup emin olamayınca yetkiliye sormak hem konuğa yardımcı olur hem sorumluluğu doğru yere taşır."},{"id":"os-4-s47","tur":"senaryo","durum":"Saat 14.10, otelin ön büro masasında stajyersin. Bir acentenin gönderdiği konuk voucherını uzatıyor: iki kişilik deniz manzaralı oda yazıyor, ama sistemde aynı isme standart oda kaydı var. Konuk yorgun ve sabırsız.","soru":"Ne yaparsın?","secenekler":["Sistemde standart oda göründüğü için konuğa o odayı verir, voucherın hatalı olduğunu söylerim.","Farkı amirime bildirir, acenteyle teyit edilirken konuğa durumu nazikçe anlatırım.","Amirime sormadan voucherdaki oda tipini kendim tahsis eder, sistem kaydını değiştiririm.","Konuğa farkı acenteyle kendisinin çözmesi gerektiğini söyleyip lobide beklemesini rica ederim."],"dogru":1,"aciklama":"Voucher ile otel kaydı çelişiyorsa doğrusu acente ve amirle teyit etmektir; kayıt kendi başına değiştirilmez. Konuğu suçlamak ya da bekletmek de sorun çözmez, durumu nazikçe anlatmak gerekir."},{"id":"os-4-s48","tur":"coktan-secmeli","soru":"Acente, çalıştıracağı rehberin yakasındaki kokartı kontrol ediyor. Rehbere çalışma yetkisini gösteren bu kokartı hangi kurum verir?","secenekler":["Kültür ve Turizm Bakanlığı","Seyahat Acentaları Birliği (TÜRSAB)","Turist Rehberleri Birliği (TUREB)","Ulaştırma ve Altyapı Bakanlığı"],"dogru":0,"aciklama":"Profesyonel turist rehberinin yetkisini gösteren kokartı Bakanlık verir. Rehber odası ve TUREB mesleği temsil eder ama kokartı vermez."},{"id":"os-4-s49","tur":"coktan-secmeli","soru":"Konuk, vize dosyasını ve biyometrik verisini VFS Global’de teslim ediyor. Bu tür kuruluşların vize sürecindeki görevi nedir?","secenekler":["Başvuruyu inceleyip vize kararını kendisi verir","Pasaport defterini basıp başvuru sahibine teslim eder","Seyahat sağlık sigortası poliçesini düzenleyip satar","Konsolosluk adına evrakı ve biyometrik veriyi toplar"],"dogru":3,"aciklama":"VFS Global, iDATA ve BLS gibi kuruluşlar yalnızca başvuruyu alan aracı kurumdur; vize kararını konsolosluk verir. Pasaport nüfus müdürlüğünde çıkarılır."},{"id":"os-4-s50","tur":"coktan-secmeli","soru":"Vize sorumlusu, Schengen başvurusunda konuğun mali durumunu göstermek için bir belge istiyor. Ders kitabına göre bu belge hangisidir?","secenekler":["Barkodlu tam vukuatlı nüfus kayıt örneği","Biyometrik fotoğraf ve imzalı başvuru formu","Son 3 aya ait imzalı, kaşeli banka dökümü","Uçak bileti ile otel rezervasyon belgeleri"],"dogru":2,"aciklama":"Mali durum, imzalı ve kaşeli banka hesap dökümüyle gösterilir. Nüfus kayıt örneği aile bilgisini, rezervasyonlar ise seyahat planını gösterir; mali durumu kanıtlamaz."},{"id":"os-4-s51","tur":"coktan-secmeli","soru":"Salı sabahı bir acente görevlisi, cuma günü yola çıkacak grup için otelden odaları, otobüs firmasından da koltukları istenen tarihte ayırtıyor. Bu görevli hangi bölümde çalışır?","secenekler":["Rezervasyon bölümü","Operasyon departmanı","Satış ve pazarlama bölümü","Muhasebe bölümü"],"dogru":0,"aciklama":"Turda kullanılacak oda ve araç yerlerini istenen tarih ve özellikte ayırtmak rezervasyon bölümünün işidir. Operasyon ise satılmış turun hizmetlerini sahada yürütür."},{"id":"os-4-s52","tur":"coktan-secmeli","soru":"Beş kişilik bir acentede aynı görevli sabah bir müşteriye Kapadokya turunu satıyor, öğleden sonra da aynı turun transferini ayarlıyor. Bu çalışma düzeni neyi gösterir?","secenekler":["Acentenin büyük ölçekli olduğunu ve satışla operasyonun ayrı departmanlarda yürüdüğünü","Acentenin küçük ölçekli olduğunu ve görevlilerin birkaç işi birlikte yürüttüğünü","Görevlinin iş tanımını aşarak başka bir bölümün yetkisine girdiğini","Acentenin transfer işini toptancı bir acenteye devretmiş olduğunu"],"dogru":1,"aciklama":"Küçük ölçekli acentede bölümler yoktur; az sayıda görevli satış ve transfer gibi birkaç işi birlikte yürütür. Büyük acentede ise bu işler ayrı departmanlara dağılır."},{"id":"os-4-s53","tur":"coktan-secmeli","soru":"Tur dönüşünden bir hafta sonra büyük bir acentede bir departman katılımcılara anket gönderiyor, şikâyetleri not ediyor ve tercihlerini kayda geçiriyor. Bu departman hangisidir?","secenekler":["İnsan kaynakları departmanı","Ürün planlama ve satın alma departmanı","Müşteri ilişkileri (CRM) departmanı","Satış ve pazarlama bölümü"],"dogru":2,"aciklama":"Satıştan önce ve sonra iletişimi yürütüp tercihleri ve geri bildirimleri kaydeden departman müşteri ilişkileri (CRM) departmanıdır. Satış ve pazarlamanın asıl işi ise ürünü tanıtıp satmaktır."},{"id":"os-4-s54","tur":"coktan-secmeli","soru":"Satış görevlisi bir gruba vejetaryen menü sözü veriyor. Grubun yemekte sorun yaşamaması için en doğru adım hangisidir?","secenekler":["Tur günü grubun durumu rehbere kendisinin anlatmasını beklemek","Sözü yalnız satış dosyasına not edip tur gününe kadar saklamak","Restoranın vejetaryen menüyü kendiliğinden hazırlayacağını varsaymak","Bilgiyi aynı gün operasyona yazıp restorana bildirilmesini sağlamak"],"dogru":3,"aciklama":"Bölümler arası iş birliğinde bilgi zamanında paylaşılır: satış sözü operasyona yazar, operasyon da restorana bildirir. Bilgi yalnız dosyada kalırsa verilen söz tutulamaz."},{"id":"os-4-s55","tur":"coktan-secmeli","soru":"Bir firma, İzmir’de iki günlük bir konferans düzenlemek istiyor; salonun, konaklamanın ve transferlerin tek programda planlanmasını bekliyor. Bu iş acentede hangi görevliye verilir?","secenekler":["MICE sorumlusu","Otel rehberi","Vize sorumlusu","Enformasyon memuru"],"dogru":0,"aciklama":"Toplantı, teşvik gezisi, konferans ve sergi gibi iş amaçlı etkinliklerin organizasyonunu MICE sorumlusu yürütür. Enformasyon memurunun işi ise seyahat, vize ve gidilecek yer hakkında bilgi vermektir."},{"id":"os-4-s56","tur":"coktan-secmeli","soru":"Sabah 10.00, tatil bölgesinde yeni varan konukların karşılandığı tesis girişi: acentenin bir görevlisi bilgilendirme toplantısı yapıyor, dönüş transfer saatlerini anlatıyor ve konaklama boyunca sorunları tesisle birlikte çözüyor. Bu görevli kimdir?","secenekler":["Transfer elemanı","Otel rehberi","Rezervasyon sorumlusu","Profesyonel turist rehberi"],"dogru":1,"aciklama":"Acentenin konuklarını otelde karşılayan, sorularını yanıtlayan ve sorunlarını otelle birlikte çözen görevli otel rehberidir. Transfer elemanı ise konukları havalimanı, otel ve gezi noktaları arasında taşırken onlara eşlik eder."},{"id":"os-4-s57","tur":"coktan-secmeli","soru":"Bir acentede yeni bir tur için yürütülen işlerin doğru sırası hangisidir?","secenekler":["Satış ve rezervasyon → Planlama → Tedarik ve sözleşme → Saha operasyonu → Değerlendirme","Planlama → Satış ve rezervasyon → Saha operasyonu → Tedarik ve sözleşme → Değerlendirme","Planlama → Tedarik ve sözleşme → Satış ve rezervasyon → Saha operasyonu → Değerlendirme","Tedarik ve sözleşme → Planlama → Saha operasyonu → Satış ve rezervasyon → Değerlendirme"],"dogru":2,"aciklama":"Operasyonel süreç planlamayla başlar; hizmetler sağlanıp sözleşmeye bağlanır, ürün satılır, tur sahada yapılır ve en sonda değerlendirilir. Satış, hizmetler sözleşmeye bağlandıktan sonra başlar."},{"id":"os-4-s58","tur":"coktan-secmeli","soru":"Satış görevlisi sözleşmeyi imzalatmadan önce müşteriye “Bu tarihten sonra vazgeçerseniz ödediğiniz tutardan kesinti yapılır.” diyerek ilgili maddeyi gösteriyor. Görevlinin gösterdiği madde hangi başlığa girer?","secenekler":["Opsiyon süresi","Konfirmasyon","Sigorta teminatı","İptal koşulları"],"dogru":3,"aciklama":"Rezervasyonun hangi tarihe kadar ücretsiz iptal edilebileceğini ve sonrasında ne kadar kesinti yapılacağını iptal koşulları belirler. Opsiyon ise kesinleşmemiş rezervasyonda ödeme için tanınan son tarihtir."},{"id":"os-4-s59","tur":"coktan-secmeli","soru":"İstanbul’dan Sidney’e uçacak bir müşteri, yolculuğunu Singapur’da bölüp iki uçuş arasında şehirde bir gece geçirmek istiyor. Bu ara durağa ne denir?","secenekler":["Stopover","Charter","Transfer","Go-show"],"dogru":0,"aciklama":"Uzun yolculuklarda varış noktasına ulaşmadan önce aktarma noktasında verilen ara durak stopoverdır. Transfer ise yolcunun havalimanı, otel ve gezi noktaları arasında araçla taşınmasıdır."},{"id":"os-4-s60","tur":"coktan-secmeli","soru":"Otel bir odayı acenteye, acentenin kazancı eklenmemiş bir fiyatla veriyor; acente bunun üzerine kendi payını ekleyip müşteriye satacağı fiyatı belirliyor. Otelin acenteye verdiği fiyata ne denir?","secenekler":["Komisyon tutarı","Net fiyat","Son dakika fiyatı","Satış fiyatı"],"dogru":1,"aciklama":"Tedarikçinin acenteye verdiği, acentenin kazancı eklenmemiş fiyat net fiyattır. Komisyonda ise tedarikçi, satış bedelinin önceden anlaşılan bir bölümünü acenteye bırakır."},{"id":"os-4-s61","tur":"coktan-secmeli","soru":"Bir turizm bölgesindeki oteller, sezon öncesinde farklı şehirlerdeki acente çalışanlarını bölgeye davet edip tesislerini tanıtıyor. Bu geziye ne denir?","secenekler":["Teşvik gezisi (incentive)","Paket tur","Fam trip","Charter"],"dogru":2,"aciklama":"Bir bölgeyi ve oradaki tesisleri acente çalışanlarına tanıtmak için düzenlenen gezi fam triptir. Teşvik gezisi ise şirketlerin çalışanlarını ya da bayilerini ödüllendirmek için düzenlettiği gezidir."},{"id":"os-4-s62","tur":"coktan-secmeli","soru":"Bir Ege turunda tur operatörü ile bu turu vitrinine koyan seyahat acentesinin rolleri için hangisi doğrudur?","secenekler":["Acente turu oluşturup fiyatını belirler, operatör yalnız satar.","İkisi de aynı turu ayrı ayrı oluşturur ve kendi adına satar.","Operatör turu satar, acente otellerle oda sözleşmesi yapar.","Operatör turu oluşturur, acente bu ürünü müşteriye ulaştırır."],"dogru":3,"aciklama":"Tur operatörü paket turu oluşturan üretici, seyahat acentesi ise bu hazır ürünü müşteriye ulaştıran satış noktasıdır; acente bunun karşılığında anlaşılan komisyonu alır."},{"id":"os-4-s63","tur":"coktan-secmeli","soru":"Belgesi olmayan bir kişi sosyal medyada çok ucuza tur satıyor; sigorta yaptırmıyor, kurallara uymuyor ve dürüst çalışan acentelerin müşterilerini elinden alıyor. Bu durum hangi kavramla açıklanır?","secenekler":["Haksız rekabet","Son dakika satışı","Mesafeli sözleşme","Overbooking"],"dogru":0,"aciklama":"Dürüstlük kurallarına aykırı yollarla rakiplerinin önüne geçmeye çalışmak haksız rekabettir. Son dakika satışı ise dolmayan yerlerin hizmet tarihine az kala indirimle satılmasıdır."},{"id":"os-4-s64","tur":"coktan-secmeli","soru":"Bir acente, ilçede düzenlenen kiraz festivaline özel bir tur hazırlıyor. Otobüslerin park yerini ve festival programını hangi tarafla birlikte planlar?","secenekler":["Türkiye Seyahat Acentaları Birliği (TÜRSAB)","Yerel yönetim (belediye)","Uluslararası Hava Taşımacılığı Birliği (IATA)","Türkiye Otelciler Birliği (TÜROB)"],"dogru":1,"aciklama":"Bölgesel tanıtım, çevre düzeni ve yerel etkinlik izinlerinde acentenin iş birliği yaptığı taraf belediye ve valilik gibi yerel yönetimlerdir. TÜRSAB ise acentelik mesleğinin temsilcisidir."},{"id":"os-4-s65","tur":"coktan-secmeli","soru":"Yurt dışına çıkacak bir iş insanının yanındaki nakit para belirlenen sınırı aşıyor. Havalimanında ne yapması gerekir?","secenekler":["Parayı bavuluna koyup kimseye bildirmeden geçmesi","Vize başvuru merkezinde nakdi kayda geçirtmesi","Döviz beyan formunu doldurup gümrük görevlisine vermesi","Konsolosluktan nakit taşıma izni alıp pasaportuna işletmesi"],"dogru":2,"aciklama":"Sınırı aşan döviz ve nakit para, döviz beyan formuyla gümrüğe bildirilir. Vize başvuru merkezi ve konsolosluk ise vize başvurularıyla ilgilenir."},{"id":"os-4-s66","tur":"coktan-secmeli","soru":"Bir anne, lise öğrencisi kızının ailesi olmadan bir yurt dışı geziye katılacağını acenteye bildiriyor. Acente görevlisi anneye hangi belgeyi önceden hazırlamasını söyler?","secenekler":["Tam vukuatlı nüfus kayıt örneği","Hizmet damgalı pasaport talep formu","Döviz beyan formu","Seyahat izin belgesi"],"dogru":3,"aciklama":"Reşit olmayan yolcuya yasal temsilcisinin yazılı izin verdiğini seyahat izin belgesi gösterir; gidilecek ülke ve hava yolu bunu isteyebilir. Nüfus kayıt örneği yalnız aile bilgilerini gösterir, izin yerine geçmez."},{"id":"os-4-s67","tur":"coktan-secmeli","soru":"Çalıştığı bakanlık tarafından yurt dışındaki uluslararası bir toplantıda ülkesini temsil etmek üzere gönderilen bir kamu çalışanı hangi vizeye başvurur?","secenekler":["Resmî görev vizesi","Çalışma vizesi","Turistik (gezi) vizesi","Transit vize"],"dogru":0,"aciklama":"Devletin verdiği bir görevle yurt dışına gidecek kişilere resmî görev vizesi verilir. Çalışma vizesi ise yurt dışında bir işte çalışmak üzere gidecek kişiler içindir."},{"id":"os-4-s68","tur":"coktan-secmeli","soru":"Müşteri gece 23.00’te evinden, acentenin internet sitesi üzerinden bir hizmet satın alıyor ve onayını ekrandaki kutuyu işaretleyerek veriyor. Bu satış hangi kavramla adlandırılır?","secenekler":["Tedarik sözleşmesi","Mesafeli sözleşme","Kontenjan anlaşması","Sigorta poliçesi"],"dogru":1,"aciklama":"Satıcı ile tüketicinin yüz yüze gelmeden internet ya da telefon gibi araçlarla kurduğu sözleşme mesafeli sözleşmedir. Tedarik sözleşmesi ise acente ile otel gibi hizmet veren işletmeler arasında yapılır."},{"id":"os-4-s69","tur":"dogru-yanlis","soru":"Bir acente yasal açıdan A grubu, fonksiyonel açıdan karşılayıcı, yapısal açıdan perakendeci olabilir; çünkü bu sınıflandırmalar farklı ölçütlere dayanır.","secenekler":["Doğru","Yanlış"],"dogru":0,"aciklama":"Acenteler yasal, fonksiyonel ve yapısal olmak üzere üç ayrı ölçüte göre sınıflandırılır. Bu yüzden aynı acente her ölçütte ayrı bir gruba girebilir."},{"id":"os-4-s70","tur":"dogru-yanlis","soru":"Kontenjan (allotment), otelin belirli bir dönem için satışı geçici olarak durdurup bunu acentelere bildirmesidir.","secenekler":["Doğru","Yanlış"],"dogru":1,"aciklama":"Kontenjan, otelin ya da hava yolunun belirli bir dönem için bir acenteye belirli sayıda oda veya koltuk ayırmasıdır. Satışın geçici olarak durdurulup acentelere bildirilmesi stop-sale olarak adlandırılır."},{"id":"os-4-s71","tur":"dogru-yanlis","soru":"Bir şirketin, yılın en başarılı bayilerini ödül olarak üç günlük bir geziye göndermesi teşvik gezisine (incentive) örnektir.","secenekler":["Doğru","Yanlış"],"dogru":0,"aciklama":"Teşvik gezisi, şirketlerin çalışanlarını ya da bayilerini ödüllendirmek ve daha verimli çalışmaya özendirmek için düzenlettiği gezidir."},{"id":"os-4-s72","tur":"dogru-yanlis","soru":"Pasaport çıkarılırken ödenen harç ile defter bedeli, aynı ödemenin iki farklı adıdır.","secenekler":["Doğru","Yanlış"],"dogru":1,"aciklama":"Harç devlete ödenir, defter bedeli ise pasaport defterinin kendi ücretidir; ikisi ayrı ödemelerdir. Bu yüzden harç ödemeyen bir üniversite öğrencisi de defter bedelini yatırır."},{"id":"os-4-s73","tur":"dogru-yanlis","soru":"Vize dosyasına konan tam vukuatlı nüfus kayıt örneği, e-Devlet’ten barkodlu olarak alınabilir.","secenekler":["Doğru","Yanlış"],"dogru":0,"aciklama":"Tam vukuatlı nüfus kayıt örneği kişinin aile bilgilerini ve evlilik, doğum gibi olayları gösterir; e-Devlet’ten barkodlu olarak alınabilir."},{"id":"os-4-s74","tur":"dogru-yanlis","soru":"Seyahat Acentaları Yönetmeliği, 1618 sayılı Kanun’un yerine çıkarılmış ve onu yürürlükten kaldırmış bir düzenlemedir.","secenekler":["Doğru","Yanlış"],"dogru":1,"aciklama":"Yönetmelik kanunu kaldırmaz; 1618 sayılı Kanun’un nasıl uygulanacağını ayrıntılı olarak gösterir. Örneğin kanun acentenin işletme belgesi alacağını söyler, belgenin nasıl alınacağı yönetmelikte yazar."}],"siralamalar":[{"id":"os-4-r01","konu":"4.2","baslik":"Bir turun doğuşundan değerlendirmesine","yonerge":"Seyahat acentesinde bir turun operasyonel sürecindeki beş aşamayı doğru sıraya koy.","adimlar":["Turun nereye, ne zaman ve kimler için yapılacağını araştır; turu tasarla.","Tasarlanan tur için gereken hizmetleri (konaklama, ulaşım vb.) tedarik et ve sözleşmeyi hazırla.","Turu pazarla, konuklara sat ve rezervasyon işlemlerini yap.","Turu gerçekleştir; konukları karşıla ve saha operasyonlarını yürüt.","Turdan sonra hizmeti değerlendir; konukların görüşlerini incele."],"aciklama":"Kitaptaki beş operasyon aşaması bu sırayla ilerler: önce tur planlanır, sonra hizmetler tedarik edilip sözleşme yapılır, ardından satış ve rezervasyon gelir, tur sahada uygulanır ve en son değerlendirilir."}],"acikSorular":[{"id":"os-4-y01","konu":"4.3","soru":"Yeni mezun bir arkadaşınız kendi seyahat acentesini açmak ve paket tur satmak istiyor. Acentenin işe başlayabilmesi için gereken iki şartı ve paket tur satacaksa yaptırması gereken zorunlu sigortayı yazınız; bu düzenlemelerin konuğu nasıl koruduğunu açıklayınız.","olcut":[{"metin":"İşletme belgesinin Kültür ve Turizm Bakanlığından alınması gerektiğini belirtir.","puan":25},{"metin":"TÜRSAB’a üye olmanın zorunlu olduğunu belirtir.","puan":25},{"metin":"Paket tur satan acentenin zorunlu paket tur sigortası yaptırması gerektiğini belirtir.","puan":20},{"metin":"Bu düzenlemelerin konuğu nasıl koruduğunu nedenleriyle açıklar.","puan":30}],"ornek":"Acente önce Kültür ve Turizm Bakanlığından işletme belgesini almalıdır; belgeyi TÜRSAB değil, Bakanlık verir. Ardından TÜRSAB’a üye olması zorunludur. Paket tur satacaksa ayrıca zorunlu paket tur sigortasını da yaptırmalıdır. Belge ve üyelik acentenin kayıtlı ve denetlenen bir işletme olduğunu gösterir, konuk şikâyetini iletebileceği bir muhatap bulur. Paket tur sigortası da hizmet eksik verilirse ya da hiç verilmezse konuğun zararını güvence altına alır.","ipucu":"Belgeyi kimin verdiğini, birliğin görevini ve sigortanın hangi riske karşı olduğunu ayrı ayrı düşünün."},{"id":"os-4-y02","konu":"4.2.2","soru":"Bir acente görevlisi, yaz tatili için otelde yer ayırtmak isteyen bir konukla görüşüyor. Konuk ödemeyi birkaç gün sonra yapacağını söylüyor ve yerin o zamana kadar tutulmasını istiyor. Opsiyon ve konfirmasyon kavramlarının ne anlama geldiğini yazınız; görevlinin yazılı onay gelmeden konuğa “yeriniz hazır” dememesi gerektiğini nedeniyle açıklayınız.","olcut":[{"metin":"Opsiyonu, ödeme için tanınan son tarih ya da süre olarak tanımlar.","puan":20},{"metin":"Opsiyon süresi içinde ödeme yapılmazsa yerin başkasına satılabileceğini belirtir.","puan":20},{"metin":"Konfirmasyonu, rezervasyonun hizmeti verecek işletme tarafından yazılı olarak onaylanması diye tanımlar.","puan":20},{"metin":"Yazılı onay gelmeden konuğa söz verilmemesinin nedenini (onaysız rezervasyonun kesin olmadığını) açıklar.","puan":40}],"ornek":"Opsiyon, kesinleşmemiş bir rezervasyonda ödeme yapılması için tanınan son tarih ya da süredir. Konuk bu süre içinde ödeme yapmazsa yer başkasına satılabilir. Konfirmasyon ise rezervasyonun, hizmeti verecek otel tarafından yazılı olarak onaylanmasıdır. Onayı gelmemiş rezervasyon yapılmamış sayılır; görevli “yeriniz hazır” derse ve otel yeri vermezse konuk mağdur olur, acente de güvenini kaybeder. Bu yüzden önce konfirme alınmalı, sonra konuğa kesin bilgi verilmelidir.","ipucu":"Yerin kimin elinde olduğunu düşünün: acentenin mi, hizmeti verecek işletmenin mi?"}]},{"ders":"otelcilik-seyahat","sinif":9,"unite":5,"baslik":"Konuk İlişkileri","onay":true,"kazanimlar":["Konuk tiplerinin özelliklerini açıklar; farklı konuk tiplerine uygun olarak doğru iletişim kurar; konuk memnuniyetinin nasıl sağlanması gerektiğini açıklar; konuğun sorunlarına çözüm bulur.","Olağan dışı durumları sıralar; olağan dışı durumlarda uygun çözüm yollarını uygular; olağan dışı durumlarda örnek senaryolarla konuğa yardımcı olur; müdahale edilmesi mümkün olmayan durumlarda örnek senaryolarla konuğa yardımcı olur."],"soz":"Konuk sorunu değil, çözümü hatırlar; kriz anında da sakin kalan profesyoneli unutmaz.","dersler":[{"baslik":"Müşteri mi, Konuk mu?","ilk":"os-5-001"},{"baslik":"Neden Geldiğini Bil","ilk":"os-5-005"},{"baslik":"Aynı Hizmet Herkese Uymaz","ilk":"os-5-010"},{"baslik":"Yardım Etmeden Önce Sor","ilk":"os-5-014"},{"baslik":"Büyükler ve Küçükler","ilk":"os-5-020"},{"baslik":"VIP Kim, CIP Kim?","ilk":"os-5-022"},{"baslik":"İstemeden Önce Sunmak","ilk":"os-5-026"},{"baslik":"Butler’ın Not Defteri","ilk":"os-5-029"},{"baslik":"Parmakla Okuyan, Işıkla Uyanan Konuk","ilk":"os-5-185"},{"baslik":"Titiz Konuk, Öfkeli Konuk","ilk":"os-5-032"},{"baslik":"Susan Konuk, Konuşan Konuk","ilk":"os-5-036"},{"baslik":"Karar Veremeyen, Fikrinden Dönmeyen","ilk":"os-5-040"},{"baslik":"Memnuniyet Neyle Ölçülür?","ilk":"os-5-045"},{"baslik":"Binanın Veremediği Üç Şey","ilk":"os-5-049"},{"baslik":"İlk Otuz Saniye","ilk":"os-5-053"},{"baslik":"Şikâyet Bir Hediyedir","ilk":"os-5-057"},{"baslik":"LEARN: Beş Harf, Beş Adım","ilk":"os-5-060"},{"baslik":"Beş Kez “Neden?”","ilk":"os-5-066"},{"baslik":"Hayal Kırıklığı Nereden Doğar?","ilk":"os-5-070"},{"baslik":"Az Söz Ver, Fazlasını Yap","ilk":"os-5-074"},{"baslik":"Özürden Fazlası: Telafi","ilk":"os-5-077"},{"baslik":"Sorun Seni Aşarsa","ilk":"os-5-083"},{"baslik":"Otelde Her Şey Yolunda Gitmezse?","ilk":"os-5-100"},{"baslik":"Kapıyı Kim, Ne Zaman Açtı?","ilk":"os-5-103"},{"baslik":"Alarm Çalınca Sistem Ne Yapar?","ilk":"os-5-107"},{"baslik":"Kapının Arkasındaki Kroki","ilk":"os-5-111"},{"baslik":"Pasaport Numarası da Emanettir","ilk":"os-5-114"},{"baslik":"Dört Adımda Kriz","ilk":"os-5-117"},{"baslik":"Lobide Biri Düştü!","ilk":"os-5-123"},{"baslik":"Kazadan Sonra: Zincirin Halkaları","ilk":"os-5-128"},{"baslik":"112’yi Ne Zaman Ararsın?","ilk":"os-5-131"},{"baslik":"Kayıp mı, Çalıntı mı?","ilk":"os-5-137"},{"baslik":"Bornoz, Şezlong, Kırık Televizyon","ilk":"os-5-143"},{"baslik":"Sahipsiz Çanta, Ciddi Telefon","ilk":"os-5-146"},{"baslik":"R.A.C.E.: Dört Harf, Dört Adım","ilk":"os-5-152"},{"baslik":"Duman Varken Asansör Olmaz","ilk":"os-5-158"},{"baslik":"Panik Bulaşır, Sakinlik de","ilk":"os-5-163"},{"baslik":"Elimizde Olmayan Sebepler","ilk":"os-5-165"},{"baslik":"Otel Tek Başına Değil","ilk":"os-5-171"},{"baslik":"Kriz Anında Konuğa Beş Adım","ilk":"os-5-174"}],"kavramlar":[{"id":"os-5-001","konu":"5.1","terim":"Konuk ilişkileri yönetimi","ingilizce":"Guest relations management","tanim":"Konuğun kapıdan girdiği andan ayrıldığı ana kadar yaşadığı bütün deneyimin profesyonelce yönetilmesidir.","ornek":"Saat 14.00, lobi: konuk ilişkileri görevlisi yeni gelen aileyi karşılar, odalarına kadar eşlik eder ve akşam “Her şey yolunda mı efendim?” diye arar.","sektor":"Yalnız bir bölümün değil, konuğa dokunan herkesin işidir. Oda, yemek ve havuz her otelde bulunur; konuğu geri getiren şey kendisiyle nasıl ilgilenildiğidir.","iliskili":["os-5-002","os-5-003","os-5-045"],"kontrol":null},{"id":"os-5-002","konu":"5.1","terim":"Misafirperverlik","ingilizce":"Hospitality","tanim":"Gelen kişiyi içtenlikle karşılama, rahat etmesi için elinden geleni yapma ve ona değer verdiğini hissettirme anlayışıdır.","ornek":"Gece 23.30, Kapadokya’da küçük bir otel: geç gelen konuğa mutfak kapalı olduğu hâlde bir tabak sıcak çorba ve ekmek hazırlanır.","sektor":"Konuk ilişkilerinin kökü kültürümüzdeki konukseverliktir; otelcilik bunu mesleğe dönüştürür. Sektörün İngilizce adı da buradan gelir: hospitality industry.","iliskili":["os-5-001","os-5-053"],"kontrol":null,"gorsel":"sektor-turk-kahvesi"},{"id":"os-5-003","konu":"5.1","terim":"Konuk tipi","ingilizce":"Guest type","tanim":"Benzer ihtiyaç, beklenti ya da davranış gösteren konukların oluşturduğu gruplardan her biridir.","ornek":"Sabah 08.00, ön büro toplantısı: şef “Bugün bir kongre grubu, iki balayı çifti ve çocuklu altı aile geliyor” der; herkes hazırlığını buna göre yapar.","sektor":"Konuklar üç açıdan gruplanır: seyahat amacı, özel ilgi gerektiren durum, karakter ve davranış biçimi. Amaç konuğu etiketlemek değil, ona doğru yaklaşmaktır: nezaket herkese aynıdır, değişen yalnız üsluptur.","iliskili":["os-5-005","os-5-014","os-5-032"],"kontrol":null},{"id":"os-5-004","konu":"5.1","terim":"Konuk beklentisi","ingilizce":"Guest expectation","tanim":"Konuğun tesise gelmeden önce zihninde kurduğu ve karşılanmasını umduğu hizmet düzeyidir.","ornek":"İnternette deniz manzaralı oda fotoğrafını görüp rezervasyon yapan konuk, perdeyi açtığında denizi görmeyi bekler.","sektor":"Beklenti fotoğraflardan, yorumlardan, ödenen ücretten ve önceki deneyimlerden oluşur. Personel beklentiyi ne kadar iyi tahmin ederse hizmeti o kadar isabetli sunar; memnuniyet de bu beklentiyle ölçülür.","iliskili":["os-5-045","os-5-071","os-5-074"],"kontrol":null},{"id":"os-5-183","konu":"5.1","terim":"Müşteri","ingilizce":"Customer","tanim":"Bir işletmeden ücret karşılığı mal ya da hizmet satın alan kişidir.","ornek":"Cumartesi 11.00, bir seyahat acentesinde: Kapadokya turu için ödeme yapan Ayşe Hanım acente için müşteridir; turun otelinde odasına yerleştiğinde aynı kişi otel için konuktur.","sektor":"Ders dilinde otelde “konuk”, acentede “müşteri” denir. Konuk sözü satın alma ilişkisinin yanında ağırlanmayı da anlatır; misafirperverlik anlayışı bu yüzden konuk sözünü öne çıkarır.","iliskili":["os-5-001","os-5-002"],"kontrol":null,"cizim":"zil-hizmet"},{"id":"os-5-005","konu":"5.1.1","terim":"Seyahat amacı","ingilizce":"Purpose of travel","tanim":"Konuğu yola çıkaran iş, tatil, sağlık, kültür ya da inanç gibi temel nedendir.","ornek":"Aynı otelde aynı gece: 204’teki konuk sabah toplantısına hazırlanıyor, 310’daki aile ertesi günkü tekne turunu planlıyor.","sektor":"Konuğun tesise adım attığı andaki bütün beklentilerini seyahat amacı biçimlendirir. Neden geldiğini bilen personel hizmeti kişiye göre ayarlayabilir.","iliskili":["os-5-006","os-5-007","os-5-011"],"kontrol":null},{"id":"os-5-006","konu":"5.1.1","terim":"İş amaçlı konuk","ingilizce":"Business traveller","tanim":"Toplantı, görüşme ya da görev için seyahat eden; hız, kesintisiz internet, sessiz çalışma ortamı ve kolay ulaşım bekleyen konuktur.","ornek":"Saat 07.15, İstanbul’da bir şehir oteli: konuk telefonda konuşarak bankoya gelir; görevli faturasını önceden hazırlamıştır, çıkış işlemi bir iki dakikada biter.","sektor":"Bu konuk için en değerli şey zamandır. Giriş ve çıkış işlemleri hızlı yapılır, ciddi ve profesyonel bir hitap kullanılır, sorun çıktığında uzun açıklama değil çözüm sunulur.","iliskili":["os-5-005","os-5-011","os-5-051"],"kontrol":null,"gorsel":"h5a-is-seyahati-cantasi"},{"id":"os-5-007","konu":"5.1.1","terim":"Tatil amaçlı konuk","ingilizce":"Leisure traveller","tanim":"Dinlenmek ve eğlenmek için seyahat eden; konfor, eğlence, çocuk etkinlikleri ve yerel lezzetler bekleyen konuktur.","ornek":"Saat 10.30, Antalya’da bir tatil köyü: resepsiyon görevlisi yeni gelen aileye gülümseyerek çocuk kulübünün saatlerini ve akşamki gösteriyi anlatır.","sektor":"Tatilcinin acelesi yoktur; sohbet ve ilgi ona hızdan daha kıymetli gelebilir. Güler yüzlü ve enerjik bir iletişim, etkinlik önerileri, sabırlı ve yardımsever bir tutum beklenir.","iliskili":["os-5-005","os-5-011","os-5-021"],"kontrol":null,"gorsel":"t13e-hasir-semsiye-sezlong"},{"id":"os-5-008","konu":"5.1.1","terim":"Sağlık / termal amaçlı konuk","ingilizce":"Health and thermal guest","tanim":"Tedavi olmak, iyileşmek ya da sağlığını korumak için seyahat eden; hijyen, diyete uygun yemek, sakinlik ve uzman personel desteği bekleyen konuktur.","ornek":"Akşam 19.00, Afyonkarahisar’da bir termal otel: garson, konuğun diyet listesindeki tuzsuz menüyü mutfağa kendi eliyle iletir ve tabağı servisten önce kontrol eder.","sektor":"Hassas ve saygılı bir yaklaşım, diyet takibinde titizlik ve yüksek empati gerekir. Personel teşhis koymaz, tedavi önermez; konuğun sağlığıyla ilgili bilgiyi de kimseyle paylaşmaz.","iliskili":["os-5-005","os-5-027","os-5-050"],"kontrol":null,"gorsel":"h5a-termal-spa"},{"id":"os-5-009","konu":"5.1.1","terim":"Kültür / inanç amaçlı konuk","ingilizce":"Cultural and faith traveller","tanim":"Tarihî, kültürel ya da dinî yerleri görmek için seyahat eden; bu mekânlara yakınlık, rehberlik hizmeti ve değerlerine saygı bekleyen konuktur.","ornek":"Sabah 09.00, Konya’da bir otel: resepsiyon görevlisi Mevlana Müzesi’ne gidecek gruba yürüme yolunu haritada gösterir ve müzenin ziyaret saatlerini söyler.","sektor":"Personelden yerel kültür bilgisi ve konuğun hassasiyetlerine uygun davranış beklenir. Çevresindeki müzeyi, camiyi, ören yerini tanımayan personel bu konuğa yardımcı olamaz.","iliskili":["os-5-005","os-5-010"],"kontrol":null,"gorsel":"cami"},{"id":"os-5-010","konu":"5.1.1","terim":"Kültürel değerlere saygı","ingilizce":"Cultural sensitivity","tanim":"Konuğun inancından, dilinden ve alışkanlıklarından doğan farklı isteklerini yargılamadan, özenle karşılama tutumudur.","ornek":"Saat 20.00, restoran: konuk inancı gereği bazı yiyecekleri yemediğini söyler; garson soru sormadan menüde ona uygun seçenekleri gösterir.","sektor":"Bir otelde aynı gün pek çok ülkeden ve inançtan konuk ağırlanır. “Şu ülkeden gelenler şöyledir” gibi kalıp yargılar hem yanlıştır hem konuğu kırar; her konuk tek tek tanınır, emin olunmayan şey nazikçe sorulur.","iliskili":["os-5-009","os-5-003"],"kontrol":null,"gorsel":"h5a-giris-ayakkabilik"},{"id":"os-5-011","konu":"5.1.1","terim":"İhtiyaç algısı","ingilizce":"Perceived need","tanim":"Konuğun o anda kendisi için en önemli gördüğü şeydir; konuk gruplarını birbirinden ayıran en büyük fark budur.","ornek":"Öğlen 12.00, resepsiyon: uçağına yetişecek konuk için değerli olan hızdır; güneşlenmekten dönen tatilci için ise iki dakikalık hoş bir sohbet.","sektor":"Aynı davranış bir konuğu memnun eder, diğerini bunaltır. İşi iyi yapan personel önce “Bu konuk şu anda neye ihtiyaç duyuyor?” diye düşünür, sonra davranır.","iliskili":["os-5-005","os-5-006","os-5-012"],"kontrol":null},{"id":"os-5-012","konu":"5.1.1","terim":"Kişiselleştirilmiş hizmet","ingilizce":"Personalised service","tanim":"Hizmetin herkese aynı kalıpla değil, o konuğun amacına, isteklerine ve alışkanlıklarına göre uyarlanarak sunulmasıdır.","ornek":"Saat 06.30, restoran: her sabah erken çıkan iş konuğunun çayı ve gazetesi, o gelmeden her zamanki masasına hazırlanmıştır.","sektor":"Konuğa “Beni tanıyorlar” dedirten şey budur. Adıyla hitap etmek kişiselleştirmenin en basit ve en etkili adımıdır; gerisi dikkat etmek ve not almaktır.","iliskili":["os-5-011","os-5-029","os-5-028"],"kontrol":null,"gorsel":"h5a-monogram-bez"},{"id":"os-5-013","konu":"5.1.1","terim":"Kongre ve etkinlik konuğu","ingilizce":"MICE guest","tanim":"Toplantı, kongre, fuar ya da spor karşılaşması gibi bir etkinliğe katılmak için gelen ve çoğunlukla grup hâlinde konaklayan konuktur.","ornek":"Saat 08.30, kongre oteli: iki yüz kişilik grup aynı anda kahvaltıdan çıkıp salona yürür; servis ekibi kahve molasının saatini programa göre önceden ayarlamıştır.","sektor":"MICE; toplantı, teşvik gezisi, kongre ve fuar sözcüklerinin İngilizce karşılıklarının baş harfleridir (meetings, incentives, conferences, exhibitions). Bu konuğun günü programa bağlıdır: servis bir kişi için değil, bütün grup için saatinde hazır olmalıdır.","iliskili":["os-5-006","os-5-005"],"kontrol":null,"kitapDisi":true,"gorsel":"t12o-dinleyici-koltuklar"},{"id":"os-5-187","konu":"5.1.1","terim":"Balayı çifti hizmeti","ingilizce":"Honeymoon service","tanim":"Balayına gelen çifte tematik oda süslemesi, meyve sepeti ve özel ikramlarla sunulan kişiselleştirilmiş hizmettir.","ornek":"Rezervasyon notunda balayı yazan çiftin odası çiçek ve kalp biçimli havlularla süslenir, akşam odalarına meyve sepeti ve bir tatlı gönderilir.","sektor":"Konuk odasına girdiğinde beklemediği bir sürprizle karşılaşırsa beklentisi aşılır. Tanıtımda önceden söylenmeyen ikram sürpriz olarak kalır. Kitabın ölçme bölümünde balayı çiftleri için tematik süsleme, meyve sepeti ve özel ikramlar doğru kişiselleştirilmiş hizmet olarak sayılır.","iliskili":["os-5-012","os-5-046","os-5-007"],"kontrol":null,"cizim":"zil-hizmet"},{"id":"os-5-014","konu":"5.1.2","terim":"Özel ilgi gerektiren konuk","ingilizce":"Special attention guest","tanim":"Standart hizmetin ötesinde kişisel hassasiyet, fiziksel destek ya da üst düzey özen bekleyen konuktur.","ornek":"Saat 09.00, bölümler arası toplantı: ön büro müdürü “Bugün tekerlekli sandalye kullanan bir konuğumuz ve bir VIP konuğumuz var” diyerek hazırlıkları tek tek sayar.","sektor":"Engelli konuklar, yaşlı konuklar, VIP / CIP konuklar ve çocuklu aileler bu grupta anılır. Bu konukları tanımak, personelin saygı, sabır ve anlayış gibi değerleri davranışa dökmesini sağlar.","iliskili":["os-5-015","os-5-020","os-5-022"],"kontrol":null,"cizim":"zil-hizmet"},{"id":"os-5-015","konu":"5.1.2","terim":"Engelli konuk","ingilizce":"Guest with disabilities","tanim":"Hareket, görme ya da işitme gibi bir alanda engeli bulunan ve tesisin hizmetlerine güvenle, başkasına bağımlı kalmadan ulaşmak isteyen konuktur.","ornek":"Saat 15.00, resepsiyon: görme engelli konuğa görevli önce kendini tanıtır, “Odanıza kadar eşlik etmemi ister misiniz?” diye sorar; konuk isteyince kolunu uzatır.","sektor":"Temel beklentiler erişilebilirlik, güvenlik ve bağımsız hareket edebilmektir. Amaç acımak değil, konuğun herkes gibi rahat bir konaklama yaşamasıdır. Konuşurken refakatçisine değil, konuğun kendisine hitap edilir.","iliskili":["os-5-016","os-5-017","os-5-018"],"kontrol":null},{"id":"os-5-016","konu":"5.1.2","terim":"Erişilebilirlik","ingilizce":"Accessibility","tanim":"Bir tesisin bütün alanlarına ve hizmetlerine, engelli ve yaşlı konuklar dâhil herkesin güvenle ve kolayca ulaşabilmesidir.","ornek":"Girişte rampası, katlar arasında asansörü ve restoranda tekerlekli sandalyenin geçebileceği genişlikte masa aralığı olan otelde konuk her yere kendisi gider.","sektor":"Personel tesisin rampa, asansör ve erişilebilir oda imkânlarını ezbere bilmelidir. “Bilmiyorum, bir sorayım” cevabı konuğa bu otelde kendisinin düşünülmediğini hissettirir.","iliskili":["os-5-015","os-5-019","os-5-017"],"kontrol":null,"gorsel":"t14c-rampa-tutamak"},{"id":"os-5-017","konu":"5.1.2","terim":"Bağımsız hareket edebilme","ingilizce":"Independent mobility","tanim":"Engelli konuğun tesis içinde başkasının yardımına mecbur kalmadan, kendi başına dolaşabilmesi ve işini görebilmesidir.","ornek":"Sabah 08.00, açık büfe: tekerlekli sandalye kullanan konuk tabağını kendisi doldurmak ister; garson yalnız yolu açar ve “Bir şeye ihtiyacınız olursa buradayım” der.","sektor":"Engelli konuğun en önemli beklentilerinden biridir. Her işini onun yerine yapmak iyilik gibi görünür, ama konuğa “Sen yapamazsın” demektir. Doğrusu imkânı sağlamak ve kararı konuğa bırakmaktır.","iliskili":["os-5-015","os-5-018"],"kontrol":null,"gorsel":"h5a-rampali-otobus"},{"id":"os-5-018","konu":"5.1.2","terim":"Yardım etmeden önce sorma","ingilizce":"Asking before helping","tanim":"Engelli ya da yaşlı bir konuğa dokunmadan, eşyasını ya da sandalyesini tutmadan önce yardım isteyip istemediğini sorma nezaketidir.","ornek":"Saat 11.00, otel girişi: bellboy tekerlekli sandalyeyi arkadan itmeye başlamaz; öne geçip “Size yardımcı olmamı ister misiniz efendim?” diye sorar.","sektor":"Tekerlekli sandalye, baston ya da rehber köpek konuğun kişisel alanının parçasıdır; izinsiz dokunulmaz. Sormadan yapılan yardım konuğu ürkütebilir, dengesini bozabilir; sorarak yapılan yardım ise saygıdır.","iliskili":["os-5-015","os-5-017","os-5-020"],"kontrol":null},{"id":"os-5-019","konu":"5.1.2","terim":"Erişilebilir oda","ingilizce":"Accessible room","tanim":"Engelli konukların rahat ve güvenli konaklayabilmesi için geniş geçişler, tutunma barları ve uygun banyo gibi düzenlemelerle hazırlanmış odadır.","ornek":"Rezervasyon görevlisi telefonda “Zemin katta, kapısı geniş ve banyosunda tutunma barı olan odamızı sizin için ayırıyorum efendim” der.","sektor":"Eski kaynaklarda “engelli odası” diye geçer; sektörde bugün “accessible room” denir. Kat görevlisi bu odada eşyaların yerini rastgele değiştirmez: konuk odayı ezberine göre kullanır.","iliskili":["os-5-016","os-5-015"],"kontrol":null,"gorsel":"t14zb-erisilebilir-banyo"},{"id":"os-5-020","konu":"5.1.2","terim":"Yaşlı konuk (üçüncü yaş)","ingilizce":"Senior guest","tanim":"İleri yaşta olan; güvenlik, sessizlik, sağlık desteği ve saygı bekleyen konuktur.","ornek":"Saat 16.00, resepsiyon: görevli yaşlı çifte asansöre yakın, sessiz bir oda verir; kahvaltı saatini yavaş ve net söyler, bir kâğıda da yazar.","sektor":"Yavaş ve net konuşmak, acil durum prosedürlerini iyi bilmek ve gerektiğinde fiziksel destek sunmaya hazır olmak gerekir. Yüksek sesle ya da çocukla konuşur gibi konuşmak saygısızlıktır; sabır ve “efendim” yeterlidir.","iliskili":["os-5-014","os-5-018","os-5-016"],"kontrol":null},{"id":"os-5-021","konu":"5.1.2","terim":"Çocuklu aile","ingilizce":"Family with children","tanim":"Çocuğuyla birlikte konaklayan; güvenlik, eğlence, beslenme kolaylığı ve pratik çözümler bekleyen konuk grubudur.","ornek":"Saat 13.00, giriş işlemi: görevli aileye çocuk havuzunun yerini, çocuk büfesinin saatini anlatır ve odaya bebek yatağı gönderilmesi için kat hizmetlerini arar.","sektor":"Çocuk dostu alanlar hakkında bilgi vermek, sabırlı bir dil kullanmak ve hızlı çözüm üretmek beklenir. Çocuğu mutlu olan aile rahat eder; çocuğu sıkılan ya da güvende hissetmeyen aile tatilinden memnun kalmaz.","iliskili":["os-5-014","os-5-007"],"kontrol":null,"gorsel":"h5a-bebek-besigi"},{"id":"os-5-022","konu":"5.1.2","terim":"VIP konuk","ingilizce":"VIP (Very Important Person)","tanim":"Devlet büyüğü, sanatçı ya da alanında tanınmış kişi gibi, işletmenin çok önemli sayıp ayrıcalıklı hizmet sunduğu konuktur.","ornek":"Saat 17.00: tanınmış bir sanatçı gelmeden önce odası bir kez daha kontrol edilir; konuk bankoda bekletilmez, kaydı odasında tamamlanır.","sektor":"Beklentisi gizlilik, hız, ayrıcalık ve kusursuz ayrıntıdır. Kimin VIP sayılacağını işletme belirler; balayı çiftleri ve yöneticilerin misafirleri de bu gruba alınabilir. Hazırlık konuk gelmeden biter.","iliskili":["os-5-023","os-5-026","os-5-027"],"kontrol":null},{"id":"os-5-023","konu":"5.1.2","terim":"CIP konuk","ingilizce":"CIP (Commercially Important Person)","tanim":"Seyahat acentesi yetkilisi, medya mensubu ya da iş yapılan şirketin yöneticisi gibi, işletme için ticari açıdan önem taşıyan konuktur.","ornek":"Otelle sözleşmesi olan acentenin satış müdürü hafta sonu konaklamaya gelir; genel müdür kendisini lobide karşılar ve yenilenen odaları gezdirir.","sektor":"CIP konuk gördüğünü işine taşır: memnun kalan acente yetkilisi otele çok sayıda konuk yönlendirebilir, memnun kalmayan ise anlaşmayı gözden geçirir.","iliskili":["os-5-022","os-5-024"],"kontrol":null,"gorsel":"os-cip-konuk"},{"id":"os-5-024","konu":"5.1.2","terim":"VVIP konuk","ingilizce":"VVIP (Very Very Important Person)","tanim":"Ülke başkanı, dünyaca tanınmış bir isim ya da işletmenin sahibi gibi, VIP konuktan da üstün tutulan ve en üst düzey özenle ağırlanan konuktur.","ornek":"Bir devlet başkanının konaklayacağı gün otelde kat planı, güvenlik düzeni ve karşılama töreni günler öncesinden hazırlanır.","sektor":"Her otelde bu kategori bulunmaz; kimin VVIP sayılacağına işletme karar verir. Personel için anlamı açıktır: bu konaklamada hiçbir ayrıntı tesadüfe bırakılmaz.","iliskili":["os-5-022","os-5-026"],"kontrol":null,"kitapDisi":true,"cizim":"zil-hizmet"},{"id":"os-5-025","konu":"5.1.2","terim":"Sadık konuk","ingilizce":"Loyal guest","tanim":"Aynı oteli sürekli tercih eden ve işletmeyle duygusal bağ kuran konuktur.","ornek":"Her yaz aynı otele gelen aileyi resepsiyon görevlisi “Tekrar hoş geldiniz, Demir Ailesi, geçen yılki odanızı ayırdık” diye karşılar.","sektor":"Sektörde “repeat guest” denir. Sık gelen konuk sayısının çok olması işletmenin saygınlığını gösterir: memnun kalmayan geri gelmez. Bu konuğa kendini yeniden tanıtmak zorunda bırakılmaması en büyük ayrıcalıktır.","iliskili":["os-5-029","os-5-048"],"kontrol":null},{"id":"os-5-026","konu":"5.1.2","terim":"Protokol kuralları","ingilizce":"Protocol","tanim":"Resmî ve önemli konukların karşılanması, ağırlanması ve uğurlanması sırasında uyulan öncelik, hitap ve davranış düzenidir.","ornek":"Bir bakanın geleceği gün: kimin kapıda karşılayacağı, hangi asansörün ayrılacağı ve konuğa nasıl hitap edileceği önceden belirlenir.","sektor":"VIP konuk ağırlarken protokolü uygulamak personelden beklenen bir beceridir. Stajyer protokolü kendi kafasına göre yorumlamaz; amirinden aldığı talimatı harfiyen uygular.","iliskili":["os-5-022","os-5-024"],"kontrol":null,"gorsel":"h5a-bayrakli-toplanti-masasi"},{"id":"os-5-027","konu":"5.1.2","terim":"Konuk gizliliği","ingilizce":"Guest confidentiality","tanim":"Konuğun kim olduğu, hangi odada kaldığı, kiminle geldiği ve ne yaptığı gibi bilgilerin kimseyle paylaşılmaması ilkesidir.","ornek":"Saat 21.00, santral: arayan kişi ünlü bir oyuncunun otelde kalıp kalmadığını sorar; görevli “Konuklarımızla ilgili bilgi veremiyorum efendim” der.","sektor":"VIP konuğun ilk beklentisidir, ama her konuğun hakkıdır. Oda numarası yüksek sesle söylenmez, konuğun fotoğrafı çekilmez, arkadaşlara “Bizde kim kalıyor biliyor musun?” denmez.","iliskili":["os-5-022","os-5-008"],"kontrol":null},{"id":"os-5-028","konu":"5.1.2","terim":"Beklenti oluşmadan sunma","ingilizce":"Anticipating guest needs","tanim":"Konuğun ihtiyacını o istemeden önce fark edip hizmeti kendiliğinden sunma becerisidir.","ornek":"Yağmurlu bir sabah 09.00: kapı görevlisi dışarı çıkmak üzere olan konuğa, o sormadan şemsiye uzatır.","sektor":"VIP konuk ağırlamanın ölçüsüdür: iyi otel isteneni yapar, çok iyi otel istenmeden yapar. Bunun yolu konuğun tercihlerini önceden öğrenmek ve gözlem yapmaktır.","iliskili":["os-5-029","os-5-037","os-5-012"],"kontrol":null},{"id":"os-5-029","konu":"5.1.2","terim":"Konuk tercih kaydı","ingilizce":"Guest history","tanim":"Konuğun önceki konaklamalarındaki istek, alışkanlık ve yaşadığı sorunların işletme sisteminde saklanan kaydıdır.","ornek":"Rezervasyon ekranında not: “Yüksek kat ister, kuş tüyü yastığa alerjisi var.” Kat hizmetleri odayı konuk gelmeden buna göre hazırlar.","sektor":"Konuğun kişisel tercihlerini önceden öğrenmenin yolu budur. Kayıt tutulmazsa aynı hata aynı konuğa ikinci kez yapılır. Bu bilgiler yalnız hizmet için kullanılır ve gizli tutulur.","iliskili":["os-5-012","os-5-025","os-5-028"],"kontrol":null,"kitapDisi":true,"cizim":"zil-hizmet"},{"id":"os-5-030","konu":"5.1.2","terim":"Butler","ingilizce":"Butler","tanim":"Bazı üst sınıf otellerde özel konuklara konaklamaları boyunca birebir, kişisel hizmet veren görevlidir.","ornek":"Kral dairesinde kalan konuğun valizini açan, akşam yemeği rezervasyonunu yapan ve sabah kahvesini istediği saatte getiren hep aynı kişidir.","sektor":"Türkçede “kişisel servis görevlisi” de denir. Konuk isteğini her seferinde başka bir bölüme anlatmak zorunda kalmaz; tek bir kişi onu tanır ve her şeyi o ayarlar.","iliskili":["os-5-022","os-5-012"],"kontrol":null,"kitapDisi":true},{"id":"os-5-031","konu":"5.1.2","terim":"Turn down hizmeti","ingilizce":"Turndown service","tanim":"Akşam saatlerinde yatak örtüsü açılarak, perdeler kapatılarak ve oda toparlanarak konuk odasının geceye hazırlanması hizmetidir.","ornek":"Saat 19.30: konuk akşam yemeğindeyken kat görevlisi odaya girer, yatak örtüsünü açar, perdeleri kapatır ve başucu lambasını yakar.","sektor":"Öğretmen notunda özellikle engelli ve hasta konuklar için sunulduğu vurgulanır: konuk odasına döndüğünde yatağı hazırdır, eğilip uğraşması gerekmez. Üst sınıf otellerde VIP konuklara da sunulan bir akşam hizmetidir.","iliskili":["os-5-015","os-5-022"],"kontrol":null,"kitapDisi":true,"gorsel":"h5a-yatak-hazirligi"},{"id":"os-5-185","konu":"5.1.2","terim":"Braille (kabartma) alfabe","ingilizce":"Braille","tanim":"Görme engelli kişilerin parmaklarıyla okuduğu kabartma noktalardan oluşan yazı sistemidir.","ornek":"Asansör düğmelerinde ve kat tabelalarında Braille yazı bulunur; görme engelli konuk kat numarasını yardım istemeden bulur.","sektor":"Engelli konuklar için alınan fiziksel önlemlerdendir: Braille’li asansör düğmeleri ve yönlendirme tabelaları bağımsız hareketi sağlar.","iliskili":["os-5-015","os-5-016","os-5-019"],"kontrol":null,"cizim":"zil-hizmet"},{"id":"os-5-186","konu":"5.1.2","terim":"Işıklı uyarı sistemi","ingilizce":"Visual alarm (strobe alarm)","tanim":"Yangın alarmı gibi uyarıları sesle birlikte yanıp sönen ışıkla da veren, işitme engelli konukların uyarıyı fark etmesini sağlayan sistemdir.","ornek":"Gece yangın alarmı çalar; işitme engelli konuğun odasındaki ışıklı uyarı yanıp söner ve konuk tehlikeyi fark eder.","sektor":"Alarmı yalnız sesle veren tesiste işitme engelli konuk tehlikeden haberdar olmayabilir; bu yüzden ışıklı uyarı erişilebilir odaların parçasıdır.","iliskili":["os-5-015","os-5-019","os-5-107"],"kontrol":null,"cizim":"uyari"},{"id":"os-5-032","konu":"5.1.3","terim":"Davranış biçimine göre konuk tipleri","ingilizce":"Guest behaviour types","tanim":"Konukların karakterlerine ve o andaki davranışlarına bakılarak yapılan, her birine nasıl yaklaşılacağını gösteren gruplamadır.","ornek":"Aynı sabah bankoya üç konuk gelir: biri her ayrıntıyı sorar, biri sesini yükseltir, biri bir şey söyleyemeden bekler. Görevli üçüne de aynı nezaketle, ama farklı üslupla yaklaşır.","sektor":"Ders kitabı beş tip sayar: titiz ve eleştirel, öfkeli ve sert, sessiz ve utangaç, konuşkan ve samimi, kararsız. Bir konuk tek bir tipe sığmaz; yorgunken öfkeli, dinlenince güler yüzlü olabilir. Tipler kişiyi değil, o andaki davranışı anlamaya yarar.","iliskili":["os-5-033","os-5-034","os-5-003"],"kontrol":null,"cizim":"kalp-empati"},{"id":"os-5-033","konu":"5.1.3","terim":"Titiz ve eleştirel konuk","ingilizce":"Meticulous and critical guest","tanim":"Her ayrıntıya dikkat eden, kusursuzluk bekleyen ve küçük eksikleri hemen fark edip dile getiren konuk tipidir.","ornek":"Saat 15.20, oda 508: konuk çarşafın katlanışından aynadaki su lekesine kadar gördüklerini not almıştır; kat şefi listeyi tek tek dinler ve odayı yeniden kontrol ettirir.","sektor":"Standartlara tam uygun hizmet sunulur, sabırlı ve nazik bir dil kullanılır. “Odanız kontrol edildi” diye savunmaya geçmek işe yaramaz. Titiz konuk memnun kalırsa sadık konuğa dönüşebilir; çünkü aradığı standardı sende bulmuştur.","iliskili":["os-5-032","os-5-043"],"kontrol":null},{"id":"os-5-034","konu":"5.1.3","terim":"Öfkeli ve sert konuk","ingilizce":"Angry guest","tanim":"Küçük bir aksilikte sesini yükseltebilen, sabırsız ve buyurgan davranan konuk tipidir.","ornek":"Saat 22.00, resepsiyon: odasında sıcak su akmayan konuk bankoya vurarak konuşur; görevli sesini yükseltmez, sözünü kesmez, sonuna kadar dinler ve teknik servisi arar.","sektor":"Doğru yaklaşım sakin kalmak, sözünü kesmeden dinlemek ve savunmaya geçmeden çözüme yönelmektir. Öfke çoğu zaman sana değil, duruma yöneliktir; üstüne alınma.","iliskili":["os-5-035","os-5-032","os-5-060"],"kontrol":null},{"id":"os-5-035","konu":"5.1.3","terim":"Sakin kalma","ingilizce":"Staying calm","tanim":"Konuk sesini yükseltse ya da kırıcı konuşsa bile soğukkanlılığı koruma, savunmaya geçmeme ve konukla tartışmama ilkesidir.","ornek":"Konuk “Siz bu işi bilmiyorsunuz!” diye bağırır; görevli derin bir nefes alır ve aynı sakin sesle “Sizi dinliyorum efendim, hemen ilgileneceğim” der.","sektor":"Konukla tartışmayı kazanan personel, konuğu kaybetmiştir. Sen de sesini yükseltirsen sorun büyür; sakin kalırsan çoğu zaman konuğun sesi de düşer. Haklı çıkmak senin işin değil; sorunu çözmek senin işin.","iliskili":["os-5-034","os-5-060","os-5-083"],"kontrol":null,"cizim":"kalp-empati"},{"id":"os-5-036","konu":"5.1.3","terim":"Sessiz ve utangaç konuk","ingilizce":"Quiet and shy guest","tanim":"İhtiyacını ve rahatsızlığını söylemekte zorlanan, şikâyetini çoğu zaman dile getirmeyen ama memnun kalmadan ayrılabilen konuk tipidir.","ornek":"Saat 18.00, lobi: odasında internet çalışmayan konuk bankoya yaklaşıp geri döner. Görevli fark eder ve yanına gidip “Yardımcı olabileceğim bir konu var mı efendim?” diye sorar.","sektor":"Bu konukta personel ilk adımı kendisi atar: nazik ve kısa sorularla konuğu konuşmaya açar. Sessizlik memnuniyet demek değildir; hiçbir şey söylemeden giden konuk bir daha gelmeyebilir.","iliskili":["os-5-037","os-5-032"],"kontrol":null,"cizim":"kalp-empati"},{"id":"os-5-037","konu":"5.1.3","terim":"Proaktif yaklaşım","ingilizce":"Proactive approach","tanim":"Sorun ortaya çıkmadan ya da konuk bir şey istemeden önce durumu fark edip harekete geçme tutumudur.","ornek":"Saat 13.30: görevli, o gün gelecek konuğun odasını konuk gelmeden bir kez daha kontrol eder; kumandanın pili bitmiştir, hemen değiştirtir.","sektor":"En iyi çözülen şikâyet, hiç yaşanmamış olandır. Proaktif personel beklemez; bakar, sorar, önlem alır. Tersi tepkisel davranmaktır: sorun büyüyüp şikâyete dönüşene kadar harekete geçmemek.","iliskili":["os-5-036","os-5-028"],"kontrol":null,"cizim":"kalp-empati"},{"id":"os-5-038","konu":"5.1.3","terim":"Konuşkan ve samimi konuk","ingilizce":"Talkative guest","tanim":"Uzun uzun sohbet etmeyi seven ve farkında olmadan personeli işinden alıkoyabilen konuk tipidir.","ornek":"Saat 11.00, resepsiyon: konuk torunlarını anlatırken arkasında sıra oluşur. Görevli “Ne güzel efendim; izninizle bekleyen konuklarımızla ilgileneyim, sonra devamını dinlemek isterim” der.","sektor":"Nezaketle dinlenir, ama profesyonel mesafe korunur ve zaman iyi yönetilir. Sohbeti kırmadan bitirmek öğrenilen bir beceridir. Bu konuk memnun kalırsa oteli herkese anlatır.","iliskili":["os-5-039","os-5-032"],"kontrol":null,"cizim":"konusma"},{"id":"os-5-039","konu":"5.1.3","terim":"Profesyonel mesafe","ingilizce":"Professional distance","tanim":"Konuğa sıcak ve içten davranırken saygı sınırını aşmama, senli benli olmama ve işini aksatmama ölçüsüdür.","ornek":"Konuk “Akşam bizim masaya gel, birlikte yiyelim” der; garson gülümseyerek “Çok naziksiniz efendim, görevdeyim; size en güzel masayı hazırlayayım” diye karşılık verir.","sektor":"Fazla resmî personel soğuk, fazla rahat personel saygısız görünür. Konuk arkadaş değil, ağırladığın kişidir: özel hayatını anlatmazsın, onunkini sormazsın, telefon numarası alıp vermezsin.","iliskili":["os-5-038","os-5-027"],"kontrol":null,"cizim":"beden-dili"},{"id":"os-5-040","konu":"5.1.3","terim":"Kararsız konuk","ingilizce":"Indecisive guest","tanim":"Oda ya da yemek seçerken karar vermekte zorlanan ve sürekli onay bekleyen konuk tipidir.","ornek":"Saat 20.15, restoran: konuk menüye uzun süre bakar. Garson “Bugün levreğimiz çok taze; daha hafif bir şey isterseniz ızgara sebze tabağımızı öneririm” der.","sektor":"Konuğun önüne az sayıda seçenek konur; personel kendi uzmanlığına dayanarak öneride bulunur ve konuğu nazikçe yönlendirir. Acele ettirmek konuğu daha da kararsız yapar; son sözü yine konuk söyler.","iliskili":["os-5-041","os-5-032"],"kontrol":null,"cizim":"konusma"},{"id":"os-5-041","konu":"5.1.3","terim":"Seçenekleri daraltma","ingilizce":"Narrowing down the options","tanim":"Kararsız konuğa bütün olasılıkları saymak yerine ona en uygun iki ya da üç seçeneği sunarak karar vermesini kolaylaştırma yöntemidir.","ornek":"Rezervasyon görevlisi sekiz oda tipini saymaz: “Size iki odamızı önerebilirim: biri bahçe manzaralı ve sessiz, diğeri deniz manzaralı ve balkonlu” der.","sektor":"Çok seçenek konuğu rahatlatmaz, yorar. İyi daraltmak için önce bir iki soru sorulur (“Sessizlik mi, manzara mı önemli?”), sonra öneri yapılır; karar konuğa bırakılır.","iliskili":["os-5-040","os-5-042"],"kontrol":null,"cizim":"konusma"},{"id":"os-5-042","konu":"5.1.3","terim":"İnatçı konuk","ingilizce":"Stubborn guest","tanim":"Fikrinden kolay dönmeyen ve istediği şeyde ısrar eden konuk tipidir.","ornek":"Konuk dolu olan 301 numaralı odada ısrar eder. Görevli tartışmaz: “301 bu gece dolu efendim; aynı manzaraya bakan 401’i hemen verebilirim ya da yarın 301’e geçebilirsiniz” der.","sektor":"Ders kitabının tablosunda yer almaz; öğretmen notundaki on iki kişilik tipinden biridir. Doğru yaklaşım inatlaşmamak, mümkün olan seçenekleri sunmak ve kararı konuğa bırakmaktır.","iliskili":["os-5-041","os-5-035"],"kontrol":null,"kitapDisi":true,"cizim":"konusma"},{"id":"os-5-043","konu":"5.1.3","terim":"Şüpheci konuk","ingilizce":"Sceptical guest","tanim":"Söylenene kolay inanmayan, her bilgiyi sorgulayan ve kanıt görmek isteyen konuk tipidir.","ornek":"Konuk hesabındaki bir tutarı sorar; görevli “Sanırım minibardır” demez, dökümü yazdırır ve kalem kalem birlikte üzerinden geçer.","sektor":"Ders kitabının tablosunda yer almaz; öğretmen notundaki tiplerden biridir. Bilgi açık, net ve mümkünse yazılı verilir. Yuvarlak cevap şüpheyi artırır: emin olmadığın şeyi söyleme; öğren, sonra söyle.","iliskili":["os-5-033","os-5-052"],"kontrol":null,"kitapDisi":true,"cizim":"kalp-empati"},{"id":"os-5-044","konu":"5.1.3","terim":"Kötümser konuk","ingilizce":"Pessimistic guest","tanim":"Olayların hep olumsuz yanını gören ve işlerin ters gideceğini düşünen konuk tipidir.","ornek":"Konuk “Kesin yine uçağı kaçıracağım” der; görevli “Transfer aracınız 05.30’da kapıda olacak efendim, uyandırma aramanızı da 04.45’e kaydettim” diye cevap verir.","sektor":"Ders kitabının tablosunda yer almaz; öğretmen notundaki tiplerden biridir. Boş teselli işe yaramaz; bu konuğu rahatlatan şey olumlu ama gerçekçi bir dille verilen somut bilgidir.","iliskili":["os-5-043","os-5-032"],"kontrol":null,"kitapDisi":true,"cizim":"kalp-empati"},{"id":"os-5-184","konu":"5.1.3","terim":"Sürekli şikâyet eden konuk","ingilizce":"Persistent complainer","tanim":"Küçük aksaklıklarda bile sık sık şikâyet eden, “zor konuk” sayılan konuk tipidir.","ornek":"Tatil köyünde üçüncü gün: konuk sabah kahvaltıda çayın soğuk olmasından, öğleden sonra şezlong sıkıntısından yakınır; görevli tartışmaya girmez, her şikâyeti not alır, sabırla dinler ve her biri için somut bir çözüm sunar.","sektor":"Doğru yaklaşım sabırla dinlemek, empati kurmak, çözüm odaklı olmak ve notlar almaktır; tartışmaya girmek yanlıştır. Her şikâyet kayda geçer, çünkü bu konuğun bir şikâyeti gerçek bir sorunu da gösterebilir.","iliskili":["os-5-033","os-5-059","os-5-057"],"kontrol":null,"cizim":"konusma"},{"id":"os-5-045","konu":"5.1.4","terim":"Konuk memnuniyetinin ölçüsü","ingilizce":"Guest satisfaction level","tanim":"Konuk memnuniyetinin ölçüsü, aldığı hizmetin konuğun beklentisini karşılama düzeyidir; memnuniyet, konuğun bu karşılaştırması sonucunda oluşan duygusal tepkidir.","ornek":"İki konuk aynı odada kalır: sade bir oda bekleyen çok memnun olur, fotoğraflarda daha geniş bir oda gören ise hayal kırıklığı yaşar.","sektor":"Memnuniyet odanın büyüklüğüyle değil, beklenti ile yaşanan arasındaki farkla ölçülür. Temiz oda ve lezzetli yemek gereklidir ama tek başına yetmez; belirleyici olan konuğun kendini nasıl hissettiğidir.","iliskili":["os-5-004","os-5-046","os-5-049"],"kontrol":null,"gorsel":"h5a-bes-yildiz"},{"id":"os-5-046","konu":"5.1.4","terim":"Beklentiyi aşma","ingilizce":"Exceeding expectations","tanim":"Konuğa umduğundan daha iyi bir hizmet ya da ummadığı bir incelik sunulmasıdır.","ornek":"Konuk giriş sırasında doğum günü olduğunu söylemez; görevli kimlikten fark eder, akşam odasına küçük bir pasta ve el yazısıyla bir kutlama notu gönderilir.","sektor":"Beklentisi karşılanan konuk memnun olur; beklentisi aşılan konuk bunu başkalarına anlatır. Fark çoğu zaman pahalı bir şey değil, dikkat ve küçük bir inceliktir.","iliskili":["os-5-045","os-5-047","os-5-076"],"kontrol":null,"cizim":"zil-hizmet"},{"id":"os-5-047","konu":"5.1.4","terim":"İşletmenin elçisi konuk","ingilizce":"Brand ambassador guest","tanim":"Beklentisinden fazlasını bulduğu için işletmeyi çevresine kendiliğinden öven ve öneren memnun konuktur.","ornek":"Tatilden dönen konuk iş yerinde “Bodrum’da öyle bir otelde kaldık ki, mutlaka gidin” der ve otelin adını arkadaşlarına yazıp gönderir.","sektor":"İnsanlar reklamdan çok tanıdıklarının sözüne güvenir. Memnun konuk otelin ücretsiz ve en inandırıcı tanıtımını yapar; memnun kalmayan konuk ise aynı işi tersine yapar.","iliskili":["os-5-046","os-5-048"],"kontrol":null,"cizim":"marka"},{"id":"os-5-048","konu":"5.1.4","terim":"Konuk sadakati","ingilizce":"Guest loyalty","tanim":"Memnun kalan konuğun aynı işletmeyi tekrar tekrar tercih etmesi ve ona bağlılık duymasıdır.","ornek":"Çeşme’deki bir otelin konuklarından bazıları, çıkış yaparken bir sonraki yazın rezervasyonunu da yaptırır.","sektor":"Sadık konuk otele düzenli gelir getirir. Doğru karşılanan bir şikâyet bile şikâyetçiyi sadık konuğa dönüştürebilir; otelden memnun ayrılan her konuk bir sonraki sezonun hazır konuğudur.","iliskili":["os-5-047","os-5-025","os-5-057"],"kontrol":null,"cizim":"kalite-yildiz"},{"id":"os-5-049","konu":"5.1.4","terim":"Memnuniyeti belirleyen unsurlar","ingilizce":"Drivers of guest satisfaction","tanim":"Fiziksel imkânların ötesinde konuğun hoşnut kalıp kalmayacağını asıl belirleyen üç etkendir: empati ve ilgi, hız ve profesyonellik, güven ve dürüstlük.","ornek":"Odası çok güzel olan ama sorusuna kimsenin cevap vermediği konuk memnun ayrılmaz; odası sade olan ama her isteğiyle ilgilenilen konuk yeniden gelir.","sektor":"Üçü de binaya değil, insana bağlıdır. Havuzu, mobilyayı yatırımcı satın alır; bu üç unsuru ise her gün personel üretir.","iliskili":["os-5-050","os-5-051","os-5-052"],"kontrol":null},{"id":"os-5-050","konu":"5.1.4","terim":"Empati ve ilgi","ingilizce":"Empathy and attention","tanim":"Konuğun durumunu onun gözünden görmeye çalışma ve kendisiyle gerçekten ilgilenildiğini ona hissettirme tutumudur.","ornek":"Saat 02.00, resepsiyon: gecikmeli uçakla gelen aileye görevli “Çok yorulmuş olmalısınız; işleminizi hemen bitirip sizi odanıza çıkarayım” der.","sektor":"Memnuniyeti belirleyen üç unsurun ilkidir; sonucu konuğun kendini değerli hissetmesidir. İlgi göstermek için zaman değil dikkat gerekir: göz teması, adıyla hitap, söylediğini hatırlamak.","iliskili":["os-5-049","os-5-061"],"kontrol":null,"cizim":"kalp-empati"},{"id":"os-5-051","konu":"5.1.4","terim":"Hız ve profesyonellik","ingilizce":"Speed and professionalism","tanim":"Konuğun isteğinin ve sorununun vakit kaybetmeden, işini bilen bir tavırla sonuçlandırılmasıdır.","ornek":"Saat 16.10: konuk ek havlu ister; görevli “On dakika içinde odanızda olacak efendim” der, kat hizmetlerini arar ve havlu sekiz dakikada gelir.","sektor":"Memnuniyeti belirleyen üç unsurdan biridir. Küçük bir istek bile bekledikçe büyür: yarım saat beklenen havlu artık bir havlu sorunu değil, “Beni unuttular” sorunudur.","iliskili":["os-5-049","os-5-064","os-5-006"],"kontrol":null},{"id":"os-5-052","konu":"5.1.4","terim":"Güven ve dürüstlük","ingilizce":"Trust and honesty","tanim":"Konuğa doğru bilgi verilmesi ve verilen her sözün tutulmasıyla kazanılan güvendir.","ornek":"Görevli klimanın ne zaman onarılacağını bilmiyorsa “Beş dakikada olur” demez; “Teknik servise soruyorum, on dakika içinde sizi arayıp bilgi vereceğim” der ve arar.","sektor":"Memnuniyeti belirleyen üç unsurdan biridir. Tutulmayan söz ikinci bir şikâyet doğurur. Az söz verip fazlasını yapmak, çok söz verip azını yapmaktan her zaman iyidir.","iliskili":["os-5-049","os-5-076","os-5-084"],"kontrol":null},{"id":"os-5-053","konu":"5.1.4","terim":"Karşılama sanatı","ingilizce":"Art of welcoming","tanim":"Konuğun tesise adım attığı anda başlayan; beden dili, ses tonu ve sözcüklerin uyumuyla ona özel olduğunu hissettiren karşılama biçimidir.","ornek":"Saat 14.05, otel girişi: kapı görevlisi kapıyı açar, resepsiyon görevlisi ayağa kalkıp gülümser ve “Hoş geldiniz efendim, yolculuğunuz nasıl geçti?” diye sorar.","sektor":"Bütün konaklama deneyiminin temelini karşılama atar. Önemli olan yalnız ne söylendiği değil, konuğa ne hissettirildiğidir: güzel bir cümle ilgisiz bir yüzle söylenirse boşa gider.","iliskili":["os-5-054","os-5-002"],"kontrol":null},{"id":"os-5-054","konu":"5.1.4","terim":"İlk otuz saniye","ingilizce":"First thirty seconds","tanim":"Konuğun tesis hakkındaki ilk izlenimini edindiği, sonradan geri alınamayan kısa karşılaşma anıdır.","ornek":"Konuk kapıdan girer; bankodaki görevli ekrandan başını kaldırmaz, gülümsemez. Konuk daha tek kelime konuşulmadan oteli hakkında kararını vermeye başlamıştır.","sektor":"Ders kitabı ilk izlenimin oluştuğu süreyi ilk otuz saniye olarak verir. Süre kesin bir ölçü değildir; anlatmak istediği şudur: ilk izlenim çok çabuk oluşur ve ikinci kez kurulamaz.","iliskili":["os-5-053"],"kontrol":null},{"id":"os-5-055","konu":"5.1.4","terim":"Dijital deneyim","ingilizce":"Digital guest experience","tanim":"Konuğun rezervasyondan çıkışa kadar telefonu ve internet üzerinden aldığı hizmetlerin bütünüdür.","ornek":"Konuk girişini otele gelmeden telefonundan yapar, restoranda menüyü karekoddan açar, ek yastık isteğini otelin uygulamasından yazar.","sektor":"Konuklar artık yalnız bir oda değil, dijital alışkanlıklarına uyan bir hizmet bekler; bunu sunan tesis rekabette öne geçer. Teknoloji işi hızlandırır, ama güler yüzün yerini tutmaz: ekran çalışmadığında konuk yine bir insan arar.","iliskili":["os-5-056","os-5-012"],"kontrol":null,"cizim":"dijital"},{"id":"os-5-056","konu":"5.1.4","terim":"Yeni nesil konuk","ingilizce":"New-generation guest","tanim":"İşlemlerini telefonundan yapmaya alışkın olan, teknolojik kolaylık bekleyen ve işletmenin çevreye duyarlılığını önemseyen konuk tipidir.","ornek":"Saat 19.00, restoran: konuk karekodlu menüyü bulamadığı için gerilir ve otelin sürdürülebilirlik belgesini sorar. Garson karekodu gösterir, belgenin lobide asılı olduğunu söyler.","sektor":"Personelden teknolojik yetkinlik ve otelin çevreci uygulamalarını anlatabilme beklenir. “Ben o uygulamadan anlamam” diyen personel bu konuğun gözünde oteli de eskitir.","iliskili":["os-5-055"],"kontrol":null,"cizim":"grafik"},{"id":"os-5-057","konu":"5.1.4","terim":"Şikâyet","ingilizce":"Complaint","tanim":"Konuğun memnun kalmadığı bir durumu işletmeye bildirmesidir.","ornek":"Sabah 08.30, resepsiyon: konuk “Dün gece yan odadan çok ses geldi, uyuyamadık” der.","sektor":"Şikâyet işletme için bir hediye sayılır: konuk hizmetteki bir açığı gösterir ve kendisini kaybetmemen için sana ikinci bir şans verir. Bu yüzden şikâyet eden konuğa teşekkür edilir. Asıl kayıp, hiçbir şey söylemeden giden konuktur.","iliskili":["os-5-058","os-5-059","os-5-070"],"kontrol":null,"gorsel":"h5a-oneri-kutusu"},{"id":"os-5-058","konu":"5.1.4","terim":"Şikâyet yönetimi","ingilizce":"Complaint management","tanim":"Konuk şikâyetlerinin dinlenmesi, çözülmesi, kaydedilmesi ve aynı sorunun tekrarlanmaması için değerlendirilmesi işidir.","ornek":"Otelde her sabah toplantısında bir önceki günün şikâyetleri okunur: hangisi çözüldü, hangisi tekrar etti, kim takip ediyor?","sektor":"İşletmenin zayıf halkalarını bulup güçlendirmesini sağlayan en değerli geri bildirim yoludur. İyi çözülmüş bir sorun, şikâyetçi konuğu sadık bir konuğa çevirebilir.","iliskili":["os-5-057","os-5-059","os-5-066"],"kontrol":null},{"id":"os-5-059","konu":"5.1.4","terim":"LEARN modeli","ingilizce":"LEARN model","tanim":"Şikâyeti olan konukla iletişimde sırayla izlenen dinle, empati kur, özür dile, çözüm üret ve hemen yap adımlarından oluşan beş basamaklı yöntemdir.","ornek":"Kliması soğutmayan konuğu görevli sonuna kadar dinler, “Bu sıcakta çok zor olmalı” der, özür diler, teknik servisi arar ve hemen başka bir oda hazırlatır.","sektor":"Adını adımların İngilizce baş harflerinden alır: Listen, Empathise, Apologise, React, Now. Amaç konuğun duygusunu sakinleştirmek ve sorunu profesyonelce sahiplenmektir. Sıra önemlidir: dinlemeden çözüm önerirsen konuk dinlenmediğini düşünür.","iliskili":["os-5-060","os-5-061","os-5-063"],"kontrol":null,"cizim":"kitap-ogrenme"},{"id":"os-5-060","konu":"5.1.4","terim":"Dinle (Listen)","ingilizce":"Listen","tanim":"LEARN modelinin ilk adımı olan, konuğu sözünü kesmeden, göz teması kurarak ve başka işle uğraşmadan sonuna kadar dinleme davranışıdır.","ornek":"Konuk şikâyetini anlatırken görevli ekrana bakmaz, telefonu açmaz, “Ama efendim…” diye araya girmez; yalnız başıyla onaylar.","sektor":"Konuk önce dinlenmek ister, çözüm sonra gelir. Sözü kesilen konuk aynı şeyi daha yüksek sesle baştan anlatır. Dinlerken kısa not almak hem bilgiyi korur hem konuğa ciddiye alındığını gösterir.","iliskili":["os-5-059","os-5-061","os-5-035"],"kontrol":null,"cizim":"kulak-dinleme"},{"id":"os-5-061","konu":"5.1.4","terim":"Empati kur (Empathise)","ingilizce":"Empathise","tanim":"LEARN modelinin ikinci adımı olan, konuğun ne hissettiğini anladığını ona sözle ve tavırla gösterme davranışıdır.","ornek":"Görevli, “Uzun bir yolculuktan sonra sıcak bir odayla karşılaşmak gerçekten çok yorucu; sizi anlıyorum efendim” der.","sektor":"Empati, konuğa her konuda hak vermek ya da her isteğini kabul etmek değildir; duygusunu gördüğünü göstermektir. Anlaşıldığını hisseden konuk sakinleşir ve çözümü dinlemeye hazır olur.","iliskili":["os-5-059","os-5-050","os-5-062"],"kontrol":null,"cizim":"kalp-empati"},{"id":"os-5-062","konu":"5.1.4","terim":"Özür dile (Apologise)","ingilizce":"Apologise","tanim":"LEARN modelinin üçüncü adımı olan, yaşanan aksaklık için işletme adına konuğa içtenlikle üzgün olduğunu söyleme davranışıdır.","ornek":"Görevli, “Yaşadığınız bu durum için çok özür dilerim efendim; bize bildirdiğiniz için teşekkür ederim” der.","sektor":"Özür, hatayı kimin yaptığını tartışmak değildir; otelin adına sorumluluğu üstlenmektir. “Ama” ile devam eden özür (“Özür dilerim ama bugün çok yoğunuz”) özür sayılmaz; suçu başka bölüme atmak da öyle.","iliskili":["os-5-059","os-5-065","os-5-080"],"kontrol":null,"cizim":"zil-hizmet"},{"id":"os-5-063","konu":"5.1.4","terim":"Çözüm üret (React)","ingilizce":"React","tanim":"LEARN modelinin dördüncü adımı olan, konuğun sorununu giderecek somut bir çözüm bulma ve bunu ona açıkça söyleme davranışıdır.","ornek":"Görevli, “Teknik ekibimizi şimdi odanıza gönderiyorum; isterseniz aynı katta kliması çalışan bir odaya da hemen geçebilirsiniz” diyerek iki seçenek sunar.","sektor":"Konuk özürle değil, çözümle rahatlar. Mümkünse seçenek sunulur: karar konuğa bırakılınca kontrol duygusu ona geri verilmiş olur. Yetkini aşan bir çözüm gerekiyorsa söz vermeden önce amirine danışırsın.","iliskili":["os-5-059","os-5-064","os-5-085"],"kontrol":null,"cizim":"hedef-basari"},{"id":"os-5-064","konu":"5.1.4","terim":"Hemen yap (Now)","ingilizce":"Now","tanim":"LEARN modelinin son adımı olan, bulunan çözümü ertelemeden, konuk beklerken uygulamaya koyma davranışıdır.","ornek":"Görevli “Birazdan ilgileniriz” demez; konuğun yanında telefonu kaldırır, teknik servisi arar ve “On dakika içinde odanızdalar efendim” der.","sektor":"Geciken çözüm, çözüm sayılmaz: konuk beklerken öfkesi yeniden büyür. Konuğun gözü önünde atılan ilk adım, ona işin gerçekten başladığını gösterir.","iliskili":["os-5-059","os-5-063","os-5-051"],"kontrol":null,"cizim":"zil-hizmet"},{"id":"os-5-065","konu":"5.1.4","terim":"Sorunu sahiplenme","ingilizce":"Taking ownership","tanim":"Şikâyeti alan personelin “Bu benim bölümüm değil” demeden, sorun çözülene kadar işin sorumluluğunu üstlenmesidir.","ornek":"Garsona “Odamdaki televizyon çalışmıyor” diyen konuğa garson “Resepsiyona söyleyin” demez; “Hemen ön büroya bildiriyorum efendim, oda numaranızı alabilir miyim?” der.","sektor":"Konuk bölümleri görmez, tek bir otel görür. Şikâyeti kim aldıysa doğru kişiye ulaştırmak ve sonucunu izlemek onun işidir. Konuğu bir bölümden ötekine yollamak, sorunu ikiye katlar.","iliskili":["os-5-062","os-5-084","os-5-085"],"kontrol":null,"cizim":"zil-hizmet"},{"id":"os-5-066","konu":"5.1.4","terim":"Kök neden analizi","ingilizce":"Root cause analysis","tanim":"Tekrar eden bir sorunun yalnız görünen sonucunu düzeltmekle yetinmeyip onu doğuran asıl kaynağı bulma çalışmasıdır.","ornek":"Bir ayda dört konuk aynı kattaki klimalardan yakınır. Yönetim her seferinde oda değiştirmek yerine nedenini araştırır: o katın klima bakımı planda atlanmıştır.","sektor":"Aynı şikâyet farklı konuklardan geliyorsa sorun kişisel değil, sistemle ilgilidir. Bir şikâyeti çözmek bir konuğu kurtarır; nedenini ortadan kaldırmak ise sonraki bütün konukları.","iliskili":["os-5-067","os-5-068","os-5-058"],"kontrol":null,"cizim":"grafik"},{"id":"os-5-067","konu":"5.1.5","terim":"5 Neden tekniği","ingilizce":"Five Whys","tanim":"Bir sorunun kök nedenine inmek için her cevaba yeniden “Neden?” diye sorulan, genellikle beş adımlı sorgulama yöntemidir.","ornek":"Klima neden soğutmuyor? Filtresi tıkalı. Neden fark edilmedi? Kontrol listesinde yok. Neden yok? Liste güncel değil. Neden güncel değil? Bölümler birbirine bilgi vermiyor.","sektor":"İlk cevap çoğu zaman yalnız belirtidir (“klima bozuk”); asıl neden birkaç adım derindedir (“bilgi paylaşılmıyor”). Yöntem suçlu aramak için değil, sistemi düzeltmek için kullanılır.","iliskili":["os-5-066","os-5-068"],"kontrol":null,"cizim":"zil-hizmet"},{"id":"os-5-068","konu":"5.1.4","terim":"Balık kılçığı diyagramı","ingilizce":"Fishbone diagram","tanim":"Bir sorunun olası nedenlerini başlıklar altında toplayarak balık kılçığına benzeyen bir şekil üzerinde gösteren neden–sonuç çizimidir.","ornek":"Eğitim toplantısında tahtaya balığın başına “Konuk memnuniyetsizliği” yazılır; kılçıklara “personel”, “oda”, “teknik”, “tanıtım” başlıkları açılır ve altları doldurulur.","sektor":"Tek bir nedene takılıp kalmayı önler: ekip bütün olası nedenleri aynı anda görür ve hangisinin en önemli olduğunu tartışır. Neden–sonuç diyagramı da denir.","iliskili":["os-5-066","os-5-067","os-5-070"],"kontrol":null},{"id":"os-5-069","konu":"5.1.4","terim":"Konuk anketi","ingilizce":"Guest questionnaire","tanim":"Konuğun aldığı hizmetleri değerlendirerek görüşünü işletmeye bildirdiği, kâğıt ya da dijital biçimdeki formdur.","ornek":"Çıkıştan bir gün sonra konuğun telefonuna “Konaklamanızı nasıl değerlendirirsiniz?” diye soran kısa bir anket bağlantısı gelir.","sektor":"Yüzüne söylemeye çekinen konuk, memnuniyetsizliğini ankete yazar. Yönetim anketleri okuyarak hangi bölümde sorun olduğunu görür; okunmayan anket ise konuğa boşuna zahmet verdirmektir.","iliskili":["os-5-058","os-5-036"],"kontrol":null,"kitapDisi":true,"gorsel":"h5a-anket-formu"},{"id":"os-5-182","konu":"5.1.4","terim":"Sadakat programı","ingilizce":"Loyalty programme","tanim":"Aynı işletmeyi tekrar tercih eden konuğu puan, indirim ya da ayrıcalıklarla ödüllendiren üyelik sistemidir.","ornek":"Konuk her konaklamada puan kazanır; belli puana ulaşınca bir gece ücretsiz kalma ya da oda yükseltme hakkı elde eder.","sektor":"Konuk sadakatini sistemli bir ödüle bağlar. Kitabın ölçme bölümündeki bir vakada “Elite Club üyesi” konuk bu tür bir programın üyesidir.","iliskili":["os-5-048","os-5-025","os-5-047"],"kontrol":null,"cizim":"kalite-yildiz"},{"id":"os-5-188","konu":"5.1.4","terim":"Konuk bilgilendirme","ingilizce":"Guest briefing","tanim":"Giriş işlemi sırasında konuğa tesisin hizmetlerini, saatlerini ve kurallarını anlatarak tesise uyum sağlamasına yardım etme sürecidir.","ornek":"Saat 14.10, check-in: görevli konuğa kahvaltı ve havuz saatlerini, Wi-Fi şifresini ve acil çıkış yolunu kısaca anlatır.","sektor":"İyi bilgilendirilen konuk sormak zorunda kalmaz ve sonradan “Bilmiyordum” diye şikâyet etmez. Acil çıkış ve toplanma alanı bilgisi de bu sırada verilebilir.","iliskili":["os-5-053","os-5-054","os-5-112"],"kontrol":null,"cizim":"konusma"},{"id":"os-5-070","konu":"5.1.5","terim":"Konuk memnuniyetsizliği","ingilizce":"Guest dissatisfaction","tanim":"Konuğun yaşadığı hizmetin beklediğinin altında kalması sonucunda duyduğu hoşnutsuzluktur.","ornek":"Sessiz bir tatil uman konuğa, gece yarısına kadar müzik çalan barın hemen üstündeki oda verilmiştir.","sektor":"Başlıca üç kaynağı vardır: fiziksel ve teknik sorunlar, hizmet süreçleri ve personel etkileşimi, pazarlama ve beklenti yönetimi. Bazen bir arızadan, bazen de personelin tek bir bakışından doğar.","iliskili":["os-5-071","os-5-072","os-5-073"],"kontrol":null,"cizim":"zil-hizmet"},{"id":"os-5-071","konu":"5.1.5","terim":"Beklenti–gerçeklik farkı","ingilizce":"Expectation gap","tanim":"Konuğun umduğu hizmet ile tesiste gerçekten karşılaştığı durum arasındaki açıklıktır.","ornek":"İnternet sayfasında “denize sıfır” yazan otelin kumsalına gitmek için yolun karşısına geçmek gerektiğini konuk ancak geldiğinde öğrenir.","sektor":"Memnuniyetsizliğin temelinde bu fark yatar. Fark ya hizmeti iyileştirerek ya da beklentiyi baştan doğru kurarak kapatılır; ikisi birlikte yapılırsa konuk hayal kırıklığı yaşamaz.","iliskili":["os-5-070","os-5-004","os-5-074"],"kontrol":null,"cizim":"zil-hizmet"},{"id":"os-5-072","konu":"5.1.5","terim":"Fiziksel ve teknik sorunlar","ingilizce":"Physical and technical problems","tanim":"Odanın temizliği, gürültü ya da klima ve internet gibi donanımların yetersizliğinden doğan memnuniyetsizlik kaynağıdır.","ornek":"Temmuz ayında saat 15.00: uzun yoldan gelen aile odaya yerleşir, bir saat sonra klimanın soğutmadığını fark eder.","sektor":"Çözümü çoğunlukla başka bölümdedir: arıza teknik servise, temizlik kat hizmetlerine bildirilir; gerekirse oda değiştirilir. Şikâyeti alan kişi bildirmekle yetinmez, iş bitene kadar izler.","iliskili":["os-5-070","os-5-073","os-5-037"],"kontrol":null,"cizim":"zil-hizmet"},{"id":"os-5-073","konu":"5.1.5","terim":"Hizmet süreçleri ve personel etkileşimi","ingilizce":"Service and staff-related problems","tanim":"Soğuk karşılama, yavaş servis ya da personelin konuğun ihtiyacını fark etmemesi gibi insana bağlı aksaklıklardan doğan memnuniyetsizlik kaynağıdır.","ornek":"Saat 13.15, havuz barı: konuk on dakikadır bekler; iki görevli kendi aralarında konuşmaktadır ve konuğa dönüp bakmazlar.","sektor":"Konuğun duygusunu en çok bu alan belirler: teknik arıza affedilir, ilgisizlik kolay affedilmez. Bu aksaklıklar konukla kurulan duygusal bağı koparır; onarmak, bir klimayı onarmaktan zordur.","iliskili":["os-5-070","os-5-072","os-5-050"],"kontrol":null,"gorsel":"h5a-garson-kahve-tepsisi"},{"id":"os-5-074","konu":"5.1.5","terim":"Pazarlama ve beklenti yönetimi","ingilizce":"Expectation management","tanim":"İşletmenin tanıtımda ve satışta konuğa sunabileceğinden fazlasını vaat etmeyerek beklentiyi baştan doğru kurmasıdır.","ornek":"Rezervasyon görevlisi telefonda “Havuzumuz bu hafta bakımda, ayın yirmisinde açılacak; yine de rezervasyon yapmak ister misiniz?” diye sorar.","sektor":"İnternetteki fotoğrafla gerçeğin uyuşmaması ya da vaat edilen hizmetin sunulmaması hayal kırıklığı yaratır. Olumsuz bir bilgiyi baştan söylemek bir rezervasyon kaybettirebilir; söylememek ise konuğu ve otelin adını kaybettirir.","iliskili":["os-5-075","os-5-076","os-5-071"],"kontrol":null,"cizim":"marka"},{"id":"os-5-075","konu":"5.1.5","terim":"Gerçeği yansıtan tanıtım","ingilizce":"Accurate marketing","tanim":"Tesisin fotoğraflarının ve açıklamalarının olanı olduğu gibi göstermesi; internet sitesi, sosyal medya ve acentedeki bilgilerin birbirini tutmasıdır.","ornek":"Otel sitesinde “geniş oda” yazmak yerine odanın kaç metrekare olduğu yazılır; fotoğraflar tadilattan sonraki güncel hâli gösterir.","sektor":"“Geniş”, “yakın”, “lüks” gibi sözcükleri herkes farklı anlar; ölçü ve somut bilgi yanlış beklentiyi önler. Acentenin sayfasında yazan bir hizmet otelde yoksa konuk acenteye değil, karşısındaki personele kızar.","iliskili":["os-5-074","os-5-071"],"kontrol":null},{"id":"os-5-076","konu":"5.1.5","terim":"Vaat edilenden fazlasını sunma","ingilizce":"Under-promise and over-deliver","tanim":"Konuğa söz verilenden bir adım fazlasını verme ve küçük sürprizleri tanıtımda önceden duyurmama ilkesidir.","ornek":"Tanıtımda hiç söz edilmemiştir; konuk odasına girdiğinde masada yörenin meşhur lokumundan küçük bir tabak ve “Hoş geldiniz” notu bulur.","sektor":"Önceden duyurulan ikram artık sürpriz değil, beklentidir; verilmezse şikâyet konusu olur. Söylenmeden yapılan incelik ise beklentiyi aşar ve konuğun aklında kalır.","iliskili":["os-5-046","os-5-074","os-5-052"],"kontrol":null,"cizim":"zil-hizmet"},{"id":"os-5-077","konu":"5.1.5","terim":"Hizmet telafisi","ingilizce":"Service recovery","tanim":"Aksaklık yaşayan konuğun hayal kırıklığını gidermek ve memnuniyetini yeniden kazanmak için işletmenin yaptığı düzeltme ve gönül alma çalışmasıdır.","ornek":"Odası geç hazırlanan aileye özür dilenir, bekledikleri sürede lobide ikram yapılır ve akşam yemeği için en güzel masa ayrılır.","sektor":"Yalnız özür dilemenin ötesine geçer: amaç hayal kırıklığını mutluluğa çevirmektir. İyi telafi edilen bir aksaklık, konuğu hiç sorun yaşamamış olandan daha bağlı bir konuğa dönüştürebilir.","iliskili":["os-5-078","os-5-079","os-5-062"],"kontrol":null},{"id":"os-5-078","konu":"5.1.5","terim":"Telafi jesti","ingilizce":"Recovery gesture","tanim":"Aksaklık yaşayan konuğa gönlünü almak için sunulan, büyüklüğü yaşanan sorunla orantılı olan ikram ya da ayrıcalıktır.","ornek":"Çorbası soğuk gelen konuğa yenisi getirilir ve bir tatlı ikram edilir; bütün gece arıza yüzünden uyuyamayan konuğun ise oda değişikliği ve daha büyük bir telafi için müdür devreye girer.","sektor":"Temel ilke orantıdır: küçük soruna büyük jest gereksizdir, büyük soruna küçük jest alay gibi algılanır. Hangi jestin yapılacağına personel yetkisi içinde karar verir; yetkisini aşan jesti amiri onaylar.","iliskili":["os-5-077","os-5-079","os-5-085"],"kontrol":null},{"id":"os-5-079","konu":"5.1.5","terim":"Somut telafi","ingilizce":"Tangible compensation","tanim":"Konaklama sürerken sunulan ücretsiz akşam yemeği, meyve sepeti ya da spa kullanımı gibi, elle tutulur telafi jestidir.","ornek":"Saat 18.00: su kesintisi yüzünden duş alamayan konuğa özür dilenir ve o akşam otelin restoranında ücretsiz yemek ikram edilir.","sektor":"Konuğun o andaki gerginliğini fiziksel bir konforla dağıtır. Sorun çözülmeden sunulursa işe yaramaz: klima hâlâ bozukken gelen meyve sepeti konuğu daha da kızdırır. Ücretsiz ikrama personel kendi başına söz vermez; yetkisi yoksa amirine danışır.","iliskili":["os-5-078","os-5-080","os-5-081"],"kontrol":null,"gorsel":"f3h-meyve-sepeti"},{"id":"os-5-080","konu":"5.1.5","terim":"El yazısıyla özür notu","ingilizce":"Handwritten apology note","tanim":"Tesis müdürünün aksaklık yaşayan konuğa kendi el yazısıyla yazdığı ve çoğu zaman özel bir ikramla birlikte odasına bırakılan özür mesajıdır.","ornek":"Konuk akşam odasına döner; masada bir tabak meyve ve müdürün imzasını taşıyan, “Bugün yaşadığınız aksaklık için içtenlikle özür dilerim” yazılı kısa bir not bulur.","sektor":"Konuğa özel olduğunu hissettirir: hazır basılmış bir kart herkese gider, el yazısı yalnız ona yazılmıştır. Müdürün imzası, sorunun en üst düzeyde ciddiye alındığını gösterir.","iliskili":["os-5-062","os-5-078","os-5-079"],"kontrol":null,"cizim":"kalp-empati"},{"id":"os-5-081","konu":"5.1.5","terim":"Gelecek konaklama için indirim kuponu","ingilizce":"Discount voucher for a future stay","tanim":"Aksaklık yaşayan konuğa bir sonraki gelişinde kullanması için verilen indirim hakkıdır.","ornek":"Çıkış sırasında ön büro müdürü “Sizi yeniden ağırlayıp bu kez kusursuz bir konaklama sunmak isteriz efendim” diyerek konuğa içinde indirim kuponu olan bir zarf uzatır.","sektor":"Konukla ilişkiyi yaşanan krizle sınırlı bırakmaz, geleceğe taşır: konuğa “Bize bir şans daha verin” demenin yoludur. Bu tür bir telafiye personel değil, yönetim karar verir.","iliskili":["os-5-078","os-5-082","os-5-048"],"kontrol":null,"cizim":"bilet"},{"id":"os-5-082","konu":"5.1.5","terim":"Oda yükseltme (upgrade)","ingilizce":"Room upgrade","tanim":"Konuğa ek ücret alınmadan, rezervasyon yaptırdığından daha üst kategoride bir oda verilmesidir.","ornek":"Standart odasının kliması onarılamayan aile, aynı gece ek ücret ödemeden bir üst kategorideki süit odaya taşınır.","sektor":"Telafi jesti olarak o gün verilebileceği gibi, bir sonraki konaklama için güvence olarak da sunulabilir. Sektörde İngilizce adıyla “upgrade” denir; müsaitliğe bağlıdır ve kararı yetkili kişi verir.","iliskili":["os-5-078","os-5-081"],"kontrol":null},{"id":"os-5-083","konu":"5.1.5","terim":"İzolasyon tekniği","ingilizce":"Moving the guest to a quiet area (isolation technique)","tanim":"Şikâyeti olan konuğun, diğer konukların duymayacağı sakin bir bölüme alınması ve mümkünse oturtulmasıdır.","ornek":"Saat 12.00, kalabalık lobi: görevli yüksek sesle konuşan konuğa “Sizi rahatça dinleyebilmem için şöyle oturalım mı efendim?” diyerek onu sakin köşedeki koltuğa davet eder.","sektor":"Öğretmen notundaki yedi adımlı müdahalenin ilk adımıdır. İki yararı vardır: oturan konuk ayaktakine göre daha sakin olur ve diğer konuklar tartışmaya tanık olmaz. Amaç konuğu saklamak değil, onu rahatça dinlemektir.","iliskili":["os-5-035","os-5-060"],"kontrol":null,"kitapDisi":true},{"id":"os-5-084","konu":"5.1.5","terim":"Takip","ingilizce":"Follow-up","tanim":"Sorun için yapılan işlemin sonucunu kontrol etme ve konuğa yeniden ulaşıp memnun kalıp kalmadığını sorma adımıdır.","ornek":"Teknik servis odadan çıktıktan yarım saat sonra görevli konuğu arar ve “Klimanız şimdi istediğiniz gibi çalışıyor mu efendim?” diye sorar.","sektor":"Sorun çözme bu adımla kapanır. Geri aranan konuk önemsendiğini hisseder; aranmayan konuk, çözülmemiş sorunu çıkışta ya da internette anlatır.","iliskili":["os-5-065","os-5-064","os-5-052"],"kontrol":null,"kitapDisi":true,"cizim":"zil-hizmet"},{"id":"os-5-085","konu":"5.1.5","terim":"Amire aktarma","ingilizce":"Escalation","tanim":"Personelin yetkisini aşan bir sorunu, aldığı notlarla birlikte amirine iletmesi ve konuğa bu konuda bilgi vermesidir.","ornek":"Konuk ücret iadesi ister; stajyer “Bu konuda karar verme yetkim yok efendim; ön büro müdürümüze hemen haber veriyorum, kendisi sizinle görüşecek” der.","sektor":"Aktarmak, sorumluluğu atmak değildir: konuğu başından savmazsın, amirin gelene kadar yanında kalırsın. Notların sayesinde konuk her şeyi baştan anlatmak zorunda kalmaz.","iliskili":["os-5-063","os-5-065","os-5-078"],"kontrol":null,"kitapDisi":true,"cizim":"lider"},{"id":"os-5-100","konu":"5.2","terim":"Olağan dışı durum","ingilizce":"Emergency (extraordinary situation)","tanim":"Tesisin günlük akışını bozan, konuğun ya da personelin can veya mal güvenliğini tehdit eden ve hızlı müdahale gerektiren olaydır.","ornek":"Gece 02.30, üçüncü kat koridoru: duman dedektörü ötmeye başlar. Önceki gün öğle sıcağında havuz başında bir konuk fenalaşmıştı; ikisi de olağan dışı durumdur.","sektor":"Bu olayların hiç yaşanmayacağını kimse garanti edemez. İyi tesis, olay çıktığında kimin ne yapacağını önceden bilen tesistir. Sıra hiç değişmez: önce can güvenliği, sonra eşya ve bina.","iliskili":["os-5-101","os-5-117","os-5-165"],"kontrol":null,"gorsel":"f3h-ambulans-112"},{"id":"os-5-101","konu":"5.2.1","terim":"Konuk güvenliği","ingilizce":"Guest safety and security","tanim":"Konuğun tesise girdiği andan ayrıldığı ana kadar kendini bedence, ruhça ve dijital olarak tehditlerden uzak hissetmesini sağlayan önlemlerin bütünüdür.","ornek":"Akşam 22.00: konuk kartıyla odasına girer, kapıyı kapatır ve rahatça uyur. Koridordaki kamerayı, tavandaki dedektörü ve bilgilerinin şifreli tutulduğunu hiç düşünmez.","sektor":"Güvenlik yalnız kapıyı kilitlemek değildir; konuğun sağlığını, özel hayatını ve kişisel bilgilerini de kapsar. İyi kurulmuş güvenlik çoğu zaman fark edilmez, ama tesisin itibarı ona bağlıdır: kendini güvende hissetmeyen konuk bir daha gelmez.","iliskili":["os-5-102","os-5-111","os-5-114"],"kontrol":null,"gorsel":"h5a-guvenlik-kamerasi"},{"id":"os-5-116","konu":"5.2.1","terim":"Gıda güvenliği önlemi (HACCP)","ingilizce":"Food safety control (HACCP)","tanim":"Konuğun tabağına giden yemeğin sağlığı tehdit edebilecek noktalarının önceden belirlenip denetlendiği, tesisin konuk güvenliği önlemlerinden biri olan HACCP sistemine uygun çalışmaktır.","ornek":"Sabah 06.30, mutfak: aşçı soğuk odanın sıcaklığını ölçüp çizelgeye yazar; sıcaklık uygun değilse şefine haber verir ve içindeki ürün şefin kararı olmadan servise çıkmaz.","sektor":"Sistemin kendisi 1. ünitede ayrıca işlenir; burada konu, güvenliğin yalnız kilit ve kamera değil, akıllı kilitten gıda hijyenine kadar uzanmasıdır. Konuğun tabağındaki yemeğin güvenli olması da güvenliğin parçasıdır: toplu bir gıda zehirlenmesi, tesis için ciddi bir olağan dışı durumdur.","iliskili":["os-5-101","os-5-132"],"kontrol":null,"gorsel":"h5a-gida-termometresi"},{"id":"os-5-102","konu":"5.2.1","terim":"Fiziksel ve elektronik güvenlik","ingilizce":"Physical and electronic security","tanim":"Kapı, kilit, duvar gibi engellerle tehlikeyi dışarıda tutan ve bu engelleri kart, kamera, alarm gibi teknolojilerle izleyip kaydeden önlemlerdir.","ornek":"Personel kapısı kilitlidir (fiziksel); kapı yalnız tanımlı kartla açılır ve her açılış kayda geçer (elektronik).","sektor":"Konuk güvenliği için alınan tedbirler üç başlıkta toplanır: fiziksel ve elektronik güvenlik, acil durum ve yaşam güvenliği, veri ve bilgi güvenliği. İlki engel koyar ve izler; teknoloji ne kadar iyi olursa olsun onu kullanan personel eğitimsizse işe yaramaz.","iliskili":["os-5-103","os-5-105","os-5-107"],"kontrol":null},{"id":"os-5-103","konu":"5.2.1","terim":"Giriş kontrol sistemi","ingilizce":"Access control system","tanim":"Kapıların metal anahtar yerine yetki tanımlanmış kartlarla açıldığı ve her açma denemesinin kaydedildiği güvenlik düzenidir.","ornek":"Saat 14.00, giriş işlemi: konuğa verilen akıllı kart yalnız kendi odasını açar; çıkış yaptığı gün kart kendiliğinden geçersiz olur.","sektor":"Sistemin temeli yetkilendirme ve kayıttır: hangi kartın, hangi saatte, hangi kapıyı açtığı ya da açamadığı raporlanabilir. Bir olay yaşandığında “Orada kim vardı?” sorusunun cevabı tahminle değil, bu kayıtla verilir.","iliskili":["os-5-104","os-5-102","os-5-138"],"kontrol":null,"cizim":"kurallar-liste"},{"id":"os-5-104","konu":"5.2.1","terim":"Pas anahtarı güvenliği","ingilizce":"Staff key control","tanim":"Personelin yalnız kendi görev alanındaki kapıları açabilmesi için yetki seviyesine göre tanımlanan anahtar ya da kartın, giriş kontrol sisteminde kayıtlı ve denetimli kullanılmasıdır.","ornek":"Sabah 08.00, kat ofisi: dördüncü katın görevlisi kartını imzayla teslim alır. Kart o kattaki odaları açar, başka katlardakini açmaz.","sektor":"Bu kart sana duyulan güvendir: başkasına verilmez, kat arabasının üstünde bırakılmaz, vardiya sonunda teslim edilir; kaybolursa hemen amire bildirilir. Kartla açılan her kapı senin adına kayda geçer. Pas anahtarının (master key) kendisi 3. ünitede ayrıca işlenir; burada konu, anahtar ya da kartın yetkisinin sınırlandırılması ve denetlenmesidir.","iliskili":["os-5-103","os-5-137"],"kontrol":null,"kitapDisi":true,"gorsel":"f3h-kartli-kapi-kilidi"},{"id":"os-5-105","konu":"5.2.1","terim":"CCTV","ingilizce":"Closed-circuit television (CCTV)","tanim":"Kameralardan gelen görüntünün yalnız tesisin kendi ekranlarında izlendiği ve kaydedildiği, yirmi dört saat çalışan kapalı devre kamera sistemidir.","ornek":"Saat 17.00: kaybolan bir sırt çantasının en son lobide mi, restoranda mı görüldüğü kamera kayıtlarından anlaşılır.","sektor":"Kameranın üç işi vardır: caydırır, anında izleme sağlar ve olaydan sonra kanıt olur. İzleme tesisin dış sınırından başlar; resepsiyon, asansör ve koridor gibi iç alanlara doğru sıklaşır. Kayıtları güvenlik birimi inceler; görüntüler merak için izlenmez, yetkisiz kişilerle paylaşılmaz.","iliskili":["os-5-106","os-5-102","os-5-138"],"kontrol":null,"gorsel":"sektor-guvenlik-kamerasi"},{"id":"os-5-106","konu":"5.2.1","terim":"Kör nokta","ingilizce":"Blind spot","tanim":"Kameranın ya da gözün doğrudan göremediği, koridor köşesi ve merdiven altı gibi yerdir.","ornek":"L biçimindeki koridorun köşesine asılan dışbükey ayna karşıdan geleni önceden gösterir; iki kamera da köşeyi iki yandan görecek biçimde yerleştirilir.","sektor":"Kör noktayı yok etmenin en etkili yolu kameraların görüş alanlarını birbirinin üstüne bindirmektir: birinin bittiği yerde öbürü başlar. Koridordaki ayna, iyi aydınlatma ve oda kapısındaki balık gözü mercekli gözetleme deliği de konuğun kendini güvende hissetmesi içindir.","iliskili":["os-5-105","os-5-102"],"kontrol":null,"gorsel":"os-kor-nokta"},{"id":"os-5-107","konu":"5.2.1","terim":"Entegre alarm sistemi","ingilizce":"Integrated alarm system","tanim":"Tesisin farklı yerlerindeki duyargaları (sensörleri) tek bir merkezî panele bağlayan ve sistemlerin birbirini kendiliğinden harekete geçirmesini sağlayan düzendir.","ornek":"Yangın alarmı devreye girdiği anda elektronik kilit sistemi acil çıkış kapılarını kendiliğinden açar; kimsenin anahtar aramasına gerek kalmaz.","sektor":"En büyük yararı zamandır: saniyelerin önemli olduğu anda sistemler insan eli değmeden birbiriyle haberleşir. Duman dedektörü, panik butonu ve hırsızlık alarmı aynı panele bağlıdır. Yetkisiz bir kapı ya da pencere açılışını algılayan hırsızlık alarmı alanı sirenle uyarır. Ders kitabına göre bu düzenin kalbi merkezî kontrol panelidir: tesisin farklı noktalarındaki duyargalar (sensörler) tek panelde toplanır. Hırsızlık alarmı sensörü kapı ya da pencereden yetkisiz giriş algıladığında sistem alanı yüksek sesli sirenle uyarır ve giriş çıkışları kilitler; duman dedektörü yangın başlangıcında, panik butonu ise personel ya da konuk tehlikedeyken devreye girer.","iliskili":["os-5-108","os-5-109","os-5-158"],"kontrol":null},{"id":"os-5-108","konu":"5.2.1","terim":"Duman dedektörü","ingilizce":"Smoke detector","tanim":"Havadaki dumanı algılayarak yangını başlangıç aşamasında haber veren duyargadır.","ornek":"Öğleden sonra 15.00: 214 numaralı odada prizde unutulan bir saç maşası örtüyü tutuşturur; dedektör dumanı algılar, resepsiyondaki panelde o odanın ışığı yanar.","sektor":"Dedektör merkezî sisteme bağlıdır: duman algılanınca sistem havalandırmayı kapatabilir, asansörleri zemin kata indirebilir ve itfaiyeye haber verebilir. Panelden gelen uyarı asla “Yine mi?” diye geçiştirilmez; her uyarı gerçekmiş gibi kontrol edilir.","iliskili":["os-5-107","os-5-152","os-5-162"],"kontrol":null,"gorsel":"os-duman-dedektoru"},{"id":"os-5-109","konu":"5.2.1","terim":"Panik butonu","ingilizce":"Panic button","tanim":"Tehlikede olan personelin ya da konuğun tek dokunuşla sessizce yardım çağırmasını sağlayan acil durum düğmesidir.","ornek":"Gece 01.00, resepsiyon: bankoya yumruğunu vuran saldırgan bir kişi karşısında görevli tartışmaya girmez, bankonun altındaki butona basar.","sektor":"Butona basılınca merkezî sistem en yakın güvenlik görevlisine yeri bildirir ve kameraları o noktaya çevirir. Buton, “Kendim hallederim” diye beklenecek bir araç değildir; tehlike sezildiği anda basılır.","iliskili":["os-5-107","os-5-110"],"kontrol":null,"gorsel":"t14zb-panik-butonu"},{"id":"os-5-110","konu":"5.2.1","terim":"Güvenlik görevlisi","ingilizce":"Security officer","tanim":"Tesisin, konukların ve personelin güvenliğini sağlamakla görevli, bu iş için eğitilmiş çalışandır.","ornek":"Gece 01.00, lobi: bağırıp eşyalara vuran bir kişi için resepsiyon görevlisi araya girmez, hemen güvenliği arar.","sektor":"Saldırgan kişi, kavga, hırsızlık şüphesi, sahipsiz paket: bunlarda diğer personel kendi başına müdahale etmez, güvenliğe haber verir. Herkes eğitimini aldığı işi yapar; stajyerin işi görmek, haber vermek ve konukları uzak tutmaktır.","iliskili":["os-5-109","os-5-145","os-5-151"],"kontrol":null,"cizim":"uyari"},{"id":"os-5-111","konu":"5.2.1","terim":"Acil durum ve yaşam güvenliği protokolü","ingilizce":"Emergency and life safety protocol","tanim":"Yangın, doğal afet ve sağlık sorunu gibi durumlarda kimin, ne zaman, neyi, nasıl yapacağını önceden belirleyen yazılı kurallar bütünüdür.","ornek":"Alarm çaldığında resepsiyon görevlisi kimi arayacağını, kat görevlisi hangi koridoru boşaltacağını düşünmez; ikisi de protokolde yazanı yapar.","sektor":"Protokol kargaşayı düzene çevirir. Her acil durum birbirinden farklıdır, ama hepsinde iki ortak amaç vardır: can güvenliğini sağlamak ve paniği yönetmek. Protokol kriz anında ilk kez okunmaz; önceden öğrenilir ve tatbikatla denenir.","iliskili":["os-5-112","os-5-113","os-5-117"],"kontrol":null},{"id":"os-5-112","konu":"5.2.1","terim":"Tahliye planı","ingilizce":"Evacuation plan","tanim":"Bulunulan yerden en yakın acil çıkışa giden yolu gösteren, konuk odalarında ve tesisin görünür yerlerinde asılı duran krokidir.","ornek":"Oda kapısının iç yüzündeki krokide “Buradasınız” noktası ve koridorun iki ucundaki acil çıkış merdivenleri okla gösterilir.","sektor":"Konuk binayı tanımaz; karanlıkta ya da dumanda yolu ona bu plan ve yönlendirme levhaları gösterir. Konuğa odasına kadar eşlik ederken en yakın acil çıkışı göstermek çok kısa sürer, gerektiğinde çok şey kazandırır.","iliskili":["os-5-113","os-5-120","os-5-111"],"kontrol":null},{"id":"os-5-113","konu":"5.2.2","terim":"Toplanma alanı","ingilizce":"Assembly point","tanim":"Tahliye edilen konukların ve personelin binadan uzakta bir araya geldiği, önceden belirlenmiş güvenli açık alandır.","ornek":"Yangın alarmında konuklar acil çıkış merdiveninden bahçenin girişindeki toplanma alanına yönlendirilir; sayım orada yapılır.","sektor":"Herkes aynı yerde toplanırsa eksik olan hemen anlaşılır ve ekiplere doğru bilgi verilir. Toplanma alanına gelen kişi izin verilmeden binaya dönmez; unutulan telefon ya da valiz için geri girilmez.","iliskili":["os-5-112","os-5-120","os-5-161"],"kontrol":null,"gorsel":"sektor-toplanma-noktasi"},{"id":"os-5-114","konu":"5.2.1","terim":"Veri ve bilgi güvenliği","ingilizce":"Data and information security","tanim":"Konuğun kimlik, pasaport ve kredi kartı gibi bilgilerinin yetkisiz kişilerin eline geçmesini önlemek için alınan teknik ve hukuki önlemlerdir.","ornek":"Saat 18.00, resepsiyon: telefondaki bir kişi “Konuğunuzun pasaport numarasını doğrulayacaktım, okur musunuz?” der; görevli numarayı söylemez, kimliği doğrulanmamış kişiyle bilgi paylaşılmadığını nazikçe belirtir ve amirine haber verir.","sektor":"Konuğun pasaport numarası, en az valizindeki eşya kadar değerlidir. Tesisler çok sayıda hassas bilgi tuttuğu için siber saldırıların hedefi olabilir. Bu yüzden bilgiler şifrelenerek saklanır; şifreli veri ele geçse bile anahtarı olmadan okunamaz. Tesisin kendi iş ağı ile konukların kullandığı Wi-Fi ağı da birbirinden ayrılır.","iliskili":["os-5-115","os-5-101"],"kontrol":null},{"id":"os-5-115","konu":"5.2.1","terim":"Konuk bilgilerinin gizliliği (KVKK)","ingilizce":"Guest data privacy (KVKK)","tanim":"Konuğun kimlik, pasaport ve kart gibi kişisel bilgilerinin nasıl toplanacağını, saklanacağını ve kimlerle paylaşılabileceğini belirleyen Kişisel Verilerin Korunması Kanunu’na uygun davranmaktır.","ornek":"Stajyer, giriş yapan tanınmış bir konuğun kimlik fotokopisinin fotoğrafını çekip arkadaşına gönderemez; bu hem güveni hem yasayı çiğnemektir.","sektor":"Veri güvenliği yalnız yasal bir zorunluluk değil, konukla kurulan güven ilişkisinin temelidir. Konuğun adı, oda numarası, kimlik ve kart bilgileri yalnız iş için ve yalnız yetkili kişilerce kullanılır.","iliskili":["os-5-114"],"kontrol":null,"gorsel":"f3h-evrak-imha"},{"id":"os-5-180","konu":"5.2.1","terim":"Hırsızlık alarmı","ingilizce":"Burglar alarm","tanim":"Kapı ya da pencereden yetkisiz giriş olduğunu algılayıp yüksek sesli sirenle uyaran ve giriş çıkışları kilitleyen alarmdır.","ornek":"Gece 03.00, kapalı spa girişindeki kapı zorlanır; hırsızlık alarmı sirenle öter, güvenlik ekranda hangi kapının zorlandığını görür.","sektor":"Entegre alarm sisteminde duman dedektörü ve panik butonuyla aynı merkezî panele bağlıdır. Tesis kapalıyken boş alanları ve personel girişlerini korur.","iliskili":["os-5-107","os-5-108","os-5-109"],"kontrol":null,"cizim":"uyari"},{"id":"os-5-181","konu":"5.2.1","terim":"Gaz dedektörü","ingilizce":"Gas detector","tanim":"Ortamdaki yanıcı gaz kaçağını algılayıp uyarı veren duyargadır.","ornek":"Gece 02.00, mutfakta gaz dedektörü öter; görevli alandan çıkar, güvenliğe ve teknik servise haber verir, alana kimseyi sokmaz.","sektor":"Mutfak, kazan dairesi ve çamaşırhane gibi gaz kullanılan yerlerde bulunur. Alarmı çalan dedektör “yanlış alarm” diye geçiştirilmez; gaz kokusu varsa yangın ve patlama riski vardır.","iliskili":["os-5-107","os-5-108","os-5-111"],"kontrol":null,"cizim":"uyari"},{"id":"os-5-117","konu":"5.2.2","terim":"Olağan dışı durum prosedürü","ingilizce":"Emergency procedure","tanim":"Kriz anında paniği önlemek için personelin sırayla uygulayacağı, önceden belirlenmiş ve denenmiş adımlar dizisidir.","ornek":"Çamaşırhanede su borusu patlar: gören görevli teknik servise haber verir, vana kapatılır, alandaki kişiler uzaklaştırılır, olay rapora yazılır.","sektor":"Amaç, personelin o anda kendi kafasına göre karar vermek zorunda kalmamasıdır. İyi kurulmuş bir prosedür dört aşamadan oluşur: tespit ve ihbar, acil müdahale, tahliye ve koruma, kayıt ve analiz. Kriz anında doğaçlama yapılmaz, prosedür uygulanır.","iliskili":["os-5-118","os-5-119","os-5-120","os-5-121"],"kontrol":null,"gorsel":"h5a-acil-cikis-levhasi"},{"id":"os-5-118","konu":"5.2.2","terim":"Tespit ve ihbar","ingilizce":"Detection and reporting","tanim":"Olağan dışı durumun fark edilip güvenlik ve resepsiyon gibi ilgili birimlere hemen bildirilmesi, prosedürün ilk aşamasıdır.","ornek":"Saat 16.40: kat görevlisi koridorda yanık kokusu alır; kaynağını aramaya girişmeden telsizle kat şefine “Üçüncü kat, 310’un önü, yanık kokusu var” der.","sektor":"Bu aşamanın amacı hızlı bilgi akışıdır. İyi bir ihbar kısa ve açıktır: ne oldu, nerede, kim haber veriyor. “Belki bir şey değildir” diye beklemek, küçük olayı büyük olaya çevirir.","iliskili":["os-5-117","os-5-119"],"kontrol":null,"gorsel":"h5a-duman-dedektoru"},{"id":"os-5-119","konu":"5.2.2","terim":"Acil müdahale","ingilizce":"Immediate response","tanim":"Olayın yayılmasını önlemek için vanayı kapatmak, elektriği kesmek gibi ilk fiziksel adımların atıldığı aşamadır.","ornek":"Banyosunu su basan odada teknik servis görevlisi önce ana vanayı kapatır; suyun alt kata inmesi böylece durur.","sektor":"Amaç zararı en az düzeyde tutmaktır. Bu adımları o işin eğitimini almış kişi atar: vanayı ve şalteri teknik servis, ilk yardımı ilk yardımcı, söndürmeyi eğitimli personel yapar. Diğerleri haber verir, ekiplerin yolunu açık tutar ve konukları uzak tutar.","iliskili":["os-5-118","os-5-120"],"kontrol":null},{"id":"os-5-120","konu":"5.2.2","terim":"Tahliye ve koruma","ingilizce":"Evacuation and protection","tanim":"Konukların ve personelin tehlikeli bölgeden çıkarılıp toplanma alanı gibi güvenli yerlere yönlendirildiği aşamadır.","ornek":"Genel alarmda kat görevlisi koridorda sakin ve yüksek sesle “Lütfen bu taraftan, merdivenden inelim” diyerek yön gösterir.","sektor":"Amaç can güvenliğidir. Personel konuğa sakin bir sesle ve kısa cümlelerle yol gösterir; yaşlı, çocuklu ve hareket kısıtlılığı olan konuklara öncelik verilir. Tahliyede asansör kullanılmaz, eşya almak için geri dönülmez.","iliskili":["os-5-113","os-5-162","os-5-121"],"kontrol":null},{"id":"os-5-121","konu":"5.2.2","terim":"Kayıt ve analiz","ingilizce":"Recording and analysis","tanim":"Kriz sona erdikten sonra olayın bütün ayrıntılarıyla yazıya geçirildiği ve nedenlerinin araştırıldığı son aşamadır.","ornek":"Aynı merdiven basamağında bir ayda ikinci düşme kaydı görülünce yönetim o basamağa kaydırmaz bant yaptırır.","sektor":"Amaç ilerideki riskleri önlemektir. Yazılmayan olay unutulur, unutulan olay tekrar eder. Raporlar suçlu aramak için değil, prosedürü gözden geçirip iyileştirmek için okunur.","iliskili":["os-5-122","os-5-117"],"kontrol":null,"cizim":"grafik"},{"id":"os-5-122","konu":"5.2.2","terim":"Olay tespit formu","ingilizce":"Incident report form","tanim":"Olağan dışı bir olayın tarihini, saatini, yerini, olaya karışanları, olayın özetini, yapılan müdahaleyi ve tanıkları kayda geçiren belgedir.","ornek":"Saat 14.20’de lobi girişinde düşen konuk için form doldurulur: oda numarası, olayın nasıl geliştiği, revirin arandığı, tanıkların adı ve düzenleyenlerin imzası yazılır.","sektor":"Sektörde olay raporu ya da tutanak da denir. Olay sıcakken, görülen ve yapılan şeyler yorum katılmadan yazılır: “Konuk dikkatsizdi” değil, “Konuk ıslak zeminde kaydı.” Bu belge ileride sigorta ve hukuk sürecinde kanıt olur; işletmeyi de çalışanı da haksız suçlamadan korur.","iliskili":["os-5-121","os-5-128","os-5-130"],"kontrol":null,"cizim":"belge-form"},{"id":"os-5-123","konu":"5.2.2","terim":"Kaza","ingilizce":"Accident","tanim":"İstenmeden ve aniden gerçekleşen, yaralanmaya ya da zarara yol açan olaydır.","ornek":"Sabah 08.15, kahvaltı salonu: bir konuğun elindeki bardak kırılır ve parmağı kesilir; garson hemen şefine ve tesisin sağlık ekibine haber verir.","sektor":"Tesis günün her saati hareketli olduğu için hem konuk hem personel için kaza riski taşır. Kazalar dört grupta toplanır: düşme ve kaymalar, yanık ve yaralanmalar, kimyasal kazalar, elektrik kazaları. Bu türleri bilmek, yönetimin riski önceden görmesini ve önlem almasını sağlar.","iliskili":["os-5-124","os-5-125","os-5-126","os-5-127"],"kontrol":null,"cizim":"ilk-yardim"},{"id":"os-5-124","konu":"5.2.2","terim":"Düşme ve kayma","ingilizce":"Slips, trips and falls","tanim":"Kişinin ıslak zeminde kayarak ya da merdivende dengesini kaybederek yere düşmesiyle oluşan kaza türüdür.","ornek":"Saat 09.15: yeni silinmiş lobi zemininde bir konuk kayar ve dizinin üstüne düşer; yakındaki bellboy yanına gider, onu kaldırmaya çalışmadan revire haber verir.","sektor":"En çok havuz çevresinde, banyolarda ve lobide görülür. Islak zemine uyarı levhası koymak küçük bir iştir, koymamak büyük bir ihmaldir. Düşen konuk kalkamıyorsa ya da ağrısı şiddetliyse yerinden oynatılmaz; yanında kalınır, sakinleştirilir, sağlık ekibi çağrılır.","iliskili":["os-5-123","os-5-130","os-5-131"],"kontrol":null,"gorsel":"h5a-kaygan-zemin"},{"id":"os-5-125","konu":"5.2.2","terim":"Yanık ve yaralanma","ingilizce":"Burns and injuries","tanim":"Sıcak su, sıcak yüzey ya da kesici aletle temas sonucunda oluşan kaza türüdür.","ornek":"Öğle servisi, saat 12.40: açık büfedeki sıcak çorba kazanının kapağını kaldıran konuğun eline buhar çarpar; garson hemen şefine ve revire haber verir.","sektor":"En çok mutfakta, banyoda ve restoranda görülür. Müdahaleyi tesisin sağlık ekibi ya da sertifikalı ilk yardımcı yapar; personel kulaktan dolma yöntemler denemez, yaraya kendi bildiği bir şey sürmez. Senin işin yardımı hızla çağırmak ve konuğun yanında kalmaktır.","iliskili":["os-5-123","os-5-131"],"kontrol":null},{"id":"os-5-126","konu":"5.2.2","terim":"Kimyasal kaza","ingilizce":"Chemical accident","tanim":"Temizlik maddelerinin solunması ya da cilde ve göze temas etmesi sonucunda oluşan kaza türüdür.","ornek":"Saat 10.30, kat ofisi: etiketsiz bir şişedeki sıvıyı başka bir temizlik maddesiyle karıştıran görevlinin gözleri yanmaya, nefesi daralmaya başlar.","sektor":"En çok kat hizmetleri ofislerinde ve depolarda görülür. Temizlik maddeleri birbirine karıştırılmaz, etiketsiz kaba konmaz, eldiven gibi koruyucu donanım kullanılır. Kaza olursa kişi temiz havaya çıkarılır, amire ve sağlık ekibine haber verilir; ürünün etiketi sağlık ekibine gösterilir.","iliskili":["os-5-123","os-5-131"],"kontrol":null},{"id":"os-5-127","konu":"5.2.2","terim":"Elektrik kazası","ingilizce":"Electrical accident","tanim":"Arızalı cihaz ya da açıkta kalmış kablo yüzünden vücuttan elektrik akımı geçmesiyle oluşan kaza türüdür.","ornek":"Kat görevlisi 508’de su ısıtıcısının kablosunun soyulduğunu görür; cihazı kullanmaz, fişini çekmeye de kalkışmaz, odayı listesinde işaretleyip teknik servise bildirir.","sektor":"En çok konuk odalarında ve teknik servis alanlarında görülür. Akım kesilmeden kazaya uğrayan kişiye dokunulmaz, yoksa yardım eden de çarpılır: önce elektrik şalterden kestirilir, 112 aranır. Bozuk priz ya da açık kablo gören personel bunu hemen bildirir.","iliskili":["os-5-123","os-5-133"],"kontrol":null,"cizim":"ilk-yardim"},{"id":"os-5-128","konu":"5.2.2","terim":"Kaza anında izlenen adımlar","ingilizce":"Accident response steps","tanim":"Anlık müdahale, olay yerini koruma, tutanak hazırlama ve bildirim ile takipten oluşan, kaza sonrasında sırayla uygulanan dört aşamalı akıştır.","ornek":"Havuz başında düşen konuk için önce revir çağrılır ve alan güvenli hâle getirilir; zemin silinmeden fotoğrafı çekilir; tutanak yazılır; yönetime bildirilir.","sektor":"Adımlar bir zincirin halkaları gibidir: biri koparsa hem insan sağlığı hem işletmenin hukuki güvenliği tehlikeye girer. Tutanağa olayın saati, yeri, tanıkların anlattıkları ve yapılan müdahale yazılır. Son adımda yönetime, sigorta şirketine ve gerekiyorsa kolluk kuvvetlerine haber verilir.","iliskili":["os-5-129","os-5-122","os-5-130"],"kontrol":null},{"id":"os-5-129","konu":"5.2.2","terim":"Olay yerini koruma","ingilizce":"Preserving the scene","tanim":"Kazanın ya da suçun gerçekleştiği yerin, nedenini gösteren izler bozulmasın diye temizlenmeden ve değiştirilmeden bırakılmasıdır.","ornek":"Lobide konuğun kaydığı su birikintisi hemen silinmez; önce fotoğrafı çekilir, çevresine kimse girmesin diye uyarı konur.","sektor":"İyi niyetle “Hemen toplayayım” demek kanıtı yok eder. Kazada neden (örn. ıslak zemin), hırsızlıkta ve vandalizmde ise parmak izi ile deliller korunur. Olay yerine kimin girip çıkacağına yetkililer karar verir.","iliskili":["os-5-128","os-5-138","os-5-151"],"kontrol":null},{"id":"os-5-130","konu":"5.2.2","terim":"Kusur","ingilizce":"Fault (negligence)","tanim":"Bir kazanın, alınması gereken önlemin alınmaması ya da dikkatsiz davranılması yüzünden gerçekleşmiş olması durumudur.","ornek":"Kırık bir merdiven basamağı günlerdir onarılmamışsa ve konuk orada düşerse kusur işletmededir.","sektor":"Kazanın hukuki açıdan en kritik kavramıdır. Kaza işletmenin ihmalinden doğmuşsa (onarılmayan basamak, levhasız ıslak zemin) işletme tazminat ve ceza davasıyla karşılaşabilir. Bütün önlemler alınmışsa ve kaza konuğun ağır kusuruyla olmuşsa işletmenin sorumluluğu azalır ya da kalkar. Senin koyduğun uyarı levhası bu yüzden önemlidir.","iliskili":["os-5-124","os-5-122","os-5-128"],"kontrol":null,"cizim":"uyari"},{"id":"os-5-131","konu":"5.2.2","terim":"Tesis sağlık ekibi","ingilizce":"In-house medical team","tanim":"Tesisin revirinde görev yapan doktor ve hemşire ile sertifikalı ilk yardımcılardan oluşan, sağlık sorununda ilk çağrılan ekiptir.","ornek":"Saat 13.10: restoranda fenalaşan konuk için garson reviri arar; doktor gelene kadar konuğun yanından ayrılmaz ve çevresini boşaltır.","sektor":"Kural açıktır: ilk yardımı yalnız bu eğitimi almış kişi yapar; bilmeden yapılan müdahale zarar verebilir. Personel teşhis koymaz, kendi kararıyla ilaç vermez. Sağlık ekibine en hızlı biçimde ulaşılır, amire haber verilir ve onların talimatıyla hareket edilir; hayati tehlike varsa aynı anda 112 de aranır.","iliskili":["os-5-132","os-5-133","os-5-134"],"kontrol":null},{"id":"os-5-132","konu":"5.2.2","terim":"Hastalık, zehirlenme ve alerji durumları","ingilizce":"Guest illness, poisoning and allergic reactions","tanim":"Konaklama sırasında konuğun hastalanması, zehirlenmesi ya da alerjik tepki göstermesi durumudur.","ornek":"Akşam 20.15, restoran: tabağındaki yemeği yedikten kısa süre sonra bir konuğun yüzü kızarır, “Nefes alamıyorum” der. Garson beklemeden şefine seslenir; 112 ve revir aranır.","sektor":"Kendini iyi hissetmediğini söyleyen konuğa şikâyeti sorulur, adı ve oda numarası not alınır, sağlık ekibine en hızlı biçimde ulaşılır ve onların talimatıyla hareket edilir. Nefes darlığı ve yaygın kızarıklık gibi ani alerji belirtilerinde beklenmez. Konuk yalnız bırakılmaz; durumu başka konuklarla konuşulmaz.","iliskili":["os-5-131","os-5-133","os-5-134"],"kontrol":null,"gorsel":"f3h-ilkyardim-dolabi"},{"id":"os-5-133","konu":"5.2.2","terim":"112 Acil Çağrı Merkezi","ingilizce":"Emergency call centre (112)","tanim":"Türkiye’de ambulans, itfaiye, polis ve jandarma gibi acil yardım ekiplerine tek numaradan ulaşılan çağrı merkezidir.","ornek":"Arayan görevli sakin bir sesle ne olduğunu, tesisin adını ve adresini, konuğun durumunu söyler; sorulanları yanıtlar ve 112 görevlisi kapatmadan telefonu kapatmaz.","sektor":"112’yi aramak için izin beklenmez; hayatı tehdit eden bir durum görüldüğünde hemen aranır ve aynı anda yöneticiye haber verilir. Ambulansı kapıda bir personelin karşılayıp en kısa yoldan konuğun yanına götürmesi dakikalar kazandırır.","iliskili":["os-5-134","os-5-131","os-5-139"],"kontrol":null,"gorsel":"t13d-ambulans-112"},{"id":"os-5-134","konu":"5.2.2","terim":"Acil belirtiler","ingilizce":"Emergency warning signs","tanim":"Bir kişide görüldüğünde vakit kaybetmeden 112’nin aranmasını ve yöneticiye haber verilmesini gerektiren sağlık işaretleridir.","ornek":"Saat 11.00, lobi: koltukta oturan konuk göğsünü tutuyor, sol kolunun uyuştuğunu söylüyor. Resepsiyon görevlisi beklemeden 112’yi arar, arkadaşı nöbetçi müdüre haber verir.","sektor":"Şunlardan biri bile yeterlidir: bayılma ya da kendinden geçmek üzere olma, göğüste baskı ve ağrıyla birlikte kolda uyuşma, nefes almakta zorlanma, karında dayanılmaz ağrı ve baskı, kusmada kan görülmesi, sözcükleri karıştırma ya da peltek konuşma, kırık ya da çatlak şüphesi uyandıran ciddi yaralanma.","iliskili":["os-5-133","os-5-132","os-5-131"],"kontrol":null,"gorsel":"h5a-nabiz-oksimetre"},{"id":"os-5-135","konu":"5.2.2","terim":"Konuk vefatı","ingilizce":"Guest death","tanim":"Bir konuğun konaklaması sırasında doğal ya da doğal olmayan bir nedenle tesiste hayatını kaybetmesidir.","ornek":"Sabah 10.00: kat görevlisi kapısını çaldığı odadan yanıt alamaz, kapıyı açınca konuğun hareketsiz yattığını görür. Odadaki hiçbir şeye dokunmadan çıkar ve hemen amirine haber verir; amir 112’yi ve sağlık ekibini arar.","sektor":"Hareketsiz bulunan konuğun öldüğüne personel karar veremez, çünkü kişi hayatta olabilir: hemen amire haber verilir, 112 ve sağlık ekibi çağrılır; durumu sağlık ekibi belirler. Olay diğer konuklara duyurulmaz, yalnız yönetime bildirilir; oda eşyasına dokunulmaz, girişler durdurulur ve kolluk kuvvetlerine haber verilir. Bu işlerin tamamı yönetimin ve yetkililerin işidir; stajyer odaya tek başına girmez. Cenaze, yetkililerin izniyle ve konukların görmeyeceği biçimde servis asansörüyle çıkarılır. Olayı kimin, ne zaman fark ettiği tutanağa yazılır.","iliskili":["os-5-129","os-5-139","os-5-122"],"kontrol":null,"cizim":"uyari"},{"id":"os-5-136","konu":"5.2.2","terim":"Aşırı alkol almış konuk","ingilizce":"Intoxicated guest","tanim":"Fazla alkol aldığı için kendine ya da çevresine zarar verebilecek duruma gelen konuktur.","ornek":"Gece 23.30, lobi barı: bir konuk yüksek sesle konuşuyor, ayakta zor duruyor; barmen servisi keser ve nöbetçi müdüre haber verir.","sektor":"Üç amaç vardır: konuğun sağlığını korumak, diğer konukların rahatsız olmasını önlemek ve işletmenin yasal sorumluluğunu yerine getirmek. İş servisi kesmekle bitmez; konuğun odasına güvenle ulaşması sağlanır, gerekirse sağlık yardımı çağrılır; konuk bayılacak gibiyse ya da bilinci bulanıksa beklenmez, 112 aranır. Konukla tartışılmaz, konuk utandırılmaz. Sonrasında saati, konuğun durumunu ve yapılan yardımı yazan tutanak tutulur.","iliskili":["os-5-110","os-5-133","os-5-122"],"kontrol":null,"cizim":"uyari"},{"id":"os-5-137","konu":"5.2.2","terim":"Hırsızlık","ingilizce":"Theft","tanim":"Başkasına ait bir eşyanın, sahibinin haberi ve izni olmadan alınmasıdır.","ornek":"Saat 19.00: akşam yemeğinden dönen konuk, odasındaki kasada bıraktığı saatin yerinde olmadığını söyleyerek resepsiyonu arar.","sektor":"Tesiste hırsızlığı üç grup yapabilir: personel, konuklar ya da tesisle ilgisi olmayan yabancılar. Bu olaylar işletmenin hem yasal sorumluluğunu hem güvenilirliğini sınar. Kimse peşinen suçlanmaz; olay, önceden belirlenmiş adımlarla ve yetkililerce yürütülür.","iliskili":["os-5-138","os-5-139","os-5-140"],"kontrol":null},{"id":"os-5-138","konu":"5.2.2","terim":"Hırsızlık olayında izlenen adımlar","ingilizce":"Theft response procedure","tanim":"Alanı korumak, ihbar ve kayıt, tutanak hazırlama ve inceleme aşamalarından oluşan, hırsızlık bildirimi alındığında uygulanan sıradır.","ornek":"Konuk kasasından pasaportunun çalındığını söyler: oda kapatılır, güvenlik müdürü ve yönetim aranır, kaybolan eşyanın listesi çıkarılır, kart ve kamera kayıtları incelenir.","sektor":"Önce olay yeri kapatılır ve içeri kimse alınmaz; böylece delil ve parmak izi bozulmaz. Güvenlik müdürüne ve yönetime haber verilir, ardından kolluk kuvvetleri çağrılır. Mağdurun anlattıkları ve kaybolan eşyanın listesi tutanağa yazılır, tanıklar belirlenir. Son aşamada kamera kayıtları ile personel giriş çıkış raporları incelenir; bu incelemeyi stajyer değil, yetkililer yapar.","iliskili":["os-5-137","os-5-129","os-5-105","os-5-103"],"kontrol":null},{"id":"os-5-139","konu":"5.2.2","terim":"Kolluk kuvvetleri","ingilizce":"Law enforcement (police and gendarmerie)","tanim":"Kamu düzenini ve güvenliğini sağlamakla görevli olan polis ve jandarma gibi resmî güvenlik birimleridir.","ornek":"Otoparkta iki konuk arasındaki tartışma yumruklaşmaya dönünce güvenlik amiri 112’yi arayarak polis ister.","sektor":"Hırsızlık, darp, vefat, bomba ihbarı ve büyük zarar veren vandalizm gibi olaylarda devreye girer. Tesisin güvenlik görevlisi ile kolluk aynı şey değildir: soruşturmayı kolluk yürütür, tesis ona bilgi, kayıt ve rehberlik sağlar. Kolluğa çoğunlukla yönetim haber verir; can tehlikesi varsa beklenmez.","iliskili":["os-5-133","os-5-138","os-5-145"],"kontrol":null,"gorsel":"h5a-jandarma-araci"},{"id":"os-5-140","konu":"5.2.2","terim":"Konuk eşyasının kaybolması","ingilizce":"Loss of guest property","tanim":"Konuğun bir eşyasını unutması, yanlış yere koyması ya da eşyasının çalındığını düşünerek tesise bildirmesi durumudur.","ornek":"Saat 16.00, resepsiyon: bir konuk “Telefonum yok, odada bırakmıştım, biri almış olmalı” der. Görevli sakin kalır, en son nerede gördüğünü ve telefonun rengini sorar.","sektor":"Kaybolan her eşya çalınmış değildir; çoğu unutulmuş ya da yanlış yere konmuştur. Görevli konuğu dinler, eşyanın tarifini ve en son görüldüğü yeri not alır, bulunan eşya kayıtlarına baktırır, amirine ve güvenliğe haber verir. Kimseyi suçlamaz, “Bulunur” diye söz de vermez.","iliskili":["os-5-141","os-5-137","os-5-142"],"kontrol":null,"cizim":"etik-terazi"},{"id":"os-5-141","konu":"5.2.2","terim":"Kayıp ve bulunmuş eşya sistemi","ingilizce":"Lost and found","tanim":"Konukların unuttuğu ya da kaybettiği eşyaların kaydedilip sahibine teslim edilene kadar güvenle saklandığı düzendir.","ornek":"Saat 12.30: çıkış yapan konuğun banyoda unuttuğu saati gören kat görevlisi saate dokunmadan kat şefine haber verir; saat kayıp eşya defterine yazılır.","sektor":"Sektörde “lost and found” denir; eşya sahibine teslim edilene kadar genellikle kat hizmetleri sorumludur. Eşya deftere kaydedilerek izlenir; kayda geçen eşya ortada kalmadığı için kaybolması ya da çalınması önlenir. Çıkış yapmış konuğa rezervasyon ve iletişim bilgilerinden telefon, e-posta ya da postayla haber verilir.","iliskili":["os-5-140","os-5-142"],"kontrol":null,"gorsel":"sektor-kayip-esya"},{"id":"os-5-142","konu":"5.2.2","terim":"Muhafaza süresi","ingilizce":"Holding period","tanim":"Bulunan eşyanın, sahibi gelip alana kadar işletmede saklandığı süredir.","ornek":"Kasım ayında bulunan bir gözlük etiketlenip dolaba konur; konuğa ulaşılamazsa süre dolana kadar orada bekler.","sektor":"Bu süre genellikle 90 gündür. Süre içinde eşya alınmazsa ya da konuğa ulaşılamazsa işletmenin kayıp eşya prosedürüne ve yürürlükteki mevzuata göre işlem yapılır. Bulunan eşya, süre ne kadar uzarsa uzasın, bulanın cebine girmez.","iliskili":["os-5-141","os-5-140"],"kontrol":null},{"id":"os-5-143","konu":"5.2.2","terim":"Tesis eşyasının alınması","ingilizce":"Removal of hotel property","tanim":"Konuğun ayrılırken bornoz, havlu gibi tesise ait bir eşyayı yanında götürmesidir.","ornek":"Saat 11.40: konuk çıkış yaparken kat görevlisi odayı hızlıca kontrol eder; bornozlardan biri yoktur, durumu ön büroya bildirir.","sektor":"Konuklar bornozu ya da havluyu bazen hatıra sanarak alır. Profesyonel işletme konuğu suçlamaz, durumu nazikçe çözer; nasıl çözüleceğine ön büro yetkilisi karar verir. Kat görevlisinin işi eksiği fark edip bildirmektir; konuğun valizine bakmak ya da hesap sormak değildir.","iliskili":["os-5-144","os-5-137"],"kontrol":null},{"id":"os-5-144","konu":"5.2.2","terim":"Sarf malzemesi ve demirbaş","ingilizce":"Consumables and fixed assets","tanim":"Kullanıldıkça biten ve konuğa bırakılan ürünler ile tesisin kalıcı malı olan eşyalar arasındaki ayrımdır.","ornek":"Banyodaki küçük şampuan ve sabun sarf malzemesidir, konuk alabilir; bornoz, havlu ve saç kurutma makinesi demirbaştır, odada kalır.","sektor":"Konuğun tesis eşyasını götürmesi bu ayrıma göre yönetilir. Sarf malzemesinin alınması olağandır; demirbaş eksikse ön büro bilgilendirilir. Ayrımı bilen personel, şampuanı alan konuğa da bornozu alan konuğa da doğru tepkiyi verir.","iliskili":["os-5-143"],"kontrol":null},{"id":"os-5-145","konu":"5.2.2","terim":"Konuklar arası çatışma","ingilizce":"Dispute between guests","tanim":"İki ya da daha fazla konuk arasında çıkan ve tesisin havasını bir anda bozabilen tartışma ya da kavgadır.","ornek":"Saat 15.00, havuz başı: iki aile şezlong yüzünden bağrışmaya başlar. Görevli yaklaşmadan sakin bir sesle “Lütfen sakinleşelim” der, şefine ve güvenliğe haber verir; güvenlik görevlileri aileleri ayrı masalara alır.","sektor":"Personel taraf tutmaz; bir hakem gibi ortamı güvenli kılar ve gerginliği düşürür. İlk adım tarafları birbirinden ayırmak ve mümkünse diğer konukların görmeyeceği sakin bir yere almaktır; bunu güvenlik görevlileri yapar. Diğer personelin en güçlü aracı sakin ses tonu ve beden dilidir. Öncelik personelin kendi can güvenliğidir: güvenlik görevlileri dışında kimse taraflara fiziksel olarak yaklaşmaz. Olay darba ya da suça dönerse, tesise ciddi zarar verilirse polise ya da jandarmaya haber vermek yasal zorunluluktur.","iliskili":["os-5-110","os-5-139","os-5-164"],"kontrol":null,"cizim":"uyari"},{"id":"os-5-151","konu":"5.2.2","terim":"Vandalizm","ingilizce":"Vandalism","tanim":"Tesise ya da konuklara ait bir mala, araca ya da eşyaya bilerek ve isteyerek zarar verme eylemidir.","ornek":"Gece 00.40: bir konuğun odasındaki televizyonu kırdığı duyulur; kat görevlisi kapıyı çalmaz, güvenliğe ve nöbetçi müdüre haber verir.","sektor":"Bahçedeki heykele zarar vermek, otoparktaki araçları çizmek de vandalizmdir. Müdahale zinciri şöyledir: personel tek başına değil, güvenlik eşliğinde müdahale eder; zarar gören yere dokunulmaz, fotoğrafı çekilir; güvenlik müdürüne haber verilir; tutanak tutulur; zarar büyükse ya da suç oluşturuyorsa polis çağrılır. Zararı konuk verdiyse masraf faturasına eklenir, yabancı biri verdiyse yasal yola başvurulur.","iliskili":["os-5-110","os-5-129","os-5-139"],"kontrol":null,"gorsel":"h5a-grafiti-vitrin"},{"id":"os-5-146","konu":"5.2.2","terim":"Şüpheli paket","ingilizce":"Suspicious package","tanim":"Sahibi belli olmayan ve alışılmışın dışında görünen çanta, koli ya da kutudur.","ornek":"Saat 17.20: kat görevlisi asansörün yanında, bir saattir aynı yerde duran sahipsiz bir sırt çantası fark eder; dokunmaz, uzaklaşır ve güvenliğe haber verir.","sektor":"Şu işaretler paketi şüpheli yapar: sahibi ortada yoktur ve paket uzun süredir aynı yerdedir; üzerinde gereğinden fazla bant, kablo ya da tel vardır; içinden saat tıkırtısına benzer ses gelir; üzerinde yağ lekesi, renk değişimi ya da ağır bir koku vardır. En önemli kural: kahramanlık yapma, uzmanına bırak.","iliskili":["os-5-147","os-5-148","os-5-110"],"kontrol":null},{"id":"os-5-147","konu":"5.2.2","terim":"Şüpheli paket prosedürü","ingilizce":"Suspicious package procedure","tanim":"Sahipsiz ve şüpheli bir paket görüldüğünde dokunmadan haber vermekle başlayıp alanın uzman ekibe devredilmesi ve tutanakla biten adımlar dizisidir.","ornek":"Koridordaki sahipsiz çanta için güvenlik çevreyi boşaltır ve şeritle kapatır; yönetim 112’yi arar; ekip gelene kadar bir görevli girişte bekleyip kimseyi yaklaştırmaz.","sektor":"Sıra şöyledir: paketi bulan dokunmadan en yakın güvenlik birimine ya da yönetime haber verir; güvenlik çevreyi boşaltır (ders kitabına göre paketin çevresinde en az 100 metrelik alan); girişler şeritle kapatılır ve nöbetçi bırakılır; 112 aranarak açık ve ayrıntılı bilgi verilir; paketin yakınında telsiz ve cep telefonu kullanılmaz, aramalar paketten uzakta yapılır; bomba imha ekibi gelince alan ona bırakılır; olay tutanağa yazılır.","iliskili":["os-5-146","os-5-149","os-5-150"],"kontrol":null,"gorsel":"h5a-guvenlik-kontrol-noktasi"},{"id":"os-5-148","konu":"5.2.2","terim":"Bomba tehdidi","ingilizce":"Bomb threat","tanim":"Tesiste bomba bulunduğunun çoğunlukla telefonla ya da yazılı bir notla bildirilmesidir.","ornek":"Gece 03.10: santrale düşen aramada yabancı bir ses otelde bomba olduğunu söyler; görevli telefonu kapatmaz, sakin kalır ve dinler.","sektor":"Paniğe yol açabilecek en ciddi kriz anlarından biridir. Temel kural: tehdit asılsız olabilir, ama aksi kanıtlanana kadar gerçekmiş gibi davranılır. Karar stajyerin ya da tek bir görevlinin değildir; yönetime haber verilir, kolluk kuvvetlerinin talimatı izlenir.","iliskili":["os-5-149","os-5-146","os-5-150"],"kontrol":null,"gorsel":"t13a-terminal-sahipsiz-bavul"},{"id":"os-5-149","konu":"5.2.2","terim":"Bomba ihbarı prosedürü","ingilizce":"Bomb threat procedure","tanim":"İhbarı dinleyip not almakla başlayan; haber verme, arama, tahliye kararı, ekipleri karşılama ve kayıt aşamalarıyla süren adımlar dizisidir.","ornek":"Görevli arayanı konuştururken önündeki kâğıda “BOMBA İHBARI, MÜDÜRÜ ARA” yazıp yanındaki arkadaşına gösterir; arkadaşı nöbetçi müdürü arar.","sektor":"Telefon kapatılmaz, arayan konuşturulur; söyledikleri, ses tonu ve arkadan gelen sesler not alınır. Bu sırada bir arkadaşa işaretle ya da notla durumu yönetime bildirmesi söylenir. Yönetimin talimatıyla her personel kendi alanında “buraya ait olmayan” bir nesne var mı diye bakar, bulduğuna dokunmaz. Tehlike büyükse konuklar sakin bir dille, şüpheli bölgeden uzak bir toplanma alanına yönlendirilir. Gelen ekibe binanın planı verilir. Arayanın cinsiyeti, aksanı, aramanın saati ve kullandığı sözcükler tutanağa yazılır.","iliskili":["os-5-148","os-5-147","os-5-113"],"kontrol":null},{"id":"os-5-150","konu":"5.2.2","terim":"“Tüm alan temiz” onayı","ingilizce":"All clear","tanim":"Uzman ekiplerin aramayı ya da müdahaleyi bitirip tehlikenin kalmadığını tesise bildirmesidir.","ornek":"Bomba imha ekibi binayı aradıktan sonra “Alan temiz” der; toplanma alanında bekleyen konuklar ancak o zaman içeri alınır.","sektor":"Sektörde “all clear” denir. Bu onay gelmeden tesis normal işleyişine dönmez. “Bir şey yokmuş” kararını personel değil, olay yerini devralan uzman ekip verir.","iliskili":["os-5-147","os-5-149"],"kontrol":null,"kitapDisi":true},{"id":"os-5-152","konu":"5.2.2","terim":"Yangın","ingilizce":"Fire","tanim":"Kontrolden çıkan, cana ve mala zarar veren yanma olayıdır.","ornek":"Öğleden sonra 15.00: ikinci kat koridorunda genel alarm çalıyor; kat görevlisi konukları sakin bir sesle acil çıkış merdivenine yönlendiriyor.","sektor":"Yangın müdahale planı yalnız tüplerin yerini bilmek değildir; dumanın ilk fark edildiği andan bütün konukların toplanma alanına ulaştığı ana kadar her adımı kapsar. Üç bölümü vardır: R.A.C.E. protokolü, tahliye ve lojistik, ekipman ve işaretleme. Hiç kimse kendi canını tehlikeye atmaz: dumanın yoğun olduğu yere girilmez, içeride kalan varsa itfaiyeye bildirilir.","iliskili":["os-5-153","os-5-158","os-5-159"],"kontrol":null,"gorsel":"ocak-yangini"},{"id":"os-5-153","konu":"5.2.2","terim":"R.A.C.E. protokolü","ingilizce":"R.A.C.E. protocol","tanim":"Yangın gibi acil durumlarda personelin paniğe kapılmadan belirli bir öncelik sırasıyla hareket etmesini sağlayan, yaygın kullanılan dört adımlı hatırlatma kuralıdır.","ornek":"Çamaşırhanede duman gören görevli sırayı aklından geçirir: önce yanındakileri dumandan uzaklaştır, sonra butona bas, çıkarken kapıyı kapat; söndürmek eğitimli ekibin işidir.","sektor":"Harfler dört İngilizce sözcüğün baş harfidir: Rescue (kurtar), Alarm (alarm ver), Confine (sınırla), Extinguish / Evacuate (söndür ya da tahliye et). Sıra önemlidir: önce insan, sonra haber, sonra yayılmayı durdurma, en son alev.","iliskili":["os-5-154","os-5-155","os-5-156","os-5-157"],"kontrol":null,"gorsel":"h5a-yangin-sondurucu"},{"id":"os-5-154","konu":"5.2.2","terim":"Kurtar (R)","ingilizce":"Rescue","tanim":"Yangın alanındaki herkesin, öncelikle hareket kabiliyeti kısıtlı olanların, hemen güvenli bir bölgeye alınması, R.A.C.E. protokolünün ilk adımıdır.","ornek":"Koridorda duman fark eden görevli önce tekerlekli sandalyedeki konuğu ve yanındaki çocuğu dumandan uzağa, merdiven sahanlığına yönlendirir.","sektor":"İlk adımın insan olması rastlantı değildir: eşya ve bina yerine konur, can konmaz. Kurtarmak kahramanlık demek değildir; yakınındaki kişiyi tehlikeden uzaklaştırırsın, dumanın içine girmezsin. Kendi başına çıkaramadığın kişiyi unutmazsın, ama kendini de tehlikeye atmazsın: onu en güvenli noktaya alır, yerini hemen yönetime ve itfaiyeye bildirirsin.","iliskili":["os-5-153","os-5-155"],"kontrol":null,"gorsel":"h5a-sedye"},{"id":"os-5-155","konu":"5.2.2","terim":"Alarm ver (A)","ingilizce":"Alarm","tanim":"En yakın yangın ihbar butonuna basılarak ya da santral aranarak yangının tam yerinin bildirilmesi, R.A.C.E. protokolünün ikinci adımıdır.","ornek":"Görevli butona basar ve santrale “Dördüncü kat, 412’nin karşısındaki kat ofisi, duman var” der.","sektor":"Yangını tek başına söndürmeye çalışıp haber vermeyen kişi, herkesi tehlikeye atar. İhbarda yer açıkça söylenir: kat, oda numarası, bölüm. “Bir yerde duman var” demek ekibi aramaya mahkûm eder.","iliskili":["os-5-153","os-5-158","os-5-156"],"kontrol":null},{"id":"os-5-156","konu":"5.2.2","terim":"Sınırla (C)","ingilizce":"Confine","tanim":"Yangının ve dumanın yayılmasını yavaşlatmak için kapı ve pencerelerin kapatılması, R.A.C.E. protokolünün üçüncü adımıdır.","ornek":"Odadan çıkan son kişi kapıyı arkasından çeker; kapalı kapı dumanın koridora dolmasını geciktirir.","sektor":"Kapılar kapatılır, ama asla kilitlenmez: kilitli kapı hem içeride kalanı hapseder hem itfaiyeyi geciktirir. Kapalı bir kapı, kaçış yolunun daha uzun süre dumansız kalmasına yardım eder.","iliskili":["os-5-153","os-5-157"],"kontrol":null,"cizim":"pasaport"},{"id":"os-5-157","konu":"5.2.2","terim":"Söndür ya da tahliye et (E)","ingilizce":"Extinguish or evacuate","tanim":"Yangın küçükse söndürmeye çalışılması, kontrol edilemeyecek durumdaysa binanın hemen boşaltılması, R.A.C.E. protokolünün son adımıdır.","ornek":"Çöp kovasında tutuşan kâğıdı eğitimli görevli söndürücüyle söndürür; perdeyi sarmış bir alevde ise kimse oyalanmaz, kat boşaltılır.","sektor":"Söndürme en sondadır ve herkesin işi değildir: yalnız eğitimini almış kişi, alarm verildikten sonra, yangın küçükse ve çıkış yolu arkasında açıksa dener. Kuşku varsa tahliye seçilir; yanlış karar verip çıkmak, yanlış karar verip kalmaktan iyidir.","iliskili":["os-5-153","os-5-159","os-5-120"],"kontrol":null},{"id":"os-5-158","konu":"5.2.2","terim":"Yangın ihbar butonu","ingilizce":"Fire alarm call point","tanim":"Yangını gören kişinin basarak alarm sistemini elle çalıştırdığı, koridor ve çıkışların yakınına yerleştirilen kırmızı düğmedir.","ornek":"Stajın ilk günü kat şefi sana koridoru gezdirirken sorar: “Bu kata en yakın buton nerede?” Sen de merdiven kapısının yanındaki kırmızı kutuyu gösterirsin.","sektor":"Dedektör dumanı kendiliğinden algılar; buton ise insanın gördüğü yangını haber vermesi içindir. Çalıştığın katta en yakın butonun, söndürücünün ve acil çıkışın yerini ilk gün öğrenmek mesleğin gereğidir.","iliskili":["os-5-155","os-5-107","os-5-159"],"kontrol":null,"gorsel":"g1-yangin-ihbar-butonu"},{"id":"os-5-159","konu":"5.2.2","terim":"Yangın söndürücü","ingilizce":"Fire extinguisher","tanim":"Küçük bir yangını büyümeden söndürmek için kullanılan, içinde söndürücü madde bulunan basınçlı tüptür.","ornek":"Kat ofisindeki çöp kovasında tutuşan kâğıtlar, kapının yanında asılı söndürücüyle birkaç saniyede söndürülür.","sektor":"Söndürücülerin türleri vardır; hangisinin kullanılacağı yanan maddeye göre değişir ve üzerindeki etikette yazar. Elektrikli cihaz yangınına ve yanan yağa su dökülmez. Söndürücüyü yalnız eğitimini almış kişi kullanır; eğitim almadıysan işin haber vermek ve konukları uzaklaştırmaktır.","iliskili":["os-5-157","os-5-160","os-5-152"],"kontrol":null,"gorsel":"t14c-sondurucu-sirasi"},{"id":"os-5-160","konu":"5.2.2","terim":"Yangın dolabı","ingilizce":"Fire hose cabinet","tanim":"İçinde yangın hortumu ve çoğu zaman bir söndürücü bulunan, koridor duvarlarına yerleştirilmiş kırmızı dolaptır.","ornek":"Kat arabasını koridora bırakan görevli, arabanın yangın dolabının önünü kapatmadığına dikkat eder.","sektor":"Dolabın önü hiçbir zaman kapatılmaz: önüne araba, saksı ya da valiz konmaz. İçindeki hortumu itfaiye ve tesisin eğitimli ekibi kullanır. Önü kapalı bir dolap, yangın anında yok hükmündedir.","iliskili":["os-5-159","os-5-152"],"kontrol":null,"kitapDisi":true,"gorsel":"yangin-dolabi"},{"id":"os-5-161","konu":"5.2.2","terim":"Konuk sayımı","ingilizce":"Roll call","tanim":"Tahliyeden sonra toplanma alanında konukların ve personelin listeyle karşılaştırılarak eksik kişi olup olmadığının belirlenmesidir.","ornek":"Toplanma alanında ön büro görevlisi elindeki konuk listesinden oda oda yoklama yapar; 305’teki konuğun görünmediğini itfaiye amirine bildirir.","sektor":"Yangın planının “tahliye ve lojistik” bölümü güvenli çıkış yollarını, toplanma alanlarını ve bu sayımı kapsar. Eksik kişiyi aramak için binaya personel girmez; bilgi, olay yerindeki ekibe verilir. Güncel konuk listesine bina dışından da ulaşılabilmesi bu yüzden önemlidir.","iliskili":["os-5-113","os-5-120","os-5-174"],"kontrol":null},{"id":"os-5-162","konu":"5.2.2","terim":"Acil durumda asansör kuralı","ingilizce":"Do not use lifts in an emergency","tanim":"Yangın ve deprem gibi durumlarda asansöre binilmemesi, bunun yerine acil çıkış merdivenlerinin kullanılması ilkesidir.","ornek":"Alarm çalarken asansörün önünde bekleyen konuklara görevli sakin bir sesle “Lütfen merdiveni kullanalım, bu taraftan” der ve yolu gösterir.","sektor":"Asansör elektrik kesilince katlar arasında kalabilir, kuyusuna duman dolabilir. Entegre alarm sistemi yangında asansörleri zemin kata indirir. Konuk alışkanlıkla asansöre yönelir; onu merdivene yönlendirmek personelin görevidir.","iliskili":["os-5-120","os-5-108","os-5-112"],"kontrol":null,"gorsel":"t14zb-asansor-levhasi"},{"id":"os-5-163","konu":"5.2.2","terim":"Kriz iletişimi","ingilizce":"Crisis communication","tanim":"Olağan dışı bir durumda konuklara ne söyleneceğini, kimin söyleyeceğini ve nasıl söyleneceğini belirleyen iletişim biçimidir.","ornek":"Lobide toplanan konuklara görevli şöyle der: “Lütfen sakin olun, güvenliğiniz önceliğimizdir. Yeni bilgi ulaştığında sizinle paylaşacağız.”","sektor":"Üç ayağı vardır: ses ve beden dili (göz teması, sakin ton, açık duruş), kurumsal bilgi (yalnız doğrulanmış bilgi paylaşılır) ve yönlendirme (acil çıkış, merdiven, toplanma alanı). Bilmediğin şeyi tahmin etmezsin: “Henüz doğrulanmamış bilgi hakkında açıklama yapamam” demek dürüst ve doğru cevaptır.","iliskili":["os-5-164","os-5-120","os-5-175"],"kontrol":null,"cizim":"uyari"},{"id":"os-5-164","konu":"5.2.2","terim":"Panik yönetimi","ingilizce":"Panic management","tanim":"Korkuya kapılan insanların birbirini ezmeden, doğru yöne ve düzen içinde hareket etmesini sağlamak için yapılanların bütünüdür.","ornek":"Alarmda merdivene koşan bir konuğa görevli göz teması kurarak kısa cümlelerle seslenir: “Buradayım. Yürüyerek inelim. Çıkış bu tarafta.”","sektor":"Panik bulaşıcıdır, sakinlik de. Konuk zor anda personelin yüzüne bakar: sen koşarsan o da koşar. Panikteki konuğa uzun açıklama yapılmaz; kısa, anlaşılır cümleler ve açık bir yön yeterlidir.","iliskili":["os-5-163","os-5-111","os-5-145"],"kontrol":null},{"id":"os-5-189","konu":"5.2.2","terim":"Alerjen uyarı etiketi","ingilizce":"Allergen label","tanim":"Yiyeceğin içindeki süt, yumurta, fıstık gibi alerji yapabilecek maddeleri gösteren ve konuğun yemekten önce okuyabileceği uyarıdır.","ornek":"Öğle 12.30, açık büfe: her yemeğin önündeki kartta “fıstık içerir” gibi bir uyarı bulunur; alerjisi olan konuk kartı okuyup tabağını seçer.","sektor":"Etiketi okumadan yemek yiyen konuk ani alerjik tepki verebilir (nefes darlığı, kızarıklık); bu durumda beklenmez, tesis revirine ve 112’ye haber verilir. Konuğun önceden bildirdiği alerji ise “gıda alerjisi bildirimi” kartında anlatılır.","iliskili":["os-5-132","os-5-133"],"kontrol":null,"cizim":"mikrop"},{"id":"os-5-165","konu":"5.2.3","terim":"Mücbir sebep","ingilizce":"Force majeure","tanim":"İşletmenin önceden önleyemediği, kontrol edemediği ve yükümlülüklerini yerine getirmesini engelleyen olağan dışı durumdur.","ornek":"Yoğun kar yüzünden havalimanı kapanır: tesis ne kadar iyi çalışırsa çalışsın uçağı kaldıramaz; konuklar valizleriyle lobide kalır.","sektor":"Sektörde Fransızca kökenli “force majeure” sözü kullanılır; ders kitabında “force major” diye geçer. Dört grupta toplanır: doğal afetler, toplumsal olaylar, teknolojik aksaklıklar ve ekonomik olumsuzluklar. Her olumsuzluk mücbir sebep sayılmaz; bir olayın bu kapsamda değerlendirilip değerlendirilmeyeceğine rezervasyon sözleşmesi ve mevzuata göre yönetim karar verir. Olayı durduramazsın, ama konuğa nasıl davranacağın senin elindedir.","iliskili":["os-5-166","os-5-168","os-5-169","os-5-170"],"kontrol":null,"gorsel":"g1-firtina-dalgalari"},{"id":"os-5-166","konu":"5.2.3","terim":"Doğal afet","ingilizce":"Natural disaster","tanim":"Deprem, sel, kasırga ve orman yangını gibi doğa olaylarının can ve mal kaybına yol açmasıdır.","ornek":"Ağustos ayında yakındaki ormanda çıkan yangın yüzünden kaymakamlık bölgenin boşaltılmasına karar verir; tesis konuklarını gösterilen güvenli bölgeye götürür.","sektor":"Afette sıra bellidir: can güvenliği önce gelir, panik önlenir, konuklar toplanma alanına yönlendirilir, ilgili birimlere haber verilir, yapılanlar kayda geçirilir. Büyük afetlerde tesisler, mülki idarenin kararıyla geçici barınma ya da lojistik merkezi olarak da kullanılabilir.","iliskili":["os-5-165","os-5-167","os-5-178"],"kontrol":null,"gorsel":"g1-orman-yangini-duman"},{"id":"os-5-167","konu":"5.2.3","terim":"Çök-Kapan-Tutun","ingilizce":"Drop, cover and hold on","tanim":"Deprem sırasında sağlam bir eşyanın yanına çökülmesini, baş ve ensenin korunmasını ve sarsıntı bitene kadar tutunulmasını öğreten korunma hareketidir.","ornek":"Gece 04.00, sarsıntı başlar: resepsiyon görevlisi kapıya koşmaz, bankonun yanına çöker, başını korur; sarsıntı durunca konukları merdivenden toplanma alanına yönlendirir.","sektor":"AFAD’ın önerdiği harekettir. Sarsıntı sürerken koşulmaz; merdivene, balkona ve asansöre yönelinmez, cam ve pencerelerden uzak durulur. Bina, sarsıntı durduktan sonra sakin biçimde ve merdivenden boşaltılır. Bunu bilen personel konuğa da aynı sakinlikle yol gösterir.","iliskili":["os-5-166","os-5-173","os-5-162"],"kontrol":null,"kitapDisi":true,"cizim":"uyari"},{"id":"os-5-168","konu":"5.2.3","terim":"Toplumsal olaylar","ingilizce":"Social events (war, strikes, epidemics)","tanim":"Savaş hâli, grev ve büyük çaplı salgın hastalık gibi toplumun genelini etkileyen ve işletmenin önleyemediği olağan dışı durumlardır.","ornek":"Hava yolu çalışanlarının grevi yüzünden otuz kişilik bir grubun dönüş uçuşu iptal olur; grup tesiste iki gece daha kalmak zorunda kalır.","sektor":"Tek bir görevlinin çözebileceği olaylar değildir. Salgında tesis kendi başına karar vermez; sağlık kurumlarının koyduğu kurallara uyar ve konukları doğru bilgilendirir. Konuğun bunda kusuru yoktur: sabırlı, açık ve yardımsever bir tutum beklenir.","iliskili":["os-5-165","os-5-171"],"kontrol":null},{"id":"os-5-169","konu":"5.2.3","terim":"Teknolojik aksaklık","ingilizce":"Technological failure","tanim":"Ulaşımın aksaması ya da iletişim ağının çökmesi gibi, teknik sistemlerin çalışmamasından doğan ve işletmenin gideremediği durumdur.","ornek":"Bölgede telefon ve internet ağı saatlerce çöker; konuklar yakınlarına ulaşamaz, resepsiyon uçuş bilgilerini öğrenmek için havalimanına bir personel gönderir.","sektor":"Konuklara ne olduğu ve ne zaman düzelmesinin beklendiği, bilindiği kadarıyla açıkça söylenir. Bilgi verilmeyen konuk en kötüsünü düşünür. Tesisin kendi arızası (örn. bozuk klima) mücbir sebep değildir; bölgenin tamamını etkileyen çöküş mücbir sebeptir.","iliskili":["os-5-165","os-5-163"],"kontrol":null,"cizim":"uyari"},{"id":"os-5-170","konu":"5.2.3","terim":"Ekonomik olumsuzluk","ingilizce":"Economic downturn","tanim":"Büyük finansal dalgalanma ve ekonomik kriz gibi, ekonominin geneline yayılan ve işletmenin tek başına önleyemediği durumdur.","ornek":"Ülkeyi saran ani bir finansal kriz yüzünden bankalar günlerce işlem yapamaz; yabancı bir konuğun kartı çalışmaz, parasına ulaşamaz ve resepsiyonda hesabı nasıl ödeyeceğini endişeyle sorar.","sektor":"Tek bir şirketin iflası ya da bir acentenin hatası ekonomik kriz sayılmaz; ekonominin geneline yayılan olay beklenir. Konuğun bunda bir kusuru yoktur. Önce onu sakinleştirmek, sonra yönetimin kararını doğru biçimde aktarmak gerekir. Görevli kendi başına ödeme ya da konaklama sözü vermez; “Yönetimimiz konuyla ilgileniyor, sizi bilgilendireceğiz” der.","iliskili":["os-5-165","os-5-179"],"kontrol":null},{"id":"os-5-179","konu":"5.2.3","terim":"Geri ödeme ve alternatif tarih","ingilizce":"Refund and rebooking","tanim":"Mücbir sebep yüzünden konaklayamayan konuğa ödediği ücretin geri verilmesi ya da konaklamasının başka bir tarihe taşınmasıdır.","ornek":"Sel yüzünden gelemeyen konuğa rezervasyon bölümü kendiliğinden yazar: “Dilerseniz ücretinizi iade edelim, dilerseniz sizi başka bir tarihte ağırlayalım.”","sektor":"Uluslararası uygulamada yaygın bir çözümdür ve işletmenin imajını güçlendirir. Koşullar rezervasyon sözleşmesine ve işletmenin politikasına göre belirlenir; kararı yönetim verir. Tesisin sorumluluğu genel olarak kendi hizmetiyle sınırlıdır: konuğun uçak bileti gibi dış seyahat masraflarını karşılamak zorunda değildir.","iliskili":["os-5-165","os-5-170"],"kontrol":null,"kitapDisi":true,"cizim":"para-kart"},{"id":"os-5-171","konu":"5.2.3","terim":"Kriz yönetimi","ingilizce":"Crisis management","tanim":"Bir krizi önlemek, kriz çıktığında hızlı ve düzenli davranmak ve olumsuz sonuçlarını hafifletmek için yapılan çalışmaların bütünüdür.","ornek":"Sel uyarısından sonra tesis yönetimi kaymakamlıkla görüşür, kaymakamlığın talimatına göre giriş katındaki konukları üst katlara alır ve restoranı gece boyunca açık tutar.","sektor":"İletişimin hızlanması kriz yönetimini kolaylaştırmıştır: uyarı daha erken gelir, kurumlar daha çabuk haberleşir. Birçok ülkede afet ve kriz riskini azaltmak ve bu durumları yönetmek için devletin kurduğu ulusal bir koordinasyon kurulu bulunur. Tesis krizi tek başına değil, bu yapıyla birlikte yönetir.","iliskili":["os-5-172","os-5-173","os-5-165"],"kontrol":null,"cizim":"uyari"},{"id":"os-5-172","konu":"5.2.3","terim":"Mülki idare","ingilizce":"Civil administration (governor's office)","tanim":"İlde valilik, ilçede kaymakamlık olarak örgütlenen ve devleti o yerde temsil eden yönetim birimidir.","ornek":"Orman yangınında kaymakamlık bölgenin boşaltılmasına karar verir; tesis müdürü bu karara uyar ve tahliyeyi başlatır.","sektor":"Mücbir sebep durumunda tesis kendi başına hareket etmez; mülki idareyle ve AFAD, Emniyet, Sağlık Müdürlüğü gibi kamu birimleriyle ortak çalışır. Tahliye, sokağa çıkma ya da barınma kararları buradan gelir. Ama dikkat: tesisin içindeki bir olayda ilk adım resmî talimat beklemek değil, prosedürü uygulamaktır.","iliskili":["os-5-173","os-5-175","os-5-171"],"kontrol":null,"gorsel":"g1-izmir-hukumet-konagi"},{"id":"os-5-173","konu":"5.2.3","terim":"AFAD","ingilizce":"Disaster and Emergency Management Authority (AFAD)","tanim":"Afet ve Acil Durum Yönetimi Başkanlığının kısaltması olup Türkiye’de afetlere hazırlık, müdahale ve iyileştirme çalışmalarını yürüten kamu kurumudur.","ornek":"Deprem sonrasında AFAD ekipleri bölgeye gelir; tesis yönetimi konuk listesini ve binanın durumunu ekiplere bildirir.","sektor":"Mücbir sebep durumunda tesisin birlikte çalıştığı kamu birimlerinden biridir. Afet anında bilgi resmî kaynaktan alınır; sosyal medyada dolaşan doğrulanmamış haber konuklara aktarılmaz.","iliskili":["os-5-172","os-5-167","os-5-171"],"kontrol":null,"cizim":"uyari"},{"id":"os-5-174","konu":"5.2.3","terim":"Veri paylaşımı","ingilizce":"Sharing guest data with the authorities","tanim":"Mücbir sebep durumunda tesiste kalan konukların güncel listesinin, sağlık durumlarının ve özel ihtiyaçlarının mülki idareye hemen iletilmesidir.","ornek":"Sel gecesi ön büro müdürü kaymakamlığa listeyi gönderir: tesiste kaç konuk var, kaçı yaşlı, hangi odada tekerlekli sandalye kullanan konuk kalıyor.","sektor":"Mücbir sebepte konuklara yönelik akışın ilk adımıdır. Yardım ekipleri kimin nerede olduğunu ve kimin özel yardıma ihtiyacı olduğunu bu listeden öğrenir. Bilgi yalnız resmî makama ve yalnız bu amaçla verilir; listeyi yönetim paylaşır, stajyer değil.","iliskili":["os-5-175","os-5-172","os-5-161"],"kontrol":null,"cizim":"sosyal-medya"},{"id":"os-5-175","konu":"5.2.3","terim":"Resmî talimatların duyurulması","ingilizce":"Announcing official instructions","tanim":"Mülki idarenin yayımladığı tahliye, sokağa çıkmama ya da barınma talimatlarının anons sistemi ve personel aracılığıyla konuklara aynı anda aktarılmasıdır.","ornek":"Saat 21.00: valiliğin “Sabaha kadar dışarı çıkılmaması” kararı anonsla Türkçe ve İngilizce duyurulur; kat görevlileri de odaları tek tek dolaşır.","sektor":"Talimat herkese aynı anda ve aynı sözlerle ulaşmalıdır; yoksa söylenti başlar. Personel talimata kendi yorumunu eklemez, yumuşatmaz, abartmaz. Yabancı konuklar için duyuru anlayacakları dilde yinelenir.","iliskili":["os-5-172","os-5-163","os-5-176"],"kontrol":null,"gorsel":"g1-huni-hoparlorler"},{"id":"os-5-176","konu":"5.2.3","terim":"Lojistik ve iaşe koordinasyonu","ingilizce":"Logistics and provisions coordination","tanim":"Kriz sırasında gıda, temiz su ve tıbbi malzemenin, mülki idarenin yardım ağlarıyla birlikte çalışılarak konuklara ulaştırılmasıdır.","ornek":"Yollar kapandığı için tedarikçi gelemez; yönetim kaymakamlıktan içme suyu ister, mutfak eldeki malzemeyle herkese yetecek sade bir menü çıkarır.","sektor":"İaşe, yiyecek ve içecek sağlamak demektir. Mücbir sebepte ilk iş konukların temel ihtiyaçlarını gidermektir: su, yemek, ısınma, ilaç. Lüks hizmet bekleyebilir, temel ihtiyaç bekleyemez; ilaç kullanan ve bebekli konuklar önce sorulur.","iliskili":["os-5-175","os-5-178","os-5-171"],"kontrol":null},{"id":"os-5-177","konu":"5.2.3","terim":"Uluslararası iletişim","ingilizce":"Consular notification","tanim":"Mücbir sebep durumunda yabancı uyruklu konuklar için mülki idare aracılığıyla ilgili konsolosluk ve büyükelçiliklere durum bildirimi yapılmasıdır.","ornek":"Deprem sonrasında tesiste kalan Alman ve Hollandalı konukların listesi valiliğe verilir; valilik ilgili konsolosluklara bilgi ulaştırır.","sektor":"Yabancı konuk, dilini bilmediği bir ülkede kriz yaşıyordur; ülkesinin temsilciliğinin haberdar olduğunu duymak onu rahatlatır. Ailesi de konsolosluk üzerinden haber alabilir. Bildirim yönetimin işidir; personel konuğa konsolosluğunun bilgilendirildiğini söyleyebilir.","iliskili":["os-5-174","os-5-172"],"kontrol":null},{"id":"os-5-178","konu":"5.2.3","terim":"Geçici barınma ve sevk","ingilizce":"Temporary shelter and relocation","tanim":"Tesisin riskli duruma gelmesi hâlinde konukların, mülki idarenin gösterdiği güvenli bölgelere personel rehberliğinde götürülmesidir.","ornek":"Yangın tesise yaklaşınca konuklar personel eşliğinde otobüslerle ilçe merkezindeki spor salonuna taşınır; her otobüste liste tutan bir görevli bulunur.","sektor":"Mücbir sebep akışının son adımıdır. Nereye gidileceğine tesis değil, mülki idare karar verir. Personel konukları yalnız göndermez, eşlik eder: araca kim bindi, kim nerede indi, liste üzerinden izlenir.","iliskili":["os-5-176","os-5-166","os-5-172"],"kontrol":null,"cizim":"oda"}],"sorular":[{"id":"os-5-s01","tur":"coktan-secmeli","soru":"Oda 204’teki iş amaçlı konuk yarın sabah önemli bir toplantıya katılacak. Otel bu konuğun beklentisini karşılamak için hangisini yapmalıdır?","secenekler":["Odasına çocuk kulübünün haftalık etkinlik programını bırakmalıdır.","Kesintisiz internet ve sessiz bir çalışma ortamı sağlamalıdır.","Akşam yemeği için yöreye özgü bir tadım menüsü hazırlamalıdır.","Ertesi gün için müzelere yürüyüş yolunu gösteren harita vermelidir."],"dogru":1,"aciklama":"İş amaçlı konuk hız, kesintisiz internet ve sessiz çalışma ortamı bekler. Çocuk etkinliği ve yerel lezzet tatilciye, müze haritası kültür amaçlı konuğa uygundur."},{"id":"os-5-s02","tur":"coktan-secmeli","soru":"Antalya’daki bir tatil köyüne gelen aileye hangi yaklaşım, bu konuk grubunun beklentisine uygundur?","secenekler":["Kısa ve resmî konuşup giriş işlemini olabildiğince çabuk bitirmek","Diyet listesini titizlikle sorup sakin bir oda ayarlamak","Güler yüzlü olup çocuk kulübünü ve akşam gösterisini anlatmak","Protokol kurallarını uygulayıp konuğun gizliliğini öne çıkarmak"],"dogru":2,"aciklama":"Tatilci eğlence, dinlenme ve konfor bekler; acelesi yoktur, sohbet ve ilgi ona hızdan değerli gelir. Kısa ve resmî tutum iş konuğuna, diyet takibi sağlık konuğuna, protokol VIP konuğa uyar."},{"id":"os-5-s03","tur":"coktan-secmeli","soru":"Termal bir otelde garson, diyet listesinde tuzsuz menü yazan konuğun yemeğini mutfağa kendisi iletiyor ve tabağı servisten önce kontrol ediyor. Bu özen hangi konuğun beklentisine karşılık gelir?","secenekler":["Kültür / inanç amaçlı konuğun","Kongre ve etkinlik konuğunun","Tatil ve eğlence amaçlı konuğun","Sağlık / termal amaçlı konuğun"],"dogru":3,"aciklama":"Sağlığı için seyahat eden konuk hijyen, diyete uygun yemek, sakinlik ve uzman desteği bekler. İş konuğu hız, kültür konuğu rehberlik, kongre konuğu programa uygun servis bekler."},{"id":"os-5-s04","tur":"coktan-secmeli","soru":"Bir görevli uçağına yetişen iş konuğuna hızı, havuzdan yeni dönen tatilciye ise kısa bir sohbeti ön plana çıkarıyor. Bu farklı davranışı doğru kılan şey nedir?","secenekler":["İş konuğuna daha fazla, tatilciye daha az nezaket gösterilmesinin gerekmesi","Her konuk grubu için ayrı bir hizmet standardı uygulanmasının zorunlu olması","İş konuğunun tatilciden daha pahalı bir oda tutmuş olması","O an en önemli saydıkları şeyin, yani ihtiyaç algılarının farklı olması"],"dogru":3,"aciklama":"Konuk grupları en çok ihtiyaç algılarıyla ayrılır; nezaket herkese aynıdır, değişen yalnız üsluptur. Fiyat ya da nezaket farkı davranışı belirlemez."},{"id":"os-5-s05","tur":"coktan-secmeli","soru":"Görme engelli bir konuk resepsiyona geliyor. Hangi davranış doğrudur?","secenekler":["Kolundan tutup kendi seçtiği en kısa yoldan odasına götürmek","Sorularını konuğa değil yanındaki refakatçisine yöneltmek","Önce kendini tanıtıp yardıma ihtiyacı olup olmadığını sormak","Odadaki eşyaların yerini ona kolay olsun diye değiştirmek"],"dogru":2,"aciklama":"Engelli konuğa dokunmadan önce yardım isteyip istemediği sorulur ve konuşma konuğun kendisiyle yapılır. Konuk odayı ezberine göre kullandığı için eşyalar rastgele değiştirilmez."},{"id":"os-5-s06","tur":"coktan-secmeli","soru":"Aşağıdaki konuklardan hangisi, işletme için ticari önem taşıdığı için CIP konuk sayılır?","secenekler":["Dünyaca tanınmış bir sinema sanatçısı","Resmî ziyarette bulunan devlet başkanı","Otelle çalışan acentenin satış müdürü","Aynı oteli her yaz tercih eden bir aile"],"dogru":2,"aciklama":"CIP konuk, işletmeye ticari açıdan değer katan kişidir; memnun kalırsa otele çok sayıda konuk yönlendirebilir. Sanatçı VIP, devlet başkanı VVIP, her yıl gelen aile sadık konuktur."},{"id":"os-5-s07","tur":"dogru-yanlis","soru":"Odasında internet çalışmayan bir konuğun şikâyet etmeden ayrılması, o konuğun otelden memnun kaldığını gösterir.","secenekler":["Doğru","Yanlış"],"dogru":1,"aciklama":"Sessiz ve utangaç konuklar rahatsızlıklarını çoğu zaman dile getirmez; sessizlik memnuniyet demek değildir. Bu yüzden personel ilk adımı atıp nazik bir soruyla ihtiyacı öğrenir."},{"id":"os-5-s08","tur":"coktan-secmeli","soru":"VIP bir sanatçının gelişine hazırlanılıyor. Aşağıdaki uygulamalardan hangisi yanlıştır?","secenekler":["Konuğun otelde kaldığını merak edip soranlara bunu söylemek","Odayı konuk gelmeden önce son bir kez baştan sona kontrol etmek","Kaydını bankoda bekletmeden, odasında sessizce tamamlamak","Oda numarasını yanındaki kişilerin duyacağı sesle söylememek"],"dogru":0,"aciklama":"VIP konuğun ilk beklentisi gizliliktir; kim olduğu ve nerede kaldığı kimseyle paylaşılmaz. Diğer üç uygulama hız, ayrıcalık ve kusursuz ayrıntı beklentisini karşılar."},{"id":"os-5-s09","tur":"coktan-secmeli","soru":"Yaşlı bir konuğa kahvaltı saatini söylerken hangi uygulama doğrudur?","secenekler":["Anlasın diye sesi yükseltip çocukla konuşur gibi basit sözcükler seçmek","Bilgiyi konuğa değil yanındaki yakınına vermek","Sıra uzamasın diye saati bir kez söyleyip hemen diğer konuğa geçmek","Yavaş ve net konuşup gerekirse saati bir kâğıda yazmak"],"dogru":3,"aciklama":"Yaşlı konuk yavaş, net ve saygılı bir dil bekler; yazılı not da işi kolaylaştırır. Yüksek sesle ya da çocukla konuşur gibi konuşmak saygısızlıktır."},{"id":"os-5-s10","tur":"coktan-secmeli","soru":"Odasında internet çalışmayan konuk bankoya iki kez yaklaşıp hiçbir şey söylemeden geri dönüyor. Konuk hangi tiptir ve görevli ne yapmalıdır?","secenekler":["Kararsız tip; görevli iki üç seçenek sunarak karar vermesini kolaylaştırmalıdır.","Sessiz ve utangaç tip; görevli yanına gidip nazikçe yardım teklif etmelidir.","Konuşkan tip; görevli sohbeti kırmadan kısaltıp işine dönmelidir.","Şüpheci tip; görevli bilgiyi yazılı verip kanıt göstermelidir."],"dogru":1,"aciklama":"İhtiyacını söylemekte zorlanan konuk sessiz ve utangaç tiptir; ilk adımı personel atar. Seçenek daraltma kararsız, sohbeti kısaltma konuşkan, yazılı kanıt şüpheci konuk içindir."},{"id":"os-5-s11","tur":"coktan-secmeli","soru":"Restoranda menüye uzun süredir bakan konuk hâlâ karar verememiştir. Garson ne yapmalıdır?","secenekler":["Bir iki soru sorup iki üç uygun yemek önermek ve seçimi ona bırakmak","Menüdeki bütün yemekleri baştan sona tek tek sayıp tanıtmak","Mutfağın kapanış saatini hatırlatıp kararını çabuklaştırmasını istemek","En çok sattıkları yemeği sipariş defterine yazıp onun adına vermek"],"dogru":0,"aciklama":"Kararsız konuk çok seçenekten yorulur; seçenekler daraltılır ve karar konuğa bırakılır. Acele ettirmek ya da kararı onun yerine vermek konuğu daha da kararsız yapar."},{"id":"os-5-s12","tur":"coktan-secmeli","soru":"Torunlarını anlatan konuğun arkasında sıra oluştu. Hangi karşılık hem profesyonel mesafeyi korur hem konuğu kırmaz?","secenekler":["“Ne güzel efendim; bekleyen konuklarla ilgilenip devamını sonra dinleyeyim.”","“Efendim, arkada sıra var; lütfen konuşmayı kısa tutar mısınız?”","“Torunlarınızın adları neydi, hangi okula gidiyorlar, biraz daha anlatın lütfen.”","Dinler gibi yapıp başını ekrana çevirerek kendi işine devam etmek"],"dogru":0,"aciklama":"Konuşkan konuk nezaketle dinlenir, ama zaman iyi yönetilir ve sohbet kırılmadan bitirilir. Sözü kesmek soğuk, sohbeti sürdürmek profesyonel mesafeyi aşmak olur."},{"id":"os-5-s13","tur":"coktan-secmeli","soru":"Aynı sade odada kalan iki konuktan sade oda bekleyen çok memnun kalıyor, fotoğraflarda daha geniş bir oda gören ise hayal kırıklığı yaşıyor. Bu durum memnuniyetin neye bağlı olduğunu gösterir?","secenekler":["Odanın metrekaresinin ve manzarasının ne kadar etkileyici olduğuna","Konuğun ödediği ücretin ne kadar yüksek olduğunun hesaplanmasına","Hizmetin konuğun beklentisiyle karşılaştırılmasına","Tesisin yıldız sayısının ne kadar fazla olduğuna"],"dogru":2,"aciklama":"Memnuniyet, yaşanan ile beklenen arasındaki farka göre oluşur; aynı oda iki konukta farklı duygu doğurur. Oda büyüklüğü, ücret ve yıldız sayısı tek başına belirleyici değildir."},{"id":"os-5-s14","tur":"dogru-yanlis","soru":"Tanıtımda hiç söz edilmeyen küçük bir ikram konuğun beklentisini aşar; tanıtımda önceden duyurulan ikram ise artık sürpriz değil beklentidir.","secenekler":["Doğru","Yanlış"],"dogru":0,"aciklama":"Duyurulan ikram beklenti hâline gelir ve verilmezse şikâyet konusu olur. Söylenmeden yapılan incelik beklentiyi aşar ve konuğun aklında kalır."},{"id":"os-5-s15","tur":"coktan-secmeli","soru":"Aşağıdakilerden hangisi konuk memnuniyetini belirleyen üç insan unsurundan biri değildir?","secenekler":["Konuğun durumunu onun gözünden görüp onunla gerçekten ilgilenmek","İsteği ve sorunu vakit kaybetmeden, işini bilen bir tavırla sonuçlandırmak","Doğru bilgi verip verilen her sözü tutmak","Oda sayısı ve havuz gibi fiziksel imkânların çokluğu"],"dogru":3,"aciklama":"Üç unsur empati ve ilgi, hız ve profesyonellik, güven ve dürüstlüktür; üçü de binaya değil insana bağlıdır. Fiziksel imkânlar gereklidir ama memnuniyeti asıl belirleyen bunlar değildir."},{"id":"os-5-s16","tur":"coktan-secmeli","soru":"Şikâyet eden konuğa teşekkür etmek neden doğru bir davranıştır?","secenekler":["Hizmetteki açığı gösterdiği ve konuğu kaybetmeden düzeltme fırsatı verdiği için","Şikâyet eden konuk, ileride yeni bir şikâyette bulunmayacağı için","Şikâyet, işletmenin konuğa her zaman indirim yapması gerektiğini gösterdiği için","Şikâyet, öteki konukların da memnun olduğunu kanıtladığı için"],"dogru":0,"aciklama":"Şikâyet bir hediyedir: sorunu gösterir ve konuğa ikinci şans tanır. Asıl kayıp, hiçbir şey söylemeden giden konuktur."},{"id":"os-5-s17","tur":"coktan-secmeli","soru":"Konuk şikâyetini anlatmayı bitirdi. LEARN modeline göre görevlinin sıradaki adımı hangisidir?","secenekler":["Empati kurmak; duygusu anlaşılan konuk sakinleşir, çözümü dinlemeye hazır olur.","Çözüm üretmek; konuk en çok çözüm bekler, bu yüzden hemen önerilmelidir.","Özür dilemek; özür sözü konuğu en çabuk yatıştıran ve öfkesini söndüren adımdır.","Hemen uygulamak; geciken çözüm konuğun öfkesini yeniden büyüttüğü için sırada ilk gelir."],"dogru":0,"aciklama":"LEARN sırasıyla dinle, empati kur, özür dile, çözüm üret, hemen yap adımlarından oluşur; dinlemenin ardından konuğun duygusu görülür. Sıra bozulursa çözüm, konuğa dinlenmeden dayatılmış olur."},{"id":"os-5-s18","tur":"coktan-secmeli","soru":"Konuk beklerken görevli telefonu kaldırıp teknik servisi arıyor ve “On dakika içinde odanızdalar efendim” diyor. LEARN modelinin hangi adımı uygulanmaktadır?","secenekler":["React: konuğun sorununu giderecek somut bir çözüm bulunuyor.","Apologise: işletme adına konuğa üzgün olunduğu söyleniyor.","Now: bulunan çözüm ertelenmeden hemen uygulamaya konuluyor.","Empathise: konuğun ne hissettiği anlaşıldığı gösteriliyor."],"dogru":2,"aciklama":"Çözümü bulmak (React) ile onu konuğun gözü önünde başlatmak (Now) ayrı adımlardır; burada eylem hemen başlamıştır. Geciken çözüm çözüm sayılmaz."},{"id":"os-5-s19","tur":"coktan-secmeli","soru":"Bir ayda aynı kattan dört konuk klimadan yakındı ve her seferinde oda değiştirildi. Yönetim sorunun yeniden yaşanmasını istemiyor. Hangi adım en doğrudur?","secenekler":["Her şikâyet eden konuğa daha değerli bir ikram göndermek","O kata verilen oda sayısını azaltıp konuk yoğunluğunu düşürmek","Şikâyetlerin ortak nedenini araştırıp asıl kaynağı gidermek","Şikâyet eden konukları sonraki konaklamaları için sadakat programına almak"],"dogru":2,"aciklama":"Farklı konuklardan gelen aynı şikâyet kişisel değil, sistemle ilgili bir sorundur; kök neden bulunmazsa sonraki konuklar da aynısını yaşar. İkram ve oda değişikliği yalnız belirtiyi düzeltir."},{"id":"os-5-s20","tur":"dogru-yanlis","soru":"Konuğun duygusunu anladığını gösteren görevli, şikâyetinde onu haklı bulduğu için istediği telafiyi vermek zorundadır.","secenekler":["Doğru","Yanlış"],"dogru":1,"aciklama":"Empati duyguyu görmektir; konuğa her konuda hak vermek ya da her isteğini kabul etmek değildir. Telafiyi yetkisi ölçüsünde personel, aşan kısmı amir belirler."},{"id":"os-5-s21","tur":"coktan-secmeli","soru":"Sitede “denize sıfır” yazan otelin kumsalına gitmek için yolun karşısına geçmek gerekiyor. Konuğun hayal kırıklığı memnuniyetsizliğin hangi kaynağından doğar?","secenekler":["Pazarlama ve beklenti yönetimi","Fiziksel ve teknik sorunlar","Hizmet süreçleri ve personel etkileşimi","Hizmet telafisinin gecikmesi"],"dogru":0,"aciklama":"Tanıtımda vaat edilenle gerçeğin uyuşmaması beklenti yönetimi hatasıdır. Fiziksel sorun klima ya da gürültü gibi donanımla, süreç sorunu soğuk karşılama gibi insanla ilgilidir."},{"id":"os-5-s22","tur":"coktan-secmeli","soru":"Çorbası soğuk gelen konuğa yenisi getirilmiş, üstüne pahalı bir spa paketi de hediye edilmiştir. Hangi ilke ihlal edilmiştir?","secenekler":["Jestin yalnız yönetim tarafından verilmesi","Jestin yaşanan sorunun büyüklüğüyle orantılı olması","Aynı sorunu yaşayan bütün konuklara aynı jestin verilmesi","Jestin konuk istemeden önce sunulmaması"],"dogru":1,"aciklama":"Küçük soruna büyük jest gereksizdir, büyük soruna küçük jest alay gibi algılanır; ilke orantıdır. Küçük jestlere personel yetkisi içinde karar verebilir."},{"id":"os-5-s23","tur":"coktan-secmeli","soru":"Standart odasının kliması onarılamayan aileye ek ücret alınmadan bir üst kategoride süit verildi. Bu uygulamanın sektördeki adı nedir?","secenekler":["Gelecek konaklama için indirim kuponu","Oda yükseltme (upgrade)","El yazısıyla özür notu","Sadakat programı ödülü"],"dogru":1,"aciklama":"Ücretsiz olarak üst kategoride oda vermek oda yükseltmedir. Kupon bir sonraki geliş, el yazısı not kişisel gönül alma, sadakat programı ise tekrar gelen konuğu ödüllendirme yoludur."},{"id":"os-5-s24","tur":"dogru-yanlis","soru":"Kimin VIP sayılacağına işletme karar verir; balayı çiftleri ve yöneticilerin konukları da bu gruba alınabilir.","secenekler":["Doğru","Yanlış"],"dogru":0,"aciklama":"VIP ve VVIP sınıflaması işletmenin kendi politikasıdır; her otelde aynı değildir. Bu yüzden personel kimin hangi gruptan sayıldığını amirinden öğrenir."},{"id":"os-5-s25","tur":"senaryo","durum":"Saat 07.10, şehir otelinin resepsiyonundasın. Takım elbiseli bir konuk telefonla konuşarak bankoya geliyor; taksisi kapıda bekliyor ve toplantısına yirmi dakika kalmış. Şefin konuğun faturasını önceden hazırlamış, sana uzatıyor.","soru":"Nasıl davranırsın?","secenekler":["Konaklamasını sorar, spa merkezinin yeni hizmetlerini tanıtırım.","Görüşmesi bitene kadar bekler, sonra bütün kalemleri tek tek okurum.","Memnuniyet anketini şimdi doldurması için kalem uzatırım.","Kısa bir selamla faturayı gösterir, işlemi hızla tamamlarım."],"dogru":3,"aciklama":"İş konuğu için en değerli şey zamandır; işlem hızlı ve profesyonelce bitirilir. Tanıtım, uzun açıklama ve anket tatilciye ya da sonraya uygundur, bu konuğu geciktirir."},{"id":"os-5-s26","tur":"senaryo","durum":"Saat 11.00, otelin girişindesin. Tekerlekli sandalye kullanan bir konuk tek başına rampadan çıkmaya çalışıyor; kucağında küçük bir valiz var. Kapı görevlisi başka bir araçla ilgileniyor.","soru":"Ne yaparsın?","secenekler":["Arkasına geçip sandalyeyi rampadan yukarı iterim.","Valizi kucağından alıp hızla resepsiyona taşırım.","Zorlandığını görsem de kendi işime döner, konuk seslenmedikçe yaklaşmam.","Yanına gidip yardım isteyip istemediğini sorarım."],"dogru":3,"aciklama":"Sandalye ve eşya konuğun kişisel alanıdır; izinsiz dokunmak onu ürkütür, dengesini bozabilir. Sorarak yardım etmek hem saygıdır hem bağımsızlığı korur; hiç yaklaşmamak ise ihtiyacı fark etmemek olur."},{"id":"os-5-s27","tur":"senaryo","durum":"Saat 15.20, resepsiyondasın; kat şefin başka bir işle ilgileniyor. 508’de kalan konuk elinde bir listeyle geliyor: çarşafın katlanışından aynadaki su lekesine kadar bir dizi ayrıntıyı sıralıyor.","soru":"Ne yaparsın?","secenekler":["Odanın sabah standartlara göre kontrol edildiğini söyleyerek durumu açıklarım.","Listeyi sabırla dinler, maddeleri not alır, odayı yeniden kontrol ettiririm.","Önemsiz bulduklarımı geçer, yalnız ciddi eksikleri kat şefime aktarırım.","Rahatsızlık için odasına hemen bir meyve sepeti göndereceğimi söylerim."],"dogru":1,"aciklama":"Titiz ve eleştirel konuk standartlara tam uygun hizmet ve sabırlı bir dil bekler; savunmaya geçmek işe yaramaz. Eksikleri kendi ölçünle ayıklamak ya da yetkin olmayan bir ikram sözü vermek sorunu çözmez."},{"id":"os-5-s28","tur":"senaryo","durum":"Saat 22.15, resepsiyondasın; şefin az önce arka ofise geçti. Bir konuk bankoya sertçe gelip “İki saattir sıcak su yok, bu ne biçim otel!” diye bağırıyor. Lobide başka konuklar da oturuyor.","soru":"Nasıl davranırsın?","secenekler":["“Lütfen bağırmayın, diğer konuklarımız rahatsız oluyor” derim.","Dinler, özür diler, teknik servisi arar ve şefime haber veririm.","“Teknik servis akşam bakmıştı, sorun olmaması gerekiyor” diye açıklarım.","Konuğu şefimle görüşmesi için arka ofise yönlendirir, kendim ilgilenmem."],"dogru":1,"aciklama":"Öfkeli konuğa sakin kalıp sözünü kesmeden dinlemek, savunmaya geçmeden çözüme yönelmek gerekir; öfke çoğu zaman sana değil duruma yöneliktir. Konuğu uyarmak, suçu başkasına atmak ya da başka birine yollamak sorunu sahiplenmemektir."},{"id":"os-5-s29","tur":"senaryo","durum":"Temmuz, saat 16.00. Resepsiyonda stajyersin; şefin yan tarafta başka bir konukla ilgileniyor. Çocuklu bir konuk yanına gelip “Odamızda klima soğutmuyor, çocuklar sıcaktan perişan oldu!” diyor.","soru":"İlk adımın ne olur?","secenekler":["Önce sözünü kesmeden, göz teması kurarak sonuna kadar dinlerim.","Hemen odasına bir meyve sepeti göndereceğimi söylerim.","Klimaların bu sabah kontrol edildiğini anlatırım.","Teknik servisin numarasını verip kendisinin aramasını söylerim."],"dogru":0,"aciklama":"LEARN modelinin ilk adımı dinlemektir; konuk önce dinlenmek ister, çözüm sonra gelir. İkram sözü yetkin dışında olabilir, açıklama savunmadır, numarayı verip yollamak sorunu sahiplenmemektir."},{"id":"os-5-s30","tur":"senaryo","durum":"Saat 10.30, çıkış işlemlerine yardım ediyorsun. Bir konuk gece boyunca gürültüden uyuyamadığını söylüyor ve bir gecelik ücretin hesabından silinmesini istiyor. Ücret silme yetkin yok; ön büro müdürü ofisinde.","soru":"Ne yaparsın?","secenekler":["Konuk haklı göründüğü için ücreti sileceğime söz veririm.","Yetkim olmadığını söyler, çıkış işlemine olduğu gibi devam ederim.","Not alır, yetkim olmadığını söyler, müdüre haber veririm.","Gürültünün otelden kaynaklanmadığını uzun uzun anlatmaya çalışırım."],"dogru":2,"aciklama":"Yetkiyi aşan bir talep notlarla birlikte amire aktarılır ve konuğa bilgi verilir; böylece konuk her şeyi baştan anlatmak zorunda kalmaz. Yetkisiz söz vermek ya da konuğu savmak durumu kötüleştirir."},{"id":"os-5-s31","tur":"senaryo","durum":"Saat 20.00, santralde telefonlara bakan görevliye yardım ediyorsun. Arayan kişi kendini gazeteci olarak tanıtıyor; ünlü bir şarkıcının otelde kalıp kalmadığını ve hangi odada olduğunu soruyor.","soru":"Ne cevap verirsin?","secenekler":["Kaldığını doğrular, ama oda numarasını söylemem.","Konuklarla ilgili bilgi veremediğimi söylerim.","Gazeteci olduğu için sorusunu eksiksiz cevaplarım.","“Bilmiyorum” deyip telefonu hemen kapatırım."],"dogru":1,"aciklama":"Konuğun kim olduğu, kaldığı ya da nerede kaldığı bilgisi kimseyle paylaşılmaz; kaldığını doğrulamak bile gizliliği çiğnemektir. Yalan söylemek de çözüm değildir, nazikçe bilgi verilemeyeceği söylenir."},{"id":"os-5-s32","tur":"senaryo","durum":"Saat 15.00, havuz barında servise yardım ediyorsun. Birkaç gündür seninle sohbet eden güler yüzlü bir konuk “Çok iyi anlaştık; telefon numaranı ver, akşam mesajlaşırız” diyor.","soru":"Nasıl davranırsın?","secenekler":["Kırmamak için numaramı verir, mesajlarına kısa cevap yazarım.","“Bana böyle şeyler soramazsınız” diyerek sert bir cevap veririm.","Nazikçe teşekkür eder, bunun görevde uygun olmadığını söylerim.","Numaramı vermem, ama sosyal medya hesabımı paylaşırım."],"dogru":2,"aciklama":"Konuğa sıcak davranırken saygı sınırı aşılmaz: telefon numarası alınıp verilmez, özel hayat paylaşılmaz. Sert cevap konuğu kırar, başka bir iletişim yolu vermek de aynı sınırı aşar."},{"id":"os-5-s33","tur":"senaryo","durum":"Rezervasyon bölümünde stajyersin. Şefin bu sabah havuzun ayın yirmisine kadar bakımda olacağını duyurdu. Telefondaki konuk ayın on beşi için oda sormak istiyor ve “Çocuklar için havuz çok önemli, açık değil mi?” diyor.","soru":"Ne söylersin?","secenekler":["Rezervasyon kaçmasın diye havuzun açık olduğunu söylerim.","Havuzdan söz etmeden yalnız oda fiyatlarını anlatırım.","Havuzun yakında açılacağını söyler, tarih vermekten kaçınırım.","Havuzun bakımda olduğunu ve açılış tarihini açıkça söylerim."],"dogru":3,"aciklama":"Olumsuz bilgiyi baştan söylemek bir rezervasyon kaybettirebilir; söylememek ise konuğu ve otelin adını kaybettirir. Güven ve dürüstlük, verilen her bilginin doğru olmasını gerektirir."},{"id":"os-5-s35","tur":"coktan-secmeli","soru":"Gece duman dedektörü ötüyor; aynı katta kasada nakit ve değerli bir tablo da duruyor. Personelin öncelik sırası hangisidir?","secenekler":["Önce konukların ve personelin canı, sonra eşya ve bina","Önce değerli eşya ve kasa, sonra konuklar","Önce tesisin itibarını koruyacak açıklama, sonra konuklar","Önce zarar gören bölümün onarımı, sonra konuklar"],"dogru":0,"aciklama":"Olağan dışı durumlarda sıra hiç değişmez: can güvenliği önce gelir, eşya ve bina sonra. Eşya ya da itibar uğruna can riske atılmaz."},{"id":"os-5-s36","tur":"coktan-secmeli","soru":"Bir olaydan sonra “Hangi kart, hangi saatte, hangi kapıyı açtı?” sorusu kayıttan yanıtlanabiliyor. Bu kaydı tutan sistem hangisidir?","secenekler":["Kapalı devre kamera sistemi (CCTV)","Giriş kontrol sistemi","Entegre alarm sistemi","Panik butonu sistemi"],"dogru":1,"aciklama":"Giriş kontrol sistemi kartlara yetki tanımlar ve her açma denemesini kaydeder. Kamera görüntü kaydeder; kart ve kapı bilgisini tutan sistem değildir."},{"id":"os-5-s37","tur":"coktan-secmeli","soru":"Koridorun L biçimindeki köşesi hiçbir kameraya görünmüyor. Bu kör noktayı en etkili biçimde ne giderir?","secenekler":["Kameraların çözünürlüğünü yükseltip görüntüyü netleştirmek","Kayıtları sunucuda aylarca daha uzun süre saklamak","Kameraları yalnız tesisin dış sınırına yöneltmek","Kameraların görüş alanlarını birbirine bindirmek"],"dogru":3,"aciklama":"Birinin bittiği yerde öbürünün başladığı yerleşim kör noktayı kapatır. Çözünürlük ve saklama süresi görünmeyen yeri görünür kılmaz."},{"id":"os-5-s38","tur":"coktan-secmeli","soru":"Entegre alarm sisteminde yangın alarmı devreye girdiğinde elektronik kilit sistemi ne yapar?","secenekler":["Acil çıkış kapılarının kilidini kendiliğinden açar.","Giriş ve çıkışları kilitleyip alanı dışarıya kapatır.","Yalnız personel kartlarını bir süre geçersiz kılar.","Bütün oda kapılarını yarım saat kilitli tutar."],"dogru":0,"aciklama":"Yangında saniyeler önemlidir; kapılar açılarak kaçış kolaylaşır. Girişleri kilitleyen, yetkisiz giriş algılayan hırsızlık alarmıdır."},{"id":"os-5-s39","tur":"coktan-secmeli","soru":"Gece resepsiyonda saldırgan bir kişiyle karşılaşan görevli panik butonuna basıyor. Merkezî sistem ne yapar?","secenekler":["Havalandırmayı kapatıp asansörleri zemin kata indirir ve itfaiyeye haber verir.","Giriş çıkışları kilitleyip yüksek sesli sirenle alanı uyarır.","En yakın güvenlik görevlisine yeri bildirir ve kameraları o noktaya çevirir.","Bütün oda kartlarını geçersiz kılıp konukları odalarına yönlendirir."],"dogru":2,"aciklama":"Panik butonu tehlikedeki kişinin sessizce yardım çağırmasını sağlar. Havalandırma ve asansör tepkisi duman dedektörünün, kilitleyip siren çalma hırsızlık alarmının işidir."},{"id":"os-5-s40","tur":"coktan-secmeli","soru":"Konuk bilgilerinin korunması (KVKK) açısından aşağıdaki davranışlardan hangisi yanlıştır?","secenekler":["Kimlik fotokopisini yalnız yetkili kişilerin eriştiği yerde saklamak","Konuğun adını ve oda numarasını yalnızca iş için kullanmak","Kimliği doğrulanmamış kişiye bilgi vermeyip amire haber vermek","Kimliği doğrulanmamış bir arayana konuğun pasaport numarasını okumak"],"dogru":3,"aciklama":"Kimlik, pasaport ve kart bilgileri yalnız iş için ve yalnız yetkili kişilerce kullanılır. Doğrulanmamış kişiyle paylaşmak konuğun güvenini ve yasayı çiğnemektir."},{"id":"os-5-s41","tur":"coktan-secmeli","soru":"Çamaşırhanede su borusu patladı. Olağan dışı durum prosedürünün dört aşaması hangi sırayla işler?","secenekler":["Tespit ve ihbar – tahliye ve koruma – acil müdahale – kayıt ve analiz","Tespit ve ihbar – acil müdahale – tahliye ve koruma – kayıt ve analiz","Acil müdahale – tespit ve ihbar – tahliye ve koruma – kayıt ve analiz","Tespit ve ihbar – acil müdahale – kayıt ve analiz – tahliye ve koruma"],"dogru":1,"aciklama":"Önce olay fark edilip bildirilir, sonra ilk fiziksel müdahale yapılır, ardından insanlar korunur ve en son olay yazılıp analiz edilir. Haber verilmeden müdahale ya da tahliyeden önce kayıt mantık sırasını bozar."},{"id":"os-5-s42","tur":"coktan-secmeli","soru":"Aynı merdiven basamağında bir ayda ikinci düşme kaydı görülünce yönetim o basamağa kaydırmaz bant yaptırıyor. Bu, prosedürün hangi aşamasının işidir?","secenekler":["Tespit ve ihbar; amaç hızlı ve kesintisiz bilgi akışı","Acil müdahale; amaç zararı en az düzeyde tutmak","Kayıt ve analiz; amaç ilerideki riskleri önlemek","Tahliye ve koruma; amaç konukların can güvenliği"],"dogru":2,"aciklama":"Kayıtlar incelenip tekrar eden risk bulunur ve önlem alınır; bu son aşamanın görevidir. Öteki aşamalar olay anındaki bilgi, müdahale ve can güvenliği içindir."},{"id":"os-5-s43","tur":"coktan-secmeli","soru":"Etiketsiz şişedeki sıvıyı başka bir temizlik maddesiyle karıştıran kat görevlisinin gözleri yanıyor ve nefesi daralıyor. Bu hangi kazadır ve en çok nerede görülür?","secenekler":["Yanık ve yaralanma; mutfak, banyo ve restoran","Kimyasal kaza; kat hizmetleri ofisleri ve depolar","Düşme ve kayma; havuz çevresi, banyo ve lobi","Elektrik kazası; konuk odaları ve teknik servis alanları"],"dogru":1,"aciklama":"Temizlik maddelerinin solunması ya da göze teması kimyasal kazadır ve en çok kat ofislerinde, depolarda görülür. Öteki kaza türlerinin nedeni sıcak yüzey, ıslak zemin ve akımdır."},{"id":"os-5-s44","tur":"coktan-secmeli","soru":"Lobide bir konuk kaydı. Görevli “Hemen kurulayayım” diyor, ama amiri onu durdurup önce fotoğraf çekiyor. Neden?","secenekler":["Islak zemin öteki konukların dikkatini çekip kazayı önler.","Zeminin kurulanması yalnız sigorta şirketinin görevidir.","Silinen su, kazanın nedenini gösteren kanıtı yok eder.","Kuruyan zemin tutanağa yazılamaz."],"dogru":2,"aciklama":"Olay yeri korunmazsa kazanın nedeni (ıslak zemin) kanıtlanamaz; sonradan tutanak ve kusur tartışmasında işletme zor durumda kalır. Önce fotoğraf çekilir ve uyarı konur."},{"id":"os-5-s45","tur":"coktan-secmeli","soru":"Aşağıdaki durumlardan hangisi, kartta sayılan acil belirtiler arasında olduğu için beklenmeden 112’nin aranmasını gerektirir?","secenekler":["Konuğun uzun yolculuktan sonra halsiz olduğunu söylemesi","Konuğun yemekten sonra uyuşuk görünmesi","Konuğun sözcükleri karıştırması ve peltek konuşması","Konuğun güneşte kalıp yüzünün hafif kızarması"],"dogru":2,"aciklama":"Sözcükleri karıştırma ya da peltek konuşma ciddi bir sağlık sorununun işaretidir; vakit kaybedilmez, 112 aranır ve yöneticiye haber verilir. Yorgunluk, uyku hâli ve hafif kızarma bu listede yer almaz."},{"id":"os-5-s46","tur":"coktan-secmeli","soru":"Çıkış yapmış bir konuğun unuttuğu telefon kayda alınıp saklanıyor; muhafaza süresi doldu ama sahibi gelmedi. Eşyaya ne yapılır?","secenekler":["Eşyayı bulan görevli kendisi için saklayabilir.","Kimseye sorulmadan eşya çöpe atılır.","Eşya sahibi çıkana kadar süresiz saklanır.","Prosedür ve mevzuata göre işlem yapılır."],"dogru":3,"aciklama":"Süre dolunca işlem, kayıp eşya prosedürüne ve yürürlükteki mevzuata göre yapılır. Eşya hiçbir zaman bulanın cebine girmez; çöpe atmak ya da süresiz saklamak da prosedür değildir."},{"id":"os-5-s47","tur":"coktan-secmeli","soru":"Çıkış yapan bir konuğun valizinde aşağıdakilerden hangisi bulunursa personel bunu olağan karşılar?","secenekler":["Banyodaki küçük şampuan","Odadaki bornoz","Odadaki saç kurutma makinesi","Banyodaki yüz havlusu"],"dogru":0,"aciklama":"Küçük şampuan ve sabun sarf malzemesidir, konuk alabilir. Bornoz, havlu ve saç kurutma makinesi demirbaştır, odada kalır ve eksikse ön büro bilgilendirilir."},{"id":"os-5-s48","tur":"coktan-secmeli","soru":"Havuz başında iki aile şezlong yüzünden bağırarak tartışıyor. Aşağıdaki davranışlardan hangisi yanlıştır?","secenekler":["Sakin bir sesle sakinleşmelerini isteyip şefe ve güvenliğe haber vermek","Yakındaki garsonun araya girip tarafları kolundan ayırmaya çalışması","Taraf tutmadan ortamı güvenli kılmaya ve gerginliği düşürmeye çalışmak","Taraflar ayrıldıktan sonra olayı tutanağa geçirmek"],"dogru":1,"aciklama":"Güvenlik görevlileri dışında kimse taraflara fiziksel olarak yaklaşmaz; öncelik personelin kendi can güvenliğidir. Diğer personelin aracı sakin ses tonu, taraf tutmamak ve haber vermektir."},{"id":"os-5-s49","tur":"coktan-secmeli","soru":"Aşağıdakilerden hangisi bir paketi şüpheli yapan işaretlerden biri değildir?","secenekler":["Sahibi ortada yokken uzun süredir aynı yerde durması","Üzerinde gereğinden fazla bant, kablo ya da tel bulunması","İçinden saat tıkırtısına benzer bir ses gelmesi","Üzerinde, gönderilen konuğun adının yazılı olması"],"dogru":3,"aciklama":"Adı yazılı bir paket tek başına şüpheli sayılmaz. Sahipsizlik, aşırı bant ve kablo, ses, leke ve ağır koku şüphe işaretleridir; bunlarda kural dokunmamak, haber vermektir."},{"id":"os-5-s50","tur":"coktan-secmeli","soru":"Duman fark eden son kişi odadan çıkarken kapıyı arkasından çekiyor. Bu davranış R.A.C.E. protokolünün hangi adımıdır?","secenekler":["C (Confine): yangını ve dumanı sınırlamak","R (Rescue): alandaki kişileri kurtarmak","A (Alarm): yangını haber vermek","E (Extinguish / Evacuate): söndürmek ya da tahliye etmek"],"dogru":0,"aciklama":"Kapalı kapı dumanın yayılmasını yavaşlatır ve kaçış yolunu daha uzun süre dumansız tutar. Kapılar kapatılır ama kilitlenmez; kilitli kapı içeride kalanı hapseder."},{"id":"os-5-s51","tur":"coktan-secmeli","soru":"Aşağıdaki olaylardan hangisi mücbir sebep sayılmaz?","secenekler":["Büyük bir selin bölgedeki yolları kapatması","Otelle çalışan tek bir acentenin rezervasyon hatası yapması","Bölgenin tamamında telefon ve internet ağının günlerce çökmesi","Ülke genelinde bankaların günlerce işlem yapamadığı finansal kriz"],"dogru":1,"aciklama":"Mücbir sebep, işletmenin önleyemediği ve ekonominin ya da toplumun geneline yayılan olaydır. Tek bir acentenin hatası ya da tesisin kendi arızası bu kapsamda değildir."},{"id":"os-5-s52","tur":"coktan-secmeli","soru":"Deprem sonrasında tesiste kalan Alman ve Hollandalı konukların konsolosluklara bildirilmesi için ne yapılır?","secenekler":["Resepsiyon görevlisi ilgili büyükelçilikleri tek tek telefonla arar.","Her konuğun kendi ülkesine kendisinin haber vermesi beklenir.","Kriz bitip konuklar tesisten ayrılana kadar bildirim yapılmaz.","Konuk listesi mülki idareye verilir, idare konsolosluklara iletir."],"dogru":3,"aciklama":"Bildirim mülki idare aracılığıyla ve yönetimin gönderdiği listeyle yapılır. Personel yalnız konuğa konsolosluğunun bilgilendirildiğini söyleyebilir."},{"id":"os-5-s53","tur":"dogru-yanlis","soru":"Telefonla gelen bomba ihbarı asılsız görünse bile aksi kanıtlanana kadar gerçekmiş gibi davranılır ve karar tek bir görevlinin değil yönetimin ve kolluğun olur.","secenekler":["Doğru","Yanlış"],"dogru":0,"aciklama":"Tehdit asılsız olabilir, ama bu bir tahmindir. İhbarı alan görevli arayanı konuşturup not alır ve yönetime haber verir."},{"id":"os-5-s54","tur":"dogru-yanlis","soru":"Yangında dumanın yayılmasını önlemenin en güvenli yolu, odadan çıkarken kapıyı arkadan kilitlemektir.","secenekler":["Doğru","Yanlış"],"dogru":1,"aciklama":"Kapılar kapatılır ama asla kilitlenmez; kilitli kapı hem içeride kalanı hapseder hem itfaiyeyi geciktirir."},{"id":"os-5-s55","tur":"dogru-yanlis","soru":"Tesisin içinde yangın çıktığında personel, prosedürü uygulamaya başlamak için önce kaymakamlığın talimatını beklemelidir.","secenekler":["Doğru","Yanlış"],"dogru":1,"aciklama":"Tesis içindeki olayda ilk adım resmî talimat beklemek değil, prosedürü uygulamaktır. Mülki idarenin talimatı mücbir sebep gibi bölgesel durumlarda devreye girer."},{"id":"os-5-s56","tur":"dogru-yanlis","soru":"Uyarı levhası konmamış ıslak zeminde kayıp düşen konuk olayında kusur işletmededir ve işletme tazminat davasıyla karşılaşabilir.","secenekler":["Doğru","Yanlış"],"dogru":0,"aciklama":"Kaza işletmenin ihmalinden doğmuşsa kusur işletmeye aittir. Bütün önlemler alınmışsa işletmenin sorumluluğu azalır ya da kalkar; bu yüzden uyarı levhası önemlidir."},{"id":"os-5-s57","tur":"senaryo","durum":"Saat 17.20, stajının ikinci haftası. Kat hizmetlerinde çalışıyorsun. Üçüncü katta asansörün yanında sahipsiz bir sırt çantası duruyor; bir saat önce geçerken de oradaydı. Koridorda iki konuk var.","soru":"Ne yaparsın?","secenekler":["Çantayı açar, içinde kimlik ya da oda kartı var mı diye bakarım.","Dokunmadan uzaklaşır, güvenliğe ve kat şefime haber veririm.","Kayıp eşya olabilir diye çantayı alıp kat ofisine götürürüm.","Konuklara yüksek sesle “Bomba olabilir, kaçın!” diye bağırırım."],"dogru":1,"aciklama":"Sahipsiz ve uzun süredir duran pakete dokunulmaz; kural kahramanlık yapmamak, haber vermektir. Çantayı açmak ya da taşımak riski artırır, bağırmak paniğe yol açar."},{"id":"os-5-s58","tur":"senaryo","durum":"Saat 09.15, lobi. Yeni silinmiş zeminde bir konuk kayıp düştü; bileğini tutuyor, kalkamıyor ve “Burada uyarı levhası bile yok!” diye bağırıyor. Bellboy olarak en yakınında sen varsın.","soru":"İlk adımın ne olur?","secenekler":["Yanında kalır, sakinleştirir; reviri ve şefimi hemen çağırırım.","Koluna girer, onu hemen kaldırıp en yakın koltuğa oturturum.","Zeminin o kadar da ıslak olmadığını, biraz dikkat etmesi gerektiğini söylerim.","Başkası da düşmesin diye önce paspası getirip zemini kuruturum."],"dogru":0,"aciklama":"Kalkamayan ya da ağrısı şiddetli olan konuk yerinden oynatılmaz; sağlık ekibi çağrılır ve konuğun yanında kalınır. Zemini hemen kurutmak olay yerindeki kanıtı yok eder, konuğu suçlamak ise durumu kötüleştirir."},{"id":"os-5-s59","tur":"senaryo","durum":"Akşam 20.15, restoranda servise yardım ediyorsun. Masadaki konuk yemeğe başladıktan birkaç dakika sonra yüzü kızarıyor, boğazını tutuyor ve “Nefes alamıyorum” diyor. Eşi panik içinde sana bakıyor.","soru":"Ne yaparsın?","secenekler":["Bir bardak su getirir, belirtilerin kendiliğinden geçmesini beklerim.","Çantamdaki alerji ilacını çıkarır, konuğa hemen içiririm.","Şefime seslenir, 112’yi arattırır, konuğun yanında kalırım.","Dinlenmesi için konuğu eşiyle birlikte odasına gönderirim."],"dogru":2,"aciklama":"Nefes darlığı ve yaygın kızarıklık gibi ani alerji belirtilerinde beklenmez; 112 ve revir aranır, konuk yalnız bırakılmaz. Personel kendi kararıyla ilaç vermez, ilk yardımı eğitimli kişi yapar."},{"id":"os-5-s60","tur":"senaryo","durum":"Saat 19.00, resepsiyonda staj yapıyorsun; şefin arka ofiste. Bir konuk bankoya gelip bağırıyor: “Kasadaki saatim yok! Odayı temizleyen görevliniz aldı, hemen getirin onu buraya!” Lobideki konuklar dönüp bakıyor.","soru":"Nasıl davranırsın?","secenekler":["Kat görevlisini lobiye çağırır, konuğun önünde saati sorarım.","Konuğun odasına çıkar, kasayı ve dolapları kendim ararım.","Sakince dinler, not alır; şefime ve güvenliğe haber veririm.","Otelimizde hırsızlık olmayacağını, saati kendisinin kaybettiğini söylerim."],"dogru":2,"aciklama":"Hırsızlık bildiriminde kimse peşinen suçlanmaz; olay yönetim, güvenlik ve yetkililerce önceden belirlenmiş adımlarla yürütülür. Odayı kendin aramak delili bozar, konuğu suçlamak ise güveni zedeler."},{"id":"os-5-s61","tur":"senaryo","durum":"Saat 15.00, dördüncü kat. Koridorda yanık kokusu alıyorsun; 412 numaralı odanın kapısının altından duman sızıyor. Söndürücü eğitimi almadın. Koridorda odasından çıkmış iki konuk şaşkın şaşkın bakıyor.","soru":"Ne yaparsın?","secenekler":["Kapıyı açar, içeride gerçekten yangın var mı diye önce kendim bakarım.","Konukları uzaklaştırır, butona basıp yeri söyler, merdivene yönlendiririm.","Duvardaki söndürücüyü alır, hemen odaya girip alevi söndürmeyi denerim.","Asansörle lobiye inip durumu resepsiyondaki arkadaşa ayrıntısıyla anlatırım."],"dogru":1,"aciklama":"R.A.C.E. sırası önce insanları kurtarmak, sonra alarm vermektir; söndürme eğitimli kişinin işidir. Dumanın içine girmek kahramanlık değil risktir, asansör de yangında kullanılmaz."},{"id":"os-5-s62","tur":"senaryo","durum":"Gece 03.10, santralde görevli arkadaşının yanında staj yapıyorsun; o başka bir hatta konuşuyor. Çalan telefonu açıyorsun. Yabancı bir ses “Otelinizde bomba var” diyor ve konuşmayı sürdürüyor.","soru":"Ne yaparsın?","secenekler":["Şaka olduğunu düşünür, uyarıp telefonu kapatırım.","Telefonu bırakır, lobiye koşup konuklara binayı boşaltmalarını söylerim.","Arayana kim olduğunu sorar, polise şikâyet edeceğimi söyleyip tartışırım.","Kapatmam; dinleyip not alır, arkadaşıma işaretle haber veririm."],"dogru":3,"aciklama":"İhbar asılsız görünse de gerçekmiş gibi davranılır; telefon kapatılmaz, söylenenler ve arka plan sesleri not alınır, yönetime işaretle haber verilir. Tahliye kararını tek başına stajyer vermez."},{"id":"os-5-s63","tur":"senaryo","durum":"Saat 11.00. Yoğun kar yüzünden havalimanı kapandı; çıkış yapan konuklar valizleriyle lobide bekliyor. Bir konuk sana dönüp sinirli bir sesle “Uçağım ne zaman kalkacak? Hemen söyleyin!” diyor. Elindeki tek bilgi, havalimanının şu an kapalı olduğu.","soru":"Ne dersin?","secenekler":["Bildiğim doğrulanmış bilgiyi söyler, yeni bilgi gelince paylaşacağımı eklerim.","Rahatlasın diye “Merak etmeyin, bir saate kadar açılır” derim.","Bunun otelle ilgisi olmadığını söyler, hava yolunu kendisinin aramasını isterim.","Sosyal medyada az önce gördüğüm bir paylaşımı kesin bilgi gibi aktarırım."],"dogru":0,"aciklama":"Kriz iletişiminde yalnız doğrulanmış bilgi paylaşılır; bilinmeyen şey tahmin edilmez. Boş teselli ve doğrulanmamış haber güveni zedeler, konuğu savmak yardımsever tutuma aykırıdır."},{"id":"os-5-s64","tur":"senaryo","durum":"Saat 11.40. Kat görevlisiyle birlikte, konuğu az önce çıkış için lobiye inen 305 numaralı odayı kontrol ediyorsun. Banyodaki iki bornozdan biri yok. Konuk o sırada resepsiyonda hesabını kapatıyor.","soru":"Ne yaparsın?","secenekler":["Eksiği kat görevlisiyle birlikte hemen ön büroya bildiririm.","Lobiye iner, konuktan valizini açıp göstermesini isterim.","Resepsiyona gidip konuğa bornozu aldığını herkesin önünde söylerim.","Küçük bir şey olduğunu düşünür, eksiği kimseye söylemeden geçerim."],"dogru":0,"aciklama":"Kat görevlisinin işi eksiği fark edip bildirmektir; konuğun valizine bakmak ya da hesap sormak değildir. Nasıl çözüleceğine ön büro yetkilisi karar verir ve konuk suçlanmadan nazikçe çözülür."},{"id":"os-5-s65","tur":"coktan-secmeli","soru":"Gece 04.00 deprem sarsıntısı başladı; resepsiyon görevlisi bankonun yanında. Sarsıntı sürerken ne yapmalıdır?","secenekler":["Konukları uyarmak için merdivenden odalara koşmalıdır.","Asansörle hızla zemin kata inip dışarı çıkmalıdır.","Balkona çıkıp konuklara dışarıdan seslenmelidir.","Sağlam bir eşyanın yanına çöküp başını korumalıdır."],"dogru":3,"aciklama":"Çök-Kapan-Tutun sarsıntı sürerken yapılacak harekettir; koşulmaz, merdivene, balkona ve asansöre yönelinmez. Bina, sarsıntı bittikten sonra merdivenden boşaltılır."},{"id":"os-5-s66","tur":"dogru-yanlis","soru":"Alarm verildikten sonra yangın küçükse, söndürücü eğitimi almamış bir personel de söndürücüyü alıp yangına müdahale etmelidir.","secenekler":["Doğru","Yanlış"],"dogru":1,"aciklama":"Söndürücüyü yalnız eğitimini almış kişi kullanır. Eğitimsiz personelin işi haber vermek, konukları uzaklaştırmak ve ekiplerin yolunu açık tutmaktır."},{"id":"os-5-s67","tur":"coktan-secmeli","soru":"Ali Bey Bodrum paket turunu bir seyahat acentesinden satın alıyor, sonra turun otelinde odasına yerleşiyor. Ders dilinde Ali Bey acente ve otel için sırasıyla nasıl anılır?","secenekler":["Konuk – müşteri","Müşteri – konuk","Müşteri – müşteri","Konuk – konuk"],"dogru":1,"aciklama":"Ücret karşılığı hizmet aldığı acente için müşteri, ağırlandığı otel için konuktur. “Konuk” sözü satın almanın yanında ağırlanmayı da anlatır; acentede ise “müşteri” denir."},{"id":"os-5-s68","tur":"coktan-secmeli","soru":"Aşağıdakilerden hangisi kişiselleştirilmiş hizmetin en basit ve en etkili adımı olarak gösterilir?","secenekler":["Konuğa her karşılaşmada adıyla hitap etmek","Her odaya akşamları aynı meyve sepetini koymak","Odadaki minibarı ücretsiz yapmak","Bütün konuklara aynı karşılama içeceğini sunmak"],"dogru":0,"aciklama":"Adıyla hitap, konuğa “Beni tanıyorlar” dedirten en basit kişiselleştirmedir. Herkese aynı sepeti ya da içeceği sunmak ise kalıp hizmettir, kişiye göre uyarlanmış değildir."},{"id":"os-5-s69","tur":"coktan-secmeli","soru":"Bebek arabasıyla gelen ailenin kapıda zorlandığını gören görevli, aile bir şey istemeden kapıyı açık tutuyor ve asansörü çağırıyor. Bu davranış hangi kavrama örnektir?","secenekler":["Hizmet telafisi","Kişiselleştirilmiş hizmet","Beklenti oluşmadan sunma","Sorunu sahiplenme"],"dogru":2,"aciklama":"Görevli ihtiyacı aile istemeden fark edip hizmeti kendiliğinden sunmuştur. Hizmet telafisi ise yaşanmış bir aksaklıktan sonra konuğun gönlünü almaktır; burada bir aksaklık yoktur."},{"id":"os-5-s70","tur":"coktan-secmeli","soru":"Bir tesis, işitme engelli konukların yangın alarmını fark edebilmesi için erişilebilir odalara hangisini koymalıdır?","secenekler":["Braille yazılı kat tabelası","Tutunma barı","Panik butonu","Işıklı uyarı sistemi"],"dogru":3,"aciklama":"Işıklı uyarı, alarmı sesle birlikte yanıp sönen ışıkla da verir; işitme engelli konuk tehlikeyi böyle fark eder. Braille tabela ise görme engelli konuğun yolunu bulmasına yardım eder."},{"id":"os-5-s71","tur":"coktan-secmeli","soru":"Tesiste rampa ve asansör olduğu hâlde resepsiyon görevlisi, erişilebilir yolu soran engelli konuğa “Bilmiyorum, bir sorayım” diyor. Bu cevap neden yanlıştır?","secenekler":["Konuğa bu otelde kendisinin düşünülmediğini hissettirdiği için","Rampanın yerini yalnız teknik servisin bilmesi gerektiği için","Engelli konuğa yol tarifi yapmak personelin işi olmadığı için","Konuğun bu bilgiyi rezervasyon sırasında öğrenmiş olması gerektiği için"],"dogru":0,"aciklama":"Personel rampa, asansör ve erişilebilir oda imkânlarını ezbere bilmelidir; bilmemek konuğa düşünülmediğini hissettirir. Bilgiyi teknik servise ya da rezervasyona bırakmak bu eksikliği gidermez."},{"id":"os-5-s72","tur":"coktan-secmeli","soru":"Aşağıdaki davranışlardan hangisi proaktif bir yaklaşımdır?","secenekler":["Klima arızasını konuk şikâyet ettikten sonra bildirmek","Konuk gelmeden odayı yeniden kontrol edip eksiği gidermek","Konuğun sorununu ikinci kez sorduğunda ele almak","Bozuk lambayı konuk çıkış yaptıktan sonra değiştirmek"],"dogru":1,"aciklama":"Proaktif personel sorun çıkmadan ya da konuk istemeden harekete geçer. Şikâyetten sonra bildirmek, sorun büyüyene kadar beklemek demek olan tepkisel davranıştır."},{"id":"os-5-s73","tur":"coktan-secmeli","soru":"Tatil köyündeki bir konuk her gün küçük aksaklıklardan yakınıyor. Bu konuğa yaklaşımda aşağıdakilerden hangisi yanlıştır?","secenekler":["Her şikâyetini not alıp ayrı ayrı kayda geçirmek","Sabırla dinleyip her biri için somut çözüm sunmak","Haksız olduğunu göstermek için tartışmaya girmek","Empati kurup çözüm odaklı bir tutum takınmak"],"dogru":2,"aciklama":"Sürekli şikâyet eden konukla tartışmaya girmek yanlıştır. Şikâyetlerinin kayda geçmesi ise doğrudur, çünkü bunlardan biri gerçek bir sorunu gösterebilir."},{"id":"os-5-s74","tur":"coktan-secmeli","soru":"Ders kitabının “ilk otuz saniye” ifadesiyle asıl anlatmak istediği nedir?","secenekler":["Karşılamanın en fazla otuz saniye sürmesi gerektiği","Otuz saniyeden uzun bekletilen konuğun mutlaka şikâyet edeceği","Giriş işleminin otuz saniyede bitirilmesi gerektiği","İlk izlenimin çok çabuk oluştuğu ve ikinci kez kurulamadığı"],"dogru":3,"aciklama":"Otuz saniye kesin bir ölçü değildir; vurgulanan, ilk izlenimin çok kısa sürede oluşması ve sonradan geri alınamamasıdır. Karşılamanın ya da girişin süresiyle ilgili bir kural değildir."},{"id":"os-5-s75","tur":"coktan-secmeli","soru":"Konuk girişini otele gelmeden telefonundan yapmak istiyor ve otelin çevreci uygulamalarını soruyor. Bu konuk hangi tipe girer?","secenekler":["Şüpheci konuk","Yeni nesil konuk","Titiz ve eleştirel konuk","Kararsız konuk"],"dogru":1,"aciklama":"İşlemlerini telefondan yapmaya alışkın olup çevreye duyarlılığı önemseyen konuk yeni nesil konuktur. Titiz konuk ise hizmetteki küçük kusurlara odaklanır; burada öyle bir durum yoktur."},{"id":"os-5-s76","tur":"coktan-secmeli","soru":"Havuz barındaki garsona bir konuk, odasındaki duşun akmadığını söylüyor. Garsonun doğru davranışı hangisidir?","secenekler":["Oda numarasını alıp sorunu hemen ön büroya bildirmek","“Bu benim bölümüm değil, resepsiyona söyleyin” demek","Konuğa teknik servisin dahili numarasını vermek","Vardiyası bitince durumu bir arkadaşına anlatmak"],"dogru":0,"aciklama":"Şikâyeti kim aldıysa sorunu sahiplenir, doğru kişiye ulaştırır ve sonucunu izler. Konuğu resepsiyona ya da teknik servise yollamak sorunu ikiye katlar, çünkü konuk tek bir otel görür."},{"id":"os-5-s77","tur":"coktan-secmeli","soru":"Balık kılçığı diyagramının bir sorunu inceleyen ekibe sağladığı en önemli yarar hangisidir?","secenekler":["Şikâyetçi konuğun adını ve oda numarasını kaydetmesi","Hatayı yapan personeli bulup cezalandırmayı kolaylaştırması","Olası bütün nedenleri bir arada görmeyi sağlaması","Sorunu yalnız tek bir başlıkta toplaması"],"dogru":2,"aciklama":"Diyagram nedenleri başlıklar altında toplar; ekip tek bir nedene takılmadan hepsini aynı anda görür. Sorunu tek başlıkta toplamak ise tam da önlemeye çalıştığı şeydir."},{"id":"os-5-s78","tur":"coktan-secmeli","soru":"Aksaklık yaşayan konuğun odasına müdürün kendi el yazısıyla yazdığı bir özür notu bırakılıyor. Bu notu hazır basılmış bir karttan daha etkili yapan nedir?","secenekler":["Konuğa ücret iadesi yapılacağını yazılı olarak garanti etmesi","Hatayı hangi personelin yaptığını açıkça belirtmesi","Bir sonraki konaklamada indirim kuponu yerine geçmesi","Konuğa yalnız ona yazıldığını ve özel olduğunu hissettirmesi"],"dogru":3,"aciklama":"Basılı kart herkese gider, el yazısı yalnız o konuğa yazılmıştır; müdürün imzası sorunun en üst düzeyde ciddiye alındığını da gösterir. Not bir iade ya da indirim taahhüdü değildir."},{"id":"os-5-s79","tur":"coktan-secmeli","soru":"Otelin internet sitesinde odayı anlatan ifadelerden hangisi yanlış beklenti oluşturma riskini en aza indirir?","secenekler":["Geniş ve ferah odalar","28 metrekare, balkonlu odalar","Denize çok yakın, lüks odalar","Herkesin beğeneceği konforlu odalar"],"dogru":1,"aciklama":"“Geniş”, “yakın”, “lüks” gibi sözcükleri herkes farklı anlar; ölçü ve somut bilgi ise olanı olduğu gibi gösterir. Bu yüzden metrekare yazılan ifade yanlış beklentiyi önler."},{"id":"os-5-s80","tur":"coktan-secmeli","soru":"Personel kapısının kilitli olması ve kapının yalnız tanımlı kartla açılıp her açılışın kayda geçmesi, konuk güvenliği tedbirlerinin hangi başlığına girer?","secenekler":["Fiziksel ve elektronik güvenlik","Veri ve bilgi güvenliği","Acil durum ve yaşam güvenliği protokolü","Gıda güvenliği önlemi"],"dogru":0,"aciklama":"Kilitli kapı fiziksel engeldir, kartla açılış ve kayıt ise elektronik izlemedir; ikisi birlikte bu başlığı oluşturur. Veri güvenliği konuğun kimlik ve kart bilgilerini korumakla ilgilidir."},{"id":"os-5-s81","tur":"coktan-secmeli","soru":"Gece mutfakta gaz dedektörü ötüyor. Görevlinin doğru davranışı hangisidir?","secenekler":["Kaynağı bulmak için ocakları tek tek kendisi kontrol etmek","Sık yanlış alarm verdiği için dedektörü susturup işine dönmek","Kokunun geçmesi için mutfakta biraz daha beklemek","Alandan çıkıp güvenliğe ve teknik servise haber vermek"],"dogru":3,"aciklama":"Gaz kaçağında yangın ve patlama riski vardır; görevli alandan çıkar, haber verir ve alana kimseyi sokmaz. Kaynağı kendisi aramak onu tehlikenin tam ortasında bırakır."},{"id":"os-5-s82","tur":"coktan-secmeli","soru":"Kat görevlisi, prize takılı arızalı bir cihaza dokunan arkadaşının elektriğe kapıldığını görüyor. İlk yapması gereken hangisidir?","secenekler":["Arkadaşını hemen tutup cihazdan çekerek uzaklaştırmak","Önce elektriği şalterden kestirip 112’yi aramak","Arkadaşının üzerine su döküp onu ayıltmaya çalışmak","Cihazın fişini çıplak elle hızla prizden çekmek"],"dogru":1,"aciklama":"Akım kesilmeden kazaya uğrayan kişiye dokunulmaz; yoksa yardım eden de çarpılır. Bu yüzden önce elektrik şalterden kestirilir, ardından 112 aranır."},{"id":"os-5-s83","tur":"coktan-secmeli","soru":"Lobide bir konuk aniden bayılıyor. 112’nin aranmasıyla ilgili hangisi doğrudur?","secenekler":["Önce genel müdürün izni alınmalı, sonra aranmalıdır.","Konuk kendine gelirse gerek kalmayacağı için beklenmelidir.","Hemen aranmalı, aynı anda yöneticiye de haber verilmelidir.","Yalnız tesis doktoru izin verirse aranmalıdır."],"dogru":2,"aciklama":"Bayılma acil belirtilerdendir; hayatı tehdit eden durumda 112 için izin beklenmez. Arama yapılırken yöneticiye de aynı anda haber verilir."},{"id":"os-5-s84","tur":"coktan-secmeli","soru":"Lobi barında ayakta zor duran ve yüksek sesle konuşan konuğa barmen servisi kesti. Bundan sonra yapılması gereken hangisidir?","secenekler":["Durum diğer konuklara yüksek sesle açıklanır.","Konuk barda yalnız bırakılır.","Konukla tartışılıp davranışının yanlışlığı anlatılır.","Konuğun odasına güvenle ulaşması sağlanır."],"dogru":3,"aciklama":"İş servisi kesmekle bitmez; konuğun odasına güvenle ulaşması sağlanır, gerekirse sağlık yardımı çağrılır. Konuğu utandırmak ya da onunla tartışmak ise doğru değildir."},{"id":"os-5-s85","tur":"coktan-secmeli","soru":"Çıkış yapan konuğun banyoda unuttuğu saati kat görevlisi buluyor. Kayıp ve bulunmuş eşya sistemine göre ne yapılmalıdır?","secenekler":["Kat şefine haber verip saati deftere kaydettirmek","Saati cebine koyup sonra teslim etmek","Konuğun peşinden otoparka koşup saati yetiştirmek","Saati çekmeceye koyup konuk arayana kadar beklemek"],"dogru":0,"aciklama":"Bulunan eşya kayıt defterine yazılarak izlenir; böylece ortada kalmaz, kaybolması ya da çalınması önlenir. Kayda geçmeyen eşyanın nerede olduğu izlenemez."},{"id":"os-5-s86","tur":"coktan-secmeli","soru":"Koridorda sahipsiz ve şüpheli bir çanta bulundu. Şüpheli paket prosedürüne göre aşağıdakilerden hangisi doğrudur?","secenekler":["Güvenliği paketin hemen yanından cep telefonuyla aramak","Paketi kimsenin olmadığı boş bir odaya taşımak","Çevreyi boşaltıp girişleri şeritle kapatmak","Paketi açıp içine bakmak"],"dogru":2,"aciklama":"Güvenlik çevreyi boşaltır, girişler şeritle kapatılır ve nöbetçi bırakılır. Paketin yakınında telsiz ve cep telefonu kullanılmaz; aramalar paketten uzakta yapılır."},{"id":"os-5-s87","tur":"coktan-secmeli","soru":"Tahliyeden sonra toplanma alanındaki sayımda bir konuğun eksik olduğu anlaşılıyor. Doğru davranış hangisidir?","secenekler":["Bir personeli hemen binaya gönderip odayı aratmak","Eksik konuğun bilgisini itfaiye ekibine vermek","Alarm bitene kadar kimseye söylemeden beklemek","Sayımı bitirip eksik konuğu sonradan rapora yazmak"],"dogru":1,"aciklama":"Eksik kişiyi aramak için binaya personel girmez; bilgi olay yerindeki ekibe verilir. Personeli içeri göndermek ikinci bir kişiyi de tehlikeye atar."},{"id":"os-5-s88","tur":"coktan-secmeli","soru":"Valilik “Sabaha kadar dışarı çıkılmasın” kararı yayımladı. Bu talimatı konuklara aktaran personelin doğru tutumu hangisidir?","secenekler":["Korkutmamak için talimatı biraz yumuşatarak aktarmak","Yalnız soran konuklara talimattan söz etmek","Yorum katmadan, herkese aynı sözlerle duyurmak","Önemini abartarak konukları sert biçimde uyarmak"],"dogru":2,"aciklama":"Talimat herkese aynı anda ve aynı sözlerle ulaşmalıdır, yoksa söylenti başlar. Personel talimatı yumuşatmaz da abartmaz da; yabancı konuklara anlayacakları dilde yinelenir."},{"id":"os-5-s89","tur":"coktan-secmeli","soru":"Orman yangını tesise yaklaşıyor ve konukların güvenli bir yere götürülmesi gerekiyor. Konukların nereye götürüleceğine kim karar verir?","secenekler":["Tesisin genel müdürü","Her konuğun kendisi","Tesisin güvenlik müdürü ve ekibi","Kaymakamlık ya da valilik"],"dogru":3,"aciklama":"Geçici barınma ve sevkte nereye gidileceğine tesis değil, mülki idare karar verir. Personel ise konuklara eşlik eder ve kimin nereye gittiğini liste üzerinden izler."},{"id":"os-5-s90","tur":"dogru-yanlis","soru":"Konuk tercih kaydında konuğun istek ve alışkanlıklarının yanında önceki konaklamalarında yaşadığı sorunlar da tutulur.","secenekler":["Doğru","Yanlış"],"dogru":0,"aciklama":"Tercih kaydı istekleri, alışkanlıkları ve yaşanan sorunları saklar. Kayıt tutulmazsa aynı hata aynı konuğa ikinci kez yapılır."},{"id":"os-5-s91","tur":"dogru-yanlis","soru":"Asansör düğmelerindeki Braille (kabartma) yazı, görme engelli konuğun kat numarasını yardım istemeden bulmasını sağlar.","secenekler":["Doğru","Yanlış"],"dogru":0,"aciklama":"Braille, parmakla okunan kabartma noktalardan oluşur. Asansör düğmesinde ve tabelada bulunması görme engelli konuğun bağımsız hareket etmesini sağlar."},{"id":"os-5-s92","tur":"dogru-yanlis","soru":"Bir otelde sık gelen konuk sayısının çok olması, o işletmenin saygınlığını gösterir.","secenekler":["Doğru","Yanlış"],"dogru":0,"aciklama":"Memnun kalmayan konuk geri gelmez; bu yüzden tekrar tekrar gelen sadık konukların çokluğu işletmenin saygınlığının göstergesidir."},{"id":"os-5-s93","tur":"dogru-yanlis","soru":"Tahliyede herkesin aynı toplanma alanında buluşması, eksik kişinin hemen anlaşılmasını ve ekiplere doğru bilgi verilmesini sağlar.","secenekler":["Doğru","Yanlış"],"dogru":0,"aciklama":"Toplanma alanı önceden belirlenmiş tek bir güvenli yer olduğu için sayım orada yapılır; eksik olan hemen fark edilir ve bilgi ekiplere aktarılır."},{"id":"os-5-s94","tur":"dogru-yanlis","soru":"VVIP kategorisi her otelde bulunur ve kimin bu gruba gireceğini kanun belirler.","secenekler":["Doğru","Yanlış"],"dogru":1,"aciklama":"Her otelde VVIP kategorisi bulunmaz; kimin VVIP sayılacağına işletmenin kendisi karar verir."},{"id":"os-5-s95","tur":"dogru-yanlis","soru":"Karşılamada doğru cümleyi kurmak yeterlidir; cümlenin hangi yüz ifadesiyle söylendiği konuğun izlenimini değiştirmez.","secenekler":["Doğru","Yanlış"],"dogru":1,"aciklama":"Karşılama sanatı beden dili, ses tonu ve sözcüklerin uyumuna dayanır. Güzel bir cümle ilgisiz bir yüzle söylenirse boşa gider."},{"id":"os-5-s96","tur":"dogru-yanlis","soru":"Aksaklık yaşayan konuğa gelecek konaklama için indirim kuponu verme kararını resepsiyon görevlisi kendi başına verebilir.","secenekler":["Doğru","Yanlış"],"dogru":1,"aciklama":"Gelecek konaklama için indirim kuponu gibi bir telafiye personel değil, yönetim karar verir."},{"id":"os-5-s97","tur":"dogru-yanlis","soru":"Personelin ilgisizliğinden doğan memnuniyetsizlik, teknik bir arızadan doğan memnuniyetsizliğe göre daha kolay onarılır.","secenekler":["Doğru","Yanlış"],"dogru":1,"aciklama":"Teknik arıza affedilir, ilgisizlik kolay affedilmez. Personelden kaynaklanan aksaklık konukla kurulan duygusal bağı koparır; onu onarmak bir klimayı onarmaktan zordur."}],"siralamalar":[{"id":"os-5-r01","konu":"5.1.4","baslik":"Kliması soğutmayan oda: LEARN ile çözüm","yonerge":"Kliması çalışmadığı için öfkeyle resepsiyona gelen konuğa LEARN modeliyle yaklaşırken izleyeceğin adımları doğru sıraya koy.","adimlar":["Konuğu sözünü kesmeden, göz teması kurarak sonuna kadar dinle.","Ne hissettiğini anladığını göster: “Bu sıcakta çok yorulmuşsunuz, sizi anlıyorum.”","Yaşanan aksaklık için işletme adına içtenlikle özür dile.","Klimanın onarılması ya da başka bir odaya geçiş gibi somut bir çözüm öner.","Konuk beklerken teknik servisi ara ve çözümü hiç ertelemeden uygulamaya koy."],"aciklama":"LEARN; Listen (dinle), Empathise (empati kur), Apologise (özür dile), React (çözüm üret) ve Now (hemen yap) adımlarından oluşur. Konuk dinlendiğini ve anlaşıldığını hissetmeden çözüm konuşulmaz; bulunan çözüm de ertelenmeden uygulanır."},{"id":"os-5-r02","konu":"5.2.2","baslik":"Koridorda duman: R.A.C.E. sırası","yonerge":"Kat koridorunda yangın fark eden görevli olarak R.A.C.E. protokolünün adımlarını doğru sıraya koy.","adimlar":["Yangın alanındaki herkesi, hareket etmekte zorlananlardan başlayarak güvenli bir bölgeye al.","En yakın yangın ihbar butonuna bas ya da santrali arayıp yangının tam yerini bildir.","Yangının ve dumanın yayılmasını yavaşlatmak için kapı ve pencereleri kapat, ama asla kilitleme.","Yangın küçükse söndürmeye çalış; kontrol edilemiyorsa binayı hemen boşalt."],"aciklama":"R.A.C.E.; Rescue (kurtar), Alarm (alarm ver), Confine (sınırla) ve Extinguish / Evacuate (söndür ya da tahliye et) demektir. Can güvenliği her şeyden önce gelir; yangın bildirilir, yayılması yavaşlatılır ve söndürme ya da tahliye kararı en sonda verilir."},{"id":"os-5-r03","konu":"5.2.2","baslik":"Asansörün yanında sahipsiz bir çanta","yonerge":"Kat koridorunda sahipsiz ve şüpheli bir çanta gördüğünde uygulanacak prosedürün adımlarını doğru sıraya koy.","adimlar":["Çantaya dokunmadan ve yerinden oynatmadan en yakın güvenlik birimine ya da yönetime haber ver.","Çevredeki en az 100 metrelik alanı boşalt, girişleri şeritle kapat ve nöbetçi bırak.","Bomba imha ekibi geldiğinde alanı onlara devret ve gereken yerlerde yol göster.","Olay bittiğinde tüm süreci saatleri ve ayrıntılarıyla tutanağa geçir."],"aciklama":"Paketi bulan kişi kahramanlık yapmaz, yalnız haber verir; can güvenliği için alan boşaltılıp kapatılır, bu sırada yönetim 112’yi arar ve yakındaki telsiz ve telefonlar kapatılır. Müdahaleyi yalnız uzman ekip yapar; tutanak yasal kanıt olarak en sonda yazılır."}],"acikSorular":[{"id":"os-5-y01","konu":"5.1.4","soru":"Sabah vardiyasında resepsiyonda çalışıyorsunuz. Bir konuk, odasının klimasının çalışmadığını ve geceyi çok sıcakta geçirdiğini yüksek sesle söylüyor. LEARN modelinin adımlarını sırasıyla yazınız ve her adımda konuğa nasıl davranacağınızı açıklayınız.","olcut":[{"metin":"LEARN modelinin beş adımını doğru sırayla yazar (dinle, empati kur, özür dile, çözüm üret, hemen yap).","puan":20},{"metin":"Dinleme adımında konuğun sözünü kesmeden, göz teması kurarak dinlediğini belirtir.","puan":15},{"metin":"Empati kurma ve özür dileme adımlarını konuğa söylenecek cümlelerle örneklendirir.","puan":20},{"metin":"Çözüm üretme ve hemen yapma adımlarında somut bir çözüm (oda değişikliği, teknik servis) verir ve ertelemeden uygulayacağını belirtir.","puan":15},{"metin":"Modelin amacını, yani konuğun duygusunu sakinleştirmenin ve sorunu sahiplenmenin şikâyeti çözmedeki önemini açıklar.","puan":30}],"ornek":"LEARN modelinin adımları sırasıyla şunlardır: dinle, empati kur, özür dile, çözüm üret, hemen yap. Önce konuğu sözünü kesmeden, göz teması kurarak sonuna kadar dinlerim. Sonra “Sıcak bir odada uyumak gerçekten çok zor, sizi anlıyorum” derim ve yaşadığı durum için içtenlikle özür dilerim. Ardından teknik servisi göndermeyi ya da kliması çalışan başka bir odayı önermeyi çözüm olarak sunarım ve bunu konuk beklerken hemen uygularım. Bu sıra konuğun öfkesini sakinleştirir ve sorunu sahiplendiğimi gösterir; iyi çözülen bir şikâyet konuğu işletmeye bağlayabilir.","ipucu":"Konuğun önce neye ihtiyaç duyduğunu düşünün: duygusu mu, çözümü mü, ve bu ikisinin sırası ne olmalı?"},{"id":"os-5-y02","konu":"5.2.2","soru":"Kat görevlisi olarak çalışırken dördüncü kat koridorunda duman fark ediyorsunuz. R.A.C.E. protokolünün dört adımını sırasıyla yazınız ve her adımda ne yapacağınızı açıklayınız.","olcut":[{"metin":"R.A.C.E. protokolünün dört adımını doğru sırayla yazar (kurtar, alarm ver, sınırla, söndür ya da tahliye et).","puan":20},{"metin":"Kurtar adımında önce tehlikedeki kişileri, özellikle hareket kabiliyeti kısıtlı olanları güvenli bölgeye alacağını belirtir.","puan":20},{"metin":"Alarm ver adımında yangın ihbar butonuna basacağını ya da santrali arayıp yangının yerini söyleyeceğini açıklar.","puan":15},{"metin":"Sınırla adımında kapı ve pencereleri kapatarak dumanın ve yangının yayılmasını yavaşlatacağını belirtir.","puan":15},{"metin":"Yangının küçük ya da kontrol edilemez olmasına göre söndürme ya da tahliye kararını gerekçesiyle açıklar.","puan":30}],"ornek":"R.A.C.E. protokolünün adımları sırasıyla kurtar, alarm ver, sınırla, söndür ya da tahliye et şeklindedir. Önce koridordaki konukları, özellikle tekerlekli sandalyedeki ya da yardıma ihtiyacı olanları dumandan uzağa, güvenli bir bölgeye alırım. Sonra en yakın yangın ihbar butonuna basar ya da santrale yangının yerini bildiririm. Ardından kapı ve pencereleri kapatarak dumanın yayılmasını geciktiririm. Yangın küçükse eğitimli kişi söndürücüyle söndürür; kontrol edilemiyorsa kimse oyalanmaz ve bina tahliye edilir, çünkü can güvenliği her zaman önce gelir.","ipucu":"Adımların sırasını neyin belirlediğini düşünün: yangında en değerli ve geri getirilemeyen şey nedir?"}]},{"ders":"otelcilik-seyahat","sinif":9,"unite":6,"baslik":"Astlarla İlgili Çalışmalar","onay":true,"kazanimlar":["Yönetsel sorumlulukları yerine getirir.","Personelin moral ve motivasyonunu artırmaya yönelik yöntemleri uygular.","Denetim işlemlerini yapar."],"soz":"Ekibini gören yönetici, konuğunu gören ekip yetiştirir.","dersler":[{"baslik":"Müdür Olmak Bir Unvan mı?","ilk":"os-6-001"},{"baslik":"Yöneticinin Gördüğü İş","ilk":"os-6-005"},{"baslik":"“Yetkili Arkadaşımı Çağırıyorum”","ilk":"os-6-009"},{"baslik":"Toplantı Zaman Kaybı mı?","ilk":"os-6-013"},{"baslik":"Söz Uçar, Tutanak Kalır","ilk":"os-6-017"},{"baslik":"Yazılmayan İş Yapılmamış Sayılır","ilk":"os-6-022"},{"baslik":"O Belge Nerede?","ilk":"os-6-025"},{"baslik":"Gülümsemenin Arkasında Ne Var?","ilk":"os-6-030"},{"baslik":"Bir “Eline Sağlık” Ne Değiştirir?","ilk":"os-6-035"},{"baslik":"Fikrini Soran Müdür","ilk":"os-6-039"},{"baslik":"Fazla Mesainin Grafiği","ilk":"os-6-083"},{"baslik":"Denetim Hata Avı mıdır?","ilk":"os-6-044"},{"baslik":"Konuk Ne Diyor, Işık Neden Yanıyor?","ilk":"os-6-047"},{"baslik":"Otel Hiç Uyumaz","ilk":"os-6-051"},{"baslik":"S, A, G, N: Günün Dört Dilimi","ilk":"os-6-054"},{"baslik":"Kanun Ne Diyor?","ilk":"os-6-059"},{"baslik":"Bankoyu Devretmeden Çıkma","ilk":"os-6-062"},{"baslik":"Kartını Okuttun mu?","ilk":"os-6-064"},{"baslik":"Karne Değil, Yol Haritası","ilk":"os-6-069"},{"baslik":"Zayıf Yön Değil, Gelişim Alanı","ilk":"os-6-072"}],"kavramlar":[{"id":"os-6-001","konu":"6.1","terim":"Yönetici","ingilizce":"Manager","tanim":"Turizm işletmesinde bir ekibi yönlendiren, kararlar alan ve bu kararların sonuçlarından sorumlu olan kişidir.","ornek":"Sabah 08.30, İstanbul’da bir şehir oteli: tur otobüsü erken gelince resepsiyonda sıra oluşur. Ön büro müdürü öne çıkar; birine bagajları, birine ikramı, stajyere de konukları karşılamayı verir.","sektor":"Yöneticilik bir unvandan ibaret değildir: sorumluluk almak, örnek olmak ve ekibi ortak hedefe yöneltmektir. Sektörde “müdür” ya da “menajer” de denir. Stajyer için yönetici, işin nasıl yapılacağını soracağı ve gördüğü sorunu bildireceği kişidir.","iliskili":["os-6-002","os-6-003","os-6-005"],"kontrol":null,"cizim":"lider"},{"id":"os-6-002","konu":"6.1","terim":"Ast","ingilizce":"Subordinate","tanim":"Bir yöneticinin sorumluluğu altında çalışan ve kendisine verilen işleri yerine getiren kişidir.","ornek":"Resepsiyon görevlisi ön büro müdürünün, kat görevlisi kat şefinin astıdır; stajyer de staj yaptığı bölümün şefine bağlıdır.","sektor":"Ast olmak küçük görülmek değildir: konuğu karşılayan, odayı hazırlayan, turu gezdiren çoğu zaman asttır ve işletmenin başarısına doğrudan katkı verir. Yönetici de kendi üstünün astıdır. İyi yönetici olmanın yolu, önce iyi bir ekip üyesi olmaktan geçer.","iliskili":["os-6-001","os-6-003","os-6-004"],"kontrol":null,"cizim":"ekip"},{"id":"os-6-003","konu":"6.1","terim":"Amir","ingilizce":"Line manager (supervisor)","tanim":"Çalışanın doğrudan bağlı olduğu, ondan talimat aldığı ve işiyle ilgili ilk başvurduğu yöneticidir.","ornek":"Stajının ilk günü, kat ofisi: müdür “Senin amirin kat şefi; izin, soru, sorun, hepsi için önce ona gideceksin.” der.","sektor":"Aynı anlamda “ilk amir” ya da “bağlı olunan üst” de denir. Stajyerin amiri çoğu zaman müdür değil, vardiya şefidir. Bir sorun gördüğünde, bir şeyden emin olmadığında ya da izin isteyeceğinde ilk adres odur; amirinin kim olduğunu ilk gün öğrenirsin.","iliskili":["os-6-002","os-6-001","os-6-012"],"kontrol":null,"kitapDisi":true,"cizim":"lider"},{"id":"os-6-004","konu":"6.1","terim":"Astlarla ilgili çalışmalar","ingilizce":"Staff management","tanim":"Yöneticinin ekibine görev dağıtma, toplantı yapma, onu motive etme, işini denetleme, performansını değerlendirme ve raporlama işlerinin bütünüdür.","ornek":"Resepsiyon şefi sabah görevleri paylaştırır, öğlen bankoyu gözlemler, akşam iyi çalışan görevlisine teşekkür eder: üçü de bu çalışmaların parçasıdır.","sektor":"Yönetici burada hem teknik bilgisini hem insan ilişkilerindeki becerisini kullanır. Hizmeti makine değil insan verir; yöneticinin ekibiyle kurduğu ilişki, konuğun gördüğü hizmetin kalitesini belirler.","iliskili":["os-6-001","os-6-002","os-6-007"],"kontrol":null,"cizim":"ekip"},{"id":"os-6-005","konu":"6.1","terim":"Yönetsel sorumluluklar","ingilizce":"Managerial responsibilities","tanim":"Yöneticinin yalnız kârı artırmakla kalmayıp hizmet kalitesini yükseltme, çalışanlarını geliştirme ve işletmenin marka değerini koruma yükümlülükleridir.","ornek":"Dolu geçen bir hafta sonunun ardından ön büro müdürü yalnız gelire bakmaz: konuk yorumlarını okur, yeni başlayan görevlinin hangi konuda eğitime ihtiyacı olduğunu not eder.","sektor":"Turizm konuk memnuniyetine dayanır; bugün kâr edip konuğunu ve çalışanını kaybeden otel yarın boş kalır. Toplantı düzenlemek, rapor ve dosya düzenini kurmak bu sorumlulukların günlük hayattaki karşılığıdır.","iliskili":["os-6-001","os-6-006","os-6-013","os-6-022"],"kontrol":null},{"id":"os-6-006","konu":"6.1","terim":"Yönetimin fonksiyonları","ingilizce":"Functions of management","tanim":"Yöneticinin işini oluşturan planlama, örgütleme, yönlendirme ve kontrol adımlarıdır.","ornek":"Bayram haftası için kat şefi önce kaç odanın çıkacağını hesaplar (planlama), ekibi katlara böler (örgütleme), sabah görevleri anlatır (yönlendirme), öğlen odaları dolaşır (kontrol).","sektor":"Turizmde yöneticilik bu dört adımla bitmez: insan davranışını anlamak, çalışanı isteklendirmek ve kuruma bağlılığı güçlendirmek de işin parçasıdır. Çünkü planı kâğıt değil, insanlar uygular.","iliskili":["os-6-005","os-6-007","os-6-044"],"kontrol":null,"cizim":"lider"},{"id":"os-6-076","konu":"6.1","terim":"Yönetim tarzı","ingilizce":"Management style","tanim":"Yöneticinin ekibiyle ilişki kurma, iletişim sağlama ve onları motive etme biçimini belirleyen genel yönetim yaklaşımıdır.","ornek":"Pazartesi 08.30 toplantısında ön büro müdürü yalnız görev dağıtmaz; ekibine hafta sonunun nasıl geçtiğini sorar, yoğun günlerin yükünü nasıl paylaşacaklarını birlikte konuşur.","sektor":"Ders kitabına göre etkin yönetimde yönetim tarzı ön plandadır: planlama, örgütleme, yönlendirme ve kontrol gibi klasik fonksiyonların yanında insan davranışını anlamak, motivasyonu artırmak ve kuruma bağlılığı güçlendirmek gerekir. Astlarla kurulan ilişki örgüt içi iletişimi, iş tatminini, performansı ve verimliliği doğrudan etkiler.","iliskili":["os-6-006","os-6-008","os-6-031"],"kontrol":null,"cizim":"lider"},{"id":"os-6-007","konu":"6.1","terim":"Görev dağılımı","ingilizce":"Task allocation","tanim":"Yapılacak işlerin, kimin hangi işi ne zamana kadar yapacağı belli olacak biçimde ekip üyeleri arasında paylaştırılmasıdır.","ornek":"Sabah 08.00, kat ofisi: kat şefi iki görevliye üçüncü katı, iki görevliye dördüncü katı verir; stajyeri de deneyimli bir görevlinin yanına yazar.","sektor":"Görev açık değilse aynı iş iki kez yapılır ya da hiç yapılmaz. Dengeli dağılım motivasyonu da korur: hızlı çalışana hep daha fazla iş yüklemek, iyi çalışanı cezalandırmak anlamına gelir.","iliskili":["os-6-004","os-6-006","os-6-010"],"kontrol":null,"cizim":"doga"},{"id":"os-6-008","konu":"6.1","terim":"Liderlik","ingilizce":"Leadership","tanim":"Yöneticinin ekibini yalnız talimatla değil, örnek olarak ve güven vererek ortak hedefe yöneltmesidir.","ornek":"Yoğun bir giriş saatinde ön büro müdürü odasında oturmaz; bankoya geçer, konuk karşılar, sıra eriyince ekibine teşekkür eder.","sektor":"Ekip, yöneticinin söylediğinden çok yaptığına bakar: kendisi geç kalan şef ekibinden dakiklik bekleyemez. Sabır, ekip çalışması ve insana değer vermek, turizmde işi doğru yapmak kadar önemlidir.","iliskili":["os-6-001","os-6-005","os-6-021"],"kontrol":null,"cizim":"lider"},{"id":"os-6-009","konu":"6.1","terim":"Yetki","ingilizce":"Authority","tanim":"Bir görevlinin, işinin gereği olarak karar verme, talimat verme ya da bir işlemi yapma hakkıdır.","ornek":"Saat 14.00, resepsiyon: konuk fiyatta indirim ister. Stajyer “Bu konuda yetkili arkadaşımı çağırıyorum efendim.” der ve resepsiyon şefine haber verir.","sektor":"Otelde herkesin yetkisi bellidir: indirimi, oda değişikliğini, ücretsiz ikramı kimin onaylayacağı önceden tanımlanır. Yetkisi olmayan bir konuda söz vermek, tutulamayacak bir söz vermektir; doğrusu konuğu bekletmeden yetkili kişiye haber vermektir.","iliskili":["os-6-010","os-6-011","os-6-012"],"kontrol":null,"kitapDisi":true,"cizim":"lider"},{"id":"os-6-010","konu":"6.1","terim":"Sorumluluk","ingilizce":"Responsibility","tanim":"Kişinin üstlendiği işi zamanında ve doğru yapma, sonucunun hesabını verebilme yükümlülüğüdür.","ornek":"Stajyere lobideki broşür standını düzenli tutma görevi verilir; akşam stand dağınıksa bunun hesabını o verir.","sektor":"Yetki ile sorumluluk birlikte yürür: karar verme hakkı olan, sonucunu da üstlenir. Performans değerlendirmede sorumluluk bilinci ilk bakılan ölçütlerdendir. Hata yaptığında bunu saklamak yerine amirine söyleyen çalışan sorumluluk sahibidir.","iliskili":["os-6-009","os-6-011","os-6-071"],"kontrol":null,"cizim":"lider"},{"id":"os-6-011","konu":"6.1","terim":"Yetki devri (delegasyon)","ingilizce":"Delegation","tanim":"Yöneticinin, kendi yetkisindeki bir işi ve o işle ilgili karar hakkını astına bırakmasıdır.","ornek":"Ön büro müdürü toplantıya girerken resepsiyon şefine “Ben çıkana kadar oda değişikliklerine sen karar ver.” der.","sektor":"Yönetici her işe kendisi yetişemez; iş devredilince hem hız artar hem ast gelişir. İş devredilir, ama sonucun sorumluluğu yöneticide kalmaya devam eder. Sana bir iş devredildiyse sınırını sor: nereye kadar kendin karar vereceksin, hangi durumda haber vereceksin?","iliskili":["os-6-009","os-6-010","os-6-007"],"kontrol":null,"kitapDisi":true,"cizim":"lider"},{"id":"os-6-012","konu":"6.1","terim":"Emir komuta zinciri","ingilizce":"Chain of command","tanim":"Talimatların üstten asta, bilgi ve sorunların asttan üste basamak basamak iletildiği yetki sırasıdır.","ornek":"Oda görevlisi kattaki bozuk prizi kat şefine, kat şefi kat hizmetleri müdürüne bildirir; stajyer bu iş için doğrudan genel müdürün kapısını çalmaz.","sektor":"Basamak atlanırsa amirin haberi olmadan karar çıkar, ekipte güven sarsılır. İstisnası can güvenliğidir: yangın, yaralanma gibi acil bir durumda en yakındaki yetkiliye hemen haber verilir.","iliskili":["os-6-003","os-6-009","os-6-002"],"kontrol":null,"kitapDisi":true,"cizim":"lider"},{"id":"os-6-082","konu":"6.1","terim":"İş tatmini","ingilizce":"Job satisfaction","tanim":"Çalışanın yaptığı işten ve çalıştığı ortamdan duyduğu memnuniyettir.","ornek":"Üç yıldır aynı otelde çalışan kat görevlisi, emeği için teşekkür edildiğinde ve izinleri adil dağıtıldığında “Bu işi seviyorum” der.","sektor":"Ders kitabına göre yöneticinin astlarıyla kurduğu ilişki iş tatminini, performansı ve iş verimliliğini doğrudan etkiler. İşinden memnun çalışan konuğa da daha içten davranır.","iliskili":["os-6-076","os-6-031","os-6-083"],"kontrol":null,"cizim":"kalite-yildiz"},{"id":"os-6-013","konu":"6.1.1","terim":"Toplantı","ingilizce":"Meeting","tanim":"Belirli bir konuyu görüşmek, bilgi paylaşmak ya da karar almak için ilgili kişilerin planlı biçimde bir araya gelmesidir.","ornek":"Pazartesi 10.00, toplantı odası: genel müdür ve bölüm müdürleri geçen haftanın satış raporlarını ve konuk yorumlarını birlikte inceler.","sektor":"Turizm işletmesi sürekli değişir ve öğrenir; toplantı, hedefleri netleştirmenin ve ekibin uyumunu artırmanın aracıdır. Toplantıya çağrılan stajyer zamanında gelir, not alır, telefonunu sessize alır.","iliskili":["os-6-014","os-6-015","os-6-016"],"kontrol":null,"gorsel":"t13f-toplanti-masasi"},{"id":"os-6-014","konu":"6.1.1","terim":"Toplantının amaçları","ingilizce":"Purposes of meetings","tanim":"Ekibi bilgilendirme, bölümler arasında eşgüdüm sağlama, işleyişteki sorunlara ve kriz durumlarına çözüm bulma, çalışanları isteklendirme ve ekip ruhunu güçlendirme hedefleridir.","ornek":"Fırtına yüzünden uçuşlar iptal olunca müdür bölüm şeflerini kısa bir kriz toplantısına çağırır: kaç konuk kalacak, hangi odalar uzatılacak, mutfak kaç kişilik yemek çıkaracak?","sektor":"Amacı belli olmayan toplantı zaman kaybıdır. Amacı belli bir kriz toplantısı ise dağınık çalışan bölümleri birkaç dakikada aynı plana bağlar; konuk karışıklığı hissetmez.","iliskili":["os-6-013","os-6-020","os-6-021"],"kontrol":null},{"id":"os-6-015","konu":"6.1.1","terim":"Toplantı süreci","ingilizce":"Meeting process","tanim":"Toplantının hazırlanması, uygulanması, yönetilmesi ve alınan sonuçların ilgili birimlere yazılı olarak iletilmesi aşamalarıdır.","ornek":"Müdür salı günü gündemi gönderir, çarşamba toplantıyı yönetir, perşembe sabahı kararları bölümlere e-postayla duyurur.","sektor":"En sık atlanan aşama sonuncusudur. Sözle aktarılan karar unutulur ya da herkes başka hatırlar; yazıyla iletilen karar ise kimin ne yapacağını tartışmasız gösterir.","iliskili":["os-6-013","os-6-016","os-6-017"],"kontrol":null,"cizim":"toplanti-sunum"},{"id":"os-6-016","konu":"6.1.1","terim":"Toplantı gündemi","ingilizce":"Agenda","tanim":"Toplantıda görüşülecek konuların sırasıyla yazıldığı ve katılımcılara önceden duyurulan listedir.","ornek":"Gündem: 1) Geçen haftanın konuk şikâyetleri, 2) Hafta sonu gelecek grubun girişi, 3) Yeni vardiya düzeni.","sektor":"Gündemi önceden bilen kişi hazırlıklı gelir, toplantı konudan sapmaz ve zamanında biter. Gündemsiz toplantıda en çok konuşan öne çıkar, asıl sorun konuşulmadan kalır.","iliskili":["os-6-013","os-6-015","os-6-017"],"kontrol":null,"cizim":"toplanti-sunum"},{"id":"os-6-017","konu":"6.1.1","terim":"Toplantı tutanağı","ingilizce":"Minutes of the meeting","tanim":"Toplantıda alınan kararların, kimin hangi işi üstlendiğinin ve işlerin bitiş tarihlerinin toplantı sırasında yazıldığı belgedir.","ornek":"Tutanaktan bir satır: “Karar 2 – Açık büfede servis hızı için akşam vardiyasına bir kişi eklenecek. Sorumlu: yiyecek içecek müdürü. Tarih: cuma.”","sektor":"İşletmelerde bunun için hazır bir “toplantı tutanak formu” kullanılır. Tutanak toplantının hafızasıdır; bir sonraki toplantı çoğu zaman “Geçen hafta ne karar almıştık, yapıldı mı?” sorusuyla açılır.","iliskili":["os-6-016","os-6-018","os-6-015"],"kontrol":null,"cizim":"toplanti-sunum"},{"id":"os-6-018","konu":"6.1.1","terim":"Termin süresi","ingilizce":"Deadline","tanim":"Bir işin tamamlanması için önceden belirlenmiş son tarih ya da süredir.","ornek":"Toplantıda teknik şefe “Havuz pompasının onarımı – termin: perşembe akşamı” denir; perşembe akşamı ilk sorulacak şey budur.","sektor":"Tarihi olmayan görev “bir ara yapılır” diye bekler. Sana verilen işte tarih söylenmediyse “Ne zamana kadar bitmeli?” diye sormak profesyonelliktir; yetişmeyecekse bunu son gün değil, önceden haber verirsin.","iliskili":["os-6-017","os-6-007"],"kontrol":null,"gorsel":"t13f-kum-saati-takvim"},{"id":"os-6-019","konu":"6.1.1","terim":"Günlük brifing","ingilizce":"Daily briefing","tanim":"Vardiya başında şefin ekibiyle yaptığı, o günün işlerinin ve dikkat edilecek noktaların paylaşıldığı birkaç dakikalık kısa toplantıdır.","ornek":"Saat 07.50, resepsiyonun arkası: şef “Bugün çıkışlar yoğun, öğlen bir VIP giriş bekliyoruz, asansörlerden biri bakımda.” der.","sektor":"Sektörde “briefing” ya da “morning briefing” de denir. Brifingi kaçıran görevli günün yarısını bilgisiz geçirir: VIP konuğu tanımaz, bakımdaki asansörü konuğa önerir. Brifinge zamanında ve üniformalı gelinir.","iliskili":["os-6-013","os-6-007","os-6-062"],"kontrol":null,"kitapDisi":true,"cizim":"toplanti-sunum"},{"id":"os-6-020","konu":"6.1.1","terim":"Departmanlar arası koordinasyon","ingilizce":"Interdepartmental coordination","tanim":"Otelin farklı bölümlerinin işlerini birbirinden haberdar olarak, aynı hedefe göre uyum içinde yürütmesidir.","ornek":"Kalabalık bir grup 12.00’de gelecek: ön büro giriş listesini, kat hizmetleri odaları, mutfak öğle yemeğini, bellboy ekibi bagaj arabalarını aynı saate göre hazırlar.","sektor":"Konuk oteli bölüm bölüm değil, tek bir bütün olarak yaşar. Bir bölümün aksaması zincirleme ilerler: oda geç hazırlanırsa resepsiyonda kuyruk uzar. Koordinasyon toplantıları bu zinciri sağlam tutar.","iliskili":["os-6-014","os-6-021","os-6-013"],"kontrol":null,"cizim":"ekip"},{"id":"os-6-021","konu":"6.1.1","terim":"Ekip ruhu","ingilizce":"Team spirit","tanim":"Bir grubun üyelerinin kendilerini aynı hedefin parçası sayması, birbirine güvenmesi ve gerektiğinde birbirinin yükünü paylaşması duygusudur.","ornek":"Giriş saatinde banko kalabalıklaşınca bagaj işini bitiren bellboy, sırada bekleyen konuklara “Hoş geldiniz.” diyerek ikram dağıtmaya başlar.","sektor":"“Bu benim işim değil.” cümlesi ekip ruhunun bittiği yerdir. Toplantılar, birlikte kutlanan başarılar ve personel etkinlikleri bu duyguyu besler; konuk da uyumlu çalışan ekibi hemen fark eder.","iliskili":["os-6-014","os-6-020","os-6-043"],"kontrol":null,"cizim":"ekip"},{"id":"os-6-022","konu":"6.1.2","terim":"Raporlama","ingilizce":"Reporting","tanim":"Yapılan işlerin ve elde edilen sonuçların düzenli aralıklarla yazıya ya da tabloya dökülerek yöneticiye sunulmasıdır.","ornek":"Gece 23.00: akşam vardiyasındaki resepsiyon görevlisi günün giriş, çıkış ve şikâyet sayılarını vardiya raporuna yazar.","sektor":"Rapor, yöneticinin orada olmadığı saatlerde yaşananları görmesini sağlar. Kontrolü güçlendirir, hataların tekrarını önler, verimi artırır; yönetici işletmenin geleceğiyle ilgili stratejik kararları bu raporlara bakarak verir.","iliskili":["os-6-023","os-6-025","os-6-024"],"kontrol":null,"cizim":"belge-form"},{"id":"os-6-023","konu":"6.1.2","terim":"Faaliyet raporu","ingilizce":"Activity report","tanim":"Bir bölümün günlük, haftalık ya da aylık çalışmalarını ve sonuçlarını özetleyen belgedir.","ornek":"Ay sonu: ön büro müdürü o ayın doluluk durumunu, konuk yorumlarını ve gelmeyen rezervasyonları tek sayfada toplayıp genel müdüre gönderir.","sektor":"Bu raporlarda konuk memnuniyeti, satış verileri, rezervasyon oranları, maliyet analizleri ve personel performansı yer alır; rakamlar çoğu zaman grafikle sunulur. Genel müdür bölümlerden gelen raporları inceleyip kısa bir yönetici özet raporu çıkarır ve kararını ona göre verir.","iliskili":["os-6-022","os-6-025","os-6-047"],"kontrol":null,"cizim":"belge-form"},{"id":"os-6-024","konu":"6.1.2","terim":"Olay raporu","ingilizce":"Incident report","tanim":"Kaza, kayıp, hasar ya da ciddi bir şikâyet gibi olağan dışı bir olayın ne zaman, nerede, nasıl olduğunun ve ne yapıldığının yazıldığı belgedir.","ornek":"Saat 21.40, lobi: bir konuk ıslak zeminde kayar. Vardiya şefi önce konukla ilgilenir; sonra saati, yeri, olayı görenleri ve yapılanları olay raporuna yazar.","sektor":"Rapora yorum değil, görülenler ve yapılanlar saatiyle birlikte yazılır; bekletilmez, aynı gün doldurulur. Stajyer olayı gördüyse gördüğünü olduğu gibi amirine anlatır; raporu çoğunlukla vardiya şefi doldurur. Zamanında yazılan rapor, sonradan çıkabilecek bir anlaşmazlıkta işletmenin en sağlam kaydıdır.","iliskili":["os-6-022","os-6-063","os-6-003"],"kontrol":null,"kitapDisi":true,"cizim":"belge-form"},{"id":"os-6-025","konu":"6.1.2","terim":"Dosyalama","ingilizce":"Filing","tanim":"Belgelerin türüne göre sınıflandırılıp arandığında hemen bulunacak bir düzenle saklanmasıdır.","ornek":"Muhasebe ofisinde bir stajyer, haftanın faturalarını tarih sırasına koyup o ayın fatura klasörüne takar.","sektor":"Sözleşmeler, faturalar, konuk kayıtları ve resmî yazışmalar dosyalanır. Düzenli dosya, yöneticinin bilgiye hızla ulaşmasını ve denetimde istenen belgenin hemen masaya konmasını sağlar. Konuk bilgisi içeren belge ortada bırakılmaz, yetkisiz kişiye gösterilmez.","iliskili":["os-6-026","os-6-027","os-6-028"],"kontrol":null,"gorsel":"f3h-dosya-dolabi"},{"id":"os-6-026","konu":"6.1.2","terim":"Arşivleme","ingilizce":"Archiving","tanim":"İşi biten ama ileride gerekebilecek belgelerin güvenli bir yerde, düzenli biçimde uzun süre saklanmasıdır.","ornek":"Yıl sonunda geçen yılın belgeleri kutulanır, üzerine yıl ve bölüm adı yazılır ve arşiv odasındaki rafa kaldırılır.","sektor":"İşletmeler bazı belgeleri yasa gereği belirli bir süre saklamak zorundadır; arşiv bu yükümlülüğü karşılar. Günümüzde dosyalama ve arşivleme hem elle (kâğıt dosya) hem dijital ortamda yapılır.","iliskili":["os-6-025","os-6-027","os-6-028"],"kontrol":null,"gorsel":"f3h-arsiv-kutulari"},{"id":"os-6-027","konu":"6.1.2","terim":"Fiziksel dosyalama","ingilizce":"Physical filing","tanim":"Kâğıt belgelerin klasör ve dolaplarda, tarih sırasına (kronolojik) ya da harf sırasına (alfabetik) göre saklanmasıdır.","ornek":"Faturalar tarih sırasıyla, acente sözleşmeleri acente adının baş harfine göre dizilir; aranan sözleşme harfinden hemen bulunur.","sektor":"Tek bir belge yanlış klasöre girerse o belge fiilen kaybolmuştur. Bu yüzden belge önce türüne göre ayrılır (tutanak, fatura, konuk kaydı, resmî yazı), sonra sırasına konur.","iliskili":["os-6-025","os-6-028","os-6-026"],"kontrol":null,"gorsel":"f3h-kartotek-cekmece"},{"id":"os-6-028","konu":"6.1.2","terim":"Dijital dosyalama","ingilizce":"Digital filing","tanim":"Rapor ve belgelerin bilgisayar ortamında, bölüm adına ve dönemine göre düzenli bir adlandırmayla klasörlenip saklanmasıdır.","ornek":"Ortak sürücüde “Ön Büro > 2026 > Mart > Haftalık Rapor 2” yolunu gören herkes dosyanın ne olduğunu açmadan anlar.","sektor":"“Yeni belge (3) son” gibi adlar dijital dağınıklıktır; mantıklı bir kodlama aramayı saniyelere indirir. Dijital dosya yedeklenir ve şifreyle korunur; herkes yalnız yetkisi olan klasöre girer.","iliskili":["os-6-025","os-6-027","os-6-026"],"kontrol":null,"cizim":"dijital"},{"id":"os-6-029","konu":"6.1.2","terim":"İç denetim ve dış denetim","ingilizce":"Internal and external audit","tanim":"İşletmenin kendi yöneticilerince yapılan (iç) ve resmî kurumlar ya da bağımsız kuruluşlarca dışarıdan yapılan (dış) kontrol türleridir.","ornek":"Salı sabahı resmî denetim ekibi otele gelir ve bazı belgeleri ister; dosyalar düzenli olduğu için istenenler birkaç dakikada masadadır.","sektor":"Düzenli raporlama ve dosyalama her iki denetimi de kolaylaştırır: işletme yasal yükümlülüklerini yerine getirdiğini belgeyle gösterir ve güvenilir bir duruş sergiler. Belgesini bulamayan işletme, işi doğru yapmış olsa bile bunu kanıtlayamaz.","iliskili":["os-6-025","os-6-022","os-6-044"],"kontrol":null,"cizim":"kurallar-liste"},{"id":"os-6-079","konu":"6.1.2","terim":"Yönetici özet raporu","ingilizce":"Executive summary report","tanim":"Genel müdürün, bölümlerden gelen raporları inceleyip stratejik kararlarına dayanak olacak biçimde kısa ve toplu hâle getirdiği rapordur.","ornek":"Ayın ilk iş gününde genel müdür ön büro, kat hizmetleri ve yiyecek içecek raporlarını okur; doluluk, şikâyet ve maliyet başlıklarını tek sayfada toplayıp bölüm müdürlerine dağıtır.","sektor":"Bölüm raporları ayrıntılıdır, özet rapor ise karar vermeye yöneliktir: genel müdür her bölümü baştan sona okumadan işletmenin durumunu görür. Ders kitabındaki toplantı etkinliğinde “Yönetici Özet Raporu” stratejik kararları içeren belge olarak geçer.","iliskili":["os-6-022","os-6-023","os-6-029"],"kontrol":null,"cizim":"belge-form"},{"id":"os-6-030","konu":"6.2","terim":"Moral","ingilizce":"Morale","tanim":"Çalışanın işine ve iş yerine karşı o dönemde taşıdığı ruh hâli ve istek düzeyidir.","ornek":"Ağustos ortası, haftalardır süren yoğunluk: personel yemekhanesinde kimse konuşmuyor, şakalar kesilmiş; ekibin morali düşmüş.","sektor":"Moral ekipte bulaşıcıdır, konuğa da geçer: gülümsemeyen görevli, geciken oda, uzayan kuyruk çoğu zaman düşük moralin görünen yüzüdür. İyi yönetici ekibinin moralini izler; düşüşü fark edip nedenini sorması bile bir adımdır.","iliskili":["os-6-031","os-6-035","os-6-042"],"kontrol":null,"cizim":"lider"},{"id":"os-6-031","konu":"6.2","terim":"Motivasyon","ingilizce":"Motivation","tanim":"Kişiyi bir işi isteyerek ve elinden gelenin en iyisiyle yapmaya yönelten iç ve dış etkenlerin bütünüdür.","ornek":"Bir konuk ayrılırken yorum kartına resepsiyon görevlisinin adını yazarak teşekkür eder; şef kartı sabah brifinginde ekibe okur.","sektor":"Hizmet sektöründe tempo yüksektir; bu yüzden motivasyonun yüksek olması gerekir. Motivasyon yükseldiğinde konuk memnuniyeti ve iş gücü verimi artar, personel devir hızı düşer, aidiyet duygusu güçlenir. Otelin binası ve teknolojisi kadar, çalışanının isteği de hizmet kalitesini belirler.","iliskili":["os-6-030","os-6-035","os-6-033","os-6-034"],"kontrol":null,"cizim":"lider"},{"id":"os-6-032","konu":"6.2","terim":"Maslow’un ihtiyaçlar hiyerarşisi","ingilizce":"Maslow's hierarchy of needs","tanim":"İnsan ihtiyaçlarını temelden yukarı doğru beş basamakta sıralayan ve alttaki ihtiyaç karşılanmadan üsttekinin kişiyi pek harekete geçirmediğini öne süren motivasyon kuramıdır.","ornek":"Dinlenmeye vakit bulamayan, izin günü sürekli ertelenen bir çalışanı “ayın personeli” rozeti pek sevindirmez: önce alt basamak karşılanmalıdır.","sektor":"Basamaklar alttan üste şöyledir: fizyolojik ihtiyaçlar (yemek, uyku, dinlenme), güvenlik (iş güvencesi, güvenli ortam), ait olma ve sevgi (ekip, arkadaşlık), saygı (takdir, başarı), kendini gerçekleştirme (yeteneğini kullanma, gelişme). Kuramı psikolog Abraham Maslow ortaya koymuştur; yöneticiye motivasyon yöntemlerini hangi sırayla düşüneceğini hatırlatır.","iliskili":["os-6-031","os-6-041","os-6-036"],"kontrol":null,"kitapDisi":true,"cizim":"hedef-basari"},{"id":"os-6-033","konu":"6.2","terim":"Devir hızının motivasyonla ilişkisi","ingilizce":"Motivation and staff turnover","tanim":"Çalışanların isteği yükseldikçe işten ayrılanların toplam çalışanlara oranının, yani personel devir hızının düşmesi; isteği düştükçe artmasıdır.","ornek":"Bir otelde her sezon resepsiyon ekibinin büyük bölümü değişiyorsa devir hızı yüksektir: konuk her gelişinde bankoda yeni bir yüz görür.","sektor":"Her ayrılan çalışanla birlikte verilen eğitim ve kazanılan deneyim de gider; yerine gelen kişi işi öğrenene kadar hata artar. Motivasyonu yüksek ekipte devir hızı düşer; sık gelen konuk da kendisini tanıyan personeli görmekten memnun olur.","iliskili":["os-6-031","os-6-034","os-6-038"],"kontrol":null},{"id":"os-6-034","konu":"6.2","terim":"Aidiyet duygusu","ingilizce":"Sense of belonging","tanim":"Çalışanın kendini iş yerinin bir parçası olarak görmesi ve işletmenin başarısını kendi başarısı gibi sahiplenmesidir.","ornek":"Mesaisi biten bir garson lobiden geçerken yerdeki peçeteyi görür; “Benim işim değil.” demez, eğilip alır.","sektor":"Aidiyet hisseden çalışan “otel” demez, “bizim otel” der. Fikri sorulan, emeği görülen ve adil davranılan çalışanda bu duygu gelişir; böyle bir ekip işletmede kalır ve konuğa içten davranır.","iliskili":["os-6-031","os-6-033","os-6-039"],"kontrol":null,"cizim":"kalp-empati"},{"id":"os-6-035","konu":"6.2","terim":"Motivasyon artırma yöntemleri","ingilizce":"Motivation methods","tanim":"Yöneticinin çalışanların isteğini yükseltmek için başvurduğu takdir ve ödüllendirme, eğitim ve gelişim, iletişim ve katılım, çalışma koşullarını iyileştirme ve sosyal etkinlik uygulamalarıdır.","ornek":"Sezon ortasında bir otel müdürü aynı hafta içinde ayın personelini açıklar, yabancı dil kursunu duyurur ve vardiya düzeni için ekibin önerilerini toplar.","sektor":"Tek bir yöntem herkese yetmez: biri takdirle, biri kendini geliştirme fırsatıyla, biri düzenli izin günüyle isteklenir. İyi yönetici ekibini tanır ve yöntemleri birlikte kullanır.","iliskili":["os-6-036","os-6-038","os-6-039","os-6-041","os-6-043"],"kontrol":null,"cizim":"lider"},{"id":"os-6-036","konu":"6.2","terim":"Takdir ve ödüllendirme","ingilizce":"Recognition and reward","tanim":"Çalışanın iyi yaptığı işin teşekkür, belge, prim ya da ödülle görünür kılınmasıdır.","ornek":"Sezon sonu toplantısında genel müdür, bulduğu cüzdanı eksiksiz teslim eden bellboy’a ekibin önünde teşekkür belgesi verir.","sektor":"Araçları teşekkür belgesi, prim (ücrete ek başarı ödemesi) ve ödüldür; en çabuk olanı ise zamanında söylenmiş bir “Eline sağlık.” sözüdür. Görülmeyen emek zamanla azalır; takdir edilen davranış tekrarlanır ve ekibe örnek olur.","iliskili":["os-6-035","os-6-037","os-6-075"],"kontrol":null,"cizim":"trofe-odul"},{"id":"os-6-037","konu":"6.2","terim":"Ayın personeli","ingilizce":"Employee of the month","tanim":"Bir ay boyunca işi, davranışı ve konuk memnuniyetine katkısıyla öne çıkan çalışanın seçilip ilan edildiği ödül uygulamasıdır.","ornek":"Ayın ilk pazartesi günü personel panosuna kat hizmetlerinden bir görevlinin fotoğrafı asılır; altında konukların onun için yazdığı iki teşekkür notu vardır.","sektor":"Takdir ve ödüllendirmenin otellerde sık görülen bir biçimidir. Seçim ölçütü açık ve adil olmalıdır: hep aynı kişi ya da yöneticiye yakın olan seçilirse ödül motive etmez, kırgınlık yaratır.","iliskili":["os-6-036","os-6-035","os-6-050"],"kontrol":null,"kitapDisi":true,"cizim":"ekip"},{"id":"os-6-038","konu":"6.2","terim":"Eğitim ve gelişim fırsatları","ingilizce":"Training and development","tanim":"Çalışanın mesleki bilgi ve becerisini artırması için işletmenin sunduğu seminer ve kurum içi eğitim olanaklarıdır.","ornek":"Kasım ayında, sezonun sakin haftasında otel, resepsiyon ekibine şikâyet karşılama üzerine iki günlük bir seminer düzenler.","sektor":"Çalışmakta olan personele işletmenin kendi içinde verdiği eğitime “hizmet içi eğitim” (in-service training) denir. Eğitim alan çalışan işini daha güvenle yapar ve kendisine değer verildiğini görür; yükselme yolu açık olan kişi işletmede kalır.","iliskili":["os-6-035","os-6-033","os-6-072"],"kontrol":null,"cizim":"kitap-ogrenme"},{"id":"os-6-039","konu":"6.2","terim":"Açık iletişim","ingilizce":"Open communication","tanim":"Çalışanların fikir, öneri ve sorunlarını çekinmeden yöneticilerine iletebildiği, yöneticilerin de bunları dinleyip dikkate aldığı iletişim ortamıdır.","ornek":"Vardiya sonunda şef ekibine “Bugün sizi en çok ne zorladı?” diye sorar; stajyerin söylediği anahtar kartı sorunu ertesi gün çözülür.","sektor":"Toplantılar, öneri sistemleri ve açık iletişim kanalları bu ortamın araçlarıdır. İletişim çift yönlüdür: yönetici talimat verir, ast da gördüğü sorunu yukarı aktarır. Fikrinin dikkate alındığına inanan çalışan konuşur; inanmayan susar ve sorun büyüyene kadar kimse duymaz.","iliskili":["os-6-040","os-6-034","os-6-035"],"kontrol":null,"gorsel":"f3h-oneri-kutusu"},{"id":"os-6-040","konu":"6.2","terim":"Öneri sistemi","ingilizce":"Suggestion scheme","tanim":"Çalışanların işi iyileştirecek fikirlerini yazılı ya da dijital yolla yönetime ulaştırdığı düzendir.","ornek":"Personel yemekhanesindeki öneri kutusuna bir kat görevlisi, kat arabalarına ikinci bir çöp torbası askısı takılmasını yazar; öneri uygulanır ve adı toplantıda anılır.","sektor":"İşi en iyi, onu her gün yapan bilir. Önerisi uygulanan çalışan kendini değerli hisseder; öneriler okunmuyor ve cevap verilmiyorsa kutu kısa sürede boş kalır.","iliskili":["os-6-039","os-6-034","os-6-036"],"kontrol":null,"gorsel":"os-oneri-sistemi"},{"id":"os-6-041","konu":"6.2","terim":"Çalışma koşullarının iyileştirilmesi","ingilizce":"Improving working conditions","tanim":"Çalışanın işini sağlıklı ve rahat yapabilmesi için çalışma ortamının, araçlarının ve çalışma saatlerinin düzenlenmesidir.","ornek":"Otel, görevlilerin saatlerce ayakta durduğu resepsiyon bankosunun arkasına yorgunluğu azaltan bir zemin döşer ve personel dinlenme odasını yeniler.","sektor":"Bunun kapsamında ergonomik (bedene uygun) çalışma ortamı, iş-yaşam dengesini gözeten uygulamalar ve esnek vardiya düzeni yer alır. Dinlenmiş çalışan daha az hata yapar ve konuğa daha sabırlı davranır.","iliskili":["os-6-042","os-6-035","os-6-052"],"kontrol":null},{"id":"os-6-042","konu":"6.2","terim":"İş-yaşam dengesi","ingilizce":"Work-life balance","tanim":"Çalışanın işine ayırdığı zaman ile ailesine, dinlenmeye ve kendine ayırdığı zamanın birbirini ezmeyecek ölçüde olmasıdır.","ornek":"Kardeşinin düğünü olan resepsiyon görevlisi haftalar önceden haber verir; şef vardiya çizelgesinde o hafta sonunu ona izin olarak ayarlar.","sektor":"Otel bayramda, hafta sonunda ve gece de açıktır; bu yüzden denge kendiliğinden kurulmaz, planlanır. Esnek vardiya düzeni ve adil dağıtılan izinler bunun araçlarıdır. Uzun süre dinlenemeyen ekipte hem moral hem hizmet kalitesi düşer.","iliskili":["os-6-041","os-6-058","os-6-030"],"kontrol":null,"gorsel":"h6-plaj-hamagi"},{"id":"os-6-043","konu":"6.2","terim":"Sosyal etkinlikler","ingilizce":"Staff social events","tanim":"Çalışanların iş dışında bir araya gelmesi için düzenlenen personel gecesi ve kutlama gibi etkinliklerdir.","ornek":"Sezon kapanışında otel, bütün bölümlerin katıldığı bir personel gecesi düzenler; o gece ağırlanan taraf çalışanlardır.","sektor":"Farklı bölümlerde çalışanlar birbirini tanır; ertesi gün telefonda yalnız “kat hizmetleri” değil, tanıdık bir isim aranır. Ekip ruhunu geliştirir, yoğun sezonun yorgunluğunu hafifletir.","iliskili":["os-6-021","os-6-035","os-6-030"],"kontrol":null,"cizim":"festival"},{"id":"os-6-083","konu":"6.2","terim":"İş gücü verimliliği","ingilizce":"Labour productivity","tanim":"Çalışanların aynı sürede ve emekle ne kadar ve ne kalitede iş çıkardığını gösteren ölçüdür.","ornek":"Motivasyonu yüksek kat ekibi öğlene kadar daha çok odayı, tek bir şikâyet gelmeden ve eksiksiz hazırlar.","sektor":"Ders kitabına göre çalışanların motivasyonu yükseldiğinde iş gücü verimliliği de artar. Verimlilik acele etmek değil, doğru işi doğru sırayla yapmaktır; hatalı işin tekrarı verimi düşürür.","iliskili":["os-6-031","os-6-082","os-6-033"],"kontrol":null,"cizim":"grafik"},{"id":"os-6-085","konu":"6.2","terim":"İnfografik","ingilizce":"Infographic","tanim":"Bilgiyi şema, grafik, simge ve renklerle görselleştirerek kısa sürede anlaşılır kılan tasarımdır.","ornek":"Sınıf grubu, personel motivasyonu yöntemlerini beş simgeyle tek bir afişte gösterir: yıldız takdiri, kitap eğitimi, iki konuşma balonu iletişimi temsil eder.","sektor":"Ders kitabının motivasyon etkinliğinde grup, “Personel Motivasyon İnfografiği” hazırlayıp sınıfa sunar. Otelde de rezervasyon oranları gibi veriler toplantılarda grafikle gösterilir.","iliskili":["os-6-035","os-6-031"],"kontrol":null,"cizim":"grafik"},{"id":"os-6-086","konu":"6.2","terim":"Fazla mesai","ingilizce":"Overtime","tanim":"Çalışanın haftalık yasal çalışma süresini aşan çalışmasıdır.","ornek":"Temmuz ayında yaz yoğunluğu nedeniyle haftalık çalışma süresini dolduran resepsiyon görevlisi cuma akşamı da vardiyasını uzatır; yasal süreyi aşan bu saatler fazla mesaidir.","sektor":"Yoğun sezonda kaçınılmaz olabilir; ancak sürekli ve esnek olmayan fazla mesai morali düşürür. Ders kitabındaki Antalya vakasında fazla mesai ve esnek olmayan vardiyalar personelin moralinin düşmesinin nedenidir.","iliskili":["os-6-059","os-6-041","os-6-042"],"kontrol":null,"cizim":"saat-zaman"},{"id":"os-6-044","konu":"6.3","terim":"Denetim","ingilizce":"Inspection","tanim":"İşlerin belirlenen standartlara ve hedeflere uygun yürüyüp yürümediğinin düzenli ve sistemli biçimde kontrol edilmesidir.","ornek":"Akşam 19.00: ön büro müdürü lobiyi ve resepsiyonu dolaşır; görevlinin konuğu nasıl karşıladığını, lobinin düzenini, bekleyen konuk olup olmadığını gözlemler.","sektor":"Denetim hata avı ya da ceza aracı değildir: çalışanın performansını geliştirmek, konuk memnuniyetini artırmak ve işletmeyi hedefine ulaştırmak için yapılır. İyi iş takdir edilir, eksik iş gösterilip düzelttirilir. Stajyer için de denetlenmek, işi doğru öğrenmenin kısa yoludur.","iliskili":["os-6-045","os-6-046","os-6-050"],"kontrol":null},{"id":"os-6-045","konu":"6.3","terim":"Denetim adımları","ingilizce":"Inspection steps","tanim":"Yöneticinin denetimde izlediği standartların kontrolü, personel performansı, konuk geri bildirimleri, kaynak kullanımı ve raporlama basamaklarıdır.","ornek":"Müdür akşam denetiminde resepsiyon görevlisinin karşılamasını izler, boşa yanan ışıkları not eder, konuk ilişkileri raporunu okur ve ertesi sabah gördüklerini yazıp üst yönetime sunar.","sektor":"Beşi birlikte resmin tamamını verir: iş standarda uygun mu, çalışan görevini nasıl yapıyor ve konukla nasıl iletişim kuruyor, konuk ne diyor, kaynak boşa gidiyor mu ve bunlar yazıya döküldü mü? Yalnız birine bakan denetim eksik kalır.","iliskili":["os-6-044","os-6-046","os-6-047","os-6-048","os-6-049"],"kontrol":null,"cizim":"kurallar-liste"},{"id":"os-6-046","konu":"6.3","terim":"Hizmet standardı","ingilizce":"Service standard","tanim":"Bir işin her seferinde, kim yaparsa yapsın aynı kalitede yapılması için işletmenin önceden belirlediği ölçü ve yöntemdir.","ornek":"Otelin karşılama standardı: bankoya yaklaşan konuk selamlanır, göz teması kurulur, adı öğrenildikten sonra adıyla hitap edilir.","sektor":"Denetimin ilk adımı, standartların uygulanıp uygulanmadığını gözlemlemektir. Standart yoksa denetim de olmaz; çünkü neyin doğru olduğu kişiden kişiye değişir. Bölümlerin yazılı iş adımlarına prosedür denir.","iliskili":["os-6-044","os-6-045","os-6-071"],"kontrol":null,"gorsel":"h6-masa-standardi"},{"id":"os-6-047","konu":"6.3","terim":"Konuk geri bildirimi","ingilizce":"Guest feedback","tanim":"Konukların aldıkları hizmetle ilgili ilettiği şikâyet, öneri ve teşekkürlerin tümüdür.","ornek":"Son bir haftada dört ayrı konuk yorum kartına havuz başındaki havluların geç geldiğini yazmıştır; müdür kartları yan yana koyunca sorunu görür.","sektor":"Yönetici hizmet kalitesini konuğun gözünden bununla ölçer. Tek şikâyet bir olay, tekrar eden şikâyet bir işarettir: aynı konu üst üste geliyorsa sorun çoğu zaman kişide değil, düzendedir. Sana söylenen şikâyeti amirine iletmen, geri bildirimin kaybolmamasını sağlar.","iliskili":["os-6-045","os-6-049","os-6-023"],"kontrol":null,"cizim":"konusma"},{"id":"os-6-048","konu":"6.3","terim":"Kaynak kullanımı","ingilizce":"Use of resources","tanim":"Zaman, malzeme, enerji ve bütçe gibi işletme olanaklarının boşa harcanmadan, doğru ve verimli kullanılmasıdır.","ornek":"Gece 02.00: boş toplantı salonunda bütün ışıklar ve klima açık kalmış; denetime çıkan gece müdürü kapatır ve rapora not düşer.","sektor":"Denetimde yönetici kaynakların boşa gidip gitmediğine de bakar. Boşa yanan ışık, fazla kullanılan deterjan, gereksiz açılan malzeme doğrudan maliyettir; tasarruf aynı zamanda çevreye saygıdır. Çıkarken ışığı kapatan stajyer de bu işin parçasıdır.","iliskili":["os-6-045","os-6-049","os-6-044"],"kontrol":null},{"id":"os-6-049","konu":"6.3","terim":"Düzeltici önlem","ingilizce":"Corrective action","tanim":"Denetimde saptanan bir eksiğin ya da hatanın tekrarlanmaması için planlanan ve uygulanan çözümdür.","ornek":"Havlu şikâyetleri üzerine müdür, öğle saatlerinde havuz başına ikinci bir görevli verir ve bir hafta sonra şikâyetlerin kesilip kesilmediğine bakar.","sektor":"Denetimin son adımı raporlamadır: sonuçlar yazılı ya da görsel raporla üst yönetime sunulur ve önlem planlanır. Sorunu saptayıp bırakmak denetim değildir; önlem alınır, sonra işe yarayıp yaramadığı yeniden kontrol edilir.","iliskili":["os-6-047","os-6-048","os-6-045"],"kontrol":null,"cizim":"kurallar-liste"},{"id":"os-6-050","konu":"6.3","terim":"Denetimde adil yaklaşım","ingilizce":"Fair approach to inspection","tanim":"Yöneticinin denetimi herkes için aynı ölçütle, açık ve güvenilir biçimde, teknolojiden de yararlanarak yürütmesi ilkesidir.","ornek":"Şef, yakın arkadaşı olan görevlinin eksik bıraktığı işi de yeni başlayan stajyerinkini de aynı kontrol listesiyle değerlendirir.","sektor":"Şeffaflık, neye bakıldığının önceden bilinmesidir. Kayırma yapılan ekipte denetim güven değil, kırgınlık üretir. Adil yönetici iyi işi de görür: denetimde karşılaştığı başarılı çalışanı takdir etmek, hatayı düzelttirmek kadar görevidir.","iliskili":["os-6-044","os-6-069","os-6-036"],"kontrol":null,"cizim":"konusma"},{"id":"os-6-051","konu":"6.3.1","terim":"Vardiya düzeni","ingilizce":"Shift system","tanim":"Yirmi dört saat kesintisiz hizmet veren işletmede çalışanların günün belirli dilimlerinde dönüşümlü görev yaptığı, yöneticinin planlayıp yönettiği çalışma düzenidir.","ornek":"Saat 15.00, resepsiyon: sabahçı görevli kasayı ve notları akşamcıya devreder; banko bir an bile boş kalmaz.","sektor":"Otel günün yirmi dört saati açıktır; kimse yirmi dört saat çalışamayacağına göre gün dilimlere bölünür. Sektörde İngilizcesiyle “shift” de denir. Stajyer için ilk kural: vardiyana zamanında, üniforman hazır gelirsin. Ders kitabına göre konaklama işletmelerinde vardiya çizelgeleri 8 saatlik süreler üzerine kurulur; şehir otellerinde vardiya başlangıcı olarak 08.00 tercih edilir.","iliskili":["os-6-052","os-6-053","os-6-062"],"kontrol":null},{"id":"os-6-052","konu":"6.3.1","terim":"Vardiya planlaması","ingilizce":"Shift planning (rostering)","tanim":"Hangi çalışanın hangi gün ve hangi vardiyada görev yapacağının, iş yükü ve yasal kurallar gözetilerek önceden belirlenmesidir.","ornek":"Ön büro müdürü gelecek haftanın rezervasyonlarına bakar: cumartesi büyük bir grup girişi var; o günün akşam vardiyasına bir kişi daha yazar.","sektor":"Amacı iş yükünü dengeli dağıtmak, hizmet kalitesini korumak ve konuk memnuniyetini artırmaktır. Plan yapılırken beklenen doluluk, VIP ve grup girişleri, organizasyonlar ile personelin izin ve sağlık raporu durumu birlikte değerlendirilir; her vardiyada en az kaç kişinin gerektiği buna göre hesaplanır.","iliskili":["os-6-051","os-6-053","os-6-059"],"kontrol":null,"cizim":"ekip"},{"id":"os-6-053","konu":"6.3.1","terim":"Çizelge kodları ve ilanı","ingilizce":"Roster codes and notice","tanim":"Vardiya çizelgesindeki S, A, G, N ve OFF gibi kısaltmaların okunması ve çizelgenin çalışanlara önceden duyurulmasıdır.","ornek":"Personel panosundaki çizelgede adının karşısında “S S A A OFF A A” yazıyor: iki sabah, iki akşam, bir izin, iki akşam.","sektor":"Çizelgede S sabah, A akşam, G gece, N normal (ofis) vardiyasını, OFF ya da X haftalık izni gösterir. Bazı çizelgelerde izinli ya da hasta olanın yerine giren gezici (yedek) personel de yer alır. Çizelge, herkes hazırlık yapabilsin diye dönem başlamadan önce panoda ya da dijital kanalda ilan edilir. İlan edildikten sonra amirin onayı olmadan vardiya değiştirilmez. Ders kitabına göre çizelge en az 3 gün önceden ilan edilmelidir. Kitaptaki örnek çizelgede sabah (S), akşam (A) ve gece (G) vardiyalarının her biri 7,5 saat net çalışma olarak gösterilir.","iliskili":["os-6-052","os-6-054","os-6-058"],"kontrol":null,"gorsel":"os-cizelge-kodlari"},{"id":"os-6-054","konu":"6.3.1","terim":"Sabah vardiyası","ingilizce":"Morning shift","tanim":"Günün ilk çalışma dilimi olan, ön büroda çıkış işlemlerinin ve sabah taleplerinin yoğunlaştığı vardiyadır.","ornek":"Saat 09.30, resepsiyon: bankoda üç konuk hesabını kapatıyor, biri fatura istiyor, telefondaki konuk geç çıkış yapıp yapamayacağını soruyor.","sektor":"Çizelgede S ile gösterilir; birçok otelde 07.00–15.00 arasıdır, saatler işletmeye göre değişebilir. Check-out (çıkış), faturalandırma ve sabah gelen konuk istekleri bu vardiyanın ana işidir.","iliskili":["os-6-055","os-6-056","os-6-053"],"kontrol":null,"cizim":"saat-zaman"},{"id":"os-6-055","konu":"6.3.1","terim":"Akşam vardiyası","ingilizce":"Evening shift","tanim":"Öğleden sonra başlayıp gece yarısına doğru biten, ön büroda giriş işlemlerinin yoğunlaştığı vardiyadır.","ornek":"Saat 17.00: havalimanı servisi otelin önüne yanaşır, on iki konuk aynı anda bankoya gelir.","sektor":"Çizelgede A ile gösterilir; birçok otelde 15.00–23.00 arasıdır. Check-in (giriş), oda blokajı (belirli odaların belirli konuklar için ayrılması) ve no-show takibi, yani rezervasyonu olduğu hâlde gelmeyen konukların izlenmesi en çok bu vardiyada yapılır.","iliskili":["os-6-054","os-6-056","os-6-062"],"kontrol":null},{"id":"os-6-056","konu":"6.3.1","terim":"Gece vardiyası","ingilizce":"Night shift","tanim":"Akşam vardiyasının ardından başlayıp sabaha kadar süren, gün sonu işlemlerinin yapıldığı ve gece güvenliğinin izlendiği vardiyadır.","ornek":"Saat 03.00: gece resepsiyonisti günün hesaplarını kapatır; o sırada geç gelen bir konuğun girişini yapar, lobiyi de gözünün önünden ayırmaz.","sektor":"Çizelgede G ile gösterilir; birçok otelde 23.00–07.00 arasıdır. Gün sonu işlemleri ile otel yönetim sisteminde günün kapatılıp yeni günün açılması bu saatlerde yapılır. Ekip azdır, sorumluluk büyüktür; gece çalışması İş Kanunu’nda ayrıca sınırlanmıştır.","iliskili":["os-6-054","os-6-055","os-6-061"],"kontrol":null},{"id":"os-6-057","konu":"6.3.1","terim":"Normal (ofis) vardiyası","ingilizce":"Office hours (day shift)","tanim":"Gündüz mesai saatlerini kapsayan ve çoğunlukla bölüm yöneticilerinin idari işleri yürütmek için çalıştığı vardiyadır.","ornek":"Ön büro müdürü 09.00’da gelir: raporları okur, toplantıya girer, gelecek haftanın çizelgesini hazırlar ve akşamüstü çıkar.","sektor":"Çizelgede N ile gösterilir. Müdürün ofis saatlerinde çalışması, sabah ve akşam ekiplerinin ikisini de görebilmesini sağlar. Müdür otelde yokken vardiyanın sorumlusu vardiya şefidir; sorun önce ona iletilir.","iliskili":["os-6-054","os-6-053","os-6-058"],"kontrol":null,"cizim":"ekip"},{"id":"os-6-058","konu":"6.3.1","terim":"Haftalık izin (OFF)","ingilizce":"Day off (weekly rest day)","tanim":"Çalışanın haftada bir kullandığı, çizelgede OFF ya da X ile gösterilen yasal dinlenme günüdür.","ornek":"Çizelgede salı günü “OFF” yazıyor: arkadaşların hafta sonu tatil yaparken sen cumartesi bankodasın, salı günü dinleniyorsun.","sektor":"Otel hafta sonu da açık olduğundan izin günü çoğu zaman hafta içine gelir. Adil yönetici hafta sonu izinlerini ekip içinde dönüşümlü paylaştırır; hep aynı kişinin hafta sonu çalışması motivasyonu düşürür.","iliskili":["os-6-053","os-6-042","os-6-061"],"kontrol":null},{"id":"os-6-059","konu":"6.3.1","terim":"Yasal çalışma süreleri","ingilizce":"Statutory working hours","tanim":"Çalışanın bir günde ve bir haftada en çok ne kadar çalıştırılabileceğini belirleyen, kanunla konmuş sınırlardır.","ornek":"Müdür çizelgeyi bitirince her satırın sonundaki toplam saate bakar: hiçbir çalışanın haftası kırk beş saati geçmemelidir.","sektor":"4857 sayılı İş Kanunu’na göre haftalık çalışma süresi en çok 45 saattir; günlük çalışma 11 saati, gece çalışması kural olarak 7,5 saati aşamaz. Çizelge bu sınırlara göre hazırlanır. Bu rakamlar yetişkin çalışanlar içindir; on sekiz yaşından küçük çalışanlar ve stajyer öğrenciler için daha kısa süreler ve ayrı kurallar geçerlidir. Kurallar çalışanın sağlığını korur; yorgun çalışan hem kendisi hem konuk için risktir.","iliskili":["os-6-060","os-6-061","os-6-052"],"kontrol":null,"cizim":"etik-terazi"},{"id":"os-6-060","konu":"6.3.1","terim":"Vardiyalar arası dinlenme süresi","ingilizce":"Rest period between shifts","tanim":"Çalışanın bir vardiyadan çıkıp bir sonrakine başlaması arasında kesintisiz dinlenmesi gereken en az süredir.","ornek":"Gece 23.00’te akşam vardiyasından çıkan görevli ertesi sabah 07.00 vardiyasına yazılamaz: arada yalnızca sekiz saat vardır.","sektor":"Ders kitabındaki İş Kanunu’na uyumlu çizelge kuralına göre, vardiyası değişen çalışan en az on bir saat kesintisiz dinlenmeden yeni vardiyasına başlatılmaz (bu kural da yetişkin çalışanlar içindir). Akşam vardiyasını kapatıp ertesi sabahı açmak dinlenmeye vakit bırakmaz; uykusuz çalışan hata yapar. İyi hazırlanmış çizelgede böyle bir sıra bulunmaz.","iliskili":["os-6-059","os-6-061","os-6-053"],"kontrol":null,"cizim":"ekip"},{"id":"os-6-061","konu":"6.3.1","terim":"Vardiya rotasyonu","ingilizce":"Shift rotation","tanim":"Çalışanların sabah, akşam ve gece vardiyalarında belirli aralıklarla dönüşümlü olarak görevlendirilmesidir.","ornek":"Bu dönem gece çalışan resepsiyon görevlisi sonraki dönem gündüz vardiyasına alınır; geceye başka bir arkadaşı yazılır.","sektor":"Gece çalışmanın bedensel yükü tek kişiye bırakılmaz; mevzuat, gece çalışanın belirli aralıklarla gündüz vardiyasına geçirilmesini ister. Hafta sonu izinleri de aynı mantıkla sırayla dağıtılır. Ders kitabına göre gece çalışan personel en geç iki haftada bir gündüz vardiyasına kaydırılacak biçimde rotasyona alınır. Rotasyon hem adalet hem sağlık konusudur.","iliskili":["os-6-056","os-6-058","os-6-059"],"kontrol":null,"cizim":"harita-rota"},{"id":"os-6-062","konu":"6.3.1","terim":"Vardiya devir teslimi","ingilizce":"Shift handover","tanim":"Vardiyası biten görevlinin, süren işleri, bekleyen talepleri ve önemli notları yerine gelen görevliye eksiksiz aktarmasıdır.","ornek":"Saat 14.50: sabahçı, akşamcıya “Bir odanın kliması arızalı, teknik servis dörtte gelecek; konuğa ben söz verdim, takibi sende.” der ve deftere de yazar.","sektor":"Devir, vardiya değişiminden önce başlar; bu yüzden vardiyaya tam saatinde değil, saatinden biraz önce gelinir. Devir yapılmadan bankodan ayrılınmaz. Konuk aynı isteği ikinci kez anlatmak zorunda kalıyorsa devir teslim eksik yapılmıştır. Ders kitabına göre log book devir teslimi, vardiya değişiminden en az 15 dakika önce eksiksiz yapılmalıdır.","iliskili":["os-6-063","os-6-051","os-6-055"],"kontrol":null,"cizim":"ekip"},{"id":"os-6-063","konu":"6.3.1","terim":"Log book (takip defteri)","ingilizce":"Log book","tanim":"Vardiya boyunca olan önemli olayların, bekleyen işlerin ve sonraki vardiyaya bırakılan notların yazıldığı defterdir.","ornek":"Defterden bir satır: “22.15 – 214 numaralı oda 05.00’e uyandırma istedi, 05.30’a taksi çağrılacak. Takip: gece vardiyası.”","sektor":"Vardiyaya gelen görevlinin ilk işi defteri okumaktır. Not kısa, tarihli ve saatli yazılır, yazan kişi adını ekler; “Söylemiştim.” değil, “Yazmıştım.” geçerlidir. Devir teslim vardiya değişiminden önce bu defter üzerinden eksiksiz yapılır.","iliskili":["os-6-062","os-6-024","os-6-022"],"kontrol":null,"gorsel":"t13e-acik-defter-kalem"},{"id":"os-6-080","konu":"6.3.1","terim":"Gece resepsiyonisti","ingilizce":"Night receptionist","tanim":"Vardiyası gece (G) olan, geç gelen konuklarla ilgilenen ve sabaha kadar ön büro hizmetini sürdüren resepsiyon görevlisidir.","ornek":"Saat 02.30, resepsiyon: gecikmeli uçakla gelen aile için görevli girişi yapar, sabah 06.00 uyandırma isteğini deftere yazar ve sabahçıya devretmek üzere notunu hazırlar.","sektor":"Ders kitabındaki örnek çizelgede gece resepsiyonisti yalnız gece (G) vardiyasında görünür ve diğer resepsiyonistlerden ayrı satırda yazılır. Ekip azdır, sorumluluk büyüktür; gece yaşanan her şey devir teslimle sabah ekibine aktarılır.","iliskili":["os-6-056","os-6-062","os-6-063"],"kontrol":null,"cizim":"resepsiyon"},{"id":"os-6-081","konu":"6.3.1","terim":"Gezici (yedek) personel","ingilizce":"Floating (relief) staff","tanim":"İzne çıkan ya da rahatsızlanan çalışanın yerini dolduran, çizelgede sabah, akşam ve gece vardiyalarına dönüşümlü yazılan yedek çalışandır.","ornek":"Çizelgede “Gezici / Yedek Personel” satırındaki görevli bir gün sabah, birkaç gün sonra akşam ya da gece vardiyasına yazılır; izne çıkan arkadaşının bankosunu devralır.","sektor":"Yedek personel sayesinde banko hiç boş kalmaz ve diğer çalışanlar izinlerini rahatça kullanır. Vardiyası sık değiştiği için çizelgesini herkesten dikkatli izlemesi gerekir.","iliskili":["os-6-058","os-6-061","os-6-052"],"kontrol":null,"cizim":"ekip"},{"id":"os-6-064","konu":"6.3.2","terim":"Geliş gidiş kontrolü","ingilizce":"Attendance control","tanim":"Personelin işe geliş ve işten çıkış saatlerinin kayda geçirilip izlenmesidir.","ornek":"Sabah 06.50: personel girişinde görevliler kartını okutur; şef 07.00’de ekranda kimin geldiğini, kimin henüz gelmediğini görür.","sektor":"Yönetsel denetimin bir parçasıdır: hizmetin sürmesi herkesin vardiyasına zamanında başlamasına bağlıdır. Geç kalan tek kişi, vardiyası bitmiş arkadaşını bankoda bekletir. Kayıt çalışanı da korur: çalıştığı sürenin belgesidir. Gecikeceksen ya da gelemeyeceksen önceden amirine haber verirsin.","iliskili":["os-6-065","os-6-066","os-6-067"],"kontrol":null,"gorsel":"h6-mesai-karti-saati"},{"id":"os-6-065","konu":"6.3.2","terim":"Personel geliş gidiş kontrol sistemi (PDKS)","ingilizce":"Time and attendance system","tanim":"Çalışanların giriş ve çıkış saatlerini kart, parmak izi ya da karekod gibi yollarla kaydeden ve yöneticiye devam raporu sunan dijital sistemdir.","ornek":"Ay sonunda insan kaynakları sistemden raporu alır: kimin kaç gün çalıştığı ve kaç kez geç kaldığı tek tabloda görünür.","sektor":"Sektörde “personel devam kontrol sistemi” diye de açılır. Dijital raporlama sayesinde yönetici personelin devam durumunu anlık izleyebilir. Hem disiplini hem iş gücü verimliliğini destekler; elle tutulan kayıttaki unutma ve hata payını azaltır.","iliskili":["os-6-064","os-6-067","os-6-068"],"kontrol":null,"cizim":"dis-bakimi"},{"id":"os-6-066","konu":"6.3.2","terim":"İmza çizelgesi","ingilizce":"Attendance register (sign-in sheet)","tanim":"Personelin geliş ve çıkış saatini elle yazıp imzaladığı kâğıt kayıttır.","ornek":"Küçük bir butik otelde sabah gelen görevli resepsiyonun arkasındaki çizelgeye “06.55” yazar ve imzasını atar.","sektor":"Geliş gidiş kontrolünün elle yapılan (manuel) yoludur; dijital sistemlerle birlikte hâlâ kullanılır. Saat olduğu gibi yazılır ve herkes yalnız kendi adına imzalar: arkadaşının yerine imza atmak dürüstlüğe aykırıdır ve ciddi bir disiplin konusudur.","iliskili":["os-6-064","os-6-065","os-6-067"],"kontrol":null,"cizim":"belge-form"},{"id":"os-6-067","konu":"6.3.2","terim":"Kartlı geçiş sistemi","ingilizce":"Card access system","tanim":"Çalışanın personel kartını okuyucuya okutmasıyla giriş ve çıkış saatinin kendiliğinden kaydedildiği sistemdir.","ornek":"Personel kapısındaki turnikeye kartını yaklaştırırsın; yeşil ışık yanar, sistem “06.52 – giriş” kaydını düşer.","sektor":"Karekodlu personel kartları da aynı işi görür. Kart kişiye özeldir: başkasına verilmez, başkasının kartı okutulmaz. Kartını kaybeden personel bunu hemen amirine bildirir.","iliskili":["os-6-065","os-6-068","os-6-064"],"kontrol":null,"cizim":"veri-guvenlik"},{"id":"os-6-068","konu":"6.3.2","terim":"Biyometrik doğrulama","ingilizce":"Biometric verification","tanim":"Kişinin parmak izi ya da yüzü gibi kendine özgü bedensel özelliğiyle tanınarak giriş çıkış kaydının alınmasıdır.","ornek":"Bu sistemi kullanan bir otelde görevli, personel girişindeki cihaza parmağını basar; ekranda adı ve saat görünür, kayıt tamamlanır.","sektor":"Kart unutulabilir ya da başkasına verilebilir; parmak izi verilemez. Bu yüzden kaydın güvenilirliğini artırır. Her işletmede bulunmaz: biyometrik veri kanunla özel olarak korunan kişisel veridir; işletme bu veriyi ancak kurallara uygun biçimde toplayabilir ve korumak zorundadır.","iliskili":["os-6-065","os-6-067","os-6-064"],"kontrol":null,"gorsel":"t14c-parmak-izi-okuyucu"},{"id":"os-6-084","konu":"6.3.2","terim":"Mobil konum tabanlı giriş uygulaması","ingilizce":"Mobile location-based check-in app","tanim":"Çalışanın telefondaki uygulama üzerinden, bulunduğu konum doğrulanarak işe giriş ve çıkış saatini kaydettiği dijital yöntemdir.","ornek":"Otelin bahçe ekibi işe başlarken telefondaki uygulamayı açar; sistem otel sınırları içinde olduklarını doğrulayıp giriş saatini kaydeder.","sektor":"Ders kitabının ölçme sorusunda kartlı geçiş ve biyometrik doğrulamayla birlikte dijital kontrol araçları arasında sayılır. Konum bilgisi kişisel veridir; çalışan bilgilendirilir ve veri korunur.","iliskili":["os-6-067","os-6-068","os-6-065"],"kontrol":null,"cizim":"harita-rota"},{"id":"os-6-069","konu":"6.3.3","terim":"Performans değerlendirme","ingilizce":"Performance appraisal","tanim":"Çalışanın belirli bir dönemdeki işinin, önceden bilinen ölçütlere göre yöneticisi tarafından düzenli olarak gözden geçirilmesidir.","ornek":"Sezon sonunda resepsiyon şefi her görevlisiyle ayrı ayrı oturur: formu birlikte okurlar, iyi gidenleri ve geliştirilecek noktaları konuşurlar.","sektor":"Amaç not vermek değil, geliştirmektir: işletmenin verimini artırır, çalışanın gelişim alanlarını belirler ve motivasyonunu destekler. Değerlendirme şeffaf, güvenilir ve gelişim odaklı olmalıdır; kişiliğe değil, işe ve davranışa bakar.","iliskili":["os-6-070","os-6-071","os-6-050"],"kontrol":null,"cizim":"doga"},{"id":"os-6-070","konu":"6.3.3","terim":"Performans çalışma raporu","ingilizce":"Performance report","tanim":"Çalışanın dönem içindeki performansının ölçütlere göre işaretlendiği, yönetici yorumunun ve çalışanın görüşünün yazıldığı, iki tarafın imzaladığı formdur.","ornek":"Formun başında değerlendirme dönemi, çalışanın adı, görevi ve değerlendiren yöneticinin adı yazar; sonunda iki imza yeri vardır.","sektor":"Bölümleri sırasıyla şöyledir: değerlendirme amacı, temel performans ölçütleri, güçlü yönler, gelişim alanları, genel performans sonucu, ödül / terfi / eğitim önerisi, çalışan görüşü ve imzalar. Örnek formda her ölçüt zayıf, geliştirilmeli, iyi, çok iyi ve mükemmel basamaklarından biriyle işaretlenir.","iliskili":["os-6-069","os-6-071","os-6-073"],"kontrol":null,"cizim":"belge-form"},{"id":"os-6-071","konu":"6.3.3","terim":"Performans ölçütleri","ingilizce":"Performance criteria","tanim":"Çalışanın işinin hangi başlıklar altında değerlendirileceğini gösteren, önceden belirlenmiş ölçülerdir.","ornek":"Formdaki “İş disiplini” başlığının altında üç satır vardır: görevini zamanında bitirme, vardiya kurallarına uyma, işine özen gösterme.","sektor":"Örnek bir performans formunda beş temel başlık vardır: iş disiplini ve sorumluluk bilinci, hizmet kalitesi ve misafir iletişimi, ekip çalışması ve iletişim, problem çözme ve inisiyatif (gerektiğinde kendiliğinden sorumluluk alma), öğrenme isteği ve gelişim. Ölçüt önceden bilinir ve herkese aynı uygulanırsa değerlendirme adil olur. Stajyer de aynı gözle izlenir: dakiklik, güler yüz, ekiple uyum, öğrenme isteği. Ders kitabının performans raporu etkinliğinde ölçütler üç başlıkta toplanır: mesleki bilgi ve beceri, iş birliği ve koordinasyon, meslek etiği ve motivasyon.","iliskili":["os-6-070","os-6-069","os-6-010"],"kontrol":null},{"id":"os-6-072","konu":"6.3.3","terim":"Güçlü yönler ve gelişim alanları","ingilizce":"Strengths and areas for development","tanim":"Değerlendirme sonunda çalışanın iyi yaptığı işlerin ve daha iyi hâle getirmesi gereken becerilerin ayrı ayrı yazıldığı bölümlerdir.","ornek":"Güçlü yön: “Konuklarla sıcak ve sabırlı iletişim kuruyor.” Gelişim alanı: “Yoğun saatlerde otel yönetim sistemini daha hızlı kullanmalı.”","sektor":"“Zayıf yön” yerine “gelişim alanı” denmesi bilinçli bir seçimdir: eksiklik bir kusur değil, çalışılacak bir konudur. Gelişim alanı, çalışanın daha iyi hâle getirmesi gereken beceridir; rapor buna eğitim ya da gelişim planı gibi somut bir öneri ekler.","iliskili":["os-6-070","os-6-038","os-6-074"],"kontrol":null,"cizim":"tren"},{"id":"os-6-073","konu":"6.3.3","terim":"Çalışan görüşü","ingilizce":"Employee's comments","tanim":"Performans raporunda çalışanın kendi çalışmasını değerlendirdiği ve aldığı değerlendirmeyle ilgili düşüncesini yazdığı bölümdür.","ornek":"Görevli bu bölüme “Yabancı dil konusunda destek almak istiyorum.” yazar ve formu imzalar.","sektor":"Değerlendirme tek yönlü bir hüküm değil, karşılıklı konuşmadır; bu yüzden raporu hem değerlendiren yönetici hem çalışan imzalar. Katılmadığın bir nokta varsa bunu saygılı bir dille bu bölüme yazarsın.","iliskili":["os-6-070","os-6-074","os-6-039"],"kontrol":null,"cizim":"konusma"},{"id":"os-6-074","konu":"6.3.3","terim":"Yapıcı geri bildirim","ingilizce":"Constructive feedback","tanim":"Çalışana işinde neyi iyi yaptığını ve neyi nasıl düzeltebileceğini, kişiliğini hedef almadan ve somut örnekle anlatan değerlendirmedir.","ornek":"Şef, stajyeri kenara çeker: “Konuğu çok güzel karşıladın. Yalnız oda numarasını yüksek sesle söyledin; bir dahaki sefere kartın üstünde göster.”","sektor":"Övgü herkesin önünde yapılabilir, eleştiri baş başa yapılır; konuğun ya da ekibin önünde azarlamak geri bildirim değildir. Sana verilen geri bildirimi savunmaya geçmeden dinlemen, performans raporundaki “geri bildirimlere açıklık” satırının karşılığıdır.","iliskili":["os-6-072","os-6-073","os-6-069"],"kontrol":null,"kitapDisi":true,"cizim":"konusma"},{"id":"os-6-075","konu":"6.3.3","terim":"Terfi","ingilizce":"Promotion","tanim":"Başarılı çalışanın daha fazla yetki ve sorumluluk taşıyan bir üst göreve getirilmesidir.","ornek":"Birkaç sezondur başarıyla çalışan resepsiyon görevlisi, şefin emekli olmasıyla resepsiyon şefliğine getirilir.","sektor":"Performans raporunun “ödül / terfi / eğitim önerisi” bölümünde yönetici şu seçeneklerden uygun olanı işaretler: prim önerilir, terfiye uygun, eğitim planına alınmalı, mevcut pozisyonda gelişim planı. Yükselme yolunun açık olduğunu gören ekip daha istekli çalışır; otelcilikte kariyer basamak basamak ilerler.","iliskili":["os-6-070","os-6-036","os-6-072"],"kontrol":null},{"id":"os-6-077","konu":"6.3.3","terim":"Performans çalışma raporunun unsurları","ingilizce":"Elements of a performance report","tanim":"Çalışanın görev bilinci ve sorumluluğunun, iletişim becerilerinin, hizmet standartlarına uyumunun, problem çözme ve öz düzenlemesinin, motivasyon ve iş birliğinin değerlendirildiği beş başlıktır.","ornek":"Şef bir görevlinin dosyasına bakar: vardiyalarına zamanında gelmiş (görev bilinci), konuklarla nazik konuşmuş (iletişim), karşılama standardına uymuş (hizmet standardı), uzun kuyrukta sakin kalmış (öz düzenleme), yoğun günde ekip arkadaşına yardım etmiş (iş birliği).","sektor":"Bu beş başlık raporun nelere bakacağını genel olarak gösterir; örnek formdaki beş ölçüt başlığı (iş disiplini, hizmet kalitesi, ekip çalışması, problem çözme, öğrenme isteği) bunların ayrıntılı hâlidir. Öz düzenleme, beklenmedik bir durumda duygu ve davranışını kontrol edebilmektir.","iliskili":["os-6-071","os-6-070","os-6-078"],"kontrol":null,"cizim":"belge-form"},{"id":"os-6-078","konu":"6.3.3","terim":"Genel performans sonucu","ingilizce":"Overall performance rating","tanim":"Performans raporunun sonunda çalışanın dönem boyunca genel durumunun beklentinin altında, beklentiyi karşılıyor, beklentinin üzerinde ya da üstün performans düzeylerinden biriyle belirtilmesidir.","ornek":"Sezon sonu formunda şef, kat görevlisi için “beklentinin üzerinde” kutusunu işaretler; gerekçe olarak yoğun haftalarda hiç şikâyet almamasını ve yeni gelenlere yardım etmesini yazar.","sektor":"Dört düzey düşükten yükseğe beklentinin altında, beklentiyi karşılıyor, beklentinin üzerinde ve üstün performanstır. Tek işaret çalışanın sezonunu özetlediği için ölçütlerdeki işaretlerle ve yönetici yorumuyla tutarlı olmalıdır.","iliskili":["os-6-070","os-6-071","os-6-077"],"kontrol":null,"cizim":"grafik"}],"sorular":[{"id":"os-6-s01","tur":"coktan-secmeli","soru":"Resepsiyon görevlisi Deniz, izin ve sorunları için önce ön büro şefine başvurur, talimatı da ondan alır. Şef, Deniz’in neyidir?","secenekler":["Astı","Amiri","Meslektaşı","Danışmanı"],"dogru":1,"aciklama":"Doğrudan bağlı olunan, talimat alınan ve ilk başvurulan yönetici amirdir. Ast ise tersidir: Deniz şefin astıdır; meslektaş aynı düzeydeki arkadaşı anlatır."},{"id":"os-6-s02","tur":"coktan-secmeli","soru":"Kat şefi bayram haftasında önce kaç odanın çıkacağını hesaplıyor, ardından ekibi katlara bölüyor. Bu iki adım sırasıyla hangi yönetim fonksiyonlarıdır?","secenekler":["Kontrol, sonra yönlendirme","Örgütleme, sonra planlama","Yönlendirme, sonra örgütleme","Planlama, ardından örgütleme"],"dogru":3,"aciklama":"Odaların hesaplanması planlama, ekibin katlara bölünmesi örgütlemedir. “Yönlendirme” ise sabah görevleri anlatmak gibi işin başlamasını sağlayan adımdır; sıra da planlamadan örgütlemeye gider."},{"id":"os-6-s03","tur":"coktan-secmeli","soru":"Ön büro müdürü resepsiyon şefine “Bu hafta oda değişikliği kararlarını sen ver, bana sormana gerek yok.” diyor. Bu uygulama hangisidir?","secenekler":["Yetki devri (delegasyon)","Görev dağılımı","Emir komuta zinciri","Performans değerlendirmesi"],"dogru":0,"aciklama":"Yetki devrinde iş ile birlikte o işe ilişkin karar hakkı da astına bırakılır. Görev dağılımı yalnız kimin hangi işi ne zamana kadar yapacağını belirler; karar hakkı vermez."},{"id":"os-6-s04","tur":"coktan-secmeli","soru":"Resepsiyon görevlisi Ada, işi gereği konuğa oda yükseltmesi yapabiliyor; gün sonunda kaç yükseltme yaptığını da şefine anlatmak zorunda. Bu iki durum sırasıyla hangi kavramlardır?","secenekler":["Sorumluluk, yetki","Yetki devri, liderlik","Yetki, sorumluluk","Liderlik, yetki"],"dogru":2,"aciklama":"Karar verme ve işlem yapma hakkı yetkidir; işi doğru yapıp sonucunun hesabını verebilmek sorumluluktur. Yetki devri ise yöneticinin bu hakkı astına bırakmasıdır, Ada’nın durumunu tek başına anlatmaz."},{"id":"os-6-s05","tur":"coktan-secmeli","soru":"Müdür toplantıyı yönetti ve kararlar tutanağa yazıldı. Toplantı sürecinin sıradaki adımı hangisidir?","secenekler":["Gündemi tüm katılımcılara duyurmak","Kararları birimlere yazılı iletmek","Toplantı salonunu ve sunumu hazırlamak","Gündem sırasını yeniden düzenlemek"],"dogru":1,"aciklama":"Süreç hazırlama, uygulama, yönetme ve sonuçları ilgili birimlere yazılı iletme sırasıyla ilerler; kararlar duyulmadıkça uygulanamaz. Gündemi duyurmak ve salonu hazırlamak toplantıdan önceki adımlardır."},{"id":"os-6-s06","tur":"coktan-secmeli","soru":"Gündem ile tutanak arasındaki fark hangisidir?","secenekler":["Gündem kararları kaydeder, tutanak konuları sıralar.","İkisi de toplantı bittikten sonra hazırlanır.","Tutanak önceden duyurulur, gündem sonradan yazılır.","Gündem önceden duyurulur, tutanak kararları kaydeder."],"dogru":3,"aciklama":"Gündem görüşülecek konuların önceden duyurulan listesidir; tutanak ise toplantıda alınan kararların, sorumluların ve tarihlerin yazıldığı belgedir. Birincisi hazırlık, ikincisi kayıt işlevi görür."},{"id":"os-6-s07","tur":"coktan-secmeli","soru":"Aşağıdaki tutanak satırlarından hangisi eksiksizdir?","secenekler":["Karar: Akşam vardiyasına kişi eklenecek. Sorumlu: ön büro müdürü. Tarih: cuma.","Karar: Akşam vardiyasına bir kişi eklenecek. Tarih: cuma gününe kadar yapılacak.","Karar: Akşam vardiyasına bir kişi eklenecek. Sorumlu: herkes birlikte ilgilenecek.","Sorumlu: ön büro müdürü. Tarih: cuma. Toplantı verimli geçti, konular konuşuldu."],"dogru":0,"aciklama":"Tutanak, alınan kararı, işi kimin üstlendiğini ve bitiş tarihini birlikte yazar. “Herkes” sorumlu olunca işi kimse sahiplenmez; kararı olmayan satırın da bir işe yaradığı söylenemez."},{"id":"os-6-s08","tur":"coktan-secmeli","soru":"Gece vardiyasında bir konuğun bagajının kaybolduğu fark edildi. Olayın ne zaman, nerede olduğunu ve neler yapıldığını yazan belge hangisidir?","secenekler":["Faaliyet raporu","Yönetici özet raporu","Olay raporu","Performans çalışma raporu"],"dogru":2,"aciklama":"Kayıp, hasar, kaza ya da ciddi şikâyet gibi olağan dışı olaylar olay raporuna yazılır. Faaliyet raporu bölümün olağan çalışmalarını özetler, olay anlatmak için yazılmaz."},{"id":"os-6-s09","tur":"coktan-secmeli","soru":"Bir yıl önce biten etkinliğin sözleşmeleri günlük işte kullanılmıyor ama ileride gerekebilir. Bu belgeler için en uygun uygulama hangisidir?","secenekler":["Her gün bakılsın diye masadaki klasörde tutmak","Güvenli bir yerde düzenli biçimde saklamak","Özetini çıkarıp asıl belgeleri imha etmek","Her ay yeni bir klasöre kopyalayıp dağıtmak"],"dogru":1,"aciklama":"İşi bitmiş ama ileride gerekebilecek belgeler arşivlenir. Dosyalama, sık bakılan belgeleri hemen bulunacak biçimde düzenlemektir; asıl belgeyi imha etmek ileride kanıt gerektiğinde sorun çıkarır."},{"id":"os-6-s10","tur":"coktan-secmeli","soru":"Olay raporu yazarken hangi uygulama yanlıştır?","secenekler":["Olayın ne zaman ve nerede olduğunu belirtmek","Olay sırasında yapılan işlemleri sırasıyla yazmak","Olayın nasıl gerçekleştiğini ayrıntılı biçimde anlatmak","Yapılan işlemleri yazmadan yalnız sonucu not etmek"],"dogru":3,"aciklama":"Olay raporu zamanı, yeri, olayın nasıl olduğunu ve ne yapıldığını birlikte anlatır. Yalnız sonucu yazmak, kaydın ne işe yaradığını ve hangi adımların atıldığını gizler; bir sonraki yönetici olayı yeniden kuramaz."},{"id":"os-6-s11","tur":"coktan-secmeli","soru":"Sezon boyunca bir otelde resepsiyon ekibinin yarısı işten ayrıldı. Bunun doğrudan sonucu hangisidir?","secenekler":["Eğitim ve deneyim ekiple gider; yeni gelenlerde hata artar.","Sık gelen konuklar bankoda tanıdık yüz bulmaktan memnun olur.","Çalışanların aidiyet duygusu güçlenir, işe istekleri artar.","Eğitim giderleri azalır, çünkü yeni gelenler işi zaten bilir."],"dogru":0,"aciklama":"Ayrılan her çalışanla birlikte verilen eğitim ve kazanılan deneyim de gider, yenisi işi öğrenene kadar hata artar. Tanıdık yüz ise devir hızı düşük ekipte görülen bir sonuçtur, yüksek ekipte değil."},{"id":"os-6-s12","tur":"coktan-secmeli","soru":"Müdür personel dinlenme odasını yeniledi ve hafta sonu izinlerini dönüşümlü dağıttı. Bu hangi motivasyon yöntemine girer?","secenekler":["Takdir ve ödüllendirme uygulaması","Eğitim ve gelişim fırsatları","Çalışma koşullarını iyileştirme","Sosyal etkinlik ve kutlamalar"],"dogru":2,"aciklama":"Çalışma ortamının ve çalışma düzeninin çalışan lehine düzenlenmesi koşulların iyileştirilmesidir. Takdir, iyi yapılan işin görünür kılınmasıdır; burada böyle bir ödül ya da teşekkür yoktur."},{"id":"os-6-s13","tur":"coktan-secmeli","soru":"Haftalardır izin gününü kullanamayan ve dinlenemeyen bir çalışana “ayın personeli” rozeti verildi, ama isteği artmadı. Maslow’a göre neden?","secenekler":["Çalışan zaten kendini gerçekleştirmiştir, rozeti önemsemez.","Saygı ihtiyacı yalnız yönetici düzeyindeki çalışanlar için geçerlidir.","Rozet ait olma ihtiyacını karşıladığı için etkisi çabuk biter.","Dinlenme gibi alt ihtiyaç karşılanmadan rozet pek harekete geçirmez."],"dogru":3,"aciklama":"Maslow’a göre alttaki, yani fizyolojik ihtiyaç karşılanmadan üsttekiler (saygı, takdir) kişiyi pek harekete geçirmez. Saygı basamağı herkes içindir; çalışan kendini gerçekleştirmiş olsaydı dinlenme ihtiyacı sorun olmazdı."},{"id":"os-6-s14","tur":"coktan-secmeli","soru":"Müdür gece denetiminde boş bir salonda ışıkların ve klimanın açık kaldığını görüyor. Bu gözlem hangi denetim adımına girer?","secenekler":["Standartların kontrolü","Kaynakların kullanımı","Personel performansı","Konuk geri bildirimleri"],"dogru":1,"aciklama":"Enerjinin boşa harcanması kaynak kullanımının konusudur. Personel performansı kişinin işini nasıl yaptığına bakar; burada bir görevlinin işi değil, tesisin gereksiz tüketimi gözleniyor."},{"id":"os-6-s15","tur":"coktan-secmeli","soru":"Sabah 08.30’da konuklar çıkış yapıp faturalarını istiyor, bir kısmı da sabah taleplerini iletiyor. Bu yoğunluk en çok hangi vardiyada yaşanır?","secenekler":["Sabah vardiyası","Akşam vardiyası","Gece vardiyası","Normal (ofis) vardiyası"],"dogru":0,"aciklama":"Ön büroda çıkış işlemleri ve sabah talepleri sabah vardiyasında yoğunlaşır. Akşam vardiyasının yükü giriş işlemleridir; gece vardiyası gün sonu işlemlerine ve güvenliğin izlenmesine ayrılır."},{"id":"os-6-s16","tur":"coktan-secmeli","soru":"Yetişkin çalışanlar için haftalık çalışma süresi en çok 45 saattir. Aşağıdaki haftalık toplamlardan hangisi çizelgeyi bu sınırın dışına çıkarır?","secenekler":["40 saat","45 saat","47,5 saat","38,5 saat"],"dogru":2,"aciklama":"Sınır 45 saattir; 47,5 saat bunu aşar. 45 saat sınırın tam kendisidir ve aşmaz. Müdür çizelgeyi bitirince her satırın haftalık toplamını bu yüzden bu sınırla karşılaştırır."},{"id":"os-6-s17","tur":"coktan-secmeli","soru":"Vardiyası değişen yetişkin bir çalışan en az 11 saat kesintisiz dinlenmelidir. Hangi geçiş çizelgeye yazılamaz?","secenekler":["15.00’te çıkıp ertesi gün 07.00’de başlamak","23.00’te çıkıp ertesi gün 07.00’de başlamak","07.00’de çıkıp ertesi gün 15.00’te başlamak","23.00’te çıkıp ertesi gün 15.00’te başlamak"],"dogru":1,"aciklama":"23.00 ile ertesi gün 07.00 arası yalnız sekiz saattir, 11 saatten azdır. Diğer geçişlerde arada 16 saat ya da daha fazlası vardır; uykusuz çalışan hata yapar."},{"id":"os-6-s18","tur":"coktan-secmeli","soru":"Akşam vardiyasına başlayan Selin, sabahtan kalan bir ütü talebini ve geç gelecek konuğun bilgisini öğrenmek istiyor. Önce nereye bakmalı?","secenekler":["Personel devam raporuna (PDKS)","Geçen ayın faaliyet raporuna","Konukların geri bildirim formlarına","Log book ve devir teslim notuna"],"dogru":3,"aciklama":"Süren işler, bekleyen talepler ve vardiyaya bırakılan notlar log book ile devir teslimde bulunur. Faaliyet raporu geçmiş dönemi özetler; PDKS yalnız çalışanların geliş gidiş saatini gösterir."},{"id":"os-6-s19","tur":"coktan-secmeli","soru":"Aşağıdaki geliş gidiş kayıt yöntemlerinden hangisi kişiyi kendine özgü bedensel özelliğiyle tanır?","secenekler":["Parmak izi ya da yüzle tanınarak girmek","Kartını okuyucuya okutarak girmek","Telefonda karekodu göstererek girmek","Kâğıda saatini yazıp imzalayarak girmek"],"dogru":0,"aciklama":"Parmak izi ve yüz gibi bedensel özelliklerle tanıma biyometrik doğrulamadır. Kart ve karekod bir nesneye, imza çizelgesi ise elle yazılı kayda dayanır; başkasına devredilebilirler."},{"id":"os-6-s20","tur":"coktan-secmeli","soru":"Şef değerlendirme formuna “Yoğun saatlerde sakin kalmakta zorlanıyor.” yazdı. Bu cümle formda hangi bölüme girer?","secenekler":["Güçlü yönler","Çalışan görüşü","Gelişim alanları","Genel performans sonucu"],"dogru":2,"aciklama":"Daha iyi hâle getirilmesi gereken beceriler gelişim alanlarına yazılır. Güçlü yönler iyi yapılan işleri, çalışan görüşü ise çalışanın kendi değerlendirmesini içerir; ikisini şef yazmaz."},{"id":"os-6-s21","tur":"dogru-yanlis","soru":"Denetimde saptanan bir eksik için düzeltici önlem planlanması, aynı hatanın tekrarlanmasını önlemeyi amaçlar.","secenekler":["Doğru","Yanlış"],"dogru":0,"aciklama":"Düzeltici önlem, hatanın yalnız fark edilmesiyle yetinmez; tekrarlanmaması için çözüm planlar ve uygular. Denetim bu sayede çalışanı ve hizmeti geliştirir."},{"id":"os-6-s22","tur":"dogru-yanlis","soru":"Takdir ve ödüllendirme, yalnız prim ya da maaş artışı verildiğinde yapılmış sayılır; teşekkür etmek ve belge vermek sayılmaz.","secenekler":["Doğru","Yanlış"],"dogru":1,"aciklama":"Takdir; teşekkür, belge, prim ya da ödülle çalışanın iyi işini görünür kılmaktır. Ayın personeli seçmek gibi para vermeyen uygulamalar da motivasyonu artırır."},{"id":"os-6-s23","tur":"dogru-yanlis","soru":"Çizelgede “OFF” ya da “X” yazan gün çalışanın haftalık yasal izin günüdür ve bu gün her zaman hafta sonuna gelmek zorundadır.","secenekler":["Doğru","Yanlış"],"dogru":1,"aciklama":"OFF, haftalık yasal dinlenme gününü gösterir; otel hafta sonu da açık olduğundan izin günü çoğu zaman hafta içine gelir. Adil yönetici hafta sonu izinlerini dönüşümlü dağıtır."},{"id":"os-6-s24","tur":"dogru-yanlis","soru":"Yapıcı geri bildirim çalışanın kişiliğini değil işini hedef alır ve somut bir örnekle verilir.","secenekler":["Doğru","Yanlış"],"dogru":0,"aciklama":"Somut örnek çalışana neyi nasıl düzelteceğini gösterir. Kişiliği hedef alan eleştiri yol göstermez, yalnız savunmaya geçirir."},{"id":"os-6-s25","tur":"senaryo","durum":"Akşam vardiyası, saat 21.40, ön büro. Şef akşam yemeğinde. Bir konuk gürültülü odasından yakınıyor ve ücretsiz olarak süite geçirilmesini istiyor.","soru":"Ne yaparsın?","secenekler":["Sistemde boş bir süit bulup konuğu hemen oraya geçiririm.","Yakınmayı dinler, şefimi arayıp oda değişikliği için onay isterim.","Ücretsiz yükseltmenin yapılamayacağını söyleyip konuyu kapatırım.","Şef dönünce bakılacağını söyler, başka bir şey önermem."],"dogru":1,"aciklama":"Ücretsiz yükseltmeyi onaylama yetkisi sende değil. Konuğun gürültü sorunu gerçek, bu yüzden bekletmeden yetkili amirine ulaşırsın. Yetkisiz oda vermek de konuğu geri çevirmek de yanlıştır."},{"id":"os-6-s26","tur":"senaryo","durum":"Vardiyan 23.00’te bitti, eve vardın. Saat 23.40’ta bir konuğun sabah 05.30 için istediği taksiyi log book’a yazmadığını ve gece görevlisine söylemediğini fark ediyorsun.","soru":"Ne yaparsın?","secenekler":["Konuk sabah yeniden sorar, ilk işte durumu çözerim.","Kimseyi rahatsız etmez, sabah erkenden işe gelip taksiyi ayarlarım.","Şefime sabaha okuması için yazılı bir not bırakırım.","Gece görevlisini arar, talebi aktarır, ertesi gün şefime söylerim."],"dogru":3,"aciklama":"Sorumluluk, hatayı saklamak değil telafi etmek ve hesabını vermektir. Gece görevlisi taksiyi zamanında ayarlayabilir; şef de olaydan haberdar olur. Sabaha bırakmak ya da yazılı not, 05.30’da konuğu bekleten gecikmeyi önlemez."},{"id":"os-6-s27","tur":"senaryo","durum":"Aylık toplantıda bir görev sana verildi; tutanağa “Sorumlu: sen. Tarih: cuma.” yazıldı. Çarşamba günü işin cumaya yetişmeyeceğini anlıyorsun.","soru":"Ne yaparsın?","secenekler":["Amirime durumu bildirir, yeni tarih öneririm.","Cuma gününe kadar kimseye söylemeden çalışmaya devam ederim.","İşin bir kısmını haber vermeden bir arkadaşıma bırakırım.","Cuma günü kimse sormazsa konuyu kendim açmam."],"dogru":0,"aciklama":"Tutanakta adın yazılı: işi bitirmek ve sonucunu bildirmek senin sorumluluğundur. Termini kaçıracaksan bunu önceden söylemek, amirin planını değiştirmesine fırsat verir. Sessiz kalmak ya da işi gizlice devretmek güveni zedeler."},{"id":"os-6-s28","tur":"senaryo","durum":"Gece vardiyasının bitmesine on dakika var. Saat 03.00’te bir konuk klimanın bozulduğunu söyledi; teknik servise haber verildi ama onarım sürüyor. Sabah vardiyasından arkadaşın az önce geldi.","soru":"Ne yaparsın?","secenekler":["Teknik servise haber gittiği için bir şey söylemeden vardiyayı kapatırım.","Sabahçıya yalnızca konuğun oda numarasını söyleyip çıkarım.","Olayı ve bekleyen onarımı log book’a yazar, sabahçıya da anlatırım.","Onarım bitene kadar mesai bitse de teknik servisin yanında beklerim."],"dogru":2,"aciklama":"Devir teslimde süren işler ve bekleyen talepler yazılı ve sözlü aktarılır; böylece konuk aynı sorunu yeniden anlatmak zorunda kalmaz. Yalnız oda numarası, ne yapıldığını ve neyin beklendiğini söylemez."},{"id":"os-6-s29","tur":"senaryo","durum":"Sabah 06.58, personel girişi. Parmak izi okuyucusu arıza verdi ve giriş kaydın oluşmadı. Vardiyan 07.00’de başlıyor.","soru":"Ne yaparsın?","secenekler":["Arıza giderilince kaydımı girerim, saatin yanlış çıkmasını önemsemem.","Daha önce gelen bir arkadaşımdan benim yerime kayıt girmesini isterim.","Sistem bozuk olduğu için kayıt gerekmediğini düşünür, bir şey yapmam.","Şefimi bilgilendirir, imza çizelgesine gelişimi yazıp imzalarım."],"dogru":3,"aciklama":"Geliş gidiş kaydı gerçek saatle tutulmalıdır. Sistem çalışmıyorsa şef bilgilendirilir ve imza çizelgesi gibi elle kayıt devreye girer. Başkasına kayıt yaptırmak ya da kaydı boş geçmek yanlış kayıt ve güven sorunu doğurur."},{"id":"os-6-s30","tur":"senaryo","durum":"Ön büro şefisin ve çizelgeyi hazırlıyorsun. Üç haftadır cumartesi ve pazar hep Kaan çalışıyor; “en deneyimli” o ve itiraz etmiyor.","soru":"Ne yaparsın?","secenekler":["Kaan itiraz etmediği için çizelgeyi aynen sürdürürüm.","Hafta sonlarını dönüşümlü dağıtır, Kaan’a teşekkür ederim.","Hafta sonu vardiyalarını yalnız yeni gelen personele yazarım.","Hafta sonu çalışma sırasını kurayla belirler, Kaan’ı kuraya almam."],"dogru":1,"aciklama":"Hafta sonu izinleri adil ve dönüşümlü dağıtılır; hep aynı kişinin çalışması motivasyonu düşürür ve işten ayrılma riskini artırır. Sessiz çalışanı kayırıp yükü yeni gelenlere yıkmak da yeni bir adaletsizliktir."},{"id":"os-6-s31","tur":"senaryo","durum":"Ön büro şefisin. Görevli Berk bu hafta iki kez konukları gereksiz yere uzun bekletti. Gün sonunda onunla baş başa konuşacaksın.","soru":"Ne yaparsın?","secenekler":["“Sen yavaş birisin, bu işe uygun değilsin.” diyerek başlarım.","Bir şey söylemez, dönem sonu raporuna düşük puan yazarım.","Bekleme anlarını örnek gösterir, çözümü birlikte konuşurum.","Ekip grubuna herkesi ilgilendiren genel bir uyarı mesajı yazarım."],"dogru":2,"aciklama":"Yapıcı geri bildirim kişiyi değil davranışı hedef alır, somut örnekle verilir ve çözüm yolunu birlikte arar. Kişiliği yargılamak savunmaya iter; söylemeden rapora yazmak gelişim fırsatı vermez."},{"id":"os-6-s32","tur":"senaryo","durum":"Sezon sonu değerlendirmesi. Şef formda “problem çözme” ölçütünü “beklentinin altında” işaretlemiş; sen son haftadaki su baskınını çözdüğünü hatırlıyorsun ve katılmıyorsun.","soru":"Ne yaparsın?","secenekler":["“Çalışan görüşü” bölümüne örneğimi yazıp formu imzalarım.","Formu imzalamaz ve geçersiz olduğunu söylerim.","Şefin önünde itiraz eder, sonuç değişene kadar tartışırım.","Hiçbir şey yazmadan imzalar, sonra ekipte şikâyet ederim."],"dogru":0,"aciklama":"“Çalışan görüşü”, değerlendirmeye karşı düşünceni somut örnekle yazacağın yerdir. İmzadan kaçmak ya da tartışmak değerlendirmenin amacı olan gelişimi engeller; susmak da görüşünü kayda geçirmeni önler."},{"id":"os-6-s33","tur":"coktan-secmeli","soru":"Bir otelde personel devir hızı yükseldi. Bu ifade neyin arttığını gösterir?","secenekler":["Çalışanların vardiya değiştirme sıklığının","İşten ayrılanların toplam çalışanlara oranının","Yeni işe alınanların eğitimi tamamlama süresinin","Çalışanların haftalık ortalama çalışma saatinin"],"dogru":1,"aciklama":"Devir hızı, işten ayrılanların toplam çalışanlara oranıdır; motivasyon düştükçe artar. Vardiya değişimi, eğitim süresi ve çalışma saati ayrılma oranını ölçmez."},{"id":"os-6-s34","tur":"coktan-secmeli","soru":"Oda görevlisi temizlik sırasında odadaki prizin bozuk olduğunu fark ediyor. Emir komuta zincirine göre bunu ilk kime bildirmelidir?","secenekler":["Otelin genel müdürüne doğrudan","Bağlı olduğu kat şefine","Ön büro müdürüne","Odada kalan konuğa"],"dogru":1,"aciklama":"Emir komuta zincirinde sorun basamak basamak, önce doğrudan bağlı olunan amire, yani kat şefine iletilir. Genel müdüre gitmek basamak atlamaktır; amirin haberi olmadan iş yürür."},{"id":"os-6-s35","tur":"coktan-secmeli","soru":"Saat 07.50. Resepsiyon şefi vardiya başında ekibine birkaç dakika içinde günün yoğun çıkışlarını, öğlen beklenen VIP girişini ve bakımdaki asansörü anlatıyor. Bu kısa buluşma hangisidir?","secenekler":["Kriz toplantısı","Devir teslim","Günlük brifing","Performans görüşmesi"],"dogru":2,"aciklama":"Vardiya başında şefin o günün işlerini ve dikkat edilecek noktaları ekibiyle paylaştığı kısa toplantı günlük brifingdir. Devir teslim ise vardiyası biten görevlinin süren işleri yerine gelene aktarmasıdır."},{"id":"os-6-s36","tur":"coktan-secmeli","soru":"Aşağıdakilerden hangisi dış denetime örnektir?","secenekler":["Ön büro müdürünün akşam lobiyi ve bankoyu dolaşması","Genel müdürün bölümlerden gelen aylık raporları incelemesi","Kat şefinin öğlen hazırlanan odaları kontrol etmesi","Resmî bir kurumun ekibinin otele gelip belge istemesi"],"dogru":3,"aciklama":"Dış denetim resmî kurumlar ya da bağımsız kuruluşlarca dışarıdan yapılır. Müdürün, genel müdürün ya da şefin yaptığı kontroller işletmenin kendi yöneticilerince yapıldığı için iç denetimdir."},{"id":"os-6-s37","tur":"coktan-secmeli","soru":"Bir otel, kat hizmetleri ekibine yeni temizlik malzemelerinin nasıl kullanılacağını kendi eğitim salonunda öğretiyor. İşletmenin hâlen çalışan personeline kendi içinde verdiği bu eğitime ne denir?","secenekler":["Günlük brifing","Hizmet içi eğitim","Yapıcı geri bildirim","Vardiya rotasyonu"],"dogru":1,"aciklama":"Çalışmakta olan personele işletmenin kendi içinde verdiği eğitime hizmet içi eğitim denir. Brifing yalnız o günün bilgilerini paylaşan birkaç dakikalık toplantıdır, yeni bir beceri kazandırmaz."},{"id":"os-6-s38","tur":"coktan-secmeli","soru":"Bir otelde çalışanlar, işlerini kolaylaştıracak fikirlerini personel uygulamasındaki bir form aracılığıyla yönetime gönderiyor. Bu düzen hangisidir?","secenekler":["Öneri sistemi","Konuk geri bildirimi","Log book","Faaliyet raporu"],"dogru":0,"aciklama":"Çalışanların işi iyileştirecek fikirlerini yazılı ya da dijital yolla yönetime ulaştırdığı düzen öneri sistemidir. Konuk geri bildirimi ise çalışandan değil, konuktan gelir."},{"id":"os-6-s39","tur":"dogru-yanlis","soru":"Denetimin asıl amacı, hata yapan çalışanı bulup cezalandırmaktır.","secenekler":["Doğru","Yanlış"],"dogru":1,"aciklama":"Denetim bir ceza aracı değildir; çalışanın performansını geliştirmek, konuk memnuniyetini artırmak ve işletmeyi hedefine ulaştırmak için yapılır. İyi iş takdir edilir, eksik iş gösterilip düzelttirilir."},{"id":"os-6-s40","tur":"coktan-secmeli","soru":"Bir otelde havlular her odada aynı biçimde katlanıp aynı yere konuyor; işi hangi görevli yaparsa yapsın sonuç değişmiyor. Bu uygulamanın dayandığı kavram hangisidir?","secenekler":["Görev dağılımı","Kaynak kullanımı","Vardiya planlaması","Hizmet standardı"],"dogru":3,"aciklama":"Bir işin kim yaparsa yapsın her seferinde aynı kalitede yapılması için önceden belirlenen ölçü ve yöntem hizmet standardıdır. Görev dağılımı yalnız işi kimin yapacağını belirler, nasıl yapılacağını değil."},{"id":"os-6-s41","tur":"coktan-secmeli","soru":"Müdür, son iki haftada üç ayrı konuğun yorum kartına kahvaltıdaki yumurtaların soğuk geldiğini yazdığını görüyor. Bu tablo en çok neyi gösterir?","secenekler":["Konukların beklentilerinin fazla yüksek olduğunu","Yalnız o sabah çalışan aşçının sözlü uyarılması gerektiğini","Sorunun kişiden çok çalışma düzeninden kaynaklandığını","Şikâyetlerin rastlantı olduğunu, önlem gerekmediğini"],"dogru":2,"aciklama":"Tek şikâyet bir olaydır, aynı konunun üst üste gelmesi ise bir işarettir: sorun çoğu zaman kişide değil, düzendedir. Bu yüzden tek bir çalışanı uyarmak sorunu çözmez."},{"id":"os-6-s42","tur":"coktan-secmeli","soru":"Vardiya çizelgesinde bir çalışanın o günkü kutusunda “N” harfi yazıyor. Bu kod neyi gösterir?","secenekler":["Gece vardiyasını","Normal (ofis) vardiyasını","Haftalık izin gününü","Gezici (yedek) personel görevini"],"dogru":1,"aciklama":"Çizelgede N normal (ofis) vardiyasını gösterir. Gece vardiyası G ile, haftalık izin OFF ya da X ile yazılır; “N” harfini gece sanmak sık yapılan bir hatadır."},{"id":"os-6-s43","tur":"dogru-yanlis","soru":"Rezervasyonu olduğu hâlde gelmeyen konukların izlenmesi, yani no-show takibi, en çok akşam vardiyasında yapılır.","secenekler":["Doğru","Yanlış"],"dogru":0,"aciklama":"Konuk girişleri akşam vardiyasında yoğunlaştığı için gelmesi beklenen konukların gelip gelmediği de en çok bu vardiyada izlenir. Check-in ve oda blokajı da bu vardiyanın ana işleri arasındadır."},{"id":"os-6-s44","tur":"coktan-secmeli","soru":"Bir resepsiyon görevlisi aylardır yalnız gece vardiyasında çalışıyor, ekipteki diğer arkadaşları ise hep gündüz. Şefin bu durumda yapması gereken nedir?","secenekler":["Görevli itiraz etmedikçe mevcut düzeni aynen sürdürmek","Görevliye prim verip gece vardiyasında tutmak","Gece vardiyasındaki kişi sayısını bire indirmek","Görevliyi belli aralıklarla gündüze de kaydırmak"],"dogru":3,"aciklama":"Gece çalışmanın bedensel yükü tek kişiye bırakılmaz; vardiya rotasyonuyla gece çalışan görevli belirli aralıklarla gündüz vardiyasına geçirilir. Görevlinin itiraz etmemesi bu sağlık ve adalet kuralını ortadan kaldırmaz."},{"id":"os-6-s45","tur":"coktan-secmeli","soru":"Ön büro müdürü, ekibinden kimin bu sabah işe geç başladığını bilgisayarından anlık olarak görebiliyor. Bunu sağlayan araç hangisidir?","secenekler":["Personel geliş gidiş kontrol sistemi","Personel panosundaki vardiya çizelgesi","Log book (takip defteri)","Yöneticinin tuttuğu performans raporu"],"dogru":0,"aciklama":"PDKS giriş ve çıkış saatlerini dijital olarak kaydeder ve yöneticinin personelin devam durumunu anlık izlemesini sağlar. Vardiya çizelgesi ise kimin ne zaman çalışacağını gösteren bir plandır, gerçek geliş saatini göstermez."},{"id":"os-6-s46","tur":"dogru-yanlis","soru":"Performans raporunun “ödül / terfi / eğitim önerisi” bölümünde yönetici yalnız prim ya da terfi önerebilir; çalışanın eğitim planına alınması bu bölümde önerilmez.","secenekler":["Doğru","Yanlış"],"dogru":1,"aciklama":"Bu bölümde prim önerisi ve terfiye uygunluğun yanında “eğitim planına alınmalı” ve “mevcut pozisyonda gelişim planı” seçenekleri de yer alır. Yani yönetici eğitim de önerebilir."},{"id":"os-6-s47","tur":"coktan-secmeli","soru":"Performans raporundaki genel performans sonucu düzeylerinin düşükten yükseğe sıralanışı hangisidir?","secenekler":["Beklentinin altında, beklentiyi karşılıyor, beklentinin üzerinde, üstün performans","Beklentiyi karşılıyor, beklentinin altında, üstün performans, beklentinin üzerinde","Beklentinin altında, beklentinin üzerinde, beklentiyi karşılıyor, üstün performans","Beklentinin altında, beklentiyi karşılıyor, üstün performans, beklentinin üzerinde"],"dogru":0,"aciklama":"Dört düzey düşükten yükseğe beklentinin altında, beklentiyi karşılıyor, beklentinin üzerinde ve üstün performanstır. Üstün performans en üst düzeydir; beklentinin üzerinde düzeyinden sonra gelir."}],"siralamalar":[{"id":"os-6-r01","konu":"6.1.1","baslik":"Kriz masası: toplantıyı baştan sona yönet","yonerge":"Genel müdür olarak düzenlediğin yönetsel toplantının adımlarını doğru sıraya koy.","adimlar":["Toplantının amacını netleştir: konuk memnuniyetini artırmak ve bölümler arası eşgüdümü sağlamak.","Görüşülecek konuları içeren gündemi hazırla ve ilgili birimlere yazılı ya da dijital olarak duyur.","Toplantıyı başlat ve gündem maddelerini görüşmeye aç.","Bölüm müdürlerinin kendi birimlerindeki sorunları ve çözüm önerilerini sunmasını sağla.","Kararları al; görev dağılımını ve termin sürelerini toplantı tutanağına anında yaz.","Toplantının sonuçlarını ilgili birimlere yazılı olarak ilet."],"aciklama":"Toplantı amaçtan doğar; gündem bu amaca göre hazırlanıp duyurulur, sorunlar dinlendikten sonra karar alınır ve kararlar yazılı iletilmeden toplantı işini bitirmiş sayılmaz."},{"id":"os-6-r02","konu":"6.3.1","baslik":"Gelecek haftanın vardiya çizelgesi","yonerge":"Ön büro müdürü olarak haftalık vardiya çizelgesi hazırlama adımlarını doğru sıraya koy.","adimlar":["Gelecek haftanın doluluğunu incele ve ekibin izin, rapor ve özel gün taleplerini topla.","Doluluğa göre sabah, akşam ve gece vardiyasında en az kaç kişi gerektiğini hesapla.","Haftalık 45 saat sınırını ve vardiyalar arası 11 saatlik dinlenmeyi gözeterek taslak çizelgeyi hazırla.","Onaylanan kesin çizelgeyi vardiya dönemi başlamadan en az 3 gün kala panoda ya da dijital kanalda duyur."],"aciklama":"Kaç kişiye ihtiyaç olduğu doluluk ve çalışabilecek kişiler bilinmeden hesaplanamaz; çizelge bu hesaba ve yasal sürelere göre kurulur, onaylanınca personel hazırlansın diye en az 3 gün öncesinden ilan edilir."},{"id":"os-6-r03","konu":"6.3.3","baslik":"Performans raporu nasıl tamamlanır?","yonerge":"Bir çalışanın performans çalışma raporunu doldurma adımlarını doğru sıraya koy.","adimlar":["Çalışanı iş disiplini, misafir iletişimi, ekip çalışması gibi ölçütlerin her birinde ayrı ayrı değerlendir.","Güçlü yönlerini, gelişim alanlarını ve genel performans sonucunu yaz; prim, terfi ya da eğitim öner.","Çalışanın kendi değerlendirmesini ve geri bildirimini rapora yazmasını sağla.","Raporu imzala ve çalışana da imzalat."],"aciklama":"Rapor formu bu sırayı izler: önce ölçütler tek tek değerlendirilir, sonra güçlü yönler, gelişim alanları, genel sonuç ve öneri yazılır; çalışan kendi görüşünü ekler ve iki taraf imzalayınca rapor tamamlanır."}],"acikSorular":[{"id":"os-6-y01","konu":"6.2","soru":"Bir otelde sezon boyunca yoğun çalışan resepsiyon ekibinin morali düşmüş, bazı çalışanlar işten ayrılmak istediğini söylemektedir. Önce motivasyonun ne demek olduğunu yazınız. Ön büro müdürü olsaydınız ekibin motivasyonunu artırmak için hangi iki yöntemi uygulardınız? Yöntemleri örnekle açıklayınız ve motivasyonun personel devir hızıyla ilişkisini belirtiniz.","olcut":[{"metin":"Motivasyonu doğru tanımlar.","puan":15},{"metin":"Birinci motivasyon yöntemini adıyla yazar ve örnekle açıklar.","puan":25},{"metin":"İkinci motivasyon yöntemini adıyla yazar ve örnekle açıklar.","puan":25},{"metin":"Motivasyon yükseldikçe personel devir hızının düşeceğini nedeniyle açıklar.","puan":35}],"ornek":"Motivasyon, çalışanı işini isteyerek ve elinden gelenin en iyisiyle yapmaya yönelten etkenlerin bütünüdür; ekibin morali düşünce bu istek de azalır. Birinci yöntem takdir ve ödüllendirmedir: konukların teşekkür ettiği görevliyi ayın personeli seçip ekibin önünde teşekkür belgesi verebilirim. İkinci yöntem açık iletişim ve katılımdır: vardiya sonunda ekibe “Bugün sizi en çok ne zorladı?” diye sorar, vardiya düzeni için önerilerini alırım. Çalışanların isteği yükseldikçe işten ayrılanların oranı, yani personel devir hızı düşer; çünkü kendini değerli ve işletmenin parçası gören çalışan ayrılmak istemez.","ipucu":"Yöntemleri yalnızca adlandırmayın; ekibin neden işten ayrılmak istediğini düşünüp çözümün bu nedene nasıl dokunduğunu bağlayın."},{"id":"os-6-y02","konu":"6.3.1","soru":"Bir otelin ön büro müdürü, akşam vardiyası 23.00’te biten bir resepsiyon görevlisini ertesi sabah 07.00 vardiyasına yazmıştır. Bu planlamadaki hatayı açıklayınız, vardiya planlamasında dikkat edilmesi gereken iki noktayı yazınız ve vardiya devir teslimi sırasında görevlinin hangi bilgileri aktarması gerektiğini belirtiniz.","olcut":[{"metin":"Vardiyalar arasında kesintisiz dinlenme süresi gerektiğini ve planlamadaki hatayı belirtir.","puan":25},{"metin":"Vardiya planlamasında dikkat edilecek iki noktayı yazar (iş yükü, yasal kurallar, izin günü gibi).","puan":25},{"metin":"Vardiya devir teslimi sırasında aktarılacak bilgileri (süren işler, bekleyen talepler, önemli notlar) yazar.","puan":20},{"metin":"Eksiksiz devir teslimin hizmetin kesintisiz sürmesi için neden gerekli olduğunu açıklar.","puan":30}],"ornek":"Hata şudur: çalışanın bir vardiyadan çıkıp bir sonrakine başlaması arasında kesintisiz dinlenmesi gereken en az süre on bir saattir; 23.00 ile 07.00 arasında yalnızca sekiz saat olduğu için bu plan uygun değildir. Vardiya planlamasında önce iş yükü gözetilmelidir; örneğin büyük bir grup girişi olan güne bir kişi daha yazılır. İkinci olarak yasal çalışma süreleri ve haftalık izin günü dikkate alınır. Devir teslimde görevli, süren işleri, bekleyen konuk taleplerini ve önemli notları yerine gelen kişiye aktarır, log book’a da yazar. Böylece yeni gelen görevli bilgiyi kaybetmeden işi sürdürür ve konuk hizmeti kesintiye uğramaz.","ipucu":"Planlamayı hem çalışanın dinlenmesi hem de işletmenin hizmetinin kesintisiz sürmesi açısından düşünün."}]}]`),r=JSON.parse(`[{"ders":"otelcilik-seyahat","onay":true,"diyaloglar":[{"id":"os-d01","unite":2,"baslik":"Akşam Santralde Rezervasyon Değişikliği","rol":"Santral görevlisi","sahne":"Saat 19.10. Otelin telefonu çalıyor; hattaki konuk rezervasyonunun tarihini değiştirmek istiyor. Görüşmeyi santraldeki görevli baştan sona kendisi yürütecek.","kavramlar":["os-2-085","os-2-083","os-2-103","os-2-086","os-2-087"],"adimlar":[{"konuk":"Alo? Orası otel mi?","ingilizce":"Hello? Is that the hotel?","secenekler":[{"metin":"Alo? Efendim, buyurun, kimi aramıştınız?","puan":0,"tepki":"Konuk tedirgin olur: “Doğru yere mi aradım?” Otel telefonu “Alo?” ya da “Efendim?” diye açılmaz; arayan, kiminle konuştuğunu ilk cümlede öğrenmelidir."},{"metin":"İyi akşamlar, resepsiyon, ben Selin. Size nasıl yardımcı olabilirim?","ingilizce":"Good evening, reception, Selin speaking. How may I help you?","puan":2,"tepki":"Konuk rahatlar: “Evet, doğru yere aramışım.” Selamdan sonra ad ve kurum söylendiği için görüşme baştan düzenli ve güvenilir başlar."},{"metin":"İyi akşamlar, buyurun, size nasıl yardımcı olabilirim, hangi birimi arıyordunuz, rezervasyon mu?","puan":1,"tepki":"Selam var, ama konuk yine de “Burası hangi birim, kimle konuşuyorum?” diye düşünür. Selamdan sonra ad ve kurum bilgisi de söylenmeliydi."}]},{"konuk":"Ben Hakan Demir. 20 Ekim için iki kişilik bir rezervasyonum var. Uçuşum değişti, bir gün erken, yani 19 Ekim’de gelmem gerekiyor.","ingilizce":"My name is Hakan Demir. I have a booking for two people on 20 October. My flight has changed, so I need to arrive a day earlier, on 19 October.","secenekler":[{"metin":"Rezervasyonunuza bakmam gerekiyor, hatta kalın lütfen, birazdan dönerim efendim.","puan":1,"tepki":"Konuk hatta kalır ama emir almış gibi hisseder. Bekleme nedeni söylenmiş, fakat izin istenmemiş; konuk beklemeye alınmadan önce sorulmalıdır."},{"metin":"Şu an çok yoğunum, tarih değişikliği için biraz sonra tekrar arayın, rica ederim, olur mu?","puan":0,"tepki":"Konuk dinlenmeden geri çevrilir ve derdini baştan anlatmak zorunda kalır. Telefondaki konuğun isteği o anda dikkatle dinlenip ele alınmalıdır."},{"metin":"Not alıyorum efendim. Rezervasyonunuzu kontrol etmem için sizi bekletebilir miyim?","ingilizce":"I'll make a note of that, sir. May I put you on hold while I check your reservation?","puan":2,"tepki":"Konuk “tabii” der. Önce kısa bir geri bildirim verildi, sonra bekleme nedeni söylenip izin istendi; konuk habersiz bekletilmediği için hatta sabırla kalır."}]},{"konuk":"Alo? Hâlâ hatta mısınız?","ingilizce":"Hello? Are you still on the line?","secenekler":[{"metin":"Evet efendim, beklediğiniz için teşekkür ederim. 19 Ekim’de oda uygun, değişikliği yapıyorum.","ingilizce":"Yes, sir. Thank you for waiting. A room is available on 19 October, and I am making the change.","puan":2,"tepki":"Konuk memnun olur. Hatta dönünce beklediği için teşekkür edildi ve sonuç net söylendi; kısa bekleme konuğu rahatsız etmedi."},{"metin":"Evet, buradayım. 19 Ekim’de oda uygun görünüyor, değişikliğe geçiyorum; bekleme için kusura bakmayın.","puan":1,"tepki":"Konuk bilgiyi alır, ama beklediği için teşekkür edilmediğini fark eder. Hatta dönünce teşekkür etmek küçük bir ayrıntı gibi görünse de görüşmenin kalitesini yükseltir."},{"metin":"Sistem çok yavaş, biraz daha bekleyin lütfen; hemen bitiyor.","puan":0,"tepki":"Konuk sabırsızlanır ve hattı kapatmak ister. Habersiz ve uzun beklemiş konuk çoğu zaman telefonu kapatır; sistemden şikâyet etmek yerine bilgi vermek gerekirdi."}]},{"konuk":"Güzel. Bir de kahvaltı kaçta başlıyor?","ingilizce":"Lovely. And what time does breakfast start?","secenekler":[{"metin":"Galiba sabah yedi gibi, sanırım; emin değilim.","puan":0,"tepki":"Konuk güvenmez: “Peki ben ne yapacağım?” “Galiba” ve “sanırım” gibi sözler konukta güvensizlik yaratır; bilinmiyorsa tahmin yürütülmez, öğrenilir."},{"metin":"Kahvaltı 07.00’de başlıyor, salon giriş katında. Başka sorunuz var mı efendim?","ingilizce":"Breakfast starts at 7 a.m., and the dining room is on the ground floor. Is there anything else I can help you with?","puan":2,"tepki":"Konuk “Teşekkürler, tam aradığım bilgi” der. Saat ve yer kısa söylendi, başka sorusu olup olmadığı soruldu; görüşme gereksiz uzamadan kapanışa hazırlandı."},{"metin":"Kahvaltı 07.00’de başlıyor. Ayrıca havuzumuz, spa merkezimiz, restoranımız ve toplantı salonlarımız var.","puan":1,"tepki":"Bilgi doğru, ama konuk sormadığı şeyleri de dinlemek zorunda kalır. Telefon görüşmesi kısa ve amaca uygun tutulmalı; hat meşgulken başka konuklar da bekler."}]},{"konuk":"Teşekkürler, başka sorum yok.","ingilizce":"Thank you, I have no other questions.","secenekler":[{"metin":"Tamam efendim, iyi günler, hoşça kalın.","puan":1,"tepki":"Görüşme kabaca bitti ama teşekkür eksik kaldı. Görüşmenin son cümlesi akılda kalır; teşekkür ve iyi dilek eklenmeliydi."},{"metin":"Peki, başka bir şey yoksa kapatıyorum. (Telefonu kapatır.)","puan":0,"tepki":"Konuk birden kapanan telefonu duyar ve o ana kadarki özenin değeri düşer. Teşekkürsüz bitirilen görüşme bütün emeği boşa çıkarır."},{"metin":"Aradığınız için teşekkür ederim, iyi akşamlar dilerim.","ingilizce":"Thank you for calling. Have a pleasant evening.","puan":2,"tepki":"Konuk sıcak bir sesle “Size de, iyi akşamlar” der. Teşekkür ve iyi dilekle biten görüşme, konuğun aklında olumlu kalır."}]}]},{"id":"os-d02","unite":2,"baslik":"Kapıda İlk Dakikalar","rol":"Bellboy","sahne":"Saat 14.00, otel girişi. Uzun bir yolculuktan gelen bir çift taksiden iniyor; valizleri yanlarında; konuşmayı eşlerden erkek olanı yapıyor. Bellboy kapıda; konuğun ilk karşılaştığı kişi o.","kavramlar":["os-2-054","os-2-053","os-2-048","os-2-036","os-2-051"],"adimlar":[{"konuk":"İyi günler, rezervasyonumuz var. Valizleri nereye bırakacağız?","ingilizce":"Good afternoon, we have a booking. Where should we leave our luggage?","secenekler":[{"metin":"(Telefondaki mesaja bakmayı sürdürür.) Resepsiyon içeride, şu kapıdan girin.","puan":0,"tepki":"Konuk bir an bekler, sonra homurdanarak yürür. Konuşurken telefona bakmak “Sana önem vermiyorum” mesajı verir; ilk izlenim daha kapıda bozulur."},{"metin":"(Doğrulur, gözlerine bakıp gülümser.) Hoş geldiniz efendim, valizlerinizi ben alayım.","ingilizce":"Welcome, sir. Let me take your bags.","puan":2,"tepki":"Konuk gülümseyerek “Teşekkürler” der. Dik duruş, göz teması, gülümseme ve nazik jest sözden önce geldiği için konuk daha ilk dakikada kendini değerli hisseder."},{"metin":"(Gülümsemeden, başıyla işaret ederek.) Hoş geldiniz efendim, resepsiyon içeride, buyurun.","puan":1,"tepki":"Söz doğru, ama yüz ve duruş aynı sıcaklığı taşımıyor; konuk karşılandığını pek hissetmez. Karşılamada söz, göz teması ve gülümsemeyle birlikte gelmelidir."}]},{"konuk":"Çok yorgunuz, yol bitmek bilmedi. Üstüne bir de bavulun tekerleği kırıldı.","ingilizce":"We are exhausted, the journey seemed endless. And now the wheel of our suitcase has broken.","secenekler":[{"metin":"(Aynı gülümsemeyle.) Önemli değil efendim, olur öyle şeyler, hemen resepsiyona geçelim!","puan":1,"tepki":"Konuk içinden “Ciddiye alınmadım” diye düşünür. Her duruma aynı gülümsemeyle karşılık vermek profesyonellik değil, ezberdir; sorun yaşayan konuğa duygusuna uygun bir yüzle yaklaşılır."},{"metin":"(Ciddi ve ilgili bir yüzle, hafifçe öne eğilerek.) Geçmiş olsun, bavulu elimle taşırım.","ingilizce":"I am sorry to hear that, sir. I will carry it by hand.","puan":2,"tepki":"Konuk rahatlar: “Anlaşıldım.” Yüz ifadesi ve duruş konuğun o anki duygusuna uydurulduğu için empati sözle birlikte beden diliyle de gösterildi."},{"metin":"(Kollarını göğsünde kavuşturur.) Tekerleği taksici kırmıştır herhalde, ona sormanız lazım.","puan":0,"tepki":"Konuk kapanır ve geri çekilir. Kavuşturulan kollar iletişime kapalı olma işareti sayılır; üstelik konuğun derdi sahiplenilmeyip yok sayılmış olur."}]},{"konuk":"Sağ olun... Yalnız şu çantamı kendim taşıyabilirim.","ingilizce":"Thank you... but I can carry this bag myself.","secenekler":[{"metin":"(Olduğu yerde kalıp.) Ağır görünüyor efendim, yine de verirseniz memnuniyetle taşırım.","puan":1,"tepki":"Konuk çantayı tutmaya devam eder. Söz kibar, ama konuk geri çekilirken mesafe açılmadı; yerinde kalmak yerine bir adım geri çekilip alan bırakmak gerekirdi."},{"metin":"(Bir adım açılır, açık eliyle diğer valizi gösterir.) Elbette efendim, diğerlerini ben alayım.","ingilizce":"Of course, sir. I will take the others.","puan":2,"tepki":"Konuk rahatlar ve gülümser. Konuğun geri çekildiği fark edildi, mesafe açıldı; konuk rahat konuşabileceği bir açıklıkta kalınca kendini güvende hisseder."},{"metin":"(Biraz daha yaklaşıp elini uzatır.) Verin efendim, çanta ağır, düşürürsünüz.","puan":0,"tepki":"Konuk iyice geri çekilir, yüzü gerilir. Konuk geri çekiliyorsa mesafe zaten fazla yakındır; daha da yaklaşmak onu rahatsız eder."}]},{"konuk":"Teşekkürler, size zahmet oldu. Gerçekten sorun olmadı mı?","ingilizce":"Thank you, sorry for the trouble. Was it really no problem?","secenekler":[{"metin":"(Gözlerine bakıp gülümser, dik durur.) Hiç zahmet değil efendim, memnuniyetle.","ingilizce":"It is no trouble at all, sir. It is my pleasure.","puan":2,"tepki":"Konuk içtenliğe inanır: “Ne güzel bir karşılama.” Söz, yüz ifadesi ve duruş aynı mesajı verdiği için söylenen cümle inandırıcı oldu."},{"metin":"(Gözlerini kaçırıp kollarını bağlar.) Hiç sorun değil efendim, rahat olun, siz bakmayın bana.","puan":0,"tepki":"Konuk “Söylediği gibi değil” diye düşünür. Söz ile beden çeliştiğinde karşıdaki çoğu zaman bedene inanır; göz kaçırmak ve kolları bağlamak sözü boşa çıkarır."},{"metin":"(Düz bir yüzle, saatine bakar.) Hiç zahmet değil efendim, rica ederim.","puan":1,"tepki":"Söz doğru, ama saate bakmak sabırsızlık gibi okunur. Konuk “acelesi var galiba” diye düşünür ve teşekkürünü rahatça söyleyemez."}]},{"konuk":"Resepsiyon şuradaki tezgâh mı?","ingilizce":"Is reception the desk over there?","secenekler":[{"metin":"(Konuğa dönük durup açık eliyle gösterir.) Evet efendim, tam karşıda. İyi konaklamalar!","ingilizce":"Yes, sir, straight ahead. Enjoy your stay!","puan":2,"tepki":"Konuk gülümseyerek “Teşekkürler” der. Konuğa dönük durup açık elle yol gösterildiği için ilgi sıcak ve içten hissedildi; veda, karşılama kadar önemlidir."},{"metin":"(Eliyle işaret edip bakışını başka yere çevirir.) Evet efendim, şu tezgâh, orada size bakarlar, buyurun.","puan":1,"tepki":"Yön doğru verildi, ama bakış başka yerde olduğu için konuk ilgisiz bir veda gördü. Bakış ve duruş, söz kadar mesaj taşır."},{"metin":"(Telefonunu çıkarıp bakar.) Hı hı, şurası, bakarsınız.","puan":0,"tepki":"Konuk, yarım ağızdan bir cevap alır ve vedasız bırakılır. Konuşurken telefona dönmek karşıdakine önem verilmediğini gösterir; karşılamada kurulan olumlu izlenim bozulur."}]}]},{"id":"os-d03","unite":2,"baslik":"Yarım Kalan Cümle","rol":"Acente danışmanı","sahne":"Saat 11.00, bir seyahat acentesinin masası. Bir anne yaz tatili için danışmanlık almaya geliyor; çocuğu küçük, bütçesi sınırlı. Danışmanın işi önce konuğu doğru anlamak.","kavramlar":["os-2-012","os-2-106","os-2-027","os-2-025","os-2-020"],"adimlar":[{"konuk":"Merhaba, ağustosta ailemle tatile gitmeyi düşünüyoruz.","ingilizce":"Hello, we are thinking of going on holiday with my family in August.","secenekler":[{"metin":"(Ekrandan başını kaldırır, konuğa döner.) Hoş geldiniz efendim, buyurun. Sizi dinliyorum.","ingilizce":"Welcome, madam, please go ahead. I am listening.","puan":2,"tepki":"Konuk oturur ve rahatça anlatmaya başlar. Dikkat konuğa verildiği için daha ilk saniyede dinleneceğini anlar."},{"metin":"(Bilgisayara bakarak.) Hoş geldiniz efendim, buyurun, ne istiyordunuz acaba?","puan":1,"tepki":"Konuk soruyu cevaplar ama kendini yarım hisseder. Selam var, ancak gözler ekranda olduğu için dikkat konuğa verilmemiştir."},{"metin":"(Telefonla yazışmaya devam eder.) Bir saniye, şu mesajı bitireyim, hemen sonra size bakarım, oturun biraz.","puan":0,"tepki":"Konuk içeri girer girmez ikinci planda kalır. Başka işle uğraşırken dinlenmeye çalışılan konuk anlatmaktan vazgeçebilir."}]},{"konuk":"Üç kişiyiz, kızım altı yaşında. Deniz kenarı olsun, ama çok kalabalık olmasın. Bir de ulaşım konusunda...","ingilizce":"There are three of us, and my daughter is six. We want the seaside, but nowhere too crowded. And for transport...","secenekler":[{"metin":"Tamam, çocuk kulübü olan sakin bir otel arıyorsunuz, hemen listeliyorum.","puan":0,"tepki":"Konuk cümlesini yarım bırakır: “Ulaşımı söyleyecektim...” Cümle bitmeden araya girmek konuğun önemsenmediği izlenimini verir, söylemek istediği yarım kalır."},{"metin":"Hı hı, anladım. Ama önce otelleri bir göstereyim.","puan":1,"tepki":"Konuk sessizce razı olur, ama söyleyeceği yarım kalmıştır; cümlenin sonu beklenmeden konu değiştirildi."},{"metin":"Evet, devam edin lütfen, not alıyorum.","ingilizce":"Yes, please go on. I am taking notes.","puan":2,"tepki":"Konuk rahatlayıp devam eder. Söz kesilmedi, kısa bir karşılıkla dinlendiği gösterildi; asıl istek bu sayede eksiksiz duyuldu."}]},{"konuk":"...Ulaşım için arabamız olmayacak, havalimanından otele transfer olsun isterim. En çok da sessiz bir yer istiyorum.","ingilizce":"...We will not have a car, so I would like a transfer from the airport to the hotel. Above all, I want a quiet place.","secenekler":[{"metin":"Peki, ben size iyisini bulurum; çok iyi yerler biliyorum, hemen ayarlarım.","puan":0,"tepki":"Konuk içinden “Anladı mı acaba?” diye düşünür. Anladığını göstermeyen danışman, yanlış tarihte ya da yanlış türde bir otel bulabilir; önemli bilgiler tekrar edilmeden işlem yapılır."},{"metin":"Tamam, anladım: sakin bir otel ve havalimanı transferi. Hemen bakıyorum.","puan":1,"tepki":"Konuk “ağustos” ve “üç kişi” bilgilerinin duyulup duyulmadığından emin olamaz. Otel türü ve transfer tekrar edildi; tarih ve kişi sayısı da özetlenseydi hata kalmazdı."},{"metin":"Doğru anladıysam: ağustosta üç kişi, sakin bir deniz kenarı otel ve transfer istiyorsunuz, öyle mi?","ingilizce":"If I understood correctly: you need a quiet seaside hotel for three people in August, with a transfer. Is that right?","puan":2,"tepki":"Konuk “Evet, aynen” der. Söylenenler kendi cümleleriyle tekrar edildi; bu teyit hem hatayı önledi hem de konuğa “Sizi gerçekten duydum” dedi."}]},{"konuk":"Bütçemiz çok yüksek değil ama kızımız için iyi bir yer olsun. Ne kadar tutar, hiç bilmiyorum.","ingilizce":"Our budget is not very high, but we want somewhere good for our daughter. I have no idea how much it costs.","secenekler":[{"metin":"Anladım. Gecelik ne kadarlık bir tutar sizi rahat ettirir, söyler misiniz?","ingilizce":"I see. What nightly amount would be comfortable for you? Could you tell me?","puan":2,"tepki":"Konuk rahatlar ve rakamı söyler. Anlaşılmayan yer tahmin edilmedi, açıklayıcı bir soruyla netleştirildi; yanlış bütçeyle yapılacak bir seçim önlendi."},{"metin":"Anladım. Orta fiyatlı ve çocuklara uygun bir yer ayarlarım, ama size uygun mu bilmiyorum.","puan":1,"tepki":"Konuk “orta” dendiğinde neyin kastedildiğini bilemez. Dürüst bir cümle, ama bütçe sorulmadan tahmin yürütüldü; rakam konuşulmadan seçilen otel konuğu kırabilir."},{"metin":"Bütçeyi net söylemezseniz size yardımcı olamam, kusura bakmayın.","puan":0,"tepki":"Konuk geri çekilir: “Ben bilmiyorum diyorum.” Anlamadığı yeri açıklayıcı soruyla çözmesi gereken danışman, konuğa yük bindirerek ilgisiz görünür."}]},{"konuk":"Peki, bana ne zaman dönmeyi düşünüyorsunuz?","ingilizce":"So, when are you planning to get back to me?","secenekler":[{"metin":"En kısa sürede size dönerim efendim, ilgileneceğiz.","puan":1,"tepki":"Konuk “Ne zaman?” diye düşünür. Söz verildi, ama “en kısa sürede” net bir zaman değildir; konuk beklemekten emin olamaz."},{"metin":"Bilmiyorum, uygun olunca ararım; şimdi çok işim var, kusura bakmayın, bu sabah çok yoğunuz.","puan":0,"tepki":"Konuk güvenini kaybeder. Belirsiz ve ilgisiz cevap, az önce kurulan güveni bozar; netlik olmadan konuk beklemeye geçemez."},{"metin":"Yarın öğlene kadar üç seçenekle sizi arayacağım. Teşekkürler, iyi günler.","ingilizce":"I will call you with three options by noon tomorrow. Thank you, and have a good day.","puan":2,"tepki":"Konuk gülümseyerek ayrılır: “Sizi bekliyorum.” Zaman ve yapılacak iş açık söylendi; belirsiz kalan hiçbir yer bırakılmadı."}]}]},{"id":"os-d04","unite":2,"baslik":"Uykusuz Bir Gecenin Ardından","rol":"Konuk ilişkileri görevlisi","sahne":"Saat 09.30, konuk ilişkileri masası. Bir önceki gece yan odadan gelen müzik sesi yüzünden uyuyamayan bir konuk, sinirli hâlde masaya geliyor.","kavramlar":["os-2-009","os-2-027","os-2-010","os-2-064","os-2-104"],"adimlar":[{"konuk":"Dün gece ikiye kadar yan odadan müzik sesi geldi, gözümü kırpmadım! Buraya böyle mi dinlenmeye geliyoruz?","ingilizce":"There was music from the next room until two in the morning, and I did not sleep at all! Is this how guests are supposed to rest here?","secenekler":[{"metin":"Özür dilerim efendim, çok üzüldüm. Hemen yan odaya haber veriyorum.","puan":1,"tepki":"Konuk biraz yumuşar ama “Dinlenmedim bile” der. Çözüme koşuldu, ancak konuğun duygusu duyulmadan; önce anlaşılmak ister, sonra çözüm."},{"metin":"Uykusuz bir gece çok yorucudur, kızgınlığınızı anlıyorum. Lütfen anlatın, sizi dinliyorum.","ingilizce":"A sleepless night is very tiring, and I understand why you are upset. Please tell me; I am listening.","puan":2,"tepki":"Konuk derin bir nefes alır ve anlatmaya başlar. Kendisini onun yerine koyan bir görevli, konuğun öfkesini düşürür; empati hak vermek değil, hissedileni görmektir."},{"metin":"Neden gece resepsiyona haber vermediniz? Hemen çözerdik, sorun çıkınca bize söylemeniz yeterdi.","puan":0,"tepki":"Konuk daha da kızar: “Aradım zaten!” Suçlamak, sorunu çözmek yerine kimin hatalı olduğuna odaklanmaktır; konuk savunmaya geçer."}]},{"konuk":"214’te kalıyorum. Gece iki kez resepsiyonu aradım ama kimse ilgilenmedi. Üçüncü aramada “tamam” dediler, müzik devam etti.","ingilizce":"I am staying in room 214. I rang reception twice during the night and nobody dealt with it. On the third call they said 'all right', but the music carried on.","secenekler":[{"metin":"Bizim ekip öyle bir şey yapmaz, galiba yanlış hatırlıyorsunuz, gece vardiyası çok dikkatlidir.","puan":0,"tepki":"Konuk sinirlenir: “Yalan mı söylüyorum?” Konuğun sözü bir çözüm aramadan yalanlandı; sorunun kimin hatası olduğuna değil, nasıl giderileceğine bakılmalıydı."},{"metin":"Özür dilerim, gece vardiyasına sorarım; hemen bir bakayım, bir aksaklık olmuş.","puan":1,"tepki":"Konuk özrü kabul eder, ama anlattıklarının doğru anlaşılıp anlaşılmadığını bilemez. Özür kısa ve doğru, fakat teyit edilmeden yapılan işlem hata payı taşır."},{"metin":"Yanlış anlamadıysam 214’te kalıyorsunuz, gece üç kez aradınız ve sonuncuda “tamam” denmesine rağmen müzik sürdü. Özür dilerim.","ingilizce":"If I have understood correctly, you are in room 214, you rang three times, and although you were told 'all right' on the last call, the music carried on. I apologise.","puan":2,"tepki":"Konuk “Evet, aynen öyle” der. Anlatılanlar teyit edildi, özür bahane aranmadan kısa ve açık yapıldı; konuk duyulduğunu anlar."}]},{"konuk":"Peki şimdi ne yapacaksınız? Bu gece de aynısı olursa...","ingilizce":"So what will you do now? If it happens again tonight...","secenekler":[{"metin":"Müzik konusunda elimizden geleni yapacağız, ilgileneceğiz, en kısa sürede gereğine bakarız.","puan":1,"tepki":"Konuk ikna olmaz: “Neyi, ne zaman yapacaksınız?” Cevap nazik, ama atılacak adım söylenmediği için çözüm belirsiz kaldı."},{"metin":"Komşu odadaki konuğa bugün nazikçe haber vereceğim. İsterseniz sizi sessiz bir odaya da alabiliriz.","ingilizce":"I will politely speak to the guest in the next room today. If you prefer, we can also move you to a quiet room.","puan":2,"tepki":"Konuk sakinleşir ve seçeneklerden birini düşünür. Suçlayan değil çözen bir yaklaşım izlendi; yapılacak işler açıkça söylendi ve seçim konuğa bırakıldı."},{"metin":"Her gece olacağı belli değil, şimdiden bir şey yapamam, bakarız bakalım.","puan":0,"tepki":"Konuk öfkelenir: “Yani umursamıyorsunuz.” Sorun küçümsendi ve çözüm sunulmadı; çözüm odaklı yaklaşım yapılabilecekleri söyler, yapılamayanları değil."}]},{"konuk":"Tamam, odayı değiştirmeye gerek yok, yalnız uyarın. Ama bir daha olursa nereye başvuracağım?","ingilizce":"All right, I do not need to move rooms, just warn them. But if it happens again, who should I contact?","secenekler":[{"metin":"Bir daha olmaz, boşuna endişelenmeyin; böyle şeyler pek olmaz.","puan":0,"tepki":"Konuk huzursuz kalır: “Ya olursa?” Söz verilemeyecek bir şey söylendi ve konuğun sorusu cevapsız bırakıldı."},{"metin":"Resepsiyonu arayabilirsiniz, hat gece de açık; geceki aksamanın nedenini bilmiyorum, ama bu kez haber verilmesini isteyeceğim.","puan":1,"tepki":"Konuk dudağını büker: “Onlar geçen gece de ilgilenmedi.” Dürüst bir cevap, ama aynı hattı göstermek ve kesin bir takip sözü vermemek geceki hayal kırıklığını gidermez."},{"metin":"Resepsiyonu arayın, adımı söyleyin; ben takip edeceğim. Tekrar özür dilerim.","ingilizce":"Call reception and give my name; I will follow it up. I apologise once more.","puan":2,"tepki":"Konuk güvenle başını sallar. Net bir başvuru yolu verildi ve takibi üstlenildi; özür kısa olur, ardından çözüm gelir."}]},{"konuk":"Peki. İlgilendiğiniz için sağ olun.","ingilizce":"Fine. Thank you for dealing with this.","secenekler":[{"metin":"Ne demek, bazı konuklar çok daha kötüsünü yapıyor, siz şanslısınız.","puan":0,"tepki":"Konuk şaşırır ve kırılır: “Beni diğerleriyle mi kıyaslıyor?” Konuğun derdi küçümsendi; bu söz yeni bir şikâyet konusu doğurabilir."},{"metin":"Biz teşekkür ederiz efendim. Yarın sabah arayıp bu gecenin nasıl geçtiğini soracağım.","ingilizce":"Thank you, sir. I will ring you tomorrow morning to ask how the night went.","puan":2,"tepki":"Konuk ilk kez gülümser: “Bu iyi oldu.” Bir süre sonra arayıp durumu sormak, küçük bir eksiğin şikâyete dönüşmeden giderilmesini sağlar ve konuğa düşünüldüğünü hissettirir."},{"metin":"Rica ederim efendim, iyi günler dilerim, bir şey olursa bize her zaman haber verebilirsiniz.","puan":1,"tepki":"Konuk nazik bir veda alır, ama arkasından bir güvence gelmez. Görüşme düzgün bitti; takip sözü verilseydi güven artardı."}]}]},{"id":"os-d05","unite":2,"baslik":"Başı İki Yana Sallayan Konuk","rol":"Concierge","sahne":"Saat 10.30, lobi. Bulgaristan’dan gelen bir konuk, Türkçe bilmediği için İngilizce soruyor; gün için bir gezi ayarlamak istiyor. Concierge hem sade konuşmalı hem de sözsüz işaretlere dikkat etmeli.","kavramlar":["os-2-011","os-2-038","os-2-020","os-2-033","os-2-031"],"adimlar":[{"konuk":"Günaydın! Bugün eski şehri görmek istiyorum. Bana yardımcı olabilir misiniz?","ingilizce":"Good morning! I would like to see the old town today. Can you help me?","secenekler":[{"metin":"Günaydın efendim, tabii ki. Eski şehir yakın; isterseniz yanınıza bir rehber ayarlayayım.","ingilizce":"Good morning, sir, of course. The old town is close by; shall I arrange a guide for you?","puan":2,"tepki":"Konuk gülümser: “Tam istediğim bu.” Kısa, açık ve anlaşılır sözcükler kullanıldığı için konuk, yabancı dilde bile ne yapacağını hemen kavradı."},{"metin":"Eski şehirde çarşı, kale, müze, plaj, dolmuş, otobüs, taksi, rehber ve tur seçenekleri var; hangisi?","puan":1,"tepki":"Konuk bocalar: “Hepsi mi?” Bilgi doğru, ama gereksiz ayrıntı konuğu yordu. Mesaj kısa ve karşıdakinin anlayacağı dilde verilmeliydi."},{"metin":"Konsiyerj olarak yalnız tur operasyonlarına bakıyorum; sizin için acente kodu ve bir form gerekir.","puan":0,"tepki":"Konuk kaşlarını çatar: “Anlamadım.” Meslek terimleri ekip içinde işi hızlandırır, konuğun karşısında ise duvar örer; konuk anlamadığı dilden uzaklaşır."}]},{"konuk":"(Başını iki yana sallayarak.) Evet, rehber çok iyi olur, teşekkürler.","ingilizce":"(Shaking his head from side to side.) Yes, a guide would be very nice, thank you.","secenekler":[{"metin":"Peki, istemiyorsunuz, o zaman size rehbersiz bir harita vereyim, kendiniz gezersiniz.","puan":0,"tepki":"Konuk şaşırır: “Hayır, rehber istiyorum!” Bazı toplumlarda başı iki yana sallamak “evet” demektir; sözü dinlemeyip tek bir harekete göre karar vermek yanlış anlaşılmaya yol açtı."},{"metin":"Tamam efendim, hemen bir rehber ayarlıyorum.","puan":1,"tepki":"Konuk “Evet, doğru” der. Söz doğru anlaşıldı, ama baş sallamanın farklı bir anlam taşıyabileceği fark edilip doğrulanmadığı için hata riski vardı."},{"metin":"Anladım. Emin olmak için soruyorum: rehber istiyorsunuz, doğru mu?","ingilizce":"I see. Just to be sure: you would like a guide, is that right?","puan":2,"tepki":"Konuk gülümseyip “Evet, evet” der. Hareketin anlamından emin olunmadığında sözle doğrulamak, kültür farkından doğan yanlış anlamayı önler."}]},{"konuk":"Tur ne kadar sürüyor ve kaçta başlıyor?","ingilizce":"How long does the tour take, and what time does it start?","secenekler":[{"metin":"Sanırım üç saat sürüyor, saat de galiba ikide gibi, ama emin değilim, bir bakmak lazım.","puan":0,"tepki":"Konuk güvensiz kalır: “Peki ben ne yapacağım?” Bilgi tahminle verildi; bilmediğini tahmin etmek yerine öğrenmek hem net hem dürüsttür."},{"metin":"Bir dakika efendim, süresini ve saatini şimdi öğrenip size net bilgi vereyim.","ingilizce":"One moment, sir. Let me find out the exact length and time for you right now.","puan":2,"tepki":"Konuk teşekkür eder ve bekler. Bilinmeyen tahmin edilmedi, öğrenilip net bilgi verileceği söylendi; konuk güvende hisseder."},{"metin":"Programa bakmam gerekiyor, birazdan söylerim; şimdilik bir şey diyemem.","puan":1,"tepki":"Konuk yarım cevap alır. Süre de saat de belirsiz kaldı; “birazdan” bir an değildir, iki sorunun cevabı net verilmeliydi."}]},{"konuk":"Kalenin bugün kapalı olduğunu duydum. Doğru mu?","ingilizce":"I heard the castle is closed today. Is that true?","secenekler":[{"metin":"Evet efendim, kale bugün kapalı. Ama müze ve çarşı açık; önce müzeyi gezebilirsiniz.","ingilizce":"Yes, sir, the castle is closed today. But the museum and the market are open; you could visit the museum first.","puan":2,"tepki":"Konuk memnun olur: “Güzel bir plan.” Olumsuz bilgi tek başına bırakılmadı, yanına seçenek konuldu; gerçek gizlenmedi ama kapı konuğun yüzüne kapatılmadı."},{"metin":"Evet, kapalı ama başka yerler var, onları gezebilirsiniz.","puan":1,"tepki":"Konuk “Hangi yerler?” diye sorar. Seçenek olduğu söylendi ama adı verilmedi; olumlu dil somut öneriyle birlikte gelmelidir."},{"metin":"Kale kapalı, bu yüzden bugün şehri gezmenin anlamı kalmadı; otelde dinlenseniz daha iyi olur.","puan":0,"tepki":"Konuk hayal kırıklığına uğrar. Yalnız yapılamayan söylendi; yapılabilecek bir şey önerilmediği için konuk bugünden vazgeçecek."}]},{"konuk":"Çok teşekkür ederim. Çok naziksiniz.","ingilizce":"Thank you very much. You have been very kind.","secenekler":[{"metin":"Tamam tamam, hadi hızlı olun, arkada bekleyenler var.","puan":0,"tepki":"Konuk kırılır ve sessizce uzaklaşır. Kaba ve aceleci üslup, o ana kadarki özeni silip götürür."},{"metin":"Rica ederim efendim. Hava çok güzel, iyi gezmeler!","ingilizce":"My pleasure, sir. The weather is lovely. Enjoy your trip!","puan":2,"tepki":"Konuk gülümseyerek ayrılır. Kısa ve nazik bir sohbetle, asıl işin dışına çıkan sıcak bir kapanış yapıldı; konuk gerçekten karşılandığını hisseder."},{"metin":"Rica ederim, görevimiz.","puan":1,"tepki":"Konuk nazik bir karşılık alır ama sıcak bir veda duymaz. Doğru ve yeterli bir cevap; küçük bir iyi dilek eklenseydi konuğun aklında olumlu kalırdı."}]}]},{"id":"os-d06","unite":2,"baslik":"Arızayı Amire Bildirmek","rol":"Kat görevlisi","sahne":"Saat 11.00, kat ofisi. Kat görevlisi odaları kontrol ederken 309 numaralı odanın banyo lambasının yanmadığını fark etti. Kat şefi Zeynep Hanım vardiya durumunu soruyor; konuklar öğleden sonra geliyor.","kavramlar":["os-2-007","os-2-010","os-2-016","os-2-032","os-2-027"],"adimlar":[{"konuk":"Günaydın. Bugünkü odalar nasıl, durumu özetler misin?","ingilizce":"Good morning. How are the rooms today? Can you give me a summary?","secenekler":[{"metin":"Günaydın efendim. Odaların çoğu hazır, ama birkaç yerde küçük sorunlar var, onları sonra anlatırım.","puan":1,"tepki":"Kat şefi “Hangi sorun, hangi oda?” diye sorar. Cevap yanlış değil, ama belirsiz; amirin tam olarak neyi çözeceğini bilmesi gerekir."},{"metin":"Günaydın efendim. 305 ve 307 hazır; 309’un banyo lambası yanmıyor, teknik servise bildirmek gerek.","ingilizce":"Good morning. Rooms 305 and 307 are ready; the bathroom light in 309 does not work and needs reporting to maintenance.","puan":2,"tepki":"Kat şefi hemen arıza kaydını açtırır. Hangi odanın hazır, hangisinin sorunlu olduğu sade ve net söylendiği için kimse tahmin yürütmek zorunda kalmadı."},{"metin":"Günaydın efendim. Her şey yolunda, hiçbir sorun yok, odalar tamam.","puan":0,"tepki":"Konuk gelince lamba yanmaz ve herkes zor durumda kalır. Bilinen bir arızayı söylememek, sorunu büyütür; açık ve doğru bilgi vermek görevlinin işidir."}]},{"konuk":"Teşekkürler. 309’u dün kim temizledi? Neden fark etmedi?","ingilizce":"Thanks. Who cleaned 309 yesterday? Why didn't they notice?","secenekler":[{"metin":"Ece fark etmedi efendim, o hep dikkatsiz davranıyor, daha önce de oldu.","puan":0,"tepki":"Kat şefi ciddileşir. Bir arkadaşı suçlayan genelleme iş arkadaşını da amirini de zor durumda bırakır; ekip içi gerginlik hemen yayılır."},{"metin":"Listeden bakıp size söylerim; ama önce arızayı kayda alıp teknik servise bildireyim, öğleye kadar da odaya bakarım.","ingilizce":"I'll check the list and tell you, madam; but first let me log the fault and report it to maintenance, and I'll check the room before noon.","puan":2,"tepki":"Kat şefi rahatlar: “Tamam, hemen ilerle.” Amirin sorusu cevapsız bırakılmadı; kimin hatası olduğu sonra söylenecek, önce sorunun nasıl giderileceğine odaklanıldı."},{"metin":"Ece’ydi sanırım ama dün akşam çok yoğundu, belki bu yüzden bakmamış olabilir efendim, her zaman dikkatli çalışır aslında.","puan":1,"tepki":"Kat şefi isim öğrenir ama çözüm yerine yeni bir tartışma konusu açılır. Yumuşak bir ifade bile olsa arkadaşı suçlamak çözüm değildir."}]},{"konuk":"Peki. Dün akşam vardiyada Ece vardı; aranız nasıl? Vardiya devrinin geciktiğini duydum.","ingilizce":"Right. Ece was on shift last night; how are things between you? I heard the handover was late.","secenekler":[{"metin":"Vardiya devri gecikince notları göremiyorum ve işimi planlayamıyorum. Ece ile saatini konuşmak istiyorum.","ingilizce":"When the handover is late I cannot see the notes and I cannot plan my work. I would like to talk to Ece about the timing.","puan":2,"tepki":"Kat şefi başını sallar: “Bu makul.” Karşıdaki suçlanmadı; kişinin kendi zorluğu ve ihtiyacı anlatıldığı için kişi değil sorun konuşuldu."},{"metin":"Ece hep geç kalıyor, onunla çalışmak çok zor.","puan":0,"tepki":"Kat şefi ciddileşir: “Bu kadar kesin konuşma.” “Hep” ve “çok zor” sözleri suçlar; karşıdakini savunmaya iter ve sorunun çözümünü zorlaştırır."},{"metin":"Biraz geç kalıyor ama bir şey demedim, belki siz konuşsanız daha iyi olur diye düşündüm, ne dersiniz? Ben pek karışmak istemedim.","puan":1,"tepki":"Kat şefi konuyu devralır, ama görevli kendi sorununu hiç anlatmadan geri çekilir. Saygılı bir dille doğrudan konuşmak, iki çalışan arasındaki gerginliğin büyümesini önlerdi."}]},{"konuk":"Tamam. Teknik servis gelene kadar arızayı not düş, sonra 311’e geç ve 12.30’da bana dön.","ingilizce":"Right. Note the fault until maintenance arrives, then move on to 311 and come back to me at 12.30.","secenekler":[{"metin":"Teknik servis halletsin, ben kendi odalarımla uğraşırım; başka iş vermeyin lütfen.","puan":0,"tepki":"Kat şefi sinirlenir. Verilen görev sorumluluk atılarak reddedildi; çözüm odaklı bir ekip böyle çalışmaz."},{"metin":"Anlaşıldı: arızayı kayda alıp 311’e geçiyorum, 12.30’da dönüyorum. Doğru mu?","ingilizce":"Understood: I will log the fault, move to 311 and report back at 12.30. Is that right?","puan":2,"tepki":"Kat şefi onaylar. Söylenenler kendi cümleleriyle tekrar edildi; bu teyit, saat ya da oda numarasının yanlış anlaşılmasını baştan önler."},{"metin":"Tamam efendim, anladım, hallederim.","puan":1,"tepki":"Kat şefi çıkarken “Emin misin?” diye düşünür. Kısa bir karşılık verildi, ama tekrar edilmediği için oda ya da saatin yanlış anlaşıldığı fark edilemez."}]},{"konuk":"Güzel iş çıkardın. Başka söylemek istediğin bir şey var mı?","ingilizce":"Good work. Is there anything else you would like to tell me?","secenekler":[{"metin":"Beni sürekli bu işlerle uğraştırmayın, yoğunum, yetişemiyorum, bir de bunlar çıkıyor.","puan":0,"tepki":"Kat şefi şaşırır ve ses tonunu sertleştirir. Yoğunluk bir gerekçe değildir; stres söze yansıtılınca olumlu geçen bir görüşme bile gergin biter."},{"metin":"Yok efendim, teşekkür ederim, şimdilik başka bir şey yok, işime devam edeyim.","puan":1,"tepki":"Kat şefi başını sallar. Cevap nazik ama kapalı; yeni bir arıza görüldüğünde haber verileceği de söylenseydi iletişim daha açık olurdu."},{"metin":"Teşekkür ederim efendim. Yeni bir arıza görürsem hemen size haber veririm.","ingilizce":"Thank you, madam. If I see another fault I will tell you straight away.","puan":2,"tepki":"Kat şefi gülümser: “Böyle devam.” Teşekkür edildi ve açık bir söz verildi; ekip içi iletişim güveni artırır."}]}],"karsi":"Kat şefi"},{"id":"os-d07","unite":3,"baslik":"Öğleden Sonra Check-in","rol":"Resepsiyonist","sahne":"Saat 15.00, resepsiyon. Hollandalı bir çift uzun bir yolculuktan sonra otele varmıştır; rezervasyonları vardır ama yorgun ve sabırsızdırlar. Kayıt, kimlik, belge ve kart işlemleri sırayla yapılacaktır.","kavramlar":["os-3-102","os-3-139","os-3-153","os-3-152","os-3-138"],"adimlar":[{"konuk":"İyi günler, soyadımız de Vries. Bu hafta için bir rezervasyonumuz var.","ingilizce":"Good afternoon, our surname is de Vries. We have a reservation for this week.","secenekler":[{"metin":"Hoş geldiniz efendim, rezervasyonunuzu hemen buluyorum. Pasaportlarınızı alabilir miyim?","ingilizce":"Welcome, sir. I'll find your reservation right away. May I have your passports, please?","puan":2,"tepki":"Konuk rahatlar, pasaportları uzatır. Güler yüzlü ve hızlı bir karşılama, konaklamanın geri kalanına iyi bir başlangıç yaptırır."},{"metin":"Hoş geldiniz. Önce rezervasyon numaranızı söyler misiniz, ona göre bakayım?","puan":1,"tepki":"Konuk telefonunda numarayı aramaya koyulur ve bir süre bekler. Uzun yoldan gelen konuk bekletilmek istemez; giriş hızlı olmalıdır."},{"metin":"Şu an çok yoğunum, görmüyor musunuz? Biraz bekleyin, sıra size gelince ben ilgilenirim; lütfen bankoyu çevrelemeyin.","puan":0,"tepki":"Konuk yüzünü ekşitir. Varış, konuk döngüsünün ilk izlenimidir; karşılamada ilgisizlik bütün konaklamanın tonunu bozar."}]},{"konuk":"Buyurun pasaportlarımız. Bunlar gerçekten gerekli mi?","ingilizce":"Here are our passports. Are they really necessary?","secenekler":[{"metin":"Zorunlu değil aslında; istemezseniz vermeyin, kaydınızı yine de yaparım.","puan":0,"tepki":"Konuk pasaportları geri çeker. Yanlış bilgi: kimlik bildirimi tercihe bağlı değil, yasal zorunluluktur."},{"metin":"Evet efendim, kimlik bildirimi yasal zorunluluk. Pasaportları okutup hemen geri veririm; kredi kartınızı da alabilir miyim?","ingilizce":"Yes, sir, identity notification is a legal requirement. I'll scan the passports and hand them straight back; may I also take your credit card?","puan":2,"tepki":"Konuk “Anladım” der ve kartını uzatır. Pasaport okuyucu bilgileri hızla aktarır, belge hemen konuğa geri verilir; kart ise ön provizyon içindir ve bir sonraki adımda açıklanır."},{"metin":"Evet, herkesten istiyoruz. Bilgilerinizi tek tek elle yazacağım.","puan":1,"tepki":"Konuk beklerken sıkılır. Neden gerektiği anlatılmadı; elle yazarken bir harf yanlış girilebilir, pasaport okuyucu bunun için vardır."}]},{"konuk":"Kayıt için bir şey imzalamam gerekiyor mu?","ingilizce":"Do I need to sign something for the registration?","secenekler":[{"metin":"Evet, şurayı imzalayın lütfen.","puan":1,"tepki":"Konuk okumadan imzalar ve neyi kabul ettiğini bilmez. Belgenin ne olduğu ve bilgilerin kontrolü konuğa söylenmelidir."},{"metin":"İmzayı şimdi atlayalım, siz odanıza çıkın dinlenin; belge işlerini yarın sabah toplu yaparız.","puan":0,"tepki":"Konuk şaşırır. Konaklama belgesi konuğun ıslak imzasını taşır ve yasal açıdan en kritik ön büro belgesidir; imzasız belge eksik yapılmış bir girişir."},{"metin":"Evet efendim, bu konaklama belgeniz. Bilgilerinizi kontrol edip şurayı imzalar mısınız?","ingilizce":"Yes, sir, this is your registration card. Could you check your details and sign here, please?","puan":2,"tepki":"Konuk bilgileri okuyup imzalar. İmza, konuğun otelin kurallarını ve verilerinin işlenmesini kabul ettiğini gösterir."}]},{"konuk":"Kredi kartımı da istediniz. Paramı şimdiden mi çekeceksiniz?","ingilizce":"You also asked for my credit card. Will you be taking the money now?","secenekler":[{"metin":"Hayır efendim, tutar yalnız ayrılıyor, çekilmiyor. Çıkışta gerçek hesabınıza göre işlem yapılır.","ingilizce":"No, sir, the amount is only reserved, not taken. At check-out it is settled against your actual bill.","puan":2,"tepki":"Konuk gülümser. Provizyon tahsilat değildir; önceden açıklanınca telefona gelen bildirim “Habersiz para çekildi” şikâyetine dönüşmez."},{"metin":"Evet, tutar kartınızdan hemen çekilecek; çıkışta gerçek hesabınız çıkarılıp fazlası size iade edilecek, endişe etmeyin.","puan":0,"tepki":"Konuk itiraz eder: “Hiç haberim yoktu.” Yanlış bilgi: ön provizyonda tutar karttan çekilmez, yalnızca güvence olarak ayrılır."},{"metin":"Ekstra harcamalara güvence olarak bir tutar ayırıyoruz.","puan":1,"tepki":"Konuk tam anlamaz: “Ayırmak ne demek?” Doğru söylendi ama “çekilmiyor” diye açıkça belirtilmedi; bildirim gelirse şaşırabilir."}]},{"konuk":"Her şey tamam mı? Hangi odadayız?","ingilizce":"Is everything done? Which room are we in?","secenekler":[{"metin":"Odanız 412, kartınız burada. Kolay gelsin.","puan":1,"tepki":"Konuk kartı alır ama bagajıyla ilgili yardım sunulmaz. “Kolay gelsin” çalışana söylenen bir sözdür, konuğa söylenmez; kısa ve soğuk bir kapanış güler yüzlü girişin tadını kaçırır."},{"metin":"Kartınızı alın, oda ikinci katta bir yerde olmalı; bakarsınız.","puan":0,"tepki":"Konuk ne yapacağını bilemez. Oda numarası ve yönlendirme belirsizdir; yorgun konuk lobide dolaşmak zorunda kalır."},{"metin":"Odanız 412, kapı kartınız burada; bellboyumuz bagajlarınıza eşlik edecek. İyi tatiller dileriz.","ingilizce":"Your room is 412, here is your key card, and our porter will take your luggage. Enjoy your stay.","puan":2,"tepki":"Konuk teşekkür eder. Kartın teslimi ve içten bir dilekle giriş tamamlanır; konuk iyi bir başlangıçla odasına çıkar."}]}]},{"id":"os-d08","unite":3,"baslik":"Çıkış ve Hesap","rol":"Ön büro kasiyeri","sahne":"Sabah 10.45, ön büro kasası. Türk bir iş kadını iki gecelik konaklamasından sonra çıkış yapmak istiyor; hesabında tanımadığı bir restoran satırı var ve faturayı şirketi adına istiyor.","kavramlar":["os-3-103","os-3-118","os-3-144","os-3-159","os-3-406"],"adimlar":[{"konuk":"Günaydın, 202 numaralı odadan çıkış yapmak istiyorum.","ingilizce":"Good morning, I would like to check out of room 202.","secenekler":[{"metin":"Hesap çıkış saatinden önce hazır olmaz, bu bizim kuralımız; lütfen öğleden sonra bir daha uğrayın, o zaman bakarız.","puan":0,"tepki":"Konuk şaşırır: “Uçağım var!” Uydurma bir kuralla konuk geri çevrildi; ayrılış, konuğun otelden aklında kalan son sahnedir."},{"metin":"Günaydın hanımefendi, hesabınızı ekranda açıyorum; birlikte bakalım.","ingilizce":"Good morning, madam. I'm opening your account on the screen, so let's look at it together.","puan":2,"tepki":"Konuk ekrana bakar, rahatlar. Hesap dökümünün konuğa gösterilmesi çıkış işleminin ilk adımıdır."},{"metin":"Günaydın. Hesabı hazırlıyorum, birkaç dakika sürer; şuraya oturabilirsiniz.","puan":1,"tepki":"Konuk bekler ama sıkılır. Nazik ama gereksiz bir bekleme; hesap hemen açılıp konuğa gösterilebilirdi."}]},{"konuk":"Hesapta bir restoran satırı var, bunu hatırlamıyorum. Kontrol eder misiniz?","ingilizce":"There is a restaurant charge on the bill that I don't remember. Could you check it, please?","secenekler":[{"metin":"Hesap sistemde yazıyor, doğrudur efendim.","puan":1,"tepki":"Konuk itirazının dinlenmediğini düşünür. Belge folyo havuzunda duruyor; ona bakılmadan geçiştirmek güveni azaltır."},{"metin":"Yemeği yiyen sizsiniz, hatırlamamanız benim sorunum değil; sistem yanlış yazmaz, lütfen ödemenizi yapın.","puan":0,"tepki":"Konuk öfkelenir. Kabalık ve suçlama; kasada güven ve mahremiyete saygı şarttır, tartışma çözümü değil sorunu büyütür."},{"metin":"Tabii hanımefendi, imzalı adisyonunuzu dosyadan çıkarıyorum; birlikte bakalım.","ingilizce":"Of course, madam. I'll pull your signed bill from the file and we can look at it together.","puan":2,"tepki":"Konuk imzasını görünce hatırlar: “Haklısınız, arkadaşlarımla yemiştik.” Konuğun harcamasını kanıtlayan imzalı belge folyo havuzunda saklanır."}]},{"konuk":"Evet, doğruymuş. Şimdi faturayı şirketim adına istiyorum.","ingilizce":"Yes, it's correct. Now I'd like the invoice in my company's name.","secenekler":[{"metin":"Faturayı şimdilik kendi adınıza keseyim, şirket adına sonra düzeltiriz.","puan":0,"tepki":"Konuk itiraz eder: “Şirkete lazım, sonra uğraşamam.” Fatura mali ve yasal değeri olan bir belgedir; yanlış adla kesilen belge sonradan düzeltme zahmeti çıkarır, baştan doğru düzenlenmelidir."},{"metin":"Tabii hanımefendi. Vergi numaranızı söyler misiniz, faturayı hemen ona göre hazırlayayım?","puan":1,"tepki":"Konuk numarasını söyler, ama fatura için vergi dairesi de gerekir; eksik sorulduğu için bilgi yarım kalır ve konuk yeniden beklemek zorunda kalır."},{"metin":"Tabii. Şirketinizin vergi dairesini ve vergi numarasını alabilir miyim?","ingilizce":"Certainly. May I have your company's tax office and tax number, please?","puan":2,"tepki":"Konuk bilgileri yazdırır. Şirket adına fatura için vergi dairesi ve vergi numarası gerekir; bilgiler alınınca hatasız fatura düzenlenir."}]},{"konuk":"Faturada KDV ve bir de konaklama vergisi görüyorum. Bunlar ne?","ingilizce":"I can see VAT and an accommodation tax on the invoice. What are they?","secenekler":[{"metin":"Oda ve yiyecek içecek bedellerine KDV eklenir; konaklama vergisi ise konaklamaya ayrıca uygulanan vergi kalemidir.","ingilizce":"VAT is added to the room and food and drink charges, and the accommodation tax is a separate tax item on the stay.","puan":2,"tepki":"Konuk başını sallar: “Şimdi anladım.” Vergi kalemlerini açıklayabilen görevli çıkışta tartışmayı baştan önler."},{"metin":"Bunlar devlete giden vergiler efendim, bizimle ilgisi yok.","puan":1,"tepki":"Konuk kısmen ikna olur ama kalemleri hâlâ bilmez. Kısa bir geçiştirme; faturadaki kalemlerin açıklanması güveni artırır."},{"metin":"Bunlar otelin kendi hizmet bedelidir efendim, ödemeniz gerekiyor; ayrıca açıklanacak bir şey yok.","puan":0,"tepki":"Konuk huzursuzlanır. Yanlış bilgi: KDV ve konaklama vergisi otelin hizmet bedeli değil, vergi kalemleridir."}]},{"konuk":"Tamam, kartla ödeyeceğim. Her şey için teşekkürler.","ingilizce":"Fine, I'll pay by card. Thank you for everything.","secenekler":[{"metin":"Ödemeniz alındı. Faturanız gerekirse sonra istersiniz, arkada kuyruk var.","puan":0,"tepki":"Konuk bozulur. Fatura çıkışta verilir; kuyruğu bahane edip konuğu uğurlamadan geçiştirmek son sahneyi bozar."},{"metin":"Ödemeniz alındı, faturanız burada. Kapı kartınızı da alayım; yine bekleriz, güvenli yolculuklar dileriz.","ingilizce":"Your payment has been received and here is your invoice. I'll take your key card, too; we look forward to seeing you again. Safe travels.","puan":2,"tepki":"Konuk gülümseyerek ayrılır. Ödeme, fatura ve kartın geri alınmasıyla çıkış tamamlanır; konuk sıcak bir uğurlamayla yola çıkar."},{"metin":"Ödeme tamam. İyi günler.","puan":1,"tepki":"Konuk faturasını bekler ve bir an duraksar. Çıkış, faturanın verilmesi, kapı kartının geri alınması ve içten bir uğurlamayla tamamlanır."}]}]},{"id":"os-d09","unite":3,"baslik":"Ayrı Yatak İsteği","rol":"Konuk ilişkileri görevlisi","sahne":"Saat 16.30, lobi. Bir fuar için gelen iki iş arkadaşı, kendilerine büyük yataklı bir double oda verildiğini fark etmiştir. Konuk ilişkileri görevlisi, memnuniyetsiz konukları dinleyip çözüm üretmekle yükümlüdür.","kavramlar":["os-3-132","os-3-172","os-3-248","os-3-163","os-3-160"],"adimlar":[{"konuk":"Biz iş arkadaşıyız, odamızda tek büyük yatak var. Ayrı yatak istemiştik.","ingilizce":"We are colleagues, and our room has only one large bed. We asked for separate beds.","secenekler":[{"metin":"Double ile twin aynı şeydir efendim; iki kişi de aynı büyük yatakta rahatça uyur, birkaç gün idare edersiniz.","puan":0,"tepki":"Konuk öfkelenir. Yanlış bilgi: ikisi de iki kişiliktir ama fark yatak düzenindedir; arkadaşlar çoğu zaman ayrı yatak ister."},{"metin":"Rezervasyon kaydınıza bakıyorum, yatak düzeni görünmüyor. Bir oda arayayım.","puan":1,"tepki":"Konuk biraz yumuşar ama tam rahatlamaz. Kayda bakıldı ve çözüm aranıyor, ama rahatsızlık için özür dilenmedi; önce özür dilenip konuğun duygusu görülmeliydi."},{"metin":"Rahatsızlık için özür dilerim, sizi anlıyorum. İki ayrı yataklı, yani twin bir oda arayacağım.","ingilizce":"I'm sorry for the inconvenience, I understand. I'll look for a twin room with two separate beds.","puan":2,"tepki":"Konuk sakinleşir. Şikâyetin empatiyle dinlenmesi konuğu otele bağlı tutar; ayrı yataklı oda twin odadır."}]},{"konuk":"Peki, ayrı yataklı başka oda var mı?","ingilizce":"So, is there another room with separate beds?","secenekler":[{"metin":"Twin odaların durumuna akşam vardiyası devralınca bakarım; o zamana kadar bu odada kalın.","puan":0,"tepki":"Konuk sinirlenir: “Akşama kadar mı?” Çözüm akşama atıldı; hata otelden geldiği için konuğun bekletilmeden uygun odaya yerleşmesi gerekir."},{"metin":"Ekranda boş görünen bir twin oda var. Kat hizmetlerine sorayım; hazırsa anahtarını veririm, değilse biraz beklersiniz.","puan":1,"tepki":"Konuk bekler. Doğru bölüme soruluyor, ama oda durumu için net bir süre ve haber sözü verilmedi; konuk lobide kalabilir."},{"metin":"Boş ve temiz görünen bir twin oda arıyorum; kat hizmetleriyle de teyit edip size hemen haber vereceğim.","ingilizce":"I'm looking for a vacant clean twin room. I'll confirm with housekeeping and let you know straight away.","puan":2,"tepki":"Konuk teşekkür eder; kısa sürede oda hazırdır. Ön büro odayı satar, kat hizmetleri hazırlar; iki bölüm haberleşirse konuk lobide beklemez."}]},{"konuk":"Oda hazırmış, sağ olun. Ama bavullarımızı yeniden taşımak zorunda kalıyoruz, yorucu.","ingilizce":"The room is ready, thank you. But we have to move our luggage again, which is tiring.","secenekler":[{"metin":"Oda değişikliği sizin tercihiniz, taşıma da size ait.","puan":0,"tepki":"Konuk öfkesini bastıramaz. Hata otelden kaynaklanıyor; sorumluluğu konuğa atmak güveni bozar."},{"metin":"Haklısınız, bagajınızı bir görevlimiz yeni odanıza taşıyacak; yeni kartlarınız da hazır.","ingilizce":"You're right. One of our staff will carry your luggage to the new room, and your new key cards are ready.","puan":2,"tepki":"Konuk rahatlar. Yaşadığı zahmet otel tarafından üstlenilince şikâyet tatmin olur."},{"metin":"Haklısınız, bir görevli ayarlıyorum; biraz beklemeniz gerekecek.","puan":1,"tepki":"Konuk bekler. Zahmetin otele ait olduğu kabul edildi ve görevli ayarlandı, ama ne kadar bekleneceği ve yeni kartların hazır olup olmadığı söylenmedi."}]},{"konuk":"Bir dahaki sefere de ayrı yataklı oda olursa çok iyi olur.","ingilizce":"It would be great if we could have separate beds next time as well.","secenekler":[{"metin":"Tercihinizi kayıtlarınıza yazıyorum; bir dahaki gelişinizde ayrı yataklı oda ayırmaya özen göstereceğiz.","ingilizce":"I'm noting your preference in your records, so next time we'll do our best to reserve a room with separate beds.","puan":2,"tepki":"Konuk memnun olur. Tercihiyle hatırlandığını hisseden konuk sadakat gösterir; kayıt yalnız daha iyi hizmet için kullanılır."},{"metin":"Rezervasyon yaptırırken yine belirtirseniz iyi olur.","puan":1,"tepki":"Konuk hayal kırıklığına uğrar. Aynı yük tekrar konuğa bırakıldı; tercih kayıtlı olsaydı konuk sormadan hatırlanırdı."},{"metin":"Tercihinizi kayda yazarım; yatak düzeninizi fuar organizatörüne de ileteceğim, onlar da sizi hatırlasın.","puan":0,"tepki":"Konuk itiraz eder. Konuğun bilgisi özeldir ve korunması yasal sorumluluktur; izinsiz üçüncü kişiyle paylaşılmaz."}]},{"konuk":"Her şey için teşekkürler, iyi akşamlar.","ingilizce":"Thank you for everything, good evening.","secenekler":[{"metin":"Biz teşekkür ederiz; bir ihtiyacınız olursa bana ya da resepsiyona her an ulaşabilirsiniz. Konaklamanız güzel geçsin.","ingilizce":"Thank you. If you need anything, you can reach me or reception at any time. I hope you enjoy your stay.","puan":2,"tepki":"Konuk gülümseyerek ayrılır. Ulaşılabilir olduğunu söylemek, konuk ilişkilerinin özüdür: memnuniyeti artırmak ve hizmeti kişiye özel kılmak."},{"metin":"İyi akşamlar, iyi dinlenmeler.","puan":1,"tepki":"Konuk nazikçe ayrılır. Nazik ama sıradan bir veda; yeni bir isteği olursa kime ulaşacağını bilmiyor."},{"metin":"Başka isteğiniz olursa bana değil resepsiyona söyleyin; ben yalnız şikâyetlerle ilgileniyorum.","puan":0,"tepki":"Konuk geri çekilir. Konuk ilişkileri yalnız şikâyetleri değil, memnuniyeti artırmayı da üstlenir; konuk geri çevrilmemelidir."}]}]},{"id":"os-d10","unite":3,"baslik":"Erken Gelen Aile, Emanet Valizler","rol":"Bellboy","sahne":"Saat 10.15, otel girişi. Almanya’dan gelen dört kişilik bir aile odalarının ancak öğleden sonra hazır olacağını öğrenmiştir. Üç büyük valizleri ve yorgun iki çocukları vardır; bellboy valizleri emanet alıp sonra odaya eşlik edecektir.","kavramlar":["os-3-133","os-3-186","os-3-148","os-3-140","os-3-117"],"adimlar":[{"konuk":"Günaydın. Odamız öğleden sonra hazır olacakmış. Valizlerimizi bir yere bırakabilir miyiz?","ingilizce":"Good morning. Our room won't be ready until this afternoon. Can we leave our luggage somewhere?","secenekler":[{"metin":"Valizleri lobinin köşesine bırakın, kimse almaz; etiket, fiş gibi şeylerle uğraşmayalım.","puan":0,"tepki":"Konuk tereddüt eder. Konuğun eşyası emanettir; gözetimsiz ve etiketsiz bırakılan valiz karışabilir ya da kaybolabilir."},{"metin":"Olur, şuraya bırakın, dönünce alırsınız.","puan":1,"tepki":"Konuk valizleri bırakır ama içi rahat etmez. Kime ait olduğu belirtilmedi; etiketsiz emanet karışabilir."},{"metin":"Elbette hanımefendi, bagaj odamızda güvenle saklarız. Her valize etiket takıyorum.","ingilizce":"Of course, madam. We'll keep your luggage safely in our luggage room. I'm tagging each suitcase.","puan":2,"tepki":"Konuk rahatlar. Bagaj odasındaki emanette kimin eşyası olduğu etiketle belli olur; konuk şehri rahatça gezebilir."}]},{"konuk":"Üç büyük valizimiz var. Bunları nasıl taşıyacaksınız?","ingilizce":"We have three big suitcases. How will you carry them?","secenekler":[{"metin":"Bagaj arabasını getiriyorum, valizleri üst üste yığıp götürürüm.","puan":1,"tepki":"Konuk onaylar ama içi rahat etmez. Bagaj arabası doğru araçtır, ama valizler düzgün dizilmedi; üst üste yığılan valiz devrilebilir."},{"metin":"Bagaj arabasına düzgünce dizerim; valizleriniz yerde sürünmez, siz de yorulmazsınız.","ingilizce":"I'll load them neatly onto the luggage trolley, so they won't be dragged along the floor and you won't have to carry them.","puan":2,"tepki":"Konuk gülümser. Bagaj arabası hem konuğun eşyasını hem personelin belini korur; lobiden geçtiği için düzenli olması otelin özenini gösterir."},{"metin":"Arabayı kullanmıyoruz; valizleri üst üste istifleyip kollarımla taşıyacağım, siz çocuklara bakın.","puan":0,"tepki":"Konuk irkilir. Valizler üst üste gelişigüzel atılmaz; bagaj arabası tam bu iş için vardır."}]},{"konuk":"Odamız şimdi hazır. Valizlerimizi alabilir miyiz?","ingilizce":"Our room is ready now. May we have our luggage back?","secenekler":[{"metin":"Buyurun, etiketlerine bakıp hangileri sizinse alın.","puan":1,"tepki":"Konuk valizleri kendisi seçer. Kontrol konuğa bırakıldı; teslimde eşyanın kime ait olduğunu doğrulamak görevlinin işidir."},{"metin":"Elbette hanımefendi. Etiketleri ve adınızı kontrol ettikten sonra valizlerinizi teslim ediyorum.","ingilizce":"Of course, madam. Once I've checked the tags and your name, I'll hand your luggage over.","puan":2,"tepki":"Konuk teşekkür eder. Teslimde konuğun kendisi olduğundan emin olunur; tek bir valizin karışması bütün karşılamayı gölgeler."},{"metin":"Sizi tanıyorum, etiketlere bakmadan valizleri yükleyip yukarı çıkalım, vakit kaybetmeyelim, kimse valiz karıştırmaz.","puan":0,"tepki":"Konuk şaşırır. Kontrolsüz teslim valiz karışmasına yol açar; eşya emanettir, kime verildiği doğrulanmalıdır."}]},{"konuk":"Oda kaçıncı katta? Bu kartı nasıl kullanacağız?","ingilizce":"Which floor is our room on? And how do we use this key card?","secenekler":[{"metin":"Kart bütün odaları açar; kaybederseniz önemli değil.","puan":0,"tepki":"Konuk şaşkın kalır. Yanlış bilgi: kapı kartı yalnız konuğun odasını, konaklama süresi boyunca açar; kaybolursa yenisi programlanır."},{"metin":"512, beşinci kat. Kartı kapıya tutun, açılır.","puan":1,"tepki":"Konuk kapıyı açar ama acil çıkışı bilmez. Kısa bir bilgi; bellboyun işi odayı ve imkânları tanıtmaktır."},{"metin":"Beşinci kat, 512 numaralı oda. Kart yalnız bu odanın kapısını açar; birlikte deneyelim, acil çıkışın yerini de göstereyim.","ingilizce":"Fifth floor, room 512. The card opens only your door; let's try it together, and I'll show you where the emergency exit is.","puan":2,"tepki":"Konuk güvenle kartı dener. Bellboy, odaya eşlik edip kartı ve acil çıkışın yerini tanıtarak karşılamayı tamamlar."}]},{"konuk":"Klima nasıl çalışıyor? Çocuklar sıcaktan bunalmış.","ingilizce":"How does the air conditioning work? The children are feeling the heat.","secenekler":[{"metin":"Klimayı bozmayın, her şey ayarlı; sıcak gelirse pencereyi açın.","puan":0,"tepki":"Konuk hayal kırıklığına uğrar. Konuk rahatsızlığı çözülmeden bırakıldı; klimanın nasıl çalıştığını göstermek bell desk görevidir."},{"metin":"Kumanda komodinin üstünde, kılavuzu da yanında; isterseniz kendiniz bakarsınız, yardıma gerek olmaz.","puan":1,"tepki":"Konuk kumandayı bulur ama kendi başına uğraşır. Gösterilmeden bırakılan donanım konukta sıkıntı yaratabilir."},{"metin":"Göstereyim hanımefendi, kumandayı birlikte ayarlayalım. Çalışmazsa resepsiyona bildiririm.","ingilizce":"Let me show you how to use the remote control, madam. If it doesn't work, I'll tell reception.","puan":2,"tepki":"Oda serinler, çocuklar rahatlar. Bell desk, konuğu odasına yerleştirip donanımı tanıtır; aile iyi bir ilk izlenimle dinlenmeye başlar."}]}]},{"id":"os-d11","unite":3,"baslik":"Kapıdaki Kart","rol":"Kat görevlisi","sahne":"Saat 11.00, dördüncü kat. Oda görevlisi listesindeki odaya gelir; kapıda henüz kart yoktur. Üç kez vurup seslenir; içeriden bir ses gelir. Aynı katta başka bir konuk da yardım isteyecektir.","kavramlar":["os-3-273","os-3-271","os-3-272","os-3-274","os-3-215"],"adimlar":[{"konuk":"Bir saniye! Kim o?","ingilizce":"Just a second! Who is it?","secenekler":[{"metin":"Kat hizmetleri. Açar mısınız lütfen?","puan":1,"tepki":"Konuk telaşla kapıya yürür. Kim olduğu söylendi ama konuğa seçenek tanınmadı; uykudan kalkan biri aceleye gelir."},{"metin":"Kat hizmetleri efendim. Odanızı şimdi mi temizleyeyim, yoksa daha sonra mı gelmemi istersiniz?","ingilizce":"Housekeeping, sir. Would you like me to clean your room now, or shall I come back later?","puan":2,"tepki":"Konuk rahatlar. Odaya girmeden önce üç kez vurup seslenmek konuğun özel alanına saygıdır; seçeneği konuğa bırakmak da nezakettir."},{"metin":"Girmem lazım, listem çok uzun; anahtarla açıyorum, siz yatmaya devam edebilirsiniz, ben çabuk çıkarım.","puan":0,"tepki":"Konuk panikler. Konuk cevap verdiği anda içeri girmek izinsiz girmektir; pas anahtarı bunun için kullanılmaz."}]},{"konuk":"Pardon, geç uyandım. Yarım saat sonra gelebilir misiniz?","ingilizce":"Sorry, I overslept. Could you come back in half an hour?","secenekler":[{"metin":"Peki efendim, öğleden sonra bakarız.","puan":1,"tepki":"Konuk emin olamaz. Zaman belirsiz bırakıldı; konuk ne zaman rahatsız edileceğini bilmek ister."},{"metin":"Yarım saat çok geç, işlerim var. Şimdi girip yatağı yapayım, siz de şuraya oturup bekleyin.","puan":0,"tepki":"Konuk gerilir. Oda konuğun özel alanıdır; konuğun isteği dinlenmeden içeri girilmez."},{"metin":"Tabii efendim, yarım saat sonra uğrarım. Rahatsız ettiğim için özür dilerim.","ingilizce":"Of course, sir. I'll come back in half an hour. I'm sorry to have disturbed you.","puan":2,"tepki":"Konuk gülümseyerek teşekkür eder. İstenen saat kabul edildi; net bir söz konuğa saygıyı ve güveni gösterir."}]},{"konuk":"Aslında bugün hiç temizlik istemiyorum. Bunu size nasıl bildiririm?","ingilizce":"Actually, I don't want any cleaning today. How do I let you know?","secenekler":[{"metin":"Kart asmanız fark etmez, ben yine de kapıyı çalıp bakarım; her odayı kontrol etmem gerekiyor.","puan":0,"tepki":"Konuk bozulur. “Lütfen rahatsız etmeyin” kartı mutlak giriş yasağı demektir; kart varken kapı çalınmaz."},{"metin":"Kapı koluna “Lütfen rahatsız etmeyin” kartını asın; kartı görünce kapıyı çalmam, kat şefime haber veririm.","ingilizce":"Just hang the 'Do Not Disturb' card on your door handle, sir; when I see it I won't knock, and I'll tell my supervisor.","puan":2,"tepki":"Konuk kartı asar ve gönül rahatlığıyla dinlenir. Kartı gören görevli kapıyı çalmaz, listesinde işaretler ve kat şefine bildirir."},{"metin":"Resepsiyonu arayıp söyleyin, ben de bakarım.","puan":1,"tepki":"Konuk telefona uzanır. Çözüm var ama dolambaçlı; kapıya asılan kart bunun için en açık yoldur."}]},{"konuk":"Peki, temizlik istersem ne yapmalıyım?","ingilizce":"And what should I do if I want my room cleaned?","secenekler":[{"metin":"Kapıya “Lütfen odamı temizleyin” kartını asarsınız efendim; kartı gördüğümde odanızı listemde öne alırım.","ingilizce":"You hang the 'Please Make Up My Room' card on your door, sir; when I see it, I'll move your room to the front of my list.","puan":2,"tepki":"Konuk rahat bir nefes alır. İstek açıkça belirtilmiştir; konuk hizmet istediğinde bekletilmez."},{"metin":"Bana ya da resepsiyona söylemeniz yeterli, sizi buluruz.","puan":1,"tepki":"Konuk tamam der ama emin değildir. Kart varken bunu sözlü bildirmek belirsizdir; kartlar istek bildirmenin en açık yoludur."},{"metin":"Kartla uğraşmayın, odanızı ben bildiğim saatte temizlerim; sıra bende.","puan":0,"tepki":"Konuk şaşırır. Konuk açıkça hizmet istediğinde sıra değiştirilir; görevli kendi planını konuğun isteğinin önüne koymaz."}]},{"konuk":"(Koridorda yaklaşan başka bir konuk.) Pardon, 410 benim odam, anahtarımı içeride unuttum. Kapıyı açar mısınız?","ingilizce":"(Another guest approaches along the corridor.) Excuse me, room 410 is mine and I've left my key inside. Could you open the door for me?","secenekler":[{"metin":"Üzgünüm hanımefendi, pas anahtarını başkası için kullanamam; resepsiyona gidin, kimliğinizi doğrulayıp kartınızı yenilerler.","ingilizce":"I'm sorry, madam, I can't use my master key for anyone else. Please go to reception, where they will confirm who you are and issue a new key.","puan":2,"tepki":"Konuk anlayışla resepsiyona gider. Kimin hangi odada kaldığını doğrulamak ön büronun işidir; pas anahtarı başkasına verilmez ya da kullandırılmaz."},{"metin":"Kuralı tam bilmiyorum, kat şefimi çağırayım, o karar versin; bu arada burada bekleyin lütfen.","puan":1,"tepki":"Konuk bekler. Kural bellidir: “Odamı açar mısınız?” diyene kapı açılmaz, kibarca resepsiyona yönlendirilir."},{"metin":"410 mu, tamam; anahtar bende nasılsa, hemen açıyorum; bu kadar basit bir iş için resepsiyona gitmeyin.","puan":0,"tepki":"Konuk tedirgin olur. Pas anahtarı konukların eşyasına açılan kapıdır; kimlik doğrulanmadan hiçbir kapı açılmaz."}]}]},{"id":"os-d12","unite":3,"baslik":"Unutulan Kol Saati","rol":"Kat ofisi görevlisi","sahne":"Öğleden sonra, kat hizmetleri ofisi. Geçen hafta ayrılan Japon bir konuk telefon eder; kol saatini odada unuttuğunu düşünmektedir. Kat ofisi görevlisi kayıp ve bulunmuş eşya kayıtlarını izlemekle yükümlüdür.","kavramlar":["os-3-256","os-3-258","os-3-215","os-3-267"],"adimlar":[{"konuk":"Merhaba, geçen hafta 304 numaralı odada kaldım. Kol saatimi unuttum sanırım.","ingilizce":"Hello, I stayed in room 304 last week. I think I left my watch behind.","secenekler":[{"metin":"Şu an çok yoğunum, bir saat sonra ya da yarın sabah tekrar arar mısınız? O zaman bakarız.","puan":1,"tepki":"Konuk endişeyle kabul eder. Kayıt defteri elinin altındayken konuğu bekletmek gereksizdir."},{"metin":"Geçmiş olsun, hemen kayıt defterine bakıyorum. Adınızı ve konaklama tarihlerinizi alabilir miyim?","ingilizce":"I'm sorry to hear that. I'll check our lost and found log right away. May I have your name and the dates of your stay?","puan":2,"tepki":"Konuk adını ve tarihleri söyler. Bulunan her eşya deftere kayıt numarasıyla yazılır; defterden bakarak yanıt verilir."},{"metin":"Kol saatleri çoğu zaman bulunmuyor; bakmamız anlamsız.","puan":0,"tepki":"Konuk umudunu yitirir. Kayda bakmadan sonuca varmak yanlış: bulunan eşyanın tamamı defterde izlenir."}]},{"konuk":"Siyah deri kayışlı, kadranı mavi bir saat. Bulunmuş mu?","ingilizce":"It's a watch with a black leather strap and a blue dial. Has it been found?","secenekler":[{"metin":"Kayıtta üç saat var; hepsini masaya sıralayalım, hangisi sizinse gelip alırsınız, kimse sormaz.","puan":0,"tepki":"Konuk şaşırır. Başkalarının eşyası ortaya serilmez; eşya konuğun tarifi kayıtla eşleşince teslim edilir."},{"metin":"Bir kol saati kayıtta var, sizinki olabilir; gelip bakarsınız, eğer sizinki değilse başka bir yerde aramak gerekir.","puan":1,"tepki":"Konuk sevinir ama emin olamaz. Tarif kayıtla karşılaştırılmadı; eşya sahibine ancak tarif ve kayıt örtüşünce verilir."},{"metin":"Evet efendim, 304’te bulunan bir kol saati kayıtlı ve güvenle saklanıyor; tarifiniz kayıtla uyuşuyor.","ingilizce":"Yes, sir, a watch found in room 304 is in our log and is being kept in a safe place. Your description matches the record.","puan":2,"tepki":"Konuk derin bir nefes alır. Eşyanın cinsi, rengi, bulunduğu yer ve saklandığı yer forma yazılır; tarif kayıtla eşleşince eşya konuğa aittir."}]},{"konuk":"Harika! Yarın öğleden sonra gelip alabilir miyim?","ingilizce":"Wonderful! Could I come and collect it tomorrow afternoon?","secenekler":[{"metin":"Saati kapıdaki görevliye bırakırım, o size verir; yarın bize uğramak zorunda kalmazsınız.","puan":0,"tepki":"Konuk razı olur ama kayıt tutulmaz. Teslim bilgileri deftere yazılmadan eşya el değiştirmez; kimin kime teslim ettiği belli olmalıdır."},{"metin":"Tabii efendim, yarın öğleden sonra bekleriz; saatiniz hazır olur.","puan":1,"tepki":"Konuk teşekkür eder. Randevu verildi ama teslimde tarifin kayıtla eşleştirileceği ve konuğun kendisi olduğunun doğrulanacağı söylenmedi; hazırlıksız gelebilir."},{"metin":"Elbette efendim. Teslimde tarifi kayıtla eşleştirip kimliğinizi kayıttaki oda ve adla doğrulayacağım; teslimi deftere yazarız.","ingilizce":"Of course, sir. At handover I'll match your description with the log and verify your identity against the room and name on record; then we'll log the handover.","puan":2,"tepki":"Konuk “Anlaşıldı” der. Teslimde tarif kayıtla eşleştirilir, konuğun kendisi olduğu kayıttaki oda ve adla doğrulanır; kayıt numarası ve kimin teslim aldığı deftere işlenir."}]},{"konuk":"Kayıtta bir cüzdan da var mı? Varsa içinde kimlik kartım olmalı, açıp adıma bakar mısınız?","ingilizce":"Is there a wallet in the log too? If so, my ID card should be inside, so could you open it and check my name?","secenekler":[{"metin":"Cüzdanlar kayıtlıysa kontrol ederim, içini açmayız; rengini ve bulunduğu yeri tarif ederseniz kayıtla eşleştiririm.","ingilizce":"I'll check the log for wallets, but we don't open them; if you describe its colour and where you lost it, I'll match it with our records.","puan":2,"tepki":"Konuk durumu anlar. Bulunan eşyanın içi karıştırılmaz; cüzdanın içine bakılmaz, konuğun tarifi kayıtla eşleştirilir."},{"metin":"Tabii, bulursak cüzdanın içini açıp kimlik kartındaki adınıza bakar, size hemen haber veririm.","puan":0,"tepki":"Konuk rahatlar gibi olur ama yanlış: cüzdanın içi kurcalanmaz; bulunan eşyanın içine bakmak mahremiyeti ihlal eder."},{"metin":"Kayıtta cüzdan yok; bir hafta sonra bir daha arayın, bakarız.","puan":1,"tepki":"Konuk kısmen rahatlar. Hızlı bir cevap; ama eşya henüz kayda geçmemiş olabilir ve konuğa nereye bakıldığı da anlatılmadı."}]},{"konuk":"Çok teşekkür ederim, bu hizmeti unutmayacağım.","ingilizce":"Thank you so much, I won't forget this service.","secenekler":[{"metin":"Rica ederiz efendim; saatiniz yarın öğleden sonra teslime hazır olacak. İyi günler dileriz.","ingilizce":"You're welcome, sir. Your watch will be ready for collection tomorrow afternoon. Have a good day.","puan":2,"tepki":"Konuk içten teşekkür eder. Eşya güvenle kayıtlıdır, konuğa net bir söz verilmiştir; iyi bir kayıt sistemi güveni yeniden kazandırır."},{"metin":"Rica ederim, görüşürüz.","puan":1,"tepki":"Konuk kısaca teşekkür eder. Nazik ama kısa; saatin yarın hazır olacağı ve teslim şekli bir kez daha hatırlatılmadı."},{"metin":"Bir dahaki sefere eşyalarınızı odada unutmayın, her seferinde bulunamıyor; bu işler hep böyle oluyor.","puan":0,"tepki":"Konuk bozulur. Konuğa ders vermek yerine yardım etmek görevdir; sitem soğuk bir iz bırakır."}]}]},{"id":"os-d13","unite":3,"baslik":"Alerjisi Olan Küçük Konuk","rol":"Garson","sahne":"Akşam 20.00, otelin balık restoranı (alakart). Bir anne ve kızı yemeğe oturmuştur; kızın yer fıstığı alerjisi vardır. Garson, siparişi alırken hem satışı hem konuğun sağlığını gözetmelidir.","kavramlar":["os-3-026","os-3-410","os-3-033","os-3-165","os-3-144"],"adimlar":[{"konuk":"İyi akşamlar. Menüde ne önerirsiniz? Kızımın yer fıstığı alerjisi var.","ingilizce":"Good evening. What would you recommend from the menu? My daughter has a peanut allergy.","secenekler":[{"metin":"Geçmiş olsun, alerjiyi not aldım. Menü burada; seçtiğinizde mutfağa sorarım.","puan":1,"tepki":"Anne menüye bakar. Mutfağa sormak doğru, ama geç: alerji öğrenilir öğrenilmez mutfağa sorulup güvenli seçenekler konuğa önceden söylenir, böylece konuk boşa seçim yapmaz."},{"metin":"İyi akşamlar, hoş geldiniz. Alerjiyi not alıyorum; önerimden önce mutfağa sorup size kesin bilgi vereceğim.","ingilizce":"Good evening, welcome. I've noted the allergy; before I recommend anything I'll check with the kitchen and give you a definite answer.","puan":2,"tepki":"Anne “Teşekkür ederim” der. Yemekler reçeteye göre hazırlanır; alerji gibi sağlık konusunda kesin bilgi mutfaktan alınır."},{"metin":"Hoş geldiniz. Çocuk menüsünde yer fıstığı yoktur herhalde, buyurun.","puan":0,"tepki":"Anne tereddüt eder. “Herhalde” bir tahmindir; alerjide tahminle cevap verilmez, mutfağa danışılmalıdır."}]},{"konuk":"Levrek ve kızım için ızgara tavuk düşünüyorduk. Bunlar güvenli mi?","ingilizce":"We were thinking of the sea bass, and grilled chicken for my daughter. Are they safe?","secenekler":[{"metin":"Izgara olduğu için güvenlidir; pişince alerji kalmaz, siparişi verebilirsiniz.","puan":0,"tepki":"Anne bir an duraksar. Yanlış bilgi: pişirmek alerjiyi yok etmez; malzeme ve sos mutfaktan kontrol edilir."},{"metin":"Mutfağa söylerim, siz siparişi verin; sorun çıkarsa haber veririm.","puan":1,"tepki":"Anne tereddütle onaylar. Önce sipariş sonra kontrol sırası yanlış; yemek mutfaktan onay alındıktan sonra siparişe girmelidir."},{"metin":"Şefe soruyorum: reçeteye, sosa ve hazırlanış şekline bakılacak. Onay gelince siparişinizi alırım.","ingilizce":"I'm asking the chef to check the recipe, the sauce and how it is prepared. Once it's confirmed, I'll take your order.","puan":2,"tepki":"Anne memnun olur. Mutfak reçetelere ve hijyen kurallarına göre çalışır; içerik mutfaktan sorulunca kesin bilgi alınır."}]},{"konuk":"Ne dediler? Kızım için yemek hazırlanabilir mi?","ingilizce":"What did they say? Can the meal be prepared for my daughter?","secenekler":[{"metin":"Mutfak şu an çok yoğun, kesin söz veremiyoruz; yine de siparişi alayım, umarım bir sorun çıkmaz, çıkarsa kızınız söyler.","puan":0,"tepki":"Anne endişelenir. Konuğun gıda sağlığı emanettir; emin olunmayan yemek konuğa verilmez."},{"metin":"Şef levreğin ve tavuğun yer fıstığı içermeden hazırlanacağını onayladı. Siparişe “yer fıstığı alerjisi” notunu yazıp mutfağa iletiyorum.","ingilizce":"The chef has confirmed that the sea bass and chicken will be prepared without peanuts. I'm writing 'peanut allergy' on the order and passing it to the kitchen.","puan":2,"tepki":"Anne içtenlikle teşekkür eder. Alerji notu siparişle birlikte yazılı gidince bilgi servis sırasında kaybolmaz."},{"metin":"Yer fıstığı içermeden yapılacak denildi. Siparişi şimdi alıyorum.","puan":1,"tepki":"Anne yarı rahat siparişi verir. Onay doğru ama not siparişe yazılmadı; sözlü bilgi servis sırasında kolayca kaybolabilir."}]},{"konuk":"Tabaklar geldi. Kızımınki hangisi? Sosta bir şey olabilir mi?","ingilizce":"The plates are here. Which one is my daughter's? Could there be something in the sauce?","secenekler":[{"metin":"Tabaklar karışmış olabilir; mutfağa bakıp haber veririm, siz yemeğe başlayın.","puan":0,"tepki":"Anne tabakları geri iter. Kontrol sonuçlanmadan yemek yenmez; alerjik konuğun tabağı kesin olarak bilinmelidir."},{"metin":"Bu tabak kızınızın; hiçbiri yer fıstığı içermiyor. Afiyet olsun.","puan":1,"tepki":"Anne tabağı kızına verir ama içeriği merak eder. Doğru bilgi verildi ama içerik anlatılmadı; endişeli konuğa ayrıntı güven verir."},{"metin":"Bu tabak kızınızın, hanımefendi; alerji notuyla hazırlandı. İsterseniz içindekileri anlatayım, şefi de çağırayım.","ingilizce":"This plate is your daughter's, madam; it was prepared with the allergy note. If you like, I'll go through the ingredients and call the chef.","puan":2,"tepki":"Anne rahat bir nefes alır. Konuk sorusunu yanıtlamak ve ayrıntı sunmak satışı da güveni de artırır; garson menüyü iyi bilmelidir."}]},{"konuk":"Her şey harikaydı. Hesabı odamıza yazabilir misiniz? Oda 318.","ingilizce":"Everything was wonderful. Could you charge it to our room? Room 318.","secenekler":[{"metin":"Tamam, 318’e yazıyorum.","puan":1,"tepki":"Anne teşekkür eder. İmzasız kayıt, çıkışta itiraz çıkarsa belgesiz kalır; oda ve ad doğrulanmalıdır."},{"metin":"Elbette. Oda numaranızı ve adınızı doğrulayıp adisyonu imzalatıyorum; böylece doğru odaya yazılır.","ingilizce":"Of course. I'll confirm your room number and name, have you sign the bill and have it charged to your account, so it goes to the right room.","puan":2,"tepki":"Anne imzalar. İmzalı adisyon belgedir; yanlış odaya işlenirse başka bir konuk haksız yere borçlanır."},{"metin":"Oda numaranız yeterli, hesabı o kadarla yazarım; imza ve ad doğrulamasıyla vakit kaybetmeyelim, başka masalar da bekliyor.","puan":0,"tepki":"Anne ters bir şeyin olmadığını sanar. İmzasız adisyon belgesiz bir harcamadır; çıkışta itiraz edilirse tahsil zorlaşır."}]}]},{"id":"os-d14","unite":3,"baslik":"Gece Yarısı Oda Servisi","rol":"Oda servisi görevlisi","sahne":"Gece 23.30. Büyük bir otelin oda servisi gece de açıktır. Geç saatte otele varan İsveçli bir konuk 214 numaralı odadan telefon eder; yorgundur, sıcak bir şey yemek istemektedir.","kavramlar":["os-3-031","os-3-165","os-3-024","os-3-266"],"adimlar":[{"konuk":"Merhaba, 214 numaralı odadayım. Bir çorba ve bir tost istiyorum.","ingilizce":"Hello, I'm in room 214. I'd like a soup and a toasted sandwich, please.","secenekler":[{"metin":"Bu saatte oda servisi verilmez efendim; mutfak kapanmış olabilir, yarın sabah tekrar deneyin lütfen.","puan":0,"tepki":"Konuk şaşırır. Yanlış bilgi: büyük otellerde oda servisi günün her saatinde verilebilir; konuk aç ve yorgun."},{"metin":"İyi akşamlar efendim, oda servisi. Siparişiniz 214 numaralı oda için bir çorba ve bir tost; doğru anladım mı?","ingilizce":"Good evening, sir, room service. Your order is one soup and one toasted sandwich for room 214; have I understood correctly?","puan":2,"tepki":"Konuk “Evet, doğru” der. Sipariş ve oda numarası tekrarlanınca sipariş doğru odaya, eksiksiz ulaşır."},{"metin":"Peki, bir çorba bir tost. Hazır olunca getiririz.","puan":1,"tepki":"Konuk teşekkür eder ama emin olamaz. Sipariş ve oda tekrar edilmedi; yanlış anlaşılma sonradan çıkabilir."}]},{"konuk":"Bu ücretli mi? Hesabıma mı yazılacak?","ingilizce":"Is that charged? Will it go on my bill?","secenekler":[{"metin":"Fiyatı tam bilmiyorum, getirince görürsünüz; hesabınıza yazılıp yazılmayacağı da çıkışta belli olur.","puan":0,"tepki":"Konuk huzursuzlanır. Hizmetin ücretini bilmemek ve açıklamamak çıkışta tartışmaya yol açar; oda servisi çoğunlukla ekstra ücretlidir."},{"metin":"Evet, hesabınıza yazılır.","puan":1,"tepki":"Konuk “Peki” der. Ücretli olduğu ve nasıl görüneceği söylenmedi; konuk çıkışta şaşırabilir."},{"metin":"Oda servisi çoğunlukla ekstra ücretlidir efendim; tutar 214’ün hesabına işlenir, çıkışta dökümde görürsünüz.","ingilizce":"Room service usually carries an extra charge, sir. The amount goes on the account of room 214, and you will see it on your statement at check-out.","puan":2,"tepki":"Konuk rahatlar. Ücreti baştan söylemek çıkışta tartışmayı önler; harcama doğru odaya işlenir."}]},{"konuk":"Ne kadar sürer? Çok yorgunum, uyumak üzereyim.","ingilizce":"How long will it take? I'm very tired and about to fall asleep.","secenekler":[{"metin":"Bilemem, mutfağa bağlı; bekleyin.","puan":1,"tepki":"Konuk sıkılır. Dürüst ama soğuk bir cevap; sipariş mutfağa iletildi ve konuk süreç hakkında bilgilendirilmeli."},{"metin":"Mutfağa sorup tahmini süreyi hemen size bildireceğim; ardından siparişi tepsiyle getirip kapıyı çalarak kendimi tanıtırım.","ingilizce":"I'll ask the kitchen and tell you the estimated time right away; then I'll bring the order on a tray, knock and introduce myself.","puan":2,"tepki":"Konuk teşekkür eder. Süre sorusu cevapsız bırakılmadı; görevli tepsiyle gelir, kapıyı çalıp kendini tanıtır, sipariş sıcak ve eksiksiz ulaşır."},{"metin":"Siparişi kapınızın önüne bırakıp giderim; kapıyı çalmak sizi rahatsız eder, uykunuz kaçar, hiç uğraşmayalım, olur mu? Siz de yatın, sabah bakarsınız.","puan":0,"tepki":"Konuk şaşırır. Oda servisinde görevli kapıyı çalıp kendini tanıtır; kapı önüne bırakılan yemek soğur, eksiksiz teslim edildiğinden de emin olunamaz."}]},{"konuk":"Çorba geldi ama tost yok. Çorba da biraz ılık.","ingilizce":"The soup has arrived but there's no toastie. The soup is a bit lukewarm too.","secenekler":[{"metin":"Özür dilerim efendim, tost birazdan gelir.","puan":1,"tepki":"Konuk beklemeye razı olur ama emin değildir. Özür var, ancak ne zaman, nasıl sıcak getirileceği belli değil."},{"metin":"Mutfak unutmuş, benim suçum değil; bekleyin.","puan":0,"tepki":"Konuk bozulur. Sorumluluğu başkasına atmak güveni yıkar; konuk bölümleri değil oteli görür."},{"metin":"Özür dilerim efendim. Mutfağı hemen arıyorum; tostu ve gerekirse çorbayı sıcak getireceğim.","ingilizce":"I'm so sorry, sir. I'm calling the kitchen at once; I'll bring the toastie and, if needed, the soup again, hot.","puan":2,"tepki":"Konuk sakinleşir. Sipariş sıcak ve eksiksiz ulaşmalıdır; eksik giderilince konuğun güveni korunur."}]},{"konuk":"Tamam, şimdi her şey yolunda. Tepsiyi nereye bırakayım?","ingilizce":"Alright, everything's fine now. Where should I leave the tray?","secenekler":[{"metin":"Kapının önüne bırakabilirsiniz efendim, iyi geceler.","puan":1,"tepki":"Konuk tepsiyi kapının önüne koyar ve yatar. Yer doğru gösterildi, ama tepsinin ne zaman alınacağı söylenmedi; koridorda uzun süre bekleyen tepsi kötü görünür ve kokar."},{"metin":"Tepsiyi odada tutun, çıkışta resepsiyona getirirsiniz; biz kendimiz toplamıyoruz.","puan":0,"tepki":"Konuk şaşırır. Konuğa yük bırakılmaz; tepsiyi toplamak oda servisinin işidir. Bekleyen tepsi hem kötü görünür hem kokar."},{"metin":"Kapının dışına bırakabilirsiniz efendim, kısa sürede alırız; koridorda bekletmeyiz. Afiyet olsun, iyi geceler.","ingilizce":"You can leave it outside your door, sir; we'll collect it shortly and won't leave it in the corridor. Enjoy your meal, and good night.","puan":2,"tepki":"Konuk teşekkür eder, rahat bir uykuya çekilir. Tepsi hızla toplanınca koridor temiz kalır; hijyen ve görünüm korunur."}]}]},{"id":"os-d15","unite":4,"baslik":"Paris Turu Satışı","rol":"Acente danışmanı","sahne":"Cumartesi 14.00, mahalledeki bir acente. Yılmaz ailesi (anne, baba ve iki çocuk) vitrindeki “Paris Turu” ilanını görüp içeri girmiştir. Uçak, otel ve transferi tek tek aramaktan yorulmuşlardır; danışman satışı sözleşmeye kadar götürecek.","kavramlar":["os-4-063","os-4-009","os-4-054","os-4-051","os-4-074"],"adimlar":[{"konuk":"Merhaba, vitrinde Paris Turu’nu gördük. Uçak, otel ve transferi ayrı ayrı aramak istemiyoruz; hepsi bir arada mı?","ingilizce":"Hello, we saw the Paris tour in your window. We don't want to book flights, hotel and transfers separately. Is everything together?","secenekler":[{"metin":"Hoş geldiniz. Paket tur tam böyle: ulaşım, konaklama ve rehberlik tek fiyatla, tek sözleşmede; kaç kişisiniz, hangi tarih?","ingilizce":"Welcome. That is exactly what a package tour is: transport, hotel and a guide for one price in one contract. How many of you, and when?","puan":2,"tepki":"Aile rahatlar ve tarihlerini söylemeye başlar. Paket tur birden çok hizmeti tek fiyatla satan hazır üründür; ihtiyacı da hemen sormak doğru satışın ilk adımıdır."},{"metin":"Evet, hepsi bir arada. Ayrıntılar broşürde yazıyor, buyurun alın, evde sakin sakin bakarsınız; sorunuz olursa tekrar uğrarsınız.","puan":1,"tepki":"Konuk broşürü alır ama kendisine ilgi gösterilmediğini hisseder. Bilgi doğru, ancak satış görevlisi önce konuğun ihtiyacını ve tarihini sorar."},{"metin":"Hayır, uçak ayrı, otel ayrı satılır; biz yalnızca bilet kesiyoruz, otel için başka bir yere bakmanız gerekecek.","puan":0,"tepki":"Konuk şaşırır ve çıkmaya hazırlanır. Yanlış bilgi: paket turda ulaşım, konaklama ve rehberlik tek sözleşmeyle satılır."}]},{"konuk":"Otelden Eyfel Kulesi görünüyor mu? Kule manzaralı oda isteriz, çocuklar çok sevinir.","ingilizce":"Can we see the Eiffel Tower from the hotel? We'd love a room with a view; the children would be so happy.","secenekler":[{"metin":"Görünüyor tabii, çocuklar sabah perdeyi açınca kuleyi tam karşılarında görecek; bu manzarayı sizin için ayarlarım.","puan":0,"tepki":"Aile çok sevinir; ama otelden bir yazılı bilgi yoktur. Tutulamayacak söz satış anında sevindirir, tatilde şikâyete döner. Emin olunmayan şey vaat edilmez."},{"metin":"Broşürde yazan dışında bir bilgim yok efendim, bilemiyorum; otele kendiniz sorarsanız belki öğrenirsiniz.","puan":1,"tepki":"Konuk dürüstlüğü fark eder ama çözümsüz kalır. Yanlış söz verilmemiş, ancak bilgi için de bir adım atılmamış."},{"metin":"Bunu şu an kesin söyleyemem, yanlış söz vermek istemem. Otele yazılı olarak sorup size bildireyim; numaranızı alabilir miyim?","ingilizce":"I can't promise that now and I don't want to mislead you. Let me ask the hotel in writing and let you know. May I take your number?","puan":2,"tepki":"Aile bu dürüstlüğe güvenir ve numarasını verir. Satış vaadi turun sonuna kadar yerine getirilmesi gereken sözdür; emin olunmayan şey önce sorulur."}]},{"konuk":"Tamam. Gün gün ne yapacağımızı görebilir miyiz? Çocuklar sabah kaçta hazır olacaklarını bilmek ister.","ingilizce":"Okay. Can we see what we will do each day? The children like to know when to be ready in the morning.","secenekler":[{"metin":"Genel program broşürde yazıyor; gün gün saatleri sonra ayrıca vereyim.","puan":1,"tepki":"Aile broşüre bakar ama saatleri göremez. Tur programında saatler zaten yazılıdır; satıştan önce gösterilmesi gerekir, sonraya bırakılmaz."},{"metin":"Elbette. Tur programında her günün saatleri, gezileri ve hizmet sırası yazıyor; sabah hazır olma saatini de görebilirsiniz.","ingilizce":"Of course. The itinerary lists each day's times, visits and services, including the morning start time.","puan":2,"tepki":"Çocuklar programı merakla inceler. Tur programı (itinerary) güzergâhı, saatleri ve hizmetlerin sırasını gösterir; konuk neyi satın aldığını görür."},{"metin":"Program yok gibi, her gün durumuna göre rehber karar verir; bu yüzden saatleri önceden vermek de mümkün olmaz.","puan":0,"tepki":"Aile kararsız kalır. Yanlış bilgi: paket turun saatleri ve gezileri önceden yazılı bir programda bulunur."}]},{"konuk":"Peki bir şey olur da turu iptal etmemiz gerekirse ne olacak?","ingilizce":"What if something happens and we have to cancel the trip?","secenekler":[{"metin":"Her zaman tam iade yaparız, hiç kesinti olmaz; yeter ki bize haber verin, koşullara fazla takılmayın, sözleşmedeki maddeler genelde yazı süsüdür, siz yeter ki imzalayın.","puan":0,"tepki":"Konuk rahatlar; fakat iptal koşulları belirli bir tarihten sonra kesinti öngörür. Bu söz sonradan en sık şikâyet konularından birine dönüşür."},{"metin":"İptalde kesinti olabilir, sözleşmede yazıyor; tutara ve tarihe oradan bakarsınız, şimdi ayrıntıya girmeyelim.","puan":1,"tepki":"Konuk “Ne kadar, hangi tarihe kadar?” diye sorar. Söylenen doğru ama eksik; ilgili madde konuğa gösterilmelidir."},{"metin":"Önemli soru. İptal koşulları, hangi tarihe kadar ücretsiz iptal edeceğinizi ve sonrasındaki kesintiyi belirler; maddeyi sözleşmede birlikte okuyalım.","ingilizce":"Good question. The cancellation policy sets the date until which you can cancel free of charge and the deduction afterwards. Let's read the clause together.","puan":2,"tepki":"Aile maddeyi kendi gözüyle okur. İptal koşulları satış anında açıkça söylenir; söylenmezse sonradan en sık şikâyet konusu olur."}]},{"konuk":"Sözleşmeyi hemen imzalayalım, acelemiz var. Okumasak olur mu?","ingilizce":"Let's sign the contract now, we're in a hurry. Can we skip reading it?","secenekler":[{"metin":"Rica ederim, ana maddeleri okuyalım: program, fiyata dâhil hizmetler, iptal koşulları. Sözleşme iki tarafı da korur.","ingilizce":"Please, let's go through the main points: the programme, what the price includes and the cancellation terms. The contract protects both sides.","puan":2,"tepki":"Aile sakince dinler, birkaç soru sorar ve imzalar. Söz uçar, sözleşme kalır; satış görevlisi sözleşmeyi konuğa okutmadan imzalatmaz."},{"metin":"Yalnız fiyata ve tarihe bakalım, ayrıntılar hep aynı; dâhil hizmetleri ve iptal maddesini eve gidince okursunuz, sorarsanız yine uğrarsınız.","puan":1,"tepki":"Konuk imzalar ama dâhil hizmetleri ve iptal koşullarını görmemiştir. Sözleşmenin tamamı konuğun gözü önünde gözden geçirilir."},{"metin":"Hepsi standart bir sözleşme, okumadan imzalayabilirsiniz; her müşteri aynısını imzalıyor.","puan":0,"tepki":"Konuk imzalar, ama sonradan bir sorun çıkarsa neyi kabul ettiğini bilmez. Sözleşme bir formalite değildir; okutmadan imzalatmak hem konuğun hem acentenin hakkını zayıflatır."}]},{"konuk":"Teşekkürler, imzaladık ama otelle ilgili kule manzarası konusunda ne zaman haber alırız?","ingilizce":"Thank you, we have signed, but when will we hear back about the Eiffel Tower view?","secenekler":[{"metin":"Gelince siz öğrenirsiniz, ayrıca aramam; otel bir şey diyecekse kendisi söyler.","puan":0,"tepki":"Aile kırılır. Söz verilen bilgiyi iletmemek güveni bozar; konuk tatile gitmeden önce yanıtı bilmek ister."},{"metin":"Pazartesi öğleden önce otele yazılı olarak soracağım ve yanıtı size ileteceğim; bu benim sözüm.","ingilizce":"I'll put the question to the hotel in writing and pass their answer on to you by noon on Monday; you have my word.","puan":2,"tepki":"Aile gülümseyerek ayrılır. Yerine getirilebilecek net bir söz ve takip, satış vaadinin tutulmasının başlangıcıdır."},{"metin":"En kısa zamanda haber veririm efendim; telefonunuz açık olsun, sizi ararım.","puan":1,"tepki":"Konuk “En kısa ne zaman?” diye düşünür. Niyet iyi, ama belirli bir zaman verilmediği için konuk beklentisini kuramaz."}]}]},{"id":"os-d16","unite":4,"baslik":"Pasaport ve Vize Danışması","rol":"Acente danışmanı","sahne":"Pazartesi 11.00, acente. Çelik ailesi yaz tatilinde Paris, Amsterdam ve Brüksel’i gezen bir tura katılacak. Kızları Elif’in pasaportu yok ve baba Mehmet Bey vize sürecini hiç bilmiyor.","kavramlar":["os-4-115","os-4-104","os-4-108","os-4-118","os-4-017"],"adimlar":[{"konuk":"Kızımın pasaportu yok. Bizim yerimize çıkarıp getirebilir misiniz?","ingilizce":"My daughter doesn't have a passport. Can you get it issued for us?","secenekler":[{"metin":"Evet, bir hafta içinde biz çıkarırız; kızınızın kimliğini ve fotoğrafını bırakmanız yeter, randevu ve sıra derdiyle uğraşmayın.","puan":0,"tepki":"Baba sevinir ama söz yanlıştır. Pasaportu acente değil devlet, yani nüfus müdürlüğü çıkarır; verilen sözü tutmak mümkün değildir."},{"metin":"Pasaportu acente değil nüfus müdürlüğü çıkarır. Randevuyu e-Devlet’ten ya da 199’dan alın; kimlik ve biyometrik fotoğraf gerekir, reşit değilse bir ebeveyn de gelmeli.","ingilizce":"A passport is issued by the population directorate, not by us. Book through e-Devlet or on 199; you need an ID and a biometric photo, and a parent must go along if your daughter is under 18.","puan":2,"tepki":"Baba not alır ve randevuyu hemen alacağını söyler. Pasaport başvurusu randevulu ve şahsen yapılır; reşit olmayanlarda anne ya da baba hazır bulunur."},{"metin":"Biz çıkaramayız, nüfus müdürlüğüne gidin; randevu alıp almamanız gerektiğini, hangi belgeleri götüreceğinizi ve kızınızın yanında kimin olacağını orada öğrenirsiniz; biz bu konuda yardımcı olamayız.","puan":1,"tepki":"Doğru yönlendirme ama baba nasıl başvuracağını bilmeden kalır. Randevunun nasıl alındığı ve hangi belgelerin gerektiği de söylenmelidir."}]},{"konuk":"Üç ülke gezeceğiz. Her biri için ayrı vize mi almamız gerekiyor?","ingilizce":"We are visiting three countries. Do we need a separate visa for each one?","secenekler":[{"metin":"Evet, her ülke için ayrı başvuru, ayrı ücret ve ayrı randevu gerekir; üç ülke üç ayrı vize demektir.","puan":0,"tepki":"Baba bunalır ve turdan vazgeçmeyi düşünür. Yanlış bilgi: Schengen Bölgesi’ndeki ülkelere tek ortak vizeyle girilir."},{"metin":"Bence tek vize yeter ama emin değilim, siz de bir bakın; yanlış olursa sonra düzeltiriz.","puan":1,"tepki":"Konuk güven duymaz. Doğru bilgiye yakın, ama bilgi veren görevli tahmin etmez; güncel kural kontrol edilip net söylenir."},{"metin":"Hayır; üçü de Schengen Bölgesi’nde, tek Schengen vizesi hepsinde geçerli. Üye listesi değişebildiği için güncelini resmî kaynaktan kontrol edeceğim.","ingilizce":"No. All three are in the Schengen Area, so one visa covers them. The member list can change, so I'll check it from an official source.","puan":2,"tepki":"Baba rahatlar. Schengen vizesi sınır kontrolü kalkmış ülkelerde ortak geçerlidir; ülke listesi değiştiği için resmî kaynaktan doğrulanır."}]},{"konuk":"Başvuruda neler isteniyor? Banka dökümünü almadım, bir eksik olsa da olur herhalde.","ingilizce":"What do they ask for in the application? I haven't got the bank statement. A missing paper won't matter, will it?","secenekler":[{"metin":"Listeyi vereyim, eksikleri siz toplarsınız; hazır olunca dosyayı birlikte kontrol ederiz.","puan":1,"tepki":"Baba listeyi alır ama eksik belgenin başvuruda ret nedeni olabileceğini bilmez. Liste verildi, ama dökümün randevudan önce tamamlanması hatırlatılmadı; görevli eksiği önceden fark edip tamamlattırır."},{"metin":"Dökümü bize bırakın, uygun görünen bir döküm biz hazırlarız.","puan":0,"tepki":"Bu çok ciddi bir hata: gerçeğe aykırı belge hazırlamak başvurunun reddine yol açar. Acente konuğun belgesini düzeltmez, yalnız gerçek belgeyi tamamlatır."},{"metin":"Pasaport, imzalı form, biyometrik fotoğraf, sigorta, uçak ve otel rezervasyonu, banka dökümü ve iş yeri yazısı gerekiyor. Eksik belge ret nedenidir; dökümü randevudan önce tamamlayalım.","ingilizce":"You need the passport, a signed form, a biometric photo, insurance, flight and hotel bookings, a bank statement and a letter from your employer. Missing papers can cause a refusal, so let's get the statement before the appointment.","puan":2,"tepki":"Baba listeyi alır ve bankaya gideceğini söyler. Vize sorumlusu eksik belgeyi randevu gününden önce fark edip tamamlattırır."}]},{"konuk":"Sağlık sigortası da şart mı? Biz hastalanmayız ki.","ingilizce":"Is health insurance really necessary? We won't get ill.","secenekler":[{"metin":"Evet, sigorta isteniyor; poliçeyi yaptırıp bana getirin, bakarız.","puan":1,"tepki":"Baba poliçe yaptırmaya gider. Zorunlu olduğu doğru söylendi, ama poliçenin bütün seyahati kapsaması gerektiği anlatılmadı; tarih eksikliği sonradan sorun çıkarabilir."},{"metin":"Zorunlu, bir poliçe yaptıralım; tarihlerine sonra bakarız, önemli olan poliçenin olması.","puan":0,"tepki":"Poliçe alınır ama tarihler yanlış yazılırsa vize başvurusunda sorun çıkabilir. “Tarihlerine sonra bakarız” diyen görevli en önemli ayrıntıyı atlamış olur; poliçenin tarihleri hemen kontrol edilmelidir."},{"metin":"Schengen başvurusunda seyahat sağlık sigortası isteniyor. Poliçe gidiş gününden dönüş gününe bütün süreyi kapsamalı; acil bir sağlık gideri çıkarsa sizi korur.","ingilizce":"A travel health insurance is required for a Schengen application. The policy must cover the whole trip, from departure to return, and it protects you if an urgent medical cost comes up.","puan":2,"tepki":"Baba poliçeyi birlikte yaptırır. Poliçenin tarihleri seyahatin ilk gününden son gününe kadar olmalıdır; bir gün eksik yazılan poliçe sorun çıkarabilir."}]},{"konuk":"Son olarak, vizemiz kesin çıkar, değil mi? Uçak biletlerini almak istiyorum.","ingilizce":"Finally, our visas will definitely be approved, won't they? I'd like to buy the flight tickets.","secenekler":[{"metin":"Evet, vizeniz çıkar; hepsini biz hallederiz, biletleri alabilirsiniz.","puan":0,"tepki":"Baba bilet alır. Vizeyi acente değil konsolosluk verir; reddedilirse konuk “Siz kesin demiştiniz” diyecektir. Kesin söz verilmez."},{"metin":"Kararı konsolosluk verir, kesin söz veremem; dosyayı eksiksiz hazırlarım. Başvuruda rezervasyon istenir; vize kararı çıkmadan kesin bilet almayın.","ingilizce":"The consulate makes the decision, so I can't promise; I'll prepare your file completely. A reservation is asked for in the application; please don't buy firm tickets before the visa decision.","puan":2,"tepki":"Baba dürüstlüğe teşekkür eder ve belge listesiyle ayrılır. Vizeyi o ülkenin makamları verir; başvuruda uçak rezervasyonu istenir, bu yüzden kesin bilet vize kararından sonra alınır."},{"metin":"Evrak tamsa olumlu sonuç ihtimali yüksek; ama karar konsolosluğun.","puan":1,"tepki":"Baba biraz rahatlar. Kararın konsoloslukta olduğu söylendi; ama bilet sorusu cevapsız kaldı: vize çıkmadan kesin bilet alınmaması gerektiği belirtilmeliydi."}]}]},{"id":"os-d17","unite":4,"baslik":"Uçak Bileti Değişikliği","rol":"Bilet personeli","sahne":"Salı 10.30, acentenin telefon hattı. Bay Kaya, cuma akşamı için aldığı uçak biletinin pazar gününe alınmasını istiyor. Ailede bir gelişme olmuş ve konuğun sesi telaşlı.","kavramlar":["os-4-042","os-4-016","os-4-051","os-4-044","os-4-043"],"adimlar":[{"konuk":"Merhaba, ailede bir sorun çıktı, cuma günkü uçak biletimi pazara almam gerekiyor.","ingilizce":"Hello, something has come up in the family, and I need to move my Friday flight to Sunday.","secenekler":[{"metin":"Biletler değişmez, iptal edin, yenisini alın; başka yolu yok.","puan":0,"tepki":"Konuk panikler. Bilet kuralları bakılmadan reddedilemez; hava yolunun koşulları incelenir ve bilet türüne göre değişiklik mümkün olabilir."},{"metin":"Geçmiş olsun, hemen yardımcı olayım. PNR numaranızı ve soyadınızı alabilir miyim?","ingilizce":"I'm sorry to hear that; let me help right away. Could I have your PNR and surname, please?","puan":2,"tepki":"Konuk PNR’ını okur ve işlem hızla başlar. Bilet değişikliği için aradığında acentecinin ilk sorusu PNR’dır; kayıt buna göre bulunur."},{"metin":"Bir saniye, rezervasyonunuzu bulayım; adınız ve uçuş saatiniz neydi, tarihi de söyler misiniz?","puan":1,"tepki":"Kayıt yine bulunur ama zaman kaybedilir. Hava yolu rezervasyonlarında kaydı bulduran en hızlı bilgi PNR’dır."}]},{"konuk":"PNR numaram K7M2QX, soyadım Kaya. Adım biletimde Mehmet olarak görünüyor.","ingilizce":"My PNR is K7M2QX, surname Kaya. My first name should be Mehmet on the ticket.","secenekler":[{"metin":"Teşekkürler, kaydı buldum, devam ediyorum.","puan":1,"tepki":"İşlem sürer ama ad doğrulanmamıştır. Biletteki ad pasaport ya da kimlikteki adla aynı olmalıdır; kayıt konuğa bir kez okunmalıdır."},{"metin":"Adınızda küçük bir yazım farkı olsa bile havalimanında sorun olmaz, boşuna vakit kaybetmeyelim, geçiyorum.","puan":0,"tepki":"Konuk havalimanında adı uyuşmadığı için engellenebilir. Küçük bir yazım hatası bile yolcuya havalimanında sorun çıkarır."},{"metin":"Teşekkürler. Ekranda Mehmet Kaya, cuma uçuşu görünüyor; adı harf harf okuyorum, doğru mu?","ingilizce":"Thank you. I can see Mehmet Kaya on the Friday flight. I'll read the name back to you letter by letter. Is it correct?","puan":2,"tepki":"Konuk “Evet, doğru” der. Bilet personeli adı pasaporttaki gibi harf harf kontrol eder ve konuğa sesli okur; havalimanı sürprizi önlenir."}]},{"konuk":"Değişiklik için para ödemem gerekir mi?","ingilizce":"Will I have to pay for the change?","secenekler":[{"metin":"Değişiklikte genelde bir ücret çıkar ama tutarını şu an bilmiyorum, değişikliği yaptıktan sonra ekranda ne çıkarsa görürsünüz, o zaman konuşuruz.","puan":1,"tepki":"Konuk kararsız kalır. Genel bir cevap verilmiş; oysa biletin kendi kurallarına bakılıp somut bilgi verilebilir."},{"metin":"Ücretsizdir, hiçbir ücret çıkmaz; bilet değişikliği her zaman bedavadır.","puan":0,"tepki":"Konuk sevinir; kurallara bakılmadan söz verildi. Koşullar bilete göre değişir ve kesinti çıkarsa konuk sonradan şikâyet eder."},{"metin":"Bu biletin değişiklik koşullarına bakıyorum: hangi tarihe kadar ücretsiz, sonrasında ne kadar kesinti var, orada yazıyor. Net söyleyeceğim.","ingilizce":"I'm checking the change rules on your ticket: until when it is free and what is deducted afterwards. I'll give you a clear answer.","puan":2,"tepki":"Konuk beklemeyi kabul eder. İptal koşulları ürüne göre değişir; görevli tahmin etmez, kuralı okuyup söyler."}]},{"konuk":"Pazar günü 18.00 uçuşunda yer varmış, lütfen ayırın. Eşime hemen “bilet tamam” diyeceğim.","ingilizce":"There is a seat on the 18.00 flight on Sunday. Please book it. I'll tell my wife right away that the ticket is sorted.","secenekler":[{"metin":"Yeri ayırıyorum, ama hava yolunun yazılı onayı gelmeden “tamam” demeyelim. Onay numarasını e-postayla da göndereceğim.","ingilizce":"I'm booking the seat, but let's not call it sorted until the airline's written confirmation arrives. I'll also email you the confirmation number.","puan":2,"tepki":"Konuk beklemeyi anlar ve onayı bekler. Konfirmasyon, hizmeti verecek işletmenin yazılı onayıdır; onayı gelmemiş rezervasyon yapılmamış sayılır."},{"metin":"Ayırdım. Onay gelirse gelir, gelmezse de ben size haber veremeyebilirim.","puan":0,"tepki":"Konuk neyin ne zaman olacağını bilemez. Yazılı onay beklenir ve konuğa net bir takip sözü verilir; “haber veremeyebilirim” diyen görevli güveni kaybettirir."},{"metin":"Yeri ayırdım. Onay gelince size haber veririm; eşinize henüz kesin demeyin.","puan":1,"tepki":"Konuk onayı bekler. Yönlendirme doğru, ama onayın ne zaman ve hangi yolla geleceği söylenmedi; onay numarası ve bir zaman söylenseydi tam olurdu."}]},{"konuk":"Eşimle konuşup yarın kesinleştirsem olur mu? Yer kaybolmasın.","ingilizce":"Can I confirm tomorrow after speaking to my wife? I don't want to lose the seat.","secenekler":[{"metin":"Tabii, yarına kadar tutarım; sistem bana bu konuda esneklik tanır, hava yolunun onayını almama gerek kalmaz.","puan":0,"tepki":"Konuk rahatlar, ama süre hava yolunun tanıdığı süredir. Süreyi uzatmak için yeri ayıran işletmenin onayı gerekir; görevli kendi başına söz vermez."},{"metin":"Yeri bugün 17.00’ye kadar tutabiliyorum; bu opsiyon süresinde ödeme gelmezse yer başkasına satılır. Daha uzun süre için hava yolunun onayı gerekir.","ingilizce":"I can hold the seat until 17.00 today. If it isn't paid by this option date it will be sold to someone else. For longer I need the airline's approval.","puan":2,"tepki":"Konuk saati not eder ve eşini hemen arar. Opsiyon, ödeme için tanınan son tarihtir; konuğa açıkça söylenir ve uzatma sözü verilmez."},{"metin":"Olabilir, ama yeri tam ne zamana kadar tutabildiğimi şimdi söyleyemem; bakıp size yazarım, siz de telefonunuzu açık tutun.","puan":1,"tepki":"Konuk süreyi bilmediği için tedirgin kalır. Opsiyon tarihi konuğa en baştan açıkça söylenmelidir."}]},{"konuk":"Tamam, ödemeyi şimdi yapıyorum. Başka bir şey var mı?","ingilizce":"Right, I'm paying now. Is there anything else?","secenekler":[{"metin":"Hayır, hepsi bu. İyi günler, görüşmek üzere.","puan":1,"tepki":"İşlem biter ama konuk yeni bilet bilgisini nereden alacağını bilmez. Kapanışta onay ve bilgilerin nereye gideceği söylenmelidir."},{"metin":"Ödemeniz alındı; yeni bilet bilgilerini ve onayı e-postanıza gönderiyorum. Havalimanında PNR’ınız yanınızda olsun, iyi yolculuklar.","ingilizce":"Your payment has been received; I'm emailing the new ticket details and the confirmation. Please keep your PNR with you at the airport. Have a pleasant trip.","puan":2,"tepki":"Konuk teşekkür eder ve rahat ayrılır. Yazılı konfirmasyon ve PNR, konuğun kayda ulaşmasını sağlar."},{"metin":"E-posta gelmezse de sorun olmaz, havalimanında bir şekilde buluruz; PNR numarasını da hatırlamayın, adınızı söylemeniz yeter, kayıt orada çıkar.","puan":0,"tepki":"Konuk belgesiz kalabilir. Yazılı onay olmadan verilen güvence yanlıştır; konuğa onayın gönderildiği teyit edilir."}]}]},{"id":"os-d18","unite":4,"baslik":"Gece Karşılama: Havalimanı Transferi","rol":"Transfer görevlisi","sahne":"Gece 01.15, havalimanı gelen yolcu çıkışı. Acentenin transfer görevlisi, tabelası ve konuk listesiyle bekliyor. Gece uçuşundan inen, Carter soyadlı yorgun bir çift çıkışa yürüyor.","kavramlar":["os-4-022","os-4-045","os-4-004","os-4-055","os-4-021"],"adimlar":[{"konuk":"Merhaba, tabelanızı gördük. Carter adına rezervasyonumuz var.","ingilizce":"Hello, we saw your sign. We have a booking under Carter.","secenekler":[{"metin":"Sırayla gelin lütfen, ben yalnız önümdeki gruba bakıyorum, sizin için sonra vakit ayırırım.","puan":0,"tepki":"Konuk gece yarısı yorgun bir yüzle geri çekilir. Transfer görevlisi, konuğun Türkiye’de gördüğü ilk yüzdür; ilk izlenim burada kurulur."},{"metin":"Hoş geldiniz, iyi geceler. Adınızı listemde işaretleyeyim; kaç kişisiniz, hangi otelde kalacaksınız?","ingilizce":"Welcome, good evening. Let me tick your name on my list. How many of you are there, and which hotel are you at?","puan":2,"tepki":"Çift rahatlar ve otel adını söyler. Transfer elemanı konukları listesinden tek tek işaretleyip araca alır."},{"metin":"Hoş geldiniz, buyurun aracın yanına gidelim, bavullarınızı da alalım.","puan":1,"tepki":"Konuk gelir, ama liste hiç kontrol edilmedi. Konuğun gerçekten bu transferde olup olmadığı doğrulanmadan araca alınmaz."}]},{"konuk":"Adımız listenizde görünmüyor galiba, ama acenteden aldığımız voucher yanımızda.","ingilizce":"We don't seem to be on your list, but we have a voucher from the agency.","secenekler":[{"metin":"Voucher’ınızı gördüm, binin; gerisini sonra hallederiz, operasyonu aramayacağım.","puan":0,"tepki":"Konuk araca biner, ama görevli kendi başına karar vermiştir. Listede eksik ya da fazla kişi varsa görevli operasyonu arar; haber verilmeden alınan yolcu kayıtta eksik kalır."},{"metin":"Voucher’ınızı görüyorum. Operasyonu arıyorum, bir dakika.","puan":1,"tepki":"Konuk rahatlar ve bekler. Operasyon doğru aranıyor, ama voucher’ın tarihleri kontrol edilmedi ve konuğa kısa bir açıklama yapılmadı; konuk ayakta bekler."},{"metin":"Sorun değil, voucher’ınıza bakabilir miyim? Tarihleri kontrol edip operasyonu arayacağım; bu sırada kısaca oturabilirsiniz.","ingilizce":"No problem. May I see your voucher? I'll check the dates and call our operations team. Please take a seat for a moment.","puan":2,"tepki":"Operasyon birkaç dakikada kaydı bulur. Voucher hizmeti kanıtlar; fark olunca konukla tartışılmaz, operasyon aranır."}]},{"konuk":"Üç büyük bavulumuz var ve uçak geç indi. Çok yorgunuz.","ingilizce":"We have three big suitcases and the flight landed late. We are very tired.","secenekler":[{"metin":"Uçak geç indi diye araç beklemez, lütfen hızlı olun; bizim de başka işlerimiz var.","puan":0,"tepki":"Konuk üzülür ve gerilir. Transfer tatilin ilk anısıdır; kaba bir karşılama yolculuğun tamamını gölgeler."},{"metin":"Anlıyorum, uzun bir yolculuk olmuş. Bavullarınıza yardım edeyim; araç çıkışın hemen önünde, birlikte gidelim.","ingilizce":"I understand, it has been a long journey. Let me help with your suitcases; the vehicle is right outside the exit, so let's go together.","puan":2,"tepki":"Çift gülümser ve teşekkür eder. Transfer elemanı konukları araca yönlendirir ve yol boyunca onlara eşlik eder."},{"metin":"Araç otoparkta, buyurun yürüyelim; bavullar için asansör şurada.","puan":1,"tepki":"Konuk bavullarıyla yorgun yürür. Yönlendirme doğru ama konuğun yorgunluğu anlaşılmadı, bavullara yardım edilmedi."}]},{"konuk":"Otele ne kadar sürer? Yarın sabah ne yapacağımızı da bilmiyoruz.","ingilizce":"How long will it take to get to the hotel? We also don't know what we are doing tomorrow morning.","secenekler":[{"metin":"Otel yakın sayılır, kısa sürer; yarın sabah ne yapacağınızı resepsiyona sorarsanız size yardımcı olurlar, endişelenmeyin, bir şekilde öğrenirsiniz, hiç sorun yok; gerekirse tekrar sorarsınız.","puan":1,"tepki":"Konuk sorusunun yanıtlanmadığını düşünür. Yarını kimden ve nerede öğreneceği net söylenmedi."},{"metin":"Yarın sabah 07.00’de hazır olun, ilk iş gezi var; geç kalan olursa bekleyemeyiz.","puan":0,"tepki":"Konuk dehşete düşer; böyle bir program yoktur. Bilmediği bilgiyi uydurmak konuğu yanıltır."},{"metin":"Varış süresi yola bağlı, sürücüye sorup kesin söyleyeyim. Yarın için otel rehberimiz sizi bilgilendirecek; saatini operasyondan öğrenip ileteceğim.","ingilizce":"The journey time depends on the traffic; let me ask the driver and give you an exact answer. Our hotel representative will brief you tomorrow; I'll confirm the time with operations and let you know.","puan":2,"tepki":"Konuk ne olacağını öğrenmiş olarak rahatlar. Otel rehberi, konuklara bilgilendirme yapar ve konaklama boyunca sorularını yanıtlar."}]},{"konuk":"Sonunda geldik! Voucher’ı resepsiyona mı vereceğiz?","ingilizce":"We've finally arrived! Do we give the voucher to reception?","secenekler":[{"metin":"Voucher’ı bana bırakın, ben resepsiyonla hallederim; siz doğrudan odanıza çıkın, belgeler benim elimde kalsın.","puan":0,"tepki":"Konuk belgesiz kalır ve resepsiyon onu tanıyamaz. Voucher konuğun satın aldığı hizmeti kanıtlayan belgedir ve otel konuğu onunla tanır."},{"metin":"Evet, resepsiyona gösterin; otel tarihleri ve oda tipini ondan kontrol eder. Sizi listemde “karşılandı” diye işaretleyip operasyona haber veriyorum.","ingilizce":"Yes, show it at reception; the hotel will check the dates and room type from it. I'll tick you off my list as collected and tell operations.","puan":2,"tepki":"Çift teşekkür ederek içeri girer. Voucher otelde ibraz edilir; görevli listeyi tamamlayıp operasyona bilgi vererek süreci kapatır."},{"metin":"Evet, voucher’ı verin, kayıt yaptırın. Ben de gidiyorum, iyi geceler.","puan":1,"tepki":"Konuk içeri girer; hizmet tamamlanmıştır. Ancak operasyona haber verilmeyen bir karşılama kayıtta eksik kalır."}]}]},{"id":"os-d19","unite":4,"baslik":"Tur Sırasında Gerilim","rol":"Tur rehberi","sahne":"Kapadokya turunun ikinci günü; sabah lobide başlayan gün akşama kadar sürüyor. Rehber yakasındaki kokartla grubun karşısında; dün akşamki gecikme yüzünden bazı konuklar kırgın, Bay Roberts özellikle gergin.","kavramlar":["os-4-121","os-4-028","os-4-054","os-4-023","os-4-020"],"adimlar":[{"konuk":"Günaydın. Rehber siz misiniz? Yetkili biri olduğunuzu nereden bileceğiz?","ingilizce":"Good morning. Are you the guide? How do we know you are authorised?","secenekler":[{"metin":"Evet, rehberinizim. Acente beni gönderdi, programı da elimde tutuyorum; kokartım yakamda.","puan":1,"tepki":"Konuk kısmen ikna olur. Rehber olduğunu söyledi ve kokartı işaret etti, ama belgenin neyi gösterdiğini anlatmadı; yetkisini açıkça göstermek güveni anında kurardı."},{"metin":"Evet, rehberim, acente beni gönderdi; kokart ya da belge göstermem, tanıdık bir yüzüm yeter.","puan":0,"tepki":"Konuk ikna olmaz. Rehberin yetkisini gösteren belge kokarttır; kokartı göstermemek ve “tanıdık bir yüzüm” demek güveni kurmaz."},{"metin":"Günaydın, rehberinizim. Bu kokart Kültür ve Turizm Bakanlığının verdiği yetki belgesi; isterseniz inceleyin.","ingilizce":"Good morning, I'm your guide. This badge is issued by the Ministry of Culture and Tourism and shows I'm licensed; please have a look.","puan":2,"tepki":"Bay Roberts kokartı inceler ve biraz yumuşar. Rehber kokartı, kişinin profesyonel turist rehberi olarak çalışmaya yetkili olduğunu gösterir."}]},{"konuk":"Programda 09.00’da Göreme Açık Hava Müzesi yazıyor. Saat 09.40, neden hâlâ buradayız?","ingilizce":"The programme says the Göreme Open Air Museum at 09.00. It is 09.40. Why are we still here?","secenekler":[{"metin":"Trafik yüzünden, ne yapalım. Birazdan kalkarız, merak etmeyin; sonuçta herkes tatilde, acele edecek ne var?","puan":1,"tepki":"Konuk özür duymadığı için daha da sinirlenir. Aksaklığı operasyona haber vermek ve konuğa açıklamak rehberin görevidir."},{"metin":"Gecikme yok, program böyle işliyor; saatlere bu kadar takılmayın, müzeye vardığımızda kimse hatırlamaz bile.","puan":0,"tepki":"Bay Roberts saatine bakarak itiraz eder ve güvenini yitirir. Aksaklık saklanmaz; gecikmeyi inkâr etmek durumu daha da kötüleştirir."},{"metin":"Haklısınız, otobüs gecikti, özür dilerim. Operasyonu arayıp yeni varış saatini öğreniyorum; programı en az aksamayla sürdürmeye çalışacağım.","ingilizce":"You are right, the coach was late and I apologise. I'm calling operations for the new arrival time, and I'll try to keep the programme on track with as little disruption as possible.","puan":2,"tepki":"Konuk sakinleşir ve bekler. Programda yazan saat ortak plandır; aksaklık hemen operasyona bildirilir ve konuk bilgilendirilir."}]},{"konuk":"Öğleden sonra köy pazarı vardı programda. Zaman kalmadıysa onu atlayacak mısınız?","ingilizce":"There was a village market in the afternoon in the programme. If time is short, will you skip it?","secenekler":[{"metin":"Köy pazarını gerekçesiz atlamak istemem. Operasyonla konuşup programı korumaya çalışacağım; olmazsa nedenini açıkça söylerim.","ingilizce":"I don't want to skip the village market without a good reason. I'll talk to operations and try to keep the programme; if I can't, I'll tell you why.","puan":2,"tepki":"Konuk rahatlar. Programda yazan yer gerekçesiz atlanmaz; atlanacaksa nedeni açıkça söylenir. Bu dürüstlük meslek etiğinin parçasıdır."},{"metin":"Zamana bakarız, belki atlarız; öğleden sonra durumu görüp karar veririm, şimdiden kesin bir şey söyleyemem, ama sizi bilgilendiririm.","puan":1,"tepki":"Konuk ne olacağını bilemez. Cevap dürüst ama belirsiz; nedeni ve alternatifi söylenmedi."},{"metin":"Evet, zaman kalmadı; onun yerine grubu anlaşmalı olduğumuz mağazaya götürelim, orada vakit geçirir, hediyelik de alırsınız.","puan":0,"tepki":"Konuk durumu fark edip tepki gösterir. Programdaki yeri “zaman kalmadı” diyerek atlayıp yalnız komisyon alınan mağazaya götürmek konuğun hakkını çiğnemektir."}]},{"konuk":"Şu freske yaklaşıp bir dokunsam ne olur? Sadece yakından bakmak istiyorum.","ingilizce":"What's the harm in touching this fresco? I just want a closer look.","secenekler":[{"metin":"Tamam, ama kimse görmesin, bir saniye dokunun; o kadarı eseri bozmaz.","puan":0,"tepki":"Konuk dokunur ve diğer konuklar da özenir. Kültür varlıklarını korumak rehberin görevidir; eserlere dokunulmaz."},{"metin":"Anlıyorum, yakından görmek istemeniz çok doğal. Ama eserler dokunmakla zarar görür; freske dokunmadan, çizginin gerisinden izleyin.","ingilizce":"I understand, wanting a closer look is natural. But touching damages works of art; please enjoy the fresco without touching it, from behind the line.","puan":2,"tepki":"Konuk gülümseyip geri çekilir ve çizginin gerisinden izler. Rehber eserlere dokunulmaması gerektiğini nazikçe hatırlatır ve koruma bilincini aşılar."},{"metin":"Lütfen dokunmayın, yasak; tabelayı görmediniz mi, burada dokunmak olmaz, herkes kurallara uymak zorunda, bir daha uyarmayacağım, dikkat edin.","puan":1,"tepki":"Konuk geri çekilir ama kırılmış görünür. Yasak doğru; nedeni ve alternatifi söylenseydi konuk daha iyi anlardı."}]},{"konuk":"Bugün gecikme ve gerginlik yüzünden keyfim kaçtı. Acenteye şikâyet edeceğim.","ingilizce":"The delay and the tension spoilt my day. I'm going to complain to the agency.","secenekler":[{"metin":"Gecikmeyi ben yapmadım, şikâyet edecekseniz otobüs firmasına edin; benim görevim yalnız anlatmak, gerisi operasyonun ve şoförün konusu.","puan":0,"tepki":"Konuk daha da kızar. Rehber konuğun karşısındaki yüzdür; sorumluluğu başkasına atmak güveni bozar ve aksaklık saklanamaz."},{"metin":"Sizi dinledim, haklı olduğunuz yerler var. Gecikmeyi operasyona yazılı bildireceğim; şikâyet etmek hakkınız, yarın için neye ihtiyacınız var?","ingilizce":"I've listened to you and you are right in places. I'll report the delay to operations in writing, and you have every right to complain; what do you need for tomorrow?","puan":2,"tepki":"Bay Roberts sakinleşir ve beklentilerini anlatır. Aksaklık saklanmaz, operasyona bildirilir; şikâyet etmek konuğun hakkıdır ve rehber buna engel olmaz."},{"metin":"Üzgünüm, yarın daha iyi geçmesi için elimden geleni yapacağım; umarım bu akşam keyfiniz yerine gelir.","puan":1,"tepki":"Konuk kısmen yumuşar. Üzüntü ve çaba söylendi, ama gecikmenin operasyona bildirileceği ve şikâyet hakkı konuşulmadı; somut bir adım yok."}]},{"konuk":"Peki, teşekkürler. Yarın sabah kaçta lobide olacağız?","ingilizce":"All right, thank you. What time will we meet in the lobby tomorrow?","secenekler":[{"metin":"Saati şimdi bilmiyorum, sabah öğrenirsiniz; program her gün değişebiliyor.","puan":0,"tepki":"Konuk yeniden kuşkulanır. Konuk sabah kaçta hazır olacağını tur programından öğrenir ve rehber bunu bilir."},{"metin":"Programa göre yarın 08.30’da lobideyiz; saati akşam bir daha teyit edip hatırlatırım. İyi akşamlar.","ingilizce":"According to the programme we meet in the lobby at 08.30 tomorrow; I'll confirm the time again this evening and remind you. Good evening.","puan":2,"tepki":"Konuk gülümseyerek ayrılır. Program, rehberin, şoförün ve otelin ortak planıdır; saat net söylenir."},{"metin":"Sabah lobiye gelin, otobüs nasılsa bekler; acele etmeyin.","puan":1,"tepki":"Konuk tam saati bilmez; yarın da kuşku duyacak. Hizmet saati konuğa açıkça söylenmelidir."}]}]},{"id":"os-d20","unite":5,"baslik":"Gürültü Şikâyeti","rol":"Konuk ilişkileri görevlisi","sahne":"Saat 08.30, kalabalık lobi. Bir iş konuğu, dün gece yan odadan sabaha yakın ses geldiğini yüksek sesle anlatarak konuk ilişkileri masasına yaklaşıyor. Gün içinde önemli bir toplantısı var ve iki gece daha kalacak.","kavramlar":["os-5-057","os-5-059","os-5-083","os-5-079","os-5-084"],"adimlar":[{"konuk":"Dün gece yan odadan sabaha kadar ses geldi! İki gece daha kalacağım, bu nasıl bir otel?","ingilizce":"There was noise from the next room almost until morning! I'm staying two more nights. What kind of hotel is this?","secenekler":[{"metin":"Bunu gece görevlisine söylemeniz gerekirdi efendim; ben o saatte burada değildim, bu benim bölümüm de değil.","puan":0,"tepki":"Konuk iyice yükselir: “Sizin bölümünüz, onun bölümü... ben tek bir otelde kalıyorum!” Şikâyeti alan kişi “bu benim işim değil” demez; sorunu sahiplenir."},{"metin":"Sizi rahatça dinleyebilmem için şöyle oturalım mı efendim? Ne olduğunu baştan anlatın.","ingilizce":"So that I can listen properly, shall we sit down here, sir? Please tell me what happened from the beginning.","puan":2,"tepki":"Konuk lobiden uzaklaşıp koltuğa oturur ve sesi düşer. Oturan konuk daha sakin olur, diğer konuklar da tartışmaya tanık olmaz (izolasyon tekniği)."},{"metin":"Hemen gece görevlisine soruyorum efendim, siz burada ayakta bekleyin.","puan":1,"tepki":"Konuk ayakta bekler ve öfkesi artar: “Önce beni dinleyin!” Harekete geçmek iyi, ama şikâyetçi konuk önce dinlenmek ister; çözüm dinlemeden sonra gelir."}]},{"konuk":"Saat ikiye kadar müzik, sonra kahkahalar. Hiç uyuyamadım; bugün de toplantım var.","ingilizce":"Music until two, then laughing. I didn't sleep at all, and I have a meeting today.","secenekler":[{"metin":"Özür dilerim ama dün otel tamamen doluydu, her şeyi kontrol etmek zordu.","puan":1,"tepki":"Konuk yüzünü ekşitir: “Dolu olması benim sorunum değil.” “Ama” ile devam eden özür, özür sayılmaz; savunma gibi duyulur."},{"metin":"Genelde burası çok sessizdir; belki biraz abartıyorsunuzdur.","puan":0,"tepki":"Konuk yeniden yükselir: “Yalan mı söylüyorum?” Konuğun yaşadığını küçümsemek öfkeyi büyütür; önce duygusunu görmek gerekir."},{"metin":"Uykusuz bir geceden sonra toplantıya gitmek çok zor, sizi anlıyorum. Çok özür dilerim; bize bildirdiğiniz için teşekkür ederim.","ingilizce":"Going to a meeting after a sleepless night is really hard; I understand. I'm very sorry, and thank you for telling us.","puan":2,"tepki":"Konuk omuzlarını bırakır: “Neyse ki biri anlıyor.” Anlaşıldığını hisseden konuk sakinleşir ve çözümü dinlemeye hazır olur."}]},{"konuk":"Özrünüzü duydum. Peki bu akşam ne olacak?","ingilizce":"I've heard your apology. But what will happen tonight?","secenekler":[{"metin":"Bu akşam sessiz olacak, sorun yaşamazsınız.","puan":0,"tepki":"Konuk şüpheyle bakar: “Nereden biliyorsunuz?” Henüz hiçbir şey yapmadan verilen söz boştur; güven, söylenenle değil yapılanla kurulur."},{"metin":"Güvenliği şimdi bilgilendiriyorum. İsterseniz arka tarafta sessiz bir oda da ayırabilirim; hangisini seçersiniz?","ingilizce":"I'm informing security right now. If you like, I can also arrange a quiet room at the back. Which would you choose?","puan":2,"tepki":"Konuk telefonun kaldırıldığını görür ve rahatlar: “İkinci seçenek iyi.” Çözüm hemen başlar ve karar konuğa bırakılır (çözüm üret, hemen yap)."},{"metin":"Konuyu müdürümüze iletirim, size akşama kadar mutlaka dönerler; o zamana kadar lütfen odanıza çıkıp biraz dinlenin.","puan":1,"tepki":"Konuk başını sallar ama memnun değildir: “Akşama kadar mı?” Amire aktarmak yanlış değil, ama konuğun gözü önünde atılan ilk adım eksik kaldı."}]},{"konuk":"Dün gece uyutmadılar. Bunun bir karşılığı olmayacak mı?","ingilizce":"They didn't let me sleep last night. Isn't there going to be any compensation for that?","secenekler":[{"metin":"Bu akşam yemek, spa, her şey bizden olsun. Müdüre sonra söylerim.","puan":0,"tepki":"Konuk sevinir, ama müdür bunu onaylamayabilir ve konuk daha çok kırılır. Ücretsiz ikrama personel kendi başına söz vermez; yetkisi yoksa amirine danışır."},{"metin":"Ücretsiz bir kahve ikram edeyim mi?","puan":1,"tepki":"Konuk gülümsemez: “Bir kahve mi?” Telafi, yaşanan sorunla orantılı olmalı; bütün bir gece uykusuz kalan konuğa küçük jest alay gibi algılanır."},{"metin":"Evet, bir telafi hak ettiniz. Ücretsiz akşam yemeği için müdürümüzün onayını şimdi alıyorum; onaylanırsa masanız hazır.","ingilizce":"Yes, you deserve some compensation. I'm asking our manager to approve a complimentary dinner right now; once approved, your table will be ready.","puan":2,"tepki":"Konuk yumuşar: “Bu çok incelik.” Telafi sorunla orantılıdır ve yetkinin ötesindeki ikram için amirden onay alınır."}]},{"konuk":"(Ertesi sabah, oda telefonunda.) Alo? Evet, benim. Beni aradığınıza şaşırdım.","ingilizce":"(Next morning, on the room phone.) Hello? Yes, speaking. I'm surprised you called.","secenekler":[{"metin":"Yalnızca kayıt için aradım efendim, işlemimiz tamam; sizi daha fazla meşgul etmeyeyim, iyi günler.","puan":1,"tepki":"Konuk teşekkür eder ama içten bir ilgi hissetmez. Arama yapıldı, ama konuğun memnun kalıp kalmadığı sorulmadı."},{"metin":"Bakalım yine şikâyet edecek bir şey çıkmış mı diye aramıştım; umarım bu sefer yoktur.","puan":0,"tepki":"Konuk telefonu soğuk bir sesle kapatır. Takip, memnuniyeti kontrol etmek içindir; konuğu yargılamak için değil."},{"metin":"Nasıl olduğunuzu merak ettik efendim. Gece sessiz geçti mi, başka bir isteğiniz var mı?","ingilizce":"We wanted to be sure everything is fine, sir. Was the night quiet? Is there anything else you need?","puan":2,"tepki":"Konuk sıcak bir sesle teşekkür eder: “Sağ olun, bu ilgiyi unutmam.” Geri aranan konuk önemsendiğini hisseder; takip, sorun çözmeyi gerçekten kapatan adımdır."}]}]},{"id":"os-d21","unite":5,"baslik":"Karar Veremeyen Konuk","rol":"Rezervasyon görevlisi","sahne":"Saat 10.30, rezervasyon masası. Telefondaki bir konuk hafta sonu için oda ayırtmak istiyor ama bir türlü karar veremiyor ve sürekli onay bekliyor. Görevli, konuğu hem acele ettirmeden hem de yormadan karara götürmek zorunda.","kavramlar":["os-5-040","os-5-041","os-5-012","os-5-029"],"adimlar":[{"konuk":"Hafta sonu için oda istiyorum ama deniz manzaralı mı alsam, sessiz bir oda mı, yoksa süit mi? Bilmiyorum, siz ne dersiniz?","ingilizce":"I'd like a room for the weekend, but should I take a sea view, a quiet room or a suite? I really don't know. What do you think?","secenekler":[{"metin":"Bu kadar düşünmeyin efendim, deniz manzaralıyı alın ve karar verin artık; hafta sonuna az kaldı, oda kalmayabilir.","puan":0,"tepki":"Konuk telaşlanır: “Ama emin değilim ki...” Acele ettirmek kararsız konuğu daha da kararsız yapar."},{"metin":"Sekiz oda tipimiz var; hepsini tek tek anlatayım mı?","puan":1,"tepki":"Konuk iç çeker: “Hepsini mi...” Çok seçenek konuğu rahatlatmaz, yorar; kararsız konuğa seçenekleri daraltmak gerekir."},{"metin":"Size yardımcı olayım. Önce bir sorum var: sizin için sessizlik mi, yoksa manzara mı daha önemli?","ingilizce":"Let me help you. First, may I ask: which matters more to you, peace and quiet or the view?","puan":2,"tepki":"Konuk biraz düşünür ve rahatlar: “İyi soru.” Önce bir iki soru sormak, seçenekleri daraltmanın ilk adımıdır."}]},{"konuk":"Biraz sessizlik isterim ama denizi de çok severim.","ingilizce":"I'd like some quiet, but I love the sea too.","secenekler":[{"metin":"İki oda önereyim: biri bahçe manzaralı ve sessiz, diğeri deniz manzaralı ve balkonlu.","ingilizce":"Let me suggest two rooms: a quiet garden-view room, and a sea-view room with a balcony.","puan":2,"tepki":"Konuk derin bir nefes alır: “Bu iki seçenek aklıma yattı.” Bütün listeyi saymak yerine ihtiyaca uygun iki seçenek sunmak kararı kolaylaştırır."},{"metin":"Her ikisi de çok güzel; bence sizin için fark etmez, hangisini seçerseniz seçin memnun kalırsınız.","puan":1,"tepki":"Konuk yine bocalar: “O zaman hangisi?” Konuğa yol göstermeyen, görüşünü söylemeyen personel kararsızlığı çözmez."},{"metin":"Süiti alın, hepsinin iyisi o; fiyat ne olursa olsun.","puan":0,"tepki":"Konuk endişelenir: “Fiyat mı? Bütçeme bakmadınız bile.” İhtiyacı dinlemeden en pahalıyı satmaya çalışmak güveni bozar."}]},{"konuk":"Bu iki odanın farkı ne? Hangisi daha iyi?","ingilizce":"What's the difference between the two? Which one is better?","secenekler":[{"metin":"Bahçe odasını yazıyorum, tamam mı? Başka seçeneğiniz yok, hafta sonu için sadece bunlar kaldı.","puan":0,"tepki":"Konuk şaşırır: “Yok mu? Az önce iki oda dediniz.” Konuğa yalan söylemek ve söz hakkı vermemek hem güveni hem satışı kaybettirir."},{"metin":"Karar sizin efendim, ben bir şey öneremem.","puan":1,"tepki":"Konuk çaresizce “Peki...” der. Son söz konuğundur, ama personel uzman görüşüyle nazikçe yol göstermelidir."},{"metin":"Dinlenmek istediğinizi söylediniz, bu yüzden bahçe odasını öneririm. Yine de karar sizin.","ingilizce":"You said you want to rest, so I would recommend the garden room. But the decision is yours.","puan":2,"tepki":"Konuk memnun: “Bana göre tam bu.” Uzman görüşü verilip son söz konuğa bırakıldığında kararsız konuk karar verebilir."}]},{"konuk":"Bahçe odası iyi. Ama ya sonra pişman olursam?","ingilizce":"The garden room sounds good. But what if I regret it later?","secenekler":[{"metin":"Tamam, o zaman bahçe odası olsun.","puan":1,"tepki":"Konuk “Evet...” der ama endişesi geçmez. Kaygıyı dinlemeden kaydı geçmek konuğu rahatlatmaz."},{"metin":"Odayı şimdi ayırıyorum. Değişiklik koşullarını size şimdi söyleyeyim; müsaitlik olursa değiştirebiliriz.","ingilizce":"I'll reserve the room now. Let me tell you the change conditions now; if there is availability, we can change it.","puan":2,"tepki":"Konuk rahatlar: “Böyle olunca daha rahatım.” Endişe görüldü; değişiklik koşulları baştan söylenip gerçekçi bir çıkış yolu gösterildiği için karar vermek kolaylaştı."},{"metin":"Pişman olmazsınız, bundan eminim; bu otelde kimse bugüne kadar kararından pişman olmadı.","puan":0,"tepki":"Konuk şüphelenir: “Bunu nasıl bilebilirsiniz?” Kimsenin bilemeyeceği bir şeyi kesinmiş gibi söylemek doğru bilgi vermek değildir."}]},{"konuk":"Peki, bahçe odası olsun. Teşekkürler, beni hiç acele ettirmediniz.","ingilizce":"Fine, the garden room then. Thank you for not rushing me.","secenekler":[{"metin":"Herkes biraz kararsız olur, ama siz biraz fazlaydınız.","puan":0,"tepki":"Konuk kırılır ve sesi soğur. Konuğun bir özelliğiyle alay etmek, iyi geçmiş bir konuşmayı bozar."},{"metin":"Rica ederim efendim. Sessiz oda tercihinizi kayda alıyorum; bir sonraki gelişinizde de sessiz bir oda ayırmaya özen göstereceğiz.","ingilizce":"You're welcome. I'm noting your preference for a quiet room, so we'll do our best to reserve one on your next stay too.","puan":2,"tepki":"Konuk gülümser: “Beni tanıyor olmanız çok güzel.” Tercihin kayda geçmesi aynı sorunun tekrarını önler ve kişiselleştirilmiş hizmet sağlar."},{"metin":"Rica ederim, onayınız e-postanıza gidecek. İyi günler.","puan":1,"tepki":"Konuk teşekkür eder, ama özel bir ilgi görmemiştir. Nezaket tamam, kişiselleştirme eksik."}]}]},{"id":"os-d22","unite":5,"baslik":"Ünlü Konuğun Karşılanması","rol":"Konuk ilişkileri görevlisi","sahne":"Saat 17.00. Tanınmış bir sanatçı, yarım saat içinde otele gelecek; odası önceden kontrol edilmiş ve konuk tercih kaydı hazırlanmış. Konuk ilişkileri görevlisi hem karşılamayı hem de sanatçıyı arayan meraklıları yönetmek zorunda.","kavramlar":["os-5-022","os-5-027","os-5-028","os-5-029"],"adimlar":[{"konuk":"(Telefondaki arayan.) Merhaba, sanatçı Deniz Aytuna bu akşam sizde kalacak, doğru mu? Hangi odada kalıyor?","ingilizce":"(A caller on the phone.) Hello, is the performer Deniz Aytuna staying with you tonight? Which room is she in?","secenekler":[{"metin":"Evet, kalıyor ama oda numarasını söyleyemem; isterseniz bir mesaj bırakın, kendisine iletirim.","puan":0,"tepki":"Arayan “Demek ki buradaymış!” diyerek telefonu kapatır. Konuğun otelde kaldığını doğrulamak da gizlilik ihlalidir."},{"metin":"Konuklarımızla ilgili bilgi veremiyorum efendim. Size başka nasıl yardımcı olabilirim?","ingilizce":"I'm afraid I can't give any information about our guests. How else may I help you?","puan":2,"tepki":"Arayan teşekkür edip başka bir konuda soru sorar. Konuk gizliliği her konuğun hakkıdır ve VIP konuğun ilk beklentisidir."},{"metin":"Bu konuda bilgi veremem.","puan":1,"tepki":"Arayan bir şey demeden kapatır. Gizlilik korundu, ama ses soğuktu; nazik bir cümleyle başka yardım önerilebilirdi."}]},{"konuk":"(Sanatçı.) İyi akşamlar. Rezervasyonum Deniz Aytuna adına.","ingilizce":"(The performer.) Good evening. I have a reservation under Deniz Aytuna.","secenekler":[{"metin":"Aaa, sizi tanıdım, hayranınızım! Bir fotoğraf çekebilir miyiz?","puan":0,"tepki":"Konuğun yüzü ciddileşir. Konuğun fotoğrafı çekilmez ve ona hayran gibi davranılmaz; gizlilik ve profesyonel mesafe korunur."},{"metin":"Hoş geldiniz efendim, önümüzdeki konukla işim bitince hemen sizinle ilgilenip kaydınızı yapacağım, lütfen şurada bekleyin.","puan":1,"tepki":"Konuk lobide beklemek zorunda kalır ve gözler ona dönmeye başlar. VIP konuk bankoda bekletilmez."},{"metin":"Hoş geldiniz Deniz Hanım. Odanız hazır; kaydınızı odanızda tamamlayalım, sizi lobide bekletmeyelim.","ingilizce":"Welcome, Ms Aytuna. Your room is ready. We can complete your registration in your room, so you needn't wait here.","puan":2,"tepki":"Konuk rahatlar: “Çok düşüncelisiniz.” VIP konuk bekletilmez; kaydı odasında tamamlanır ve hazırlık konuk gelmeden biter."}]},{"konuk":"Geçen gelişimde kuş tüyü yastık yüzünden uyuyamamıştım.","ingilizce":"Last time I couldn't sleep because of the feather pillow.","secenekler":[{"metin":"Öyle mi? Bizim kayıtlarda böyle bir şey yok, herhalde yanlış hatırlıyorsunuzdur; yastıklarımız hep aynı.","puan":0,"tepki":"Konuk kaşlarını çatar. Kayda bakmadan konuğu yalanlamak hem hatadır hem kabalıktır."},{"metin":"Üzgünüm. İsterseniz yastığı odaya çıkınca değiştirebiliriz.","puan":1,"tepki":"Konuk “Peki” der ama güvenmez. Tercih kayda bakılarak önceden karşılanmadı; sorun konuk söyledikten sonra çözülüyor, oysa kayıt bunu önlemek için tutulur."},{"metin":"Notunuz kaydımızda var; odanıza tüy olmayan yastıklar hazırladık. Başka bir tercihiniz olursa söyleyin.","ingilizce":"It's in your guest history, so we've prepared feather-free pillows in your room. If you have any other preference, please let us know.","puan":2,"tepki":"Konuk gülümser: “Hatırlamanız çok hoş.” Tercih kaydı sayesinde istek, konuk söylemeden karşılanır (beklenti oluşmadan sunma)."}]},{"konuk":"Lobide birkaç kişi bekliyor, fotoğraf çekmek istiyorlar. Beni asansöre kadar götürebilir misiniz?","ingilizce":"A few people in the lobby want to take photos. Could you take me to the lift?","secenekler":[{"metin":"Hayranlarınıza biraz zaman ayırsanız ne olur, hepsi sizi görmek için saatlerdir bekliyor.","puan":0,"tepki":"Konuk yorgun bir sesle “Hayır” der. Konuğun gizlilik ve rahat isteğine karşı çıkmak, VIP hizmetin tersidir."},{"metin":"Elbette, size asansöre kadar ben eşlik edeyim; güvenliği de şimdi arıyorum.","ingilizce":"Of course. I'll walk you to the lift myself, and I'm calling security now.","puan":2,"tepki":"Konuk teşekkür eder ve rahatça asansöre ulaşır. Konuğun gizlilik isteğine hemen cevap verilir; kalabalığı yönetmek güvenliğin işidir."},{"metin":"Asansör şurada efendim, kendiniz gidebilirsiniz.","puan":1,"tepki":"Konuk kalabalığın arasından tek başına geçer. Sorun çözülmedi; konuk yalnız bırakıldı."}]},{"konuk":"Teşekkürler, çok rahat bir karşılamaydı.","ingilizce":"Thank you, that was a very smooth welcome.","secenekler":[{"metin":"Arkadaşlarıma da anlatacağım, bu gece bizde kaldığınızı! Hepsi çok heyecanlanacak, belki fotoğrafınızı da paylaşırım.","puan":0,"tepki":"Konuğun ifadesi sertleşir. Konuğun otelde kaldığı kimseyle konuşulmaz; sır tutmak görevdir."},{"metin":"Sağ olun, iyi geceler.","puan":1,"tepki":"Konuk bir şey demeden asansöre biner. Nezaket var, ama içten bir ilgi ve veda cümlesi eksik."},{"metin":"Rica ederiz Deniz Hanım. Bir ihtiyacınız olursa resepsiyon bir telefon uzaklığında.","ingilizce":"You're welcome, Ms Aytuna. We're only a phone call away if you need anything.","puan":2,"tepki":"Konuk gülümseyerek asansöre biner: “Teşekkürler.” Hizmetin sonu kısa ve içten bir cümleyle kapanır."}]}]},{"id":"os-d23","unite":5,"baslik":"Erişilebilir Oda İsteği","rol":"Resepsiyonist","sahne":"Saat 15.00, resepsiyon. Tekerlekli sandalye kullanan bir konuk, eşiyle birlikte giriş yapmaya geliyor. Rezervasyonunda erişilebilir oda istemiş, ama sistemde dördüncü kattan bir oda görünüyor.","kavramlar":["os-5-015","os-5-016","os-5-017","os-5-018","os-5-019"],"adimlar":[{"konuk":"İyi günler. Rezervasyon yaptırırken erişilebilir oda istemiştim ama sistemde dördüncü kat görünüyor.","ingilizce":"Good afternoon. I asked for an accessible room when I booked, but it says fourth floor on your system.","secenekler":[{"metin":"Asansör var, dördüncü kat da olur; banyoda gerekirse eşiniz yardım eder. Çoğu konuk dördüncü katta çok rahat ediyor.","puan":0,"tepki":"Konuk bozulur: “Yardıma mecbur kalmak istemiyorum.” Bağımsız hareket edebilme, engelli konuğun en önemli beklentisidir."},{"metin":"Hemen bakıyorum efendim. Zemin katta, geniş kapılı ve banyosunda tutunma barı olan odamızı sizin için ayırıyorum.","ingilizce":"Let me check right away, sir. I'm reserving our ground-floor room with a wide door and a grab bar in the bathroom for you.","puan":2,"tepki":"Konuk rahatlar: “Tam aradığım buydu.” Erişilebilir oda geniş geçiş, tutunma barı ve uygun banyoyla konuğun başkasına bağımlı kalmadan konaklamasını sağlar."},{"metin":"Bilmiyorum, tesisimizde öyle bir oda var mı, müdüre sorayım.","puan":1,"tepki":"Konuk bekler ve içinden “Bu otelde benim düşünülmediğimi hissediyorum” der. Personel tesisin erişilebilir imkânlarını bilmelidir."}]},{"konuk":"Teşekkürler. Restoran ve diğer alanlar da bana uygun mu? Kahvaltıya kendim inmek isterim.","ingilizce":"Thank you. Are the restaurant and other areas accessible too? I'd like to go to breakfast on my own.","secenekler":[{"metin":"Bilmiyorum, ben restorana pek girmem; orada bir sorarsınız.","puan":0,"tepki":"Konuk şaşkınlıkla bakar. Tesisin erişilebilirliğini bilmemek, konuğa “burada düşünülmedin” demektir."},{"metin":"Evet, uygun diye biliyorum; yine de kahvaltıda garsonlar size yardım eder.","puan":1,"tepki":"Konuk emin olamaz. “Diye biliyorum” diyen personel güven vermez; üstelik konuk kendi başına yapmak istiyor, yardım ise dayatılıyor."},{"metin":"Evet efendim, girişte rampa, restoranda da sandalyenizin geçeceği genişlikte masa aralığı var. Kahvaltıya kendiniz inebilirsiniz.","ingilizce":"Yes, sir, there is a ramp at the entrance, and the restaurant tables are spaced wide enough for a wheelchair. You can go down to breakfast on your own.","puan":2,"tepki":"Konuk gülümser: “Mükemmel.” Erişilebilir tesis, konuğun her yere kendi başına gitmesini sağlar."}]},{"konuk":"Bu giriş kapısı biraz ağır geldi ama halledeceğim.","ingilizce":"This entrance door is a bit heavy, but I'll manage.","secenekler":[{"metin":"Durun, ben sizi iterim, kapıdan geçelim, vakit kaybetmeyelim!","puan":0,"tepki":"Konuk sandalyesinin kolunu sertçe tutar: “Lütfen dokunmayın!” Sormadan yapılan yardım konuğu ürkütebilir; sandalye konuğun kişisel alanıdır."},{"metin":"Kapıyı tutabilirim, isterseniz. Yardım istemezseniz de buradayım.","ingilizce":"I can hold the door for you if you like. If not, I'm right here.","puan":2,"tepki":"Konuk gülümseyerek “Evet, kapıyı tutarsanız sevinirim” der. Yardım etmeden önce sormak saygıdır; karar konuğundadır."},{"metin":"Siz bilirsiniz efendim, ben şu an biraz yoğunum; yardım gerekirse söylersiniz.","puan":1,"tepki":"Konuk kapıyla uğraşırken görevli izlemeyi sürdürür. Yardım teklif edilmedi; ihtiyacı fark etmek ve sormak gerekirdi."}]},{"konuk":"Odanın düzenini ilk gün ezberliyorum. Her şey yerinde kalırsa çok sevinirim.","ingilizce":"I memorise the room layout on the first day, so I'd be very glad if everything stays where it is.","secenekler":[{"metin":"Odanın düzeni bizim standartlarımıza göre ayarlanır, eşyaların yeri de buna göre belirlenir; her konuk için ayrı düzen kurmamız mümkün değil.","puan":0,"tepki":"Konuk geri çekilir: “Anlıyorum, benim ihtiyacım pek önemli değil.” Erişilebilir odada eşyaların yeri rastgele değiştirilmez."},{"metin":"Not alıyorum efendim; kat ekibimiz odada hiçbir şeyin yerini değiştirmeyecek. İhtiyacınız olursa resepsiyona haber verin.","ingilizce":"I'll make a note of that, sir. Our housekeeping team won't move anything in your room. Just let reception know if you need anything.","puan":2,"tepki":"Konuk memnun: “Teşekkür ederim, çok önemliydi.” Konuk odayı ezberine göre kullanır; bu yüzden düzen korunur ve kat ekibine haber verilir."},{"metin":"Elimden geleni yaparım ama kat görevlisi toplarken eşyanın yerini değiştirebilir.","puan":1,"tepki":"Konuk endişeyle başını sallar. İhtiyaç kat ekibine iletilmedi; oysa erişilebilir odada eşyaların yeri kimse tarafından rastgele değiştirilmemeli."}]},{"konuk":"Teşekkür ederim, çok anlayışlısınız. Sanırım odama çıkabilirim.","ingilizce":"Thank you, you've been very understanding. I think I can go up to my room now.","secenekler":[{"metin":"Tamam, odanız zemin katta; kendiniz bulursunuz, ben başka konuğa bakmalıyım.","puan":0,"tepki":"Konuk yalnız bırakılmış hisseder. Erişilebilir odadaki konuk yönlendirilmeden bırakılmaz; veda ve yardım teklifi olmadan geçiştirmek güveni bozar."},{"metin":"Rica ederim efendim, iyi günler dilerim; bir şeye ihtiyacınız olursa bizi bulursunuz.","puan":1,"tepki":"Konuk nezaketle ayrılır. Veda nazik ama genel; bagaja yardım teklif edilmedi ve kime nasıl ulaşacağı söylenmedi."},{"metin":"Rica ederim efendim. İsterseniz bagajınıza bellboyumuz eşlik etsin; iyi konaklamalar dilerim.","ingilizce":"You're welcome, sir. If you like, our porter can help with your luggage; enjoy your stay.","puan":2,"tepki":"Konuk gülümseyerek odasına yönelir. Yardım dayatılmadan, sorularak teklif edildi ve içten bir dilekle veda edildi; konuk otele güvenle başlar."}]}]},{"id":"os-d24","unite":5,"baslik":"Lobide Fenalaşan Konuk","rol":"Resepsiyonist","sahne":"Saat 11.00, lobi. Yaşlı bir konuk koltukta oturuyor; göğsünü tutuyor ve sol kolunun uyuştuğunu söylüyor. Biraz sonra konuğun eşi de yanına koşuyor. Resepsiyonist, ne yapacağına hızla karar vermek zorunda.","kavramlar":["os-5-131","os-5-132","os-5-133","os-5-134","os-5-122"],"adimlar":[{"konuk":"Kendimi iyi hissetmiyorum... Göğsümde bir baskı var, kolum da uyuşuyor.","ingilizce":"I don't feel well... There's pressure in my chest and my arm is going numb.","secenekler":[{"metin":"Belki yorgunluktandır; çantamda baş ağrısı için bir ilaç var, isterseniz size vereyim, geçer.","puan":0,"tepki":"Konuğun durumu kötüleşir. Personel teşhis koymaz, kendi kararıyla ilaç vermez; göğüs baskısı ve kolda uyuşma acil belirtidir."},{"metin":"112’yi ve sağlık ekibimizi arıyorum, nöbetçi müdüre de haber veriyorum. Oturmaya devam edin.","ingilizce":"I'm calling 112 and our medical team, and informing the duty manager. Please keep sitting.","puan":2,"tepki":"Konuk derin bir nefes alır: “Teşekkür ederim.” Göğüs baskısı ve kolda uyuşma acil belirtilerdendir; vakit kaybetmeden 112 ve sağlık ekibi aranır, yöneticiye haber verilir."},{"metin":"112’yi arıyorum, siz oturun.","puan":1,"tepki":"Konuk oturur, ambulans yola çıkar. 112 doğru; ama otelin sağlık ekibi ve nöbetçi müdür aranmadığı için ambulans gelene kadar konuğun yanında eğitimli kimse yok, yönetim de haberdar değil."}]},{"konuk":"Ambulans gelecek mi? Ne kadar sürer?","ingilizce":"Is an ambulance coming? How long will it take?","secenekler":[{"metin":"Beş dakikada burada olurlar; ben de sizinle burada bekleyeceğim, korkmayın.","puan":0,"tepki":"Beş dakika geçer, ambulans gelmez; konuk paniğe kapılır. Bilinmeyen bir süre için söz verilmez."},{"metin":"Gelecek efendim ama ne zaman geleceğini bilmiyorum.","puan":1,"tepki":"Konuk daha da endişelenir. Dürüst, ama sakinleştirici ve yönlendirici bir cümle eksik."},{"metin":"Ambulans yola çıkıyor, efendim. Bir arkadaşım kapıda ekibi karşılayıp en kısa yoldan size getirecek.","ingilizce":"An ambulance is on its way, sir. A colleague will meet the crew at the entrance and bring them straight to you.","puan":2,"tepki":"Konuk biraz sakinleşir. Ambulansı kapıda bir personelin karşılaması dakikalar kazandırır."}]},{"konuk":"Kocam hastalandı! Kalp ilacını çantasında taşıyor, ona vereyim mi?","ingilizce":"My husband is ill! He carries heart medicine in his bag. Should I give it to him?","secenekler":[{"metin":"İlacı ben bilemem; sağlık ekibi gelince onlara sorun.","puan":1,"tepki":"Eşi bekler. Personelin ilaç kararı vermemesi doğru; ama 112 ve sağlık ekibinin çağrıldığını söyleyip onu sakinleştirmek de gerekirdi."},{"metin":"Evet, hemen verin; kalp ilacıdır, zararı olmaz, ne kadar çabuk verirseniz o kadar iyi olur.","puan":0,"tepki":"Konuğun durumu kötüleşebilir. Personel kendi kararıyla ilaç verdirmez ya da tavsiye etmez; ilaç kararını sağlık ekibi verir."},{"metin":"Önce 112 ve sağlık ekibimizle konuşalım, onlar yönlendirecek. Ben şimdi ekibi çağırıyorum.","ingilizce":"Let's check with 112 and our medical team first; they will guide us. I'm calling the team now.","puan":2,"tepki":"Eşi derin bir nefes alır: “Tamam.” Sağlık ekibine en hızlı biçimde ulaşılır ve onların talimatıyla hareket edilir."}]},{"konuk":"Lobideki herkes bize bakıyor, çok utanıyorum.","ingilizce":"Everyone in the lobby is staring at us. I feel very embarrassed.","secenekler":[{"metin":"Arkadaşlar, dikkat! Bu beyefendi aniden hastalandı, kalp krizi olabilir, lütfen herkes yaklaşmasın! Yer açın!","puan":0,"tepki":"Konuk iyice bunalır, lobi kalabalıklaşır. Konuğun durumu başka konuklarla konuşulmaz ve yüksek sesle ilan edilmez."},{"metin":"Aldırmayın, insanlar meraklıdır.","puan":1,"tepki":"Konuk sessizce “Evet...” der. Duygusu görülmedi; çevreyi boşaltmak ve özen göstermek gerekirdi."},{"metin":"Çevreyi hemen boşaltıyoruz, mahremiyetinize özen göstereceğiz. Durumu diğer konuklarla konuşmayacağız.","ingilizce":"We're clearing the area right now to protect your privacy. We won't discuss this with other guests.","puan":2,"tepki":"Konuk teşekkür eder; lobi sakinleşir. Fenalaşan konuğun çevresi boşaltılır ve durum başkalarıyla konuşulmaz."}]},{"konuk":"Hastaneye gidiyoruz. Odamızdaki eşyalarımız ne olacak?","ingilizce":"We're going to the hospital. What will happen to our things in the room?","secenekler":[{"metin":"Geçmiş olsun, her şey odada duruyor, hastaneden döndüğünüzde bütün ayrıntıları rahatça konuşuruz, şimdi önce eşinize bakın.","puan":1,"tepki":"Konuğun eşi başını sallar ama içi rahat değildir. Nezaket var, ama yönetimin ileteceği bilgi ve olay kaydı belirtilmedi."},{"metin":"Eşyalar için sorumluluk kabul edemeyiz; kasayı kullanmalıydınız.","puan":0,"tepki":"Konuğun eşi gözyaşlarını tutamaz. Sağlık krizinde kimse kınanmaz; konuğun yanında olmak gerekir."},{"metin":"Eşyalarınız odada güvende; olayı tutanağa yazıyorum, nöbetçi müdürümüz sizi arayacak. Geçmiş olsun.","ingilizce":"Your belongings are safe in the room; I'm recording the incident, and our duty manager will call you. We wish him a speedy recovery.","puan":2,"tepki":"Eşi teşekkür eder: “Sizin sayenizde dakikalar kazanıldı.” Olay, tarih, saat ve yapılanlarla birlikte yorum katılmadan kayda geçer; yönetim konuğu takip eder."}]}]},{"id":"os-d25","unite":5,"baslik":"Yangın Alarmı","rol":"Kat görevlisi","sahne":"Saat 15.00, ikinci kat koridoru. Genel alarm çalıyor ve konuklar odalarından telaşla çıkıyor. Kat görevlisi, yangın protokolüne göre konuklara sakin bir sesle yol göstermek zorunda.","kavramlar":["os-5-154","os-5-156","os-5-162","os-5-113","os-5-161"],"adimlar":[{"konuk":"Alarm çalıyor! Asansörle inelim, çabuk!","ingilizce":"The alarm's going off! Let's take the lift, quickly!","secenekler":[{"metin":"Tamam, asansör boş görünüyor, hemen binin.","puan":0,"tepki":"Asansör kapanır ve konuk katlar arasında kalma riskine girer. Yangında asansör kullanılmaz; kuyusuna duman dolabilir."},{"metin":"Asansör kullanılmaz efendim, lütfen kendiniz merdivenden inin; ben diğer odalara bakmalıyım.","puan":1,"tepki":"Konuk ne yapacağını bilemeden duraksar. Kural doğru, ama yol gösterilmedi; panikteki konuğa kısa cümleyle ve eşlik ederek yön verilir."},{"metin":"Lütfen merdiveni kullanalım, bu taraftan. Yürüyerek ineceğiz.","ingilizce":"Please let's use the stairs, this way. We'll walk down.","puan":2,"tepki":"Konuk sakinleşir ve görevlinin peşinden merdivene yönelir. Alışkanlıkla asansöre giden konuk merdivene yönlendirilir; kısa, net cümleler paniği azaltır."}]},{"konuk":"Pasaportum ve bavulum odada! Hemen alıp geleyim!","ingilizce":"My passport and suitcase are in the room! Let me grab them quickly!","secenekler":[{"metin":"Çabuk olun, bir dakikada çıkın; ben burada bekliyorum, pasaportsuz yolculuk zor olur.","puan":0,"tepki":"Konuk koşarak odaya girer ve koridora duman dolmaya başlar. Eşya için geri dönülmez; can her şeyden önce gelir."},{"metin":"Lütfen geri dönmeyelim efendim; eşyalar sonra alınır, can öncelikli. Hadi birlikte yürüyelim.","ingilizce":"Please don't go back, sir. Your belongings can be collected later; your safety comes first. Let's walk together.","puan":2,"tepki":"Konuk bir an duraksar, sonra görevlinin yanından yürür. Unutulan eşya için binaya geri girilmez; önce insan gelir."},{"metin":"Geri dönmeyin efendim, lütfen yürüyelim.","puan":1,"tepki":"Konuk duraksar ve yürür. Yön doğru; ama nedeni (eşya için binaya geri girilmez, duman hızla yayılır) söylenmediği ve konuğa eşlik edilmediği için ikna gücü zayıf."}]},{"konuk":"Ben tekerlekli sandalye kullanıyorum, merdiveni kendi başıma inemem. Ne yapacağım?","ingilizce":"I use a wheelchair, so I can't manage the stairs on my own. What should I do?","secenekler":[{"metin":"Maalesef yapabileceğim bir şey yok, ben diğer konuklara bakmalıyım.","puan":0,"tepki":"Konuk koridorda yalnız kalır. Hareket kabiliyeti kısıtlı kişiler önce kurtarılır; onları yalnız bırakmak yangın protokolüne aykırıdır."},{"metin":"Size yardımcı olabilir miyim? Sizi merdiven sahanlığına alıp yanınızda kalacağım, yerinizi itfaiyeye bildiriyorum.","ingilizce":"May I help you? I'm taking you to the stairwell landing and staying with you, and I'm reporting your location to the fire brigade.","puan":2,"tepki":"Konuk başını sallar: “Evet, lütfen.” Hareket kabiliyeti kısıtlı konuk önce güvenli bölgeye alınır, yeri hemen bildirilir; dumanın içine girilmez."},{"metin":"Siz burada bekleyin, ben hemen aşağı inip yardım çağırayım; birileri gelip sizi alacaktır, sakin kalın.","puan":1,"tepki":"Konuk duman gelen koridorda yalnız bekler. Yardım çağırmak doğru, ama konuğu dumandan uzağa alıp yanında kalmak gerekirdi."}]},{"konuk":"Odamın kapısını açık mı bırakayım, kilitleyeyim mi?","ingilizce":"Should I leave my room door open or lock it?","secenekler":[{"metin":"Kapıyı kapatın, hadi gidelim.","puan":1,"tepki":"Konuk kapıyı kapatır. Doğru; ama “kilitlemeyin” uyarısı eksik kaldı: kilitli kapı itfaiyenin girişini geciktirir, konuk bunu bilmeden kilitleyebilir."},{"metin":"Kilitleyin, eşyalarınız güvende olsun.","puan":0,"tepki":"Kilitli kapı hem içeride kalan birini hapseder hem itfaiyenin odaya girişini geciktirir. Kapılar kapatılır, ama kilitlenmez."},{"metin":"Kapıyı arkanızdan kapatın ama kilitlemeyin; sonra merdivene ilerleyelim.","ingilizce":"Close the door behind you but don't lock it. Then let's head for the stairs.","puan":2,"tepki":"Konuk kapıyı çeker ve yürümeye devam eder. Kapalı kapı dumanın yayılmasını yavaşlatır; kilitsiz kapı kurtarma ekiplerini geciktirmez."}]},{"konuk":"Bahçeye geldik. Şimdi odaya dönebilir miyiz?","ingilizce":"We're in the garden now. Can we go back to our rooms?","secenekler":[{"metin":"Henüz değil efendim; toplanma alanında bekleyelim. Ön büro sayım yapıyor; itfaiye uygun bulunca size haber vereceğiz.","ingilizce":"Not yet, sir. Let's wait at the assembly point while reception does a head count. We'll tell you as soon as the fire brigade says it's safe.","puan":2,"tepki":"Konuk anlayışla başını sallar. Toplanma alanına gelen kişi izin verilmeden binaya dönmez; sayım eksik kişiyi hemen gösterir."},{"metin":"Bilmiyorum, itfaiyeden haber bekleyin diyebilirim ama emin değilim; kendiniz karar verin.","puan":1,"tepki":"Konuk kararsız kalır. Yetkili ekip izin vermeden dönülmez; personel net bir yönlendirme yapmalıdır."},{"metin":"Evet, yangın küçükmüş, dönebilirsiniz.","puan":0,"tepki":"Konuk binaya yönelir ve sayım bozulur. Doğrulanmamış bilgi paylaşılmaz; yangını bitmiş ilan etme yetkisi personelde değildir."}]}]},{"id":"os-d26","unite":5,"baslik":"Kaybolan Telefon","rol":"Kat şefi","sahne":"Saat 16.00, kat ofisi. Resepsiyon, telefonunu bulamayan bir konuğu kayıp eşya sorumlusu olan kat şefine yönlendiriyor. Konuk hem endişeli hem de eşyasının çalındığından şüpheleniyor.","kavramlar":["os-5-140","os-5-141","os-5-142","os-5-138"],"adimlar":[{"konuk":"Telefonum kayboldu! Odada bırakmıştım, kesin biri almış!","ingilizce":"My phone is missing! I left it in the room, someone must have taken it!","secenekler":[{"metin":"Kayıp eşya defterine bakayım.","puan":1,"tepki":"Konuk bekler ama endişesi sürer: “Neye bakacaksınız, daha tarif etmedim bile.” Önce konuğu dinleyip eşyanın tarifini almak gerekir."},{"metin":"Odanıza girenler arasında temizlik görevlisi de vardı; belki o almıştır, hemen çağırtıp ona sorabiliriz.","puan":0,"tepki":"Konuk “Demek ki o aldı!” der ve olay büyür. Kimse peşinen suçlanmaz; kaybolan her eşya çalınmış değildir."},{"metin":"Sakin olun lütfen, birlikte bulacağız. Telefonun rengini ve en son nerede gördüğünüzü söyler misiniz?","ingilizce":"Please stay calm, we'll look into it together. Could you tell me the colour of your phone and where you last saw it?","puan":2,"tepki":"Konuk derin bir nefes alır. Görevli konuğu dinler, eşyanın tarifini ve en son görüldüğü yeri not alır."}]},{"konuk":"Siyah, koruyucu kılıflı. Dün gece restoranda masada gördüm, sonra odama çıktım.","ingilizce":"It's black, with a protective case. I last saw it on the restaurant table last night, then went up to my room.","secenekler":[{"metin":"Restoranı hemen arayayım, büyük ihtimalle orada kalmıştır; bulamazsak odanıza dönüp birlikte tekrar bakarız, sonra bir şekilde çözeriz.","puan":1,"tepki":"Konuk umutlanır, ama tek yere bakıldı. Kayıtlar, kat ve restoran ekibi birlikte kontrol edilmeli; bildirim güvenliğe ve amire de gitmeli."},{"metin":"Notlarımı aldım. Kayıtlara bakıyorum, restoran ve kat ekibine soruyorum; güvenliğe ve amirime de haber veriyorum.","ingilizce":"I've noted all that. I'm checking the records and asking the restaurant and housekeeping teams. I'm also informing security and my manager.","puan":2,"tepki":"Konuk rahatlar: “Demek her yere bakıyorsunuz.” Bulunan eşya kayıtları ve ilgili bölümler birlikte kontrol edilir, amir ve güvenlik bilgilendirilir."},{"metin":"Telefonunuz bulunur, ben bu işi yıllardır yapıyorum; bugüne kadar bulunmayan eşya çıkmadı.","puan":0,"tepki":"Konuk bir saat sonra “Hani bulunacaktı?” diye gelir. Kesin sonuçlanacak bir şey için söz verilmez; “Bulunur.” demek güveni zedeler."}]},{"konuk":"Bence çalındı. Polisi çağırmalı mıyız?","ingilizce":"I think it was stolen. Should we call the police?","secenekler":[{"metin":"Polis çağırırsak otelin adı kötüye çıkar, diğer konuklar da rahatsız olur; bence telefonu başka yerde unuttunuz, konuyu burada kapatalım.","puan":0,"tepki":"Konuk yanıtlanmadığını hisseder ve sinirlenir. Konuğu şikâyetten caydırmak dürüst değildir; şüphe varsa süreç yetkililerce yürütülür."},{"metin":"Çoğu zaman eşya unutulmuş ya da yerinden oynamış olur; önce arayalım. Şüpheniz sürerse güvenlik müdürümüz ve yönetim devreye girer.","ingilizce":"Most of the time, items have simply been left behind or misplaced, so let's search first. If you still suspect theft, our security manager and management will step in.","puan":2,"tepki":"Konuk anlar: “Mantıklı.” Her kayıp çalıntı değildir; şüphe sürerse hırsızlık adımları yetkililerce yürütülür, kimse peşinen suçlanmaz."},{"metin":"Hemen polisi arıyorum.","puan":1,"tepki":"Konuk şaşırır: “Bu kadar çabuk mu?” Acele edildi; önce olay yeri korunur, güvenlik müdürüne ve yönetime haber verilir, ardından kolluk kuvvetleri çağrılır."}]},{"konuk":"Telefon bulunmuş dediler. Ne zaman alabilirim?","ingilizce":"I was told the phone has been found. When can I collect it?","secenekler":[{"metin":"Bulunan eşyayı kim isterse veririz, tarif de sormayız, kimlik de; tek tek uğraşmak zaman kaybıdır.","puan":0,"tepki":"Başka biri telefonu almaya kalkabilir. Teslimde tarif kayıtla eşleştirilir, konuğun kendisi olduğu doğrulanır ve teslim bilgisi kayda geçer."},{"metin":"Hemen alabilirsiniz. Teslimden önce tarifi kayıtla eşleştirip kimliğinizi kayıttaki oda ve adla doğrulayacağım; teslimi deftere yazarız.","ingilizce":"You can collect it right away. Before handing it over, I'll match your description with the log and verify your identity against the room and name on record; then we'll log the handover.","puan":2,"tepki":"Konuk tarifi anlatır, adı ve odası kayıtla eşleşince telefonunu alır: “Çok teşekkürler.” Tarif kayıtla eşleştirilir, konuğun kendisi olduğu kayıttaki oda ve adla doğrulanır, teslim deftere yazılır."},{"metin":"Evet, hemen alabilirsiniz, buyurun.","puan":1,"tepki":"Konuk telefonunu alır, ama ne tarif sorulmuş ne kayıt tutulmuş. Teslim kayıtsız ve doğrulamasız yapılırsa kayıp eşya sistemi bir işe yaramaz."}]},{"konuk":"Peki çıkışta bir şeyimi unutursam bana nasıl ulaşırsınız?","ingilizce":"And if I forget something at check-out, how would you reach me?","secenekler":[{"metin":"Unutulan eşyalar bir hafta sonra atılır; o yüzden çıkarken odanızı iyice kontrol etmenizi öneririm, bir daha bakmayız, kimseye de haber vermeyiz.","puan":0,"tepki":"Konuk telaşlanır: “Bir hafta mı?” Yanlış bilgidir; bulunan eşya genellikle 90 gün saklanır ve işletmenin prosedürüne göre işlem yapılır."},{"metin":"Eşyayı kayda alıp rezervasyonunuzdaki bilgilerden size ulaşırız. Genellikle 90 güne kadar saklanır; kesin süre prosedüre bağlıdır.","ingilizce":"We would log it and contact you using your reservation details. Items are usually kept for up to 90 days, but the exact period depends on our procedure.","puan":2,"tepki":"Konuk rahatlar. Çıkış yapmış konuğa rezervasyon ve iletişim bilgilerinden haber verilir; muhafaza süresi genellikle 90 gündür."},{"metin":"Kayıt tutarız ama size ulaşabilir miyiz bilmem.","puan":1,"tepki":"Konuk emin olamaz. Çıkış yapmış konuğa rezervasyon ve iletişim bilgilerinden ulaşılır; bu bilgiyi vermek konuğu rahatlatırdı."}]},{"konuk":"Anladım. Yardımınız için teşekkürler, içim rahatladı.","ingilizce":"I see. Thank you for your help, I feel much better.","secenekler":[{"metin":"Rica ederim. Bir dahaki sefere eşyalarınıza dikkat edin, her zaman bu kadar şanslı olunmuyor.","puan":0,"tepki":"Konuk bozulur. Veda sitemle bitti; konuğa ders vermek yerine yardım edilir ve güvenle uğurlanır."},{"metin":"Rica ederim, iyi günler.","puan":1,"tepki":"Konuk nazikçe ayrılır. Düzgün bir veda, ama kat ofisine yeniden ulaşabileceğini belirten bir cümle eksik."},{"metin":"Rica ederim, geçmiş olsun. Bir şey olursa kat ofisini arayabilirsiniz; iyi günler.","ingilizce":"You're welcome, and I'm glad it's sorted. If anything comes up, you can call the housekeeping office. Have a good day.","puan":2,"tepki":"Konuk gülümseyerek teşekkür eder. Geçmiş olsun denip ulaşılabilir olunduğu söylendiği için konuk kendini güvende hisseder; sorun içten bir vedayla kapanır."}]}]},{"id":"os-d27","unite":5,"baslik":"Taşkın Konuk","rol":"Güvenlik görevlisi","sahne":"Saat 23.45, lobi barı. Bir konuk yüksek sesle konuşuyor ve ayakta zor duruyor; barmen servisi kesmiş, nöbetçi müdür de güvenliği çağırmış. Güvenlik görevlisi konuğu sakinleştirip güvenle odasına ulaştırmak istiyor.","kavramlar":["os-5-136","os-5-110","os-5-035","os-5-122"],"adimlar":[{"konuk":"Bir tane daha içki istiyorum! Neden vermiyorsunuz? Ben bu otelin konuğuyum!","ingilizce":"I want one more drink! Why won't you serve me? I'm a guest at this hotel!","secenekler":[{"metin":"Sarhoşsunuz efendim, rezil oluyorsunuz; herkes size bakıyor, lütfen hemen buradan çıkın!","puan":0,"tepki":"Konuk bağırır: “Bana rezil mi dedin?” Aşırı alkollü konuk utandırılmaz ve onunla tartışılmaz; öfke yalnızca büyür."},{"metin":"Anlıyorum efendim, bu gece size daha fazla içki servisi yapamıyoruz. Biraz oturup dinlenelim mi?","ingilizce":"I understand, sir. We can't serve you any more drinks tonight. Shall we sit down and rest for a moment?","puan":2,"tepki":"Konuk söylenerek de olsa yanındaki koltuğa oturur. Konukla tartışılmaz, konuk utandırılmaz; sakin bir ses çoğu zaman öfkeyi düşürür."},{"metin":"Efendim, kural böyle. Barmenle konuşmayın artık.","puan":1,"tepki":"Konuk söylenerek geri çekilir ama sinirli kalır. Kural doğru, ama soğuk ve emirle söylendi; konuk dinlenmedi."}]},{"konuk":"Ben sarhoş değilim! Siz kimsiniz de bana karışıyorsunuz?","ingilizce":"I'm not drunk! Who are you to tell me what to do?","secenekler":[{"metin":"Kimseye karışmıyorum ama sesinizi kesmezseniz polisi çağırırım.","puan":0,"tepki":"Konuk bağırarak ayağa kalkar. Tehdit ve savunmaya geçmek durumu büyütür; soğukkanlılık korunmalıdır."},{"metin":"Odanıza çıkın, burası olmaz.","puan":1,"tepki":"Konuk “Gitmem!” diye direnir. Amaç doğru, ama kısa ve emreder gibi söylendi; güvenle odaya ulaştırmak için konuğun iş birliği gerekir."},{"metin":"Ben güvenlik görevlisiyim efendim, size yardım için buradayım. Odanıza güvenle çıkmanız için yanınızda yürüyeceğim.","ingilizce":"I'm a member of our security team, sir, here to help you. I'll walk with you so you can reach your room safely.","puan":2,"tepki":"Konuk biraz yumuşar: “Peki, peki.” Güvenlik görevlisinin amacı konuğun sağlığını korumak ve odasına güvenle ulaşmasını sağlamaktır."}]},{"konuk":"Başım çok dönüyor... Ayakta duramıyorum, sanırım bayılacağım.","ingilizce":"I feel very dizzy... I can't stand, I think I'm going to faint.","secenekler":[{"metin":"Hemen oturun, yanınızdayım. Sağlık ekibimizi çağırıyorum.","puan":1,"tepki":"Konuk oturur, sağlık görevlisi gelir. Doğru yönde; ama bayılacak gibi olan konukta 112 de aynı anda aranır ve nöbetçi müdüre haber verilir."},{"metin":"Sizi hemen odanıza götürüp kapıyı kapatalım, orada uyursunuz; sabaha kadar geçer, kimseyi de rahatsız etmezsiniz.","puan":0,"tepki":"Konuk odada tek başına kalır ve kimse onu kontrol etmez. Bayılacak gibi olan konuk yalnız bırakılmaz."},{"metin":"Hemen oturun, yanınızdayım. 112’yi ve sağlık ekibimizi arıyorum, nöbetçi müdüre de haber veriyorum.","ingilizce":"Please sit down right now, I'm with you. I'm calling 112 and our medical team, and informing the duty manager.","puan":2,"tepki":"Konuk koltuğa çöker; ekip hızla yanına gelir ve sağlık görevlisi onu yatırarak kontrol eder. Bayılacak gibi olan konuk için beklenmez; 112 aranır, yönetime haber verilir."}]},{"konuk":"(Konuğun eşi koşarak gelir.) Ne oluyor? Eşimi neden yatırdınız? Hepinizi şikâyet edeceğim!","ingilizce":"(The guest's wife hurries over.) What's going on? Why have you laid my husband down? I'll complain about all of you!","secenekler":[{"metin":"Eşiniz çok içti, biz sadece görevimizi yaptık; lütfen bekleyin, nöbetçi müdür gelecek.","puan":1,"tepki":"Konuğun eşi daha da öfkelenir. Suçlayıcı konuşmak durumu çözmez; önce endişesi görülmeli."},{"metin":"Şikâyet edin, ben görevimi yapıyorum; sesinizi yükseltmeyin, burada herkes çalışıyor, bağırarak bir yere varamazsınız.","puan":0,"tepki":"Konuğun eşi bağırmaya devam eder. Konuk yakınıyla tartışılmaz; sakin kalmak ve açıklamak gerekir."},{"metin":"Endişenizi anlıyorum. Eşiniz iyi değil, sağlık ekibimiz ilgileniyor; sorularınızı nöbetçi müdürümüz yanıtlayacak.","ingilizce":"I understand you're worried. Your husband isn't well, so our medical team is looking after him, and our duty manager will answer your questions.","puan":2,"tepki":"Eşi derin bir nefes alır: “Peki, teşekkür ederim.” Sakin kalmak, endişeyi görmek ve ayrıntıyı amire aktarmak gerginliği düşürür."}]},{"konuk":"Ambulans eşimi aldı. Bu olay yüzünden başımıza bir şey gelecek mi?","ingilizce":"The ambulance has taken my husband. Will we get into trouble because of this?","secenekler":[{"metin":"Tutanakta eşinizin rezalet çıkardığını yazdık; hukuki sorun yaşayabilirsiniz, bir avukata danışmanız iyi olur, olay çok ciddi görünüyor.","puan":0,"tepki":"Eşi korkuyla sessizleşir. Tutanak yorum katılmadan yazılır ve tehdit aracı olarak kullanılmaz."},{"metin":"Sizi suçlayan yok; önemli olan eşinizin sağlığı. Olay yorum katılmadan tutanağa yazıldı, ayrıntıları nöbetçi müdürümüz anlatacak.","ingilizce":"Nobody is blaming you; what matters is your husband's health. The incident has been recorded without comment, and our duty manager will explain the details.","puan":2,"tepki":"Eşi teşekkür eder: “İçim rahatladı.” Tutanak olayı yorum katmadan kaydeder; olay raporu konuğu da çalışanı da haksız suçlamadan korur."},{"metin":"Bilmem, onu müdür söyler; ben güvenlikten sorumluyum, tutanak konusunda bir şey diyemem.","puan":1,"tepki":"Eşi ne olacağını öğrenemeden gider. Cevabı bilmemek normal, ama konuğa nazik ve sakinleştirici bir yönlendirme yapılmadı."}]},{"konuk":"Tamam. Ben de hastaneye gidiyorum; ilgilendiğiniz için teşekkürler.","ingilizce":"All right. I'm going to the hospital now; thank you for your help.","secenekler":[{"metin":"Peki, gidebilirsiniz; ama bu olay yüzünden otelden bir şey beklemeyin.","puan":0,"tepki":"Eşi şaşırır ve öfkelenir. Sağlık krizi sırasında konuğun yanında olunur; sitemle ya da tehditle uğurlamak güveni yıkar."},{"metin":"Geçmiş olsun, iyi günler.","puan":1,"tepki":"Eşi başını sallayıp çıkar. Nazik ama kuru bir veda; endişeli konuğa somut bir yardım teklif edilmedi."},{"metin":"Çok geçmiş olsun, eşinize acil şifalar dileriz. İsterseniz sizin için bir taksi çağırayım.","ingilizce":"I wish your husband a speedy recovery. If you like, I'll call a taxi for you.","puan":2,"tepki":"Eşi gözleri dolu teşekkür eder. Endişeli konuğa veda ederken yardım teklif etmek, ona yalnız olmadığını hissettirir."}]}]}]}]`);export{t};